local function supervision_attention(report)
  if type(report) ~= 'table' or report.operation ~= 'semantic_supervise'
      or type(report.data) ~= 'table' or type(report.data.results) ~= 'table' or not is_list(report.data.results) then return nil end
  local count = 0
  for _, result in ipairs(report.data.results) do
    if type(result) ~= 'table' or not vim.tbl_contains({ 'passed', 'observed', 'penalty_preview_only' }, result.status) then
      count = count + 1
    end
  end
  return count
end
local function has_assembly_changes(draft)
  local spec = type(draft) == 'table' and draft.spec or nil
  if type(spec) ~= 'table' then return false end
  for _, name in ipairs({ 'sets', 'routes', 'outputs', 'remove', 'params' }) do
    if type(spec[name]) == 'table' and next(spec[name]) ~= nil then return true end
  end
  return false
end
local function has_layer_draft(draft)
  return type(draft) == 'table' and ((type(draft.operations) == 'table' and #draft.operations > 0)
    or (type(draft.structures) == 'table' and #draft.structures > 0))
end
local function notify(message, level)
  vim.notify(locale.message(message), level)
end

local function open_aux_buffer(buf, vertical_first, keep_on_failure)
  -- A normal split sits underneath floating graph and preview windows. Keep
  -- reviews readable even if a preview appears after the report opens.
  local graph_or_preview = false
  for _, win in ipairs(vim.api.nvim_tabpage_list_wins(0)) do
    if vim.api.nvim_win_is_valid(win) then
      local existing = vim.api.nvim_win_get_buf(win)
      if vim.b[existing].model_maven_graph_window or vim.b[existing].model_maven_preview then graph_or_preview = true end
    end
  end
  if graph_or_preview then
      local boundary
      for _, candidate in ipairs(vim.api.nvim_tabpage_list_wins(0)) do
        if vim.api.nvim_win_is_valid(candidate) and vim.b[vim.api.nvim_win_get_buf(candidate)].model_maven_preview
            and vim.api.nvim_win_get_config(candidate).relative ~= '' then
          boundary = vim.api.nvim_win_get_position(candidate)[2]; break
        end
      end
      local width, col = require('model_maven.model_preview').layout(110, function() return boundary end)
      local height = math.min(32, vim.o.lines - 5)
      if width >= 20 and height >= 4 then
        local ok = pcall(vim.api.nvim_open_win, buf, true, {relative = 'editor', style = 'minimal', border = 'rounded',
          width = width, height = height, row = 1, col = col, zindex = 200})
        if ok then vim.b[buf].model_maven_aux_window = true; return true end
      end
  end
  local first = vertical_first and 'leftabove vsplit' or 'botright split'
  local second = vertical_first and 'leftabove split' or 'botright vsplit'
  local tab, original = vim.api.nvim_get_current_tabpage(), vim.api.nvim_get_current_buf()
  local old_windows = {}
  for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do old_windows[win] = true end
  local opened, err = pcall(vim.cmd, first)
  if not opened then opened, err = pcall(vim.cmd, second) end
  local split
  if opened and vim.api.nvim_tabpage_is_valid(tab) then
    local created = {}
    for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
      if not old_windows[win] then created[#created + 1] = win end
    end
    if #created == 1 and vim.api.nvim_win_get_buf(created[1]) == original then
      split = created[1]
      local placed, place_error = pcall(vim.api.nvim_win_set_buf, split, buf)
      opened = placed and vim.api.nvim_win_is_valid(split) and vim.api.nvim_win_get_buf(split) == buf
      err = place_error
      if not opened and vim.api.nvim_win_is_valid(split) and vim.api.nvim_win_get_buf(split) == original then
        pcall(vim.api.nvim_win_close, split, false)
      end
    else
      opened = false
    end
  else
    opened = false
  end
  if not opened then
    if keep_on_failure and vim.api.nvim_buf_is_valid(buf) then
      vim.bo[buf].buflisted = true
      notify(tr('Could not safely open a new window. The draft is kept in buffer ',
        '无法安全打开新窗口。草稿保留在 buffer ', '無法安全開啟新視窗。草稿保留在 buffer ')
        .. tostring(buf) .. tr('; open it with :buffer ', '；可使用 :buffer 打开 ', '；可使用 :buffer 開啟 ') .. tostring(buf), vim.log.levels.WARN)
    else
      if vim.api.nvim_buf_is_valid(buf) then pcall(vim.api.nvim_buf_delete, buf, { force = true }) end
      notify(tr('Could not safely open this view. Check window layout or enlarge the terminal.',
        '无法安全打开此页面；请检查窗口布局或放大终端。',
        '無法安全開啟此頁面；請檢查視窗配置或放大終端。'), vim.log.levels.WARN)
    end
    return false
  end
  if vim.api.nvim_win_is_valid(split) and vim.api.nvim_win_get_buf(split) == buf then
    pcall(vim.api.nvim_set_current_win, split)
  end
  return true
end
local function needs_generic_device(device)
  local value = type(device) == 'string' and vim.trim(device):lower() or ''
  return value ~= 'cpu' and value ~= 'cuda' and not value:match('^cuda:%d+$')
end
local run, preview_layer, probe_local, open_verified_implementation, edit_reported_parameter, export_failure_locations, mark_observed_port, focus_source, discover_layer_classes, preview_variant_edit, compose_layer_transaction, guided_parameter_transaction, prepare_trial, prepare_pytorch_training, preview_variant_supervision
local open_model_builder

local function request(state, args, callback, on_closed, fresh_forward, before_process)
  local opts = (fresh_forward or before_process) and vim.tbl_extend('force', {}, state.opts, {
    fresh_forward = fresh_forward or nil, before_process = before_process,
  }) or state.opts
  return transport.request(opts, args, function(...)
    if state.closed then
      if on_closed then on_closed(...) end
      if state.busy then
        notify('Model-Maven operation finished after its workspace closed; inspect project or run state before retrying.', vim.log.levels.WARN)
      end
      return
    end
    callback(...)
  end)
end

local dirty_buffers

local function dirty_buffer_snapshot(project)
  local result, names = {}, {}
  for _, name in ipairs(dirty_buffers(project)) do names[name] = true end
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) and vim.bo[buf].modified then
      local name = vim.api.nvim_buf_get_name(buf)
      if names[name] then result[buf] = { name = name, tick = vim.api.nvim_buf_get_changedtick(buf) } end
    end
  end
  return result
end

-- Some reviewed configuration commits use request() directly rather than run().
-- Keep their uncertain outcomes visible across workspace restarts as well.
local function begin_tracked_commit(state, title)
  local project = state.opts.project
  local marker, err = pending_operation.create(project, title)
  if not marker then
    notify(tr('Cannot record the pending change; nothing was started: ',
      '无法记录待核查的修改；操作尚未启动：', '無法記錄待核查的修改；操作尚未啟動：') .. tostring(err), vim.log.levels.ERROR)
    return nil
  end
  state.pending_foreground_checked, state.pending_foreground_cache = nil, nil
  return { project = project, cli = state.opts.cli, epoch = state.change_epoch or 0, marker = marker, title = title,
    dirty_buffers = dirty_buffer_snapshot(project) }
end

local function tracked_commit_current(state, tracked)
  return not state.closed and state.opts.project == tracked.project and state.opts.cli == tracked.cli
    and (state.change_epoch or 0) == tracked.epoch
    and vim.deep_equal(dirty_buffer_snapshot(tracked.project), tracked.dirty_buffers)
end

local function notify_tracked_context_changed(tracked)
  notify(tr('The change finished in its original context; inspect the original project before continuing: ',
    '修改已在原上下文结束；继续前请回到原项目核查：', '修改已在原上下文結束；繼續前請回到原專案核查：') .. tracked.project, vim.log.levels.WARN)
end

local function settle_tracked_commit(state, tracked, verified, problem)
  local uncertain = not verified and not (problem and problem.operation_started == false)
  if not uncertain then
    local cleared, err = pending_operation.clear(tracked.project, tracked.marker)
    if not cleared then
      uncertain = true
      notify(tr('Could not clear the pending marker; inspect before continuing: ',
        '无法清除待核查标记；继续前请检查：', '無法清除待核查標記；繼續前請檢查：') .. tostring(err), vim.log.levels.WARN)
    end
  end
  state.pending_foreground_checked, state.pending_foreground_cache = nil, nil
  if uncertain then
    if state.opts.project == tracked.project then
      state.pending_uncertain_operation = { title = tracked.title }
      if state.last and tracked_commit_current(state, tracked) then state.last.uncertain_outcome = true end
    else
      notify(tr('A change outcome is unknown in the original project; inspect it before retrying: ',
        '原项目中的修改结果未知；重试前请返回核查：', '原專案中的修改結果未知；重試前請返回核查：') .. tracked.project, vim.log.levels.WARN)
    end
  end
  return not uncertain
end

local function project_config(project)
  local file = project .. '/.model-maven/project.json'
  local fd = io.open(file, 'rb')
  if not fd then
    local stat, _, code = vim.uv.fs_lstat(file)
    return nil, stat and 'unreadable' or (code == 'ENOENT' and 'missing' or 'unreadable')
  end
  local raw = fd:read(1024 * 1024 + 1) or ''
  fd:close()
  if #raw > 1024 * 1024 then return nil, 'invalid' end
  local ok, data = pcall(vim.json.decode, raw)
  if not ok or type(data) ~= 'table' then return nil, 'invalid' end
  return data, 'present', vim.fn.sha256(raw)
end

local function project_config_current(state)
  if state.project_status == 'unconfigured' then
    local _, status = project_config(state.opts.project)
    return status == 'missing'
  end
  if state.project_status ~= 'configured' then return true end
  local _, status, digest = project_config(state.opts.project)
  return status == 'present' and type(state.config_file_digest) == 'string'
    and digest == state.config_file_digest
end

local function in_project(project, name)
  if name == '' then return false end
  local root = vim.fs.normalize(vim.uv.fs_realpath(project) or project):gsub('/+$', '') .. '/'
  local path = vim.fs.normalize(vim.uv.fs_realpath(name) or name)
  return vim.startswith(path, root)
end

dirty_buffers = function(project)
  local dirty = {}
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) and vim.bo[buf].modified then
      local name = vim.api.nvim_buf_get_name(buf)
      if in_project(project, name) then
        dirty[#dirty + 1] = name
      end
    end
  end
  return dirty
end

-- The backend and selected Python perform the authoritative Unicode check.
local function identifier_candidate(value)
  return type(value) == 'string' and value ~= '' and #value <= 256
    and not value:find('[%s%c%.:=]')
end

-- NAME=JSON is passed as one argv element, then split at the first '='.
-- Ordinary Python **kwargs may use non-identifier strings; '=' cannot be
-- represented by this CLI syntax and control characters obscure review.
local function parameter_name_candidate(value)
  return type(value) == 'string' and value ~= '' and #value <= 256
    and not value:find('[%c=]')
end

local function module_part_candidate(value)
  return identifier_candidate(value) and not value:find('[/\\]')
end

local function reloads_pending(state)
  local names = {}
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) and vim.b[buf].model_maven_reload_required then
      local name = vim.api.nvim_buf_get_name(buf)
      if in_project(state.opts.project, name) then names[#names + 1] = name end
    end
  end
  return names
end

-- An unmodified buffer can still show old contents after an external write.
-- Do not let a disk-based operation be mistaken for running the visible code.
local function stale_python_buffers(project, cache)
  local stale, visited = {}, {}
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) and vim.bo[buf].buftype == '' and not vim.bo[buf].modified then
      local name = vim.api.nvim_buf_get_name(buf)
      if name:match('%.pyi?$') and in_project(project, name) then
        local stat = vim.uv.fs_stat(name)
        local encoding = vim.bo[buf].fileencoding
        local format = vim.bo[buf].fileformat
        local function signature(info)
          if not info then return nil end
          return { name = name, tick = vim.api.nvim_buf_get_changedtick(buf), type = info.type,
            size = info.size, dev = info.dev, ino = info.ino, mtime = info.mtime, ctime = info.ctime,
            encoding = encoding, format = format, eol = vim.bo[buf].endofline, bom = vim.bo[buf].bomb }
        end
        local before = signature(stat)
        local cached = cache and cache[buf]
        visited[buf] = true
        if before and cached and vim.deep_equal(cached.signature, before) then
          if cached.stale then stale[#stale + 1] = name end
        else
          local file = stat and stat.type == 'file' and stat.size <= 8 * 1024 * 1024 and io.open(name, 'rb') or nil
          local mismatch = false
          if not file or (encoding ~= '' and encoding:lower() ~= 'utf-8')
              or (format ~= 'unix' and format ~= 'dos' and format ~= 'mac') then
            if file then file:close() end
            mismatch = true
          else
            local disk = file:read(8 * 1024 * 1024 + 1) or ''
            file:close()
            local separator = format == 'dos' and '\r\n' or (format == 'mac' and '\r' or '\n')
            local visible = table.concat(vim.api.nvim_buf_get_lines(buf, 0, -1, false), separator)
            if vim.bo[buf].endofline then visible = visible .. separator end
            if vim.bo[buf].bomb then visible = '\239\187\191' .. visible end
            mismatch = #disk > 8 * 1024 * 1024 or disk ~= visible
          end
          local after = signature(vim.uv.fs_stat(name))
          if not before or not vim.deep_equal(before, after) then mismatch = true end
          if mismatch then stale[#stale + 1] = name end
          if cache then
            cache[buf] = before and before.mtime and before.ctime and vim.deep_equal(before, after)
              and { signature = before, stale = mismatch } or nil
          end
        end
      end
    end
  end
  if cache then for buf in pairs(cache) do if not visited[buf] then cache[buf] = nil end end end
  return stale
end

local function mark_source_buffers(state, paths)
  local changed = {}
  for _, path in ipairs(paths) do
    if type(path) == 'string' and path ~= '' then
      local absolute = path:sub(1, 1) == '/' or path:match('^%a:[/\\]')
      local full = absolute and path or (state.opts.project .. '/' .. path)
      changed[vim.fs.normalize(vim.uv.fs_realpath(full) or full)] = true
    end
  end
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    local name = vim.api.nvim_buf_get_name(buf)
    if vim.api.nvim_buf_is_loaded(buf) and name ~= '' and changed[vim.fs.normalize(vim.uv.fs_realpath(name) or name)] then
      vim.b[buf].model_maven_reload_required = true
    end
  end
end

-- Session overrides belong to the selected factory, not to its UI slot.
-- Keep drafts in memory so switching back does not discard the user's work.
local function switch_factory(state, field, value, defaults)
  local parameter_field = field == 'model' and 'model_params' or 'batch_params'
  local previous = state[field] or (defaults and defaults.previous) or (state.project_info and state.project_info[field])
  local next_factory = value or (defaults and defaults.next) or (state.project_info and state.project_info[field])
  state.factory_drafts = state.factory_drafts or { model = {}, batch = {} }
  local drafts = state.factory_drafts[field]
  local keep_draft = field == 'batch' and state.batch == nil and previous == state.preserved_batch_draft
    and drafts[previous] ~= nil and next(state.batch_params or {}) == nil and state.batch_binding == nil
  if type(previous) == 'string' and previous ~= '' and not keep_draft then
    drafts[previous] = { params = vim.deepcopy(state[parameter_field] or {}),
      binding = field == 'batch' and state.batch_binding or nil }
  end
  if field == 'batch' then state.preserved_batch_draft = nil end
  local saved = type(next_factory) == 'string' and drafts[next_factory] or nil
  state[field] = value
  state[parameter_field] = saved and vim.deepcopy(saved.params) or {}
  if field == 'batch' then state.batch_binding = saved and saved.binding or nil end
end

local function render(state)
  if not vim.api.nvim_buf_is_valid(state.panel) then return end
  local auth_context = {
    project = state.opts.project, config_revision = state.project_info and state.project_info.config_revision,
    epoch = state.change_epoch or 0, model = state.model, batch = state.batch, binding = state.batch_binding,
    python = state.opts.python, cli = state.opts.cli, working_directory = state.opts.working_directory,
    import_roots = state.opts.project_import_roots, runtime_paths = state.opts.runtime_paths_override,
    model_params = state.model_params, batch_params = state.batch_params,
    probe_seed = state.probe_seed, training_seed = state.training_seed, device = state.probe_device,
  }
  if state.authorization_context and not vim.deep_equal(state.authorization_context, auth_context) then
    confirmation.revoke()
  end
  state.authorization_context = vim.deepcopy(auth_context)
  local config = state.project_info
  local project_status = state.project_status or 'checking'
  local status_text = ({
    checking = tr('checking', '检查中', '檢查中'),
    configured = tr('configured', '已配置', '已設定'),
    unconfigured = tr('not configured', '尚未配置', '尚未設定'),
    unknown = tr('unknown', '未知', '未知'),
  })[project_status] or project_status
  local current_report = state.last and state.last.report
  local current_forward = current_report and current_report.operation == 'probe'
    and current_report.status == 'success' and type(current_report.data) == 'table'
    and type(current_report.data.calls) == 'table' and is_list(current_report.data.calls)
    and current_report.data.forward_execution == 'executed' and not state.last.context_changed
  local pending_foreground, pending_foreground_error
  if not state.busy then
    local now = vim.uv.hrtime()
    if not state.pending_foreground_checked or now - state.pending_foreground_checked > 1000000000 then
      state.pending_foreground_cache, state.pending_foreground_error = pending_operation.read(state.opts.project)
      state.pending_foreground_checked = now
    end
    pending_foreground = state.pending_foreground_cache
    pending_foreground_error = state.pending_foreground_error
  end
  local next_step, shortcuts
  if project_status == 'checking' then
    next_step = tr('Checking the project…', '正在检查项目…', '正在檢查專案…')
    shortcuts = tr('[k] Refresh status', '[k] 刷新状态', '[k] 重新整理狀態')
  elseif project_status == 'unknown' then
    next_step = tr('Check why the project is unavailable.', '先查看项目状态为何不可用。', '先查看專案狀態為何無法使用。')
    shortcuts = tr('[k] Check project   [E] Environment / CLI   [c] Change project',
      '[k] 检查项目   [E] 环境 / CLI   [c] 切换项目', '[k] 檢查專案   [E] 環境 / CLI   [c] 切換專案')
  elseif pending_foreground_error then
    next_step = tr('Cannot read the pending-operation marker. Inspect it and prior effects before continuing.',
      '无法读取待核查操作标记。继续前请检查标记及先前操作的影响。',
      '無法讀取待核查操作標記。繼續前請檢查標記及先前操作的影響。')
    shortcuts = tr('[p] Marker details   [R] Runs', '[p] 标记详情   [R] 运行记录', '[p] 標記詳情   [R] 執行紀錄')
  elseif pending_foreground or state.pending_uncertain_operation then
    next_step = tr('An earlier operation is unconfirmed. Inspect its effects before continuing.',
      '先前操作尚未确认，请检查其影响后再继续。', '先前操作尚未確認，請檢查其影響後再繼續。')
    shortcuts = tr('[r] Last report   [R] Runs   [p] Review pending operation',
      '[r] 最近报告   [R] 运行记录   [p] 核查待确认操作', '[r] 最近報告   [R] 執行紀錄   [p] 核查待確認操作')
  elseif state.last and (not state.last.context_changed
      or (state.last.isolated_variant and not state.last.observed_context_changed))
      and (state.last.transport_error or (state.last.report and state.last.report.status ~= 'success')) then
    next_step = tr('Review the last result and resolve its diagnostic.', '查看最近结果并处理诊断。', '查看最近結果並處理診斷。')
    shortcuts = tr('[r] Last report   [E] Environment / CLI   [o] Source   [k] Check',
      '[r] 最近报告   [E] 环境 / CLI   [o] 源码   [k] 检查',
      '[r] 最近報告   [E] 環境 / CLI   [o] 原始碼   [k] 檢查')
  elseif state.last and not state.last.context_changed and current_report
      and current_report.operation == 'semantic_supervise' and current_report.status == 'success'
      and type(current_report.data) == 'table' and current_report.data.committed == true
      and type(current_report.data.imported) == 'number' and current_report.data.imported > 0 then
    next_step = tr('Supervision imported. Choose a mark, run forward, and rebind its port.',
      '监督声明已导入；选择标记、运行前向并重新绑定端口。', '監督宣告已匯入；選擇標記、執行前向並重新繫結連接埠。')
    shortcuts = tr('[M] Rebind a mark   [r] Import report', '[M] 重新绑定标记   [r] 导入报告', '[M] 重新繫結標記   [r] 匯入報告')
  elseif current_report and current_report.operation == 'train'
      and current_report.status == 'success' and type(current_report.data) == 'table'
      and current_report.data.detached == true and state.last and not state.last.observed_context_changed then
    next_step = tr('Training was started. Open the run to check progress and its final status.',
      '训练已启动；打开运行记录查看进度和最终状态。', '訓練已啟動；開啟執行紀錄查看進度和最終狀態。')
    shortcuts = tr('[R] Runs   [r] Start receipt   [o] Source', '[R] 运行记录   [r] 启动回执   [o] 源码', '[R] 執行紀錄   [r] 啟動回執   [o] 原始碼')
  elseif state.last and state.last.isolated_variant and not state.last.observed_context_changed
