    tr('Python: ', 'Python：', 'Python：')
      .. (state.opts.python and tr('session choice', '会话选择', '工作階段選擇')
        or (config and type(config.runtime_python) == 'string' and tr('project choice', '项目选择', '專案選擇'))
        or tr('automatic', '自动选择', '自動選擇')) .. ' · [e]',
  }
  local panel_width = state.panel_win and vim.api.nvim_win_is_valid(state.panel_win)
    and vim.api.nvim_win_get_width(state.panel_win) or vim.o.columns
  if panel_width < 48 then
    lines[7] = tr('[r] Report  [f] Find  [z] Code', '[r] 报告  [f] 找操作  [z] 代码', '[r] 報告  [f] 找操作  [z] 程式碼')
    table.insert(lines, 8, tr('[x] All  [?] Help  [q] Close', '[x] 全部  [?] 帮助  [q] 关闭', '[x] 全部  [?] 說明  [q] 關閉'))
    local wininfo = state.panel_win and vim.fn.getwininfo(state.panel_win)[1]
    local text_width = math.max(1, panel_width - ((wininfo and wininfo.textoff) or 0))
    local rows, row = {}, ''
    for _, item in ipairs(vim.split(shortcuts, '%s%s+')) do
      local next_row = row == '' and item or (row .. '  ' .. item)
      if row ~= '' and vim.fn.strdisplaywidth(next_row) > text_width then
        rows[#rows + 1], row = row, item
      else
        row = next_row
      end
    end
    if row ~= '' then rows[#rows + 1] = row end
    if #rows > 0 then
      lines[5] = rows[1]
      for index = #rows, 2, -1 do table.insert(lines, 6, rows[index]) end
    end
  end
  table.insert(lines, 4, tr('[8] Model preview', '[8] 模型预览', '[8] 模型預覽'))
  if state.canvas_snapshot and not state.canvas_snapshot.cleaned then
    table.insert(lines, 7, state.canvas_snapshot.project == state.opts.project
      and tr('Captured input ready · [2] replay  [3] discard', '已捕获输入 · [2] 重放  [3] 删除', '已擷取輸入 · [2] 重播  [3] 刪除')
      or tr('Captured input belongs to another project · [3] discard', '输入快照属于其他项目 · [3] 删除', '輸入快照屬於其他專案 · [3] 刪除'))
  end
  if state.recipe_supervision then
    table.insert(lines, 7, tr('Referenced supervision · [5] review and import',
      '声明引用监督 · [5] 审核并导入', '宣告參照監督 · [5] 檢視並匯入'))
  end
  if state.recipe_input_status == 'different' then
    table.insert(lines, 7, tr('[9] Project input differs from declaration · review sync',
      '[9] 项目输入与声明不一致 · 审核同步', '[9] 專案輸入與宣告不一致 · 檢視同步'))
  elseif state.recipe_input_status == 'unknown' then
    table.insert(lines, 7, tr('Project input and declaration could not be compared',
      '无法核对项目输入与声明', '無法核對專案輸入與宣告'))
  end
  if state.assembly_draft then
    table.insert(lines, 7, state.assembly_draft.project == state.opts.project
      and tr('Assembly draft in this session · [A] to review', '本会话有装配草稿 · 按 [A] 查看', '本工作階段有裝配草稿 · 按 [A] 檢視')
      or tr('Assembly draft belongs to another project · [A] for options', '装配草稿属于其他项目 · 按 [A] 查看选项', '裝配草稿屬於其他專案 · 按 [A] 檢視選項'))
  end
  if has_layer_draft(state.layer_draft) then
    local draft = state.layer_draft
    local draft_status = ({
      applied = tr('applied; review before reuse', '已应用；复用前请核对', '已套用；重用前請核對'),
      modified_after_applied = tr('modified since application', '应用后已修改', '套用後已修改'),
      outcome_unknown = tr('save outcome unknown', '保存结果未知', '儲存結果未知'),
      preview_ready = tr('previewed', '已预览', '已預覽'),
    })[draft.status] or tr('draft', '草稿', '草稿')
    lines[#lines + 1] = (draft.project == state.opts.project
      and tr('Layer edit', 'Layer 编辑', 'Layer 編輯')
      or tr('Layer edit from another project', '其他项目的 Layer 编辑', '其他專案的 Layer 編輯'))
      .. ' · ' .. draft_status .. ' · [W]'
  end
  if state.auto_opened_source then
    lines[#lines + 1] = tr('Source candidate (not verified): ', '源码候选（未验证）：', '原始碼候選（未驗證）：') .. state.auto_opened_source
  end
  local unresolved = reloads_pending(state)
  if #unresolved > 0 then
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Source changed on disk. Reload or reconcile open buffers before continuing:',
      '磁盘源码已变化，请重新载入或处理已打开的 buffer：', '磁碟原始碼已變更，請重新載入或處理已開啟的 buffer：')
    vim.list_extend(lines, unresolved)
    lines[#lines + 1] = tr('Use :edit to reload an unmodified buffer; inspect edits before saving.',
      '未修改的 buffer 可用 :edit 重新载入；保存前请检查已有修改。',
      '未修改的 buffer 可用 :edit 重新載入；儲存前請檢查既有修改。')
  end
  if state.expanded then vim.list_extend(lines, {
    '',
    tr('Project and context', '项目与上下文', '專案與上下文'),
    tr('Project status: ', '项目状态：', '專案狀態：') .. status_text,
    tr('Model: ', '模型：', '模型：') .. (state.model or (config and type(config.model) == 'string' and config.model) or tr('not configured', '未配置', '未設定')),
    tr('Model factory source: ', '模型工厂来源：', '模型工廠來源：')
      .. (state.model and tr('session selection', '会话选择', '工作階段選擇')
        or (config and type(config.model) == 'string' and tr('project configuration', '项目配置', '專案設定')
          or tr('unknown / not selected', '未知 / 未选择', '未知 / 未選擇'))),
    tr('Input: ', '输入：', '輸入：') .. (state.batch or (config and type(config.batch) == 'string' and config.batch) or tr('not configured', '未配置', '未設定')),
    tr('Input factory source: ', '输入工厂来源：', '輸入工廠來源：')
      .. (state.batch and tr('session selection', '会话选择', '工作階段選擇')
        or (config and type(config.batch) == 'string' and tr('project configuration', '项目配置', '專案設定')
          or tr('unknown / not selected', '未知 / 未选择', '未知 / 未選擇'))),
    tr('Input binding: ', '输入绑定：', '輸入繫結：')
      .. (state.batch_binding and (state.batch_binding .. tr(' (session)', '（会话选择）', '（工作階段選擇）'))
        or (state.batch and tr('automatic (session input)', '自动（会话输入）', '自動（工作階段輸入）'))
        or (config and type(config.batch) == 'string' and (((type(config.batch_binding) == 'string' and config.batch_binding) or tr('automatic', '自动', '自動'))
          .. tr(' (project default)', '（项目默认）', '（專案預設）')))
        or tr('no input selected', '未选择输入', '未選擇輸入')),
    tr('Input binding source: ', '输入绑定来源：', '輸入繫結來源：')
      .. (state.batch_binding and tr('session selection', '会话选择', '工作階段選擇')
        or (state.batch and tr('automatic for session input', '会话输入自动选择', '工作階段輸入自動選擇'))
        or (config and type(config.batch_binding) == 'string' and tr('project configuration', '项目配置', '專案設定')
          or tr('automatic or unknown', '自动或未知', '自動或未知'))),
    tr('Project: ', '项目：', '專案：') .. state.opts.project,
    tr('CLI: ', 'CLI：', 'CLI：') .. tostring(state.opts.cli or '?')
      .. (state.opts.cli_unresolved and tr(' (not found)', '（未找到）', '（找不到）') or ''),
    tr('Execution host: ', '执行主机：', '執行主機：') .. state.host,
    tr('Python: ', 'Python：', 'Python：') .. (state.opts.python and (state.opts.python .. tr(' (session choice)', '（本会话选择）', '（本工作階段選擇）')) or (config and type(config.runtime_python) == 'string' and (config.runtime_python .. tr(' (project choice)', '（项目选择）', '（專案選擇）'))) or tr('not explicitly selected; CLI may discover one', '未明确选择；CLI 可能自动发现', '未明確選擇；CLI 可能自動探索')),
    tr('Working directory: ', '运行目录：', '執行目錄：') .. (state.opts.working_directory or tr('project default', '项目默认', '專案預設')),
    tr('Project import roots: ', '项目模块搜索目录：', '專案模組搜尋目錄：') .. (state.opts.project_import_roots and table.concat(state.opts.project_import_roots, ', ') or tr('project default', '项目默认', '專案預設')),
    tr('Factory parameter overrides: ', '工厂参数覆盖：', '工廠參數覆蓋：') .. tostring(vim.tbl_count(state.model_params or {})) .. ' / ' .. tostring(vim.tbl_count(state.batch_params or {})),
    '',
    tr('[U] Set the current goal', '[U] 设置当前目标', '[U] 設定目前目標'),
    tr('[n] Create a custom model', '[n] 创建自定义模型', '[n] 建立自訂模型'),
    tr('[a] Set up an existing model', '[a] 接入已有模型', '[a] 接入既有模型'),
    tr('[F] Find possible project entrypoints', '[F] 查找项目入口候选', '[F] 尋找專案入口候選'),
    tr('[N] Write an adapter or user loop', '[N] 编写适配器或用户循环', '[N] 編寫配接器或使用者迴圈'),
    tr('[o] Open Python file', '[o] 打开 Python 文件', '[o] 開啟 Python 檔案'),
    tr('[m] Choose model factory', '[m] 选择模型工厂', '[m] 選擇模型工廠'),
    tr('[Q] Save project model', '[Q] 保存项目默认模型', '[Q] 儲存專案預設模型'),
    tr('[b] Choose input factory', '[b] 选择输入工厂', '[b] 選擇輸入工廠'),
    tr('[S] Save project input', '[S] 保存项目默认输入', '[S] 儲存專案預設輸入'),
    tr('[j] Preview a batch summary', '[j] 预览批次摘要', '[j] 預覽批次摘要'),
    tr('[X] Open or run a model port contract', '[X] 打开或运行模型端口契约', '[X] 開啟或執行模型連接埠契約'),
    tr('[J] Preview a dataset summary', '[J] 预览数据集摘要', '[J] 預覽資料集摘要'),
    tr('[Y] Create or configure CSV input', '[Y] 创建或配置 CSV 输入', '[Y] 建立或設定 CSV 輸入'),
    tr('[P] Set model / input parameters', '[P] 设置模型 / 输入参数', '[P] 設定模型 / 輸入參數'),
    tr('[e] Choose Python environment', '[e] 选择 Python 环境', '[e] 選擇 Python 環境'),
    tr('[K] Configure session runtime paths', '[K] 设置本会话运行时路径', '[K] 設定本工作階段執行路徑'),
    tr('[E] Inspect environment and libraries', '[E] 检查环境和库', '[E] 檢查環境與程式庫'),
    '',
    tr('Understand and edit', '理解与修改', '理解與修改'),
    tr('[i] Inspect model (executes project code)', '[i] 检查模型（执行项目代码）', '[i] 檢查模型（執行專案程式碼）'),
    tr('[p] Run a forward pass', '[p] 执行前向', '[p] 執行前向'),
    tr('[1] Capture input and run forward', '[1] 捕获输入并运行前向', '[1] 擷取輸入並執行前向'),
    tr('[2] Replay captured input', '[2] 重放已捕获输入', '[2] 重播已擷取輸入'),
    tr('[3] Discard captured input', '[3] 删除输入快照', '[3] 刪除輸入快照'),
    tr('[h] Reopen last forward observation', '[h] 重新查看上次前向观察', '[h] 重新查看上次前向觀察'),
    tr('[V] Recheck after a source change', '[V] 源码修改后独立重验', '[V] 原始碼修改後獨立重驗'),
    tr('[L] Replay an observed layer', '[L] 重放已观察的层', '[L] 重播已觀察的層'),
    tr('[O] Compare forward observations', '[O] 比较前向观察', '[O] 比較前向觀察'),
    tr('[Z] Browse saved model variants', '[Z] 查看已保存的模型变体', '[Z] 查看已儲存的模型變體'),
    tr('[l] Browse layers (executes project code)', '[l] 浏览层（执行项目代码）', '[l] 瀏覽層（執行專案程式碼）'),
    tr('[v] Browse observed modules', '[v] 浏览已报告模块', '[v] 瀏覽已報告模組'),
    tr('[G] Browse observed tensor graph / links', '[G] 查看已观察的张量图 / 连接', '[G] 查看已觀察的張量圖 / 連結'),
    tr('[g] Open observed implementation', '[g] 打开已观察实现', '[g] 開啟已觀察實作'),
    tr('[w] Preview a layer change', '[w] 预览 Layer 修改', '[w] 預覽 Layer 修改'),
    tr('[W] Compose a batch of layer changes', '[W] 编写批量 Layer 修改', '[W] 編寫批次 Layer 修改'),
    tr('[A] Assemble components and routes', '[A] 装配组件与输入接线', '[A] 裝配元件與輸入接線'),
    '',
    tr('Supervision and training', '监督与训练', '監督與訓練'),
    tr('[t] Mark an observed input or output', '[t] 标记已观察的输入或输出', '[t] 標記已觀察的輸入或輸出'),
    tr('[M] Browse semantic marks', '[M] 浏览语义标记', '[M] 瀏覽語義標記'),
    tr('[4] Export supervision', '[4] 导出监督声明', '[4] 匯出監督宣告'),
    tr('[5] Import supervision', '[5] 导入监督声明', '[5] 匯入監督宣告'),
    tr('[6] Inspect port supervision', '[6] 查看端口监督', '[6] 查看連接埠監督'),
    tr('[B] Rebind selected mark to observed port', '[B] 将所选标记重新绑定到观察端口', '[B] 將所選標記重新繫結至觀察連接埠'),
    tr('[d] Add a supervision rule', '[d] 添加监督规则', '[d] 新增監督規則'),
    tr('[D] Browse or remove supervision rules', '[D] 查看或移除监督规则', '[D] 查看或移除監督規則'),
    tr('[u] Preview supervision', '[u] 预览监督', '[u] 預覽監督'),
    tr('[y] Prepare a training trial', '[y] 准备训练试跑', '[y] 準備訓練試跑'),
    tr('[T] Prepare background training', '[T] 准备后台训练', '[T] 準備背景訓練'),
    tr('[R] Browse runs and compare results', '[R] 查看并比较运行记录', '[R] 查看並比較執行紀錄'),
    tr('[H] Resolve an unconfirmed training start', '[H] 核查未确认的训练启动', '[H] 核查未確認的訓練啟動'),
    '',
    tr('Workspace', '工作区', '工作區'),
    tr('[r] View last report', '[r] 查看最近报告', '[r] 查看最近報告'),
    tr('[k] Check project / CLI', '[k] 检查项目 / CLI', '[k] 檢查專案 / CLI'),
    tr('[I] Capability and evidence overview', '[I] 能力与证据概览', '[I] 能力與證據概覽'),
    tr('[f] Find an action', '[f] 搜索操作', '[f] 搜尋操作'),
    tr('[z] Focus source window', '[z] 聚焦源码窗口', '[z] 聚焦原始碼視窗'),
    tr('[c] Change project', '[c] 切换项目', '[c] 切換專案'),
    tr('[s] Language', '[s] 语言', '[s] 語言'),
    tr('[?] Help', '[?] 帮助', '[?] 說明'),
    tr('[q] Close workspace panel', '[q] 关闭工作区面板', '[q] 關閉工作區面板'),
    '',
    tr('Use your normal Neovim keys to edit the source buffer.', '使用 Neovim 原有键位编辑源码。', '使用 Neovim 原有按鍵編輯原始碼。'),
  }) end
  if state.expanded then
    if state.probe_seed then lines[#lines + 1] = tr('Forward / assembly / source-edit seed: ', '前向 / 装配 / 源码编辑种子：', '前向 / 裝配 / 原始碼編輯種子：') .. state.probe_seed .. ' [P]' end
    if state.training_seed then lines[#lines + 1] = tr('Training seed: ', '训练种子：', '訓練種子：') .. state.training_seed .. ' [P]' end
    if state.probe_device then lines[#lines + 1] = tr('Forward model device: ', '前向模型设备：', '前向模型裝置：') .. state.probe_device .. ' [P]' end
  end
  if state.busy then
    table.insert(lines, 2, tr('Working: ', '执行中：', '執行中：') .. state.busy)
    vim.list_extend(lines, validation_progress.progress_lines({
      state = state.cancel_requested and 'cancel_requested' or 'running',
      cancellable = state.cancellable == true,
      detail = state.cancel_requested and tr('Waiting for an acknowledged terminal result; do not retry while outcome is unknown.',
        '正在等待已确认的终态；结果未知时不要重试。', '正在等待已確認的終態；結果未知時不要重試。') or nil,
    }))
    if state.cancel_requested then
      table.insert(lines, 3, tr('Cancellation requested; waiting for the CLI and worker.', '已请求取消，正在等待 CLI 和 worker 结束。', '已要求取消，正在等待 CLI 和 worker 結束。'))
    elseif state.cancellable then
      table.insert(lines, 3, tr('[C] Request cancellation', '[C] 请求取消', '[C] 要求取消'))
    else
      table.insert(lines, 3, tr('Wait for this operation; interruption is unavailable here.', '请等待此操作；此处不能中断。', '請等待此操作；此處不能中斷。'))
    end
  end
  state.builder_buttons = {}
  local graph_available = (state.graph_canvas and state.graph_canvas.project == state.opts.project)
    or vim.uv.fs_lstat(state.opts.project .. '/model-graph.json') ~= nil
  if (project_status == 'configured' and (state.recipe_available or graph_available) or project_status == 'unconfigured')
      and not state.busy and not state.pending_foreground_cache
      and not state.pending_foreground_error and not state.pending_uncertain_operation then
    table.insert(lines, 4, graph_available and tr('  ◇  Open model canvas  [n]', '  ◇  打开模型画布  [n]', '  ◇  開啟模型畫布  [n]')
      or state.recipe_kind == 'image_classification'
      and (project_status == 'unconfigured'
        and tr('  ◇  Rebuild image project  [n]', '  ◇  重建图像项目  [n]', '  ◇  重建影像專案  [n]')
        or tr('  ◇  Open image project  [n]', '  ◇  打开图像项目  [n]', '  ◇  開啟影像專案  [n]'))
      or (state.recipe_available and tr('  ◇  Open model canvas  [n]', '  ◇  打开模型画布  [n]', '  ◇  開啟模型畫布  [n]')
      or tr('  +  Create a model  [n]', '  +  新建模型  [n]', '  +  新建模型  [n]')))
    state.builder_buttons[4] = 'n'
    if project_status == 'unconfigured' then
      table.insert(lines, 5, tr('  →  Connect existing code  [a]', '  →  接入已有代码  [a]', '  →  接入既有程式碼  [a]'))
      state.builder_buttons[5] = 'a'
    end
  end
  -- The suggested actions and navigation rows use the same action callbacks as
  -- their keyboard shortcuts. Keep each hit target bounded to its own label.
  state.panel_action_targets = {}
  for row, line in ipairs(lines) do
    if line:match('^%[') then
      local starts = {}
      for start, key, after in line:gmatch('()%[([^%]]+)%]()') do
        if state.actions and state.actions[key] then
          starts[#starts + 1] = { start = start, key = key, after = after }
        end
      end
      for index, item in ipairs(starts) do
        local finish = starts[index + 1] and starts[index + 1].start - 1 or #line
        state.panel_action_targets[#state.panel_action_targets + 1] = {
          row = row, start = item.start, finish = finish, key = item.key,
        }
      end
    end
  end
  vim.bo[state.panel].modifiable = true
  vim.api.nvim_buf_set_lines(state.panel, 0, -1, false, lines)
  vim.bo[state.panel].modifiable = false
  require('model_maven.progress_ui').update(state)
  if state.model_preview and state.model_preview_observation
      and state.model_preview.observation_epoch ~= (state.change_epoch or 0) then
    state.model_preview.observation_epoch = state.change_epoch or 0
    require('model_maven.model_preview').refresh(state)
  end
  vim.api.nvim_buf_clear_namespace(state.panel, builder_buttons, 0, -1)
  for line, key in pairs(state.builder_buttons) do
    vim.api.nvim_buf_set_extmark(state.panel, builder_buttons, line - 1, 0, {
      line_hl_group = key == 'n' and 'PmenuSel' or 'Pmenu',
    })
  end
end

local function open_initial_source(state, model)
  if state.auto_open_attempted or not state.initial_buf or not state.code_win
      or not vim.api.nvim_win_is_valid(state.code_win) or not vim.api.nvim_buf_is_valid(state.initial_buf)
      or (vim.api.nvim_win_get_buf(state.code_win) ~= state.initial_buf
        and not (state.single_panel and state.code_buf == state.initial_buf
          and vim.api.nvim_win_get_buf(state.code_win) == state.panel))
      or vim.api.nvim_buf_get_name(state.initial_buf) ~= '' or vim.bo[state.initial_buf].modified
      or vim.bo[state.initial_buf].buftype ~= '' or not vim.bo[state.initial_buf].buflisted
      or vim.api.nvim_buf_line_count(state.initial_buf) ~= 1
      or vim.api.nvim_buf_get_lines(state.initial_buf, 0, 1, false)[1] ~= '' then return end
  local module = type(model) == 'string' and model:match('^([^:]+):[^:]+$') or nil
  if not module then return end
  local parts = vim.split(module, '.', { plain = true })
  for _, part in ipairs(parts) do
    if not module_part_candidate(part) then return end
  end
  state.auto_open_attempted = true
  local candidates, seen = {}, {}
  local roots = vim.deepcopy(state.opts.project_import_roots or {})
  roots[#roots + 1] = ''
  for _, root in ipairs(roots) do
    local base = state.opts.project .. '/' .. (root ~= '' and root .. '/' or '') .. table.concat(parts, '/')
    for _, path in ipairs({ base .. '.py', base .. '/__init__.py' }) do
      local real = vim.uv.fs_realpath(path)
      if real and in_project(state.opts.project, real) and vim.fn.filereadable(real) == 1 and not seen[real] then
        candidates[#candidates + 1] = real
        seen[real] = true
      end
    end
  end
  if #candidates ~= 1 then return end
  if state.single_panel and vim.api.nvim_win_get_buf(state.code_win) == state.panel then
    -- Load the unique candidate without replacing the task panel. A later z
    -- focuses the same native buffer; no user buffer is overwritten.
    local ok, target = pcall(vim.fn.bufadd, candidates[1])
    if not ok or type(target) ~= 'number' or target <= 0 then return end
    state.loading_source_candidate = true
    local loaded = pcall(vim.fn.bufload, target)
    state.loading_source_candidate = false
    if not loaded or state.closed or not vim.api.nvim_buf_is_valid(target)
        or not vim.api.nvim_win_is_valid(state.code_win) or state.code_buf ~= state.initial_buf
        or vim.api.nvim_win_get_buf(state.code_win) ~= state.panel
        or vim.bo[target].buftype ~= '' then return end
    local actual = vim.api.nvim_buf_get_name(target)
    if actual == '' or vim.fs.normalize(vim.uv.fs_realpath(actual) or actual) ~= vim.fs.normalize(candidates[1]) then return end
    state.code_buf, state.code_view = target, nil
    state.auto_opened_source, state.auto_opened_model = candidates[1], model
    state.previous_source_candidate = vim.fs.normalize(candidates[1])
    return
  end
  -- :edit can reuse the initial unnamed buffer. It was already registered
  -- as loaded, but the first read of the newly named file is not a reload.
  local initially_read = state.read_buffers and state.read_buffers[state.initial_buf]
  if state.read_buffers then state.read_buffers[state.initial_buf] = nil end
  local ok = pcall(vim.api.nvim_win_call, state.code_win, function()
    vim.cmd.edit(vim.fn.fnameescape(candidates[1]))
  end)
  if not ok and state.read_buffers and not state.read_buffers[state.initial_buf] then
    state.read_buffers[state.initial_buf] = initially_read
  end
  if ok then
    state.auto_opened_source, state.auto_opened_model = candidates[1], model
    state.previous_source_candidate = vim.fs.normalize(candidates[1])
  end
end

local function refresh_project(state, on_refreshed)
  state.check_epoch = (state.check_epoch or 0) + 1
  local epoch = state.check_epoch
  local _, _, before_digest = project_config(state.opts.project)
  state.project_status = 'checking'
  state.project_info = nil
  state.recipe_input_status = nil
  render(state)
  request(state, { 'assembly', 'show', '--config-only' }, function(report, err, stderr)
    if state.check_epoch ~= epoch then return end
    local function invalidate_context()
      state.change_epoch = (state.change_epoch or 0) + 1
      state.journey = nil
      if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
    end
    local function mark_unknown()
      if state.known_config_revision and not state.project_context_uncertain then
        state.project_context_uncertain = true
        invalidate_context()
      end
    end
    if err then
      state.project_status, state.project_error = 'unknown', err
      mark_unknown()
    elseif report and report.operation == 'assembly_show' and report.status == 'success'
        and type(report.data) == 'table' and type(report.data.model) == 'string' then
      local saved_paths = type(report.data.runtime_paths) == 'table' and report.data.runtime_paths or nil
      local raw_config, _, after_digest = project_config(state.opts.project)
      if not before_digest or before_digest ~= after_digest then
        state.project_status = 'unknown'
        mark_unknown()
        state.project_error = tr('Project configuration changed while it was being read; check it again.',
          '读取期间项目配置发生变化，请重新检查。', '讀取期間專案設定發生變化，請重新檢查。')
        render(state); return
      end
      if raw_config and ((type(raw_config.runtime_paths) == 'table' and report.data.runtime_paths == nil)
          or (type(raw_config.runtime_python) == 'string' and report.data.runtime_python == nil)) then
        state.project_status = 'unknown'
        mark_unknown()
        state.project_error = tr('This CLI cannot report saved runtime paths; select a compatible CLI.',
          '此 CLI 无法报告已保存的运行时路径，请选择兼容的 CLI。', '此 CLI 無法回報已儲存的執行階段路徑，請選擇相容的 CLI。')
        render(state); return
      end
      local saved_directory = saved_paths and type(saved_paths.working_directory) == 'string' and saved_paths.working_directory or nil
      local saved_roots = saved_paths and type(saved_paths.project_import_roots) == 'table'
        and is_list(saved_paths.project_import_roots) and #saved_paths.project_import_roots > 0 and saved_paths.project_import_roots or nil
      local revision = type(report.data.config_revision) == 'string' and report.data.config_revision or nil
      if not revision then
        mark_unknown()
      elseif state.known_config_revision and revision ~= state.known_config_revision then
        invalidate_context()
      end
      if revision then
        state.known_config_revision = revision
        state.project_context_uncertain = false
      end
      local saved_slots = {}
      if type(report.data.slots) == 'table' and is_list(report.data.slots) then
        for _, slot in ipairs(report.data.slots) do
          if type(slot) == 'table' and identifier_candidate(slot.slot) then
            saved_slots[#saved_slots + 1] = slot.slot
          end
          if #saved_slots >= 32 then break end
        end
      end
      local next_defaults = { model = report.data.model, batch = type(report.data.batch) == 'string' and report.data.batch or nil }
      if state.known_project_defaults then
        for _, field in ipairs({ 'model', 'batch' }) do
          if state[field] == nil and state.known_project_defaults[field] ~= next_defaults[field] then
            switch_factory(state, field, nil, { previous = state.known_project_defaults[field], next = next_defaults[field] })
          end
        end
      end
      state.known_project_defaults = next_defaults
      state.project_info = { model = report.data.model, batch = next_defaults.batch,
        batch_binding = raw_config and type(raw_config.batch_binding) == 'string' and raw_config.batch_binding or nil,
        config_revision = report.data.config_revision, working_directory = saved_directory, project_import_roots = saved_roots,
        runtime_python = type(report.data.runtime_python) == 'string' and report.data.runtime_python or nil, saved_slots = saved_slots }
      state.config_file_digest = after_digest
      if not state.opts.runtime_paths_override then
        if state.opts.working_directory ~= saved_directory or not vim.deep_equal(state.opts.project_import_roots, saved_roots) then
          state.opts.working_directory, state.opts.project_import_roots = saved_directory, vim.deepcopy(saved_roots)
          state.change_epoch = (state.change_epoch or 0) + 1
          if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
          state.auto_open_attempted, state.auto_opened_source = false, nil
        end
      end
      state.project_status, state.project_error = 'configured', nil
      local active_model = state.model or report.data.model
      if state.auto_opened_model and state.auto_opened_model ~= active_model then state.auto_opened_source = nil end
      open_initial_source(state, active_model)
    elseif report and report.operation == 'assembly_show' and report.status == 'error'
        and type(report.diagnostics) == 'table' and report.diagnostics[1]
        and report.diagnostics[1].code == 'PROJECT_NOT_INITIALIZED' then
      local _, config_status = project_config(state.opts.project)
      if config_status ~= 'missing' then
        state.project_status = 'unknown'
        state.project_error = tr('Project configuration appeared or became unreadable during the check; check again.',
          '检查期间项目配置出现或变为不可读，请重新检查。', '檢查期間專案設定出現或變為無法讀取，請重新檢查。')
        mark_unknown()
      else
        state.project_status, state.project_error = 'unconfigured', nil
        if state.known_config_revision then invalidate_context() end
        state.known_config_revision, state.project_context_uncertain = nil, false
      end
    else
      state.project_status = 'unknown'
      state.project_error = { report = report, stderr = stderr }
      mark_unknown()
    end
    local saved_recipe = vim.uv.fs_lstat(state.opts.project .. '/model-maven.json')
    state.recipe_available = saved_recipe ~= nil
    local recipe = saved_recipe and require('model_maven.model_builder').load(state.opts.project) or nil
    state.recipe_kind = recipe and recipe.kind or nil
    state.recipe_supervision = recipe and recipe.supervision or nil
    state.recipe_input_status = nil
    if recipe and recipe.kind ~= 'image_classification' and state.project_status == 'configured' then
      local config, status, digest = project_config(state.opts.project)
      local matches
      if status == 'present' and digest == state.config_file_digest then
        matches = require('model_maven.model_builder').data_matches(recipe, config)
      end
      state.recipe_input_status = matches == true and 'matched' or (matches == false and 'different' or 'unknown')
    end
    render(state)
    if state.opts.open_empty_builder then
      state.opts.open_empty_builder = false
      if state.project_status == 'unconfigured' and vim.api.nvim_get_current_buf() == state.panel then
        local directory = vim.uv.fs_scandir(state.opts.project)
        if state.recipe_available then
          open_model_builder(state)
        elseif directory and vim.uv.fs_scandir_next(directory) == nil then
          sessions.open_graph_canvas(state)
        end
      end
    end
    if on_refreshed then on_refreshed() end
  end)
end

local function bounded_summary(value, hidden_samples)
  local remaining, seen = 800, {}
  local function copy(item, depth)
    if hidden_samples ~= nil and item == hidden_samples then return '[prediction samples hidden; use P or J]' end
    if remaining <= 0 then return '[…]' end
    remaining = remaining - 1
    if type(item) == 'string' then
      if #item > 2048 then return vim.fn.strcharpart(item, 0, 512) .. ' … [truncated]' end
      return item
    end
    if type(item) ~= 'table' then return item end
    if seen[item] then return '[cycle]' end
    if depth >= 5 then return '[…]' end
    seen[item] = true
    local result, count = {}, 0
    if is_list(item) then
      for _, child in ipairs(item) do
        count = count + 1
        if count > 32 or remaining <= 0 then result[#result + 1] = '[…]'; break end
        result[#result + 1] = copy(child, depth + 1)
      end
    else
      for key, child in pairs(item) do
        count = count + 1
        if count > 32 or remaining <= 0 then result['…'] = '[truncated]'; break end
        result[key] = copy(child, depth + 1)
      end
    end
    seen[item] = nil
    return result
  end
  return copy(value, 0)
end

local function reviewable_text(value)
  if type(value) ~= 'string' or #value > 512 * 1024 then return false end
  local _, count = value:gsub('\n', '')
  return count <= 10000
end

-- Keep forward metadata readable and bounded without displaying scalar values.
local function tensor_tree_summary(tree, root)
  local lines, omitted = {}, false
  local function clean(value)
    return vim.fn.strcharpart(tostring(value), 0, 160):gsub('[\r\n%z\1-\31\127]', ' ')
  end
  local function visit(value, path, depth)
    if #lines >= 32 or depth > 6 then omitted = true; return end
    if type(value) ~= 'table' then
      local kind = value == vim.NIL and 'none' or type(value)
      lines[#lines + 1] = path .. ' · ' .. kind
      return
    end
    if value.kind == 'tensor' then
      local shape = {}
      if type(value.shape) == 'table' and is_list(value.shape) then
        for index, dimension in ipairs(value.shape) do
          if index > 16 then shape[#shape + 1] = '…'; omitted = true; break end
          shape[#shape + 1] = type(dimension) == 'number' and tostring(dimension) or '?'
        end
      else shape[1] = '?' end
      lines[#lines + 1] = path .. ' · [' .. table.concat(shape, ', ') .. '] · '
        .. clean(value.dtype or '?') .. ' · ' .. clean(value.device or '?')
    elseif value.kind == 'dict' and type(value.items) == 'table' then
      local names = vim.tbl_keys(value.items)
      table.sort(names, function(a, b) return tostring(a) < tostring(b) end)
      if #names == 0 then lines[#lines + 1] = path .. ' · {}' end
      for _, name in ipairs(names) do
        if #lines >= 32 then omitted = true; break end
        if name == '<truncated>' then omitted = true
        else visit(value.items[name], path .. '.' .. clean(name), depth + 1) end
      end
    elseif (value.kind == 'tuple' or value.kind == 'list') and type(value.items) == 'table' and is_list(value.items) then
      if #value.items == 0 then lines[#lines + 1] = path .. ' · ' .. value.kind .. ' []' end
      for index, item in ipairs(value.items) do
        if #lines >= 32 then omitted = true; break end
        visit(item, path .. '[' .. (index - 1) .. ']', depth + 1)
      end
      if type(value.truncated) == 'number' and value.truncated > 0 then omitted = true end
    else
      lines[#lines + 1] = path .. ' · ' .. clean(value.kind or 'unknown')
      if value.kind == 'truncated' then omitted = true end
    end
  end
  visit(tree, root, 0)
  return lines, omitted
end

local function show_report(state)
  if not state.last then
    notify(tr('Model-Maven: no report in this session.', 'Model-Maven：本次会话尚无报告。', 'Model-Maven：本次工作階段尚無報告。'), vim.log.levels.INFO)
    return
  end
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype = 'nofile'
  vim.bo[buf].bufhidden = 'wipe'
  vim.bo[buf].swapfile = false
  local report = state.last.report
  local displayed = state.last
  local readiness_actions = nil
  local function readiness_availability(value)
    return ({ available = tr('available', '可用', '可用'),
      conditional = tr('conditional', '有条件', '有條件'), unsupported = tr('unsupported', '不支持', '不支援'),
      unknown = tr('unknown', '未知', '未知') })[value] or tr('unknown', '未知', '未知')
  end
  local rule_failure_data = report and type(report.data) == 'table' and (
    (report.operation == 'train' or report.operation == 'training_probe') and report.data
    or (report.operation == 'runs_show' and type(report.data.report) == 'table'
      and report.data.report.data)) or nil
  local rule_failure_report = report and report.operation == 'runs_show' and type(report.data) == 'table'
    and type(report.data.report) == 'table' and report.data.report or report
  local direct_rule_failure = false
  if type(rule_failure_report) == 'table' and type(rule_failure_report.diagnostics) == 'table' then
    for _, diagnostic in ipairs(rule_failure_report.diagnostics) do
      if type(diagnostic) == 'table' and diagnostic.code == 'SUPERVISION_REQUIRE_FAILED' then
        direct_rule_failure = true; break
      end
    end
  end
  local rule_failure = type(rule_failure_data) == 'table' and (
    (rule_failure_data.cause_code == 'SUPERVISION_REQUIRE_FAILED'
      and type(rule_failure_data.cause_data) == 'table' and rule_failure_data.cause_data)
    or (direct_rule_failure and rule_failure_data)) or nil
  local rule_failure_path = type(rule_failure) == 'table' and rule_failure.module_path or nil
  if type(rule_failure_path) ~= 'string' or rule_failure_path == '' or #rule_failure_path > 1024
      or rule_failure_path:find('[%c]') then rule_failure_path = nil end
  local evaluation_data = report and report.operation == 'evaluate' and report.data
    or (report and report.operation == 'runs_show' and type(report.data) == 'table'
      and type(report.data.report) == 'table' and report.data.report.operation == 'evaluate' and report.data.report.data or nil)
  local failure_call = report and report.operation == 'probe' and report.status == 'error'
    and type(report.data) == 'table' and type(report.data.failure_location) == 'table'
    and report.data.failure_location.last_observed_module_call or nil
  local failure_paths = {}
  local failure_action_rows = {}
  local forward_action_rows = {}
  local contract_paths, contract_seen, contract_sources = {}, {}, {}
  local contract_data = report and report.operation == 'probe' and type(report.data) == 'table' and report.data or nil
  local contract_checks = contract_data and type(contract_data.contract_report) == 'table' and contract_data.contract_report.checks
  if type(contract_checks) == 'table' and is_list(contract_checks) and type(contract_data.calls) == 'table' and is_list(contract_data.calls) then
    local call_paths, call_records = {}, {}
    for index, call in ipairs(contract_data.calls) do
      if index > 2048 then break end
      if type(call) == 'table' and type(call.invocation_id) == 'string' and type(call.paths) == 'table' then
        local paths = call_paths[call.invocation_id] or {}
        for alias_index, path in ipairs(call.paths) do
          if alias_index > 128 then break end
          if type(path) == 'string' then paths[path] = true end
        end
        call_paths[call.invocation_id] = paths
        if call_records[call.invocation_id] == nil then call_records[call.invocation_id] = call
        else call_records[call.invocation_id] = false end
      end
    end
    for check_index, check in ipairs(contract_checks) do
      if check_index > 4096 then break end
      if type(check) == 'table' and (check.status == 'failed' or check.status == 'unsupported')
          and type(check.path) == 'string' and type(check.invocation_id) == 'string' and check.invocation_id ~= '' then
        local marker = '#' .. check.invocation_id .. '.'
        local position = check.path:find(marker, 1, true)
        local path = position and check.path:sub(1, position - 1) or nil
        if path and #path <= 1024 and not path:find('[%c]') and (path == 'model' or vim.startswith(path, 'model.'))
            and call_paths[check.invocation_id] and call_paths[check.invocation_id][path] then
          if not contract_seen[path] then
            contract_seen[path] = true
            contract_paths[#contract_paths + 1] = path
          end
          local call = call_records[check.invocation_id]
          local impl = call and call.implementation
          if type(impl) == 'table' and type(impl.source_file) == 'string' and impl.source_file ~= ''
              and impl.source_file:sub(1, 1) ~= '@' and type(impl.source_sha256) == 'string'
              and #impl.source_sha256 == 64 and impl.source_sha256:match('^[0-9a-f]+$') then
            local source = { path = path, source = impl.source_file, digest = impl.source_sha256, line = impl.declaration_line }
            local previous = contract_sources[path]
            if previous == nil then contract_sources[path] = source
            elseif previous ~= false and (previous.source ~= source.source or previous.digest ~= source.digest or previous.line ~= source.line) then
              contract_sources[path] = false
            end
          else
            contract_sources[path] = false
          end
        end
      end
      if #contract_paths >= 32 then break end
    end
  end
  local failure_frames = {}
  local edit_location = report and report.operation == 'edit' and report.status == 'error'
    and type(report.data) == 'table' and report.data.source_edit_location or nil
  if type(edit_location) ~= 'table' or edit_location.identity_scope ~= 'source-read-during-preview'
      or type(edit_location.source) ~= 'string' or type(edit_location.path) ~= 'string'
      or type(edit_location.digest) ~= 'string' or #edit_location.digest ~= 64
      or not edit_location.digest:match('^[0-9a-f]+$')
      or type(edit_location.line) ~= 'number' or edit_location.line < 1
      or edit_location.line ~= math.floor(edit_location.line) then edit_location = nil end
  local failure_location = report and report.operation == 'probe' and report.status == 'error'
    and type(report.data) == 'table' and report.data.failure_location or nil
  if type(failure_location) == 'table' and type(failure_location.project_stack) == 'table'
      and is_list(failure_location.project_stack) then
    for _, frame in ipairs(failure_location.project_stack) do
      if type(frame) == 'table' and type(frame.file) == 'string' and frame.file ~= ''
          and type(frame.line) == 'number' and frame.line >= 1 and frame.line == math.floor(frame.line)
          and type(frame.source_sha256) == 'string' and #frame.source_sha256 == 64
          and frame.source_sha256:match('^[0-9a-f]+$') and frame.identity_scope == 'file-read-after-error' then
        failure_frames[#failure_frames + 1] = frame
      end
      if #failure_frames >= 16 then break end
    end
  end
  if type(failure_call) == 'table' and type(failure_call.alias_paths) == 'table' and is_list(failure_call.alias_paths) then
    for _, path in ipairs(failure_call.alias_paths) do
      if type(path) == 'string' and path ~= '' then failure_paths[#failure_paths + 1] = path end
      if #failure_paths >= 32 then break end
    end
  end
  local lines = { 'Model-Maven', '',
    tr('This report is a snapshot. For a newer result, return to the workspace and open [r].',
      '此报告是打开时的快照；如有新操作，请回工作区按 [r] 查看最新结果。',
      '此報告是開啟時的快照；如有新操作，請回工作區按 [r] 查看最新結果。'), '' }
  if type(displayed.scope) == 'string' then
    lines[#lines + 1] = displayed.scope:gsub('[\r\n%z\1-\31\127]', ' ')
    lines[#lines + 1] = ''
  end
  if displayed.recheck_summary then
    lines[#lines + 1] = displayed.recheck_summary
    lines[#lines + 1] = ''
  end
  if report then
    local operation_labels = {
      preview = tr('Data preview', '数据预览', '資料預覽'),
      probe = tr('Forward observation', '前向观察', '前向觀察'),
      inspect = tr('Model inspection', '模型检查', '模型檢查'),
      graph_import_scaffold = tr('Graph import preview', '图导入预览', '圖匯入預覽'),
      edit = tr('Layer edit', 'Layer 编辑', 'Layer 編輯'),
      scaffold = type(report.data) == 'table' and report.data.committed == false
        and tr('Model creation plan', '模型创建计划', '模型建立計畫')
        or tr('Model creation', '模型创建', '模型建立'),
      training_probe = tr('Training trial', '训练试跑', '訓練試跑'),
      train = tr('Training', '训练', '訓練'),
      runs_show = tr('Run details', '运行详情', '執行詳情'),
      runs_compare = tr('Run comparison', '运行对照', '執行對照'),
      semantic_mark = tr('Semantic mark', '语义标记', '語意標記'),
      semantic_supervise = tr('Supervision', '监督', '監督'),
      generic_loop_trial = tr('User loop trial', '用户循环试跑', '使用者迴圈試跑'),
      generic_loop_train = tr('User loop run', '用户循环运行', '使用者迴圈執行'),
    }
    local status_labels = {
      success = tr('Success', '成功', '成功'),
      error = tr('Failed', '失败', '失敗'),
      cancelled = tr('Cancelled', '已取消', '已取消'),
      partial = tr('Partial', '部分完成', '部分完成'),
    }
    lines[#lines + 1] = tr('Operation: ', '操作：', '操作：') .. (operation_labels[report.operation] or tostring(report.operation or '?'))
    local status = status_labels[report.status] or tostring(report.status or '?')
    if report.operation == 'scaffold' and report.status == 'success'
        and type(report.data) == 'table' and report.data.committed == false then
      status = tr('Plan ready; files not written', '计划已生成；尚未写入文件', '計畫已產生；尚未寫入檔案')
    end
    lines[#lines + 1] = tr('Status: ', '状态：', '狀態：') .. status
    if report.operation == 'graph_import_scaffold' and report.status == 'success'
        and type(report.data) == 'table' and type(report.data.graph) == 'table' then
      local graph = report.data.graph
      local inputs, outputs = {}, {}
      for _, node in ipairs(type(graph.nodes) == 'table' and graph.nodes or {}) do
        if type(node) == 'table' and type(node.id) == 'string' then
          if node.kind == 'input' then inputs[#inputs + 1] = node.id
          elseif node.kind == 'output' then outputs[#outputs + 1] = node.output_name or node.id end
        end
      end
      local editable = report.data.representation == 'editable_recipe_layers'
      lines[#lines + 1] = editable and tr('Representation: editable layers inferred from the declaration.',
        '表示方式：从声明推导的可编辑层。', '表示方式：從宣告推導的可編輯層。')
        or tr('Representation: original model as one opaque component.',
          '表示方式：原模型作为一个不可展开组件。', '表示方式：原模型作為一個不可展開元件。')
      lines[#lines + 1] = tr('Inputs: ', '输入：', '輸入：') .. table.concat(inputs, ', ')
      lines[#lines + 1] = tr('Outputs: ', '输出：', '輸出：') .. table.concat(outputs, ', ')
      if type(graph.legacy_import) == 'table' then
        lines[#lines + 1] = tr('The graph retains an inactive copy of the original declaration; it may contain project-sensitive data.',
          '图内保留一份不生效的原声明快照，可能包含项目敏感信息。', '圖內保留一份不生效的原宣告快照，可能包含專案敏感資訊。')
      end
      if report.data.data_origin == 'project_config' then
        lines[#lines + 1] = tr('Data factory, binding and parameters were copied from the reviewed project configuration; they are unverified and may contain sensitive values.',
          '数据工厂、绑定及参数来自已核对的项目配置；尚未验证，可能包含敏感信息。', '資料工廠、繫結及參數來自已核對的專案設定；尚未驗證，可能包含敏感資訊。')
      end
      if report.data.source_kind == 'image_classification' then
        lines[#lines + 1] = tr('Classification transforms, class names and loss are not converted. Verify the data factory and model signature against the current source.',
          '分类变换、类别及损失未转换；请按当前源码核对数据工厂和模型签名。', '分類轉換、類別及損失未轉換；請依目前原始碼核對資料工廠與模型簽章。')
      end
      lines[#lines + 1] = editable and tr('Only supported declared layers are mapped. Source edits and weights are not converted or compared.',
        '仅映射受支持的声明层；源码修改和权重未转换或比较。', '僅對應受支援的宣告層；原始碼修改及權重未轉換或比較。')
        or tr('Internal layers, routes, component settings and weights are not converted. Keep the original declaration and source.',
          '内部层、路由、组件设置与权重不会转换；请保留原声明和源码。', '內部層、路由、元件設定與權重不會轉換；請保留原宣告和原始碼。')
      if editable then
        lines[#lines + 1] = tr('After reordering or removing layers, review the cast node component order.',
          '重排或移除层后，请检查类型转换节点的组件顺序。', '重排或移除層後，請檢查型別轉換節點的元件順序。')
        lines[#lines + 1] = tr('Custom fusion receives a list; a custom head must return the declared output mapping. Factories are not verified.',
          '自定义融合接收列表；自定义输出头须返回声明中的具名映射。工厂尚未验证。', '自訂融合接收清單；自訂輸出頭須回傳宣告中的具名對應。工廠尚未驗證。')
      end
      lines[#lines + 1] = tr('Training is retained if declared but needs review; supervision remains a reference and must be rebound. The model factory has not run.',
        '如有训练声明则已保留，但需要审核；监督只保留引用，需重绑定。模型工厂尚未运行。', '如有訓練宣告則已保留，但需要檢視；監督只保留參照，須重新繫結。模型工廠尚未執行。')
      lines[#lines + 1] = tr('Review factory parameters and actual named inputs and outputs before running.',
        '运行前请核对工厂参数及实际具名输入输出。', '執行前請核對工廠參數及實際具名輸入輸出。')
    end
    if report.operation == 'probe' and report.status == 'success' and type(report.data) == 'table'
        and report.data.forward_execution == 'executed' and not displayed.context_changed
        and not (type(report.data.evidence_cache) == 'table' and report.data.evidence_cache.status == 'reused')
        and not displayed.isolated_variant and not displayed.historical_observation then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Observed output', '本次观察到的输出', '本次觀察到的輸出')
      if type(report.data.outputs) == 'table' then
        local outputs, omitted = tensor_tree_summary(report.data.outputs, 'output')
        for index, value in ipairs(outputs) do
          if index > 4 then omitted = true; break end
          lines[#lines + 1] = '  ' .. value
        end
        if omitted then
          lines[#lines + 1] = tr('  More outputs are in the report below.', '  更多输出见下方报告。', '  更多輸出見下方報告。')
        end
      end
      lines[#lines + 1] = tr('  → Explore observed modules [v]', '  → 查看观察到的模块 [v]', '  → 查看觀察到的模組 [v]')
      forward_action_rows[#lines] = 'v'
      lines[#lines + 1] = tr('  ◇ Mark a port for supervision [t]', '  ◇ 标记端口并添加监督 [t]', '  ◇ 標記連接埠並新增監督 [t]')
      forward_action_rows[#lines] = 't'
      lines[#lines + 1] = tr('  → Inspect a port and its rules [6]', '  → 查看端口及其规则 [6]', '  → 查看連接埠及其規則 [6]')
      forward_action_rows[#lines] = '6'
      if state.selected_mark_record then
        lines[#lines + 1] = tr('  ↻ Rebind selected mark to an observed port [B]',
          '  ↻ 将所选标记重新绑定到观察端口 [B]', '  ↻ 將所選標記重新繫結至觀察連接埠 [B]')
        forward_action_rows[#lines] = 'B'
      end
      lines[#lines + 1] = tr('  ▶ Prepare a training trial [y]', '  ▶ 准备训练试跑 [y]', '  ▶ 準備訓練試跑 [y]')
      forward_action_rows[#lines] = 'y'
    end
    if report.status == 'success' and not displayed.context_changed and not displayed.isolated_variant
        and type(report.data) == 'table' then
      if report.operation == 'config_set_batch' and report.data.committed == true then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  → Preview saved input [j]', '  → 预览已保存的输入 [j]', '  → 預覽已儲存的輸入 [j]')
        forward_action_rows[#lines] = 'j'
        lines[#lines + 1] = tr('  ▶ Run forward with this input [p]', '  ▶ 使用此输入运行前向 [p]', '  ▶ 使用此輸入執行前向 [p]')
        forward_action_rows[#lines] = 'p'
        if state.recipe_available and state.recipe_kind ~= 'image_classification' then
          lines[#lines + 1] = tr('  → Save project input in declaration [9]', '  → 将项目输入保存到声明 [9]', '  → 將專案輸入儲存到宣告 [9]')
          forward_action_rows[#lines] = '9'
          lines[#lines + 1] = tr('  → Open canvas and load input into declaration [n]', '  → 打开画布，将输入载入声明 [n]', '  → 開啟畫布，將輸入載入宣告 [n]')
          forward_action_rows[#lines] = 'n'
        end
      elseif report.operation == 'preview' and report.data.published ~= false then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  ▶ Run forward with selected input [p]', '  ▶ 使用当前选择的输入前向 [p]', '  ▶ 使用目前選擇的輸入前向 [p]')
        forward_action_rows[#lines] = 'p'
      elseif report.operation == 'semantic_mark' and type(report.data.mark) == 'table'
          and type(report.data.mark.id) == 'string' then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  → Add a rule to this port [d]', '  → 为此端口添加规则 [d]', '  → 為此連接埠新增規則 [d]')
        forward_action_rows[#lines] = 'd'
      elseif report.operation == 'semantic_supervise' and report.data.committed == true and type(report.data.imported) == 'number' then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  ↻ Choose an imported mark to rebind [M]', '  ↻ 选择导入的标记并重新绑定 [M]', '  ↻ 選擇匯入的標記並重新繫結 [M]')
        forward_action_rows[#lines] = 'M'
      elseif report.operation == 'semantic_supervise' and type(report.data.rule) == 'table' then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  → Preview supervision on the current input [u]', '  → 用当前输入预览监督 [u]', '  → 用目前輸入預覽監督 [u]')
        forward_action_rows[#lines] = 'u'
      elseif report.operation == 'semantic_supervise' and type(report.data.results) == 'table' then
        local needs_rebind = report.data.status == 'stale'
        for _, result in ipairs(report.data.results) do
          if type(result) == 'table' and result.status == 'stale' then needs_rebind = true; break end
        end
        if needs_rebind then
          lines[#lines + 1] = ''
          lines[#lines + 1] = tr('  ↻ Choose a mark to rebind [M]', '  ↻ 选择需要重新绑定的标记 [M]', '  ↻ 選擇需要重新繫結的標記 [M]')
          forward_action_rows[#lines] = 'M'
        end
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  → Prepare a training trial [y]', '  → 准备训练试跑 [y]', '  → 準備訓練試跑 [y]')
        forward_action_rows[#lines] = 'y'
      elseif report.operation == 'create' and report.data.committed == true then
        lines[#lines + 1] = ''
        if state.recipe_supervision then
          lines[#lines + 1] = tr('  → Import referenced supervision [5]', '  → 导入引用的监督 [5]', '  → 匯入參照的監督 [5]')
          forward_action_rows[#lines] = '5'
        end
        lines[#lines + 1] = tr('  → Preview image input [j]', '  → 预览图像输入 [j]', '  → 預覽影像輸入 [j]')
        forward_action_rows[#lines] = 'j'
        lines[#lines + 1] = tr('  ▶ Run forward [p]', '  ▶ 运行前向 [p]', '  ▶ 執行前向 [p]')
        forward_action_rows[#lines] = 'p'
        lines[#lines + 1] = tr('  ▶ Prepare a training trial [y]', '  ▶ 准备训练试跑 [y]', '  ▶ 準備訓練試跑 [y]')
        forward_action_rows[#lines] = 'y'
      elseif report.operation == 'train' or report.operation == 'generic_loop_train' then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  → Open training runs [R]', '  → 查看训练运行记录 [R]', '  → 查看訓練執行紀錄 [R]')
        forward_action_rows[#lines] = 'R'
      elseif report.operation == 'training_probe' then
        lines[#lines + 1] = ''
        if state.graph_canvas and state.graph_canvas.project == state.opts.project then
          lines[#lines + 1] = tr('  → Return to model graph [n]', '  → 返回模型图 [n]', '  → 返回模型圖 [n]')
          forward_action_rows[#lines] = 'n'
        end
        if state.recipe_available then
          if state.recipe_kind ~= 'image_classification' then
            lines[#lines + 1] = tr('  → Save selected training settings in declaration [0]',
              '  → 将所选训练设置保存到声明 [0]', '  → 將所選訓練設定儲存到宣告 [0]')
            forward_action_rows[#lines] = '0'
          end
          lines[#lines + 1] = tr('  → Review training settings in declaration [n]',
            '  → 在声明中审核训练设置 [n]', '  → 在宣告中檢視訓練設定 [n]')
          forward_action_rows[#lines] = 'n'
        end
        lines[#lines + 1] = tr('  → Open training runs [R]', '  → 查看训练运行记录 [R]', '  → 查看訓練執行紀錄 [R]')
        forward_action_rows[#lines] = 'R'
        lines[#lines + 1] = tr('  ▶ Prepare training [T]', '  ▶ 准备训练 [T]', '  ▶ 準備訓練 [T]')
        forward_action_rows[#lines] = 'T'
      end
    end
    if report.operation == 'probe' and report.status == 'error' and not displayed.context_changed
        and not displayed.isolated_variant and not displayed.historical_observation then
      lines[#lines + 1] = ''
      if state.canvas_snapshot and not state.canvas_snapshot.cleaned and state.canvas_snapshot.project == state.opts.project then
        lines[#lines + 1] = tr('  ↻ Replay captured input [2]', '  ↻ 重放已捕获输入 [2]', '  ↻ 重播已擷取輸入 [2]')
        forward_action_rows[#lines] = '2'
      else
        lines[#lines + 1] = tr('  ◇ Capture input on the next run [1] (it may differ from this input)',
          '  ◇ 下次运行时捕获输入 [1]（可能与本次不同）', '  ◇ 下次執行時擷取輸入 [1]（可能與本次不同）')
        forward_action_rows[#lines] = '1'
      end
    end
    if report.operation == 'graph_draft_probe' and report.status == 'error'
        and not displayed.context_changed and type(report.data) == 'table'
        and type(report.data.possible_node_id) == 'string' then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('  → Locate the possible failing node in the graph [d]',
        '  → 在画布定位可能出错的节点 [d]', '  → 在畫布定位可能出錯的節點 [d]')
      failure_action_rows[#lines] = 'd'
    end
    if report.operation == 'probe' and report.status == 'error' and not displayed.context_changed
        and not displayed.isolated_variant and not displayed.historical_observation then
      local declaration = vim.uv.fs_lstat(state.opts.project .. '/model-maven.json')
      if declaration and declaration.type == 'file' and declaration.size <= 128 * 1024 then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('  → Open model canvas to review the declaration [n]',
          '  → 打开模型画布检查声明 [n]', '  → 開啟模型畫布檢視宣告 [n]')
        forward_action_rows[#lines] = 'n'
      end
    end
    if #failure_paths > 0 and not displayed.isolated_variant then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Last observed module', '最后观察到的模块', '最後觀察到的模組')
        .. ' · ' .. vim.fn.strcharpart(failure_paths[1]:gsub('[%c]', ' '), 0, 200)
      if type(failure_call.inputs) == 'table' then
        local inputs = tensor_tree_summary(failure_call.inputs, 'input')
        for index, value in ipairs(inputs) do
          if index > 2 then break end
          lines[#lines + 1] = '  ' .. value
        end
      end
      lines[#lines + 1] = tr('The recorded call may have another cause.', '该调用是定位线索，请结合报错判断。', '該呼叫是定位線索，請結合錯誤判斷。')
      lines[#lines + 1] = tr('  → Inspect, edit or replay this module [d]', '  → 检查、修改或重放此模块 [d]', '  → 檢查、修改或重播此模組 [d]')
      failure_action_rows[#lines] = 'd'
      if #failure_frames > 0 then
        lines[#lines + 1] = tr('  ↗ Open a project stack frame [g]', '  ↗ 打开项目调用栈位置 [g]', '  ↗ 開啟專案呼叫堆疊位置 [g]')
        failure_action_rows[#lines] = 'g'
      end
    end
    local attention = supervision_attention(report)
    if attention and attention > 0 then
      lines[#lines + 1] = tr('Rules needing attention: ', '需要处理的规则：', '需要處理的規則：') .. attention
        .. tr(' · inspect the rule results below; a successful request does not mean all rules passed.',
          ' · 请查看下方规则结果；请求成功不代表所有规则通过。', ' · 請查看下方規則結果；要求成功不代表所有規則通過。')
    end
    if report.operation == 'runs_find_request' and report.status == 'success' and type(report.data) == 'table' then
      local lookup = report.data
      local matches = type(lookup.matches) == 'table' and is_list(lookup.matches) and lookup.matches or {}
      lines[#lines + 1] = tr('Request lookup: ', '请求查询：', '要求查詢：')
        .. vim.fn.strcharpart(tostring(lookup.request_id or '?'):gsub('[%c]', '?'), 0, 128)
      if #matches == 0 then
        lines[#lines + 1] = tr('No matching record was found.', '未找到匹配的运行记录。', '未找到相符的執行紀錄。')
      else
        for index, match in ipairs(matches) do
          if index > 8 then lines[#lines + 1] = tr('More matches are in [J].', '更多结果见 [J]。', '更多結果見 [J]。'); break end
          if type(match) == 'table' then
            local id = vim.fn.strcharpart(tostring(match.id or '?'):gsub('[%c]', '?'), 0, 128)
            local status = vim.fn.strcharpart(tostring(match.status or '?'):gsub('[%c]', '?'), 0, 80)
            lines[#lines + 1] = tr('Recorded run / status: ', '记录的运行 / 状态：', '記錄的執行 / 狀態：') .. id .. ' / ' .. status
          end
        end
      end
      lines[#lines + 1] = tr('These are recorded statuses, not proof that a process is alive. Inspect the run and its supervisor before retrying or clearing the marker.',
        '这里是记录状态，不能证明进程仍在运行。重试或移除标记前，请检查运行详情和监督进程。',
        '這裡是紀錄狀態，不能證明程序仍在執行。重試或移除標記前，請檢查執行詳情和監督程序。')
      if lookup.complete ~= true then
        lines[#lines + 1] = tr('Lookup was incomplete; additional records may exist.', '查询不完整，可能还有其他记录。', '查詢不完整，可能還有其他紀錄。')
      end
    end
    if type(report.diagnostics) == 'table' then
      for index, diagnostic in ipairs(report.diagnostics) do
        if index > 32 then lines[#lines + 1] = tr('Further diagnostics are in the complete report.', '更多诊断请查看完整报告。', '更多診斷請查看完整報告。'); break end
        if type(diagnostic) == 'table' then
          lines[#lines + 1] = ''
          if type(diagnostic.code) == 'string' and diagnostic.code ~= '' then
            lines[#lines + 1] = tr('Diagnostic code: ', '诊断代码：', '診斷代碼：')
              .. vim.fn.strcharpart(diagnostic.code:gsub('[%c]', '?'), 0, 128)
          end
          if diagnostic.code == 'PYTHON_SELECTION_REQUIRED' then
            lines[#lines + 1] = tr('A Python interpreter is required. Use [s] to choose one, then retry.',
              '需要 Python 解释器。按 [s] 选择后重试。', '需要 Python 直譯器。按 [s] 選擇後重試。')
          elseif diagnostic.code == 'PYTHON_UNAVAILABLE' or diagnostic.code == 'TORCH_UNAVAILABLE'
              or diagnostic.code == 'OPERATION_CAPABILITY_UNAVAILABLE' then
            lines[#lines + 1] = tr('Check the selected interpreter and its dependencies with [s]. Import failure may also come from initialization code.',
              '可按 [s] 检查所选解释器及其依赖；导入失败也可能来自初始化代码。', '可按 [s] 檢查所選直譯器及其依賴；匯入失敗也可能來自初始化程式碼。')
          elseif diagnostic.code == 'PROTOCOL_ERROR' or diagnostic.code == 'WORKER_API_UNSUPPORTED' or diagnostic.code == 'FEATURE_UNAVAILABLE' then
            lines[#lines + 1] = tr('Check CLI, workspace and worker compatibility; see the original diagnostic for details.',
              '请检查 CLI、工作区和 worker 的兼容性；细节请看原始诊断。', '請檢查 CLI、工作區和 worker 的相容性；細節請看原始診斷。')
          elseif diagnostic.code == 'ENTRYPOINT_LOAD_FAILED' then
            lines[#lines + 1] = tr('Check the entrypoint, selected Python and import paths; imported code may already have run.',
              '请检查入口、所选 Python 和导入路径；导入代码可能已经运行。', '請檢查進入點、所選 Python 和匯入路徑；匯入程式碼可能已經執行。')
          elseif diagnostic.code == 'BATCH_CONSTRUCTION_FAILED' then
            lines[#lines + 1] = tr('The selected input factory failed. Return to the workspace and use [b] to change it or [P] to inspect its parameters.',
              '所选输入工厂执行失败。返回工作区按 [b] 更换，或按 [P] 检查参数。',
              '所選輸入工廠執行失敗。返回工作區按 [b] 更換，或按 [P] 檢查參數。')
          elseif diagnostic.code == 'MODEL_CONSTRUCTION_FAILED' then
            lines[#lines + 1] = tr('The model factory failed. Return to the workspace and use [m] to change it or [P] to inspect its parameters.',
              '模型工厂执行失败。返回工作区按 [m] 更换，或按 [P] 检查参数。',
              '模型工廠執行失敗。返回工作區按 [m] 更換，或按 [P] 檢查參數。')
          elseif diagnostic.code == 'FORWARD_FAILED' then
            lines[#lines + 1] = tr('The model forward failed for this input. Inspect the diagnostic and observed calls; the failing frame may not be the cause.',
              '模型对本次输入的前向执行失败。请检查诊断和观察到的调用；失败位置不一定是根因。',
              '模型對本次輸入的前向執行失敗。請檢查診斷和觀察到的呼叫；失敗位置不一定是根因。')
          elseif diagnostic.code == 'WORKER_TIMEOUT' then
            lines[#lines + 1] = tr('Execution timed out. Inspect any run record and affected files before retrying; the outcome may be unknown.',
              '执行超时。重试前请检查运行记录和受影响文件；结果可能未知。', '執行逾時。重試前請檢查執行紀錄和受影響檔案；結果可能未知。')
          elseif diagnostic.code == 'EXPORT_PYTHON_REQUIRED' then
            lines[#lines + 1] = tr('The run has no recorded Python for extension verification. Use [s] to select one explicitly.',
              '运行未记录用于扩展核验的 Python。按 [s] 明确选择解释器。',
              '執行紀錄未記錄供擴充套件核驗的 Python。按 [s] 明確選擇直譯器。')
          end
          local function add_message(value)
            local text = vim.fn.strcharpart(tostring(value), 0, 4096)
            local parts = vim.split(text, '\n', { plain = true })
            for line_index, line in ipairs(parts) do
              if line_index > 32 then lines[#lines + 1] = '…'; break end
              lines[#lines + 1] = line:gsub('[\r%z\1-\8\11\12\14-\31\127]', '?')
            end
          end
          add_message(locale.graph_diagnostic(diagnostic, diagnostic.code or '?'))
          if diagnostic.hint and diagnostic.hint ~= vim.NIL then add_message(diagnostic.hint) end
        end
      end
    end
    if report.operation == 'doctor' and report.status == 'success' and type(report.data) == 'table' then
      local runtime = report.data
      local function runtime_fact(value)
        return type(value) == 'string' and vim.fn.strcharpart(value:gsub('[%c]', ' '), 0, 320)
          or tr('unknown', '未知', '未知')
      end
      lines[#lines + 1] = ''
      lines[#lines + 1] = 'Python · ' .. runtime_fact(runtime.python) .. ' · ' .. runtime_fact(runtime.python_version)
      lines[#lines + 1] = runtime.torch_available == true and 'PyTorch · ' .. runtime_fact(runtime.torch_version)
        or tr('PyTorch import unavailable', 'PyTorch 无法导入', 'PyTorch 無法匯入')
      if type(runtime.torch_import_error) == 'string' then
        lines[#lines + 1] = runtime_fact(runtime.torch_import_error)
      end
    end
    if report.operation == 'inspect' or report.operation == 'layers' or report.operation == 'probe' then
      local data = type(report.data) == 'table' and report.data or {}
      local mode = (report.operation == 'inspect' or report.operation == 'layers') and 'static' or 'full'
      if type(data.local_probe_reports) == 'table' then mode = 'targeted' end
      if report.operation == 'probe' and type(data.local_probe_reports) ~= 'table' then
        if data.forward_execution == 'failed' then mode = 'failed_forward'
        elseif data.forward_execution ~= 'executed' then mode = 'unknown' end
      end
      lines[#lines + 1] = ''
      vim.list_extend(lines, validation_progress.cost_lines(mode, {
        supported = type(data.local_probe_reports) == 'table',
        heavy_dependencies = type(data.runtime) == 'table' and data.runtime.heavy_dependencies or nil,
      }))
    end
    if report.operation == 'preview' and type(report.data) == 'table' and report.data.published == false then
      lines[#lines + 1] = tr('This preview was not published; a newer request has taken over. Use j or J to request a new preview if needed.',
        '本次预览未发布，较新的请求已接管；如有需要，可按 j 或 J 重新请求预览。',
        '本次預覽未發布，較新的要求已接管；如有需要，可按 j 或 J 重新要求預覽。')
    end
    local report_data = type(report.data) == 'table' and report.data or {}
    local readiness = report_data.readiness
      or (type(report_data.plan) == 'table' and report_data.plan.readiness)
      or (type(report_data.operation_plan) == 'table' and report_data.operation_plan.readiness)
    -- Current CLI reports may place the complete OperationPlan in
    -- data.readiness; its actions live in the nested readiness object.
    -- Older reports may already expose that object directly.
    if type(readiness) == 'table' and type(readiness.readiness) == 'table' then
      readiness = readiness.readiness
    end
    local recommended = type(readiness) == 'table' and readiness.actions or nil
    if type(recommended) == 'table' and is_list(recommended) and #recommended > 0 then
      readiness_actions = recommended
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Recommended recovery actions reported by the backend:', '后端建议的恢复操作：', '後端建議的復原操作：')
      for index, action in ipairs(recommended) do
        if index > 16 then break end
        if type(action) == 'table' then
          local label = tostring(action.label or action.id or '?'):gsub('[\r\n%z\1-\31\127]', ' ')
          local reason = tostring(action.description or action.reason or tr('details unavailable', '详情不可用', '詳細資料無法使用'))
            :gsub('[\r\n%z\1-\31\127]', ' ')
          local availability = readiness_availability(action.availability)
          lines[#lines + 1] = vim.fn.strcharpart(label, 0, 160) .. ' · ' .. availability .. ' · ' .. vim.fn.strcharpart(reason, 0, 240)
        end
      end
      lines[#lines + 1] = tr('Use the indicated workspace environment, input or adapter choice; actions without a known handler remain recommendations only.',
        '请通过工作区环境、输入或适配器选择入口执行建议；没有已知处理器的操作仅作提示。',
        '請透過工作區環境、輸入或配接器選擇入口執行建議；沒有已知處理器的操作僅作提示。')
      lines[#lines + 1] = tr('Press [a] to open a listed recovery action.', '按 [a] 打开列表中的恢复操作。', '按 [a] 開啟列表中的復原操作。')
    end
    if report.operation == 'project_discover' and report.status == 'success' and type(report.data) == 'table' then
      local data = report.data
      lines[#lines + 1] = tr('Static source discovery: ', '静态源码发现：', '靜態原始碼探索：')
        .. (type(data.scanned_files) == 'number' and tostring(data.scanned_files) or '?')
        .. tr(' files scanned; skipped entries: ', ' 个已扫描文件；跳过条目：', ' 個已掃描檔案；略過項目：')
        .. (type(data.skipped) == 'number' and tostring(data.skipped) or '?')
      if type(data.omitted_directory_count) == 'number' then
        lines[#lines + 1] = tr('Omitted directories: ', '省略目录数：', '省略目錄數：') .. tostring(data.omitted_directory_count)
          .. tr(' (paths and reasons in the complete report)', '（路径和原因见完整报告）', '（路徑和原因請見完整報告）')
      else
        lines[#lines + 1] = tr('Omitted-directory details are unavailable in this CLI.', '此 CLI 未提供省略目录详情。', '此 CLI 未提供省略目錄詳情。')
      end
      if data.truncated == true then
        lines[#lines + 1] = tr('Scan limits were reached; unscanned files remain unknown.',
          '已达到扫描上限，未扫描文件的内容未知。', '已達到掃描上限，未掃描檔案的內容未知。')
      end
      lines[#lines + 1] = tr('Use K to prioritize a project import directory, or enter an existing callable manually.',
        '可用 K 优先扫描项目模块目录，或手动填写已有函数。', '可用 K 優先掃描專案模組目錄，或手動填寫既有函式。')
    end
    if report.operation == 'variant_show' and report.status == 'success' and type(report.data) == 'table' then
      local variant = type(report.data.variant) == 'table' and report.data.variant or {}
      local origin = type(variant.origin) == 'table' and variant.origin or {}
      local function safe(value)
        return vim.fn.strcharpart(tostring(value or '?'):gsub('[%c]', ' '), 0, 256)
      end
      local policy = variant.device_policy == nil and 'legacy_cpu' or variant.device_policy
      lines[#lines + 1] = tr('Saved variant: ', '已保存变体：', '已儲存變體：') .. safe(report.data.name)
      lines[#lines + 1] = tr('Original model factory: ', '原始模型工厂：', '原始模型工廠：') .. safe(origin.model)
      lines[#lines + 1] = tr('Reconstruction device policy: ', '重建设备策略：', '重建裝置策略：') .. safe(policy)
      lines[#lines + 1] = tr('Replacement layers may move to the first registered state of the old layer; input is not moved automatically.',
        '替换层可能迁移到旧层首个已注册状态的设备；输入不会自动迁移。',
        '替換層可能遷移到舊層首個已註冊狀態的裝置；輸入不會自動遷移。')
      lines[#lines + 1] = tr('Layer seeds cover CPU and any devices explicitly recorded per operation; other devices and user RNGs may differ. See [J].',
        'Layer 种子覆盖 CPU 及各操作明确记录的设备；其他设备和用户随机源可能不同，详见 [J]。',
        'Layer 種子涵蓋 CPU 及各操作明確記錄的裝置；其他裝置和使用者隨機來源可能不同，詳見 [J]。')
      local seed_decimal = report.data.initialization_seed_decimal
      if type(seed_decimal) == 'string' and #seed_decimal <= 20 and seed_decimal:match('^%d+$') then
        lines[#lines + 1] = tr('Construction seed: ', '构造种子：', '建構種子：') .. seed_decimal
      else
        lines[#lines + 1] = tr('Construction seed: unavailable exactly', '构造种子：无法精确获取', '建構種子：無法精確取得')
      end
      lines[#lines + 1] = tr('Edit position / history: ', '编辑位置 / 历史数：', '編輯位置 / 歷史數：')
        .. safe(variant.cursor) .. ' / ' .. (type(variant.edits) == 'table' and tostring(#variant.edits) or '?')
      lines[#lines + 1] = tr('Metadata only; the variant has not been reconstructed or checked. Full details: [J].',
        '这里只读取元数据；尚未重建或核验变体。完整详情见 [J]。',
        '此處僅讀取中繼資料；尚未重建或核驗變體。完整詳情見 [J]。')
    end
    if report.operation == 'assembly_generate' and report.status == 'success' and type(report.data) == 'table' then
      local data = report.data
      local generated = type(data.generated_validation) == 'table' and data.generated_validation or {}
      local comparison = type(data.input_comparison) == 'table' and data.input_comparison or {}
      local input_status = {
        same = tr('same observed input', '观察到的输入一致', '觀察到的輸入一致'),
        different = tr('observed inputs differ', '观察到的输入不同', '觀察到的輸入不同'),
        unknown = tr('unknown', '未知', '未知'),
        not_run = tr('no forward input', '未执行前向输入', '未執行前向輸入'),
      }
      local function safe(value)
        return vim.fn.strcharpart(tostring(value or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
      end
      lines[#lines + 1] = tr('Generated file: ', '生成文件：', '產生檔案：') .. safe(data.output)
      lines[#lines + 1] = tr('Independent reconstruction: ', '独立重建：', '獨立重建：') .. safe(generated.construction)
      lines[#lines + 1] = tr('Independent forward: ', '独立前向：', '獨立前向：') .. safe(generated.forward)
      local seed = data.initialization_seed
      local decimal = data.initialization_seed_decimal
      local seed_text = type(decimal) == 'string' and #decimal <= 20 and decimal:match('^%d+$') and decimal
        or seed == vim.NIL and tr('runtime state', '运行时状态', '執行時狀態')
        or type(seed) == 'number' and (math.abs(seed) > 9007199254740991
          and tr('too large to display exactly', '数值过大，无法精确显示', '數值過大，無法精確顯示') or tostring(seed))
        or tr('unknown', '未知', '未知')
      lines[#lines + 1] = tr('Generated initialization seed: ', '生成代码初始化种子：', '產生程式碼初始化種子：') .. seed_text
      lines[#lines + 1] = tr('Factory state and non-CPU randomness may differ across constructions.',
        '工厂状态与非 CPU 随机状态在不同构造间可能不同。', '工廠狀態與非 CPU 隨機狀態在不同建構間可能不同。')
      if seed ~= nil and seed ~= vim.NIL or (type(decimal) == 'string' and decimal:match('^%d+$')) then
        lines[#lines + 1] = tr('Generated base construction seeds Python, CPU and any explicitly recorded accelerator RNGs; other random sources and weights may differ.',
          '生成代码的基础模型构造设置 Python、CPU 及明确记录的加速器种子；其他随机来源和权重可能不同。',
          '產生程式碼的基礎模型建構設定 Python、CPU 及明確記錄的加速器種子；其他隨機來源和權重可能不同。')
      end
      lines[#lines + 1] = tr('Input comparison: ', '输入对照：', '輸入對照：') .. (input_status[comparison.status] or tr('unknown', '未知', '未知'))
      local placement = type(data.placement_comparison) == 'table' and data.placement_comparison or {}
      local placement_labels = {
        same = tr('matching observed counts', '观察到的数量一致', '觀察到的數量一致'),
        different = tr('observed counts differ', '观察到的数量不同', '觀察到的數量不同'),
        unknown = tr('unknown', '未知', '未知'),
      }
      lines[#lines + 1] = tr('Registered device / dtype counts: ', '已注册状态的设备 / 类型数量对照：', '已註冊狀態的裝置 / 型別數量對照：')
        .. (placement_labels[placement.status] or placement_labels.unknown)
      lines[#lines + 1] = tr('Counts do not establish tensor-by-tensor placement or weight equality; details are in [J].',
        '数量不能证明各张量的位置或权重相同；详情见 [J]。',
        '數量不能證明各張量的位置或權重相同；詳情見 [J]。')
      local shared_state = type(data.shared_state_comparison) == 'table' and data.shared_state_comparison or {}
      local shared_labels = {
        same = tr('matching observed groups', '观察到的共享组一致', '觀察到的共享組一致'),
        different = tr('observed groups differ', '观察到的共享组不同', '觀察到的共享組不同'),
        unknown = tr('unknown or partially observable', '未知或仅部分可观察', '未知或僅部分可觀察'),
      }
      lines[#lines + 1] = tr('Registered shared-state comparison: ', '已注册共享状态对照：', '已註冊共享狀態對照：')
        .. (shared_labels[shared_state.status] or shared_labels.unknown)
      lines[#lines + 1] = tr('Only registered objects and inspectable storage are compared before forward; details: [J].',
        '仅比较前向前已注册对象和可检查存储；详情见 [J]。', '僅比較前向前已註冊物件和可檢查儲存；詳情見 [J]。')
      local aliases = type(generated.module_aliases) == 'table' and generated.module_aliases or {}
      local alias_comparison = type(data.module_alias_comparison) == 'table' and data.module_alias_comparison or {}
      if aliases.status == 'observed' then
        lines[#lines + 1] = tr('Shared module groups in generated construction: ', '生成代码构造中观察到的共享模块组数：', '產生程式碼建構中觀察到的共享模組組數：') .. safe(aliases.group_count)
        local labels = { same = tr('same observed groups', '观察到的共享组相同', '觀察到的共享組相同'),
          different = tr('observed groups differ', '观察到的共享组不同', '觀察到的共享組不同'),
          unknown = tr('unknown', '未知', '未知') }
        lines[#lines + 1] = tr('Construction sharing comparison: ', '构造时共享关系对照：', '建構時共享關係對照：')
          .. (labels[alias_comparison.status] or labels.unknown)
        lines[#lines + 1] = tr('Only registered module identity is compared before forward; full paths are in [J].',
          '仅比较前向前已注册模块的实例关系；完整路径见 [J]。', '僅比較前向前已註冊模組的實例關係；完整路徑見 [J]。')
      else
        lines[#lines + 1] = tr('Shared module evidence is unavailable.', '共享模块证据不可用。', '共享模組證據不可用。')
      end
      lines[#lines + 1] = tr('The wrapper does not include trained weights, project dependencies or data. Review the file before editing or running it.',
        '适配代码不包含训练权重、项目依赖或数据；编辑或运行前请检查文件。',
        '配接程式碼不包含訓練權重、專案依賴或資料；編輯或執行前請檢查檔案。')
      lines[#lines + 1] = tr('Close this report and use o to open the generated file.', '关闭报告后按 o 打开生成文件。', '關閉報告後按 o 開啟產生檔案。')
    end
    if report.operation == 'assembly_generate' and report.status == 'error' and type(report.data) == 'table' then
      local differences = {
        { report.data.module_alias_difference, tr('Shared modules', '共享模块', '共享模組') },
        { report.data.shared_state_difference, tr('Shared state', '共享状态', '共享狀態') },
      }
      for _, pair in ipairs(differences) do
        local diff = pair[1]
        if type(diff) == 'table' and diff.status == 'compared' then
          lines[#lines + 1] = pair[2] .. tr(' differ; no file was created.', '存在差异；未创建文件。', '存在差異；未建立檔案。')
          for _, side in ipairs({
            { 'original_only', 'original_only_count', tr('Original only', '仅原候选', '僅原候選') },
            { 'generated_only', 'generated_only_count', tr('Generated only', '仅生成结果', '僅產生結果') },
          }) do
            lines[#lines + 1] = '  ' .. side[3] .. ': ' .. tostring(diff[side[2]] or '?')
            local groups = diff[side[1]]
            if type(groups) == 'table' and is_list(groups) then
              for index, group in ipairs(groups) do
                if index > 3 then break end
                local ok, text = pcall(vim.inspect, bounded_summary(group))
                if ok then lines[#lines + 1] = '    ' .. vim.fn.strcharpart(text:gsub('[%c]', ' '), 0, 500) end
              end
            end
          end
          lines[#lines + 1] = tr('More details are in [J]; inspect the relevant factories or edit history.',
