      local delivery = type(preview.delivery) == 'table' and preview.delivery or {}
      local function safe(value)
        if value == nil or value == vim.NIL then return '?' end
        return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
      end
      lines[#lines + 1] = tr('Sample count: ', '样本数量：', '樣本數量：') .. safe(preview.sample_count)
      lines[#lines + 1] = preview.cached == true
        and tr('A previous preview was reused.', '复用了先前预览。', '重用了先前預覽。')
        or (preview.cached == false and tr('A new preview was generated.', '已生成新的预览。', '已產生新的預覽。')
          or tr('Preview reuse was not reported.', '未报告是否复用预览。', '未回報是否重用預覽。'))
      local interpretation = type(preview.scope) == 'table' and preview.scope.sample_interpretation or nil
      if interpretation == 'whole_factory_output_batch_axis_unknown' then
        lines[#lines + 1] = tr('One item is the entire factory output; its batch axis is unknown.',
