        lines[#lines + 1] = tr('Rendered images: ', '已渲染图像数：', '已渲染影像數：') .. safe(preview.rendered_image_count)
      end
      local scope = type(preview.scope) == 'table' and preview.scope or {}
      if type(scope.source_entrypoint) == 'string' then
        lines[#lines + 1] = tr('Input factory: ', '输入工厂：', '輸入工廠：') .. safe(scope.source_entrypoint)
      end
      if scope.batch_binding == 'single-raw' and interpretation ~= 'graph_image_batch_samples' then
        lines[#lines + 1] = tr('The complete factory result was previewed as one item without dataset sampling.',
          '工厂的完整返回值作为一项预览，未进行数据集采样。', '工廠的完整回傳值作為一項預覽，未進行資料集取樣。')
      end
      local observation = type(scope.data_observation) == 'table' and scope.data_observation or {}
      local coverage = type(observation.coverage) == 'table' and observation.coverage or {}
      if coverage.kind == 'indexed-subset' and type(coverage.population_size) == 'number' then
        lines[#lines + 1] = tr('Indexed dataset size: ', '可索引数据集大小：', '可索引資料集大小：')
          .. safe(coverage.population_size) .. tr(' (sampling does not establish coverage)', '（采样不能证明覆盖范围）', '（取樣不能證明涵蓋範圍）')
      end
      local augment_labels = {
        train = tr('project training pipeline', '项目训练增强', '專案訓練增強'),
        eval = tr('project evaluation pipeline', '项目评估增强', '專案評估增強'),
        none = tr('no project augmentation', '不使用项目增强', '不使用專案增強'),
      }
      if augment_labels[scope.augment_selection] then
        lines[#lines + 1] = tr('Requested augmentation: ', '请求的增强：', '要求的增強：') .. augment_labels[scope.augment_selection]
      end
      if scope.seed ~= nil and scope.seed ~= vim.NIL then
        local decimal = type(scope.seed_decimal) == 'string' and #scope.seed_decimal <= 20
          and scope.seed_decimal:match('^%d+$') and scope.seed_decimal or nil
        local seed_text = decimal or (type(scope.seed) == 'number' and math.abs(scope.seed) > 9007199254740991
          and tr('too large to display exactly here', '数值过大，无法在此精确显示', '數值過大，無法在此精確顯示')
          or safe(scope.seed))
        lines[#lines + 1] = tr('Sampling seed: ', '采样种子：', '取樣種子：') .. seed_text
          .. tr(' (does not fix factory or external randomness)', '（不固定工厂或外部随机性）', '（不固定工廠或外部隨機性）')
      end
      if type(scope.data_observation) == 'table' then
        local capabilities = type(observation.capabilities) == 'table' and observation.capabilities or {}
        if capabilities.independent_sampling ~= true then
          lines[#lines + 1] = tr('Sampling independence from training is unknown; user data sources may share state or streams.',
            '无法确认采样与训练相互独立；用户数据源可能共享状态或数据流。',
            '無法確認取樣與訓練相互獨立；使用者資料來源可能共用狀態或資料流。')
        end
        if coverage.seed_forwarded_to_factory == true then
          lines[#lines + 1] = tr('A seed was passed to the dataset factory; it may differ from the sampling seed.',
            '已向数据集工厂传入种子；它可能与采样种子不同。', '已向資料集工廠傳入種子；它可能與取樣種子不同。')
        elseif coverage.seed_forwarded_to_factory == false then
          lines[#lines + 1] = tr('No seed was passed to the dataset factory.', '未向数据集工厂传入种子。', '未向資料集工廠傳入種子。')
        else
          lines[#lines + 1] = tr('Whether the dataset factory received a seed is unknown.', '数据集工厂是否收到种子未知。', '資料集工廠是否收到種子未知。')
        end
      end
      if scope.split ~= nil and scope.split ~= vim.NIL then
        local handling = {
          dictionary_key = tr('Selected from returned split dictionary.', '已从返回的切分字典中选择。', '已從回傳的切分字典中選取。'),
          factory_argument = tr('Passed to the factory; its behavior is not verified.', '已传给工厂；工厂是否实际使用尚未验证。', '已傳給工廠；工廠是否實際使用尚未驗證。'),
          unverified = tr('Could not verify that the selected split was applied.', '无法确认所选切分已生效。', '無法確認所選切分已生效。'),
        }
        if interpretation == 'graph_image_batch_samples' then
          lines[#lines + 1] = tr('Image factory split: ', '图像工厂切分：', '影像工廠切分：') .. safe(scope.split)
          lines[#lines + 1] = tr('Uses declared image transforms; project augmentation was not applied.',
            '使用声明的图像变换；未应用项目级增强。', '使用宣告的影像變換；未套用專案級增強。')
        else
          lines[#lines + 1] = tr('Requested split: ', '请求的切分：', '要求的切分：') .. safe(scope.split)
          lines[#lines + 1] = handling[coverage.split_handling]
            or tr('How the split was applied is unknown.', '切分如何生效未知。', '切分如何生效未知。')
        end
      elseif coverage.split_handling == 'not_requested' then
        lines[#lines + 1] = tr('No dataset split was requested.', '未请求数据集切分。', '未要求資料集切分。')
      end
      if type(preview.structure_summaries) == 'table' and is_list(preview.structure_summaries) then
        for index, summary in ipairs(preview.structure_summaries) do
          if index > 3 then break end
          if type(summary) == 'string' then
            lines[#lines + 1] = tr('Input structure ', '输入结构 ', '輸入結構 ') .. index .. ':'
            local entries = vim.split(summary, '\n', { plain = true })
            for row, entry in ipairs(entries) do
              if row > 48 then lines[#lines + 1] = tr('Further fields omitted.', '更多字段已省略。', '更多欄位已省略。'); break end
              lines[#lines + 1] = '  ' .. safe(entry)
            end
          end
        end
        if #preview.structure_summaries > 0 then
          lines[#lines + 1] = tr('Structure values are omitted; names can be sensitive. See the HTML for more items.',
            '结构中不显示值；字段名可能敏感。更多项见 HTML。',
            '結構中不顯示值；欄位名稱可能敏感。更多項請見 HTML。')
        end
      end
      if delivery.mode == 'local' and type(delivery.path) == 'string' then
        lines[#lines + 1] = tr('Local preview file: ', '本地预览文件：', '本機預覽檔案：') .. safe(delivery.path)
        lines[#lines + 1] = tr('Open it using your preferred viewer; it may contain sensitive data.',
          '请用自己选择的查看器打开；文件可能包含敏感数据。', '請用自己選擇的檢視器開啟；檔案可能包含敏感資料。')
      end
      lines[#lines + 1] = tr('This preview does not establish training dataset coverage.',
        '此预览不能证明训练数据集覆盖范围。', '此預覽不能證明訓練資料集涵蓋範圍。')
    end
    local contract = report.operation == 'probe' and type(report.data) == 'table' and report.data.contract_report
    if type(contract) == 'table' then
      local function contract_text(value)
        if value == nil or value == vim.NIL then return tr('unknown', '未知', '未知') end
        return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 240)
      end
      local contract_statuses = {
        ['observed-runtime'] = tr('passed for observed calls', '已观察调用通过', '已觀察呼叫通過'),
        partial = tr('partial coverage', '覆盖不完整', '涵蓋不完整'),
        failed = tr('mismatch', '存在不匹配', '存在不相符'),
        unsupported = tr('cannot check', '无法检查', '無法檢查'),
        unobserved = tr('not observed', '未观察到', '未觀察到'),
      }
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Port contract: ', '端口契约：', '連接埠契約：') .. (contract_statuses[contract.status] or contract_text(contract.status))
      local identity = contract.contract_identity_check == 'matched' and tr('matched reviewed bytes', '已核对确认内容', '已核對確認內容')
        or (contract.contract_identity_check == 'not_requested' and tr('not requested', '未请求核对', '未要求核對') or tr('unknown', '未知', '未知'))
      lines[#lines + 1] = tr('Contract identity: ', '契约身份：', '契約身分：') .. identity
        .. ' · ' .. (type(contract.contract_content_sha256) == 'string' and #contract.contract_content_sha256 == 64
          and contract.contract_content_sha256:match('^[0-9a-f]+$') and contract.contract_content_sha256:sub(1, 12)
          or tr('digest unknown', '摘要未知', '摘要未知'))
      if type(contract.checks) == 'table' and is_list(contract.checks) then
        for index, check in ipairs(contract.checks) do
          if index > 32 then lines[#lines + 1] = tr('Further checks are in the complete report [J].', '更多检查见完整报告 [J]。', '更多檢查見完整報告 [J]。'); break end
          if type(check) == 'table' then
            lines[#lines + 1] = '  ' .. contract_text(check.path) .. ' · ' .. (contract_statuses[check.status] or contract_text(check.status))
            if type(check.mismatches) == 'table' and #check.mismatches > 0 then
              for mismatch_index, mismatch in ipairs(check.mismatches) do
                if mismatch_index > 4 then lines[#lines + 1] = tr('    More mismatches in [J].', '    更多不匹配见 [J]。', '    更多不相符項目見 [J]。'); break end
                if type(mismatch) == 'table' then
                  lines[#lines + 1] = tr('    Field: ', '    字段：', '    欄位：') .. contract_text(mismatch.field)
                    .. tr(' · expected: ', ' · 期望：', ' · 預期：') .. contract_text(vim.inspect(mismatch.expected))
                    .. tr(' · actual: ', ' · 实际：', ' · 實際：') .. contract_text(vim.inspect(mismatch.actual))
                end
              end
            end
            if type(check.unknown_fields) == 'table' and is_list(check.unknown_fields) and #check.unknown_fields > 0 then
              local fields = {}
              for field_index, field in ipairs(check.unknown_fields) do
                if field_index > 8 then fields[#fields + 1] = '…'; break end
                fields[#fields + 1] = contract_text(field)
              end
              lines[#lines + 1] = tr('    Unknown fields: ', '    未知字段：', '    未知欄位：') .. table.concat(fields, ', ')
            end
            if type(check.coverage) == 'string' then lines[#lines + 1] = '    ' .. contract_text(check.coverage) end
          end
        end
      else
        lines[#lines + 1] = tr('Individual checks are unavailable.', '单项检查结果不可用。', '個別檢查結果無法使用。')
      end
      lines[#lines + 1] = type(contract.coverage) == 'string' and contract_text(contract.coverage)
        or tr('Results cover only the reported inference and observed calls.',
          '结果仅覆盖已报告的推演和实际观察到的调用。', '結果僅涵蓋已回報的推演和實際觀察到的呼叫。')
      if #contract_paths > 0 and #failure_paths == 0 and not rule_failure_path then
        lines[#lines + 1] = tr('[d] Inspect or edit a module associated with a reported check.',
          '[d] 检查或修改与检查结果相关的模块。', '[d] 檢查或修改與檢查結果相關的模組。')
      end
    end
    if type(displayed.contract_file) == 'string' then
      lines[#lines + 1] = tr('[b] Open the current contract file for editing; it may have changed since this report.',
        '[b] 打开当前契约文件进行编辑；文件可能在报告后发生变化。', '[b] 開啟目前契約檔案進行編輯；檔案可能在報告後發生變更。')
    end
    if report.operation == 'runs_show' and type(report.data) == 'table'
        and type(report.data.seed_decimal) == 'string' and #report.data.seed_decimal <= 20
        and report.data.seed_decimal:match('^%d+$') then
      lines[#lines + 1] = tr('Recorded execution seed: ', '记录的执行种子：', '記錄的執行種子：') .. report.data.seed_decimal
      lines[#lines + 1] = tr('A variant may have a separate construction seed.',
        '变体可能有独立的构造种子。', '變體可能有獨立的建構種子。')
    end
    local generic_report = (report.operation == 'generic_loop_trial' or report.operation == 'generic_loop_train') and report
      or (report.operation == 'runs_show' and type(report.data) == 'table'
        and type(report.data.report) == 'table' and (report.data.report.operation == 'generic_loop_trial'
          or report.data.report.operation == 'generic_loop_train') and report.data.report or nil)
    if generic_report and type(generic_report.data) == 'table' then
      local data = generic_report.data
      if data.detached == true then
        lines[#lines + 1] = tr('Background run started. Open runs to follow progress or request a stop.',
          '后台运行已启动。打开运行记录可跟踪进度或请求停止。', '背景執行已啟動。開啟執行紀錄可追蹤進度或要求停止。')
      else
        lines[#lines + 1] = tr('User-reported steps / requested target: ', '用户报告的步数 / 请求目标：', '使用者回報的步數 / 要求目標：')
          .. (type(data.completed_steps) == 'number' and tostring(data.completed_steps) or tr('unknown', '未知', '未知'))
          .. ' / ' .. (type(data.requested_steps) == 'number' and tostring(data.requested_steps) or tr('unknown', '未知', '未知'))
        if data.termination_reason == 'target_reached' then
          lines[#lines + 1] = tr('The loop reported the requested number of steps.', '循环已报告请求的步数。', '迴圈已回報要求的步數。')
        elseif data.termination_reason == 'loop_returned_before_target' then
          lines[#lines + 1] = tr('The loop returned before the requested step target; check the user code and saved state.',
            '循环在请求的步数目标之前返回；请检查用户代码及已保存状态。', '迴圈在要求的步數目標之前返回；請檢查使用者程式碼及已儲存狀態。')
        elseif generic_report.status == 'success' then
          lines[#lines + 1] = tr('Termination reason was not reported by this worker.',
            '此 worker 未报告结束原因。', '此 worker 未回報結束原因。')
        end
      end
      if type(data.last_metrics) == 'table' then
        local names = vim.tbl_keys(data.last_metrics)
        table.sort(names)
        for index, name in ipairs(names) do
          if index > 16 then lines[#lines + 1] = tr('Further metrics are in the full report.', '更多指标见完整报告。', '更多指標見完整報告。'); break end
          local value = data.last_metrics[name]
          if type(name) == 'string' and type(value) == 'number' then
            lines[#lines + 1] = vim.fn.strcharpart(name:gsub('[\r\n%z\1-\31\127]', ' '), 0, 128) .. ': ' .. tostring(value)
          end
        end
      end
      if data.detached ~= true then
        lines[#lines + 1] = generic_report.operation == 'generic_loop_trial'
          and tr('These are user reports, not verified model updates. Trial state was not saved.',
            '这是用户报告，不证明模型已更新；试跑状态未保存。', '這是使用者回報，不證明模型已更新；試跑狀態未儲存。')
          or tr('These are user reports, not verified model updates. Only explicitly reported JSON state can be restored.',
            '这是用户报告，不证明模型已更新；仅能恢复明确报告的 JSON 状态。', '這是使用者回報，不證明模型已更新；僅能恢復明確回報的 JSON 狀態。')
        if data.recovery_status == 'no_user_state_reported' then
          lines[#lines + 1] = tr('No state was reported in this run; there is no tool-managed checkpoint for this run.',
            '本次运行未报告状态；本次没有可由工具恢复的检查点。', '本次執行未回報狀態；本次沒有可由工具恢復的檢查點。')
        elseif data.recovery_status == 'checkpoint_recorded_verify_before_resume' then
          lines[#lines + 1] = tr('A checkpoint was recorded before the failure or stop; it must be verified when resuming.',
            '失败或停止前已记录检查点；恢复时仍须核验。', '失敗或停止前已記錄檢查點；恢復時仍須驗證。')
        end
        if type(data.checkpoint_completed_steps) == 'number' then
          lines[#lines + 1] = tr('Last saved state step: ', '最近保存的状态步数：', '最近儲存的狀態步數：') .. tostring(data.checkpoint_completed_steps)
            .. tr(' (later progress may not be included)', '（可能不包含其后的进度）', '（可能不包含其後的進度）')
        end
      end
      local delta = data.source_observation_delta
      if type(delta) == 'table' and delta.scope == 'loaded_project_modules_and_package_trees'
          and type(delta.changed_content_count) == 'number' and type(delta.newly_observed_count) == 'number'
          and type(delta.no_longer_observed_count) == 'number' then
        lines[#lines + 1] = tr('Captured source: content changed / newly captured / no longer captured: ',
          '源码采集：内容变化 / 新采集 / 不再采集：', '原始碼採集：內容變更 / 新採集 / 不再採集：')
          .. tostring(delta.changed_content_count) .. ' / ' .. tostring(delta.newly_observed_count) .. ' / ' .. tostring(delta.no_longer_observed_count)
        lines[#lines + 1] = tr('Includes loaded modules and their package trees, not proof every file executed. Baseline follows loop import; newly captured files do not prove changes, and uncovered changes are unknown.',
          '范围包括已加载模块及其包目录，不代表每个文件都已执行。基线位于循环导入之后；新采集不代表文件已修改，未覆盖变化未知。',
          '範圍包括已載入模組及其套件目錄，不代表每個檔案都已執行。基準位於迴圈匯入之後；新採集不代表檔案已修改，未涵蓋變更未知。')
      elseif data.source_changed_during_run == true then
        lines[#lines + 1] = tr('The observed source set or content changed; the older report cannot distinguish them.',
          '源码观察集合或内容发生变化；旧报告无法区分二者。', '原始碼觀察集合或內容發生變化；舊報告無法區分兩者。')
      end
    end
    if report.operation == 'runs_show' and type(report.data) == 'table'
        and type(report.data.record) == 'table' and report.data.record.operation == 'generic_loop_train' then
      local record = report.data.record
      local summary = type(record.summary) == 'table' and record.summary or {}
      local checkpoint = type(report.data.checkpoint) == 'table' and report.data.checkpoint or nil
      if summary.completed_steps_source == 'checkpoint_manifest_unverified' then
        lines[#lines + 1] = tr('Last known checkpoint step: ', '清单记录的最近检查点步数：', '清單記錄的最近檢查點步數：')
          .. tostring(summary.completed_steps or '?')
          .. tr(' (unverified; later progress unknown)', '（未核验；后续进度未知）', '（未驗證；後續進度未知）')
      elseif not generic_report and summary.completed_steps_source == 'worker_report' then
        lines[#lines + 1] = tr('Last worker-reported step: ', 'worker 报告的最近步数：', 'worker 回報的最近步數：') .. tostring(summary.completed_steps or '?')
      elseif not generic_report then
        lines[#lines + 1] = tr('Last reported step is unknown.', '最近报告的步数未知。', '最近回報的步數未知。')
      end
      if checkpoint and type(checkpoint.completed_steps) == 'number' then
        lines[#lines + 1] = tr('Checkpoint manifest step: ', '检查点清单步数：', '檢查點清單步數：') .. tostring(checkpoint.completed_steps)
          .. tr(' (verified on resume)', '（恢复时核验）', '（恢復時驗證）')
      end
    end
    if report.operation == 'semantic_mark' and type(report.data) == 'table'
        and type(report.data.mark) == 'table' then
      local observation = report.data.mark.observation
      local coverage = type(observation) == 'table' and observation.trace_coverage
      if type(coverage) == 'table' and coverage.scope == 'selected-subtree' then
        lines[#lines + 1] = tr('Mark observation: selected subtree complete; only this input and executed path are covered.',
          '标记观察：所选子树记录完整；仅覆盖本次输入和实际执行路径。',
          '標記觀察：所選子樹紀錄完整；僅涵蓋本次輸入和實際執行路徑。')
        if coverage.full_trace_truncated == true then
          lines[#lines + 1] = tr('The full-model trace was truncated.', '全模型调用记录已截断。', '全模型呼叫紀錄已截斷。')
        end
      end
    end
    local training_data = report.operation == 'train' and report.data
      or (report.operation == 'runs_show' and type(report.data) == 'table'
        and type(report.data.report) == 'table' and report.data.report.data or nil)
    if report.operation == 'training_probe' then training_data = report.data end
    if report.operation == 'train' and report.status == 'success' and type(training_data) == 'table'
        and training_data.detached == true then
      lines[#lines + 1] = tr('Background training started; this receipt does not establish that training completed. Open runs to follow it.',
        '后台训练已启动；此回执不代表训练已完成。打开运行记录查看进度。',
        '背景訓練已啟動；此回執不代表訓練已完成。開啟執行紀錄查看進度。')
    end
    local recorded_inputs = report.operation == 'runs_show' and type(report.data) == 'table'
      and type(report.data.inputs) == 'table' and report.data.inputs or nil
    local recorded_policy = recorded_inputs and recorded_inputs.batch_device_policy or nil
    local batch_policy = type(training_data) == 'table' and training_data.batch_device_policy or recorded_policy
    local is_training = report.operation == 'train' or report.operation == 'training_probe'
      or (recorded_inputs and (recorded_inputs.operation == 'train' or recorded_inputs.operation == 'training_probe'))
    if is_training and (batch_policy == 'preserve' or batch_policy == 'recursive-strict' or batch_policy == 'legacy-recursive') then
      lines[#lines + 1] = tr('Training batch device policy: ', '训练批次设备策略：', '訓練批次裝置策略：') .. batch_policy
    elseif recorded_inputs and (recorded_inputs.operation == 'train' or recorded_inputs.operation == 'training_probe')
        and (recorded_inputs.training_mode == 'managed-step' or recorded_inputs.training_mode == 'manual-step')
        and (recorded_policy == nil or recorded_policy == vim.NIL) then
      lines[#lines + 1] = tr('Training batch device policy: legacy behavior (not recorded)',
        '训练批次设备策略：历史行为（未记录）', '訓練批次裝置策略：歷史行為（未記錄）')
    end
    if type(training_data) == 'table' and type(training_data.seed_decimal) == 'string'
        and training_data.seed_decimal:match('^%d+$') and #training_data.seed_decimal <= 20 then
      local seed_sources = {
        generated_for_new_run = tr(' (generated for this run)', '（为本次运行生成）', '（為本次執行產生）'),
        explicit = tr(' (explicitly selected)', '（明确指定）', '（明確指定）'),
        repeated_run = tr(' (from repeated run)', '（来自重放的运行）', '（來自重播的執行）'),
        resumed_run = tr(' (from resumed run)', '（来自恢复的运行）', '（來自恢復的執行）'),
      }
      lines[#lines + 1] = tr('Reported execution seed: ', '报告的执行种子：', '回報的執行種子：') .. training_data.seed_decimal
        .. (seed_sources[training_data.seed_source] or '')
      if training_data.seed_source == 'resumed_run' then
        lines[#lines + 1] = tr('Resume may restore random state from the checkpoint; the seed alone does not describe it.',
          '续训可能恢复检查点中的随机状态；种子本身不能完整描述该状态。',
          '續訓可能恢復檢查點中的隨機狀態；種子本身不能完整描述該狀態。')
      end
      if training_data.variant_applied == true then
        lines[#lines + 1] = tr('The variant may use a separate saved construction seed.', '变体可能使用另一个已保存的构造种子。', '變體可能使用另一個已儲存的建構種子。')
      end
    end
    if type(training_data) == 'table' and type(training_data.supervision) == 'table' then
      local supervision = training_data.supervision
      local function clean(value)
        if value == nil or value == vim.NIL then return '?' end
        return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 180)
      end
      local function count(value)
        return type(value) == 'number' and value >= 0 and tostring(value) or '?'
      end
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Supervision observed in this run:', '本次运行观察到的监督：', '本次執行觀察到的監督：')
      if supervision.status ~= 'applied' then
        lines[#lines + 1] = tr('Application status: ', '生效状态：', '生效狀態：') .. clean(supervision.status)
      end
      if type(supervision.rules) == 'table' and is_list(supervision.rules) then
        if #supervision.rules == 0 then
          lines[#lines + 1] = tr('No rule observations were reported.', '未报告规则观察结果。', '未回報規則觀察結果。')
        end
        for index, rule in ipairs(supervision.rules) do
          if index > 32 then
            lines[#lines + 1] = tr('Further rules are in the complete report [J].', '其余规则见完整报告 [J]。', '其餘規則見完整報告 [J]。')
            break
          end
          if type(rule) == 'table' then
            lines[#lines + 1] = clean(rule.role) .. ' · ' .. clean(rule.module_path) .. ' · ' .. clean(rule.port)
              .. ' · ' .. clean(rule.mode)
            if type(rule.observation_scope) == 'table' and rule.observation_scope.input_reference_may_be_mutated == true then
              lines[#lines + 1] = tr('  Input was observed after the module call; in-place changes and call side effects are not prevented.',
                '  输入在模块调用后观察；无法阻止原地修改和调用副作用。', '  輸入在模組呼叫後觀察；無法阻止原地修改和呼叫副作用。')
            elseif type(rule.port) == 'string' and rule.port:match('^inputs') then
              lines[#lines + 1] = tr('  Input observation timing is not recorded in this run.', '  此运行未记录输入观察时机。', '  此執行未記錄輸入觀察時機。')
            end
            lines[#lines + 1] = tr('  Observed steps: ', '  观察步数：', '  觀察步數：') .. count(rule.steps_observed)
              .. tr(' · violations / measured elements: ', ' · 违反数 / 检查元素数：', ' · 違反數 / 檢查元素數：')
              .. count(rule.violation_count) .. ' / ' .. count(rule.element_count)
            lines[#lines + 1] = tr('  Unmeasured calls / affected steps: ', '  未测调用数 / 涉及步数：', '  未測呼叫數 / 涉及步數：')
              .. count(rule.unmeasured_calls) .. ' / ' .. count(rule.steps_with_unmeasured_calls)
            if rule.steps_observed == 0 then
              lines[#lines + 1] = tr('  Not observed; this does not mean the rule passed.',
                '  未观察到此规则；不代表规则通过。', '  未觀察到此規則；不代表規則通過。')
            end
            if rule.mode == 'penalty' and type(rule.mean_weighted_penalty) == 'number'
                and rule.mean_weighted_penalty == rule.mean_weighted_penalty
                and math.abs(rule.mean_weighted_penalty) ~= math.huge then
              lines[#lines + 1] = tr('  Mean weighted penalty on observed steps: ', '  已观察步骤的平均加权惩罚：', '  已觀察步驟的平均加權懲罰：')
                .. tostring(rule.mean_weighted_penalty)
            end
            if type(rule.sample_coverage) == 'table' then
              lines[#lines + 1] = tr('  Sample localization: ', '  样本定位：', '  樣本定位：') .. clean(rule.sample_coverage.status)
            end
          end
        end
      else
        lines[#lines + 1] = tr('Rule observations are unavailable.', '规则观察结果不可用。', '規則觀察結果無法取得。')
      end
      lines[#lines + 1] = tr('Only executed marked ports are covered; sample IDs are user-declared and dataset coverage is unknown.',
        '仅覆盖已执行且标记的端口；样本 ID 由用户声明，数据集覆盖率未知。',
        '僅涵蓋已執行且標記的連接埠；樣本 ID 由使用者宣告，資料集涵蓋率未知。')
    end
    if type(training_data) == 'table' and rule_failure then
      local cause = rule_failure
      local function safe(value)
        if value == nil or value == vim.NIL then return '?' end
        return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 180)
      end
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('A required supervision rule stopped this step:', '必需的监督规则阻止了本步：', '必要的監督規則阻止了本步：')
      lines[#lines + 1] = safe(cause.module_path) .. ' · ' .. safe(cause.port)
        .. tr(' · rule ', ' · 规则 ', ' · 規則 ') .. safe(cause.rule_id)
      if type(cause.observation_scope) == 'table' and cause.observation_scope.input_reference_may_be_mutated == true then
        lines[#lines + 1] = tr('The module call had already occurred before its input was checked.',
          '检查输入时，模块调用已经发生。', '檢查輸入時，模組呼叫已經發生。')
      end
      lines[#lines + 1] = tr('Violations / measured: ', '违反数 / 检查数：', '違反數 / 檢查數：')
        .. safe(cause.violation_count) .. ' / ' .. safe(cause.element_count)
      lines[#lines + 1] = tr('Completed steps before the failure: ', '失败前完成步数：', '失敗前完成步數：') .. safe(training_data.completed_steps)
      if training_data.training_mode == 'managed-step' and training_data.managed_backward_started == false
          and training_data.managed_optimizer_step_started == false then
        lines[#lines + 1] = tr('The tool had not started its backward or optimizer update for this step.',
          '工具尚未为本步开始受管反向或优化器更新。', '工具尚未為本步開始受管反向或最佳化器更新。')
      else
        lines[#lines + 1] = tr('Update state is not established by this report.', '本报告未确定更新状态。', '本報告未確定更新狀態。')
      end
      lines[#lines + 1] = tr('User code may already have changed state or had other effects; those are not rolled back.',
        '用户代码可能已经改变状态或产生其他副作用，工具不会回滚。', '使用者程式碼可能已變更狀態或產生其他副作用，工具不會回復。')
    end
    if type(training_data) == 'table' and type(training_data.resources) == 'table' then
      local resources = training_data.resources
      local function number(value)
        return type(value) == 'number' and value >= 0 and tostring(value) or tr('unknown', '未知', '未知')
      end
      lines[#lines + 1] = tr('Memory bytes (allocated / reserved / peak allocated / free / total): ',
        '内存字节（已分配 / 已保留 / 分配峰值 / 空闲 / 总量）：',
        '記憶體位元組（已分配 / 已保留 / 分配峰值 / 可用 / 總量）：')
        .. number(resources.allocated_bytes) .. ' / ' .. number(resources.reserved_bytes) .. ' / '
        .. number(resources.peak_allocated_bytes) .. ' / ' .. number(resources.free_bytes) .. ' / ' .. number(resources.total_bytes)
      if resources.peak_scope == 'process_lifetime_not_reset' then
        lines[#lines + 1] = tr('Peak is since process start; it was not reset for this run.',
          '峰值从进程启动开始统计，未针对本次运行重置。', '峰值從程序啟動開始統計，未針對本次執行重設。')
      end
      if type(resources.measurement_error) == 'string' and resources.measurement_error ~= '' then
        lines[#lines + 1] = tr('Some memory measurements are unavailable; see the complete report.',
          '部分内存指标不可用，详情见完整报告。', '部分記憶體指標無法取得，詳情見完整報告。')
      end
    end
    if type(training_data) == 'table' and type(training_data.optimizer_identity) == 'table' then
      local identity = training_data.optimizer_identity
      local function count(value) return type(value) == 'number' and tostring(value) or '?' end
      local name = type(identity.optimizer_type) == 'string' and vim.fn.strcharpart(identity.optimizer_type:gsub('[\r\n%z\1-\31\127]', ' '), 0, 256) or '?'
      lines[#lines + 1] = tr('Custom optimizer: ', '自定义优化器：', '自訂最佳化器：') .. name
      lines[#lines + 1] = tr('Trainable / included / omitted parameter objects: ', '可训练 / 纳入 / 未纳入的参数对象：', '可訓練 / 納入 / 未納入的參數物件：')
        .. count(identity.parameter_count) .. ' / ' .. count(identity.optimized_parameter_count) .. ' / ' .. count(identity.omitted_trainable_parameter_count)
      lines[#lines + 1] = tr('Coverage does not prove every included parameter was updated.', '纳入优化器不证明每个参数都已更新。', '納入最佳化器不證明每個參數都已更新。')
    end
    if type(training_data) == 'table' and type(training_data.resume_device_comparison) == 'table' then
      local comparison = training_data.resume_device_comparison
      local names = {}
      if type(comparison.compared_fields) == 'table' then
        for _, field in ipairs(comparison.compared_fields) do
          if field == 'device' or field == 'device_backend' or field == 'device_name' then names[#names + 1] = field end
          if #names == 3 then break end
        end
      end
      local fields = table.concat(names, ', ')
      lines[#lines + 1] = tr('Resume device comparison: ', '续训设备对照：', '續訓裝置對照：')
        .. (comparison.status == 'matched_available_fields' and tr('available fields match', '已有字段一致', '既有欄位一致') or tr('unknown', '未知', '未知'))
        .. (fields ~= '' and (' (' .. fields .. ')') or '')
      lines[#lines + 1] = tr('Matching names and visible indexes do not prove the same physical device or environment.',
        '名称和可见索引一致不证明物理设备或环境相同。', '名稱和可見索引一致不證明實體裝置或環境相同。')
    end
    if type(training_data) == 'table' and training_data.resume_batch_binding_evidence == 'legacy_checkpoint_unverified' then
      lines[#lines + 1] = tr('The older checkpoint did not pin input binding; resume used the historical record or automatic binding when missing.',
        '旧检查点未固定输入绑定；续训沿用历史记录，记录缺失时使用自动绑定。',
        '舊檢查點未固定輸入繫結；續訓沿用歷史紀錄，紀錄缺失時使用自動繫結。')
    end
    if type(report.data) == 'table' and type(report.data.code_snapshot) == 'table'
        and report.data.code_snapshot.files == 0 then
      lines[#lines + 1] = tr('No project Python files were captured; installed libraries and data are not in this snapshot.',
        '快照未包含项目 Python 文件；已安装的库和数据不在快照中。', '快照未包含專案 Python 檔案；已安裝的程式庫和資料不在快照中。')
    end
    if report.operation == 'environment_library_probe' and type(report.data) == 'table' and type(report.data.probes) == 'table' then
      local function clean(value)
        if value == nil or value == vim.NIL then return '?' end
        return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 512)
      end
      local function yes_no_unknown(value)
        if value == true then return tr('yes', '是', '是') end
        if value == false then return tr('no', '否', '否') end
        return tr('unknown', '未知', '未知')
      end
      lines[#lines + 1] = tr('Selected Python: ', '所选 Python：', '所選 Python：') .. clean(report.data.python_executable)
      lines[#lines + 1] = tr('Automatically installed / bound: ', '自动安装 / 绑定：', '自動安裝 / 繫結：')
        .. yes_no_unknown(report.data.auto_installed) .. ' / ' .. yes_no_unknown(report.data.auto_bound)
      lines[#lines + 1] = tr('Distribution metadata does not establish the origin of an imported module.',
        '发行包元数据不能证明导入模块的来源。', '發行套件中繼資料無法證明匯入模組的來源。')
      if report.data.import_may_have_executed_code == true then
        lines[#lines + 1] = tr('Import was attempted; initialization code may have run even if import failed.',
          '已尝试导入；即使失败，初始化代码也可能已经运行。', '已嘗試匯入；即使失敗，初始化程式碼也可能已執行。')
      end
      for index, probe in ipairs(report.data.probes) do
        if index > 32 then lines[#lines + 1] = tr('More probes in the full report.', '更多探测结果见完整报告。', '更多探測結果見完整報告。'); break end
        if type(probe) == 'table' then
          lines[#lines + 1] = clean(probe.import_name) .. ' · ' .. clean(probe.status)
          lines[#lines + 1] = tr('  Distribution metadata: ', '  发行包元数据：', '  發行套件中繼資料：') .. clean(probe.distribution_status)
          lines[#lines + 1] = tr('  Import origin: ', '  导入来源：', '  匯入來源：') .. clean(probe.import_origin)
          local adapter = probe.adapter_status == 'implemented' and tr('implemented (scope is operation-specific)', '已实现（范围依操作而定）', '已實作（範圍依操作而定）')
            or probe.adapter_status == 'package-only' and tr('library only; no automatic adapter', '仅库本身；无自动适配', '僅程式庫本身；無自動配接')
            or tr('unknown', '未知', '未知')
          lines[#lines + 1] = tr('  Adapter status: ', '  适配状态：', '  配接狀態：') .. adapter
          if type(probe.failure_reason) == 'string' then
            lines[#lines + 1] = tr('  Import error: ', '  导入错误：', '  匯入錯誤：') .. clean(probe.failure_reason)
          end
        end
      end
    end
    if report.operation == 'environment_devices' and type(report.data) == 'table' then
      local probe = type(report.data.probes) == 'table' and report.data.probes[1] or nil
      local inventory = type(probe) == 'table' and probe.device_inventory or nil
      lines[#lines + 1] = tr('Selected Python: ', '所选 Python：', '所選 Python：') .. tostring(report.data.python_executable or '?')
      lines[#lines + 1] = tr('Imported module origin: ', '导入模块来源：', '匯入模組來源：')
        .. vim.fn.strcharpart(tostring(type(probe) == 'table' and probe.import_origin or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
      lines[#lines + 1] = tr('Device query: ', '设备查询：', '裝置查詢：') .. tostring(type(inventory) == 'table' and inventory.status or 'unknown')
      if type(inventory) == 'table' and type(inventory.devices) == 'table' then
        for index, device in ipairs(inventory.devices) do
          if index > 32 then lines[#lines + 1] = tr('More devices in complete report.', '更多设备见完整报告。', '更多裝置見完整報告。'); break end
          if type(device) == 'table' then
            local function safe(value) return vim.fn.strcharpart(tostring(value or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 256) end
            lines[#lines + 1] = safe(device.id) .. ' · ' .. safe(device.backend) .. ' · ' .. safe(device.name)
          end
        end
      end
      lines[#lines + 1] = tr('Visibility can change; training resolves and checks the selected device again.',
        '设备可见性可能变化；训练时会再次解析并检查所选设备。', '裝置可見性可能變更；訓練時會再次解析並檢查所選裝置。')
    end
    if type(evaluation_data) == 'table' and type(evaluation_data.evaluation) == 'table' then
      local result = evaluation_data.evaluation
      local coverage = type(evaluation_data.coverage) == 'table' and evaluation_data.coverage or {}
      local function plain(value, limit)
        if value == nil or value == vim.NIL then return tr('unknown', '未知', '未知') end
        return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, limit or 160)
      end
      lines[#lines + 1] = tr('Evaluator-reported results:', '评估器报告的结果：', '評估器回報的結果：')
      lines[#lines + 1] = tr('Split / samples reported / target: ', '切分 / 已报告样本数 / 目标：', '切分 / 已回報樣本數 / 目標：')
        .. plain(result.split) .. ' / ' .. plain(result.samples_evaluated) .. ' / ' .. plain(result.sample_limit)
      if type(result.model_device) == 'table' then
        lines[#lines + 1] = tr('Model device requested / resolved: ', '模型设备请求 / 解析结果：', '模型裝置要求 / 解析結果：')
          .. plain(result.model_device.device_requested) .. ' / ' .. plain(result.model_device.device)
          .. tr('; input placement is owned by the evaluator.', '；输入设备由评估函数负责。', '；輸入裝置由評估函式負責。')
      end
      local metrics = type(result.metrics) == 'table' and result.metrics or {}
      local names = {}
      for name, value in pairs(metrics) do
        if type(name) == 'string' and type(value) == 'number' then names[#names + 1] = name end
      end
      table.sort(names)
      if #names == 0 then lines[#lines + 1] = tr('No scalar metrics reported.', '未报告标量指标。', '未回報純量指標。') end
      for index, name in ipairs(names) do
        if index > 16 then lines[#lines + 1] = tr('Further metrics are in the full report.', '更多指标见完整报告。', '更多指標見完整報告。'); break end
        lines[#lines + 1] = '  ' .. plain(name) .. ': ' .. plain(metrics[name])
      end
      local previews = type(result.sample_previews) == 'table' and result.sample_previews or {}
      lines[#lines + 1] = tr('Prediction previews: ', '预测预览：', '預測預覽：') .. plain(previews.state)
        .. tr(' · reported: ', ' · 已报告：', ' · 已回報：') .. plain(previews.reported)
      if type(previews.samples) == 'table' and is_list(previews.samples) and #previews.samples > 0 then
        lines[#lines + 1] = tr('[P] Review reported predictions (may contain sensitive values)',
          '[P] 查看报告的预测（可能包含敏感数据）', '[P] 查看回報的預測（可能包含敏感資料）')
      end
      lines[#lines + 1] = tr('Sample counts and data identity are evaluator/user declarations; they do not prove dataset contents.',
        '样本数和数据身份由评估器或用户声明，不能证明数据集内容。', '樣本數和資料身分由評估器或使用者宣告，不能證明資料集內容。')
      if coverage.data_identity == 'declared_fingerprint_and_inputs' then
        lines[#lines + 1] = tr('A data identity was declared.', '已声明数据身份。', '已宣告資料身分。')
      end
      local provenance = type(evaluation_data.provenance) == 'table' and evaluation_data.provenance or {}
      local comparison = type(provenance.source_snapshot_comparison) == 'table' and provenance.source_snapshot_comparison or {}
      local status = ({ same = tr('same', '相同', '相同'), different = tr('different', '不同', '不同'),
        unknown = tr('unknown', '未知', '未知') })[comparison.status] or tr('unknown', '未知', '未知')
      lines[#lines + 1] = tr('Training / evaluation source snapshots: ', '训练 / 评估源码快照：', '訓練 / 評估原始碼快照：') .. status
      lines[#lines + 1] = tr('A difference may be evaluation-only; data and dependencies are not covered.',
        '差异可能仅来自评估代码；该对照不覆盖数据和依赖。', '差異可能僅來自評估程式碼；該對照不涵蓋資料和依賴。')
    end
    if (report.operation == 'probe' or report.operation == 'inspect' or report.operation == 'layers'
        or (report.operation == 'edit' and type(report.data) == 'table' and report.data.target == 'source'))
        and report.status == 'success' and type(report.data) == 'table' then
      local placement = type(report.data.model_state_placement) == 'table' and report.data.model_state_placement or nil
      if placement and type(placement.groups) == 'table' and is_list(placement.groups) then
        lines[#lines + 1] = report.operation == 'edit'
          and tr('Candidate registered state after validation:', '候选验证后的已注册状态：', '候選驗證後的已註冊狀態：')
          or report.operation == 'probe'
          and tr('Registered state before forward:', '前向前已注册状态：', '前向前已註冊狀態：')
          or tr('Registered model state devices and dtypes:', '已注册模型状态的设备与类型：', '已註冊模型狀態的裝置與型別：')
        for index, group in ipairs(placement.groups) do
          if index > 6 then lines[#lines + 1] = tr('  Further groups in details.', '  更多分组见详情。', '  更多群組見詳情。'); break end
          if type(group) == 'table' then
            local function clean(value)
              return vim.fn.strcharpart(tostring(value or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 100)
            end
            lines[#lines + 1] = '  ' .. clean(group.kind) .. ' · ' .. clean(group.device) .. ' · ' .. clean(group.dtype)
              .. ' · ' .. clean(group.tensors) .. tr(' tensors', ' 个张量', ' 個張量')
          end
        end
        if #placement.groups == 0 then
          lines[#lines + 1] = tr('  No registered state was observed, or its placement could not be read.',
            '  未观察到已注册状态，或无法读取其设备。', '  未觀察到已註冊狀態，或無法讀取其裝置。')
        end
        lines[#lines + 1] = placement.status == 'observed'
          and tr('State only; temporary tensors and external resources are not covered.', '仅覆盖已注册状态；不覆盖临时张量和外部资源。', '僅涵蓋已註冊狀態；不涵蓋臨時張量和外部資源。')
          or tr('Partial state observation; temporary tensors and external resources are not covered.', '状态观察不完整；不覆盖临时张量和外部资源。', '狀態觀察不完整；不涵蓋臨時張量和外部資源。')
      else
        lines[#lines + 1] = tr('Registered model state devices and dtypes: not reported.',
          '已注册模型状态的设备与类型：未报告。', '已註冊模型狀態的裝置與型別：未回報。')
      end
      if report.operation == 'edit' and type(report.data.source_validation) == 'table' then
        local comparison = report.data.source_validation.placement_group_comparison
        local labels = {
          same = tr('same aggregate groups', '设备与类型汇总分组相同', '裝置與型別彙總群組相同'),
          different = tr('aggregate groups differ', '设备或类型汇总分组不同', '裝置或型別彙總群組不同'),
          unknown = tr('unknown', '未知', '未知'),
        }
        lines[#lines + 1] = tr('Candidate / reconstructed state: ', '候选 / 重建状态对照：', '候選 / 重建狀態對照：')
          .. (type(comparison) == 'table' and labels[comparison.status] or labels.unknown)
        lines[#lines + 1] = tr('Group equality does not prove per-tensor identity or equal values.',
          '汇总相同不能证明逐个张量身份或数值相同。', '彙總相同不能證明逐個張量身分或數值相同。')
        lines[#lines + 1] = tr('The committed source was reconstructed separately; inspect its reported state placement in [J], if available.',
          '提交后的源码已独立重建；如有状态设备信息，可在 [J] 查看。', '提交後的原始碼已獨立重建；如有狀態裝置資訊，可在 [J] 查看。')
      end
      if report.operation == 'probe' and report.data.forward_execution == 'executed' then
        local before = type(report.data.parameters) == 'number' and tostring(report.data.parameters)
          or tr('unknown (may be uninitialized)', '未知（可能尚未初始化）', '未知（可能尚未初始化）')
        lines[#lines + 1] = tr('Registered parameters before forward: ', '前向前已注册参数量：', '前向前已註冊參數量：') .. before
        local after = type(report.data.model_state_after_forward) == 'table' and report.data.model_state_after_forward or nil
        if after then
          local count = type(after.parameters) == 'number' and tostring(after.parameters)
            or tr('unknown', '未知', '未知')
          lines[#lines + 1] = tr('Registered parameters after forward: ', '前向后已注册参数量：', '前向後已註冊參數量：') .. count
          if type(after.placement) == 'table' and type(after.placement.groups) == 'table'
              and placement and not vim.deep_equal(after.placement.groups, placement.groups) then
            lines[#lines + 1] = tr('Registered state placement changed during forward; see full report.',
              '前向期间已注册状态的设备或类型分组发生变化；详情见完整报告。',
              '前向期間已註冊狀態的裝置或型別群組發生變化；詳情見完整報告。')
          end
        else
          lines[#lines + 1] = tr('Post-forward registered state was not reported.', '未报告前向后的已注册状态。', '未回報前向後的已註冊狀態。')
        end
      end
    end
    if report.operation == 'probe' and type(report.data) == 'table' then
      if report.data.forward_execution == 'reused'
          or (type(report.data.evidence_cache) == 'table' and report.data.evidence_cache.status == 'reused') then
        lines[#lines + 1] = tr('Previous forward evidence was reused; this operation did not execute a new forward.',
          '本次复用了先前的前向证据，没有执行新的前向。', '本次重用了先前的前向證據，沒有執行新的前向。')
        lines[#lines + 1] = tr('External files, environment variables and other hidden state may have changed. Use [p] on the workspace to request a new forward.',
          '外部文件、环境变量及其他隐藏状态可能已变化。返回工作区按 [p] 请求新前向。',
          '外部檔案、環境變數及其他隱藏狀態可能已變更。返回工作區按 [p] 要求新前向。')
      elseif report.data.forward_execution ~= 'executed' and report.data.forward_execution ~= 'failed' then
        lines[#lines + 1] = tr('The CLI did not report whether this forward was newly executed.',
          'CLI 未报告本次是否执行了新前向。', 'CLI 未回報本次是否執行了新前向。')
      end
      local cache = type(report.data.evidence_cache) == 'table' and report.data.evidence_cache or {}
      lines[#lines + 1] = tr('Evidence cache state / reason: ', '证据缓存状态 / 原因：', '證據快取狀態 / 原因：')
        .. tostring(cache.status or tr('unknown (legacy report)', '未知（旧报告）', '未知（舊報告）'))
        .. ' / ' .. (type(cache.reason) == 'string' and vim.fn.strcharpart(cache.reason:gsub('[\r\n%z\1-\31\127]', ' '), 0, 240)
          or tr('none reported', '未报告', '未回報'))
      if type(cache.invalidated) == 'table' and #cache.invalidated > 0 then
        lines[#lines + 1] = tr('Cache invalidation reasons: ', '缓存失效原因：', '快取失效原因：') .. table.concat(cache.invalidated, ', ')
      end
      if cache.reason == 'forward input content cannot be completely fingerprinted' then
        lines[#lines + 1] = tr('Input content could not be fully checked, so this evidence will not be reused.',
          '输入内容无法完整核对，因此本次证据不会被复用。', '輸入內容無法完整核對，因此本次證據不會被重用。')
      elseif cache.reason == 'ambient RNG state is not fixed for this probe' then
        lines[#lines + 1] = tr('This forward uses the runtime RNG state; its evidence will not be reused.',
          '本次前向使用运行时随机状态，证据不会被复用。', '本次前向使用執行時隨機狀態，證據不會被重用。')
      end
      local construction_seed = report.data.seed
      local seed_description
      if construction_seed == vim.NIL and report.data.seed_policy == 'runtime' then
        seed_description = tr('runtime state (tool did not set a seed)', '运行时状态（工具未设置种子）', '執行時狀態（工具未設定種子）')
      elseif type(construction_seed) == 'number' then
        seed_description = math.abs(construction_seed) > 9007199254740991
          and tr('too large to display exactly here', '数值过大，无法在此精确显示', '數值過大，無法在此精確顯示')
          or tostring(construction_seed)
      else
        seed_description = tr('unknown', '未知', '未知')
      end
      local randomness = type(report.data.randomness) == 'table' and report.data.randomness or nil
      if randomness then
        local construction = randomness.construction_seed_decimal
        local execution = randomness.execution_seed_decimal
        local function decimal(value)
          return type(value) == 'string' and #value <= 20 and value:match('^%d+$') and value or nil
        end
        lines[#lines + 1] = tr('Construction seed: ', '构造种子：', '建構種子：')
          .. (decimal(construction) or tr('runtime state / unknown', '运行时状态 / 未知', '執行時狀態 / 未知'))
        if randomness.forward_rng_policy == 'reset_after_variant' then
          lines[#lines + 1] = tr('Seed reset after variant reconstruction: ', '变体重建后重置的种子：', '變體重建後重設的種子：')
            .. (decimal(execution) or tr('unknown', '未知', '未知'))
        elseif randomness.forward_rng_policy == 'construction_stream' then
          lines[#lines + 1] = tr('Forward continues the random stream after construction; the input factory may also change it.',
            '前向继续使用构造后的随机状态；输入工厂也可能改变该状态。',
            '前向繼續使用建構後的隨機狀態；輸入工廠也可能改變該狀態。')
        end
      else
        lines[#lines + 1] = (report.data.variant_applied == false
          and tr('Model construction seed: ', '模型构造种子：', '模型建構種子：')
          or tr('Reported seed (variant initialization may differ): ', '报告的种子（变体初始化可能不同）：', '回報的種子（變體初始化可能不同）：')) .. seed_description
      end
      lines[#lines + 1] = tr('User code and other random libraries may use their own state.',
        '用户代码和其他随机库可能使用各自的状态。', '使用者程式碼和其他隨機函式庫可能使用各自的狀態。')
      local observation = type(report.data.data_observation) == 'table' and report.data.data_observation or {}
      local sampling = type(observation.sampling) == 'table' and observation.sampling or {}
      if type(sampling.seed_decimal) == 'string' and #sampling.seed_decimal <= 20
          and sampling.seed_decimal:match('^%d+$') then
        lines[#lines + 1] = tr('Dataset sampling seed: ', '数据集采样种子：', '資料集取樣種子：') .. sampling.seed_decimal
          .. (sampling.seed_source == 'generated_for_sampling'
            and tr(' (generated for this observation)', '（为本次观察生成）', '（為本次觀察產生）') or '')
        lines[#lines + 1] = tr('Sampling does not fix dataset content, factory state or external randomness.',
          '采样种子不固定数据内容、工厂状态或外部随机性。', '取樣種子不固定資料內容、工廠狀態或外部隨機性。')
      end
      local runtime = type(report.data.runtime) == 'table' and report.data.runtime or {}
      if type(runtime.probe_device) == 'table' then
        local selected = runtime.probe_device
        local function clean_device(value)
          return type(value) == 'string' and vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, 128) or '?'
        end
        lines[#lines + 1] = tr('Requested / resolved model device: ', '请求 / 解析的模型设备：', '要求 / 解析的模型裝置：')
          .. clean_device(selected.device_requested) .. ' / ' .. clean_device(selected.device)
        lines[#lines + 1] = tr('Input is not moved automatically; registered state is shown above.',
          '输入不会自动迁移；已注册状态见上方。', '輸入不會自動遷移；已註冊狀態見上方。')
      end
      lines[#lines + 1] = tr('Actual Python: ', '实际 Python：', '實際 Python：') .. tostring(runtime.python_executable or '?')
      lines[#lines + 1] = tr('Python / PyTorch: ', 'Python / PyTorch：', 'Python / PyTorch：')
        .. tostring(runtime.python_version or '?') .. ' / ' .. tostring(runtime.pytorch_version or '?')
      local function directory(value)
        if type(value) ~= 'string' then return tr('unknown', '未知', '未知') end
        return vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
      end
      lines[#lines + 1] = tr('Working directory before / after model / after probe: ',
        '模型前 / 模型后 / 观察后工作目录：', '模型前 / 模型後 / 觀察後工作目錄：')
        .. directory(runtime.working_directory_before_model) .. ' / '
        .. directory(runtime.working_directory_after_model) .. ' / ' .. directory(runtime.working_directory_after_probe)
      lines[#lines + 1] = tr('A project can change its own directory between these observations.',
        '项目代码可能在这些观察点之间改变工作目录。', '專案程式碼可能在這些觀察點之間變更工作目錄。')
      local provenance = type(report.data.run_provenance) == 'table' and report.data.run_provenance or nil
      local function provenance_text(value, limit)
        if type(value) == 'number' and value == value and value ~= math.huge and value ~= -math.huge then return tostring(value) end
        if type(value) ~= 'string' then return tr('unknown', '未知', '未知') end
        return vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, limit or 160)
      end
      if provenance then
        lines[#lines + 1] = tr('Provenance execution status: ', '来源执行状态：', '來源執行狀態：') .. provenance_text(provenance.execution_status)
        local input = type(provenance.input) == 'table' and provenance.input or {}
        local model_identity = type(provenance.model) == 'table' and provenance.model or {}
        local output = type(provenance.output) == 'table' and provenance.output or {}
        lines[#lines + 1] = tr('Probe / forward ID: ', 'Probe / 前向 ID：', 'Probe / 前向 ID：')
          .. provenance_text(report.data.probe_id) .. ' / ' .. provenance_text(report.data.forward_id)
        lines[#lines + 1] = tr('Input source / declared batch digest: ', '输入来源 / 声明批次摘要：', '輸入來源 / 宣告批次摘要：')
          .. provenance_text(input.source_kind) .. ' / ' .. provenance_text(input.declared_batch_sha256)
        local observation = type(input.data_observation) == 'table' and input.data_observation or {}
        local sampling = type(observation.sampling) == 'table' and observation.sampling or {}
        lines[#lines + 1] = tr('Dataset declaration digest / sampled count: ', '数据集声明摘要 / 样本数：', '資料集宣告摘要 / 樣本數：')
          .. provenance_text(observation.dataset_fingerprint_sha256) .. ' / '
          .. provenance_text(sampling.actual_samples)
        lines[#lines + 1] = tr('Reported sample ID count: ', '报告的样本 ID 数量：', '回報的樣本 ID 數量：')
          .. provenance_text(sampling.sample_count)
        lines[#lines + 1] = tr('Adapter / source / sample-ID digests: ', '适配器 / 来源 / 样本 ID 摘要：', '配接器 / 來源 / 樣本 ID 摘要：')
          .. provenance_text(observation.adapter) .. ' / ' .. provenance_text(observation.source_sha256)
          .. ' / ' .. provenance_text(sampling.sample_ids_sha256)
        local input_content = type(input.content) == 'table' and input.content or {}
        lines[#lines + 1] = tr('Actual input content status / digest: ', '实际输入内容状态 / 摘要：', '實際輸入內容狀態 / 摘要：')
          .. provenance_text(input_content.status) .. ' / ' .. provenance_text(input_content.digest)
        local weight = type(model_identity.weights_before_forward) == 'table' and model_identity.weights_before_forward or {}
        local after_weight = type(model_identity.weights_after_forward) == 'table' and model_identity.weights_after_forward or {}
        lines[#lines + 1] = tr('Registered weight digest before / after: ', '已注册权重摘要（前 / 后）：', '已註冊權重摘要（前 / 後）：')
          .. provenance_text(weight.digest) .. ' / ' .. provenance_text(after_weight.digest)
        lines[#lines + 1] = tr('Declared model / implementation source digests: ', '声明模型 / 实现源码摘要：', '宣告模型 / 實作原始碼摘要：')
          .. provenance_text(model_identity.declared_model_sha256) .. ' / '
          .. provenance_text(type(model_identity.implementation) == 'table' and model_identity.implementation.source_sha256 or nil)
        local environment = type(provenance.environment) == 'table' and provenance.environment or {}
        lines[#lines + 1] = tr('Environment fingerprint status / digest: ', '环境指纹状态 / 摘要：', '環境指紋狀態 / 摘要：')
          .. provenance_text(environment.status) .. ' / ' .. provenance_text(environment.identity_sha256)
        local randomness = type(provenance.randomness) == 'table' and provenance.randomness or {}
        lines[#lines + 1] = tr('Requested / construction seed and RNG policy: ', '请求 / 构造种子及随机策略：', '要求 / 建構種子及隨機策略：')
          .. provenance_text(randomness.requested_seed_decimal) .. ' / ' .. provenance_text(randomness.construction_seed_decimal)
          .. ' · ' .. provenance_text(randomness.forward_rng_policy)
        local path = type(provenance.path_evidence) == 'table' and provenance.path_evidence or {}
        lines[#lines + 1] = tr('Path evidence status / observed paths: ', '路径证据状态 / 已观察路径：', '路徑證據狀態 / 已觀察路徑：')
          .. provenance_text(path.status) .. ' / ' .. provenance_text(type(path.observed_paths) == 'table' and table.concat(path.observed_paths, ', ') or nil, 240)
        lines[#lines + 1] = tr('Output structure / value retention: ', '输出结构 / 数值保留：', '輸出結構 / 數值保留：')
          .. provenance_text(output.status) .. ' / ' .. (output.values_fingerprinted == true and tr('fingerprinted', '已摘要', '已摘要') or tr('not fingerprinted', '未记录数值摘要', '未記錄數值摘要'))
      else
        lines[#lines + 1] = tr('Detailed run provenance is absent in this report; weights, environment and exact identities remain unknown.',
          '此报告没有详细执行来源字段；权重、环境和精确身份保持未知。', '此報告沒有詳細執行來源欄位；權重、環境和精確身分維持未知。')
      end
      local historical_provenance = type(report.data.historical_run_provenance) == 'table' and report.data.historical_run_provenance or nil
      if historical_provenance then
        lines[#lines + 1] = tr('Historical cached execution status: ', '缓存历史执行状态：', '快取歷史執行狀態：')
          .. provenance_text(historical_provenance.execution_status)
      end
      local sources = type(report.data.input_sources) == 'table' and report.data.input_sources or {}
      local input_source = type(sources.batch) == 'table' and sources.batch.kind or nil
      lines[#lines + 1] = tr('Input selection source: ', '输入选择来源：', '輸入選擇來源：')
        .. (type(input_source) == 'string' and vim.fn.strcharpart(input_source:gsub('[\r\n%z\1-\31\127]', ' '), 0, 120)
          or tr('unknown', '未知', '未知'))
      local content = type(report.data.batch_content) == 'table' and report.data.batch_content or {}
      lines[#lines + 1] = tr('Forward-input fingerprint: ', '前向输入指纹：', '前向輸入指紋：')
        .. (content.status == 'available' and tr('available', '可用', '可用') or tr('unknown or unavailable', '未知或不可用', '未知或無法使用'))
      lines[#lines + 1] = tr('The fingerprint covers forward arguments, not targets or complete data identity.',
        '该指纹覆盖前向参数，不包含目标或完整数据身份。', '該指紋涵蓋前向參數，不包含目標或完整資料身分。')
      if report.data.inputs ~= nil and report.data.inputs ~= vim.NIL then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('Input metadata (no tensor or scalar values):', '输入元数据（不显示张量或标量值）：', '輸入中繼資料（不顯示張量或純量值）：')
        local input_lines, omitted = tensor_tree_summary(report.data.inputs, 'input')
        vim.list_extend(lines, input_lines)
        if omitted then lines[#lines + 1] = tr('Input summary truncated; use J for the complete report.',
          '输入摘要已截断；按 J 查看完整报告。', '輸入摘要已截斷；按 J 查看完整報告。') end
      end
      if report.status == 'success' and report.data.outputs ~= nil and report.data.outputs ~= vim.NIL then
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('Output metadata (no tensor values):', '输出元数据（不显示张量值）：', '輸出中繼資料（不顯示張量值）：')
        local output_lines, omitted = tensor_tree_summary(report.data.outputs, 'output')
        vim.list_extend(lines, output_lines)
        if omitted then lines[#lines + 1] = tr('Output summary truncated; use J for the complete report.',
          '输出摘要已截断；按 J 查看完整报告。', '輸出摘要已截斷；按 J 查看完整報告。') end
        lines[#lines + 1] = tr('Only this input and recorded calls are covered; after closing, use v for modules or G for recorded tensor links.',
          '仅覆盖此输入和记录到的调用；关闭后按 v 浏览模块或按 G 查看张量连接。', '僅涵蓋此輸入和記錄到的呼叫；關閉後按 v 瀏覽模組或按 G 查看張量連結。')
      end
    end
    if report.operation == 'probe' and type(report.data) == 'table'
        and type(report.data.selected_path) == 'string' and report.data.selected_path ~= 'model'
        and type(report.data.selected_calls_observed) == 'number'
        and type(report.data.selected_trace_truncated) == 'boolean' then
      local selected = vim.fn.strcharpart(report.data.selected_path:gsub('[\r\n%z\1-\31\127]', ' '), 0, 512)
      lines[#lines + 1] = tr('Selected subtree calls observed: ', '所选子树观察到的调用：', '所選子樹觀察到的呼叫：')
        .. tostring(report.data.selected_calls_observed) .. ' · ' .. selected
      lines[#lines + 1] = report.data.selected_trace_truncated
        and tr('Selected subtree trace was truncated.', '所选子树的调用记录已截断。', '所選子樹的呼叫紀錄已截斷。')
        or tr('Selected subtree stayed within the trace limit; this report may apply a call filter and the full-model trace may still be truncated.',
          '所选子树未超过记录上限；本报告可能按调用筛选，全模型记录仍可能截断。', '所選子樹未超過紀錄上限；本報告可能依呼叫篩選，全模型紀錄仍可能截斷。')
    end
    if report.operation == 'probe' and type(report.data) == 'table' and type(report.data.local_probe_reports) == 'table' then
      lines[#lines + 1] = tr('Local replay results (not a full-model or training guarantee):', '局部重放结果（不代表全模型或训练通过）：', '局部重播結果（不代表全模型或訓練通過）：')
      for _, item in ipairs(report.data.local_probe_reports) do
        if type(item) == 'table' then
          lines[#lines + 1] = tostring(item.module_path or '?') .. ' · ' .. tostring(item.invocation_index or '?') .. ' · ' .. tostring(item.status or '?')
        end
      end
      if report.data.local_probe_reports_truncated == true then
        lines[#lines + 1] = tr('Local replay results were truncated.', '局部重放结果已截断。', '局部重播結果已截斷。')
      end
    end
    if report.operation == 'semantic_supervise' and type(report.data) == 'table'
        and type(report.data.marks) == 'table' and is_list(report.data.marks)
        and (report.data.committed == false or type(report.data.bundle_json) == 'string') then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Supervision bundle contents:', '监督声明内容：', '監督宣告內容：')
      for index, mark in ipairs(report.data.marks) do
        if index > 32 then
          lines[#lines + 1] = tr('Additional marks are in the full report [J].', '其余标记见完整报告 [J]。', '其餘標記見完整報告 [J]。'); break
        end
        if type(mark) == 'table' then
          local function clean(value) return vim.fn.strcharpart(tostring(value or '?'):gsub('[%c]', ' '), 0, 160) end
          lines[#lines + 1] = clean(mark.role) .. ' · ' .. clean(mark.module_path) .. ' · ' .. clean(mark.port)
            .. tr(' · rules: ', ' · 规则数：', ' · 規則數：') .. clean(mark.rule_count)
          lines[#lines + 1] = '  ' .. clean(mark.meaning)
          if type(mark.rules) == 'table' and is_list(mark.rules) then
            for rule_index, rule in ipairs(mark.rules) do
              if rule_index > 8 then
                lines[#lines + 1] = tr('  Additional rules are in the full report [J].', '  其余规则见完整报告 [J]。', '  其餘規則見完整報告 [J]。'); break
              end
              if type(rule) == 'table' then
                local details = { clean(rule.kind), clean(rule.mode) }
                for _, key in ipairs({ 'min', 'max', 'weight', 'target_path', 'axis' }) do
                  if rule[key] ~= nil and rule[key] ~= vim.NIL then details[#details + 1] = key .. '=' .. clean(rule[key]) end
                end
                if type(rule.plugin) == 'table' then details[#details + 1] = clean(rule.plugin.entrypoint) end
                lines[#lines + 1] = '  · ' .. table.concat(details, ' · ')
              end
            end
          end
        end
      end
      lines[#lines + 1] = tr('Imported marks require a new forward and manual rebind.',
        '导入的标记需要重新执行前向并手动绑定。', '匯入的標記需要重新執行前向並手動繫結。')
    end
    if report.operation == 'semantic_supervise' and type(report.data) == 'table'
        and type(report.data.rules) == 'table' and is_list(report.data.rules) then
      local rules = report.data.rules
      local modes = {
        observe = tr('observe', '观察', '觀察'),
        require = tr('stop managed update on violation', '违反时阻止受管更新', '違反時阻止受管更新'),
        penalty = tr('add penalty to enabled training loss', '启用时将惩罚加入训练损失', '啟用時將懲罰加入訓練損失'),
      }
      local function clean(value)
        return vim.fn.strcharpart(tostring(value or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 180)
      end
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Rules selected for review: ', '待查看的规则：', '待檢視的規則：') .. tostring(#rules)
      lines[#lines + 1] = tr('Listed rules do not prove their bindings are current or that they will pass.',
        '规则列表不能证明绑定仍然有效，也不能证明规则会通过。', '規則清單不能證明繫結仍然有效，也不能證明規則會通過。')
      lines[#lines + 1] = tr('Mark and preview device and seed are observations, not training settings. Check the training environment separately.',
        '标记和预览时的设备与种子只是观察条件，不会成为训练设置；请另行核对训练环境。',
        '標記和預覽時的裝置與種子只是觀察條件，不會成為訓練設定；請另行核對訓練環境。')
      for index, rule in ipairs(rules) do
        if index > 32 then
          lines[#lines + 1] = tr('Further rules are in the complete report [J].', '其余规则请查看完整报告 [J]。', '其餘規則請查看完整報告 [J]。')
          break
        end
        if type(rule) == 'table' then
          lines[#lines + 1] = clean(rule.id) .. ' · ' .. clean(rule.mark_role) .. ' · ' .. clean(rule.module_path) .. ' · ' .. clean(rule.port)
          if type(rule.port) == 'string' and rule.port:match('^inputs') then
            lines[#lines + 1] = tr('  Check input observation timing in the preview or run report.',
              '  请在预览或运行报告中查看输入的观察时机。', '  請在預覽或執行報告中查看輸入的觀察時機。')
          end
          lines[#lines + 1] = '  ' .. clean(rule.kind) .. ' · ' .. (modes[rule.mode] or clean(rule.mode))
          local details = {}
          local fields = {
            { 'min', tr('min', '下界', '下界') }, { 'max', tr('max', '上界', '上界') },
            { 'weight', tr('weight', '权重', '權重') }, { 'target_path', tr('target', '目标', '目標') },
            { 'axis', tr('axis', '维度', '維度') },
          }
          for _, field in ipairs(fields) do
            local value = rule[field[1]]
            if value ~= nil and value ~= vim.NIL then details[#details + 1] = field[2] .. ': ' .. clean(value) end
          end
          if type(rule.plugin) == 'table' and type(rule.plugin.entrypoint) == 'string' then
            details[#details + 1] = tr('callable', '函数', '函式') .. ': ' .. clean(rule.plugin.entrypoint)
            local source = rule.plugin.source
            if type(source) == 'table' and type(source.source_file) == 'string' then
              local environment = vim.startswith(source.source_file, '@environment:')
              details[#details + 1] = tr('source', '来源', '來源') .. ': '
                .. (environment and tr('Python import path', 'Python 导入路径', 'Python 匯入路徑') or tr('project file', '项目文件', '專案檔案'))
            end
            if type(rule.plugin.params) == 'table' then
              details[#details + 1] = tr('parameter count', '参数数量', '參數數量') .. ': ' .. tostring(vim.tbl_count(rule.plugin.params))
            end
          end
          if #details > 0 then lines[#lines + 1] = '  ' .. table.concat(details, ' · ') end
        end
      end
      if #rules == 0 then
        lines[#lines + 1] = tr('No rules are configured.', '尚未配置规则。', '尚未設定規則。')
      end
    end
    if report.operation == 'semantic_supervise' and type(report.data) == 'table'
        and type(report.data.results) == 'table' and is_list(report.data.results) then
      local preview = report.data
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Supervision preview:', '监督预览：', '監督預覽：')
      local localization = type(preview.sample_localization) == 'table' and preview.sample_localization or nil
      if localization then
        local complete = type(localization.rules) == 'table' and is_list(localization.rules) and #localization.rules or 0
        local partial = type(localization.partial_rules) == 'table' and is_list(localization.partial_rules) and #localization.partial_rules or nil
        if partial then
          lines[#lines + 1] = tr('Sample-ID localization: rules with all recorded calls / only some calls: ',
            '样本 ID 定位：已记录调用全部可定位 / 仅部分可定位的规则数：',
            '樣本 ID 定位：已記錄呼叫全部可定位 / 僅部分可定位的規則數：') .. tostring(complete) .. ' / ' .. tostring(partial)
          lines[#lines + 1] = tr('IDs are user-declared; this does not establish dataset coverage.',
            'ID 由用户声明；这不代表数据集覆盖率。', 'ID 由使用者宣告；這不代表資料集涵蓋率。')
        end
      end
      local preview_seed = tr('unknown', '未知', '未知')
      if preview.seed == vim.NIL and preview.seed_policy == 'runtime' then
        preview_seed = tr('runtime state', '运行时状态', '執行時狀態')
      elseif type(preview.seed) == 'number' then
        preview_seed = math.abs(preview.seed) > 9007199254740991
          and tr('too large to display exactly', '数值过大，无法精确显示', '數值過大，無法精確顯示')
          or tostring(preview.seed)
      end
      lines[#lines + 1] = tr('Reported seed (variant initialization may differ): ',
        '报告的种子（变体初始化可能不同）：', '回報的種子（變體初始化可能不同）：') .. preview_seed
      if type(preview.model_device) == 'table' then
        local function clean(value)
          return type(value) == 'string' and vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, 128) or '?'
        end
        lines[#lines + 1] = tr('Requested / resolved model device: ', '请求 / 解析的模型设备：', '要求 / 解析的模型裝置：')
          .. clean(preview.model_device.device_requested) .. ' / ' .. clean(preview.model_device.device)
          .. tr('; input is not moved automatically.', '；输入不会自动迁移。', '；輸入不會自動遷移。')
      end
      lines[#lines + 1] = tr('Only observed paths are covered. The tool did not perform an optimizer update.',
        '仅覆盖本次观察到的路径；工具没有执行优化器更新。', '僅涵蓋本次觀察到的路徑；工具沒有執行最佳化器更新。')
      lines[#lines + 1] = tr('This device and seed are not applied to training; training uses its own settings.',
        '本次设备和种子不会应用到训练；训练使用自己的设置。', '本次裝置和種子不會套用到訓練；訓練使用自己的設定。')
      if preview.execution_mode == 'eval' and preview.gradients_enabled == false then
        lines[#lines + 1] = tr('This forward uses eval mode without gradients; training behavior can differ.',
          '本次前向使用 eval 和无梯度模式；训练时行为可能不同。', '本次前向使用 eval 和無梯度模式；訓練時行為可能不同。')
      elseif preview.status == 'observed-runtime' then
        lines[#lines + 1] = tr('The CLI did not report the preview mode; training behavior may differ.',
          'CLI 未报告预览模式；训练时行为可能不同。', 'CLI 未回報預覽模式；訓練時行為可能不同。')
      end
      lines[#lines + 1] = tr('User code may have side effects; they are not rolled back.',
        '用户代码可能产生副作用，工具不会回滚。', '使用者程式碼可能產生副作用，工具不會回復。')
      if preview.status == 'no_rules' then
        lines[#lines + 1] = tr('No rules; no forward was run.', '没有规则；未运行前向。', '沒有規則；未執行前向。')
      elseif preview.status == 'stale' then
        lines[#lines + 1] = tr('All bindings are stale or unsupported; no forward was run.',
          '所有绑定均已过期或不受支持；未运行前向。', '所有繫結均已過期或不受支援；未執行前向。')
      end
      for index, result in ipairs(preview.results) do
        if index > 32 then
          lines[#lines + 1] = tr('Further rule results are in the complete report.', '更多规则结果请查看完整报告。', '更多規則結果請查看完整報告。')
          break
        end
        if type(result) == 'table' then
          local function display(value, limit)
            return vim.fn.strcharpart(tostring(value or '?'), 0, limit or 200):gsub('[\r\n%z\1-\31\127]', ' ')
          end
          local statuses = {
            observed = tr('observed', '已观察', '已觀察'),
            observed_violation = tr('violation observed', '观察到违反', '觀察到違反'),
            would_reject = tr('would stop the managed update for this input', '此输入将阻止受管更新', '此輸入將阻止受管更新'),
            passed = tr('passed for this input', '此输入通过', '此輸入通過'),
            penalty_preview_only = tr('penalty preview only; not applied to loss', '仅预览惩罚；未加入损失', '僅預覽懲罰；未加入損失'),
            stale = tr('binding stale', '绑定已过期', '繫結已過期'),
            unsupported = tr('unsupported', '不受支持', '不受支援'),
            unobserved = tr('not observed in this forward', '本次前向未观察到', '本次前向未觀察到'),
            partial = tr('partial; outcome unknown', '证据不完整，结果未知', '證據不完整，結果未知'),
          }
          lines[#lines + 1] = display(result.role) .. ' · ' .. display(result.module_path)
            .. ' · ' .. display(result.port) .. ' · ' .. (statuses[result.status] or display(result.status))
          lines[#lines + 1] = tr('  Rule / kind / mode: ', '  规则 / 类型 / 模式：', '  規則 / 類型 / 模式：')
            .. display(result.rule_id) .. ' / ' .. display(result.kind) .. ' / ' .. display(result.mode)
          if type(result.observation_scope) == 'table' and result.observation_scope.input_reference_may_be_mutated == true then
            lines[#lines + 1] = tr('  Input was inspected after the module call; in-place changes and call side effects are not prevented.',
              '  输入在模块调用后检查；无法阻止原地修改和调用副作用。', '  輸入在模組呼叫後檢查；無法阻止原地修改和呼叫副作用。')
          elseif type(result.port) == 'string' and result.port:match('^inputs') then
            lines[#lines + 1] = tr('  Input observation timing was not reported.', '  未报告输入观察时机。', '  未回報輸入觀察時機。')
          end
          if result.reason and result.reason ~= vim.NIL then
            lines[#lines + 1] = tr('  Reason: ', '  原因：', '  原因：') .. display(result.reason, 1024)
          end
          if type(result.observations) == 'table' and is_list(result.observations) then
            local shown, skipped, seen = 0, 0, {}
            for _, observation in ipairs(result.observations) do
              if type(observation) == 'table' and observation.status == 'unsupported'
                  and type(observation.reason) == 'string' and observation.reason ~= '' then
                local reason = display(observation.reason, 512)
                if not seen[reason] and reason ~= result.reason then
                  seen[reason] = true
                  if shown < 3 then
                    lines[#lines + 1] = tr('  Unmeasured call: ', '  未测调用：', '  未測呼叫：') .. reason
                    shown = shown + 1
                  else
                    skipped = skipped + 1
                  end
                end
              end
            end
            if skipped > 0 then
              lines[#lines + 1] = tr('  More reasons are in the complete report [J].',
                '  更多原因见完整报告 [J]。', '  更多原因見完整報告 [J]。')
            end
          end
          if type(result.violation_count) == 'number' and type(result.element_count) == 'number' then
            lines[#lines + 1] = tr('  Violations / measured: ', '  违反数 / 检查数：', '  違反數 / 檢查數：')
              .. tostring(result.violation_count) .. ' / ' .. tostring(result.element_count)
          end
          if result.observations_truncated == true then
            lines[#lines + 1] = tr('  Some invocations were omitted; this is partial evidence.',
              '  部分调用未记录；这只是局部证据。', '  部分呼叫未記錄；這只是局部證據。')
          end
          if result.status == 'penalty_preview_only' and type(result.observations) == 'table' and is_list(result.observations) then
            local count = 0
            for _, observation in ipairs(result.observations) do
              local value = type(observation) == 'table' and observation.weighted_penalty_preview
              if type(value) == 'number' and value == value and value ~= math.huge and value ~= -math.huge then
                count = count + 1
                if count <= 4 then
                  lines[#lines + 1] = tr('  Weighted penalty for call ', '  调用的加权惩罚 ', '  呼叫的加權懲罰 ')
                    .. display(observation.invocation_id, 80) .. ': ' .. tostring(value)
                end
              end
            end
            if count > 4 then lines[#lines + 1] = tr('  Further values are in the full report.', '  更多数值请查看完整报告。', '  更多數值請查看完整報告。') end
          end
        end
      end
    end
    if report.operation == 'runs_compare' and type(report.data) == 'table'
        and type(report.data.dimensions) == 'table' and is_list(report.data.dimensions) then
      local comparison = report.data
      local names = {
        inputs = tr('Configuration', '配置', '設定'),
        source_code = tr('Recorded source', '记录的源码', '記錄的原始碼'),
        data = tr('Data content', '数据内容', '資料內容'),
        optimizer_factory = tr('Custom optimizer declaration', '自定义优化器声明', '自訂最佳化器宣告'),
        supervision = tr('Supervision declaration', '监督配置声明', '監督設定宣告'),
        samples = tr('Sample identity', '样本身份', '樣本身分'),
        budget = tr('Training budget', '训练预算', '訓練預算'),
        runtime_paths = tr('Declared runtime paths', '声明的运行时路径', '宣告的執行時路徑'),
        requested_device = tr('Requested device', '请求的设备', '要求的裝置'),
        runtime_device = tr('Observed device labels', '观察到的设备名称', '觀察到的裝置名稱'),
        weights = tr('Checkpoint identity', '检查点身份', '檢查點身分'),
        metrics = tr('Reported metrics', '报告的指标', '回報的指標'),
        training_mean_metrics = tr('Training mean metrics', '训练平均指标', '訓練平均指標'),
        user_reported_last_metrics = tr('User-reported last-step metrics', '用户报告的最后一步指标', '使用者回報的最後一步指標'),
        user_loop_interface = tr('User loop signature', '用户循环签名', '使用者迴圈簽名'),
        source_snapshot = tr('Source snapshot identity', '源码快照身份', '原始碼快照身分'),
      }
      local statuses = { same = tr('same', '相同', '相同'), changed = tr('different', '不同', '不同'),
        unknown = tr('unknown', '未知', '未知') }
      local function plain(value)
        return vim.fn.strcharpart(tostring(value or '?'), 0, 160):gsub('[\r\n%z\1-\31\127]', ' ')
      end
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Run comparison:', '运行比较：', '執行比較：') .. ' '
        .. plain(comparison.left_run_id) .. ' / ' .. plain(comparison.right_run_id)
      lines[#lines + 1] = tr('Differences describe records; they do not establish a cause.',
        '差异只描述记录，不能证明原因。', '差異只描述紀錄，不能證明原因。')
      lines[#lines + 1] = tr('Matching device labels do not establish physical device identity.',
        '设备名称相同不证明是同一物理设备。', '裝置名稱相同不證明是同一實體裝置。')
      for index, dimension in ipairs(comparison.dimensions) do
        if index > 32 then lines[#lines + 1] = tr('Further dimensions are in the full report.', '更多维度请查看完整报告。', '更多維度請查看完整報告。'); break end
        if type(dimension) == 'table' then
          lines[#lines + 1] = (names[dimension.name] or plain(dimension.name)) .. ': '
            .. (statuses[dimension.status] or tr('unknown', '未知', '未知'))
          if dimension.redacted == true or (type(dimension.redacted_fields) == 'table' and #dimension.redacted_fields > 0) then
            lines[#lines + 1] = tr('  Redacted values cannot establish equality; see the full report for field names.',
              '  脱敏值无法证明相同；字段名称见完整报告。', '  已遮蔽的值無法證明相同；欄位名稱見完整報告。')
          end
          if dimension.name == 'data' then
            lines[#lines + 1] = tr('  Matching settings or a declared version do not prove matching data contents.',
              '  配置或声明版本相同不能证明数据内容相同。', '  設定或宣告版本相同不能證明資料內容相同。')
          elseif dimension.name == 'optimizer_factory' then
            lines[#lines + 1] = tr('  This compares declarations, not implementation or state; missing declarations may mean a user-managed optimizer.',
              '  此处比较声明，不代表实现或状态相同；缺少声明也可能是用户管理优化器。',
              '  此處比較宣告，不代表實作或狀態相同；缺少宣告也可能是使用者管理最佳化器。')
          elseif dimension.name == 'supervision' then
            lines[#lines + 1] = tr('  Matching revisions do not prove equivalent bindings or runtime coverage.',
              '  修订相同不证明绑定或运行覆盖相同。', '  修訂相同不證明繫結或執行涵蓋範圍相同。')
          elseif dimension.name == 'runtime_paths' then
            local path_names = { working_directory = tr('working directory', '工作目录', '工作目錄'),
              project_import_roots = tr('module search directories', '模块搜索目录', '模組搜尋目錄') }
            if type(dimension.changed_fields) == 'table' then
              for _, field in ipairs(dimension.changed_fields) do
                if path_names[field] then
                  lines[#lines + 1] = '  ' .. path_names[field] .. ': ' .. statuses.changed
                end
              end
            end
            lines[#lines + 1] = tr('  Declarations do not prove the actual paths, imported code or environment match.',
              '  声明相同不能证明实际路径、导入代码或环境相同。', '  宣告相同不能證明實際路徑、匯入程式碼或環境相同。')
          elseif dimension.name == 'source_snapshot' then
            lines[#lines + 1] = tr('  The digest covers captured project Python files, not installed packages, data or external files.',
              '  摘要覆盖已捕获的项目 Python 文件，不包含已安装库、数据或外部文件。', '  摘要涵蓋已擷取的專案 Python 檔案，不包含已安裝程式庫、資料或外部檔案。')
          elseif (dimension.name == 'metrics' or dimension.name == 'training_mean_metrics' or dimension.name == 'user_reported_last_metrics') and type(dimension.left) == 'table' and type(dimension.right) == 'table' then
            if dimension.name == 'user_reported_last_metrics' then
              lines[#lines + 1] = tr('  These are loop-reported last-step values; equal names do not establish comparable data or computation.',
                '  这是循环报告的最后一步数值；名称相同不证明数据或计算可比。', '  這是迴圈回報的最後一步數值；名稱相同不證明資料或計算可比較。')
            end
            local keys, seen = {}, {}
            for key in pairs(dimension.left) do if type(key) == 'string' then seen[key] = true; keys[#keys + 1] = key end end
            for key in pairs(dimension.right) do if type(key) == 'string' and not seen[key] then keys[#keys + 1] = key end end
            table.sort(keys)
            for metric_index, key in ipairs(keys) do
              if metric_index > 16 then lines[#lines + 1] = tr('  Further metrics are in the full report.', '  更多指标请查看完整报告。', '  更多指標請查看完整報告。'); break end
              local left, right = dimension.left[key], dimension.right[key]
              lines[#lines + 1] = '  ' .. plain(key) .. ': '
                .. (type(left) == 'number' and tostring(left) or '?') .. ' / '
                .. (type(right) == 'number' and tostring(right) or '?')
            end
          end
        end
      end
    end
    if report.operation == 'environment_library_inventory' and type(report.data) == 'table' then
      lines[#lines + 1] = tr('Interpreter: ', '解释器：', '直譯器：') .. tostring(report.data.python_executable or '?')
      lines[#lines + 1] = tr('Selection source: ', '选择来源：', '選擇來源：') .. tostring(report.data.selected_by or '?')
      lines[#lines + 1] = tr('Installed does not mean imported or automatically connected.', '已安装不代表已导入或自动接入。', '已安裝不代表已匯入或自動接入。')
      if type(report.data.libraries) == 'table' and is_list(report.data.libraries) then
        local installed, shown = 0, 0
        for _, library in ipairs(report.data.libraries) do
          if type(library) == 'table' and library.installed == true then
            installed = installed + 1
            if shown < 20 then
              local name = vim.fn.strcharpart(tostring(library.name or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 160)
              lines[#lines + 1] = name .. ' · ' .. tr('installed', '已安装', '已安裝')
              shown = shown + 1
            end
          end
        end
        lines[#lines + 1] = tr('Installed entries in this report: ', '本报告中的已安装条目：', '本報告中的已安裝項目：') .. installed
          .. tr(' · omitted by backend: ', ' · 后端未列出：', ' · 後端未列出：') .. tostring(report.data.omitted_count or 0)
        lines[#lines + 1] = tr('[s] Search reported distributions; names may differ from import modules.',
          '[s] 搜索报告中的发行包；发行包名可能不同于导入模块名。', '[s] 搜尋報告中的發行套件；發行套件名稱可能不同於匯入模組名稱。')
        lines[#lines + 1] = tr('[i] Query an exact distribution in the selected environment.',
          '[i] 在所选环境中查询指定发行包。', '[i] 在所選環境中查詢指定發行套件。')
      end
    end
    if state.last.isolated_variant and not state.last.observed_context_changed then
      lines[#lines + 1] = tr('This variant result is separate from the current source-model context.',
        '此变体结果独立于当前源码模型上下文。', '此變體結果獨立於目前原始碼模型上下文。')
    elseif state.last.context_changed then
      lines[#lines + 1] = tr('Context changed; this report may be stale.', '上下文已变化，此报告可能已过期。', '上下文已變更，此報告可能已過期。')
    end
    if #failure_paths > 0 then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Last observed call (not necessarily the cause): ', '最后观察到的调用（不一定是原因）：', '最後觀察到的呼叫（不一定是原因）：')
        .. tostring(failure_call.module_type or '?') .. ' · ' .. table.concat(failure_paths, ', ')
      if type(failure_call.inputs) == 'table' then
        local input_lines, omitted = tensor_tree_summary(failure_call.inputs, 'input')
        lines[#lines + 1] = tr('Recorded inputs to this call:', '此调用记录的输入：', '此呼叫記錄的輸入：')
        for index, input_line in ipairs(input_lines) do
          if index > 3 then omitted = true; break end
          lines[#lines + 1] = '  ' .. input_line
        end
        if omitted then lines[#lines + 1] = tr('  Further input details are in the complete report.', '  更多输入详情见完整报告。', '  更多輸入詳情見完整報告。') end
      end
      if not state.last.isolated_variant then
        lines[#lines + 1] = tr('[d] Inspect, replay or edit an observed module', '[d] 检查、重放或修改已观察模块', '[d] 檢查、重播或修改已觀察模組')
      end
    end
    if #failure_frames > 0 then
      lines[#lines + 1] = tr('[g] Open a recorded project stack frame after checking current file content.',
        '[g] 核对当前文件内容后打开项目调用栈位置。', '[g] 核對目前檔案內容後開啟專案呼叫堆疊位置。')
      lines[#lines + 1] = tr('[l] Send currently matching frames to the source window location list.',
        '[l] 将当前文件匹配的调用栈位置发送到源码窗口位置列表。', '[l] 將目前檔案相符的呼叫堆疊位置傳送到原始碼視窗位置清單。')
      lines[#lines + 1] = tr('A stack frame is not necessarily the cause; its file digest was captured after the error.',
        '调用栈位置不一定是根因；文件摘要在报错后采集。', '呼叫堆疊位置不一定是根因；檔案摘要在錯誤後擷取。')
    end
    if edit_location then
      lines[#lines + 1] = tr('[g] Check and open the reported construction site; it may be a factory, not the caller.',
        '[g] 核对并打开报告的构造位置；它可能是工厂，而非调用方。',
        '[g] 核對並開啟回報的建構位置；它可能是工廠，而非呼叫方。')
    end
    if rule_failure_path then
      lines[#lines + 1] = tr('[d] Inspect this recorded path in the current model; it may differ from the failed run.',
        '[d] 在当前模型中检查此记录路径；它可能不同于失败时的模型。',
        '[d] 在目前模型中檢查此紀錄路徑；它可能不同於失敗時的模型。')
    end

  else
    lines[#lines + 1] = tr('No valid operation report.', '没有有效的操作报告。', '沒有有效的操作報告。')
    if state.last.uncertain_outcome then
      lines[#lines + 1] = tr('The operation may have started and its outcome is unknown. Inspect affected files, run records and external effects before deciding whether to retry.',
        '操作可能已经启动，但结果未知。请先检查受影响的文件、运行记录及外部副作用，再决定是否重试。',
        '操作可能已經啟動，但結果未知。請先檢查受影響的檔案、執行紀錄及外部副作用，再決定是否重試。')
    end
    local err = state.last.transport_error or state.last.project_error
    local message = type(err) == 'table' and err.message or (type(err) == 'string' and err or nil)
    if message then
      lines[#lines + 1] = vim.fn.strcharpart(tostring(message):gsub('[\r\n%z\1-\31\127]', ' '), 0, 4096)
    end
    if err ~= nil then
      lines[#lines + 1] = tr('[s] Open runtime settings, including CLI selection.',
        '[s] 打开运行时设置，包括 CLI 选择。', '[s] 開啟執行階段設定，包括 CLI 選擇。')
    end
  end
  local preview = report and report.status == 'success' and type(report.data) == 'table' and report.data.committed == false and report.data or nil
  local selected_source_line, selected_preview_row
  if preview and report.operation == 'recipe_sync' and type(preview.plan) == 'table' then
    local plan = preview.plan
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Declaration update', '声明更新', '宣告更新')
    if plan.sync_data == true then
      lines[#lines + 1] = tr('Previous input:', '原输入：', '原輸入：')
      vim.list_extend(lines, vim.split(vim.inspect(plan.previous_data), '\n', { plain = true }))
      lines[#lines + 1] = tr('Saved project input:', '项目已保存输入：', '專案已儲存輸入：')
      vim.list_extend(lines, vim.split(vim.inspect(plan.data), '\n', { plain = true }))
    end
    if plan.sync_training == true then
      lines[#lines + 1] = tr('Previous training settings:', '原训练设置：', '原訓練設定：')
      vim.list_extend(lines, vim.split(vim.inspect(plan.previous_training), '\n', { plain = true }))
      lines[#lines + 1] = tr('Selected training settings:', '所选训练设置：', '所選訓練設定：')
      vim.list_extend(lines, vim.split(vim.inspect(plan.training), '\n', { plain = true }))
    end
    lines[#lines + 1] = tr('Only the declaration changes; no model code is generated or run.',
      '只更新声明，不生成或运行模型代码。', '只更新宣告，不產生或執行模型程式碼。')
  elseif preview and report.operation == 'recipe_bundle' and type(preview.plan) == 'table' then
    local plan = preview.plan
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Project package', '项目文件包', '專案檔案包')
    lines[#lines + 1] = tr('New directory: ', '新建目录：', '新建目錄：') .. tostring(plan.output or '?'):gsub('[%c]', ' ')
    lines[#lines + 1] = tr('Total bytes: ', '总字节数：', '總位元組數：') .. tostring(plan.total_bytes or '?')
    if plan.kind == 'graph' or plan.kind == 'scaffold' then
      lines[#lines + 1] = tr('The declaration, its supervision reference and selected files are included; source, data, environment and credentials are not automatically included.',
        '包含声明、其监督引用和所选文件；源码、数据、环境和凭据不会自动打包。', '包含宣告、其監督參照和所選檔案；原始碼、資料、環境和憑據不會自動打包。')
      lines[#lines + 1] = tr('Dynamic imports and external resources remain unknown; select an interpreter and rebind resources in the destination.',
        '动态导入和外部资源仍为未知；需在目标项目选择解释器并重新绑定资源。', '動態匯入和外部資源仍為未知；需在目標專案選擇直譯器並重新繫結資源。')
    elseif plan.has_source_snapshot ~= true then
      lines[#lines + 1] = tr('No source snapshot is linked; rebuilding uses the preset and will not include edits to classification.py.',
        '尚未关联源码快照；重建会使用预设，不包含 classification.py 中的修改。',
        '尚未連結原始碼快照；重建會使用預設，不包含 classification.py 中的變更。')
    end
    if plan.kind ~= 'graph' and plan.kind ~= 'scaffold' and plan.data_directory_selected ~= true then
      lines[#lines + 1] = tr('The declared data directory was not selected as a directory; data may be missing or external.',
        '尚未选择声明的数据目录；数据可能缺失或位于项目外。', '尚未選擇宣告的資料目錄；資料可能缺失或位於專案外。')
    end
    if type(plan.potentially_sensitive_paths) == 'table' and #plan.potentially_sensitive_paths > 0 then
      lines[#lines + 1] = tr('Review possible credential files (filename hints only; not exhaustive):',
        '请检查可能含凭据的文件（仅依据文件名，可能有遗漏）：', '請檢查可能含憑據的檔案（僅依檔名，可能有遺漏）：')
      for index, path in ipairs(plan.potentially_sensitive_paths) do
        if index > 20 then lines[#lines + 1] = '…'; break end
        lines[#lines + 1] = '  ' .. vim.fn.strcharpart(tostring(path):gsub('[%c]', ' '), 0, 300)
      end
    end
    if type(plan.missing_runtime_directories) == 'table' and #plan.missing_runtime_directories > 0 then
      lines[#lines + 1] = tr('Runtime directories not present in package: ', '文件包中缺少运行目录：', '檔案包中缺少執行目錄：')
        .. table.concat(plan.missing_runtime_directories, ', '):gsub('[%c]', ' ')
    end
    if type(plan.runtime_hint) == 'table' and type(plan.runtime_hint.runtime_paths) == 'table' then
      local runtime = plan.runtime_hint.runtime_paths
      lines[#lines + 1] = tr('Runtime hints (restore explicitly):', '运行路径提示（需手动恢复）：', '執行路徑提示（需手動還原）：')
      vim.list_extend(lines, vim.split(vim.inspect(runtime), '\n', {plain = true}))
      if type(runtime.working_directory) == 'table' and runtime.working_directory.kind == 'external' then
        lines[#lines + 1] = tr('External working directory is not included; choose it again at the destination.',
          '外部运行目录未打包；请在目标项目重新选择。', '外部執行目錄未打包；請在目標專案重新選擇。')
      end
    end
    lines[#lines + 1] = tr('Included files (review paths before saving):', '将包含的文件（保存前请审核路径）：', '將包含的檔案（儲存前請檢視路徑）：')
    if type(plan.files) == 'table' then
      for _, name in ipairs(vim.fn.sort(vim.tbl_keys(plan.files))) do
        local item = plan.files[name]
        lines[#lines + 1] = '  ' .. tostring(name):gsub('[%c]', ' ') .. ' · ' .. tostring(type(item) == 'table' and item[1] or '?') .. ' B'
      end
    end
    if type(plan.generated_files) == 'table' then
      for _, name in ipairs(vim.fn.sort(vim.tbl_keys(plan.generated_files))) do
        lines[#lines + 1] = '  ' .. tostring(name):gsub('[%c]', ' ') .. tr(' · generated runtime hints', ' · 自动生成的运行路径提示', ' · 自動產生的執行路徑提示')
      end
    end
    lines[#lines + 1] = tr('Only listed files are copied. No libraries are installed; external resources are not included.',
      '只复制所列文件，不安装依赖，也不包含外部资源。', '只複製所列檔案，不安裝相依套件，也不包含外部資源。')
  elseif preview and report.operation == 'create' and type(preview.plan) == 'table' then
    local plan = preview.plan
    local function clean(value) return vim.fn.strcharpart(tostring(value or '?'):gsub('[%c]', ' '), 0, 200) end
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Image classification project', '图像分类项目', '影像分類專案')
    lines[#lines + 1] = tr('Model: ', '模型：', '模型：') .. clean(plan.preset)
    lines[#lines + 1] = tr('Image folder: ', '图像目录：', '影像目錄：') .. clean(plan.data_root)
    local paths = type(plan.config) == 'table' and plan.config.runtime_paths or nil
    if type(paths) == 'table' then
      lines[#lines + 1] = tr('Working directory: ', '运行目录：', '執行目錄：') .. clean(paths.working_directory ~= vim.NIL and paths.working_directory or tr('project default', '项目默认', '專案預設'))
      local roots = type(paths.project_import_roots) == 'table' and paths.project_import_roots or {}
      lines[#lines + 1] = tr('Project import directories: ', '项目模块目录：', '專案模組目錄：') .. (#roots > 0 and table.concat(roots, ', ') or tr('default', '默认', '預設'))
      lines[#lines + 1] = tr('Choose the target Python environment separately.', '目标 Python 环境需要另行选择。', '目標 Python 環境需要另外選擇。')
    end
    if type(plan.classes) == 'table' and is_list(plan.classes) then
      local names = {}
      for index, name in ipairs(plan.classes) do if index > 32 then break end; names[#names + 1] = clean(name) end
      lines[#lines + 1] = tr('Classes: ', '类别：', '類別：') .. table.concat(names, ', ')
    end
    lines[#lines + 1] = tr('Creates editable code and project settings. Images stay in place; content has not been validated.',
      '将创建可编辑代码和项目配置。图像保留在原处；内容尚未验证。', '將建立可編輯程式碼和專案設定。影像保留原處；內容尚未驗證。')
    lines[#lines + 1] = tr('The starter uses the training split only; edit the generated data setup for validation or test splits.',
      '骨架默认仅使用训练集；验证集或测试集需在生成的数据配置中设置。', '骨架預設僅使用訓練集；驗證集或測試集需在產生的資料設定中設定。')
  elseif preview and report.operation == 'scaffold' and type(preview.plan) == 'table' then
    local plan = preview.plan
    local selected_id = state.last and state.last.selected_scaffold_layer
    local locations = plan.layer_source_locations
    if type(selected_id) == 'string' and type(locations) == 'table'
        and locations.scope == 'proposed_generated_default_encoders_only'
        and type(plan.source) == 'string' and locations.source_sha256 == vim.fn.sha256(plan.source)
        and type(locations.locations) == 'table' then
      local location = locations.locations[selected_id]
      if type(location) == 'table' and type(location.line) == 'number' and location.line % 1 == 0
          and location.line >= 1 and location.line <= #vim.split(plan.source, '\n', {plain = true}) then
        selected_source_line = location.line
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('Selected layer in proposed Python: line ', '所选层在拟生成 Python 中的位置：第 ', '所選層在擬產生 Python 中的位置：第 ')
          .. tostring(location.line) .. tr(' (nested layers may share the enclosing expression).', ' 行（嵌套层可能共用外层表达式）。', ' 行（巢狀層可能共用外層運算式）。')
        lines[#lines + 1] = tr('Press [L] to jump to this layer in the preview.', '按 [L] 跳到预览中的该层。', '按 [L] 跳至預覽中的該層。')
        lines[#lines + 1] = tr('This is a generation preview, not evidence of the active model.', '这是生成预览，不代表当前运行模型。', '這是產生預覽，不代表目前執行模型。')
      end
    end
    if type(plan.update) == 'table' then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Build review', '构建审核', '建置檢視')
      local previous = type(plan.update.previous_model) == 'string' and plan.update.previous_model
        or tr('No active build', '尚无活动构建', '尚無作用中的建置')
      local target = type(plan.config) == 'table' and plan.config.model or '?'
      lines[#lines + 1] = previous .. '  →  ' .. tostring(target)
      local source = plan.update.previous_source
      if type(source) == 'table' then
        local file = tostring(source.file or '?'):gsub('[%c]', ' ')
        if source.status == 'different' then
          lines[#lines + 1] = tr('Current source differs from the saved declaration: ', '当前源码与保存的声明不一致：', '目前原始碼與儲存的宣告不一致：') .. file
          lines[#lines + 1] = tr('Review your edits in that file before continuing.', '继续前请检查该文件中的改动。', '繼續前請檢查該檔案中的變更。')
        elseif source.status == 'unknown' then
          lines[#lines + 1] = tr('Could not compare current source with the saved declaration.', '无法核对当前源码与保存的声明。', '無法核對目前原始碼與儲存的宣告。')
        end
      end
      lines[#lines + 1] = tr('Existing Python files are retained. Hand edits are not merged into the new build. Forward has not run.',
        '旧 Python 文件会保留；手工修改不会自动合并到新构建。尚未运行前向。',
        '舊 Python 檔案會保留；手動修改不會自動合併到新建置。尚未執行前向。')
      if type(plan.update.previous_recipe) == 'table' and type(plan.recipe) == 'table' then
        local sections = {
          {'data', tr('Data binding', '数据绑定', '資料繫結')},
          {'training', tr('Training', '训练', '訓練')},
          {'supervision', tr('Supervision reference', '监督引用', '監督參照')},
          {'inputs', tr('Input', '输入', '輸入')}, {'outputs', tr('Output head', '输出头', '輸出頭')},
          {'routes', tr('Connection', '接线', '接線')}, {'components', tr('Component', '组件', '元件')},
          {'encoder_layers', tr('Layer stack', '网络层', '網路層')},
          {'encoder_widths', tr('Component width', '组件输出宽度', '元件輸出寬度')},
          {'component_params', tr('Component parameters', '组件参数', '元件參數')},
        }
        local names = {
          shape = tr('Shape', '形状', '形狀'), dynamic_axes = tr('Dynamic axes', '动态轴', '動態軸'),
          dtype = tr('Dtype', '数据类型', '資料類型'), features = tr('Width', '维度', '維度'),
          loss = tr('Loss', '损失', '損失'), weight = tr('Weight', '权重', '權重'),
        }
        local function index(rows, ordered)
          local by_name, order = {}, {}
          for key, value in pairs(type(rows) == 'table' and rows or {}) do
            if ordered and type(value) == 'table' and type(key) == 'number' and type(value.name) == 'string' then
              by_name[value.name], order[key] = value, value.name
            elseif not ordered and type(key) == 'string' then
              by_name[key] = value
            end
          end
          return by_name, order
        end
        local start = #lines
        local function pair(prefix, old, next_value)
          lines[#lines + 1] = '  ' .. prefix .. vim.json.encode(old or vim.NIL)
            .. ' → ' .. vim.json.encode(next_value or vim.NIL)
        end
        for _, section in ipairs(sections) do
          local key, title = unpack(section)
          local ordered = key == 'inputs' or key == 'outputs'
          local old, old_order = index(plan.update.previous_recipe[key], ordered)
          local next_rows, new_order = index(plan.recipe[key], ordered)
          for _, name in ipairs(vim.fn.sort(vim.tbl_keys(vim.tbl_extend('force', old, next_rows)))) do
            local prefix = '  ' .. title .. ' · ' .. name
            local previous, current = old[name], next_rows[name]
            if previous == nil or current == nil then
              lines[#lines + 1] = prefix .. (previous == nil and tr(' added', ' · 新增', ' · 新增')
                or tr(' removed', ' · 移除', ' · 移除'))
            elseif ordered then
              for _, field in ipairs(vim.fn.sort(vim.tbl_keys(names))) do
                if not vim.deep_equal(previous[field], current[field]) then
                  pair(prefix .. ' · ' .. names[field] .. '  ', previous[field], current[field])
                end
              end
            elseif not vim.deep_equal(previous, current) then
              pair(prefix .. '  ', previous, current)
            end
          end
          if ordered and #old_order == #new_order and not vim.deep_equal(old_order, new_order)
              and #vim.tbl_keys(vim.tbl_extend('force', old, next_rows)) == #old_order then
            pair(title .. tr(' order  ', '顺序  ', '順序  '), old_order, new_order)
          end
        end
        if #lines == start then
          lines[#lines + 1] = tr('  No changes to the declaration.', '  声明内容无变化。', '  宣告內容無變化。')
        end
      end
    end
    if type(plan.encoder_dimensions) == 'table' then
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Inferred encoder widths', '推导的编码器宽度', '推導的編碼器寬度')
      for _, slot in ipairs(vim.fn.sort(vim.tbl_keys(plan.encoder_dimensions))) do
        local widths = plan.encoder_dimensions[slot]
        if type(widths) == 'table' then
          lines[#lines + 1] = '  ' .. slot .. '  ·  ' .. tostring(widths.input) .. ' → ' .. tostring(widths.output)
        end
      end
    end
    if type(plan.recipe) == 'table' then
      local recipe = plan.recipe
      local function append_records(key, comma)
        lines[#lines + 1] = '  "' .. key .. '": ['
        local records = type(recipe[key]) == 'table' and recipe[key] or {}
        for index, record in ipairs(records) do
          lines[#lines + 1] = '    ' .. vim.json.encode(record) .. (index < #records and ',' or '')
        end
        lines[#lines + 1] = comma and '  ],' or '  ]'
      end
      vim.list_extend(lines, { '', 'model-maven.json', '{', '  "version": ' .. tostring(recipe.version) .. ',' })
      if recipe.data then lines[#lines + 1] = '  \"data\": ' .. vim.json.encode(recipe.data) .. ',' end
      if recipe.training then lines[#lines + 1] = '  \"training\": ' .. vim.json.encode(recipe.training) .. ',' end
      if recipe.supervision then
        lines[#lines + 1] = '  "supervision": ' .. vim.json.encode(recipe.supervision) .. ','
      end
      append_records('inputs', true)
      append_records('outputs', recipe.routes ~= nil or recipe.components ~= nil or recipe.component_params ~= nil or recipe.encoder_layers ~= nil or recipe.encoder_widths ~= nil or recipe.native_encoders ~= nil)
      if recipe.routes then
        lines[#lines + 1] = '  "routes": ' .. vim.json.encode(recipe.routes)
          .. ((recipe.components or recipe.component_params or recipe.encoder_layers or recipe.encoder_widths or recipe.native_encoders) and ',' or '')
      end
      if recipe.components then
        lines[#lines + 1] = '  "components": ' .. vim.json.encode(recipe.components) .. ((recipe.component_params or recipe.encoder_layers or recipe.encoder_widths or recipe.native_encoders) and ',' or '')
      end
      if recipe.component_params then
        lines[#lines + 1] = '  "component_params": ' .. vim.json.encode(recipe.component_params)
          .. ((recipe.encoder_layers or recipe.encoder_widths or recipe.native_encoders) and ',' or '')
      end
      if type(recipe.encoder_layers) == 'table' then
        lines[#lines + 1] = '  "encoder_layers": {'
        local slots = vim.fn.sort(vim.tbl_keys(recipe.encoder_layers))
        for index, slot in ipairs(slots) do
          lines[#lines + 1] = '    ' .. vim.json.encode(slot) .. ': ' .. vim.json.encode(recipe.encoder_layers[slot])
            .. (index < #slots and ',' or '')
        end
        lines[#lines + 1] = (recipe.encoder_widths or recipe.native_encoders) and '  },' or '  }'
      end
      if recipe.encoder_widths then lines[#lines + 1] = '  "encoder_widths": ' .. vim.json.encode(recipe.encoder_widths) .. (recipe.native_encoders and ',' or '') end
      if recipe.native_encoders then lines[#lines + 1] = '  "native_encoders": ' .. vim.json.encode(recipe.native_encoders) end
      lines[#lines + 1] = '}'
      if recipe.supervision then
        lines[#lines + 1] = tr('Referenced rules need import and rebind.', '引用规则需要导入并重新绑定。', '參照規則需要匯入並重新繫結。')
      end
    end
    local ok, details = pcall(vim.inspect, { files = plan.files, inputs = plan.inputs,
      output = plan.output, routes = plan.routes, batch_source = plan.batch_source, starter_step = plan.starter_step, config = plan.config })
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Proposed files and model setup:', '拟创建的文件和模型配置：', '擬建立的檔案與模型設定：')
    if ok and reviewable_text(details) then vim.list_extend(lines, vim.split(details, '\n', { plain = true }))
    else lines[#lines + 1] = tr('Setup preview is too large to approve here.', '配置预览过大，当前界面不能批准。', '設定預覽過大，目前介面不能批准。') end
    lines[#lines + 1] = tr('The chosen input factory and model have not been executed or validated.',
      '所选输入工厂和模型尚未执行或验证。', '所選輸入工廠和模型尚未執行或驗證。')
  elseif preview and report.operation == 'assembly_patch' then
    local details = { sets = preview.sets, removes = preview.removes, model_injections = preview.model_injections,
      route_changes = preview.route_changes, input_routes = preview.input_routes,
      encoder_outputs = preview.encoder_outputs, encoder_output_modes = preview.encoder_output_modes, validation = preview.validation,
      injection_evidence = preview.injection_evidence }
    local ok, text = pcall(vim.inspect, details)
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Proposed assembly:', '拟保存的装配：', '擬儲存的裝配：')
    lines[#lines + 1] = tr('Shared slots describe this construction only; factories may return different instances later.',
      '共享接缝仅反映本次构造；工厂下次可能返回不同实例。', '共享接縫僅反映本次建構；工廠下次可能傳回不同實例。')
    if ok and reviewable_text(text) then vim.list_extend(lines, vim.split(text, '\n', { plain = true }))
    else lines[#lines + 1] = tr('Assembly preview is too large to approve here.', '装配预览过大，当前界面不能批准。', '裝配預覽過大，目前介面不能批准。') end
  elseif preview and report.operation == 'config_set_model' then
    local details = { previous_model = preview.previous_model, previous_model_params = preview.previous_model_params, model = preview.model,
      model_params = preview.model_params, previous_model_injections = preview.previous_model_injections,
      model_injections = preview.model_injections, clear_injections = preview.clear_injections }
    local ok, text = pcall(vim.inspect, details)
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Proposed model configuration:', '拟保存的模型配置：', '擬儲存的模型設定：')
    if ok and reviewable_text(text) then vim.list_extend(lines, vim.split(text, '\n', { plain = true }))
    else lines[#lines + 1] = tr('Model preview is too large to approve here.', '模型预览过大，当前界面不能批准。', '模型預覽過大，目前介面不能批准。') end
  elseif preview and report.operation == 'config_set_batch' then
    local ok, text = pcall(vim.inspect, { previous_batch = preview.previous_batch,
      previous_batch_binding = preview.previous_batch_binding, previous_batch_params = preview.previous_batch_params,
      batch = preview.batch, batch_binding = preview.batch_binding, batch_params = preview.batch_params })
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Proposed input configuration:', '拟保存的输入配置：', '擬儲存的輸入設定：')
    if ok and reviewable_text(text) then vim.list_extend(lines, vim.split(text, '\n', { plain = true }))
    else lines[#lines + 1] = tr('Input preview is too large to approve here.', '输入预览过大，当前界面不能批准。', '輸入預覽過大，目前介面不能批准。') end
  elseif preview and report.operation == 'init' then
    local ok, text = pcall(vim.inspect, preview.config)
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Proposed project configuration:', '拟保存的项目配置：', '擬儲存的專案設定：')
    if ok and reviewable_text(text) then vim.list_extend(lines, vim.split(text, '\n', { plain = true }))
    else lines[#lines + 1] = tr('Configuration preview is too large to approve here.', '配置预览过大，当前界面不能批准。', '設定預覽過大，目前介面不能批准。') end
  end
  if preview and report.operation == 'edit' then
    local function plain(value)
      return vim.fn.strcharpart(tostring(value or '?'), 0, 160):gsub('[\r\n%z\1-\31\127]', ' ')
    end
    local function reported_list(value)
      if type(value) ~= 'table' or not is_list(value) then return tr('not reported', '未报告', '未回報') end
      local items = {}
      for index, item in ipairs(value) do
        if index > 8 then items[#items + 1] = '…'; break end
        items[#items + 1] = type(item) == 'string' and plain(item) or tr('detail in full report', '详情见完整报告', '詳情見完整報告')
      end
      return tostring(#value) .. (#items > 0 and (' · ' .. table.concat(items, ', ')) or '')
    end
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Candidate effects (the current in-memory candidate only):',
      '候选影响（仅限当前内存中的候选）：', '候選影響（僅限目前記憶體中的候選）：')
    local adds_or_replaces = false
    for _, effect in ipairs(type(preview.edit_effects) == 'table' and preview.edit_effects or {}) do
      if type(effect) == 'table' and (effect.action == 'add' or effect.action == 'replace') then
        adds_or_replaces = true; break
      end
    end
    if adds_or_replaces then
      lines[#lines + 1] = tr('Registering or replacing a layer does not necessarily connect it to forward; a successful forward alone does not prove the new layer ran. Check the model code and execution evidence.',
        '添加或替换层不一定会将其接入前向计算；前向成功也不代表新层已执行。请检查模型代码与执行证据。',
        '新增或替換層不一定會將其接入前向運算；前向成功也不代表新層已執行。請檢查模型程式碼與執行證據。')
    end
    if type(preview.edit_effects) ~= 'table' or not is_list(preview.edit_effects) or #preview.edit_effects == 0 then
      lines[#lines + 1] = tr('Effects were not reported.', '未报告影响。', '未回報影響。')
    else
      local source_rebuild = false
      for index, effect in ipairs(preview.edit_effects) do
        if index > 64 then lines[#lines + 1] = tr('Further effects are in the full report.', '更多影响请查看完整报告。', '更多影響請查看完整報告。'); break end
        if type(effect) == 'table' then
          lines[#lines + 1] = plain(effect.action) .. ' · ' .. plain(effect.path)
          lines[#lines + 1] = tr('  Preserved state: ', '  保留状态：', '  保留狀態：') .. reported_list(effect.preserved)
          lines[#lines + 1] = tr('  Newly initialized state: ', '  新初始化状态：', '  新初始化狀態：') .. reported_list(effect.initialized)
          lines[#lines + 1] = tr('  Old state not copied: ', '  未复制的旧状态：', '  未複製的舊狀態：') .. reported_list(effect.old_state_not_copied)
          lines[#lines + 1] = tr('  Affected aliases: ', '  受影响别名：', '  受影響別名：') .. reported_list(effect.affected_aliases)
          if effect.source_rebind_preserves_original_construction == true then
            source_rebuild = true
            lines[#lines + 1] = tr('  Original container construction still runs; removed or replaced layers may be constructed before rebinding. Repeated edits add source code.',
              '  原容器构造仍会执行；删除或替换的层可能先被构造。重复编辑会增加源码。',
              '  原容器建構仍會執行；刪除或替換的層可能先被建構。重複編輯會增加原始碼。')
          end
          if type(effect.placement_policy) == 'string' then
            lines[#lines + 1] = tr('  Placement policy: ', '  设备处理：', '  裝置處理：') .. plain(effect.placement_policy)
            if type(effect.placement_reference) == 'table' then
              lines[#lines + 1] = tr('  First old-state device / dtype: ', '  旧层首个状态设备 / 类型：', '  舊層首個狀態裝置 / 型別：')
                .. plain(effect.placement_reference.device) .. ' / ' .. plain(effect.placement_reference.dtype)
            end
          end
          local retained_sharing = effect.candidate_external_state_sharing or effect.preserved_external_state_sharing
          if type(retained_sharing) == 'table' and #retained_sharing > 0 then
            lines[#lines + 1] = tr('  Candidate retains external state sharing; inspect the full report.',
              '  候选保留外部状态共享；请查看完整报告。', '  候選保留外部狀態共享；請查看完整報告。')
          end
          if type(effect.removed_candidate_external_state_sharing) == 'table' and #effect.removed_candidate_external_state_sharing > 0 then
            lines[#lines + 1] = tr('  Candidate removes external state sharing; inspect the full report.',
              '  候选会移除外部状态共享；请查看完整报告。', '  候選會移除外部狀態共享；請查看完整報告。')
          end
          if type(effect.unverified_old_state_storage) == 'table' and #effect.unverified_old_state_storage > 0 then
            lines[#lines + 1] = tr('  Some old state storage is unverified; inspect the full report.',
              '  部分旧状态存储未核实；请查看完整报告。', '  部分舊狀態儲存未核實；請查看完整報告。')
          end
        end
      end
      if source_rebuild then
        lines[#lines + 1] = tr('  In a batch, factories for layers later removed or replaced may also run; review the source diff and their side effects.',
          '  批量计划中后来删除或替换的层工厂也可能执行；请核对源码差异及其副作用。',
          '  批次計畫中後來刪除或替換的層工廠也可能執行；請核對原始碼差異及其副作用。')
        lines[#lines + 1] = tr('  Preview applies edits after model construction; generated factories run at container construction sites. Cross-container order and intermediate state may differ.',
          '  预览在模型构造后应用修改；生成代码在各容器构造处运行工厂，跨容器顺序和中间状态可能不同。',
          '  預覽在模型建構後套用修改；產生的程式碼在各容器建構處執行工廠，跨容器順序和中間狀態可能不同。')
        lines[#lines + 1] = tr('For related changes, cancel this preview and use W in the workspace to review a batch plan; or edit the source directly.',
          '如需多项相关修改，可取消本次预览，在工作区按 W 审核批量计划；也可直接编辑源码。',
          '如需多項相關修改，可取消本次預覽，在工作區按 W 檢視批次計畫；也可直接編輯原始碼。')
      end
    end
    if preview.target == 'source' then
      lines[#lines + 1] = tr('State copied into this candidate is not a checkpoint migration. After the source is saved, weight loading and compatibility depend on your model code and checkpoint.',
        '复制到本次候选的状态不等于迁移检查点。源码保存后，权重如何加载以及是否兼容取决于模型代码和检查点。',
        '複製到本次候選的狀態不等於遷移檢查點。原始碼儲存後，權重如何載入以及是否相容取決於模型程式碼和檢查點。')
    end
    local validation = type(preview.validation) == 'table' and preview.validation or {}
    lines[#lines + 1] = tr('Candidate forward: ', '候选前向：', '候選前向：') .. plain(validation.forward)
      .. tr(' · execution evidence: ', ' · 执行证据：', ' · 執行證據：') .. plain(validation.forward_evidence)
    if preview.target == 'source' then
      lines[#lines + 1] = tr('Review the source diff below. Saving and a later independent forward are separate steps.',
        '请查看下方源码差异；保存与之后的独立前向是两个步骤。', '請查看下方原始碼差異；儲存與之後的獨立前向是兩個步驟。')
    elseif type(preview.variant) == 'table' then
      local variant = preview.variant
      local edit = type(variant.edits) == 'table' and type(variant.cursor) == 'number' and variant.edits[variant.cursor] or nil
      local operations = type(edit) == 'table' and edit.action == 'transaction' and edit.operations or { edit }
      if type(operations) == 'table' then
        for index, operation in ipairs(operations) do
          if index > 64 then lines[#lines + 1] = tr('More operations in the full report.', '更多操作见完整报告。', '更多操作見完整報告。'); break end
          if type(operation) == 'table' and (operation.action == 'add' or operation.action == 'replace') then
            local devices = operation.rng_devices
            lines[#lines + 1] = tr('Layer RNG devices: CPU + ', 'Layer 随机设备：CPU + ', 'Layer 隨機裝置：CPU + ')
              .. (devices == nil and tr('none declared', '未声明其他设备', '未宣告其他裝置') or reported_list(devices))
          end
        end
      end
      lines[#lines + 1] = tr('The candidate forward is not a saved variant or proof of identical future weights. Review before saving.',
        '候选前向不等于已保存变体，也不能证明之后权重相同；请审核后再保存。',
        '候選前向不等於已儲存變體，也不能證明之後權重相同；請檢視後再儲存。')
    end
  end
  local source = preview and report.operation == 'scaffold' and type(preview.plan) == 'table' and preview.plan.source or nil
  local diff = preview and report.operation == 'edit' and type(preview.source_patch) == 'table' and preview.source_patch.unified_diff or nil
  if type(source) == 'string' and type(preview.plan.update) == 'table' then
    local prior = preview.plan.update.previous_source
    if type(prior) == 'table' and prior.status == 'different' and type(prior.file) == 'string'
        and prior.file:match('^[%w_]+%.py$') and type(prior.revision) == 'string'
        and #prior.revision == 64 and not prior.revision:find('[^0-9a-f]') then
      local path = state.opts.project .. '/' .. prior.file
      local stat = vim.uv.fs_lstat(path)
      if stat and stat.type == 'file' and stat.size <= 2 * 1024 * 1024 then
        local file = io.open(path, 'rb')
        local old = file and file:read(2 * 1024 * 1024 + 1) or nil
        if file then file:close() end
        if old and #old <= 2 * 1024 * 1024 and vim.fn.sha256(old) == prior.revision then
          local ok, value = pcall(vim.diff, old, source, { result_type = 'unified', ctxlen = 3 })
          if ok then diff = value end
        end
      end
      if not diff then diff = tr('Source changed or cannot be read; re-preview before reviewing the difference.',
        '源码已变化或无法读取；请重新预览后查看差异。', '原始碼已變更或無法讀取；請重新預覽後查看差異。') end
    end
  end
  for _, item in ipairs({ { label = tr('Proposed source:', '拟生成源码：', '擬產生原始碼：'), text = source },
      { label = tr('Proposed source diff:', '拟修改源码差异：', '擬修改原始碼差異：'), text = diff } }) do
    if type(item.text) == 'string' then
      lines[#lines + 1] = ''
      lines[#lines + 1] = item.label
      if reviewable_text(item.text) then
        if item.text == source and selected_source_line then selected_preview_row = #lines + selected_source_line end
        vim.list_extend(lines, vim.split(item.text, '\n', { plain = true }))
      else lines[#lines + 1] = tr('Preview is too large for this view; this guarded action cannot be committed here.',
        '预览过大，当前界面不能提交此受保护操作。', '預覽過大，目前介面不能提交此受保護操作。') end
    end
  end
  lines[#lines + 1] = ''
  lines[#lines + 1] = tr('Bounded details below. [J] opens the complete structured report on demand.',
    '以下为有界详情，按 [J] 按需打开完整结构化报告。', '以下為有界詳情，按 [J] 按需開啟完整結構化報告。')
  local hidden_samples = type(evaluation_data) == 'table' and type(evaluation_data.evaluation) == 'table'
    and type(evaluation_data.evaluation.sample_previews) == 'table' and evaluation_data.evaluation.sample_previews.samples or nil
  vim.list_extend(lines, vim.split(vim.inspect(bounded_summary(displayed, hidden_samples)), '\n', { plain = true }))
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
  vim.bo[buf].modifiable = false
  -- Reuse this workspace's single visible report, including when the action
  -- started from its panel. Never replace a pending review, source window,
  -- another workspace's report, or a report shown in multiple windows.
  local reuse_report = false
  local prior = state.report_buf
  if prior and vim.api.nvim_buf_is_valid(prior) and not vim.b[prior].model_maven_review_pending then
    if vim.api.nvim_get_current_buf() == prior then
      reuse_report = true
    elseif vim.api.nvim_get_current_buf() == state.panel then
      local windows = vim.fn.win_findbuf(prior)
      local target = #windows == 1 and windows[1] or nil
      if target and vim.api.nvim_win_is_valid(target) and target ~= state.panel_win and target ~= state.code_win
          and vim.api.nvim_win_get_tabpage(target) == state.tab and vim.api.nvim_win_get_buf(target) == prior then
        local ok = pcall(vim.api.nvim_set_current_win, target)
        reuse_report = ok and vim.api.nvim_get_current_win() == target
          and vim.api.nvim_win_get_buf(target) == prior and not vim.b[prior].model_maven_review_pending
      end
    end
  end
  local opened = reuse_report or open_aux_buffer(buf, false, true)
  if not opened then
    pcall(vim.api.nvim_buf_delete, buf, { force = true })
    notify(tr('Not enough room to open the report. Resize the editor and try again.',
      '空间不足，无法打开报告。请调整编辑器大小后重试。',
      '空間不足，無法開啟報告。請調整編輯器大小後重試。'), vim.log.levels.WARN)
    return
  end
  if reuse_report then vim.api.nvim_win_set_buf(0, buf) end
  state.report_buf = buf
  if selected_preview_row then
    local mark = vim.api.nvim_buf_set_extmark(buf, builder_buttons, selected_preview_row - 1, 0, {right_gravity = true})
    vim.keymap.set('n', 'L', function()
      if state.closed or state.last ~= displayed or displayed.context_changed
          or vim.api.nvim_get_current_buf() ~= buf then return end
      local position = vim.api.nvim_buf_get_extmark_by_id(buf, builder_buttons, mark, {})
      if #position == 2 then
        pcall(vim.cmd, "normal! m'")
        vim.api.nvim_win_set_cursor(0, {position[1] + 1, 0})
      end
    end, {buffer = buf, silent = true, desc = 'Locate selected layer in proposed Python'})
  end
  vim.keymap.set('n', 'q', function()
    local report_win = vim.api.nvim_get_current_win()
    if vim.api.nvim_win_get_buf(report_win) ~= buf or not pcall(vim.api.nvim_win_close, report_win, false) then return end
    if not state.closed and state.panel_win and vim.api.nvim_win_is_valid(state.panel_win)
        and vim.api.nvim_win_get_tabpage(state.panel_win) == vim.api.nvim_get_current_tabpage() then
      pcall(vim.api.nvim_set_current_win, state.panel_win)
    end
  end, { buffer = buf, silent = true, desc = 'Close report and focus workspace' })
  if type(readiness_actions) == 'table' then
    vim.keymap.set('n', 'a', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify(tr('This readiness report is stale; refresh it before using a recovery action.',
          '这份准备度报告已过期；使用恢复操作前请刷新。', '這份就緒度報告已過期；使用復原操作前請重新整理。'), vim.log.levels.WARN)
        return
      end
      local choices, by_index = {}, {}
      for _, action in ipairs(readiness_actions) do
        if type(action) == 'table' and type(action.id) == 'string' then
          local label = tostring(action.label or action.id):gsub('[\r\n%z\1-\31\127]', ' ')
          local availability = readiness_availability(action.availability)
          choices[#choices + 1] = vim.fn.strcharpart(label, 0, 160) .. ' · ' .. availability
          by_index[#choices] = action
        end
      end
      if #choices == 0 then return end
      vim.ui.select(choices, { prompt = tr('Choose the backend recovery action to open',
        '选择要打开的后端恢复操作', '選擇要開啟的後端復原操作') }, function(_, index)
        local action = index and by_index[index]
        if not action or state.closed or state.last ~= displayed or displayed.context_changed then return end
        if action.availability ~= 'available' then
          notify(tr('This recovery action is not confirmed available. Review its conditions and refresh the report first.',
            '此恢复操作尚未确认可用；请查看条件并先刷新报告。',
            '此復原操作尚未確認可用；請查看條件並先重新整理報告。'), vim.log.levels.WARN)
          return
        end
        local key = ({
          choose_python_interpreter = 'e',
          inspect_environment = 'E',
          review_missing_dependency = 'E',
          configure_batch = 'b',
          configure_project_batch = 'S',
          provide_component_test_batch = 'b',
          select_edit_target = 'W',
        })[action.id]
        if key and state.actions and type(state.actions[key]) == 'function' then
          state.actions[key]()
        elseif action.id == 'configure_component_fixture' or action.id == 'configure_layer_provider_fixture' then
          if state.code_buf and vim.api.nvim_buf_is_valid(state.code_buf) then
            vim.api.nvim_win_set_buf(0, state.code_buf)
            notify(tr('Edit the component manifest and fixture in the project source, then rerun readiness.',
              '请在项目源码中编辑组件清单和 fixture，然后重新检查准备度。',
              '請在專案原始碼中編輯元件清單和 fixture，然後重新檢查就緒度。'), vim.log.levels.INFO)
          else
            notify(tr('No source buffer is available for the manual component fixture edit.',
              '当前没有可用于手动编辑组件 fixture 的源码 buffer。',
              '目前沒有可用於手動編輯元件 fixture 的原始碼 buffer。'), vim.log.levels.WARN)
          end
        elseif action.id == 'test_layer_provider' then
          vim.ui.input({ prompt = tr('Layer provider component ID (namespace/name): ',
            'Layer Provider 组件 ID（namespace/name）：', 'Layer Provider 元件 ID（namespace/name）：') }, function(component_id)
            if not component_id or state.closed or state.last ~= displayed or displayed.context_changed then return end
            component_id = vim.trim(component_id)
            if #component_id > 256 or component_id:find('[%c]') or not component_id:match('^[%w_.-]+/[%w_.-]+$') then
              notify(tr('Enter a valid namespace/name component ID.', '请输入有效的 namespace/name 组件 ID。',
                '請輸入有效的 namespace/name 元件 ID。'), vim.log.levels.WARN)
              return
            end
            run(state, tr('Test Layer provider component', '测试 Layer Provider 组件', '測試 Layer Provider 元件'),
              { 'component', 'test', component_id }, function() show_report(state) end)
          end)
        elseif action.id == 'inspect_protocol_compatibility' or action.id == 'inspect_unknown_diagnostic' then
          run(state, tr('Inspect CLI and Worker diagnostics', '检查 CLI 与 Worker 诊断', '檢查 CLI 與 Worker 診斷'),
            { 'doctor' }, function(result, failure)
              if not failure and result and result.status == 'success' then show_report(state) end
            end, nil, true)
        else
          notify(tr('No direct workspace handler is registered for ', '此恢复操作尚无直接工作区处理器：',
            '此復原操作尚無直接工作區處理器：') .. tostring(action.id)
            .. tr('. Use e, E or b to choose the relevant runtime, environment or input explicitly.',
              '。请按 e、E 或 b 明确选择运行环境、环境诊断或输入。',
              '。請按 e、E 或 b 明確選擇執行環境、環境診斷或輸入。'), vim.log.levels.WARN)
        end
      end)
    end, { buffer = buf, silent = true, desc = 'Open backend readiness recovery action' })
  end
  if type(displayed.contract_file) == 'string' then
    vim.keymap.set('n', 'b', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify(tr('This report is no longer current; return to the workspace.', '报告已过期，请返回工作区。', '報告已過期，請返回工作區。'), vim.log.levels.WARN); return
      end
      local file = displayed.contract_file
      if not vim.uv.fs_stat(file) then
        notify(tr('The contract file is unavailable; select it again with X.', '契约文件不可用，请用 X 重新选择。', '契約檔案無法使用，請用 X 重新選擇。'), vim.log.levels.WARN); return
      end
      if focus_source(state, file) then
        notify(tr('Opened the current file; its contents may differ from the report.',
          '已打开当前文件；其内容可能与报告不同。', '已開啟目前檔案；其內容可能與報告不同。'), vim.log.levels.INFO)
      end
    end, { buffer = buf, silent = true, desc = 'Open contract file' })
  end
  if type(evaluation_data) == 'table' and type(evaluation_data.evaluation) == 'table' then
    local preview = evaluation_data.evaluation.sample_previews
    local samples = type(preview) == 'table' and preview.samples or nil
    if type(samples) == 'table' and is_list(samples) and #samples > 0 then
      vim.keymap.set('n', 'P', function()
        if state.closed or state.last ~= displayed then return end
        local rows, labels = {}, {}
        for _, sample in ipairs(samples) do
          if type(sample) == 'table' and type(sample.sample_id) == 'string' then
            rows[#rows + 1] = sample
            labels[#labels + 1] = vim.fn.strcharpart(sample.sample_id:gsub('[\r\n%z\1-\31\127]', ' '), 0, 256)
          end
          if #rows >= 32 then break end
        end
        if #rows == 0 then notify(tr('No readable prediction samples.', '没有可读取的预测样本。', '沒有可讀取的預測樣本。'), vim.log.levels.INFO); return end
        vim.ui.select(labels, { prompt = tr('Choose a reported prediction; values may be sensitive',
          '选择报告中的预测；内容可能敏感', '選擇回報中的預測；內容可能敏感') }, function(_, index)
          local sample = index and rows[index]
          if not sample or state.closed or state.last ~= displayed then return end
          local ok, encoded = pcall(vim.json.encode, sample)
          if not ok or #encoded > 65536 then
            notify(tr('Sample is unavailable or too large for this view; inspect the full report.',
              '样本不可用或过大，请查看完整报告。', '樣本無法使用或過大，請查看完整報告。'), vim.log.levels.WARN); return
          end
          local detail = vim.api.nvim_create_buf(false, true)
          vim.bo[detail].buftype, vim.bo[detail].bufhidden, vim.bo[detail].swapfile = 'nofile', 'wipe', false
          local pretty = vim.inspect(sample)
          vim.api.nvim_buf_set_lines(detail, 0, -1, false, vim.split(pretty, '\n', { plain = true }))
          vim.bo[detail].modifiable = false
          local opened = pcall(vim.cmd, 'botright split')
          if not opened then opened = pcall(vim.cmd, 'botright vsplit') end
          if not opened then pcall(vim.api.nvim_buf_delete, detail, { force = true }); notify(tr('Cannot open prediction details.', '无法打开预测详情。', '無法開啟預測詳情。'), vim.log.levels.WARN); return end
          vim.api.nvim_win_set_buf(0, detail)
          vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = detail, silent = true, desc = 'Close prediction details' })
        end)
      end, { buffer = buf, silent = true, desc = 'Review reported prediction samples' })
    end
  end
  if report and report.operation == 'environment_library_inventory' and type(report.data) == 'table'
      and type(report.data.libraries) == 'table' and is_list(report.data.libraries) then
    vim.keymap.set('n', 'i', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify(tr('The environment report is stale; inspect again.', '环境报告已过期，请重新检查。', '環境報告已過期，請重新檢查。'), vim.log.levels.WARN); return
      end
      vim.ui.input({ prompt = tr('Exact Python distribution name: ', 'Python 发行包的完整名称：', 'Python 發行套件的完整名稱：') }, function(raw)
        if raw == nil or state.closed or state.last ~= displayed or displayed.context_changed then return end
        local name = vim.trim(raw)
        if #name > 200 or not name:match('^[A-Za-z0-9][A-Za-z0-9._%-]*$') then
          notify(tr('Enter a valid distribution name.', '请输入有效的发行包名称。', '請輸入有效的發行套件名稱。'), vim.log.levels.WARN); return
        end
        run(state, tr('Query distribution metadata', '查询发行包元数据', '查詢發行套件中繼資料'),
          { 'env', 'libraries', '--library', name }, nil, nil, true)
      end)
    end, { buffer = buf, silent = true, desc = 'Query a distribution' })
    vim.keymap.set('n', 's', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify(tr('The environment report is stale; inspect again.', '环境报告已过期，请重新检查。', '環境報告已過期，請重新檢查。'), vim.log.levels.WARN); return
      end
      vim.ui.input({ prompt = tr('Search reported distribution names: ', '搜索报告中的发行包名称：', '搜尋報告中的發行套件名稱：') }, function(query)
        if query == nil or state.closed or state.last ~= displayed or displayed.context_changed then return end
        query = vim.trim(query):lower()
        local rows, choices, total = {}, {}, 0
        for _, library in ipairs(report.data.libraries) do
          if type(library) == 'table' and type(library.name) == 'string' and library.name:lower():find(query, 1, true) then
            total = total + 1
            if #rows < 200 then
              rows[#rows + 1] = library
              local name = vim.fn.strcharpart(library.name:gsub('[\r\n%z\1-\31\127]', ' '), 0, 160)
              choices[#choices + 1] = name .. ' · ' .. (library.installed == true and tr('installed', '已安装', '已安裝') or tr('not found', '未发现', '未發現'))
            end
          end
        end
        if #rows == 0 then notify(tr('No matching reported distribution.', '报告中没有匹配的发行包。', '報告中沒有相符的發行套件。'), vim.log.levels.INFO); return end
        vim.ui.select(choices, { prompt = tr('Choose a distribution; matches: ', '选择发行包；匹配数：', '選擇發行套件；符合數：') .. total
          .. (total > #rows and tr(' (first 200; refine search)', '（仅前 200 项，请缩小搜索）', '（僅前 200 項，請縮小搜尋）') or '') }, function(_, index)
          local library = index and rows[index]
          if not library or state.closed or state.last ~= displayed or displayed.context_changed then return end
          vim.ui.select({ tr('View details only', '仅查看详情', '僅檢視詳情'), tr('Choose a module to import', '选择要导入的模块', '選擇要匯入的模組') }, {
            prompt = vim.fn.strcharpart(library.name:gsub('[\r\n%z\1-\31\127]', ' '), 0, 160),
          }, function(_, action)
            if not action or state.closed or state.last ~= displayed or displayed.context_changed then return end
            if action == 1 then
              notify(vim.inspect(bounded_summary({ name = library.name, installed = library.installed, versions = library.installed_versions,
                import_name_hint = library.import_name_hint, import_name_hint_source = library.import_name_hint_source,
                import_name_candidates = library.import_name_candidates, adapter_status = library.adapter_status })), vim.log.levels.INFO)
              return
            end
            local hint = type(library.import_name_hint) == 'string' and library.import_name_hint or ''
            local prompt = tr('Python module to import (review the name): ', '要导入的 Python 模块（请核对名称）：', '要匯入的 Python 模組（請核對名稱）：')
            if library.import_name_hint_source == 'distribution-metadata-unverified' then
              prompt = tr('Unverified metadata suggestion; review module name: ', '元数据建议未经验证，请核对模块名：', '中繼資料建議未經驗證，請核對模組名稱：')
            end
            vim.ui.input({ prompt = prompt, default = hint }, function(name)
              if not name or name == '' or state.closed or state.last ~= displayed or displayed.context_changed then return end
              if #name > 800 or name:find('[%c%s]') then
                notify(tr('Enter a module name without whitespace or control characters.', '请输入不含空格或控制字符的模块名。', '請輸入不含空白或控制字元的模組名稱。'), vim.log.levels.WARN); return
              end
              local effects = tr('Imports the chosen module in the selected Python; import-time code may execute.',
                '将在所选 Python 中导入该模块，可能执行导入时代码。', '將在所選 Python 中匯入該模組，可能執行匯入時程式碼。') .. '\nModule: ' .. name
              run(state, tr('Import module', '导入模块', '匯入模組'), { 'env', 'probe', '--library', name }, nil, effects, true)
            end)
          end)
        end)
      end)
    end, { buffer = buf, silent = true, desc = 'Search installed distributions' })
  end
  vim.keymap.set('n', 'J', function()
    local full = vim.api.nvim_create_buf(false, true)
    vim.bo[full].buftype, vim.bo[full].bufhidden, vim.bo[full].swapfile = 'nofile', 'wipe', false
    local ok, contents = pcall(vim.inspect, displayed)
    if not ok then
      pcall(vim.api.nvim_buf_delete, full, { force = true })
      notify(tr('Could not render the complete report.', '无法显示完整报告。', '無法顯示完整報告。'), vim.log.levels.WARN); return
    end
    vim.api.nvim_buf_set_lines(full, 0, -1, false, vim.split(contents, '\n', { plain = true }))
    vim.bo[full].modifiable = false
    local opened = pcall(vim.cmd, 'botright split')
    if not opened then opened = pcall(vim.cmd, 'botright vsplit') end
    if not opened then
      pcall(vim.api.nvim_buf_delete, full, { force = true })
      notify(tr('Not enough room to open the complete report. Resize the editor and try again.',
        '空间不足，无法打开完整报告；请调整编辑器大小后重试。',
        '空間不足，無法開啟完整報告；請調整編輯器大小後重試。'), vim.log.levels.WARN)
      return
    end
    vim.api.nvim_win_set_buf(0, full)
    vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = full, silent = true, desc = 'Close full report' })
  end, { buffer = buf, silent = true, desc = 'Open complete report' })
  if (report and report.status == 'error') or (not report and (displayed.transport_error ~= nil or displayed.project_error ~= nil)) then
    vim.keymap.set('n', 's', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify(tr('This report is no longer current; return to the workspace.',
          '报告已过期，请返回工作区。', '報告已過期，請返回工作區。'), vim.log.levels.WARN); return
      end
      local choices = {
        { key = 'e', label = tr('Choose Python', '选择 Python', '選擇 Python') },
        { key = 'K', label = tr('Configure runtime paths', '设置运行时路径', '設定執行階段路徑') },
        { key = 'E', label = tr('Environment actions (includes CLI selection)', '环境操作（包括选择 CLI）', '環境操作（包括選擇 CLI）') },
      }
      vim.ui.select(choices, { prompt = tr('Choose a setting to inspect; the cause may be elsewhere',
        '选择要查看的设置；错误原因也可能在别处', '選擇要檢視的設定；錯誤原因也可能在其他地方'),
        format_item = function(item) return item.label end }, function(item)
        if not item or state.closed or state.last ~= displayed or displayed.context_changed then return end
        local action = state.actions and state.actions[item.key]
        if action then action() end
      end)
    end, { buffer = buf, silent = true, desc = 'Open runtime settings' })
  end
  if #failure_paths > 0 then
    vim.keymap.set('n', 'd', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify('This diagnostic is no longer current; run the forward pass again.', vim.log.levels.WARN); return
      end
      vim.ui.select(failure_paths, { prompt = tr('Select observed path; it may not be the cause', '选择观察到的路径；它不一定是错误原因', '選擇觀察到的路徑；它不一定是錯誤原因') }, function(path)
        if not path or state.closed or state.last ~= displayed or displayed.context_changed then return end
        vim.ui.select({
          tr('Inspect this module', '检查此模块', '檢查此模組'),
          tr('Preview a source change', '预览源码修改', '預覽原始碼修改'),
          tr('Replay this module', '重放此模块', '重播此模組'),
        }, { prompt = tr('Next action for ', '下一步操作：', '下一步操作：') .. path }, function(_, action)
          if not action or state.closed or state.last ~= displayed or displayed.context_changed then return end
          state.last_selection = path
          if action == 1 then
