          elseif action == 2 then
            preview_layer(state, path)
          else
            probe_local(state)
          end
        end)
      end)
    end, { buffer = buf, silent = true, desc = 'Inspect observed module' })
  end
  if #contract_paths > 0 and #failure_paths == 0 and not rule_failure_path then
    vim.keymap.set('n', 'd', function()
