      vim.ui.select(contract_paths, { prompt = tr('Choose a recorded module (up to 32); the mismatch may have another cause',
        '选择记录的模块（最多 32 个）；不匹配也可能由其他原因造成', '選擇記錄的模組（最多 32 個）；不相符也可能由其他原因造成') }, function(path)
        if not path or state.closed or state.last ~= displayed or displayed.context_changed then return end
        local choices = { tr('Inspect current module', '检查当前模块', '檢查目前模組'),
          tr('Preview a source change', '预览源码修改', '預覽原始碼修改') }
        if contract_sources[path] then choices[#choices + 1] = tr('Open recorded implementation', '打开记录的实现', '開啟記錄的實作') end
        vim.ui.select(choices, { prompt = path }, function(_, choice)
