        notify(tr('The error report is stale; run forward again.', '错误报告已过期，请重新前向。', '錯誤報告已過期，請重新前向。'), vim.log.levels.WARN); return
      end
      export_failure_locations(state, failure_frames, displayed)
    end, { buffer = buf, silent = true, desc = 'Send stack frames to location list' })
    vim.keymap.set('n', 'g', function()
