        local safe_function = vim.fn.strcharpart(tostring(frame['function'] or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 120)
        choices[#choices + 1] = safe_file .. ':' .. frame.line .. ' · ' .. safe_function
      end
      vim.ui.select(choices, { prompt = tr('Choose a recorded stack frame', '选择记录的调用栈位置', '選擇記錄的呼叫堆疊位置') }, function(_, index)
        local frame = index and failure_frames[index]
        if not frame or state.closed or state.last ~= displayed or displayed.context_changed then return end
        open_verified_implementation(state, { path = '', source = frame.file, digest = frame.source_sha256,
          line = frame.line, location_kind = 'traceback' })
      end)
    end, { buffer = buf, silent = true, desc = 'Open project stack frame' })
  end
  if edit_location and #failure_frames == 0 then
    vim.keymap.set('n', 'g', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        notify(tr('The report context changed; preview again.', '报告上下文已变化，请重新预览。', '報告上下文已變更，請重新預覽。'), vim.log.levels.WARN); return
      end
      open_verified_implementation(state, { path = edit_location.path, source = edit_location.source,
        digest = edit_location.digest, line = edit_location.line, location_kind = 'construction' })
    end, { buffer = buf, silent = true, desc = 'Open reported construction site' })
