    vim.keymap.set('n', 'd', function()
      if state.closed or state.last ~= displayed or displayed.context_changed then
        return notify(tr('The report is stale; run the draft again.', '报告已过期，请重新运行草稿。', '報告已過期，請重新執行草稿。'), vim.log.levels.WARN)
      end
      local target
      for _, win in ipairs(vim.api.nvim_tabpage_list_wins(0)) do
        if vim.api.nvim_win_is_valid(win) and vim.b[vim.api.nvim_win_get_buf(win)].model_maven_graph_window then target = win end
      end
      if not target then
        return notify(tr('Open the graph again to locate this failure.', '请重新打开画布定位错误。', '請重新開啟畫布定位錯誤。'), vim.log.levels.WARN)
      end
      vim.api.nvim_set_current_win(target)
      vim.api.nvim_feedkeys('d', 'm', false)
    end, { buffer = buf, silent = true, desc = 'Locate possible graph failure' })
  end
  if next(failure_action_rows) or next(forward_action_rows) then
    local action_rows = vim.tbl_extend('error', failure_action_rows, forward_action_rows)
    for row in pairs(action_rows) do
      vim.api.nvim_buf_set_extmark(buf, builder_buttons, row - 1, 0, { line_hl_group = 'Pmenu' })
    end
    local function activate_failure_action(row)
      local key = action_rows[row]
      if not key or state.closed or state.last ~= displayed or displayed.context_changed then return end
      if forward_action_rows[row] then
        if state.actions and state.actions[key] then state.actions[key]((key == 'd' or key == 'M') and true or nil) end
      else
        local mapping = vim.api.nvim_buf_call(buf, function() return vim.fn.maparg(key, 'n', false, true) end)
        if type(mapping) == 'table' and type(mapping.callback) == 'function' then mapping.callback() end
      end
    end
    -- Rows advertise direct shortcuts as well as Enter/click. Preserve any
    -- report-specific mapping already installed for the same key.
    local mapped = {}
    for _, mapping in ipairs(vim.api.nvim_buf_get_keymap(buf, 'n')) do mapped[mapping.lhs] = true end
    for row, key in pairs(forward_action_rows) do
      if not mapped[key] then
        local target_row = row
        vim.keymap.set('n', key, function() activate_failure_action(target_row) end,
          { buffer = buf, silent = true, nowait = true })
        mapped[key] = true
      end
    end
    vim.keymap.set('n', '<CR>', function()
      activate_failure_action(vim.api.nvim_win_get_cursor(0)[1] - (vim.b[buf].model_maven_action_offset or 0))
    end, { buffer = buf, silent = true })
    local function click_report_action()
      local mouse = vim.fn.getmousepos()
      local action_row = mouse.line - (vim.b[buf].model_maven_action_offset or 0)
      if mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= buf
          or not action_rows[action_row] then return '<LeftMouse>' end
      vim.schedule(function()
        if vim.api.nvim_win_is_valid(mouse.winid) and vim.api.nvim_win_get_buf(mouse.winid) == buf then
          vim.api.nvim_set_current_win(mouse.winid)
          activate_failure_action(action_row)
        end
      end)
      return '<Ignore>'
    end
    for _, key in ipairs({ '<LeftMouse>', '<2-LeftMouse>', '<3-LeftMouse>', '<4-LeftMouse>' }) do
      vim.keymap.set('n', key, click_report_action, { buffer = buf, expr = true, silent = true })
    end
  end
  return buf
end

-- Keep the report navigable before presenting the final confirmation.
local function review_gate(buf, options, prompt, callback, on_close, clickable)
  if not buf or not vim.api.nvim_buf_is_valid(buf) then if on_close then on_close() end; return end
  local finished = false
  vim.b[buf].model_maven_review_pending = true
  vim.bo[buf].modifiable = true
  vim.api.nvim_buf_set_lines(buf, 0, 0, false, clickable and {
    clickable == 'update' and tr('  → Generate and activate [a]', '  → 生成并激活 [a]', '  → 產生並啟用 [a]')
      or tr('  → Confirm and save [a]', '  → 确认并保存 [a]', '  → 確認並儲存 [a]'),
    tr('  ← Cancel [q]', '  ← 取消 [q]', '  ← 取消 [q]'), '',
  } or {
    tr('Review this report. [a] Continue  [q] Cancel', '请查看此报告。[a] 继续  [q] 取消', '請查看此報告。[a] 繼續  [q] 取消'), '',
  })
  vim.bo[buf].modifiable = false
  local win = vim.fn.bufwinid(buf)
  if win ~= -1 and vim.api.nvim_win_is_valid(win) then
    vim.api.nvim_set_current_win(win)
    vim.api.nvim_win_set_cursor(win, { 1, 0 })
    vim.api.nvim_win_call(win, function() vim.cmd('normal! zt') end)
  end
  vim.api.nvim_create_autocmd('BufWipeout', { buffer = buf, once = true, callback = function()
    if not finished and on_close then on_close() end
    finished = true
  end })
  local function confirm()
    if finished then return end
    if clickable then
      finished = true
      vim.b[buf].model_maven_review_pending = false
      callback(options[2], 2)
      return
    end
    vim.ui.select(options, { prompt = prompt }, function(value, index)
      if finished then return end
      finished = true
      if vim.api.nvim_buf_is_valid(buf) then vim.b[buf].model_maven_review_pending = false end
      callback(value, index)
    end)
  end
  vim.keymap.set('n', 'a', confirm, { buffer = buf, silent = true, desc = 'Continue after reviewing' })
  if clickable then
    vim.api.nvim_buf_set_extmark(buf, builder_buttons, 0, 0, { line_hl_group = 'PmenuSel' })
    vim.api.nvim_buf_set_extmark(buf, builder_buttons, 1, 0, { line_hl_group = 'Pmenu' })
    local function click_review()
      local mouse = vim.fn.getmousepos()
      if mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= buf then return '<LeftMouse>' end
      if mouse.line == 1 then vim.schedule(confirm)
      elseif mouse.line == 2 then vim.schedule(function()
        if vim.api.nvim_win_is_valid(mouse.winid) and vim.api.nvim_win_get_buf(mouse.winid) == buf then
          vim.api.nvim_win_close(mouse.winid, false)
        end
      end)
      else return '<LeftMouse>' end
      return '<Ignore>'
    end
    for _, key in ipairs({ '<LeftMouse>', '<2-LeftMouse>', '<3-LeftMouse>', '<4-LeftMouse>' }) do
      vim.keymap.set('n', key, click_review, { buffer = buf, expr = true, silent = true })
    end
  end
end

local function module_picker(title, rows, choices, callback, on_cancel, select_item)
  local buf = vim.api.nvim_create_buf(false, true)
  vim.b[buf].model_maven_module_navigation = true
  vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
  local instructions = select_item
    and tr('[Enter] Select [/] Search [w] Wrap [q]', '[Enter] 选择 [/] 搜索 [w] 换行 [q]', '[Enter] 選擇 [/] 搜尋 [w] 換行 [q]')
    or tr('[Enter] Details [/] Search [w] Wrap [q]', '[Enter] 详情 [/] 搜索 [w] 换行 [q]', '[Enter] 詳情 [/] 搜尋 [w] 換行 [q]')
  local lines = { title, instructions, '' }
  for index, choice in ipairs(choices) do
    local _, depth = rows[index].path:gsub('%.', '')
    lines[#lines + 1] = string.rep('  ', math.min(depth, 8))
      .. vim.fn.strcharpart(choice:gsub('[\r\n%z\1-\31\127]', ' '), 0, 512)
  end
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
  vim.bo[buf].modifiable = false
  if not open_aux_buffer(buf, false, false) then
    if on_cancel then on_cancel() end
    return
  end
  vim.wo.wrap = false
  vim.keymap.set('n', 'w', function() vim.wo.wrap = not vim.wo.wrap end,
    { buffer = buf, silent = true, desc = 'Toggle list line wrapping' })
  if #choices > 0 then vim.api.nvim_win_set_cursor(0, { 4, 0 }) end
  vim.keymap.set('n', 'q', function()
    local closed = pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false)
    if closed and on_cancel then on_cancel() end
  end, { buffer = buf, silent = true, desc = 'Close module list' })
  vim.keymap.set('n', '<CR>', function()
    local index = vim.api.nvim_win_get_cursor(0)[1] - 3
    if index >= 1 and index <= #rows then callback(nil, index) end
  end, { buffer = buf, silent = true, desc = 'Open module details' })
  local function click_item()
    local mouse = vim.fn.getmousepos()
    local index = mouse.line - 3
    if mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= buf
        or index < 1 or index > #rows then return '<LeftMouse>' end
    vim.schedule(function()
      if vim.api.nvim_win_is_valid(mouse.winid) and vim.api.nvim_win_get_buf(mouse.winid) == buf then
        vim.api.nvim_set_current_win(mouse.winid)
        callback(nil, index)
      end
    end)
    return '<Ignore>'
  end
  for _, key in ipairs({ '<LeftMouse>', '<2-LeftMouse>', '<3-LeftMouse>', '<4-LeftMouse>' }) do
    vim.keymap.set('n', key, click_item, { buffer = buf, expr = true, silent = true })
  end
end

local function browse_modules(state, view)
  local report = state.last and state.last.report
  local data = report and report.data
  local modules = type(data) == 'table' and data.modules
  local observed = false
  if not view and report and report.operation == 'probe' and report.status == 'success'
      and type(data) == 'table' and data.trace_truncated == true
      and type(data.calls) == 'table' and is_list(data.calls)
      and type(modules) == 'table' and is_list(modules)
      and state.last and not (state.last.isolated_variant and state.last.observed_context_changed
        or not state.last.isolated_variant and state.last.context_changed) then
    local listed = state.last
    vim.ui.select({ tr('Observed paths (full trace is truncated)', '已观察路径（全模型调用记录已截断）', '已觀察路徑（全模型呼叫紀錄已截斷）'),
      tr('Reported model structure (not execution evidence)', '报告的模型结构（不代表已执行）', '回報的模型結構（不代表已執行）') }, {
      prompt = tr('Choose paths to browse; later layers may be absent from the observed trace.',
        '选择要浏览的路径；后段层可能未出现在调用记录中。', '選擇要瀏覽的路徑；後段層可能未出現在呼叫紀錄中。'),
    }, function(_, choice)
      if state.closed or state.last ~= listed or (listed.isolated_variant and listed.observed_context_changed)
          or (not listed.isolated_variant and listed.context_changed) then return end
      if choice == 1 then browse_modules(state, 'observed')
      elseif choice == 2 then browse_modules(state, 'structure') end
    end)
    return
  end
  if view ~= 'structure' and report and type(data) == 'table' and report.operation == 'probe'
      and report.status == 'success' and type(data.calls) == 'table' and is_list(data.calls) then
    local inspected = {}
    if type(modules) == 'table' and is_list(modules) then
      for _, module in ipairs(modules) do
        if type(module) == 'table' and type(module.path) == 'string' then
          inspected[module.path] = module
          if type(module.aliases) == 'table' then
            for _, alias in ipairs(module.aliases) do if type(alias) == 'string' then inspected[alias] = module end end
          end
        end
      end
    end
    modules, observed = {}, true
    local by_path = {}
    for call_index, call in ipairs(data.calls) do
      if call_index > 2048 then break end
      if type(call) == 'table' and type(call.paths) == 'table' and is_list(call.paths) then
        local aliases, used = {}, {}
        for _, path in ipairs(call.paths) do
          if type(path) == 'string' and path ~= '' and not used[path] and #aliases < 32 then
            aliases[#aliases + 1], used[path] = path, true
          end
        end
        for _, path in ipairs(aliases) do
          local row = by_path[path]
          if not row and #modules < 2048 then
            row = vim.deepcopy(inspected[path] or {})
            row.path, row.type, row.aliases = path, row.type or call.module_type, row.aliases or aliases
            row.observed_calls, row.observed_only = 0, true
            by_path[path] = row
            modules[#modules + 1] = row
          end
          if row then
            row.observed_calls = row.observed_calls + 1
            local impl = call.implementation
            if type(impl) == 'table' and type(impl.source_file) == 'string' and impl.source_file ~= ''
                and impl.source_file:sub(1, 1) ~= '@' and type(impl.source_sha256) == 'string'
                and #impl.source_sha256 == 64 and impl.source_sha256:match('^[0-9a-f]+$') then
              local source = { path = path, source = impl.source_file, digest = impl.source_sha256,
                line = impl.declaration_line }
              if row.observed_source and (row.observed_source.source ~= source.source
                  or row.observed_source.digest ~= source.digest or row.observed_source.line ~= source.line) then
                row.observed_source_ambiguous = true
              end
              if not row.observed_source_ambiguous then row.observed_source = source end
            else
              row.observed_source_ambiguous = true
              row.observed_source = nil
            end
            if row.observed_source_ambiguous then row.observed_source = nil end
          end
        end
      end
    end
  end
  if state.last and state.last.isolated_variant and not state.last.observed_context_changed
      and modules and is_list(modules) then
    local listed, rows, choices = state.last, {}, {}
    for _, module in ipairs(modules) do
      if #rows >= 2048 then break end
      if type(module) == 'table' and type(module.path) == 'string' then
        rows[#rows + 1] = module
        choices[#choices + 1] = module.path .. ' · ' .. tostring(module.type or '?')
      end
    end
    if #rows == 0 then notify(tr('No modules reported.', '未报告模块。', '未回報模組。'), vim.log.levels.INFO); return end
    module_picker(view == 'structure'
      and tr('Variant reported structure · not execution evidence (up to 2048)',
        '变体报告结构 · 不代表已执行（最多 2048 项）', '變體回報結構 · 不代表已執行（最多 2048 項）')
      or tr('Variant observation · read-only module paths (up to 2048)',
        '变体观察 · 只读模块路径（最多 2048 项）', '變體觀察 · 唯讀模組路徑（最多 2048 項）'), rows, choices, function(_, index)
      local row = index and rows[index]
      if not row or state.closed or state.last ~= listed or listed.observed_context_changed then return end
      local buf = vim.api.nvim_create_buf(false, true)
      vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
      local lines = {
        view == 'structure' and tr('Variant module · reported structure, not execution evidence',
          '变体模块 · 报告结构，不代表已执行', '變體模組 · 回報結構，不代表已執行')
          or tr('Variant module · read-only observation', '变体模块 · 只读观察', '變體模組 · 唯讀觀察'),
        tr('This is separate from the source model; editing starts a new variant preview.',
          '这与源码模型上下文分开；编辑会发起新的变体预览。', '這與原始碼模型上下文分開；編輯會發起新的變體預覽。'),
        listed.variant_context and tr('[e] Preview an edit for this variant path.', '[e] 预览此变体路径的编辑。', '[e] 預覽此變體路徑的編輯。') or '',
        listed.variant_context and row.observed_only and data.forward_execution == 'executed'
          and tr('[t] Mark a port observed on this variant path.', '[t] 标记此变体路径上观察到的端口。', '[t] 標記此變體路徑上觀察到的連接埠。') or '',
        row.observed_source and tr('[g] Open the observed implementation after checking its file identity.',
          '[g] 核对文件身份后打开观察到的实现。', '[g] 核對檔案身分後開啟觀察到的實作。')
          or tr('No unambiguous project-source identity was observed.',
            '未观察到无歧义的项目源码身份。', '未觀察到無歧義的專案原始碼身分。'),
        row.observed_source and tr('Editing the opened file changes project source, not the saved variant recipe.',
          '编辑打开的文件会改变项目源码，不会直接改变已保存的变体配方。',
          '編輯開啟的檔案會改變專案原始碼，不會直接改變已儲存的變體配方。') or '',
        tr('[q] Close', '[q] 关闭', '[q] 關閉'), '',
      }
      vim.list_extend(lines, vim.split(vim.inspect(bounded_summary(row)), '\n', { plain = true }))
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
      vim.bo[buf].modifiable = false
      if open_aux_buffer(buf, false, false) then
        vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close variant module details' })
        if listed.variant_context then
          vim.keymap.set('n', 'e', function()
            local context = listed.variant_context
            if state.closed or state.last ~= listed or listed.observed_context_changed
                or state.opts.project ~= context.project or state.opts.cli ~= context.cli
                or (state.change_epoch or 0) ~= context.epoch then
              notify(tr('The observation changed; run the variant again.', '观察上下文已变化，请重新运行变体。', '觀察上下文已變更，請重新執行變體。'), vim.log.levels.WARN); return
            end
            preview_variant_edit(state, context.name, context.base, context.project, context.epoch, context.cli, row.path, row)
          end, { buffer = buf, silent = true, desc = 'Preview a variant Layer edit' })
          if row.observed_only and data.forward_execution == 'executed' then
            vim.keymap.set('n', 't', function()
              if not state.closed and state.last == listed and not listed.observed_context_changed then
                mark_observed_port(state, row.path)
              end
            end, { buffer = buf, silent = true, desc = 'Mark a port on this variant' })
          end
        end
        if row.observed_source then
          vim.keymap.set('n', 'g', function()
            if state.closed or state.last ~= listed or listed.observed_context_changed then
              notify(tr('The observation changed; run the variant again.', '观察上下文已变化，请重新运行变体。', '觀察上下文已變更，請重新執行變體。'), vim.log.levels.WARN)
              return
            end
            open_verified_implementation(state, row.observed_source, true)
          end, { buffer = buf, silent = true, desc = 'Open observed variant implementation' })
        end
      end
    end)
    return
  end
  if not modules or not is_list(modules) or state.last.context_changed then
    notify(tr('No current module list or forward observations. Inspect or run forward first.',
      '没有当前模块列表或前向观察；请先检查模型或运行前向。', '沒有目前模組列表或前向觀察；請先檢查模型或執行前向。'), vim.log.levels.INFO)
    return
  end
  local rows, choices = {}, {}
  for _, module in ipairs(modules) do
    if #rows >= 2048 then break end
    if type(module) == 'table' and type(module.path) == 'string' then
      rows[#rows + 1] = module
      choices[#choices + 1] = module.path .. '  ·  ' .. tostring(module.type or '?')
    end
  end
  if #rows == 0 then notify('No modules reported.', vim.log.levels.INFO); return end
  local listed = state.last
  local picker_title = observed and tr('Observed module paths (up to 2048; not a complete graph)',
    '已观察模块路径（最多 2048 项；非完整模型图）', '已觀察模組路徑（最多 2048 項；非完整模型圖）')
    or tr('Reported module paths (up to 2048)', '报告中的模块路径（最多 2048 项）', '報告中的模組路徑（最多 2048 項）')
  if observed and (data.forward_execution == 'reused'
      or (type(data.evidence_cache) == 'table' and data.evidence_cache.status == 'reused')) then
    picker_title = picker_title .. tr(' · prior evidence reused', ' · 复用先前证据', ' · 重用先前證據')
  end
  if listed.historical_observation then
    picker_title = picker_title .. tr(' · earlier observation', ' · 先前观察', ' · 先前觀察')
  end
  module_picker(picker_title, rows, choices, function(_, index)
    local row = index and rows[index]
    if not row or state.closed then return end
    if state.last ~= listed or listed.context_changed then
      notify(tr('The module report is no longer current; inspect or run forward again.',
        '模块报告已不是当前结果，请重新检查或前向。', '模組報告已不是目前結果，請重新檢查或前向。'), vim.log.levels.WARN)
      return
    end
    state.last_selection = row.path
    -- A construction site is a reported location, not proof of loaded code.
    -- Match it against an unambiguous observed project-source identity;
    -- the open helper checks that digest again before selecting the line.
    local construction
    local site = row.construction_site
    local provenance = type(data.run_provenance) == 'table' and data.run_provenance.model
    if type(site) == 'table' and type(site.file) == 'string' and type(site.line) == 'number' then
      local root = type(state.opts.project) == 'string' and vim.uv.fs_realpath(state.opts.project) or nil
      local reported = vim.uv.fs_realpath(site.file)
      local conflicting = false
      local resolved_sources = {}
      local function consider(implementation)
        local source = type(implementation) == 'table' and implementation.source_file
        local digest = type(implementation) == 'table' and implementation.source_sha256
        if not root or not reported or type(source) ~= 'string' or source == ''
            or source:sub(1, 1) == '@' or source:sub(1, 1) == '/'
            or source:match('^%a:[/\\]') or type(digest) ~= 'string'
            or #digest ~= 64 or not digest:match('^[0-9a-f]+$') then return end
        if resolved_sources[source] == nil then
          resolved_sources[source] = vim.uv.fs_realpath(root .. '/' .. source) or false
        end
        local candidate = resolved_sources[source]
        if candidate ~= reported then return end
        if construction and construction.digest ~= digest then conflicting = true; return end
        construction = { path = row.path, source = source, digest = digest,
          line = site.line, location_kind = 'construction' }
      end
      consider(type(provenance) == 'table' and provenance.implementation)
      if type(data.calls) == 'table' and is_list(data.calls) then
        for index, call in ipairs(data.calls) do
          if index > 2048 then break end
          if type(call) == 'table' then consider(call.implementation) end
        end
      end
      if conflicting then construction = nil end
    end
    local buf = vim.api.nvim_create_buf(false, true)
    vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
    local lines = {
      tr('Selected model object', '已选择的模型对象', '已選擇的模型物件'),
      listed.historical_observation and tr('Earlier observation; current model behavior was not rechecked.',
        '先前观察；尚未重新检查当前模型行为。', '先前觀察；尚未重新檢查目前模型行為。') or '',
      tr('Path: ', '路径：', '路徑：') .. row.path,
      tr('Type: ', '类型：', '類型：') .. tostring(row.type or '?'),
      tr('Parameters: ', '参数量：', '參數量：') .. (type(row.parameters) == 'number' and tostring(row.parameters)
        or tr('unknown (may be uninitialized)', '未知（可能尚未初始化）', '未知（可能尚未初始化）')),
      tr('Shared aliases: ', '共享别名：', '共享別名：') .. vim.inspect(bounded_summary(row.aliases or {})):gsub('[\r\n]', ' '),
      tr('Editable parameters: ', '可修改参数：', '可修改參數：') .. (row.editable_params ~= nil and row.editable_params ~= vim.NIL
        and vim.inspect(bounded_summary(row.editable_params)):gsub('[\r\n]', ' ') or tr('not reported', '未报告', '未回報')),
      tr('Source edit available: ', '可源码修改：', '可原始碼修改：') .. (type(row.can_source_set) == 'boolean' and tostring(row.can_source_set) or tr('unknown', '未知', '未知')),
      tr('Source insertion available: ', '可源码插入：', '可原始碼插入：') .. (type(row.can_source_insert) == 'boolean' and tostring(row.can_source_insert) or tr('unknown', '未知', '未知')),
      tr('Reason: ', '原因：', '原因：') .. tostring(row.source_set_block_reason ~= vim.NIL and row.source_set_block_reason or '-'),
      row.observed_only and (tr('Recorded calls: ', '已记录调用：', '已記錄呼叫：') .. tostring(row.observed_calls)
        .. tr(' (trace may be truncated)', '（调用记录可能截断）', '（呼叫紀錄可能截斷）')) or '',
      '', tr('[i] Inspect  [L] Local replay  [w] Preview change  [q] Close', '[i] 检查  [L] 局部重放  [w] 预览修改  [q] 关闭', '[i] 檢查  [L] 局部重播  [w] 預覽修改  [q] 關閉'),
      not listed.historical_observation and tr('[W] Plan multiple layer changes from this object',
        '[W] 从此对象开始规划多层修改', '[W] 從此物件開始規劃多層修改') or '',
      not listed.historical_observation and tr('[V] Preview this layer in a new variant (source stays unchanged).',
        '[V] 在新变体中预览此层（不修改源码）。', '[V] 在新變體中預覽此層（不修改原始碼）。') or '',
      row.can_source_set == true and type(row.source_editable_fields) == 'table' and #row.source_editable_fields > 0
        and tr('[c] Change a reported parameter', '[c] 修改报告中的参数', '[c] 修改報告中的參數') or '',
      row.observed_only and data.forward_execution == 'executed' and not listed.historical_observation
        and tr('[t] Mark an observed port on this object', '[t] 标记此对象的已观察端口', '[t] 標記此物件的已觀察連接埠') or '',
      row.observed_source and tr('[g] Open this observed implementation after checking its file identity.',
        '[g] 核对文件身份后打开此观察实现。', '[g] 核對檔案身分後開啟此觀察實作。')
        or (not row.observed_only and tr('This is a reported path; use [L] to observe it, then browse the observed paths for its source.',
          '这是报告的路径；按 [L] 观察后，可在已观察路径中查找其源码。', '這是回報的路徑；按 [L] 觀察後，可在已觀察路徑中尋找其原始碼。')
          or tr('No unambiguous observed project-source identity is available.',
            '没有可用且无歧义的项目源码观察身份。', '沒有可用且無歧義的專案原始碼觀察身分。')),
      construction and tr('[s] Open the reported construction site (which may be a parent or factory call) after checking its file identity.',
        '[s] 核对文件身份后打开报告的构造位置（可能是上层或工厂调用）。', '[s] 核對檔案身分後開啟回報的建構位置（可能是上層或工廠呼叫）。') or '',
      '', tr('Bounded object details; [J] opens the full reported object.',
        '以下为有界对象详情；按 [J] 打开完整对象报告。', '以下為有界物件詳情；按 [J] 開啟完整物件報告。'),
    }
    vim.list_extend(lines, vim.split(vim.inspect(bounded_summary(row)), '\n', { plain = true }))
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
    vim.bo[buf].modifiable = false
    vim.b[buf].model_maven_module_navigation = true
    if not open_aux_buffer(buf, false, false) then return end
    vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close module details' })
    vim.keymap.set('n', 'J', function()
      if state.closed or state.last ~= listed or listed.context_changed then
        notify(tr('This module report is no longer current.', '模块报告已不是当前结果。', '模組報告已不是目前結果。'), vim.log.levels.WARN); return
      end
      local ok, contents = pcall(vim.inspect, row)
      if not ok then
        notify(tr('Could not render the full object.', '无法显示完整对象。', '無法顯示完整物件。'), vim.log.levels.WARN); return
      end
      local full = vim.api.nvim_create_buf(false, true)
      vim.bo[full].buftype, vim.bo[full].bufhidden, vim.bo[full].swapfile = 'nofile', 'wipe', false
      vim.api.nvim_buf_set_lines(full, 0, -1, false, vim.split(contents, '\n', { plain = true }))
      vim.bo[full].modifiable = false
      if not open_aux_buffer(full, false, false) then return end
      vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = full, silent = true, desc = 'Close full module object' })
    end, { buffer = buf, silent = true, desc = 'Open full module object' })
    local function current_selection()
      if state.closed or state.last ~= listed or listed.context_changed then
        notify(tr('This module report is no longer current. Inspect or run forward again.',
          '此模块报告已不是当前结果，请重新检查或前向。', '此模組報告已不是目前結果，請重新檢查或前向。'), vim.log.levels.WARN)
        return false
      end
      return true
    end
    vim.keymap.set('n', 'i', function()
      if current_selection() then run(state, tr('Inspect selected layer', '检查所选层', '檢查所選層'), { 'layer', 'show', row.path }) end
    end, { buffer = buf, silent = true, desc = 'Inspect selected layer' })
    vim.keymap.set('n', 'w', function()
      if current_selection() then state.last_selection = row.path; preview_layer(state, row.path, row.observed_source or construction) end
    end, { buffer = buf, silent = true, desc = 'Preview selected layer change' })
    vim.keymap.set('n', 'L', function()
      if current_selection() then state.last_selection = row.path; probe_local(state) end
    end, { buffer = buf, silent = true, desc = 'Replay selected layer' })
    if not listed.historical_observation then
      vim.keymap.set('n', 'W', function()
        if current_selection() then state.last_selection = row.path; compose_layer_transaction(state) end
      end, { buffer = buf, silent = true, desc = 'Plan multiple layer changes from selected object' })
    end
    if not listed.historical_observation then
      vim.keymap.set('n', 'V', function()
        if not current_selection() then return end
        local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
        vim.ui.input({ prompt = tr('New variant name (letters, digits, _ or -): ',
          '新变体名称（字母、数字、_ 或 -）：', '新變體名稱（字母、數字、_ 或 -）：') }, function(name)
          if not name or name == '' or not current_selection() or state.busy
              or state.opts.project ~= project or state.opts.cli ~= cli
              or (state.change_epoch or 0) ~= epoch then return end
          if #name > 64 or not name:match('^[A-Za-z0-9_-]+$') then
            notify(tr('Invalid variant name.', '变体名称无效。', '變體名稱無效。'), vim.log.levels.WARN); return
          end
          preview_variant_edit(state, name, { token = 'absent' }, project, epoch, cli, row.path, row)
        end)
      end, { buffer = buf, silent = true, desc = 'Preview selected layer in a new variant' })
    end
    if row.observed_only and data.forward_execution == 'executed' and not listed.historical_observation then
      vim.keymap.set('n', 't', function()
        if current_selection() then mark_observed_port(state, row.path) end
      end, { buffer = buf, silent = true, desc = 'Mark selected module port' })
    end
    if row.can_source_set == true and type(row.source_editable_fields) == 'table' and #row.source_editable_fields > 0 then
      vim.keymap.set('n', 'c', function()
        if current_selection() then edit_reported_parameter(state, row, current_selection) end
      end, { buffer = buf, silent = true, desc = 'Change a reported parameter' })
    end
    if row.observed_source then
      vim.keymap.set('n', 'g', function()
        if current_selection() then open_verified_implementation(state, row.observed_source) end
      end, { buffer = buf, silent = true, desc = 'Open observed implementation' })
    end
    if construction then
      vim.keymap.set('n', 's', function()
        if current_selection() then open_verified_implementation(state, construction) end
      end, { buffer = buf, silent = true, desc = 'Open reported construction site' })
    end
  end)
end

focus_source = function(state, path)
  local target = vim.fn.bufnr(path)
  local tab = vim.api.nvim_get_current_tabpage()
  if target ~= -1 then
    for _, win in ipairs(vim.fn.win_findbuf(target)) do
      if vim.api.nvim_win_is_valid(win) and vim.api.nvim_win_get_tabpage(win) == tab then
        vim.api.nvim_set_current_win(win)
        state.code_win = win
        return true
      end
    end
  end
  local has_code_window = state.code_win and vim.api.nvim_win_is_valid(state.code_win)
      and vim.api.nvim_win_get_tabpage(state.code_win) == tab
  if has_code_window then
    vim.api.nvim_set_current_win(state.code_win)
  end
  local current = vim.api.nvim_get_current_buf()
  if state.single_panel and state.code_win == state.panel_win and current == state.panel then
    state.panel_view = vim.fn.winsaveview()
    local ok, err = pcall(vim.cmd, 'hide edit ' .. vim.fn.fnameescape(path))
    if not ok then
      notify(tr('Could not open source: ', '无法打开源码：', '無法開啟原始碼：') .. tostring(err), vim.log.levels.ERROR)
      return false
    end
    if state.code_wrap ~= nil then vim.wo[state.code_win].wrap = state.code_wrap end
    state.code_buf = vim.api.nvim_get_current_buf()
    state.code_view = vim.fn.winsaveview()
    return true
  end
  -- Reuse the source window for ordinary, unmodified files. Neovim retains
  -- those buffers and their history; never replace a modified or special
  -- buffer, or one configured to be deleted when hidden.
  local empty = vim.api.nvim_buf_get_name(current) == '' and not vim.bo[current].modified
    and vim.bo[current].buftype == '' and vim.api.nvim_buf_line_count(current) == 1
    and vim.api.nvim_buf_get_lines(current, 0, 1, false)[1] == ''
  local reusable = has_code_window and not vim.bo[current].modified and vim.bo[current].buftype == ''
    and (vim.bo[current].bufhidden == '' or vim.bo[current].bufhidden == 'hide')
  local split_win
  if not empty and not reusable then
    -- Narrow terminals or an existing window layout may not permit another
    -- column. Preserve the current buffer and try a horizontal split before
    -- reporting that navigation needs more space.
    local split_ok, split_error = pcall(vim.cmd, 'leftabove vsplit')
    if not split_ok then split_ok, split_error = pcall(vim.cmd, 'leftabove split') end
    if not split_ok then
      notify(tr('Could not open another source window; enlarge the terminal or close a window: ',
        '无法打开额外的源码窗口；请放大终端或关闭一个窗口：',
        '無法開啟額外的原始碼視窗；請放大終端或關閉一個視窗：') .. tostring(split_error), vim.log.levels.WARN)
      return false
    end
    split_win = vim.api.nvim_get_current_win()
  end
  local ok, err
  if reusable and not empty then
    -- :hide keeps this buffer loaded even when the user's 'hidden' option is
    -- off, without changing that option for their other windows.
    ok, err = pcall(vim.cmd, 'hide edit ' .. vim.fn.fnameescape(path))
  else
    ok, err = pcall(vim.cmd.edit, vim.fn.fnameescape(path))
  end
  if not ok then
    -- Remove only the window created for this failed navigation. Any buffer
    -- changed by user autocommands remains under Neovim's normal ownership.
    if split_win and vim.api.nvim_win_is_valid(split_win) then pcall(vim.api.nvim_win_close, split_win, false) end
    notify(tr('Could not open source: ', '无法打开源码：', '無法開啟原始碼：') .. tostring(err), vim.log.levels.ERROR)
    return false
  end
  state.code_win = vim.api.nvim_get_current_win()
  return true
end

local function offer_buffer_recovery(state, paths, prompt)
  local project = state.opts.project
  vim.ui.select(paths, { prompt = prompt }, function(path)
    if not path or state.closed or state.opts.project ~= project or not in_project(project, path) then return end
    if focus_source(state, path) then
      local buf = vim.api.nvim_get_current_buf()
      local name = vim.api.nvim_buf_get_name(buf)
      if not vim.bo[buf].modified then
        local tick = vim.api.nvim_buf_get_changedtick(buf)
        vim.ui.select({ tr('Inspect source first', '先查看源码', '先檢視原始碼'),
          tr('Reload this unmodified buffer from disk', '从磁盘重新载入此未修改的 buffer', '從磁碟重新載入此未修改的 buffer') }, {
          prompt = tr('This buffer may differ from disk. Choose how to reconcile it:',
            '此 buffer 可能与磁盘内容不同，请选择处理方式：', '此 buffer 可能與磁碟內容不同，請選擇處理方式：'),
        }, function(_, choice)
          if choice ~= 2 then return end
          if state.closed or state.opts.project ~= project or not vim.api.nvim_buf_is_valid(buf)
              or not vim.api.nvim_buf_is_loaded(buf) or vim.api.nvim_buf_get_name(buf) ~= name
              or vim.bo[buf].modified
              or vim.api.nvim_buf_get_changedtick(buf) ~= tick then
            notify(tr('Buffer or project changed; inspect it before reloading.',
              'buffer 或项目已变化，请先检查再重新载入。', 'buffer 或專案已變更，請先檢查再重新載入。'), vim.log.levels.WARN)
            return
          end
          local ok, err = pcall(vim.api.nvim_buf_call, buf, function() vim.cmd('edit') end)
          if not ok then notify(tr('Could not reload source: ', '无法重新载入源码：', '無法重新載入原始碼：') .. tostring(err), vim.log.levels.ERROR) end
        end)
      else
        notify(tr('Inspect and reconcile this buffer yourself, then return to the panel and retry. Nothing was saved automatically.',
          '请自行检查并处理此 buffer，然后返回面板重试；工具没有自动保存。',
          '請自行檢查並處理此 buffer，然後返回面板重試；工具沒有自動儲存。'), vim.log.levels.INFO)
      end
    end
  end)
end

local function verified_source_path(state, selected, quiet)
  local function reject(message)
    if not quiet then notify(message, vim.log.levels.WARN) end
  end
  if type(selected) ~= 'table' or type(selected.path) ~= 'string' or type(selected.source) ~= 'string'
      or type(selected.digest) ~= 'string' or #selected.digest ~= 64 or not selected.digest:match('^[0-9a-f]+$') then
    return reject('No verifiable implementation identity was recorded.')
  end
  local root = vim.uv.fs_realpath(state.opts.project)
  local relative = selected.source
  if not root or relative:sub(1, 1) == '/' or relative:match('^%a:[/\\]') then
    return reject('Implementation path cannot be verified within this project.')
  end
  local actual = vim.uv.fs_realpath(root .. '/' .. relative)
  if not actual or not vim.startswith(vim.fs.normalize(actual), vim.fs.normalize(root):gsub('/+$', '') .. '/') then
    return reject('Implementation is outside the project or is unavailable.')
  end
  local stat = vim.uv.fs_stat(actual)
  if not stat or stat.type ~= 'file' or stat.size > 4 * 1024 * 1024 then
    return reject('Implementation cannot be safely verified.')
  end
  local matching_buffers = {}
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) then
      local name = vim.api.nvim_buf_get_name(buf)
      local resolved = name ~= '' and vim.uv.fs_realpath(name) or nil
      if resolved and vim.fs.normalize(resolved) == vim.fs.normalize(actual) then
        if vim.bo[buf].modified then
          return reject(tr('An open buffer for this source has unsaved edits; reconcile it before locating: ',
            '该源码的一个已打开 buffer 有未保存修改；定位前请处理：', '該原始碼的一個已開啟 buffer 有未儲存修改；定位前請處理：')
            .. vim.fn.strcharpart(name:gsub('[%c]', ' '), 0, 512))
        end
        matching_buffers[#matching_buffers + 1] = buf
      end
    end
  end
  local file = io.open(actual, 'rb')
  if not file then return reject('Cannot read implementation source.') end
  local contents = file:read(4 * 1024 * 1024 + 1) or ''
  file:close()
  if #contents > 4 * 1024 * 1024 or vim.fn.sha256(contents) ~= selected.digest then
    return reject('Implementation changed since the forward pass; run it again before locating.')
  end
  for _, buf in ipairs(matching_buffers) do
    if not vim.api.nvim_buf_is_loaded(buf) or vim.bo[buf].modified then
      return reject('An open source buffer changed during verification; reconcile it before locating.')
    end
    local encoding = vim.bo[buf].fileencoding
    local format = vim.bo[buf].fileformat
    if (encoding ~= '' and encoding:lower() ~= 'utf-8')
        or (format ~= 'unix' and format ~= 'dos' and format ~= 'mac') then
      return reject('An open buffer encoding or line format cannot be compared to the observed source.')
    end
    local separator = format == 'dos' and '\r\n' or (format == 'mac' and '\r' or '\n')
    local buffer_text = table.concat(vim.api.nvim_buf_get_lines(buf, 0, -1, false), separator)
    if vim.bo[buf].endofline then buffer_text = buffer_text .. separator end
    if vim.bo[buf].bomb then buffer_text = '\239\187\191' .. buffer_text end
    if buffer_text ~= contents then
      return reject('An open buffer for this file differs from disk; reconcile it before locating.')
    end
  end
  return actual, contents
end

-- Track only project files for which the worker reported an implementation
-- identity. External libraries and unobserved branches remain untracked.
local function observed_source_stats(project, report)
  local calls = type(report) == 'table' and type(report.data) == 'table' and report.data.calls
  local root = vim.uv.fs_realpath(project)
  if not root or type(calls) ~= 'table' then return nil end
  local prefix = vim.fs.normalize(root):gsub('/+$', '') .. '/'
  local result, count = {}, 0
  for _, call in ipairs(calls) do
    local impl = type(call) == 'table' and call.implementation
    local name = type(impl) == 'table' and impl.source_file
    if type(name) == 'string' and type(impl.source_sha256) == 'string'
        and impl.source_sha256:match('^[0-9a-f]+$') and #impl.source_sha256 == 64
        and name:sub(1, 1) ~= '/' and not name:match('^%a:[/\\]') then
      local path = vim.uv.fs_realpath(root .. '/' .. name)
      if path and vim.startswith(vim.fs.normalize(path), prefix) and not result[path] then
        local stat = vim.uv.fs_stat(path)
        if stat and stat.type == 'file' then
          result[path] = { size = stat.size, dev = stat.dev, ino = stat.ino, mtime = stat.mtime, ctime = stat.ctime }
          count = count + 1
          if count >= 128 then break end
        end
      end
    end
  end
  return result
end

local function observed_sources_changed(sources)
  for path, previous in pairs(sources or {}) do
    local stat = vim.uv.fs_stat(path)
    local current = stat and stat.type == 'file' and { size = stat.size, dev = stat.dev, ino = stat.ino,
      mtime = stat.mtime, ctime = stat.ctime } or nil
    if not vim.deep_equal(previous, current) then return true end
  end
  return false
end

export_failure_locations = function(state, frames, displayed)
  local win = state.code_win
  if not win or not vim.api.nvim_win_is_valid(win) or vim.api.nvim_win_get_tabpage(win) ~= state.tab then
    notify(tr('Open a project source window first; [g] opens one recorded frame.',
      '请先打开项目源码窗口；可用 [g] 打开一个记录的位置。',
      '請先開啟專案原始碼視窗；可用 [g] 開啟一個記錄的位置。'), vim.log.levels.WARN); return
  end
  local items, skipped = {}, 0
  for _, frame in ipairs(frames) do
    local actual, contents = verified_source_path(state, { path = '', source = frame.file, digest = frame.source_sha256 }, true)
    local count = 0
    if contents then
      local separator = contents:find('\n', 1, true) and '\n' or '\r'
      local ignored
      ignored, count = contents:gsub(separator, '')
    end
    if actual and frame.line <= count + 1 then
      local name = vim.fn.strcharpart(tostring(frame['function'] or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 120)
      items[#items + 1] = { filename = actual, lnum = frame.line, col = 1,
        text = 'Observed stack frame: ' .. name .. ' (not necessarily the cause)' }
    else
      skipped = skipped + 1
    end
  end
  if #items == 0 then
    notify(tr('No recorded frames match the current source; run forward again.',
      '没有记录的位置与当前源码匹配，请重新前向。', '沒有記錄的位置與目前原始碼相符，請重新前向。'), vim.log.levels.WARN); return
  end
  if state.closed or state.last ~= displayed or displayed.context_changed or not vim.api.nvim_win_is_valid(win) then return end
  local ok, result = pcall(vim.fn.setloclist, win, {}, ' ', {
    title = tr('Model Maven: observed stack (snapshot, not necessarily cause)',
      'Model Maven：观察到的调用栈（快照，不一定是根因）', 'Model Maven：觀察到的呼叫堆疊（快照，不一定是根因）'), items = items,
  })
  if not ok or result ~= 0 then
    notify(tr('Could not create the source window location list.', '无法创建源码窗口位置列表。', '無法建立原始碼視窗位置清單。'), vim.log.levels.WARN); return
  end
  notify(tr('Location list created; use :lopen in the source window. Files may change afterwards. Skipped: ',
    '已创建位置列表；在源码窗口使用 :lopen。文件之后可能变化。跳过：',
    '已建立位置清單；在原始碼視窗使用 :lopen。檔案之後可能變更。略過：') .. skipped, vim.log.levels.INFO)
end

open_verified_implementation = function(state, selected, separate_observation)
  local actual = verified_source_path(state, selected, false)
  if not actual then return end
  if not separate_observation and selected.path ~= '' then state.last_selection = selected.path end
  if not focus_source(state, actual) then return end
  -- Opening a buffer may run user autocommands, and the file may change
  -- between the first digest check and the edit. Recheck both the selected
  -- source and the buffer actually focused before trusting a recorded line.
  local focused_name = vim.api.nvim_buf_get_name(0)
  local focused_path = focused_name ~= '' and vim.uv.fs_realpath(focused_name) or nil
  local rechecked = verified_source_path(state, selected, true)
  if not rechecked or rechecked ~= actual or focused_path ~= actual then
    notify(tr('Source or focus changed while opening; no recorded line was selected. Inspect the buffer and recheck.',
      '打开期间源码或焦点发生变化，未定位记录的行；请检查 buffer 并重新验证。',
      '開啟期間原始碼或焦點發生變化，未定位記錄的行；請檢查 buffer 並重新驗證。'), vim.log.levels.WARN)
    return
  end
  -- The source window is underneath our auxiliary floats. Once navigation is
  -- verified, dismiss only these read-only views; the report remains available
  -- from the workspace and user buffers or pending reviews are never closed.
  for _, win in ipairs(vim.api.nvim_tabpage_list_wins(0)) do
    if win ~= vim.api.nvim_get_current_win() and vim.api.nvim_win_is_valid(win) then
      local buf = vim.api.nvim_win_get_buf(win)
      if (vim.b[buf].model_maven_module_navigation or buf == state.report_buf)
          and not vim.bo[buf].modified and not vim.b[buf].model_maven_review_pending then
        pcall(vim.api.nvim_win_close, win, false)
      end
    end
  end
  local line = selected.line
  if type(line) == 'number' and line == math.floor(line) and line >= 1
      and line <= vim.api.nvim_buf_line_count(0) then
    -- API cursor moves do not set Vim's previous-context mark. Keep normal
    -- editor navigation available without installing a user key mapping.
    local remembered = pcall(vim.cmd, "normal! m'")
    vim.api.nvim_win_set_cursor(0, { line, 0 })
    if selected.location_kind == 'traceback' then
      notify(tr('Opened the recorded stack line. The file was identified after the error and may differ from loaded code.',
        '已打开记录的调用栈行；文件身份在报错后采集，可能与已加载代码不同。',
        '已開啟記錄的呼叫堆疊行；檔案身分在錯誤後擷取，可能與已載入程式碼不同。'), vim.log.levels.INFO)
    elseif selected.location_kind == 'generated' then
      notify(tr('Opened the matching generated constructor; nested layers may share this line. The model has not necessarily run.',
        '已打开对应的生成构造代码；嵌套层可能共用此行。模型不一定已经运行。',
        '已開啟對應的產生建構程式碼；巢狀層可能共用此行。模型不一定已經執行。'), vim.log.levels.INFO)
    elseif selected.location_kind == 'construction' then
      notify(tr('Opened the reported construction site; it may be a parent or factory call. Dynamic code may differ from the loaded model.',
        '已打开报告的构造位置；它可能是上层或工厂调用，动态代码也可能与已加载的模型不同。',
        '已開啟回報的建構位置；它可能是上層或工廠呼叫，動態程式碼也可能與已載入的模型不同。'), vim.log.levels.INFO)
    else
      notify(tr('Opened the matching class declaration. Dynamic redefinition means it may not be the code that executed.',
        '已打开匹配的类声明。动态重定义可能使它并非实际执行的代码。',
        '已開啟相符的類別宣告。動態重新定義可能使它並非實際執行的程式碼。'), vim.log.levels.INFO)
    end
    if remembered then
      notify(tr("Use '' to return to the earlier cursor position in this file.",
        "按 '' 可返回此文件先前的光标位置。", "按 '' 可返回此檔案先前的游標位置。"), vim.log.levels.INFO)
    end
  else
    if selected.location_kind == 'traceback' then
      notify(tr('Opened the file, but the recorded stack line is unavailable.',
        '已打开文件，但记录的调用栈行不可用。', '已開啟檔案，但記錄的呼叫堆疊行無法使用。'), vim.log.levels.WARN)
    else
      notify(tr('Opened the observed source file; no unambiguous declaration was found.',
        '已打开观察到的源码文件；未找到无歧义的声明。',
        '已開啟觀察到的原始碼檔案；未找到無歧義的宣告。'), vim.log.levels.INFO)
    end
  end
end

local function open_observed_source(state)
  local observed = state.last
  local report = observed and observed.report
  local calls = report and report.operation == 'probe' and type(report.data) == 'table' and report.data.calls
  if not calls or not is_list(calls) or observed.context_changed then
    notify(tr('Run a current forward pass first.', '请先执行当前模型的前向。', '請先執行目前模型的前向。'), vim.log.levels.WARN)
    return
  end
  local choices, rows, seen, aliases_omitted = {}, {}, {}, false
  for _, call in ipairs(calls) do
    local impl = type(call) == 'table' and call.implementation
    local paths = type(call) == 'table' and type(call.paths) == 'table' and call.paths or {}
    if type(impl) == 'table' and type(impl.source_file) == 'string'
        and impl.source_file:sub(1, 1) ~= '@' and type(impl.source_sha256) == 'string'
        and #impl.source_sha256 == 64 and impl.source_sha256:match('^[0-9a-f]+$') then
      for index, path in ipairs(paths) do
        if index > 128 then aliases_omitted = true; break end
        local line = type(impl.declaration_line) == 'number' and tostring(impl.declaration_line) or '?'
        local qualified = type(impl.qualified_type) == 'string' and impl.qualified_type or '?'
        local key = type(path) == 'string' and (path .. '\0' .. impl.source_file .. '\0' .. impl.source_sha256 .. '\0' .. line .. '\0' .. qualified) or nil
        if key and not seen[key] then
          seen[key] = true
          rows[#rows + 1] = { path = path, source = impl.source_file, digest = impl.source_sha256,
            line = impl.declaration_line }
          choices[#choices + 1] = path .. '  ·  ' .. impl.source_file .. ':' .. line .. '  ·  ' .. qualified .. '  ·  ' .. impl.source_sha256:sub(1, 12)
        end
      end
    end
  end
  if #rows == 0 then notify('No project-source implementation with a content identity was reported.', vim.log.levels.INFO); return end
  vim.ui.select(choices, { prompt = tr('Choose an observed implementation', '选择已观察的实现', '選擇已觀察的實作')
    .. (aliases_omitted and tr(' (first 128 aliases per call)', '（每次调用最多列出 128 个别名）', '（每次呼叫最多列出 128 個別名）') or '') }, function(_, index)
    local selected = index and rows[index]
    if not selected or state.closed or state.last ~= observed or observed.context_changed then return end
    open_verified_implementation(state, selected)
  end)
end

local function browse_tensor_links(state)
  local listed = state.last
  local report = listed and listed.report
  local data = report and report.data
  local trace = type(data) == 'table' and data.tensor_identity_trace
  if not listed or listed.context_changed or not report or type(data) ~= 'table' or report.operation ~= 'probe' or report.status ~= 'success'
      or type(data.calls) ~= 'table' or not is_list(data.calls) or type(trace) ~= 'table'
      or trace.kind ~= 'same_tensor_object_and_version' then
    notify(tr('Run a current forward with tensor identity evidence first.', '请先运行带张量身份证据的当前前向。', '請先執行帶張量身分證據的目前前向。'), vim.log.levels.INFO)
    return
  end
  local by_id, edges, missing, unreadable, truncated, units = {}, {}, 0, 0, false, 0
  for index, call in ipairs(data.calls) do
    if index > 2048 then truncated = true; break end
    if type(call) == 'table' and type(call.invocation_id) == 'string' then
      local id = call.invocation_id
      if by_id[id] ~= nil then by_id[id] = false else by_id[id] = call end
    end
  end
  for index, target in ipairs(data.calls) do
    if index > 2048 or #edges >= 512 or units >= 8192 then truncated = true; break end
    if type(target) == 'table' and type(target.invocation_id) == 'string' and by_id[target.invocation_id] == target
        and type(target.paths) == 'table' and type(target.paths[1]) == 'string'
        and type(target.input_tensor_matches) == 'table' and is_list(target.input_tensor_matches) then
      for _, match in ipairs(target.input_tensor_matches) do
        units = units + 1
        if #edges >= 512 or units >= 8192 then truncated = true; break end
        if type(match) == 'table' and type(match.input_path) == 'string'
            and type(match.prior_outputs) == 'table' and is_list(match.prior_outputs) then
          for _, prior in ipairs(match.prior_outputs) do
            units = units + 1
            if #edges >= 512 or units > 8192 then truncated = true; break end
            local source = type(prior) == 'table' and type(prior.invocation_id) == 'string' and by_id[prior.invocation_id] or nil
            if type(source) == 'table' and type(source.paths) == 'table' and type(source.paths[1]) == 'string'
                and type(prior.output_path) == 'string' then
              edges[#edges + 1] = { source = source, target = target, output = prior.output_path, input = match.input_path }
            else
              missing = missing + 1
            end
          end
        else
          unreadable = unreadable + 1
        end
      end
    else
      unreadable = unreadable + 1
    end
  end
  local function clean(value)
    return vim.fn.strcharpart(tostring(value or '?'), 0, 160):gsub('[\r\n%z\1-\31\127]', ' ')
  end
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
  local function flag(value)
    return type(value) == 'boolean' and tostring(value) or tr('unknown', '未知', '未知')
  end
  local lines = {
    listed.historical_observation and tr('Earlier observed tensor links', '先前观察的张量连接', '先前觀察的張量連結')
      or tr('Observed tensor links', '已观察的张量连接', '已觀察的張量連結'),
    tr('Same Tensor object/version; first alias shown, others selectable. Partial evidence, not a complete graph or causal proof.',
      '仅表示同一 Tensor 对象及版本；列表显示首个别名，可选择其他别名。是部分证据，不是完整图或因果证明。',
      '僅表示同一 Tensor 物件及版本；清單顯示首個別名，可選擇其他別名。是部分證據，不是完整圖或因果證明。'),
    tr('[Enter] Choose endpoint  [g] Graph/list  [/] Search  [q] Close',
      '[Enter] 选择端点  [g] 图/列表  [/] 搜索  [q] 关闭', '[Enter] 選擇端點  [g] 圖/清單  [/] 搜尋  [q] 關閉'),
    tr('Missing/ambiguous sources: ', '来源未记录或有歧义：', '來源未記錄或有歧義：') .. missing
      .. tr(' · unreadable entries: ', ' · 不可读取条目：', ' · 無法讀取的項目：') .. unreadable
      .. tr(' · workspace limit: ', ' · 工作区截断：', ' · 工作區截斷：') .. tostring(truncated)
      .. tr(' · tensor trace truncated: ', ' · 张量跟踪截断：', ' · 張量追蹤截斷：') .. flag(trace.truncated)
      .. tr(' · call trace truncated: ', ' · 调用跟踪截断：', ' · 呼叫追蹤截斷：') .. flag(data.trace_truncated)
      .. ((data.forward_execution == 'executed'
          and not (type(data.evidence_cache) == 'table' and data.evidence_cache.status == 'reused'))
        and '' or tr(' · execution not confirmed fresh', ' · 未确认本次新执行', ' · 未確認本次新執行')),
  }
  local headers, mode, line_to_edge = lines, 'graph', {}
  local function draw_links(selected)
    local rendered, mapping, selected_line = vim.deepcopy(headers), {}, nil
    rendered[1] = rendered[1] .. (mode == 'graph'
      and tr(' · graph (grouped by source, not execution order)', ' · 图（按来源分组，不代表执行顺序）', ' · 圖（按來源分組，不代表執行順序）')
      or tr(' · list', ' · 列表', ' · 清單'))
    if #edges == 0 then
      rendered[#rendered + 1] = tr('No resolvable recorded links; this does not mean the model has no connections.',
        '没有可解析的已记录连接；这不代表模型没有连接。', '沒有可解析的已記錄連結；這不代表模型沒有連結。')
    end
    if mode == 'graph' then
      local groups, by_source = {}, {}
      for index, edge in ipairs(edges) do
        local id = edge.source.invocation_id
        local group = by_source[id]
        if not group then
          group = { source = edge.source, indices = {} }
          by_source[id] = group
          groups[#groups + 1] = group
        end
        group.indices[#group.indices + 1] = index
      end
      for _, group in ipairs(groups) do
        rendered[#rendered + 1] = clean(group.source.paths[1]) .. '#' .. clean(group.source.invocation_index)
        for position, index in ipairs(group.indices) do
          local edge = edges[index]
          local target = clean(edge.target.paths[1]) .. '#' .. clean(edge.target.invocation_index)
          local branch = position < #group.indices and '├─ ' or '└─ '
          rendered[#rendered + 1] = '  ' .. branch .. clean(edge.output) .. ' → ' .. target .. ' ' .. clean(edge.input)
          mapping[#rendered] = index
          if index == (selected or 1) then selected_line = #rendered end
        end
      end
    else
      for index, edge in ipairs(edges) do
        local source = clean(edge.source.paths[1]) .. '#' .. clean(edge.source.invocation_index)
        local target = clean(edge.target.paths[1]) .. '#' .. clean(edge.target.invocation_index)
        rendered[#rendered + 1] = source .. ' ' .. clean(edge.output) .. '  →  ' .. target .. ' ' .. clean(edge.input)
        mapping[#rendered] = index
        if index == (selected or 1) then selected_line = #rendered end
      end
    end
    vim.bo[buf].modifiable = true
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, rendered)
    vim.bo[buf].modifiable = false
    line_to_edge = mapping
    return selected_line
  end
  local first_line = draw_links()
  if not open_aux_buffer(buf, false, false) then return end
  vim.wo.wrap = false
  if first_line then vim.api.nvim_win_set_cursor(0, { first_line, 0 }) end
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close tensor links' })
  vim.keymap.set('n', 'g', function()
    local selected = line_to_edge[vim.api.nvim_win_get_cursor(0)[1]] or 1
    mode = mode == 'graph' and 'list' or 'graph'
    local line = draw_links(selected)
    if line then vim.api.nvim_win_set_cursor(0, { line, 0 }) end
  end, { buffer = buf, silent = true, desc = 'Toggle tensor graph and list' })
  local function activate_edge(index)
    local edge = edges[index]
    if not edge or state.closed then return end
    if state.last ~= listed or listed.context_changed then
      notify(tr('This observation is stale; run forward again.', '观察结果已过期，请重新前向。', '觀察結果已過期，請重新前向。'), vim.log.levels.WARN); return
    end
    vim.ui.select({ tr('Source module', '来源模块', '來源模組'), tr('Destination module', '目标模块', '目標模組') },
      { prompt = tr('Choose an endpoint', '选择端点', '選擇端點') }, function(_, side)
      local call = side == 1 and edge.source or (side == 2 and edge.target or nil)
      if not call or state.closed or state.last ~= listed or listed.context_changed then return end
      local aliases, seen = {}, {}
      for index, path in ipairs(call.paths) do
        if index > 128 then break end
        if type(path) == 'string' and path ~= '' and not seen[path] then aliases[#aliases + 1] = path; seen[path] = true end
      end
      if #aliases == 0 then return end
      local function choose_action(path)
      if not path or state.closed or state.last ~= listed or listed.context_changed then return end
      local impl = call.implementation
      local choices = { tr('Inspect current module', '检查当前模块', '檢查目前模組'),
        tr('Preview source change', '预览源码修改', '預覽原始碼修改') }
      local batch_action
      if not listed.historical_observation and not listed.isolated_variant then
        choices[#choices + 1] = tr('Plan multiple layer changes from here', '从这里规划多层修改', '從這裡規劃多層修改')
        batch_action = #choices
      end
      local source_action, selected_source
      if type(impl) == 'table' and type(impl.source_file) == 'string' and impl.source_file ~= ''
          and impl.source_file:sub(1, 1) ~= '@' and type(impl.source_sha256) == 'string'
          and #impl.source_sha256 == 64 and impl.source_sha256:match('^[0-9a-f]+$') then
        selected_source = { path = path, source = impl.source_file,
          digest = impl.source_sha256, line = impl.declaration_line }
        choices[#choices + 1] = tr('Open recorded implementation', '打开记录的实现', '開啟記錄的實作')
        source_action = #choices
      end
      local project_source_action
      if state.actions and state.actions.o then
        choices[#choices + 1] = tr('Open project source editor', '打开项目源码编辑器', '開啟專案原始碼編輯器')
        project_source_action = #choices
      end
      local supervision_action
      if not listed.historical_observation and not listed.isolated_variant then
        choices[#choices + 1] = tr('Inspect this port and its supervision', '查看此端口及其监督', '查看此連接埠及其監督')
        supervision_action = #choices
      end
      vim.ui.select(choices, { prompt = path }, function(_, action)
        if not action or state.closed or state.last ~= listed or listed.context_changed then return end
        state.last_selection = path
        if action == 1 then run(state, tr('Inspect selected layer', '检查所选层', '檢查所選層'), { 'layer', 'show', path })
        elseif action == 2 then preview_layer(state, path, selected_source)
        elseif action == batch_action then compose_layer_transaction(state)
        elseif action == source_action then open_verified_implementation(state, selected_source)
        elseif action == project_source_action and state.actions and state.actions.o then state.actions.o()
        elseif action == supervision_action and state.actions and state.actions['6'] then
          state.actions['6']({ path = path, port = side == 1 and edge.output or edge.input })
        end
      end)
      end
      if #aliases == 1 then choose_action(aliases[1])
      else vim.ui.select(aliases, { prompt = tr('Choose a recorded alias (first 128)', '选择已记录别名（最多前 128 个）', '選擇已記錄別名（最多前 128 個）') }, choose_action) end
    end)
  end
  vim.keymap.set('n', '<CR>', function()
    activate_edge(line_to_edge[vim.api.nvim_win_get_cursor(0)[1]])
  end, { buffer = buf, silent = true, desc = 'Choose tensor link endpoint' })
  vim.keymap.set('n', '<LeftMouse>', function()
    local mouse = vim.fn.getmousepos()
    local index = line_to_edge[mouse.line]
    if not index or mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= buf then return '<LeftMouse>' end
    vim.schedule(function()
      if vim.api.nvim_win_is_valid(mouse.winid) and vim.api.nvim_win_get_buf(mouse.winid) == buf then
        vim.api.nvim_set_current_win(mouse.winid)
        activate_edge(index)
      end
    end)
    return '<Ignore>'
  end, { buffer = buf, expr = true, silent = true })
end

run = function(state, title, args, on_result, write_effect, no_context, before_start, on_abort, fresh_forward, selection_checked, python_hint)
  local isolated_variant = vim.tbl_contains(args, '--variant')
  local runtime_check = args[1] == 'doctor' or (args[1] == 'env'
    and vim.tbl_contains({ 'check', 'libraries', 'devices', 'probe' }, args[2]))
  local function abort()
    if on_abort then on_abort() end
  end
  if state.busy then
    notify(tr('Model-Maven: an operation is already running.', 'Model-Maven：已有操作正在运行。', 'Model-Maven：已有操作正在執行。'), vim.log.levels.WARN)
    abort(); return
  end
  local review_only = (args[1] == 'runs' and vim.tbl_contains({ 'list', 'show', 'compare', 'find-request', 'acknowledge-unknown' }, args[2]))
    or (args[1] == 'assembly' and args[2] == 'show' and vim.tbl_contains(args, '--config-only'))
    or (args[1] == 'component' and vim.tbl_contains({ 'discover', 'list', 'show' }, args[2]))
    or args[1] == 'discover'
  local durable, pending_error = pending_operation.read(state.opts.project)
  if pending_error and not review_only then
    notify(tr('Cannot inspect the foreground operation marker: ', '无法检查前台操作标记：', '無法檢查前台操作標記：') .. tostring(pending_error)
      .. '\n' .. tr('Inspect this path and any effects of the earlier operation before resolving it: ',
        '处理前请检查此路径及先前操作的所有影响：', '處理前請檢查此路徑及先前操作的所有影響：')
      .. state.opts.project .. '/.model-maven/tui-foreground-pending.json', vim.log.levels.ERROR)
    abort(); return
  end
  local unresolved = durable or state.pending_uncertain_operation
  if unresolved and not review_only then
    local unresolved_project = state.opts.project
    abort()
    local detail = vim.api.nvim_create_buf(false, true)
    vim.bo[detail].buftype, vim.bo[detail].bufhidden, vim.bo[detail].swapfile = 'nofile', 'wipe', false
    local lines = {
      tr('Earlier operation may have run:', '先前操作可能已执行：', '先前操作可能已執行：'),
      vim.fn.strcharpart(tostring(unresolved.title):gsub('[%c]', ' '), 0, 128),
    }
    if durable and type(durable.host) == 'string' and type(durable.editor_pid) == 'number' then
      lines[#lines + 1] = tr('Editor host / PID: ', '编辑器主机 / PID：', '編輯器主機 / PID：')
        .. vim.fn.strcharpart(durable.host:gsub('[%c]', ' '), 0, 128) .. ' / ' .. tostring(durable.editor_pid)
    end
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Inspect files, run records and external effects before acknowledging.',
      '确认前请检查文件、运行记录和外部副作用。', '確認前請檢查檔案、執行紀錄和外部副作用。')
    lines[#lines + 1] = tr('Acknowledging does not prove the operation stopped.',
      '确认不代表操作已停止。', '確認不代表操作已停止。')
    vim.api.nvim_buf_set_lines(detail, 0, -1, false, lines)
    vim.bo[detail].modifiable = false
    if not open_aux_buffer(detail, false, false) then return end
    vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = detail, silent = true, desc = 'Keep pending operation' })
    review_gate(detail, { tr('Keep pending', '保留待核查状态', '保留待核查狀態'),
      tr('Accept unknown outcome', '接受结果仍未知', '接受結果仍未知') },
      tr('Accept unknown outcome?', '接受结果仍未知？', '接受結果仍未知？'), function(_, choice)
      if choice == 2 then
        if state.closed or state.opts.project ~= unresolved_project
            or (not durable and state.pending_uncertain_operation ~= unresolved) then
          notify(tr('Context changed; review the pending operation again.', '上下文已变化，请重新核查待处理操作。', '上下文已變更，請重新核查待處理操作。'), vim.log.levels.WARN)
          return
        end
        if durable then
          local ok, clear_err = pending_operation.clear(state.opts.project, durable)
          if not ok then notify(tr('Could not clear the marker: ', '无法移除标记：', '無法移除標記：') .. tostring(clear_err), vim.log.levels.ERROR); return end
          state.pending_foreground_checked, state.pending_foreground_cache = nil, nil
        end
        state.pending_uncertain_operation = nil
        notify(tr('Uncertainty acknowledged. Start a new action explicitly if appropriate.',
          '已接受结果仍未知；如适合继续，请明确重新发起操作。',
          '已接受結果仍未知；如適合繼續，請明確重新發起操作。'), vim.log.levels.WARN)
        render(state)
      end
      local windows = vim.fn.win_findbuf(detail)
      if #windows == 1 and vim.api.nvim_win_is_valid(windows[1])
          and windows[1] ~= state.panel_win and windows[1] ~= state.code_win
          and vim.api.nvim_win_get_buf(windows[1]) == detail then
        pcall(vim.api.nvim_win_close, windows[1], false)
      end
    end)
    return
  end
  if not project_config_current(state) then
    if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
    state.change_epoch = (state.change_epoch or 0) + 1
    state.journey = nil
    notify(tr('Project configuration changed on disk; check it before continuing.',
      '项目配置已在磁盘变化，请先检查再继续。', '專案設定已在磁碟變更，請先檢查再繼續。'), vim.log.levels.WARN)
    refresh_project(state)
    abort(); return
  end
  if state.project_status == 'checking' then
    notify(tr('Project configuration is still being checked; try again when the check finishes.',
      '正在检查项目配置，请等待检查完成后再试。', '正在檢查專案設定，請等待檢查完成後再試。'), vim.log.levels.INFO)
    abort(); return
  end
  if state.project_status == 'unknown' and args[1] ~= 'env' and args[1] ~= 'export' then
    notify(tr('Project configuration is not available; check it before running.',
