    offer_buffer_recovery(state, stale_sources, tr('Open Python buffers differ from disk or cannot be compared. Choose one to inspect:',
      '已打开的 Python buffer 与磁盘不同或无法比较；选择一个查看：',
      '已開啟的 Python buffer 與磁碟不同或無法比較；選擇一個查看：'))
    return
  end
  local config = project_config(state.opts.project) or {}
  local external_training = (args[1] == 'try' or args[1] == 'train')
    and vim.tbl_contains(args, '--training-mode') and vim.tbl_contains(args, 'external-loop')
  local no_project_model = external_training and vim.tbl_contains(args, '--no-model')
  local historical = args[1] == 'evaluate' or args[1] == 'export' or ((args[1] == 'train' or args[1] == 'loop-run') and vim.tbl_contains(args, '--resume'))
    or (args[1] == 'try' and vim.tbl_contains(args, '--repeat'))
  local project_python = state.project_info and state.project_info.runtime_python
  if type(project_python) ~= 'string' or project_python == '' then project_python = nil end
  if not selection_checked and not historical and args[1] ~= 'env'
      and not state.opts.python and not project_python then
    local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
    state.busy = tr('Checking Python selection', '检查 Python 选择', '檢查 Python 選擇')
    render(state)
    request(state, { '--describe-interface' }, function(selection, failure)
      state.busy = nil
      if state.closed or state.opts.project ~= project or state.opts.cli ~= cli or state.opts.python
          or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then
        render(state)
        notify(tr('Context changed while checking Python; retry the action.',
          '检查 Python 期间上下文已变化，请重试操作。', '檢查 Python 期間上下文已變更，請重試操作。'), vim.log.levels.WARN)
        abort(); return
      end
      local data = selection and selection.operation == 'interface' and selection.status == 'success' and selection.data
      local hint = type(data) == 'table' and type(data.capabilities) == 'table'
