    return
  end
  local historical_source = tr('recorded run; see run details', '历史运行记录；请查看运行详情', '歷史執行紀錄；請查看執行詳情')
  local generic_trial = args[1] == 'loop-trial' or args[1] == 'loop-run'
  local model = no_project_model and tr('none; the loop receives None', '无；循环接收 None', '無；迴圈接收 None')
    or generic_trial and tr('user loop owns any model', '由用户循环管理模型', '由使用者迴圈管理模型')
    or historical and historical_source or (state.model and (state.model .. tr(' (session)', '（会话选择）', '（工作階段選擇）')))
    or (type(config.model) == 'string' and (config.model .. tr(' (project default)', '（项目默认）', '（專案預設）'))) or '(project default)'
