    or args[1] == 'evaluate' and tr('evaluation data choice; see details below', '评估数据选择；见下方详情', '評估資料選擇；見下方詳情')
    or (historical and historical_source) or (external_training and tr('provided by the user loop', '由用户循环提供', '由使用者迴圈提供')
    or (state.batch and (state.batch .. tr(' (session)', '（会话选择）', '（工作階段選擇）')))
    or (type(config.batch) == 'string' and (config.batch .. tr(' (project default)', '（项目默认）', '（專案預設）'))) or '(project default)')
