    path = 'PATH',
    explicit = tr('explicit choice', '明确选择', '明確選擇'),
  })[python_hint.source] or tr('discovery', '自动发现', '自動探索')
  local python = state.opts.python or project_python
    or (python_hint and (python_hint.python .. tr(' (source: ', '（来源：', '（來源：') .. hint_source
      .. tr('; pinned for this action)', '；固定用于本次操作）', '；固定用於本次操作）')))
    or tr('(not explicitly selected; CLI may discover project environment or PATH; use e to choose)',
      '（未明确选择；CLI 可能发现项目环境或 PATH 中的 Python；按 e 选择）',
      '（未明確選擇；CLI 可能探索專案環境或 PATH 中的 Python；按 e 選擇）')
  if args[1] == 'export' or (not state.opts.python and historical) then
    python = tr('recorded run; see details below', '历史运行记录；见下方详情', '歷史執行紀錄；見下方詳情')
  end
  local context = tr('\nHost: ', '\n主机：', '\n主機：') .. state.host
    .. (historical and tr('\nCurrent workspace directory selection (may conflict with recorded run): ', '\n当前工作区目录选择（可能与历史运行冲突）：', '\n目前工作區目錄選擇（可能與歷史執行衝突）：')
      or tr('\nWorking directory: ', '\n工作目录：', '\n工作目錄：')) .. (state.opts.working_directory or state.opts.project)
    .. (historical and tr('\nCurrent workspace import roots (may conflict with recorded run): ', '\n当前工作区模块目录（可能与历史运行冲突）：', '\n目前工作區模組目錄（可能與歷史執行衝突）：')
      or tr('\nProject import roots: ', '\n项目模块搜索目录：', '\n專案模組搜尋目錄：')) .. (state.opts.project_import_roots and table.concat(state.opts.project_import_roots, ', ') or tr('default', '默认', '預設'))
  if not runtime_check then
    context = context .. tr('\nModel: ', '\n模型：', '\n模型：') .. tostring(model)
