      context = context .. tr('\nInput binding: ', '\n输入绑定：', '\n輸入繫結：')
        .. (state.batch_binding or (not state.batch and type(config.batch_binding) == 'string' and config.batch_binding) or tr('automatic', '自动', '自動'))
        .. tr('\nSession input parameter names: ', '\n会话输入参数名称：', '\n工作階段輸入參數名稱：')
        .. (#names > 0 and table.concat(names, ', ') or tr('none', '无', '無'))
    end
    context = context .. tr('\nResult is separate from current source-model evidence; variant revision is checked before execution.',
        '\n结果独立于当前源码模型证据；执行前会核对变体修订。',
        '\n結果獨立於目前原始碼模型證據；執行前會核對變體修訂。')
  end
  local uses_probe_seed = ((args[1] == 'graph-draft-probe') or (args[1] == 'model' and (args[2] == 'probe' or args[2] == 'mark' or args[2] == 'retag'
