      or (args[1] == 'assembly' and not vim.tbl_contains(args, '--config-only'))
      or (args[1] == 'layer' and vim.tbl_contains(args, '--target') and vim.tbl_contains(args, 'source')))
      and not vim.tbl_contains(args, '--seed')
  local selected_probe_seed = uses_probe_seed and state.probe_seed or nil
  local uses_training_seed = (args[1] == 'try' or args[1] == 'train') and not historical
