  local selected_training_seed = uses_training_seed and state.training_seed or nil
  local selected_initialization = uses_training_seed and not no_project_model and not isolated_variant and state.model_initialization or nil
  local selected_initialization_seed = uses_training_seed and not no_project_model and not isolated_variant and state.model_initialization_seed or nil
  local uses_probe_device = (args[1] == 'graph-draft-probe' or (args[1] == 'model' and (args[2] == 'probe' or args[2] == 'mark' or args[2] == 'retag'
      or (args[2] == 'supervise' and args[3] == 'preview'))))
    and not vim.tbl_contains(args, '--model-device')
  local selected_probe_device = uses_probe_device and state.probe_device or nil
  if uses_probe_seed then
    context = context .. tr('\nForward / assembly / source-edit seed: ', '\n前向 / 装配 / 源码编辑种子：', '\n前向 / 裝配 / 原始碼編輯種子：')
      .. (selected_probe_seed or tr('CLI/runtime policy', 'CLI/运行时策略', 'CLI/執行時策略'))
      .. tr(' (variants may use a separate initialization seed)', '（变体可能使用独立的初始化种子）', '（變體可能使用獨立的初始化種子）')
  elseif vim.tbl_contains(args, '--seed') then
    for index, value in ipairs(args) do
      if value == '--seed' and type(args[index + 1]) == 'string' then
        context = context .. tr('\nExplicit seed: ', '\n显式种子：', '\n明確種子：') .. args[index + 1]
        break
      end
    end
  end
  if uses_training_seed then
    context = context .. tr('\nTraining seed: ', '\n训练种子：', '\n訓練種子：')
