      .. (isolated_variant and tr('saved variant policy', '变体保存的策略', '變體儲存的策略')
        or no_project_model and tr('not applicable', '不适用', '不適用')
        or (selected_initialization or tr('CLI default', 'CLI 默认值', 'CLI 預設值')))
      .. (selected_initialization_seed and (' · ' .. selected_initialization_seed) or '')
  end
  if uses_probe_device then
    context = context .. tr('\nModel device: ', '\n模型设备：', '\n模型裝置：')
