  end
  if args[1] == 'layer' and vim.tbl_contains(args, '--target') and vim.tbl_contains(args, 'source') then
    context = context .. tr('\nSource-edit candidates use factory placement; later user code may move layers differently. Commit rechecks the rewritten model.',
      '\n源码编辑候选保留工厂选择的设备；用户后续代码可能采用不同迁移方式，提交时会重新检查改写后的模型。',
      '\n原始碼編輯候選保留工廠選擇的裝置；使用者後續程式碼可能採用不同遷移方式，提交時會重新檢查改寫後的模型。')
  end
  if not uses_probe_device and state.probe_device
      and ((args[1] == 'model' and (args[2] == 'mark' or args[2] == 'retag' or args[2] == 'supervise'))
        or args[1] == 'layer') then
    context = context .. tr('\nThe session forward device is not applied to this operation; it uses its own runtime context.',
      '\n本会话的前向设备不会用于此操作；此操作使用自己的运行时上下文。',
      '\n本工作階段的前向裝置不會用於此操作；此操作使用自己的執行時上下文。')
  end
  if not uses_probe_seed and not vim.tbl_contains(args, '--seed') and state.probe_seed
      and ((args[1] == 'model' and (args[2] == 'mark' or args[2] == 'retag' or args[2] == 'supervise'))
        or args[1] == 'layer') then
    context = context .. tr('\nThe session forward seed is not applied to this operation.',
      '\n本会话的前向种子不会用于此操作。', '\n本工作階段的前向種子不會用於此操作。')
  end
