    local project_batch_names = not state.batch and type(config.batch_params) == 'table' and vim.tbl_keys(config.batch_params) or {}
    table.sort(project_model_names); table.sort(project_batch_names)
    if no_project_model then
      context = context .. tr('\nNo model, model parameters or injections will be passed to this loop.',
