        .. (#project_model_names > 0 and table.concat(project_model_names, ', ') or tr('none', '无', '無'))
      context = context .. tr('\nModel parameter overrides: ', '\n模型参数覆盖：', '\n模型參數覆蓋：')
        .. (#model_names > 0 and table.concat(model_names, ', ') or tr('none', '无', '無'))
    end
