        .. (#project_batch_names > 0 and table.concat(project_batch_names, ', ') or tr('none', '无', '無'))
      context = context .. tr('\nInput parameter overrides: ', '\n输入参数覆盖：', '\n輸入參數覆蓋：') .. (#batch_names > 0 and table.concat(batch_names, ', ') or tr('none', '无', '無'))
      context = context .. tr('\nInput binding: ', '\n输入绑定：', '\n輸入繫結：')
        .. (state.batch_binding or (state.batch and tr('automatic', '自动', '自動'))
