  local selected_paths_override, selected_cli = state.opts.runtime_paths_override, state.opts.cli
  local selected_epoch, selected_report = state.change_epoch or 0, state.last
  local run_prompt = tr(': this imports and executes project Python. Continue?',
    '：将导入并执行项目 Python 代码，是否继续？', '：將匯入並執行專案 Python 程式碼，是否繼續？')
  if args[1] == 'model' and args[2] == 'supervise' and args[3] == 'import' then
    run_prompt = tr(': this starts Python and adds unbound supervision metadata; the model and rules are not run. Continue?',
      '：将启动 Python 并添加未绑定的监督信息，不运行模型和规则。是否继续？',
      '：將啟動 Python 並新增未繫結的監督資訊，不執行模型和規則。是否繼續？')
  elseif args[1] == 'runs' and args[2] == 'acknowledge-unknown' then
    run_prompt = tr(': this changes a run record. Continue?', '：将修改运行记录，是否继续？', '：將修改執行紀錄，是否繼續？')
  elseif args[1] == 'doctor' or (args[1] == 'env' and (args[2] == 'check' or args[2] == 'libraries')) then
    run_prompt = tr(': this starts Python to inspect the selected environment; Python startup hooks may run. Continue?',
      '：将启动 Python 检查所选环境；Python 启动钩子可能执行。是否继续？',
      '：將啟動 Python 檢查所選環境；Python 啟動掛鉤可能執行。是否繼續？')
  elseif args[1] == 'env' and args[2] == 'probe' then
    run_prompt = tr(': this starts Python and imports the requested library. Continue?',
      '：将启动 Python 并导入所选库。是否继续？', '：將啟動 Python 並匯入所選程式庫。是否繼續？')
  elseif args[1] == 'env' and args[2] == 'devices' then
    run_prompt = tr(': this imports PyTorch and queries visible devices; driver initialization may occur. Continue?',
      '：将导入 PyTorch 并查询可见设备，可能初始化驱动。是否继续？',
      '：將匯入 PyTorch 並查詢可見裝置，可能初始化驅動。是否繼續？')
  elseif args[1] == 'env' and args[2] == 'wheelhouse' and args[3] == 'check' then
    run_prompt = tr(': this checks the lock and archive in the selected Python. Continue?',
      '：将使用所选 Python 检查锁文件和归档，是否继续？', '：將使用所選 Python 檢查鎖定檔和封存，是否繼續？')
  elseif args[1] == 'env' and (args[2] == 'lock' or args[2] == 'setup' or args[2] == 'wheelhouse') then
    run_prompt = tr(': this may resolve or install dependencies and write project files. Continue?',
      '：可能解析或安装依赖并写入项目文件，是否继续？', '：可能解析或安裝相依套件並寫入專案檔案，是否繼續？')
  elseif args[1] == 'export' then
    run_prompt = tr(': this creates an export and may start the recorded Python to inspect its environment. Continue?',
      '：将创建导出目录，必要时可能启动记录的 Python 检查环境。是否继续？',
      '：將建立匯出目錄，必要時可能啟動記錄的 Python 檢查環境。是否繼續？')
  end
  local safe_query = (args[1] == 'runs' and vim.tbl_contains({ 'list', 'show', 'compare', 'find-request' }, args[2]))
    or (args[1] == 'assembly' and args[2] == 'show' and vim.tbl_contains(args, '--config-only'))
    or (args[1] == 'component' and vim.tbl_contains({ 'discover', 'list', 'show' }, args[2]))
    or args[1] == 'discover'
  local action_kind = safe_query and 'safe_read'
    or (args[1] == 'try' or args[1] == 'train' or args[1] == 'loop-trial'
      or args[1] == 'loop-run' or external_training) and 'training'
    or ((args[1] == 'component' and (args[2] == 'install' or args[2] == 'uninstall'))
      or (args[1] == 'env' and (args[2] == 'install' or args[2] == 'setup' or args[2] == 'configure' or args[2] == 'lock'
        or (args[2] == 'wheelhouse' and (args[3] == 'archive' or args[3] == 'replay'))))) and 'environment_change'
    or (write_effect or vim.tbl_contains(args, '--apply') or args[1] == 'init' or args[1] == 'export'
      or (args[1] == 'runs' and vim.tbl_contains({ 'stop', 'rename', 'keep', 'unkeep', 'clean' }, args[2]))
      or (args[1] == 'data' and args[2] == 'index' and vim.tbl_contains(args, '--apply-exclusions'))
      or (args[1] == 'data' and args[2] == 'csv-template')) and 'persistent_write'
    or runtime_check and 'runtime_check'
    or 'user_code'
  -- Detached training has its own durable request-id admission and recovery.
  -- Other before_start callbacks may only check preconditions (e.g. export).
  local tracked_detached = before_start and (args[1] == 'train' or args[1] == 'loop-run')
    and vim.tbl_contains(args, '--detach')
  local track_foreground = action_kind ~= 'safe_read' and not review_only and not tracked_detached
  local authorization_context = {
    project = state.opts.project, config_revision = state.project_info and state.project_info.config_revision,
    panel = state.panel, session_epoch = state.change_epoch or 0, cli = state.opts.cli,
    runtime_paths_override = state.opts.runtime_paths_override,
    working_directory = state.opts.working_directory or state.opts.project,
    project_import_roots = state.opts.project_import_roots,
  }
  local authorization = {
    kind = action_kind, label = title,
    allow_edit = not historical and not runtime_check and (action_kind == 'user_code' or action_kind == 'training'),
    effect = type(write_effect) == 'string' and write_effect or nil,
    identity_complete = false,
    selection_summary = title .. run_prompt .. context .. (runtime_check and ''
      or tr('\nUnverifiable source or input identities permit this action once only.',
        '\n源码或输入身份无法核对时，只授权本次操作。', '\n原始碼或輸入身分無法核對時，只授權本次操作。')),
    scope = authorization_context,
    context = authorization_context,
    selection = { args = args, model = state.model, input = state.batch,
      python = state.opts.python or project_python or (python_hint and python_hint.python),
      working_directory = state.opts.working_directory or state.opts.project,
      import_roots = state.opts.project_import_roots, seed = selected_probe_seed or selected_training_seed,
      device = selected_probe_device, batch_binding = selected_batch_binding,
      model_params = model_params, batch_params = batch_params },
  }
  if track_foreground then
    authorization.selection_summary = authorization.selection_summary .. tr(
      '\nA local pending-operation marker is created before execution and removed after a received result.',
      '\n执行前会创建本地待核查标记；收到结果后移除。',
      '\n執行前會建立本機待核查標記；收到結果後移除。')
  end
  local identity_supported = state.confirmation_reuse_enabled == true and action_kind == 'user_code'
    and not vim.tbl_contains(args, '--capture-input-to') and not vim.tbl_contains(args, '--replay-input-from')
    and ((args[1] == 'model' and (args[2] == 'inspect' or args[2] == 'probe'))
      or (args[1] == 'layer' and (args[2] == 'list' or args[2] == 'show')))
  local identity_operation_args
  if identity_supported then
    identity_operation_args = vim.deepcopy(args)
    if selected_probe_seed then vim.list_extend(identity_operation_args, { '--seed', selected_probe_seed }) end
    if selected_probe_device then vim.list_extend(identity_operation_args, { '--model-device', selected_probe_device }) end
    if python_hint then vim.list_extend(identity_operation_args, { '--python', python_hint.python }) end
    if not no_context and state.model then vim.list_extend(identity_operation_args, { '--model', state.model }) end
    if not no_context and state.batch then vim.list_extend(identity_operation_args, { '--batch', state.batch }) end
    if not no_context and selected_batch_binding and not vim.tbl_contains(identity_operation_args, '--batch-binding') then
      vim.list_extend(identity_operation_args, { '--batch-binding', selected_batch_binding })
    end
    if not no_context then
      for _, field in ipairs({ { flag = '--model-param', values = model_params }, { flag = '--batch-param', values = batch_params } }) do
        local names = vim.tbl_keys(field.values)
        table.sort(names)
        for _, name in ipairs(names) do
          vim.list_extend(identity_operation_args, { field.flag, name .. '=' .. vim.json.encode(field.values[name]) })
        end
      end
    end
  end
  local resolved_authorization_identity = nil
  local function resolve_authorization_identity(reviewed, done)
    if not identity_operation_args then
      confirmation.invalidate_context(reviewed.context)
      done(reviewed.selection, true)
      return
    end
    local identity_request = { 'workspace', 'authorization-identity', '--request-json', vim.json.encode(identity_operation_args) }
    state.busy = tr('Resolving execution identity', '解析执行身份', '解析執行身分')
    render(state)
    state.process = request(state, identity_request, function(report, failure)
      state.busy, state.process = nil, nil
      local unchanged = not state.closed and state.opts.project == selected_project
        and state.opts.cli == selected_cli and state.opts.python == selected_python
        and state.opts.working_directory == selected_directory
        and vim.deep_equal(state.opts.project_import_roots, selected_import_roots)
        and state.opts.runtime_paths_override == selected_paths_override
        and state.model == selected_model and state.batch == selected_batch
        and state.batch_binding == selected_batch_binding
        and vim.deep_equal(state.model_params or {}, model_params)
        and vim.deep_equal(state.batch_params or {}, batch_params)
        and (state.change_epoch or 0) == selected_epoch and project_config_current(state)
        and #dirty_buffers(state.opts.project) == 0 and #reloads_pending(state) == 0
        and #stale_python_buffers(state.opts.project) == 0
      if not unchanged then
        notify(tr('Context changed while resolving authorization identity; no operation was started.',
          '解析授权身份期间上下文已变化；操作未启动。', '解析授權身分期間上下文已變更；操作未啟動。'), vim.log.levels.WARN)
        done(nil, false)
        abort()
        return
      end
      local snapshot = not failure and report and report.operation == 'authorization_identity'
        and report.status == 'success' and type(report.data) == 'table'
        and type(report.data.identity) == 'table' and report.data.identity or nil
      local digest = snapshot and snapshot.complete == true and snapshot.action_class == 'user_code'
        and type(snapshot.identity_digest) == 'string' and #snapshot.identity_digest == 64
        and snapshot.identity_digest:match('^[0-9a-f]+$') and snapshot.identity_digest or nil
      reviewed.identity_complete = digest ~= nil
      if digest then
        resolved_authorization_identity = digest
        authorization.identity_complete = true
        reviewed.scope.backend_identity_digest = digest
        reviewed.context.backend_identity_digest = digest
        reviewed.selection.authorization_identity_digest = digest
        reviewed.selection.authorization_identity_components = type(snapshot.components) == 'table' and snapshot.components or {}
        authorization.scope.backend_identity_digest = digest
        authorization.context.backend_identity_digest = digest
        authorization.selection.authorization_identity_digest = digest
        authorization.selection.authorization_identity_components = type(snapshot.components) == 'table' and snapshot.components or {}
        if type(snapshot.display_summary) == 'string' then
          reviewed.selection_summary = reviewed.selection_summary .. '\n' .. snapshot.display_summary
          authorization.selection_summary = reviewed.selection_summary
        end
      else
        reviewed.identity_complete = false
        reviewed.selection_summary = reviewed.selection_summary
          .. tr('\nBackend could not verify a complete runtime/source/input identity; this operation requires per-run confirmation.',
            '\n后端无法核实完整运行时/源码/输入身份；此操作须逐次确认。',
            '\n後端無法核實完整執行環境/原始碼/輸入身分；此操作須逐次確認。')
        if snapshot and type(snapshot.incomplete_reasons) == 'table' then
          for _, reason in ipairs(snapshot.incomplete_reasons) do
            if type(reason) == 'string' then reviewed.selection_summary = reviewed.selection_summary .. '\n· ' .. reason end
          end
        end
        authorization.identity_complete = false
        authorization.selection_summary = reviewed.selection_summary
      end
      confirmation.invalidate_context(reviewed.context)
      render(state)
      done(reviewed.selection, true)
    end, function()
      state.busy, state.process = nil, nil
      done(nil, false)
    end)
  end
  confirmation.request(authorization, {
    reuse_confirmed = state.confirmation_reuse_enabled == true,
    edit_selection = resolve_authorization_identity,
  }, function(approved, auth_result)
    if not approved or state.closed then
      abort()
      if auth_result ~= 'edit_selection' or state.closed or state.opts.project ~= selected_project
          or state.opts.cli ~= selected_cli or (state.change_epoch or 0) ~= selected_epoch then return end
      local choices = {
        { key = 'e', label = tr('Python environment', 'Python 环境', 'Python 環境') },
        { key = 'K', label = tr('Working directory and module paths', '运行目录和模块路径', '執行目錄和模組路徑') },
      }
      if not no_context and not isolated_variant and not no_project_model then
        choices[#choices + 1] = { key = 'm', label = tr('Model factory', '模型工厂', '模型工廠') }
      end
      if not no_context and not external_training then
        choices[#choices + 1] = { key = 'b', label = tr('Input factory', '输入工厂', '輸入工廠') }
      end
      if not no_context and not no_project_model then
        choices[#choices + 1] = { key = 'P', label = tr('Parameters and input binding', '参数和输入绑定', '參數和輸入繫結') }
      end
      vim.ui.select(choices, { prompt = tr('Change a selection, then start the action again',
        '修改选择后，请重新发起操作', '修改選擇後，請重新發起操作'), format_item = function(item) return item.label end }, function(item)
          if not item or state.closed or state.busy or state.opts.project ~= selected_project
              or state.opts.cli ~= selected_cli or (state.change_epoch or 0) ~= selected_epoch then return end
          local action = state.actions and state.actions[item.key]
          if type(action) == 'function' then action() end
        end)
      return
    end
    if not state.busy and state.opts.project == selected_project then
      local changed_buffers = dirty_buffers(state.opts.project)
      if #changed_buffers == 0 then changed_buffers = reloads_pending(state) end
      if #changed_buffers == 0 then changed_buffers = stale_python_buffers(state.opts.project) end
      if #changed_buffers > 0 then
        confirmation.revoke(authorization)
        abort()
        offer_buffer_recovery(state, changed_buffers, tr('A project buffer needs attention before running. Choose one:',
          '运行前需要处理项目 buffer，请选择一个：', '執行前需要處理專案 buffer，請選擇一個：'))
        return
      end
    end
    if state.busy or not project_config_current(state) or state.opts.project ~= selected_project or state.model ~= selected_model or state.batch ~= selected_batch or state.batch_binding ~= selected_batch_binding or state.opts.python ~= selected_python
        or state.opts.working_directory ~= selected_directory or not vim.deep_equal(state.opts.project_import_roots, selected_import_roots)
        or state.opts.cli ~= selected_cli or state.opts.runtime_paths_override ~= selected_paths_override
        or (uses_probe_seed and state.probe_seed ~= selected_probe_seed)
        or (uses_training_seed and state.training_seed ~= selected_training_seed)
        or (uses_training_seed and not no_project_model and not isolated_variant and (state.model_initialization ~= selected_initialization
          or state.model_initialization_seed ~= selected_initialization_seed))
        or (uses_probe_device and state.probe_device ~= selected_probe_device)
        or not vim.deep_equal(state.model_params or {}, model_params) or not vim.deep_equal(state.batch_params or {}, batch_params)
        or (state.change_epoch or 0) ~= selected_epoch or (write_effect and state.last ~= selected_report) then
      confirmation.revoke(authorization)
      notify(tr('Model-Maven: context changed; review and confirm again.', 'Model-Maven：上下文已变化，请重新检查并确认。', 'Model-Maven：上下文已變更，請重新檢查並確認。'), vim.log.levels.WARN)
      abort(); return
    end
    local foreground_marker
    if track_foreground then
      local marker_error
      foreground_marker, marker_error = pending_operation.create(state.opts.project, title)
      if not foreground_marker then
        confirmation.revoke(authorization)
        notify(tr('Could not create the foreground operation marker; check pending operations or project permissions: ',
          '无法创建前台操作标记；请检查待核查操作或项目权限：',
          '無法建立前台操作標記；請檢查待核查操作或專案權限：') .. tostring(marker_error), vim.log.levels.ERROR)
        abort(); return
      end
    end
    if before_start and not before_start(args) then
      if foreground_marker then pending_operation.clear(state.opts.project, foreground_marker) end
      confirmation.revoke(authorization); abort(); return
    end
    local original_project = state.opts.project
    local start_epoch = state.change_epoch or 0
    local captured = {}
    local function source_stat(name)
      local stat = vim.uv.fs_stat(name)
      if not stat then return nil end
      return { type = stat.type, size = stat.size, dev = stat.dev, ino = stat.ino,
        mtime = stat.mtime, ctime = stat.ctime }
    end
    for _, buf in ipairs(vim.api.nvim_list_bufs()) do
      local name = vim.api.nvim_buf_get_name(buf)
      if vim.api.nvim_buf_is_loaded(buf) and in_project(state.opts.project, name) then
        captured[buf] = { tick = vim.api.nvim_buf_get_changedtick(buf), stat = source_stat(name), name = name }
      end
    end
    local operation_args = vim.deepcopy(args)
    if selected_probe_seed then vim.list_extend(operation_args, { '--seed', selected_probe_seed }) end
    if selected_training_seed then vim.list_extend(operation_args, { '--seed', selected_training_seed }) end
    if selected_initialization then
      vim.list_extend(operation_args, { '--model-initialization', selected_initialization })
      if selected_initialization_seed then vim.list_extend(operation_args, { '--model-initialization-seed', selected_initialization_seed }) end
    end
    if selected_probe_device then vim.list_extend(operation_args, { '--model-device', selected_probe_device }) end
    if python_hint then vim.list_extend(operation_args, { '--python', python_hint.python }) end
    if (not no_context or external_training) and state.model and not no_project_model and not isolated_variant then vim.list_extend(operation_args, { '--model', state.model }) end
    if not no_context and state.batch then vim.list_extend(operation_args, { '--batch', state.batch }) end
    if not no_context and selected_batch_binding and not vim.tbl_contains(operation_args, '--batch-binding') then
      vim.list_extend(operation_args, { '--batch-binding', selected_batch_binding })
    end
    if not no_context or external_training then
      for _, field in ipairs({ { flag = '--model-param', values = model_params }, { flag = '--batch-param', values = batch_params } }) do
        if not (external_training and field.flag == '--batch-param') and not ((no_project_model or isolated_variant) and field.flag == '--model-param') then
        local names = vim.tbl_keys(field.values)
        table.sort(names)
        for _, name in ipairs(names) do
          vim.list_extend(operation_args, { field.flag, name .. '=' .. vim.json.encode(field.values[name]) })
        end
        end
      end
    end
    local transport_args = operation_args
    if resolved_authorization_identity then
      transport_args = { 'workspace', 'run', '--request-json', vim.json.encode(operation_args),
        '--if-authorization-identity', resolved_authorization_identity }
    end
    state.busy = title
    state.cancel_requested = false
    state.cancellable = vim.fn.has('win32') ~= 1 and not write_effect and (
      (args[1] == 'model' and (args[2] == 'inspect' or args[2] == 'probe'
        or (args[2] == 'supervise' and args[3] == 'preview')))
      or (args[1] == 'layer' and (args[2] == 'list' or args[2] == 'show' or vim.tbl_contains(args, '--dry-run')))
      or (args[1] == 'assembly' and args[2] == 'patch' and not vim.tbl_contains(args, '--apply')))
    render(state)
    state.process = request(state, transport_args, function(report, err, stderr)
      local cancel_requested = state.cancel_requested
      state.busy, state.process, state.cancellable, state.cancel_requested = nil, nil, nil, nil
      local expected = args[1] == 'try' and 'training_probe'
        or args[1] == 'loop-trial' and 'generic_loop_trial'
        or args[1] == 'loop-run' and 'generic_loop_train'
        or args[1] == 'train' and 'train'
        or args[1] == 'evaluate' and 'evaluate'
        or args[1] == 'export' and 'export'
        or args[1] == 'doctor' and 'doctor'
        or args[1] == 'env' and args[2] == 'check' and 'environment_check'
        or args[1] == 'env' and args[2] == 'libraries' and 'environment_library_inventory'
        or args[1] == 'env' and args[2] == 'probe' and 'environment_library_probe'
        or args[1] == 'env' and args[2] == 'devices' and 'environment_devices'
        or args[1] == 'data' and args[2] == 'preview' and 'preview'
        or args[1] == 'assembly' and args[2] == 'patch' and 'assembly_patch'
        or args[1] == 'assembly' and args[2] == 'generate' and 'assembly_generate'
        or args[1] == 'model' and args[2] == 'inspect' and 'inspect'
        or args[1] == 'model' and args[2] == 'probe' and 'probe'
        or args[1] == 'graph-draft-probe' and 'graph_draft_probe'
        or args[1] == 'model' and (args[2] == 'mark' or args[2] == 'marks' or args[2] == 'retag') and 'semantic_mark'
        or args[1] == 'model' and args[2] == 'supervise' and 'semantic_supervise'
        or args[1] == 'layer' and (args[2] == 'list' or args[2] == 'show') and 'layers'
        or args[1] == 'layer' and 'edit' or nil
      if report and report.status == 'success' and expected and report.operation ~= expected then
        err = { message = tr('CLI returned a successful report for a different operation; outcome is unknown.',
          'CLI 返回了其他操作的成功报告；本次结果未知。', 'CLI 回傳了其他操作的成功報告；本次結果未知。') }
        report = nil
      end
      local stale = original_project ~= state.opts.project or not project_config_current(state) or (state.change_epoch or 0) ~= start_epoch
        or #dirty_buffers(state.opts.project) > 0
      for buf, original in pairs(captured) do
        if vim.api.nvim_buf_is_valid(buf) and vim.api.nvim_buf_get_changedtick(buf) ~= original.tick then stale = true end
        local current = source_stat(original.name)
        if not original.stat or not current or not vim.deep_equal(original.stat, current) then stale = true end
      end
      local uncertain_outcome = (err and err.operation_started ~= false)
        or (not err and not report) or (report and report.status == 'unknown')
      if foreground_marker and not uncertain_outcome then
        local cleared, clear_err = pending_operation.clear(original_project, foreground_marker)
        if not cleared then
          uncertain_outcome = true
          notify(tr('Could not clear the foreground marker; inspect it before continuing: ',
            '无法移除前台操作标记；继续前请检查：', '無法移除前台操作標記；繼續前請檢查：') .. tostring(clear_err), vim.log.levels.WARN)
        end
      end
      if original_project ~= state.opts.project then
        -- The receipt belongs to another project. Keep the current report and
        -- context untouched; any detached-start marker remains in the original
        -- project for explicit reconciliation instead of calling UI callbacks
        -- with the new project selected.
        confirmation.outcome_unknown(authorization)
        render(state)
        notify(tr('An operation response belongs to another project. Open that project and inspect its result or pending request before retrying: ',
          '操作回执属于另一个项目；重试前请打开原项目检查结果或待确认请求：',
          '操作回執屬於另一個專案；重試前請開啟原專案檢查結果或待確認要求：') .. original_project, vim.log.levels.WARN)
        return
      end
      state.last = { report = report, transport_error = err, stderr = stderr,
        scope = tr('This result reflects only the executed operation and input; disk changes and external resources are not pinned.',
          '此结果仅反映本次操作和输入；磁盘变化及外部资源未固定。', '此結果僅反映本次操作和輸入；磁碟變更及外部資源未固定。'),
        context_changed = stale or isolated_variant, observed_context_changed = stale,
        isolated_variant = isolated_variant, cancellation_requested = cancel_requested,
        uncertain_outcome = uncertain_outcome and true or false,
        observed_source_stats = observed_source_stats(state.opts.project, report) }
      if not stale and not err and report and report.operation == 'training_probe' and report.status == 'success'
          and type(report.data) == 'table' and type(report.data.supervision) == 'table'
          and type(report.data.supervision.rules) == 'table' and is_list(report.data.supervision.rules) then
        state.last_supervised_trial = { project = original_project, data = report.data }
      end
      if isolated_variant then
        state.last.scope = state.last.scope .. tr(' This variant result is separate from the current source model.',
          ' 此变体结果独立于当前源码模型。', ' 此變體結果獨立於目前原始碼模型。')
      end
      if args[1] == 'model' and args[2] == 'probe' then
        for index, arg in ipairs(args) do
          if arg == '--contract' and type(args[index + 1]) == 'string' then
            state.last.contract_file = args[index + 1]
            break
          end
        end
      end
      state.result_label = err and tr('CLI error', 'CLI 错误', 'CLI 錯誤') or (report and report.status or 'unknown')
      if not err and report and report.operation == 'train' and report.status == 'success'
          and type(report.data) == 'table' and report.data.detached == true then
        state.result_label = tr('training started', '训练已启动', '訓練已啟動')
      end
      if not err and report and report.status == 'success'
          and (report.operation == 'generic_loop_trial' or report.operation == 'generic_loop_train')
          and type(report.data) == 'table' and report.data.detached ~= true then
        if report.data.termination_reason == 'loop_returned_before_target' then
          state.result_label = tr('loop returned before target', '循环提前结束，未达到目标步数', '迴圈提前結束，未達到目標步數')
        elseif report.data.termination_reason ~= 'target_reached' then
          state.result_label = tr('loop completion unknown', '循环是否达到目标未知', '迴圈是否達到目標未知')
        end
      end
      local attention = supervision_attention(report)
      if not err and attention and attention > 0 then
        state.result_label = tr('supervision needs attention', '监督规则需处理', '監督規則需處理')
      end
      if report and type(report.diagnostics) == 'table' then
        for _, diagnostic in ipairs(report.diagnostics) do
          if type(diagnostic) == 'table' and diagnostic.code == 'AUTHORIZATION_IDENTITY_CONFLICT' then
            confirmation.revoke(authorization)
            break
          end
        end
      end
      if err and err.operation_started == false then confirmation.revoke(authorization) end
      if uncertain_outcome
          or (cancel_requested and err and err.kind ~= 'cancelled_before_start') then
        confirmation.outcome_unknown(authorization)
      end
      if report and report.operation == 'preview' and type(report.data) == 'table' and report.data.published == false then
        state.result_label = tr('preview superseded; not published', '预览已被替代，未发布', '預覽已被取代，未發布')
      end
      if uncertain_outcome then
        state.result_label = tr('outcome unknown; inspect before retrying', '结果未知；重试前请检查', '結果未知；重試前請檢查')
        if action_kind ~= 'safe_read' then state.pending_uncertain_operation = { title = title } end
      end
      if foreground_marker then state.pending_foreground_checked, state.pending_foreground_cache = nil, nil end
      if report and report.operation == 'probe' and report.status == 'success' then
        local data = type(report.data) == 'table' and report.data or {}
        local reused = data.forward_execution == 'reused'
          or (type(data.evidence_cache) == 'table' and data.evidence_cache.status == 'reused')
        if reused or data.forward_execution ~= 'executed' then
          state.last.forward_not_fresh = true
          state.result_label = reused and tr('previous forward evidence reused; no new forward', '复用先前前向证据；未执行新前向', '重用先前前向證據；未執行新前向')
            or tr('forward execution unconfirmed', '前向是否执行未确认', '前向是否執行未確認')
        end
      end
      if cancel_requested and err and err.kind == 'cancelled_before_start' then
        state.result_label = tr('cancelled before operation started', '操作启动前已取消', '操作啟動前已取消')
      elseif cancel_requested and err then
        state.result_label = tr('cancellation outcome unknown; inspect before retrying', '取消结果未知；重试前请检查', '取消結果未知；重試前請檢查')
      elseif cancel_requested and report and report.status == 'success' then
        state.result_label = tr('completed before cancellation', '取消前已完成', '取消前已完成')
      elseif cancel_requested and report and report.status ~= 'success' then
        local diagnostics = type(report.diagnostics) == 'table' and report.diagnostics or {}
        for _, diagnostic in ipairs(diagnostics) do
          if type(diagnostic) == 'table' and diagnostic.code == 'USER_INTERRUPTED' then
            if report.operation == 'operation_readiness' then
              state.result_label = tr('cancelled during readiness; action not started',
                '准备检查时已取消；目标操作未启动', '準備檢查時已取消；目標操作未啟動')
              state.last.scope = state.last.scope .. tr(' The target action did not start; the environment check may have run Python startup hooks.',
                ' 目标操作未启动；环境检查可能已运行 Python 启动钩子。', ' 目標操作未啟動；環境檢查可能已執行 Python 啟動鉤子。')
            else
              state.result_label = tr('interrupted; inspect possible effects',
                '已中断；请检查可能的副作用', '已中斷；請檢查可能的副作用')
              state.last.scope = state.last.scope .. tr(' User code may already have changed files or external state; cancellation does not undo its effects.',
                ' 用户代码可能已经更改文件或外部状态；取消不会撤销这些影响。',
                ' 使用者程式碼可能已更改檔案或外部狀態；取消不會復原這些影響。')
            end
            break
          end
        end
      end
      if not stale and not isolated_variant and report and report.status == 'success' then
        if (report.operation == 'inspect' or report.operation == 'layers' or report.operation == 'probe')
            and type(report.data) == 'table' and type(report.data.modules) == 'table' then
          state.model_preview_observation = {report = report, project = original_project, epoch = start_epoch}
          require('model_maven.model_preview').refresh(state)
        end
        if report.operation == 'inspect' or report.operation == 'layers' then state.journey = 'inspected'
        elseif report.operation == 'probe' and not vim.tbl_contains(args, '--local') then
          state.journey = state.last.forward_not_fresh and 'inspected' or 'observed'
        elseif report.operation == 'edit' and report.data and report.data.committed == true then state.journey = 'changed'
        elseif report.operation == 'training_probe' or report.operation == 'train'
            or report.operation == 'generic_loop_trial' or report.operation == 'generic_loop_train' then state.journey = 'trained' end
      end
      if not stale and not isolated_variant and report and report.operation == 'probe' and report.status == 'success'
          and not vim.tbl_contains(args, '--local') and not state.last.forward_not_fresh then
        state.saved_forward = { report = report, stderr = stderr, project = original_project, epoch = start_epoch }
      end
      if not isolated_variant and report and report.operation == 'probe' and report.status == 'success' and type(report.data) == 'table' then
        local data = report.data
        local calls, sources, source_conflict, source_count = {}, {}, false, 0
        local call_summary_truncated, alias_summary_truncated, source_summary_truncated = false, false, false
        local call_details_incomplete = false
        local calls_available = type(data.calls) == 'table' and is_list(data.calls)
        local backend_trace_truncated = type(data.trace_truncated) == 'boolean' and data.trace_truncated or nil
        -- Lua's and/or idiom would turn a reported false into nil.
        if data.trace_truncated == false then backend_trace_truncated = false end
        if calls_available then
          for index, call in ipairs(data.calls) do
            if index > 2048 then call_summary_truncated = true; break end
            if type(call) == 'table' and type(call.paths) == 'table' and is_list(call.paths) then
              local impl = call.implementation
              if type(impl) == 'table' and type(impl.source_file) == 'string' and impl.source_file:sub(1, 1) ~= '@'
                  and type(impl.source_sha256) == 'string' and #impl.source_sha256 == 64
                  and impl.source_sha256:match('^[0-9a-f]+$') then
                if sources[impl.source_file] and sources[impl.source_file] ~= impl.source_sha256 then source_conflict = true end
                if sources[impl.source_file] then sources[impl.source_file] = impl.source_sha256
                elseif source_count < 512 then sources[impl.source_file] = impl.source_sha256; source_count = source_count + 1
                else source_summary_truncated = true end
              end
              local paths = {}
              for index, path in ipairs(call.paths) do
                if index > 32 then alias_summary_truncated = true; break end
                if type(path) == 'string' then paths[#paths + 1] = path else call_details_incomplete = true end
              end
              local implementation
              if type(impl) == 'table' and type(impl.source_file) == 'string' and impl.source_file:sub(1, 1) ~= '@'
                  and type(impl.source_sha256) == 'string' and #impl.source_sha256 == 64
                  and impl.source_sha256:match('^[0-9a-f]+$') then
                implementation = { source = impl.source_file, digest = impl.source_sha256, line = impl.declaration_line }
              end
              calls[#calls + 1] = { paths = paths, module_type = call.module_type,
                invocation_index = call.invocation_index, implementation = implementation }
            else
              call_details_incomplete = true
            end
          end
        end
        local encoded, output_json = pcall(vim.json.encode, data.outputs)
        local outputs = encoded and #output_json <= 65536 and vim.deepcopy(data.outputs) or nil
        state.observations = state.observations or {}
        state.observations[#state.observations + 1] = {
          label = os.date('%H:%M:%S') .. ' · ' .. tostring(batch),
          project = original_project, model = tostring(model), input = tostring(batch), python = python,
          requested_batch_binding = selected_batch_binding or (not selected_batch and type(config.batch_binding) == 'string' and config.batch_binding) or 'automatic',
          model_parameter_names = vim.tbl_keys(model_params), batch_parameter_names = vim.tbl_keys(batch_params),
          epoch = start_epoch, stale_on_arrival = stale, calls = calls,
          trace_truncated = backend_trace_truncated, calls_available = calls_available,
          call_summary_truncated = call_summary_truncated, alias_summary_truncated = alias_summary_truncated,
          source_summary_truncated = source_summary_truncated, call_details_incomplete = call_details_incomplete,
          batch_id = data.batch_id, batch_identity_stable = data.batch_identity_stable == true,
          batch_content = type(data.batch_content) == 'table' and vim.deepcopy(data.batch_content) or nil,
          outputs = outputs, observed_mode = data.observed_mode,
          runtime = type(data.runtime) == 'table' and {
            python_executable = data.runtime.python_executable, python_version = data.runtime.python_version,
            pytorch_version = data.runtime.pytorch_version,
            probe_device = type(data.runtime.probe_device) == 'table' and {
              device = data.runtime.probe_device.device, device_requested = data.runtime.probe_device.device_requested,
            } or nil } or nil,
          config_revision = data.config_revision, seed = data.seed, seed_policy = data.seed_policy,
          input_sources = type(data.input_sources) == 'table' and {
            model = type(data.input_sources.model) == 'table' and data.input_sources.model.kind or nil,
            batch = type(data.input_sources.batch) == 'table' and data.input_sources.batch.kind or nil } or nil,
          observed_sources = sources, source_conflict = source_conflict,
          scope = vim.tbl_contains(args, '--local') and 'selected-module-replay' or 'full-forward',
          scope_path = vim.tbl_contains(args, '--local') and args[3] or nil,
          probe_id = data.probe_id, forward_id = data.forward_id,
          evidence_reused = data.forward_execution == 'reused'
            or (type(data.evidence_cache) == 'table' and data.evidence_cache.status == 'reused'),
          forward_execution = data.forward_execution,
        }
        if #state.observations > 6 then table.remove(state.observations, 1) end
        state.observation_generation = (state.observation_generation or 0) + 1
      end
      if stale then state.result_label = state.result_label .. tr(' (context changed; recheck)', '（上下文已变化，请重验）', '（上下文已變更，請重驗）') end
      render(state)
      local report_buf = show_report(state)
      if on_result then on_result(report, err, operation_args, stale, report_buf) end
    end, function() abort() end, fresh_forward, function()
      return not state.closed and state.opts.project == original_project
        and (state.change_epoch or 0) == start_epoch and project_config_current(state)
        and state.model == selected_model and state.batch == selected_batch and state.batch_binding == selected_batch_binding
        and (not uses_probe_seed or state.probe_seed == selected_probe_seed)
        and (not uses_training_seed or state.training_seed == selected_training_seed)
        and (not uses_probe_device or state.probe_device == selected_probe_device)
        and state.opts.python == selected_python and state.opts.cli == selected_cli
        and state.opts.working_directory == selected_directory and state.opts.runtime_paths_override == selected_paths_override
        and vim.deep_equal(state.opts.project_import_roots, selected_import_roots)
        and vim.deep_equal(state.model_params or {}, model_params) and vim.deep_equal(state.batch_params or {}, batch_params)
        and #dirty_buffers(original_project) == 0 and #reloads_pending(state) == 0
    end)
  end)
end

local function start_generic_run(state, title, args, effects, detached)
  if not detached then
    run(state, title, args, nil, effects, true)
    return
  end
  local project, request_id = state.opts.project, nil
  vim.list_extend(args, { '--detach' })
  local function before_start(operation_args)
    local items, err = pending.list(project)
    if not items or #items > 0 then
      notify(tr('Resolve pending training requests before starting: ', '请先处理待确认的训练请求：', '請先處理待確認的訓練要求：') .. tostring(err or table.concat(items, ', ')), vim.log.levels.WARN)
      return false
    end
    request_id, err = pending.create(project)
    if not request_id then notify(tr('Could not record the training request: ', '无法记录训练请求：', '無法記錄訓練要求：') .. tostring(err), vim.log.levels.ERROR); return false end
    vim.list_extend(operation_args, { '--request-id', request_id })
    return true
  end
  local function finished(report, err)
    if not request_id then return end
    if (err and err.operation_started == false) or (not err and report and report.operation == 'generic_loop_train'
        and report.status == 'success' and type(report.data) == 'table' and report.data.detached == true
        and report.data.request_id == request_id and type(report.data.run_id) == 'string' and report.data.run_id ~= '') then
      local ok, clear_err = pending.clear(project, request_id)
      if not ok then notify(tr('Pending request marker needs inspection: ', '待确认请求标记需要核查：', '待確認要求標記需要核查：') .. tostring(clear_err), vim.log.levels.WARN) end
    else
      notify(tr('Start outcome is unconfirmed. Use H to inspect request ', '启动结果尚未确认，请按 H 核查请求 ', '啟動結果尚未確認，請按 H 核查要求 ') .. request_id, vim.log.levels.WARN)
    end
  end
  run(state, title, args, finished, effects, true, before_start)
end

local function canvas_digest(value) return type(value) == 'string' and #value == 64 and value:match('^[0-9a-f]+$') ~= nil end
local function canvas_forward_identity(data)
  local provenance = type(data) == 'table' and data.run_provenance or nil
  if type(provenance) ~= 'table' or not vim.tbl_contains({'executed', 'failed'}, provenance.execution_status) then return {} end
  local model = type(provenance.model) == 'table' and provenance.model or {}
  local weights = type(model.weights_before_forward) == 'table' and model.weights_before_forward or {}
  local implementation = type(model.implementation) == 'table' and model.implementation or {}
  local environment = type(provenance.environment) == 'table' and provenance.environment or {}
  return {
    weights = weights.status == 'available' and weights.algorithm == 'sha256-registered-state-v1' and canvas_digest(weights.digest) and weights.digest or nil,
    environment = environment.status == 'available' and canvas_digest(environment.identity_sha256) and environment.identity_sha256 or nil,
    source = canvas_digest(implementation.source_sha256) and implementation.source_sha256 or nil,
  }
end

local function capture_canvas_forward(state, graph_guard, graph_revision)
  if state.busy or state.closed or not project_config_current(state) then return end
  local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
  request(state, { '--describe-interface' }, function(interface, failure)
    local caps = interface and type(interface.data) == 'table' and interface.data.capabilities
    if state.closed or state.busy or state.opts.project ~= project or state.opts.cli ~= cli
        or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then return end
    if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['input_snapshot.capture_replay'] ~= true then
      notify(tr('This CLI cannot capture and replay inputs.', '当前 CLI 不支持捕获并重放输入。', '目前 CLI 不支援擷取並重播輸入。'), vim.log.levels.WARN); return
    end
    local dir = vim.fn.tempname()
    local snapshot = { project = project, dir = dir, path = dir .. '/input.snapshot' }
    local function cleanup()
      if snapshot.cleaned then return end
      snapshot.cleaned = true
      local _, file_err, file_code = vim.uv.fs_unlink(snapshot.path)
      local removed, dir_err, dir_code = vim.uv.fs_rmdir(snapshot.dir)
      if (file_err and file_code ~= 'ENOENT') or (not removed and dir_code ~= 'ENOENT') then
        notify(tr('Could not remove input snapshot: ', '无法清理输入快照：', '無法清理輸入快照：') .. snapshot.path .. ' · ' .. tostring(file_err or dir_err), vim.log.levels.WARN)
      end
      if state.canvas_snapshot_cleanup == cleanup then state.canvas_snapshot_cleanup = nil; state.canvas_snapshot = nil end
    end
    local function prepare(args)
      if state.closed or state.opts.project ~= project or state.opts.cli ~= cli
          or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then snapshot.cleaned = true; return false end
      if graph_guard and not graph_guard() then
        snapshot.cleaned = true
        notify(tr('Graph, input or source changed; prepare capture again.', '图、输入或源码已变化，请重新准备捕获。', '圖、輸入或原始碼已變更，請重新準備擷取。'), vim.log.levels.WARN)
        return false
      end
      local ok = vim.uv.fs_mkdir(dir, 448)
      if not ok then snapshot.cleaned = true; notify(tr('Cannot create input snapshot directory.', '无法创建输入快照目录。', '無法建立輸入快照目錄。'), vim.log.levels.ERROR); return false end
      vim.list_extend(args, { '--capture-input-to', snapshot.path })
      return true
    end
    local effects = tr('Captures input values to a private temporary file for repeated replay, including if forward fails. Replacing or discarding the capture, or closing the workspace, removes the file; abnormal exit may leave it behind.',
      '将输入值捕获到私有临时文件，以便多次重放，包括前向失败的情况。替换或丢弃快照、关闭工作区时删除；异常退出可能留下文件。',
      '將輸入值擷取至私人暫存檔，以供多次重播，包括前向失敗的情況。取代或丟棄快照、關閉工作區時刪除；異常結束可能留下檔案。') .. '\n' .. snapshot.path
    run(state, tr('Capture input and run forward', '捕获输入并运行前向', '擷取輸入並執行前向'), { 'model', 'probe' }, function(report, err, _, stale)
      local data = report and report.data
      local content = type(data) == 'table' and data.batch_content
      local saved = type(data) == 'table' and data.batch_snapshot
      local file = vim.uv.fs_lstat(snapshot.path)
      if not err and not stale and report and report.operation == 'probe'
          and type(saved) == 'table' and saved.status == 'unsupported' then
        cleanup()
        notify(tr('This input cannot be captured exactly. Tensor views, shared storage and unsupported containers are not replayable; return independent tensors from the input factory and retry.',
          '此输入无法精确捕获。张量视图、共享存储或不支持的容器不能重放；请让输入工厂返回独立张量后重试。',
          '此輸入無法精確擷取。張量檢視、共用儲存空間或不支援的容器不能重播；請讓輸入工廠回傳獨立張量後重試。'), vim.log.levels.WARN)
        return
      end
      if err or stale or not report or report.operation ~= 'probe' or type(content) ~= 'table'
          or content.status ~= 'available' or content.algorithm ~= 'sha256-forward-input-v1'
          or type(content.digest) ~= 'string' or #content.digest ~= 64 or content.digest:find('[^0-9a-f]')
          or type(saved) ~= 'table' or saved.status ~= 'captured'
          or saved.format ~= 'model-maven-forward-input-snapshot-v1' or not file or file.type ~= 'file' then
        cleanup(); notify(tr('Input capture was not confirmed.', '输入捕获未得到确认。', '輸入擷取未獲確認。'), vim.log.levels.WARN); return
      end
      snapshot.digest = content.digest
      snapshot.identity = canvas_forward_identity(data)
      snapshot.graph_revision = canvas_digest(graph_revision) and graph_revision or nil
      if state.canvas_snapshot_cleanup then state.canvas_snapshot_cleanup() end
      state.canvas_snapshot, state.canvas_snapshot_cleanup = snapshot, cleanup
      render(state)
      notify(tr('Input captured for a later replay.', '已捕获输入，可用于稍后重放。', '已擷取輸入，可供稍後重播。'), vim.log.levels.INFO)
    end, effects, false, prepare, cleanup, true)
  end)
end

local function replay_canvas_forward(state, graph_guard, graph_revision)
  local snapshot = state.canvas_snapshot
  if not snapshot or snapshot.cleaned or state.closed or state.opts.project ~= snapshot.project
      or not project_config_current(state) then
    notify(tr('No current captured input is available.', '当前没有可重放的输入快照。', '目前沒有可重播的輸入快照。'), vim.log.levels.WARN); return
  end
  run(state, tr('Replay captured input', '重放已捕获输入', '重播已擷取輸入'),
    { 'model', 'probe', '--replay-input-from', snapshot.path, '--if-input-content', snapshot.digest }, function(report, err, _, stale, report_buf)
      if state.canvas_snapshot ~= snapshot then return end
      local data = report and report.data
      local content = type(data) == 'table' and data.batch_content
      local replay = type(data) == 'table' and data.batch_snapshot
      local same_input = not err and not stale and report and report.operation == 'probe' and type(data) == 'table'
          and type(content) == 'table' and content.status == 'available'
          and content.algorithm == 'sha256-forward-input-v1' and content.digest == snapshot.digest
          and type(replay) == 'table' and replay.status == 'replayed'
          and replay.format == 'model-maven-forward-input-snapshot-v1'
      local passed = same_input and report.status == 'success' and data.forward_execution == 'executed'
          and type(data.run_provenance) == 'table' and data.run_provenance.execution_status == 'executed'
      if same_input then
        local before, after = snapshot.identity or {}, canvas_forward_identity(data)
        local function comparison(left, right)
          if not left or not right then return tr('unknown', '未知', '未知') end
          return left == right and tr('same fingerprint', '指纹相同', '指紋相同') or tr('different fingerprint', '指纹不同', '指紋不同')
        end
        local summary = (passed and tr('Forward passed with captured input; ', '捕获输入的前向已通过；', '擷取輸入的前向已通過；')
          or tr('Captured input matched; forward did not pass or was not confirmed; ', '捕获输入匹配；前向未通过或无法确认；', '擷取輸入相符；前向未通過或無法確認；'))
          .. tr('registered weights before forward: ', '前向前登记权重：', '前向前登記權重：')
          .. comparison(before.weights, after.weights)
          .. tr(' · reported runtime packages: ', ' · 报告的运行时包：', ' · 回報的執行階段套件：') .. comparison(before.environment, after.environment)
          .. tr(' · reported model class source: ', ' · 报告的模型类源码：', ' · 回報的模型類別原始碼：') .. comparison(before.source, after.source)
          .. tr(' · graph revision checked before start: ', ' · 启动前核对的图版本：', ' · 啟動前核對的圖版本：')
          .. comparison(snapshot.graph_revision, canvas_digest(graph_revision) and graph_revision or nil)
          .. tr('. Other state, dependencies and side effects are not fully covered.',
            '。其他状态、依赖和副作用未被完整覆盖。', '。其他狀態、相依項目和副作用未被完整涵蓋。')
        state.last.recheck_summary = summary
        state.result_label = summary
        if report_buf and vim.api.nvim_buf_is_valid(report_buf) then
          vim.b[report_buf].model_maven_action_offset = (vim.b[report_buf].model_maven_action_offset or 0) + 2
          vim.bo[report_buf].modifiable = true
          vim.api.nvim_buf_set_lines(report_buf, 0, 0, false, {summary, ''})
          vim.bo[report_buf].modifiable = false
        end
        render(state)
        if passed then
          notify(tr('Forward passed on the captured input. The capture remains available; weights and environment may differ.',
            '已用捕获的相同输入前向通过。快照仍可重放；权重和环境可能不同。',
            '已用擷取的相同輸入前向通過。快照仍可重播；權重和環境可能不同。'), vim.log.levels.INFO)
        else
          notify(tr('Captured input matched, but forward did not pass or could not be confirmed. Inspect the report; the capture remains available.',
            '捕获输入匹配，但前向未通过或无法确认。请查看报告；快照仍可使用。',
            '擷取輸入相符，但前向未通過或無法確認。請查看報告；快照仍可使用。'), vim.log.levels.WARN)
        end
      else
        notify(tr('Replay did not pass or could not be confirmed; the snapshot remains available.',
          '重放未通过或无法确认；快照仍可使用。', '重播未通過或無法確認；快照仍可使用。'), vim.log.levels.WARN)
      end
    end, tr('Replays the previously captured input; the model and its dependencies run again.',
      '重放之前捕获的输入；模型及其依赖会重新执行。', '重播先前擷取的輸入；模型及其依賴會重新執行。'), false, graph_guard and function()
      if graph_guard() then return true end
      notify(tr('Graph or source changed; prepare replay again.', '图或源码已变化，请重新准备重放。', '圖或原始碼已變更，請重新準備重播。'), vim.log.levels.WARN)
      return false
    end or nil, function()
      if state.closed and state.canvas_snapshot == snapshot and state.canvas_snapshot_cleanup then state.canvas_snapshot_cleanup() end
    end, true)
end

local function discard_canvas_forward(state)
  if state.busy or state.closed then return end
  local snapshot, cleanup = state.canvas_snapshot, state.canvas_snapshot_cleanup
  if not snapshot or snapshot.cleaned or not cleanup then
    return notify(tr('No captured input is available.', '当前没有输入快照。', '目前沒有輸入快照。'), vim.log.levels.INFO)
  end
  vim.ui.select({tr('Cancel', '取消', '取消'), tr('Discard capture', '丢弃快照', '丟棄快照')}, {
    prompt = tr('Remove the captured input from this session?', '从本会话移除捕获的输入？', '從本工作階段移除擷取的輸入？'),
  }, function(_, choice)
    if choice ~= 2 or state.closed or state.busy or state.canvas_snapshot ~= snapshot or state.canvas_snapshot_cleanup ~= cleanup then return end
    cleanup(); render(state)
  end)
end

local function recheck_after_edit(state)
  local edit = state.last_edit
  if not edit then
    notify(tr('There is no acknowledged source edit in this session; run a forward pass instead.',
      '本次会话没有已确认的源码修改；请直接执行前向。', '本工作階段沒有已確認的原始碼修改；請直接執行前向。'), vim.log.levels.INFO)
    return
  end
  local recheck_args = { 'model', 'probe' }
  if edit.snapshot and not edit.snapshot.cleaned and type(edit.snapshot.path) == 'string' and type(edit.input_digest) == 'string' and #edit.input_digest == 64 and edit.input_digest:match('^[0-9a-f]+$') then
    vim.list_extend(recheck_args, { '--replay-input-from', edit.snapshot.path, '--if-input-content', edit.input_digest })
  end
  run(state, tr('Run an independent forward after the source change', '源码修改后运行独立前向', '原始碼修改後執行獨立前向'),
    recheck_args, function(report, err, operation_args, stale, report_buf)
      if state.last_edit ~= edit then return end
      local data = report and report.data
      local provenance = type(data) == 'table' and type(data.run_provenance) == 'table' and data.run_provenance or nil
      local provenance_execution = provenance and provenance.execution_status == 'executed'
      local content = type(data) == 'table' and data.batch_content
      local comparable_input = type(content) == 'table' and content.status == 'available'
        and content.algorithm == 'sha256-forward-input-v1' and type(content.digest) == 'string'
        and #content.digest == 64 and content.digest:match('^[0-9a-f]+$')
      local preview_digest = type(edit.input_digest) == 'string' and #edit.input_digest == 64
        and edit.input_digest:match('^[0-9a-f]+$')
      local input_status = (not comparable_input or not preview_digest) and tr('input identity unknown', '输入身份未知', '輸入身分未知')
        or (content.digest == edit.input_digest and tr('same input content as preview', '输入内容与预览相同', '輸入內容與預覽相同')
          or tr('input content differs from preview', '输入内容与预览不同', '輸入內容與預覽不同'))
      local context_matches = not stale and type(data) == 'table' and data.config_revision == edit.revision
        and state.model == edit.model and state.batch == edit.batch and state.batch_binding == edit.batch_binding and state.opts.python == edit.python
        and state.opts.working_directory == edit.working_directory
        and vim.deep_equal(state.opts.project_import_roots, edit.import_roots)
        and vim.deep_equal(state.model_params or {}, edit.model_params or {})
        and vim.deep_equal(state.batch_params or {}, edit.batch_params or {})
      local resolved_python = state.opts.python
        or (state.project_info and type(state.project_info.runtime_python) == 'string' and state.project_info.runtime_python)
      for index, arg in ipairs(operation_args or {}) do
        if arg == '--python' then resolved_python = operation_args[index + 1]; break end
      end
      local same_python = type(edit.resolved_python) == 'string' and edit.resolved_python ~= ''
        and resolved_python == edit.resolved_python
      context_matches = context_matches and same_python
      local reused = type(data) == 'table' and (data.forward_execution == 'reused'
        or (type(data.evidence_cache) == 'table' and data.evidence_cache.status == 'reused'))
      local passed = not err and report and report.operation == 'probe' and report.status == 'success'
        and not reused and type(data) == 'table' and data.forward_execution == 'executed' and provenance_execution == true
      local model_identity = provenance and type(provenance.model) == 'table' and provenance.model or {}
      local environment = provenance and type(provenance.environment) == 'table' and provenance.environment or {}
      local identity_status = tr('weights ', '权重', '權重')
        .. (model_identity.weight_comparison == 'matched' and tr('matched', '一致', '一致') or tr('unknown or changed', '未知或已变化', '未知或已變更'))
        .. tr(' · environment ', ' · 环境', ' · 環境')
        .. (environment.status == 'available' and type(environment.identity_sha256) == 'string'
          and tr('fingerprinted for this run', '本次运行有指纹', '本次執行有指紋') or tr('unknown', '未知', '未知'))
        .. tr(' · preview identity comparison unavailable', ' · 无预览身份对照', ' · 無預覽身分比對')
      local summary = (reused and tr('Previous evidence reused; independent forward not run', '复用先前证据；尚未执行独立前向', '重用先前證據；尚未執行獨立前向')
          or (not err and report and report.status == 'success' and type(data) == 'table' and (data.forward_execution ~= 'executed' or provenance_execution ~= true)
          and tr('Independent forward execution is unconfirmed', '独立前向是否执行尚未确认', '獨立前向是否執行尚未確認')
        or (passed and tr('Independent forward passed', '独立前向已通过', '獨立前向已通過')
          or tr('Independent forward did not pass', '独立前向未通过', '獨立前向未通過')))) .. ' · ' .. input_status
      summary = tr('Earlier source save was acknowledged; current files may have changed · ',
        '此前源码保存已确认；当前文件可能已变化 · ',
        '先前原始碼儲存已確認；目前檔案可能已變更 · ') .. summary
      if not context_matches then
        summary = summary .. tr(' · edit context differs or is stale', ' · 修改上下文不同或已过期', ' · 修改上下文不同或已過期')
      end
      if not same_python then
        summary = summary .. tr(' · interpreter selection differs or is unknown', ' · 解释器选择不同或未知', ' · 直譯器選擇不同或未知')
      end
      summary = summary .. ' · ' .. identity_status .. tr(' · source and preview device are not fully pinned',
        ' · 源码和预览设备未完整固定', ' · 原始碼和預覽裝置未完整固定')
      -- A successful forward on a different (or unidentifiable) input is
      -- useful evidence, but it does not finish the promised comparison to
      -- the candidate preview. Keep the recheck action available.
      local replayed = not edit.snapshot or (type(data) == 'table' and type(data.batch_snapshot) == 'table'
        and data.batch_snapshot.status == 'replayed'
        and data.batch_snapshot.format == 'model-maven-forward-input-snapshot-v1')
      local same_preview_input = comparable_input and preview_digest and replayed
        and content.digest == edit.input_digest
      if passed and context_matches and same_preview_input then
        edit.awaiting_recheck = false
        if edit.snapshot and edit.snapshot.cleanup then edit.snapshot.cleanup(); edit.snapshot = nil end
      else
        edit.awaiting_recheck = true
        summary = summary .. tr(' · preview input comparison remains unverified',
          ' · 与预览输入的重验尚未确认', ' · 與預覽輸入的重新驗證尚未確認')
      end
      state.last.recheck_summary = summary
      state.result_label = summary
      render(state)
      if report_buf and vim.api.nvim_buf_is_valid(report_buf) then
        vim.bo[report_buf].modifiable = true
        vim.b[report_buf].model_maven_action_offset = (vim.b[report_buf].model_maven_action_offset or 0) + 2
        vim.api.nvim_buf_set_lines(report_buf, 0, 0, false, { summary, '' })
        vim.bo[report_buf].modifiable = false
      end
    end, nil, false, nil, function()
      if state.closed and edit.snapshot and edit.snapshot.cleanup then edit.snapshot.cleanup() end
    end, true)
end

probe_local = function(state)
  if state.busy then notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN); return end
  vim.ui.input({ prompt = tr('Module path to replay: ', '要重放的模块路径：', '要重播的模組路徑：'), default = state.last_selection or '' }, function(path)
    if not path or path == '' or state.closed then return end
    if path == 'model' then
      notify(tr('Choose a child module for local replay.', '局部重放请选择一个子模块。', '局部重播請選擇一個子模組。'), vim.log.levels.INFO); return
    end
    vim.ui.input({ prompt = tr('Invocation number or all: ', '调用序号或 all：', '呼叫序號或 all：'), default = 'all' }, function(call)
      if not call or (call ~= 'all' and not call:match('^[1-9]%d*$')) or state.closed then return end
      state.last_selection = path
      local title = tr('Run full forward, then replay the selected observed module on copies',
        '先运行完整前向，再在副本上重放所选已观察模块',
        '先執行完整前向，再在副本上重播所選已觀察模組')
        .. tr(' (global side effects are not isolated)', '（全局副作用未隔离）', '（全域副作用未隔離）')
      run(state, title, { 'model', 'probe', path, '--local', '--call', call })
    end)
  end)
end

local function compare_observations(state)
  local records = state.observations or {}
  if #records < 2 then
    notify(tr('Run at least two forward passes to compare observations.', '请至少运行两次前向后再比较。', '請至少執行兩次前向後再比較。'), vim.log.levels.INFO); return
  end
  local generation = state.observation_generation
  local labels = {}
  for index, record in ipairs(records) do
    labels[index] = tostring(index) .. '. ' .. record.label
  end
  vim.ui.select(labels, { prompt = tr('Choose the first observation', '选择第一次观察', '選擇第一次觀察') }, function(_, left_index)
    if not left_index or state.closed or state.observation_generation ~= generation then return end
    vim.ui.select(labels, { prompt = tr('Choose the second observation', '选择第二次观察', '選擇第二次觀察') }, function(_, right_index)
      if not right_index or state.closed or state.observation_generation ~= generation then return end
      local left, right = records[left_index], records[right_index]
      if not left or not right then return end
      local function path_counts(record)
        local counts = {}
        for _, call in ipairs(record.calls) do
          local seen = {}
          for _, path in ipairs(call.paths) do
            if not seen[path] then counts[path] = (counts[path] or 0) + 1; seen[path] = true end
          end
        end
        return counts
      end
      local a, b = path_counts(left), path_counts(right)
      local keys, seen = {}, {}
      for path in pairs(a) do seen[path] = true; keys[#keys + 1] = path end
      for path in pairs(b) do if not seen[path] then keys[#keys + 1] = path end end
      table.sort(keys)
      local function value(v)
        return type(v) == 'string' and v ~= '' and v or tr('unknown', '未知', '未知')
      end
      local function input_identity(record)
        local content = record.batch_content
        if type(content) == 'table' and content.status == 'available' and content.algorithm == 'sha256-forward-input-v1'
            and type(content.digest) == 'string' and #content.digest == 64 and content.digest:match('^[0-9a-f]+$') then
          return 'sha256:' .. content.digest
        end
        return tr('unknown', '未知', '未知')
      end
      local function reported_seed(record)
        if record.seed == vim.NIL and record.seed_policy == 'runtime' then
          return tr('runtime state', '运行时状态', '執行時狀態')
        end
        if type(record.seed) ~= 'number' then return tr('unknown', '未知', '未知') end
        if math.abs(record.seed) > 9007199254740991 then
          return tr('too large to display exactly', '数值过大，无法精确显示', '數值過大，無法精確顯示')
        end
        return tostring(record.seed)
      end
      local function describe(label, record)
        return {
          label .. ': ' .. record.label,
          tr('  Model entry: ', '  模型入口：', '  模型入口：') .. record.model,
          tr('  Input entry: ', '  输入入口：', '  輸入入口：') .. record.input,
          tr('  Requested input binding: ', '  请求的输入绑定：', '  要求的輸入繫結：') .. value(record.requested_batch_binding),
          tr('  Model parameter names: ', '  模型参数名：', '  模型參數名稱：') .. table.concat(record.model_parameter_names or {}, ', '),
          tr('  Input parameter names: ', '  输入参数名：', '  輸入參數名稱：') .. table.concat(record.batch_parameter_names or {}, ', '),
          tr('  Python choice: ', '  Python 选择：', '  Python 選擇：') .. record.python,
          tr('  Actual Python: ', '  实际 Python：', '  實際 Python：') .. value(record.runtime and record.runtime.python_executable),
          tr('  Python version: ', '  Python 版本：', '  Python 版本：') .. value(record.runtime and record.runtime.python_version),
          tr('  PyTorch version: ', '  PyTorch 版本：', '  PyTorch 版本：') .. value(record.runtime and record.runtime.pytorch_version),
          tr('  Input selection source: ', '  输入选择来源：', '  輸入選擇來源：') .. value(record.input_sources and record.input_sources.batch),
          tr('  Model selection source: ', '  模型选择来源：', '  模型選擇來源：') .. value(record.input_sources and record.input_sources.model),
          tr('  Configuration revision: ', '  配置修订：', '  設定修訂：') .. value(record.config_revision),
          tr('  Reported seed (variant initialization may differ): ', '  报告的种子（变体初始化可能不同）：', '  回報的種子（變體初始化可能不同）：') .. reported_seed(record),
          tr('  Requested / resolved model device: ', '  请求 / 解析的模型设备：', '  要求 / 解析的模型裝置：')
            .. value(record.runtime and record.runtime.probe_device and record.runtime.probe_device.device_requested)
            .. ' / ' .. value(record.runtime and record.runtime.probe_device and record.runtime.probe_device.device),
          tr('  Observed mode: ', '  观察模式：', '  觀察模式：') .. value(record.observed_mode),
          tr('  Scope: ', '  范围：', '  範圍：') .. tostring(record.scope or 'unknown') .. (record.scope_path and (' · ' .. record.scope_path) or ''),
          tr('  Stable batch ID: ', '  稳定批次 ID：', '  穩定批次 ID：') .. (record.batch_identity_stable and value(record.batch_id) or tr('unknown', '未知', '未知')),
          tr('  Input content: ', '  输入内容：', '  輸入內容：') .. input_identity(record),
          tr('  Worker trace truncated: ', '  worker 调用记录截断：', '  worker 呼叫紀錄截斷：')
            .. (type(record.trace_truncated) == 'boolean' and tostring(record.trace_truncated) or tr('unknown', '未知', '未知')),
          tr('  Workspace summary limits (calls / aliases / sources): ', '  工作区摘要截断（调用 / 别名 / 源码）：', '  工作區摘要截斷（呼叫 / 別名 / 原始碼）：')
            .. (record.calls_available and tostring(record.call_summary_truncated) .. ' / ' .. tostring(record.alias_summary_truncated)
              .. ' / ' .. tostring(record.source_summary_truncated) or tr('calls unavailable', '调用记录不可用', '呼叫紀錄無法使用')),
          tr('  Unreadable call details: ', '  不可读取的调用详情：', '  無法讀取的呼叫詳情：')
            .. (record.calls_available and tostring(record.call_details_incomplete) or tr('unknown', '未知', '未知')),
          tr('  Reused prior forward evidence: ', '  复用先前前向证据：', '  重用先前前向證據：')
            .. (record.evidence_reused and 'true' or (record.forward_execution == 'executed' and 'false' or tr('unknown', '未知', '未知'))),
          tr('  Forward execution: ', '  前向执行：', '  前向執行：') .. value(record.forward_execution),
          tr('  Workspace context changed since observation: ', '  观察后工作区上下文已变化：', '  觀察後工作區上下文已變更：') .. tostring(record.stale_on_arrival or (state.change_epoch or 0) ~= record.epoch),
        }
      end
      local lines = { tr('Compare observed forward passes', '比较已观察的前向', '比較已觀察的前向'),
        tr('[d] Choose a recorded path to inspect, edit, replay or locate source; [q] close.',
          '[d] 选择记录路径以检查、修改、重放或定位源码；[q] 关闭。',
          '[d] 選擇紀錄路徑以檢查、修改、重播或定位原始碼；[q] 關閉。'), '' }
      vim.list_extend(lines, describe('A', left))
      lines[#lines + 1] = ''
      vim.list_extend(lines, describe('B', right))
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Output description: ', '输出描述：', '輸出描述：')
        .. ((left.outputs == nil or right.outputs == nil) and tr('unknown or too large', '未知或过大', '未知或過大')
          or (vim.deep_equal(left.outputs, right.outputs) and tr('same recorded metadata', '记录的元数据相同', '記錄的中繼資料相同')
            or tr('recorded metadata differs', '记录的元数据不同', '記錄的中繼資料不同')))
      lines[#lines + 1] = tr('Requested input binding: ', '请求的输入绑定：', '要求的輸入繫結：')
        .. ((left.requested_batch_binding == nil or right.requested_batch_binding == nil)
          and tr('unknown', '未知', '未知')
          or (left.requested_batch_binding == right.requested_batch_binding and tr('same', '相同', '相同') or tr('different', '不同', '不同')))
      lines[#lines + 1] = tr('Automatic binding describes a request, not a verified calling convention.',
        '自动绑定仅表示请求方式，不证明实际调用约定相同。', '自動繫結僅表示要求方式，不證明實際呼叫約定相同。')
      lines[#lines + 1] = tr('Weights, full environment and random state are not pinned; matching entry names do not prove comparable runs.',
        '权重、完整环境和随机状态未固定；入口相同不能证明两次运行可比。',
        '權重、完整環境和隨機狀態未固定；入口相同不能證明兩次執行可比。')
      local common, changed = 0, 0
      for file, digest in pairs(left.observed_sources or {}) do
        local other = (right.observed_sources or {})[file]
        if other then common = common + 1; if other ~= digest then changed = changed + 1 end end
      end
      if left.source_conflict or right.source_conflict then
        lines[#lines + 1] = tr('Observed source identities conflict; comparison is unknown.', '观察到的源码身份冲突，无法比较。', '觀察到的原始碼身分衝突，無法比較。')
      else
        lines[#lines + 1] = tr('Common observed implementation files / changed digests: ', '共同观察到的实现文件数 / 摘要变化数：', '共同觀察到的實作檔案數 / 摘要變更數：') .. common .. ' / ' .. changed
        lines[#lines + 1] = tr('Only recorded implementation files were compared; other project code and external libraries are not covered.',
          '仅比较已记录的实现文件，不覆盖其他项目代码或外部库。', '僅比較已記錄的實作檔案，不涵蓋其他專案程式碼或外部程式庫。')
      end
      lines[#lines + 1] = tr('Counts describe recorded calls and aliases only. A missing path is not proof it was never executed.',
        '计数只描述已记录调用和别名；缺少路径不能证明它从未执行。',
        '計數只描述已記錄呼叫和別名；缺少路徑不能證明它從未執行。')
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Recorded path counts (A / B):', '已记录路径次数（A / B）：', '已記錄路徑次數（A / B）：')
      for index, path in ipairs(keys) do
        if index > 200 then lines[#lines + 1] = tr('Further paths omitted from display.', '其余路径未在此显示。', '其餘路徑未在此顯示。'); break end
        lines[#lines + 1] = path .. '  ' .. tostring(a[path] or '?') .. ' / ' .. tostring(b[path] or '?')
      end
      for _, item in ipairs({ { label = 'A', record = left }, { label = 'B', record = right } }) do
        lines[#lines + 1] = ''
        lines[#lines + 1] = tr('Output metadata ', '输出元数据 ', '輸出中繼資料 ') .. item.label .. ':'
        local detail = item.record.outputs and vim.split(vim.inspect(item.record.outputs), '\n', { plain = true })
          or { tr('Not retained.', '未保留。', '未保留。') }
        for index, line in ipairs(detail) do
          if index > 200 then lines[#lines + 1] = tr('Further metadata omitted from display.', '其余元数据未在此显示。', '其餘中繼資料未在此顯示。'); break end
          lines[#lines + 1] = line
        end
      end
      local buf = vim.api.nvim_create_buf(false, true)
      vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
      vim.bo[buf].modifiable = false
      local opened = pcall(vim.cmd, 'botright split')
      if not opened then opened = pcall(vim.cmd, 'botright vsplit') end
      if not opened then
        pcall(vim.api.nvim_buf_delete, buf, { force = true })
        notify(tr('Cannot open the comparison; enlarge the terminal or close a window.',
          '无法打开比较；请放大终端或关闭窗口。', '無法開啟比較；請放大終端或關閉視窗。'), vim.log.levels.WARN); return
      end
      vim.api.nvim_win_set_buf(0, buf)
      vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close observation comparison' })
      vim.keymap.set('n', 'd', function()
        if state.closed or state.observation_generation ~= generation or state.opts.project ~= left.project
            or state.opts.project ~= right.project then
          notify(tr('The observation list or project changed; open the comparison again.',
            '观察列表或项目已变化，请重新打开比较。', '觀察列表或專案已變更，請重新開啟比較。'), vim.log.levels.WARN)
          return
        end
        -- A selection dialog may remain open while another window changes the
        -- runtime or project. Never apply its historical path to that new context.
        local selection_epoch = state.change_epoch or 0
        local function selection_current()
          return not state.closed and state.observation_generation == generation
            and state.opts.project == left.project and state.opts.project == right.project
            and (state.change_epoch or 0) == selection_epoch
        end
        local choices = {}
        for _, path in ipairs(keys) do
          choices[#choices + 1] = path .. '  ' .. tostring(a[path] or '?') .. ' / ' .. tostring(b[path] or '?')
        end
        if #choices == 0 then notify('No recorded module paths.', vim.log.levels.INFO); return end
        vim.ui.select(choices, { prompt = tr('Select a recorded path (historical, not proof of current execution)',
          '选择记录路径（属于历史观察，不代表当前执行）', '選擇紀錄路徑（屬於歷史觀察，不代表目前執行）') }, function(_, index)
          local path = index and keys[index]
          if not path then return end
          if not selection_current() then
            notify(tr('Context changed; choose the recorded path again.', '上下文已变化，请重新选择记录路径。', '上下文已變更，請重新選擇紀錄路徑。'), vim.log.levels.WARN)
            return
          end
          local function source_for(record)
            local found
            for _, call in ipairs(record.calls) do
              if vim.tbl_contains(call.paths, path) and call.implementation then
                local impl = call.implementation
                if found and (found.source ~= impl.source or found.digest ~= impl.digest) then return nil end
                found = impl
              end
            end
            return found and { path = path, source = found.source, digest = found.digest, line = found.line } or nil
          end
          local source_a, source_b = source_for(left), source_for(right)
          local actions = {
            tr('Inspect current module', '检查当前模块', '檢查目前模組'),
            tr('Preview current source change', '预览当前源码修改', '預覽目前原始碼修改'),
            tr('Run a new local replay', '执行新的局部重放', '執行新的局部重播'),
          }
          local sources = {}
          if source_a then actions[#actions + 1] = tr('Open recorded A source', '打开 A 记录的源码', '開啟 A 紀錄的原始碼'); sources[#actions] = source_a end
          if source_b then actions[#actions + 1] = tr('Open recorded B source', '打开 B 记录的源码', '開啟 B 紀錄的原始碼'); sources[#actions] = source_b end
          vim.ui.select(actions, { prompt = path }, function(_, action)
            if not action then return end
            if not selection_current() then
              notify(tr('Context changed; choose the recorded path again.', '上下文已变化，请重新选择记录路径。', '上下文已變更，請重新選擇紀錄路徑。'), vim.log.levels.WARN)
              return
            end
            state.last_selection = path
            if action == 1 then run(state, tr('Inspect selected layer', '检查所选层', '檢查所選層'), { 'layer', 'show', path })
            elseif action == 2 then preview_layer(state, path)
            elseif action == 3 then probe_local(state)
            else open_verified_implementation(state, sources[action]) end
          end)
        end)
      end, { buffer = buf, silent = true, desc = 'Choose a recorded module path' })
    end)
  end)
end

local resume_run, evaluate_run, export_run

local function follow_run(state, id)
  if state.closed then return end
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
  if not open_aux_buffer(buf, false, false) then return end
  local timer = vim.uv.new_timer()
  if not timer then
    pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), true)
    notify(tr('Could not start progress refresh.', '无法启动进度刷新。', '無法啟動進度重新整理。'), vim.log.levels.ERROR)
    return
  end
  local closed, in_flight, errors, paused, stop_in_flight, terminal = false, false, 0, false, false, false
  local animation_timer, progress_row, progress_data = nil, nil, nil
  local last_run_status
  local stop_generation = 0
  local opts = vim.deepcopy(state.opts)
  local function stop_timer()
    if timer and not timer:is_closing() then timer:stop(); timer:close() end
    timer = nil
  end
  local function stop_animation()
    if animation_timer and not animation_timer:is_closing() then animation_timer:stop(); animation_timer:close() end
    animation_timer = nil
  end
  local function close()
    closed = true
    stop_timer()
    stop_animation()
  end
  vim.api.nvim_create_autocmd('BufWipeout', { buffer = buf, once = true, callback = close })
  local function display(lines)
    if closed or not vim.api.nvim_buf_is_valid(buf) then return end
    local views = {}
    for _, win in ipairs(vim.fn.win_findbuf(buf)) do
      if vim.api.nvim_win_is_valid(win) then
        local ok, view = pcall(vim.api.nvim_win_call, win, vim.fn.winsaveview)
        if ok then views[win] = view end
      end
    end
    vim.bo[buf].modifiable = true
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
    vim.bo[buf].modifiable = false
    for win, view in pairs(views) do
      if vim.api.nvim_win_is_valid(win) and vim.api.nvim_win_get_buf(win) == buf then
        pcall(vim.api.nvim_win_call, win, function() vim.fn.winrestview(view) end)
      end
    end
  end
  local function animate_progress()
    if closed then return end
    if state.closed or not vim.api.nvim_buf_is_valid(buf) then close(); return end
    if not progress_row or not progress_data then return end
    if #vim.fn.win_findbuf(buf) == 0 then return end
    local bar = require('model_maven.progress_ui').bar(progress_data.step, progress_data.total, 20,
      progress_data.active and not paused and not terminal)
    vim.bo[buf].modifiable = true
    vim.api.nvim_buf_set_lines(buf, progress_row - 1, progress_row, false, {bar})
    vim.bo[buf].modifiable = false
  end
  local function start_animation()
    if animation_timer or vim.env.MODEL_MAVEN_REDUCE_MOTION == '1' then return end
    animation_timer = vim.uv.new_timer()
    if animation_timer then animation_timer:start(120, 120, vim.schedule_wrap(animate_progress)) end
  end
  start_animation()
  local function plain(value)
    if value == nil or value == vim.NIL then value = '?' end
    return (tostring(value):gsub('[%z\1-\8\11\12\14-\31\127]', '?'):gsub('[\r\n]', ' '))
  end
  local function poll(force)
    if closed or state.closed or not vim.api.nvim_buf_is_valid(buf) then close(); return end
    if in_flight or (paused and not force) then return end
    in_flight = true
    local observed_generation = stop_generation
    transport.request(opts, { 'runs', 'attach', id, '--follow=false' }, function(report, err)
      in_flight = false
      if closed or state.closed or not vim.api.nvim_buf_is_valid(buf) then close(); return end
      if observed_generation ~= stop_generation then
        poll(true)
        return
      end
      local data = report and report.data
      local record = type(data) == 'table' and data.record
      if err or not report or report.operation ~= 'runs_attach' or report.status ~= 'success'
          or type(data) ~= 'table' or data.run_id ~= id or type(record) ~= 'table' then
        last_run_status = nil
        errors = errors + 1
        if errors >= 3 then stop_timer(); stop_animation() end
        progress_row, progress_data = nil, nil
        display({ tr('Run progress · state unknown', '运行进度 · 状态未知', '執行進度 · 狀態未知'), id, '',
          tr('Could not read the current snapshot. Refresh before deciding what to do.', '无法读取当前快照，请刷新后再决定下一步。', '無法讀取目前快照，請重新整理後再決定下一步。'),
          plain(err and err.message or (report and report.status) or '?'),
          errors >= 3 and tr('Automatic refresh stopped after repeated errors.', '连续读取失败，已停止自动刷新。', '連續讀取失敗，已停止自動重新整理。') or '',
          '', tr('[r] Refresh  [d] Details  [p] Pause/resume  [q] Close', '[r] 刷新  [d] 详情  [p] 暂停/继续  [q] 关闭', '[r] 重新整理  [d] 詳情  [p] 暫停/繼續  [q] 關閉') })
        return
      end
      errors = 0
      local progress = type(data.progress) == 'table' and data.progress or {}
      local latest, omitted = nil, false
      for index = #progress, 1, -1 do
        local event = progress[index]
        if type(event) == 'table' and event.event == 'progress_line_omitted' then omitted = true end
        if not latest and type(event) == 'table' and type(event.step) == 'number' then latest = event end
      end
      local status = type(record.status) == 'string' and record.status or 'unknown'
      last_run_status = status
      local progress_state = (status == 'queued' or status == 'pending' or status == 'starting') and 'waiting'
        or (status == 'running' and 'running')
        or (status == 'stopping' and 'stop_requested')
        or (status == 'completed' or status == 'success') and 'completed'
        or (status == 'failed' or status == 'error') and 'failed'
        or (status == 'interrupted' and 'interrupted')
        or (status == 'cancelled' or status == 'canceled' or status == 'stopped') and 'cancelled'
        or 'unknown'
      local lines = { tr('Run progress', '运行进度', '執行進度'),
        tr('[r] Refresh  [d] Details  [s] Stop  [p] Pause refresh  [q] Close', '[r] 刷新  [d] 详情  [s] 停止  [p] 暂停刷新  [q] 关闭', '[r] 重新整理  [d] 詳情  [s] 停止  [p] 暫停重新整理  [q] 關閉'), id,
        tr('Project: ', '项目：', '專案：') .. plain(opts.project),
        tr('Updated: ', '刷新时间：', '重新整理時間：') .. os.date('%H:%M:%S') }
      if progress_state == 'unknown' then
        lines[#lines + 1] = tr('Recorded status: ', '记录中的状态：', '紀錄中的狀態：') .. plain(status)
      end
      local can_cancel
      if type(record.cancellable) == 'boolean' then can_cancel = record.cancellable end
      vim.list_extend(lines, validation_progress.progress_lines({
        state = progress_state,
        cancellable = can_cancel,
        detail = type(record.cancel_state) == 'string' and record.cancel_state or nil,
      }))
      progress_data = {step = latest and latest.step, total = latest and latest.total,
        active = progress_state == 'running' or progress_state == 'waiting' or progress_state == 'stop_requested'}
      progress_row = #lines + 1
      lines[progress_row] = require('model_maven.progress_ui').bar(progress_data.step, progress_data.total, 20, progress_data.active and not paused)
      lines[#lines + 1] = tr('Latest recorded progress:', '最近记录的进度：', '最近記錄的進度：')
      if type(latest) == 'table' then
        lines[#lines + 1] = tr('Step: ', '步数：', '步數：') .. plain(latest.step) .. ' / ' .. plain(latest.total)
        if latest.mean_loss ~= nil and latest.mean_loss ~= vim.NIL then
          lines[#lines + 1] = tr('Mean loss: ', '平均损失：', '平均損失：') .. plain(latest.mean_loss)
        end
        if type(latest.metrics) == 'table' then
          local names = {}
          for name, value in pairs(latest.metrics) do
            if type(name) == 'string' and type(value) == 'number' then names[#names + 1] = name end
          end
          table.sort(names)
          for index, name in ipairs(names) do
            if index > 16 then break end
            if type(name) == 'string' and type(latest.metrics[name]) == 'number' then
              lines[#lines + 1] = tr('Reported metric ', '报告指标 ', '回報指標 ') .. plain(name):sub(1, 128) .. ': ' .. plain(latest.metrics[name])
            end
          end
        end
        lines[#lines + 1] = tr('Checkpoint reported: ', '已报告检查点：', '已回報檢查點：') .. plain(latest.checkpoint)
      else lines[#lines + 1] = tr('No progress recorded yet.', '尚无进度记录。', '尚無進度紀錄。') end
      if omitted then
        lines[#lines + 1] = tr('An oversized progress line was omitted; inspect the worker log.',
          '有过大的进度行被省略，请检查运行日志。', '有過大的進度行被省略，請檢查執行日誌。')
      end
      lines[#lines + 1] = ''
      lines[#lines + 1] = tr('Recent log output:', '最近日志：', '最近日誌：')
      local log = type(data.log_tail) == 'string' and data.log_tail or ''
      local log_lines = vim.split(log, '\n', { plain = true })
      local start = math.max(1, #log_lines - 79)
      for i = start, #log_lines do lines[#lines + 1] = plain(log_lines[i]) end
      lines[#lines + 1] = ''
      display(lines)
      terminal = progress_state == 'completed' or progress_state == 'failed'
        or progress_state == 'interrupted' or progress_state == 'cancelled'
      if terminal then
        stop_timer()
        stop_animation()
      elseif not paused then
        start_animation()
      end
    end)
  end
  vim.keymap.set('n', 'r', function() poll(true) end, { buffer = buf, silent = true, desc = 'Refresh run progress' })
  vim.keymap.set('n', 's', function()
    if closed or state.closed or stop_in_flight or state.opts.project ~= opts.project or state.opts.cli ~= opts.cli then return end
    if last_run_status ~= 'running' then
      notify(last_run_status == 'stopping'
        and tr('A stop has already been requested; refresh for the final status.', '已请求停止，请刷新查看最终状态。', '已要求停止，請重新整理查看最終狀態。')
        or tr('Run status is not currently reported as running; refresh before requesting a stop.', '运行状态当前不是已确认运行中；请刷新后再请求停止。', '執行狀態目前不是已確認執行中；請重新整理後再要求停止。'), vim.log.levels.INFO)
      return
    end
    vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Request stop', '请求停止', '要求停止') }, {
      prompt = tr('Request a cooperative stop for ', '请求协作停止 ', '要求協作停止 ') .. id
        .. tr('? User code must honor the request.', '？用户代码需要配合处理。', '？使用者程式碼需要配合處理。'),
    }, function(_, choice)
      if choice ~= 2 or closed or state.closed or stop_in_flight or state.opts.project ~= opts.project or state.opts.cli ~= opts.cli then return end
      if last_run_status ~= 'running' then
        notify(tr('Run status changed; refresh before requesting a stop.', '运行状态已变化，请刷新后再请求停止。', '執行狀態已變更，請重新整理後再要求停止。'), vim.log.levels.WARN)
        return
      end
      stop_in_flight = true
      -- The last snapshot is no longer sufficient to authorize another stop
      -- once a request is in flight, even if its receipt is lost.
      stop_generation = stop_generation + 1
      last_run_status = nil
      transport.request(opts, { 'runs', 'stop', id }, function(report, err)
        stop_in_flight = false
        if closed or state.closed then return end
        stop_generation = stop_generation + 1
        last_run_status = nil
        if err or not report or report.operation ~= 'runs_stop' or report.status ~= 'success' then
          notify(tr('Stop outcome is unknown; refresh the run before retrying.', '停止结果未知，请刷新运行状态后再重试。', '停止結果未知，請重新整理執行狀態後再重試。'), vim.log.levels.WARN)
        else
          notify(tr('Stop requested; refresh to confirm the final state.', '已请求停止，请刷新确认最终状态。', '已要求停止，請重新整理確認最終狀態。'), vim.log.levels.INFO)
        end
        poll(true)
      end)
    end)
  end, { buffer = buf, silent = true, desc = 'Request cooperative stop' })
  vim.keymap.set('n', 'd', function()
    if closed or state.closed or state.busy or state.opts.project ~= opts.project or state.opts.cli ~= opts.cli then
      notify(tr('The workspace is busy or its project changed.', '工作区正忙或项目已变化。', '工作區正忙或專案已變更。'), vim.log.levels.WARN); return
    end
    local epoch = state.change_epoch or 0
    state.busy = tr('Reading run details', '读取运行详情', '讀取執行詳情'); render(state)
    request(state, { 'runs', 'show', id }, function(report, err, stderr)
      state.busy = nil
      if state.closed or state.opts.project ~= opts.project or state.opts.cli ~= opts.cli or (state.change_epoch or 0) ~= epoch then
        render(state); notify(tr('Context changed; open the run again.', '上下文已变化，请重新打开运行记录。', '上下文已變更，請重新開啟執行紀錄。'), vim.log.levels.WARN); return
      end
      if report and report.status == 'success' and report.operation ~= 'runs_show' then
        err, report = { message = tr('Unexpected run operation in CLI response.', 'CLI 返回了非预期的运行操作。', 'CLI 回傳了非預期的執行操作。') }, nil
      end
      state.last = { report = report, transport_error = err, stderr = stderr,
        scope = tr('Run state is a point-in-time snapshot; refresh to see later changes.',
          '运行状态是某一时刻的快照；刷新可查看后续变化。', '執行狀態是某一時刻的快照；重新整理可查看後續變更。') }
      state.result_label = err and tr('CLI error', 'CLI 错误', 'CLI 錯誤') or (report and report.status or 'unknown')
      if not err and report and report.operation == 'runs_show' and report.status == 'success'
          and type(report.data) == 'table' and type(report.data.report) == 'table' then
        local recorded = report.data.report
        if (recorded.operation == 'generic_loop_trial' or recorded.operation == 'generic_loop_train')
            and recorded.status == 'success' and type(recorded.data) == 'table' then
          if recorded.data.termination_reason == 'loop_returned_before_target' then
            state.result_label = tr('loop returned before target', '循环提前结束，未达到目标步数', '迴圈提前結束，未達到目標步數')
          elseif recorded.data.termination_reason ~= 'target_reached' then
            state.result_label = tr('loop completion unknown', '循环是否达到目标未知', '迴圈是否達到目標未知')
          end
        end
      end
      render(state)
      show_report(state)
    end)
  end, { buffer = buf, silent = true, desc = 'Open run details' })
  vim.keymap.set('n', 'p', function()
    if not timer then
      if terminal then
        notify(tr('The recorded run has ended. Use r for a fresh snapshot.', '运行记录已结束；按 r 获取新快照。', '執行紀錄已結束；按 r 取得新快照。'), vim.log.levels.INFO)
        return
      end
      timer = vim.uv.new_timer()
      if not timer then
        notify(tr('Could not restart progress refresh; use r to retry.', '无法恢复进度刷新；按 r 重试。', '無法恢復進度重新整理；按 r 重試。'), vim.log.levels.ERROR)
        return
      end
      errors, paused = 0, false
      start_animation()
      timer:start(0, 3000, vim.schedule_wrap(poll))
      notify(tr('Progress refresh resumed.', '已继续刷新进度。', '已繼續重新整理進度。'), vim.log.levels.INFO)
      return
    end
    paused = not paused
    animate_progress()
    if paused then stop_animation() else start_animation() end
    notify(paused and tr('Progress refresh paused; training continues.', '已暂停刷新；训练继续。', '已暫停重新整理；訓練繼續。')
      or tr('Progress refresh resumed.', '已继续刷新进度。', '已繼續重新整理進度。'), vim.log.levels.INFO)
    if not paused then poll(true) end
  end, { buffer = buf, silent = true, desc = 'Pause or resume progress refresh' })
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close progress viewer' })
  progress_data, progress_row = {active = true}, 3
  display({ tr('Loading run progress…', '正在读取运行进度…', '正在讀取執行進度…'), id,
    require('model_maven.progress_ui').bar(nil, nil, 20, true) })
  timer:start(0, 3000, vim.schedule_wrap(poll))
end

-- Run history is a backend snapshot; inspecting it does not import project code.
local function browse_runs(state)
  if state.busy then
    notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN)
    return
  end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local function current()
    return not state.closed and state.opts.project == project and (state.change_epoch or 0) == epoch
  end
  local function query(args, expected, callback)
    if not current() or state.busy then return end
    state.busy = expected == 'runs_stop' and tr('Requesting stop', '正在请求停止', '正在要求停止')
      or tr('Reading run history', '读取运行记录', '讀取執行紀錄')
    render(state)
    request(state, args, function(report, err, stderr)
      state.busy = nil
      if not current() then
        render(state)
        notify(expected == 'runs_stop'
          and tr('Context changed after the stop request started. Inspect the original project run before retrying.',
            '停止请求开始后上下文发生变化；重试前请检查原项目中的运行状态。', '停止要求開始後上下文發生變更；重試前請檢查原專案中的執行狀態。')
          or tr('Project context changed; reopen run history.', '项目上下文已变化，请重新打开运行记录。', '專案上下文已變更，請重新開啟執行紀錄。'), vim.log.levels.WARN)
        return
      end
      if report and report.status == 'success' and report.operation ~= expected then
        err, report = { message = tr('Unexpected run operation in CLI response.', 'CLI 返回了非预期的运行操作。', 'CLI 回傳了非預期的執行操作。') }, nil
      end
      -- A successful list is navigation, not a new model result. Preserve
      -- the previous report if the user cancels the picker.
      local successful_list = expected == 'runs_list' and not err and report and report.status == 'success'
      if not successful_list then
        state.last = { report = report, transport_error = err, stderr = stderr,
          scope = expected == 'runs_stop' and tr('If this request fails or its receipt is lost, inspect run state before retrying.',
            '请求失败或回执丢失时，重试前请核查运行状态。', '要求失敗或回執遺失時，重試前請核查執行狀態。')
            or tr('Run state is a point-in-time snapshot; refresh to see later changes.',
              '运行状态是某一时刻的快照；刷新可查看后续变化。', '執行狀態是某一時刻的快照；重新整理可查看後續變更。') }
        state.result_label = err and tr('CLI error', 'CLI 错误', 'CLI 錯誤') or (report and report.status or 'unknown')
        if not err and expected == 'runs_show' and report and report.status == 'success'
            and type(report.data) == 'table' and type(report.data.report) == 'table' then
          local recorded = report.data.report
          if (recorded.operation == 'generic_loop_trial' or recorded.operation == 'generic_loop_train')
              and recorded.status == 'success' and type(recorded.data) == 'table' then
            if recorded.data.termination_reason == 'loop_returned_before_target' then
              state.result_label = tr('loop returned before target', '循环提前结束，未达到目标步数', '迴圈提前結束，未達到目標步數')
            elseif recorded.data.termination_reason ~= 'target_reached' then
              state.result_label = tr('loop completion unknown', '循环是否达到目标未知', '迴圈是否達到目標未知')
            end
          end
        end
      end
      render(state)
      if err or not report or report.status ~= 'success' then show_report(state); return end
      callback(report.data)
    end)
  end
  query({ 'runs', 'list' }, 'runs_list', function(data)
    if type(data) ~= 'table' or type(data.runs) ~= 'table' or not is_list(data.runs) then
      notify(tr('Run list is unavailable.', '运行列表不可用。', '執行清單無法使用。'), vim.log.levels.WARN)
      return
    end
    local rows, choices = {}, {}
    local statuses = {
      running = tr('running', '运行中', '執行中'),
      stopping = tr('stop requested', '已请求停止', '已要求停止'),
      completed = tr('completed', '已完成', '已完成'),
      failed = tr('failed', '失败', '失敗'),
      interrupted = tr('interrupted', '已中断', '已中斷'),
      unknown = tr('unknown', '状态未知', '狀態未知'),
    }
    local operations = {
      training_probe = tr('training trial', '训练试跑', '訓練試跑'),
      train = tr('training', '训练', '訓練'),
      generic_loop_trial = tr('user-loop trial', '用户循环试跑', '使用者迴圈試跑'),
      generic_loop_train = tr('user-loop run', '用户循环运行', '使用者迴圈執行'),
      evaluate = tr('evaluation', '评估', '評估'),
    }
    for _, row in ipairs(data.runs) do
      if type(row) == 'table' and type(row.id) == 'string' and row.id ~= '' and row.id:sub(1, 1) ~= '-' then
        rows[#rows + 1] = row
        local name = type(row.name) == 'string' and row.name or ''
        local progress = ''
        local summary = row.summary
        if type(summary) == 'table' and summary.completed_steps_source == 'worker_report'
            and type(summary.completed_steps) == 'number' and type(summary.requested_steps) == 'number' then
          local generic = row.operation == 'generic_loop_train' or row.operation == 'generic_loop_trial'
          progress = '  ·  ' .. (generic and tr('user-reported steps ', '用户报告步数 ', '使用者回報步數 ')
            or tr('steps ', '步数 ', '步數 ')) .. tostring(summary.completed_steps) .. '/' .. tostring(summary.requested_steps)
        end
        local status = statuses[row.status] or tostring(row.status or '?')
        local operation = operations[row.operation] or tostring(row.operation or '?')
        choices[#choices + 1] = row.id .. '  ·  ' .. operation .. '  ·  ' .. status .. progress .. (name ~= '' and ('  ·  ' .. name) or '')
      end
    end
    if #rows == 0 then
      notify(tr('No run records yet.', '尚无运行记录。', '尚無執行紀錄。'), vim.log.levels.INFO)
      return
    end
    local filter = ''
    local function choose_run()
    if not current() then return end
    local visible, labels = {}, { tr('Filter runs', '筛选运行记录', '篩選執行紀錄') .. (filter ~= '' and (': ' .. filter) or '') }
    for index, label in ipairs(choices) do
      local search = label .. ' ' .. tostring(rows[index].status or '') .. ' ' .. tostring(rows[index].operation or '')
      if filter == '' or search:lower():find(filter:lower(), 1, true) then
        visible[#visible + 1] = rows[index]
        labels[#labels + 1] = label
      end
    end
    vim.ui.select(labels, { prompt = tr('Choose a run (snapshot)', '选择运行记录（快照）', '選擇執行紀錄（快照）') }, function(_, index)
      if not index or not current() then return end
      if index == 1 then
        vim.ui.input({ prompt = tr('Filter by ID, name or status (empty clears): ',
          '按 ID、名称或状态筛选（留空清除）：', '按 ID、名稱或狀態篩選（留空清除）：'), default = filter }, function(value)
          if not current() then return end
          if value ~= nil then
            if #value > 256 or value:find('[\r\n%z\1-\31\127]') then
              notify(tr('Use at most 256 bytes of single-line text.', '请输入不超过 256 字节的单行文字。', '請輸入不超過 256 位元組的單行文字。'), vim.log.levels.WARN)
            else filter = vim.trim(value) end
          end
          choose_run()
        end)
        return
      end
      local selected = visible[index - 1]
      if not selected or not current() then return end
      local generic = selected.operation == 'generic_loop_train' or selected.operation == 'generic_loop_trial'
      vim.ui.select({ tr('Details', '详情', '詳情'), tr('Progress snapshot', '进度快照', '進度快照'),
        tr('Compare with another run', '与另一条记录比较', '與另一筆紀錄比較'),
        tr('Request stop at a step boundary', '请求在步骤边界停止', '要求在步驟邊界停止'),
        tr('Resume from checkpoint', '从检查点续训', '從檢查點續訓'),
        generic and tr('Evaluation: use your own evaluator', '评估：使用自己的评估器', '評估：使用自己的評估器') or tr('Evaluate checkpoint', '评估检查点', '評估檢查點'),
        generic and tr('Export: user-managed for this loop', '导出：由此循环自行管理', '匯出：由此迴圈自行管理') or tr('Export checkpoint and source', '导出检查点和源码', '匯出檢查點與原始碼'),
        tr('Follow progress', '持续查看进度', '持續查看進度'),
        tr('Use recorded runtime for this session', '本次会话使用记录的运行环境', '本工作階段使用記錄的執行環境'),
        generic and tr('Repeat: prepare a new user-loop trial', '重复：重新准备用户循环试跑', '重複：重新準備使用者迴圈試跑') or tr('Repeat a training trial', '重复训练试跑', '重複訓練試跑'),
        tr('Review unknown run blocking new tasks', '审核阻挡新任务的未知运行', '檢視阻擋新任務的未知執行'),
        tr('Use recorded training entry and parameters', '使用记录中的训练入口与参数', '使用紀錄中的訓練入口與參數') },
        { prompt = selected.id }, function(_, action)
          if not current() or not action then return end
          if action == 12 then
            query({ 'runs', 'show', selected.id }, 'runs_show', function(data)
              local inputs = type(data) == 'table' and data.inputs or nil
              local mode = type(inputs) == 'table' and inputs.training_mode or nil
              local entry = type(inputs) == 'table' and (mode == 'external-loop' and inputs.training_loop or inputs.training_step) or nil
              local params = type(inputs) == 'table' and inputs.training_params or nil
              local info = state.project_info
              local model = state.model or (info and info.model)
              local function redacted(value)
                if value == '[REDACTED]' then return true end
                if type(value) == 'table' then
                  for _, nested in pairs(value) do if redacted(nested) then return true end end
                end
                return false
              end
              local redactions = type(inputs) == 'table' and inputs.redacted_fields or nil
              local hidden = type(redactions) ~= 'table' or not is_list(redactions)
              if not hidden then
                for _, path in ipairs(redactions) do
                  if type(path) ~= 'string' or path:find('training_params', 1, true) or path:find('training_step', 1, true)
                      or path:find('training_loop', 1, true) then hidden = true; break end
                end
              end
              if not vim.tbl_contains({ 'managed-step', 'manual-step', 'external-loop' }, mode)
                  or type(entry) ~= 'string' or not entry:match('^[^%s:;=]+:[^%s:;=]+$') or #entry > 1024
                  or type(params) ~= 'table' or (next(params) and is_list(params)) or redacted(params) or hidden
                  or type(info) ~= 'table' or type(info.config_revision) ~= 'string'
                  or not project_config_current(state) or type(model) ~= 'string' or inputs.model ~= model then
                notify(tr('This record cannot supply complete training settings for the current model.',
                  '此记录无法为当前模型提供完整的训练入口与参数。', '此紀錄無法為目前模型提供完整的訓練入口與參數。'), vim.log.levels.WARN); return
              end
              for name in pairs(params) do
                if not parameter_name_candidate(name) then
                  notify(tr('Recorded training parameters are invalid.', '记录的训练参数无效。', '紀錄的訓練參數無效。'), vim.log.levels.WARN); return
                end
              end
              local ok, raw = pcall(vim.json.encode, next(params) and params or vim.empty_dict())
              if not ok or #raw > 65536 then return end
              local listed, revision = state.last, info.config_revision
              local prompt = tr('Use these values as editable defaults for this session? Other run settings remain separate.',
                '将这些值用作本次会话可编辑的默认值？其他运行设置仍需单独选择。',
                '將這些值用作本次工作階段可編輯的預設值？其他執行設定仍需單獨選擇。')
                .. '\n' .. mode .. ' · ' .. entry .. '\n' .. raw
              vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Use defaults', '使用默认值', '使用預設值') }, { prompt = prompt }, function(_, choice)
                if choice ~= 2 or not current() or state.last ~= listed or listed.context_changed
                    or not project_config_current(state) or not state.project_info
                    or state.project_info.config_revision ~= revision or (state.model or state.project_info.model) ~= model then return end
                state.last_training_entry = { project = project, model = model, mode = mode, value = entry,
                  params = raw, config_revision = revision }
                notify(tr('Training defaults loaded. Choose the same mode when preparing a run.',
                  '已载入训练默认值；准备运行时请选择相同模式。', '已載入訓練預設值；準備執行時請選擇相同模式。'), vim.log.levels.INFO)
              end)
            end)
          elseif action == 11 then
            query({ 'runs', 'acknowledge-unknown', selected.id }, 'runs_acknowledge_unknown', function(data)
              local report_buf = show_report(state)
