                  or #data.revision ~= 64 or not data.revision:match('^[0-9a-f]+$')
                  or not vim.tbl_contains({ 'no_verified_live_process', 'original_scope_not_observable' }, data.identity_check)
                  or not vim.tbl_contains({ 'matched', 'unverified', 'mismatch' }, data.process_scope) then return end
              local listed, revision = state.last, data.revision
              local unverified_scope = data.process_scope == 'unverified'
              local different_scope = data.process_scope == 'mismatch'
              review_gate(report_buf, { tr('Keep blocking', '继续阻挡', '繼續阻擋'), tr('Accept uncertainty and unblock', '接受未知状态并解除阻挡', '接受未知狀態並解除阻擋') },
                tr('Check the processes, logs and checkpoint first. This does not prove the run stopped.',
                  '请先检查进程、日志和检查点；此操作不能证明运行已停止。', '請先檢查程序、日誌和檢查點；此操作不能證明執行已停止。'), function(_, choice)
                  if choice ~= 2 or not current() or state.busy or state.last ~= listed then return end
                  local args = { 'runs', 'acknowledge-unknown', selected.id, '--if-revision', revision, '--acknowledge' }
                  if unverified_scope then args[#args + 1] = '--accept-unverified-host' end
                  if different_scope then args[#args + 1] = '--accept-different-scope' end
                  run(state, tr('Acknowledge unknown run', '确认未知运行', '確認未知執行'), args, nil,
                    tr('Records acceptance of uncertainty and allows new runs. It does not stop processes or remove logs or checkpoints.',
                      '记录对未知状态的接受并允许启动新任务；不会停止进程或删除日志与检查点。',
                      '記錄對未知狀態的接受並允許啟動新任務；不會停止程序或刪除日誌與檢查點。')
                    .. (unverified_scope and tr('\nThe original host and PID namespace were not recorded; confirm you have checked the original environment.',
                      '\n原运行主机和 PID 命名空间未记录；请确认已在原环境核查。', '\n原執行主機和 PID 命名空間未記錄；請確認已在原環境核查。') or '')
                    .. (different_scope and tr('\nThe original process environment differs. Its processes cannot be checked here; confirm you have checked the original environment.',
                      '\n原进程环境与当前不同，无法在此检查原环境进程；请确认已核查原环境。', '\n原程序環境與目前不同，無法在此檢查原環境程序；請確認已核查原環境。') or ''), true)
                end)
            end)
          elseif action == 1 then
            query({ 'runs', 'show', selected.id }, 'runs_show', function() show_report(state) end)
          elseif action == 2 then
            query({ 'runs', 'attach', selected.id, '--follow=false' }, 'runs_attach', function() show_report(state) end)
          elseif action == 3 then
            local others, other_labels = {}, {}
            for index, row in ipairs(rows) do
              if row.id ~= selected.id then
                others[#others + 1], other_labels[#other_labels + 1] = row, choices[index]
              end
            end
            if #others == 0 then
              notify(tr('No other run is available to compare.', '没有其他运行记录可供比较。', '沒有其他執行紀錄可供比較。'), vim.log.levels.INFO)
              return
            end
            vim.ui.select(other_labels, { prompt = tr('Compare against', '选择比较对象', '選擇比較對象') }, function(_, other)
              if other and others[other] and current() then
                query({ 'runs', 'compare', selected.id, others[other].id }, 'runs_compare', function() show_report(state) end)
              end
            end)
          elseif action == 4 then
            vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Request stop', '请求停止', '要求停止') }, {
              prompt = tr('Request a cooperative stop for run ', '请求协作停止运行 ', '要求協作停止執行 ') .. selected.id
                .. tr('? It may finish its current step and write a checkpoint.', '？它可能完成当前步骤并写入检查点。', '？它可能完成目前步驟並寫入檢查點。'),
            }, function(_, confirm)
              if confirm ~= 2 or not current() or state.busy then return end
              query({ 'runs', 'stop', selected.id }, 'runs_stop', function()
                notify(tr('Stop requested; refresh the run to confirm its final state.', '已请求停止；请刷新运行记录确认最终状态。', '已要求停止；請重新整理執行紀錄確認最終狀態。'), vim.log.levels.INFO)
                show_report(state)
              end)
            end)
          elseif action == 5 then
            resume_run(state, selected.id)
          elseif action == 6 then
            if generic then notify(tr('Framework-neutral loops manage their own evaluation. The PyTorch checkpoint evaluator cannot read their state.', '无框架循环自行管理评估；PyTorch 检查点评估器无法读取其状态。', '無框架迴圈自行管理評估；PyTorch 檢查點評估器無法讀取其狀態。'), vim.log.levels.INFO); return end
            evaluate_run(state, selected.id)
          elseif action == 7 then
            if generic then notify(tr('This loop manages its own export. Its JSON state is not a PyTorch weights export.', '该循环自行管理导出；其 JSON 状态不是 PyTorch 权重导出。', '該迴圈自行管理匯出；其 JSON 狀態不是 PyTorch 權重匯出。'), vim.log.levels.INFO); return end
            export_run(state, selected.id)
          elseif action == 8 then
            follow_run(state, selected.id)
          elseif action == 9 then
            query({ 'runs', 'show', selected.id }, 'runs_show', function(data)
              local inputs = type(data) == 'table' and data.inputs
              local runtime = type(inputs) == 'table' and inputs.runtime
              if type(runtime) ~= 'table' or type(runtime.python_executable) ~= 'string'
                  or runtime.python_executable == '' or runtime.working_directory == nil or runtime.project_import_roots == nil then
                notify(tr('The recorded runtime is incomplete; inspect the report and choose it manually.',
                  '运行记录中的环境信息不完整，请查看报告并手动选择。', '執行紀錄中的環境資訊不完整，請查看報告並手動選擇。'), vim.log.levels.WARN)
                show_report(state); return
              end
              local cwd = runtime.working_directory
              if cwd == vim.NIL then cwd = state.opts.project end
              local roots = runtime.project_import_roots
              if roots == vim.NIL then roots = {} end
              if type(cwd) ~= 'string' or #cwd > 4096 or #runtime.python_executable > 4096
                  or type(roots) ~= 'table' or not is_list(roots) or #roots > 32
                  or cwd:find('[\r\n%z\1-\31\127]') or runtime.python_executable:find('[\r\n%z\1-\31\127]') then
                notify(tr('The recorded runtime cannot be safely selected.', '无法选择该运行记录中的环境。', '無法選擇該執行紀錄中的環境。'), vim.log.levels.WARN); return
              end
              for _, root in ipairs(roots) do
                if type(root) ~= 'string' or #root > 1024 or root:find('[\r\n%z\1-\31\127]') then
                  notify(tr('The recorded import roots are invalid.', '记录的模块目录无效。', '記錄的模組目錄無效。'), vim.log.levels.WARN); return
                end
              end
              local project, epoch, listed = state.opts.project, state.change_epoch or 0, state.last
              local prompt = tr('Use recorded paths and Python? They have not been revalidated.\nPython: ',
                '使用记录的路径和 Python？它们尚未重新验证。\nPython：',
                '使用記錄的路徑和 Python？它們尚未重新驗證。\nPython：')
                .. runtime.python_executable .. '\n' .. tr('Working directory: ', '运行目录：', '執行目錄：') .. cwd
                .. '\n' .. tr('Project import roots: ', '项目模块目录：', '專案模組目錄：') .. table.concat(roots, ', ')
              vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Use for this session', '本次会话使用', '本工作階段使用') }, { prompt = prompt }, function(_, choice)
                if choice ~= 2 or state.closed or state.busy or state.opts.project ~= project
                    or (state.change_epoch or 0) ~= epoch or state.last ~= listed then return end
                local actual = vim.uv.fs_realpath(cwd)
                local stat = actual and vim.uv.fs_stat(actual)
                if not stat or stat.type ~= 'directory' or vim.fs.normalize(actual) ~= vim.fs.normalize(cwd) then
                  notify(tr('The recorded working directory is unavailable or changed.', '记录的运行目录不可用或已变化。', '記錄的執行目錄無法使用或已變更。'), vim.log.levels.WARN); return
                end
                for _, root in ipairs(roots) do
                  if type(root) ~= 'string' or root == '' or root:sub(1, 1) == '/' or root:find('\\', 1, true)
                      or root:match('^%a:') or root:find('//', 1, true) or root:sub(-1) == '/'
                      or root == '.' or root == '..' or root:match('^%.%./') or root:match('/%.%./') or root:match('/%.%.$')
                      or root:match('^%./') or root:match('/%./') or root:match('/%.$') then
                    notify(tr('The recorded import roots are invalid.', '记录的模块目录无效。', '記錄的模組目錄無效。'), vim.log.levels.WARN); return
                  end
                  local full = vim.fs.normalize(project .. '/' .. root)
                  local resolved = vim.uv.fs_realpath(full)
                  local info = resolved and vim.uv.fs_stat(resolved)
                  if not info or info.type ~= 'directory' or vim.fs.normalize(resolved) ~= full then
                    notify(tr('A recorded import directory is unavailable or changed.', '记录的模块目录不可用或已变化。', '記錄的模組目錄無法使用或已變更。'), vim.log.levels.WARN); return
                  end
                end
                state.opts.python, state.opts.working_directory = runtime.python_executable, actual
                state.opts.project_import_roots = #roots > 0 and vim.deepcopy(roots) or nil
                state.opts.runtime_paths_override = true
                state.change_epoch = epoch + 1
                if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
                state.journey = nil
                state.result_label = tr('recorded runtime selected; verify before running', '已选择记录的环境；运行前请检查', '已選擇記錄的環境；執行前請檢查')
                render(state)
              end)
            end)
          elseif action == 10 then
            if generic then notify(tr('Use y to prepare a new framework-neutral trial; its previous inputs are available in run details.', '按 y 重新准备无框架试跑；先前输入可在运行详情中查看。', '按 y 重新準備無框架試跑；先前輸入可在執行詳情中查看。'), vim.log.levels.INFO); return end
            state.busy = tr('Checking repeat support', '检查重复试跑能力', '檢查重複試跑能力')
            render(state)
            request(state, { '--describe-interface' }, function(interface, failure)
              state.busy = nil
              render(state)
              local caps = interface and interface.data and interface.data.capabilities
              if not current() then return end
              if failure or not interface or interface.status ~= 'success' or interface.operation ~= 'interface'
                  or type(caps) ~= 'table' or caps['training.repeat_input_guard_v1'] ~= true
                  or caps['runtime.historical_python_v1'] ~= true then
                notify(tr('This CLI cannot safely repeat a reviewed trial.', '此 CLI 无法安全重复已审核的试跑。', '此 CLI 無法安全重複已檢視的試跑。'), vim.log.levels.WARN)
                return
              end
              query({ 'runs', 'show', selected.id }, 'runs_show', function(data)
                local digest = type(data) == 'table' and data.repeat_inputs_sha256 or nil
                local inputs = type(data) == 'table' and data.inputs or nil
                if type(digest) ~= 'string' or #digest ~= 64 or digest:find('[^0-9a-f]')
                    or type(inputs) ~= 'table' or inputs.operation ~= 'training_probe' then
                  notify(tr('This is not a repeatable trial with verifiable inputs.', '此记录不是输入可核对的试跑。', '此紀錄不是輸入可核對的試跑。'), vim.log.levels.WARN)
                  show_report(state); return
                end
                local policy = inputs.batch_device_policy
                if policy ~= nil and policy ~= vim.NIL then
                  if (policy ~= 'preserve' and policy ~= 'recursive-strict')
                      or caps['training.batch_device_policy_v1'] ~= true then
                    notify(tr('This CLI cannot preserve the recorded batch device policy.',
                      '当前 CLI 无法保留记录的批次设备策略。', '目前 CLI 無法保留記錄的批次裝置策略。'), vim.log.levels.WARN)
                    return
                  end
                end
                local listed = state.last
                local review = show_report(state)
                review_gate(review, { tr('Cancel', '取消', '取消'), tr('Continue', '继续', '繼續') },
                  tr('Review the recorded trial; [J] shows all fields. Source, data and environment can have changed. Continue?',
                    '请审核历史试跑；[J] 显示完整字段。源码、数据和环境可能已变化。继续？',
                    '請檢視歷史試跑；[J] 顯示完整欄位。原始碼、資料和環境可能已變更。繼續？'), function(_, accepted)
                  if accepted ~= 2 or not current() or state.last ~= listed or listed.context_changed then return end
                  vim.ui.select({ tr('Repeat without supervision', '不启用监督重复试跑', '不啟用監督重複試跑'),
                    tr('Review and enable current supervision', '审核并启用当前监督', '檢視並啟用目前監督') }, {
                    prompt = tr('Choose supervision for this trial', '选择本次试跑的监督', '選擇本次試跑的監督'),
                  }, function(_, choice)
                    if not choice or not current() or state.last ~= listed then return end
                    local function start(revision)
                      local args = { 'try', '--repeat', selected.id, '--if-repeat-inputs-sha256', digest }
                      if revision then vim.list_extend(args, { '--apply-supervision', '--if-supervision-revision', revision })
                      else args[#args + 1] = '--no-supervision' end
                      local function display(value)
                        if type(value) ~= 'string' or value == '' then return '?' end
                        return vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, 512)
                      end
                      local runtime = type(inputs.runtime) == 'table' and inputs.runtime or {}
                      local details = '\n' .. tr('Recorded model: ', '历史模型：', '歷史模型：') .. display(inputs.model)
                        .. '\n' .. tr('Recorded input: ', '历史输入：', '歷史輸入：') .. display(inputs.batch)
                        .. '\n' .. tr('Recorded input binding: ', '历史输入绑定：', '歷史輸入繫結：')
                        .. (type(inputs.batch_binding) == 'string' and display(inputs.batch_binding)
                          or tr('automatic / not recorded', '自动 / 未记录', '自動 / 未記錄'))
                        .. '\n' .. tr('Recorded batch device policy: ', '历史批次设备策略：', '歷史批次裝置策略：')
                        .. (type(inputs.batch_device_policy) == 'string' and display(inputs.batch_device_policy)
                          or (inputs.training_mode == 'external-loop' and tr('user loop manages data', '由用户循环管理', '由使用者迴圈管理')
                            or tr('legacy recursive behavior (not recorded)', '历史递归行为（未记录）', '歷史遞迴行為（未記錄）')))
                        .. '\n' .. tr('Recorded training mode: ', '历史训练模式：', '歷史訓練模式：') .. display(inputs.training_mode)
                        .. '\n' .. tr('Recorded training entry: ', '历史训练入口：', '歷史訓練入口：')
                        .. display(inputs.training_mode == 'external-loop' and inputs.training_loop or inputs.training_step)
                        .. '\n' .. tr('Recorded Python: ', '历史 Python：', '歷史 Python：') .. display(runtime.python_executable)
                        .. '\n' .. tr('Recorded device request: ', '历史设备请求：', '歷史裝置要求：') .. display(runtime.device)
                        .. '\n' .. tr('Recorded execution seed: ', '记录的执行种子：', '記錄的執行種子：')
                        .. (type(data.seed_decimal) == 'string' and data.seed_decimal:match('^%d+$') and #data.seed_decimal <= 20
                          and data.seed_decimal or tr('not recorded or unavailable', '未记录或不可用', '未記錄或無法取得'))
                        .. '\n' .. tr('Supervision for this trial: ', '本次试跑监督：', '本次試跑監督：')
                        .. (revision and tr('reviewed current rules', '已审核的当前规则', '已檢視的目前規則')
                          or tr('off', '关闭', '關閉'))
                      run(state, tr('Repeat training trial', '重复训练试跑', '重複訓練試跑'), args, nil,
                        tr('Uses the reviewed historical inputs. External data, code and dependencies can differ; user code may write files.',
                          '使用已审核的历史输入；外部数据、代码与依赖可能不同，用户代码可能写入文件。',
                          '使用已檢視的歷史輸入；外部資料、程式碼與依賴可能不同，使用者程式碼可能寫入檔案。') .. details, true)
                    end
                    if choice == 1 then start(nil); return end
                    if caps['training.conditional_supervision'] ~= true then
                      notify(tr('This CLI cannot pin supervision rules.', '此 CLI 无法固定监督规则。', '此 CLI 無法固定監督規則。'), vim.log.levels.WARN); return
                    end
                    query({ 'model', 'supervise', 'rule', 'list' }, 'semantic_supervise', function(rules)
                      local revision = type(rules) == 'table' and rules.state_revision or nil
                      if type(revision) ~= 'string' or #revision ~= 64 or revision:find('[^0-9a-f]')
                          or type(rules.rules) ~= 'table' or not is_list(rules.rules) then
                        notify(tr('Cannot verify supervision rules.', '无法核对监督规则。', '無法核對監督規則。'), vim.log.levels.WARN); return
                      end
                      local rule_report = state.last
                      local rule_view = show_report(state)
                      review_gate(rule_view, { tr('Cancel', '取消', '取消'), tr('Continue with these rules', '使用这些规则继续', '使用這些規則繼續') },
                        tr('Review current rules before continuing.', '继续前请审核当前规则。', '繼續前請檢視目前規則。'), function(_, confirmed)
                        if confirmed == 2 and current() and state.last == rule_report and not rule_report.context_changed then start(revision) end
                      end)
                    end)
                  end)
                end)
              end)
            end)
          end
        end)
    end)
    end
    choose_run()
  end)
end

local function sha256(value)
  return type(value) == 'string' and #value == 64 and value:match('^[0-9a-f]+$') ~= nil
end

local function historical_python_description(state, data, required)
  local inputs = type(data) == 'table' and data.inputs or nil
  local runtime = type(inputs) == 'table' and inputs.runtime or nil
  local recorded = type(runtime) == 'table' and runtime.python_executable or nil
  local function safe(value)
    return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
  end
  if required and (type(recorded) ~= 'string' or recorded == '') then
    return tr('Recorded Python is missing; this loop cannot be resumed from this record.',
      '缺少记录的 Python，无法从此记录恢复循环。', '缺少記錄的 Python，無法從此紀錄恢復迴圈。')
  end
  if state.opts.python then
    return tr('Explicit session Python: ', '会话明确选择的 Python：', '工作階段明確選擇的 Python：') .. safe(state.opts.python)
      .. (type(recorded) == 'string' and ('\n' .. tr('Recorded Python: ', '记录的 Python：', '記錄的 Python：') .. safe(recorded)) or '')
      .. (required and state.opts.python ~= recorded and tr('\nThe two paths differ; this loop cannot resume until the selection matches.',
        '\n两者不同；需要切换到记录的解释器才能恢复此循环。', '\n兩者不同；需要切換到記錄的直譯器才能恢復此迴圈。') or '')
  end
  if type(recorded) == 'string' and recorded ~= '' then
    return tr('Recorded Python will be used: ', '将使用记录的 Python：', '將使用記錄的 Python：') .. safe(recorded)
  end
  return tr('No recorded Python; the current project/default selection will be used.',
    '未记录 Python；将使用当前项目或默认选择。', '未記錄 Python；將使用目前專案或預設選擇。')
end

local function historical_runtime_paths_description(data)
  local inputs = type(data) == 'table' and data.inputs or nil
  local runtime = type(inputs) == 'table' and inputs.runtime or nil
  local function safe(value)
    return vim.fn.strcharpart(tostring(value):gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
  end
  if type(runtime) ~= 'table' then
    return tr('Recorded working directory and import roots are unknown.',
      '记录的运行目录和模块搜索目录未知。', '記錄的執行目錄和模組搜尋目錄未知。')
  end
  local directory = runtime.working_directory
  local roots = runtime.project_import_roots
  local directory_text = type(directory) == 'string' and directory ~= '' and safe(directory)
    or ((directory == nil or directory == vim.NIL) and tr('project default', '项目默认', '專案預設') or tr('unknown', '未知', '未知'))
  local roots_text = tr('unknown', '未知', '未知')
  if roots == nil or roots == vim.NIL then roots_text = tr('project default', '项目默认', '專案預設')
  elseif type(roots) == 'table' and is_list(roots) then
    local items = {}
    for index, root in ipairs(roots) do
      if index > 32 or type(root) ~= 'string' then items = nil; break end
      items[#items + 1] = safe(root)
    end
    if items then roots_text = #items > 0 and table.concat(items, ', ') or tr('project default', '项目默认', '專案預設') end
  end
  return tr('Recorded working directory: ', '记录的运行目录：', '記錄的執行目錄：') .. directory_text
    .. tr('\nRecorded project import roots: ', '\n记录的项目模块目录：', '\n記錄的專案模組目錄：') .. roots_text
end

resume_run = function(state, id)
  if state.busy or state.closed then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  state.busy = tr('Checking resume support', '检查续训能力', '檢查續訓能力')
  render(state)
  request(state, { '--describe-interface' }, function(interface, err, stderr)
    state.busy = nil
    if not current() then
      render(state)
      notify(tr('Context changed; prepare resume again.', '上下文已变化，请重新准备续训。', '上下文已變更，請重新準備續訓。'), vim.log.levels.WARN)
      return
    end
    local caps = interface and interface.data and interface.data.capabilities
    if err or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['training.conditional_resume_checkpoint'] ~= true
        or caps['training.request_identity'] ~= true or caps['training.atomic_run_admission'] ~= true
        or caps['runtime.historical_python_v1'] ~= true then
      state.last = { report = interface, transport_error = err, stderr = stderr }
      render(state)
      notify(tr('This CLI cannot safely pin and track a resume request.', '此 CLI 无法安全固定并追踪续训请求。', '此 CLI 無法安全固定並追蹤續訓要求。'), vim.log.levels.WARN)
      return
    end
    state.busy = tr('Reading checkpoint', '读取检查点', '讀取檢查點')
    render(state)
    request(state, { 'runs', 'show', id }, function(report, failure, output)
      state.busy = nil
      if not current() then
        render(state)
        notify(tr('Context changed while reading the checkpoint; prepare resume again.',
          '读取检查点时上下文已变化，请重新准备续训。', '讀取檢查點時上下文已變更，請重新準備續訓。'), vim.log.levels.WARN)
        return
      end
      state.last = { report = report, transport_error = failure, stderr = output,
        scope = tr('Recorded source and environment are not current comparisons; data content can differ.',
          '记录的源码和环境尚未与当前状态比较；数据内容可能不同。', '記錄的原始碼和環境尚未與目前狀態比較；資料內容可能不同。') }
      render(state)
      local data = report and report.data
      local record = type(data) == 'table' and data.record
      local checkpoint = type(data) == 'table' and data.checkpoint
      if failure or not report or report.operation ~= 'runs_show' or report.status ~= 'success'
          or type(record) ~= 'table' or record.id ~= id then
        notify(tr('Could not read the selected run; inspect the report before retrying.', '无法读取所选运行；请先查看报告。', '無法讀取所選執行；請先查看報告。'), vim.log.levels.WARN)
        show_report(state); return
      end
      if type(checkpoint) ~= 'table' or not sha256(checkpoint.sha256) then
        local message = record.operation == 'generic_loop_trial'
          and tr('User-loop trials do not save state. Start a formal loop and report JSON state to enable tool-managed recovery.',
            '用户循环试跑不保存状态。需要工具恢复时，请启动正式循环并报告 JSON 状态。',
            '使用者迴圈試跑不儲存狀態。需要工具恢復時，請啟動正式迴圈並回報 JSON 狀態。')
          or tr('No recorded checkpoint digest is available. A loop may manage its state outside the tool.',
            '没有可用的已记录检查点摘要；循环也可能自行管理状态。', '沒有可用的已記錄檢查點摘要；迴圈也可能自行管理狀態。')
        notify(message, vim.log.levels.WARN)
        show_report(state); return
      end
      local recorded_inputs = type(data.inputs) == 'table' and data.inputs or {}
      if record.operation == 'generic_loop_train' then
        if caps['training.generic_loop_train_cli_v1'] ~= true then
          notify(tr('The selected CLI cannot resume a framework-neutral loop.', '所选 CLI 无法恢复无框架循环。', '所選 CLI 無法恢復無框架迴圈。'), vim.log.levels.WARN); return
        end
        if recorded_inputs.loop_interface == 'context' and caps['training.generic_loop_interface_v1'] ~= true then
          notify(tr('The selected CLI cannot restore this loop signature.', '所选 CLI 无法恢复此循环签名。', '所選 CLI 無法恢復此迴圈簽名。'), vim.log.levels.WARN); return
        end
        local runtime = type(recorded_inputs.runtime) == 'table' and recorded_inputs.runtime or nil
        local recorded_python = runtime and runtime.python_executable
        if type(recorded_python) ~= 'string' or recorded_python == '' then
          notify(tr('The recorded Python is missing. This loop cannot be resumed from this record.',
            '缺少记录的 Python，无法从此记录恢复循环。', '缺少記錄的 Python，無法從此紀錄恢復迴圈。'), vim.log.levels.WARN); return
        end
        if state.opts.python and state.opts.python ~= recorded_python then
          notify(tr('The session Python differs from this run. Select the recorded runtime in run history before resuming.',
            '会话 Python 与历史运行不同，请先在运行记录中选择记录的运行环境。',
            '工作階段 Python 與歷史執行不同，請先在執行紀錄中選擇記錄的執行環境。'), vim.log.levels.WARN); return
        end
        local completed = tonumber(checkpoint.completed_steps)
        if not completed or completed < 1 or completed >= 1000000 then
          notify(tr('The checkpoint has no valid resumable step.', '检查点没有有效的可恢复步数。', '檢查點沒有有效的可恢復步數。'), vim.log.levels.WARN); return
        end
        vim.ui.input({ prompt = tr('Total step target (includes saved steps): ', '总步数目标（包含已保存的步数）：', '總步數目標（包含已儲存的步數）：'), default = tostring(completed + 1) }, function(raw)
          if not raw or not current() then return end
          local steps = raw:match('^%d+$') and tonumber(raw) or nil
          if not steps or steps <= completed or steps > 1000000 then
            notify(tr('Enter a target greater than the saved step, up to 1000000.', '请输入大于已保存步数且不超过 1000000 的目标。', '請輸入大於已儲存步數且不超過 1000000 的目標。'), vim.log.levels.WARN); return
          end
          local args = { 'loop-run', '--resume', id, '--if-checkpoint-sha256', checkpoint.sha256, '--steps', tostring(steps) }
          local detached = caps['training.generic_loop_detached_cli_v1'] == true
          local effects = (detached and tr('Starts the recorded user loop in the background.', '在后台启动记录的用户循环。', '在背景啟動記錄的使用者迴圈。')
              or tr('Runs the recorded user loop in the foreground.', '以前台方式运行记录的用户循环。', '以前景方式執行記錄的使用者迴圈。'))
            .. tr(' The worker verifies the selected checkpoint, source and environment metadata. Only user-reported JSON state is restored; external files and random state are not captured.',
            ' worker 会校验所选恢复点、源码和环境元数据。只恢复用户报告的 JSON 状态；外部文件和随机状态不包含在内。',
            ' worker 會驗證所選恢復點、原始碼和環境中繼資料。只恢復使用者回報的 JSON 狀態；外部檔案和隨機狀態不包含在內。')
            .. '\nRun: ' .. id .. '\nSHA-256: ' .. checkpoint.sha256 .. '\nTarget: ' .. tostring(steps)
            .. '\n' .. historical_python_description(state, data, true)
            .. '\n' .. historical_runtime_paths_description(data)
            .. '\n' .. tr('Recorded signature: ', '记录的循环签名：', '記錄的迴圈簽名：') .. (recorded_inputs.loop_interface == 'context' and 'loop(context, **params)' or 'loop(None, context, **params)')
          start_generic_run(state, tr('Resume user loop', '恢复用户循环', '恢復使用者迴圈'), args, effects, detached)
        end)
        return
      end
      if type(recorded_inputs.batch_binding) == 'string' and caps['training.batch_binding_v1'] ~= true then
        notify(tr('This CLI cannot preserve the recorded input binding during resume.',
          '当前 CLI 无法在续训时保留记录的输入绑定。', '目前 CLI 無法在續訓時保留記錄的輸入繫結。'), vim.log.levels.WARN)
        show_report(state); return
      end
      local recorded_policy = recorded_inputs.batch_device_policy
      if recorded_policy ~= nil and recorded_policy ~= vim.NIL
          and ((recorded_policy ~= 'preserve' and recorded_policy ~= 'recursive-strict')
            or caps['training.batch_device_policy_v1'] ~= true) then
        notify(tr('This CLI cannot preserve the recorded batch device policy during resume.',
          '当前 CLI 无法在续训时保留记录的批次设备策略。', '目前 CLI 無法在續訓時保留記錄的批次裝置策略。'), vim.log.levels.WARN)
        show_report(state); return
      end
      local recorded_runtime = type(recorded_inputs.runtime) == 'table' and recorded_inputs.runtime or {}
      local recorded_device = recorded_runtime.device
      if type(recorded_device) == 'string' and recorded_device ~= '' and needs_generic_device(recorded_device)
          and caps['training.generic_device_v1'] ~= true then
        notify(tr('This CLI cannot safely resume the recorded PyTorch device. Select a compatible CLI.',
          '当前 CLI 无法安全恢复记录的 PyTorch 设备，请选择兼容版本。',
          '目前 CLI 無法安全恢復記錄的 PyTorch 裝置，請選擇相容版本。'), vim.log.levels.WARN)
        show_report(state); return
      end
      if type(recorded_inputs.optimizer_factory) == 'string' and recorded_inputs.optimizer_factory ~= ''
          and caps['training.custom_optimizer_factory_v1'] ~= true then
        notify(tr('This CLI cannot safely resume the recorded custom optimizer. Select a compatible CLI.',
          '当前 CLI 无法安全恢复记录的自定义优化器，请选择兼容的 CLI。',
          '目前 CLI 無法安全恢復記錄的自訂最佳化器，請選擇相容的 CLI。'), vim.log.levels.WARN)
        show_report(state); return
      end
      local listed = state.last
      show_report(state)
      vim.ui.input({ prompt = tr('Additional steps: ', '额外训练步数：', '額外訓練步數：'), default = '1' }, function(steps)
        if not steps or not steps:match('^%d+$') or tonumber(steps) < 1 or tonumber(steps) > 1000000 then return end
        if not current() or state.last ~= listed or listed.context_changed then
          notify(tr('Context changed; prepare resume again.', '上下文已变化，请重新准备续训。', '上下文已變更，請重新準備續訓。'), vim.log.levels.WARN); return
        end
        local function start_resume(allow_reset)
        if not current() or state.last ~= listed or listed.context_changed then
          notify(tr('Context changed; prepare resume again.', '上下文已变化，请重新准备续训。', '上下文已變更，請重新準備續訓。'), vim.log.levels.WARN); return
        end
        local detached = caps['training.detached_cli_v1'] == true
        local args = { 'train', '--resume', id, '--additional-steps', steps,
          '--if-checkpoint-sha256', checkpoint.sha256 }
        if detached then args[#args + 1] = '--detach' end
        if allow_reset then args[#args + 1] = '--allow-state-reset' end
        local request_id
        local function before_start(operation_args)
          local items, list_err = pending.list(project)
          if not items or #items > 0 then
            notify(tr('Resolve pending training requests before resuming: ', '续训前请核查待确认的训练请求：', '續訓前請核查待確認的訓練要求：') .. tostring(list_err or table.concat(items, ', ')), vim.log.levels.WARN)
            return false
          end
          request_id, list_err = pending.create(project)
          if not request_id then notify(tr('Could not record resume request: ', '无法记录续训请求：', '無法記錄續訓要求：') .. tostring(list_err), vim.log.levels.ERROR); return false end
          vim.list_extend(operation_args, { '--request-id', request_id })
          return true
        end
        local function finished(receipt, result_err)
          if not request_id then return end
          if result_err and result_err.operation_started == false then
            local ok, clear_err = pending.clear(project, request_id)
            if not ok then notify(tr('No resume was started, but its pending marker needs inspection: ', '续训未启动，但待确认标记需要检查：', '續訓未啟動，但待確認標記需要檢查：') .. tostring(clear_err), vim.log.levels.WARN) end
          elseif not result_err and receipt and receipt.operation == 'train' and receipt.status == 'success'
              and type(receipt.data) == 'table' and receipt.data.detached == true
              and receipt.data.request_id == request_id and type(receipt.data.run_id) == 'string'
              and receipt.data.run_id ~= '' then
            local ok, clear_err = pending.clear(project, request_id)
            if not ok then notify(tr('Resume started, but its pending marker remains: ', '续训已启动，但待确认标记仍存在：', '續訓已啟動，但待確認標記仍存在：') .. tostring(clear_err), vim.log.levels.WARN) end
          else
            notify(tr('Resume outcome is not acknowledged. Use H to inspect request ', '续训结果尚未确认，请按 H 核查请求 ', '續訓結果尚未確認，請按 H 核查要求 ') .. request_id
              .. tr(' before another start.', '，然后再启动。', '，然後再啟動。'), vim.log.levels.WARN)
          end
        end
        local effects = (detached and tr('Loads the selected checkpoint and resumes in the background.',
          '将载入选定检查点并在后台续训。', '將載入選定檢查點並在背景續訓。')
          or tr('Loads the selected checkpoint and resumes in the foreground; keep this session open.',
            '将载入选定检查点并在前台续训，请保持会话打开。', '將載入選定檢查點並在前景續訓，請保持工作階段開啟。'))
          .. tr(' Source, environment and data may have changed; temporary space is required.',
            ' 源码、环境和数据可能已变化；需要临时磁盘空间。', ' 原始碼、環境和資料可能已變更；需要暫存磁碟空間。')
          .. '\nRun: ' .. id .. '\nCheckpoint SHA-256: ' .. checkpoint.sha256 .. '\nAdditional steps: ' .. steps
          .. '\n' .. historical_python_description(state, data)
          .. '\n' .. historical_runtime_paths_description(data)
          .. '\n' .. tr('Recorded batch device policy: ', '记录的批次设备策略：', '記錄的批次裝置策略：')
          .. (type(recorded_policy) == 'string' and recorded_policy
            or (recorded_inputs.training_mode == 'external-loop' and tr('user loop manages data', '由用户循环管理', '由使用者迴圈管理')
              or tr('legacy recursive behavior (not recorded)', '历史递归行为（未记录）', '歷史遞迴行為（未記錄）')))
        if allow_reset then
          effects = effects .. tr('\nYou chose to reset unavailable batch, step or loop custom state. Model and optimizer still use the checkpoint; data position or user state may restart.',
            '\n已选择重置无法恢复的批次、训练步骤或循环自定义状态。模型和优化器仍使用检查点；数据位置或用户状态可能重新开始。',
            '\n已選擇重設無法恢復的批次、訓練步驟或迴圈自訂狀態。模型和最佳化器仍使用檢查點；資料位置或使用者狀態可能重新開始。')
        end
        if type(recorded_inputs.optimizer_factory) == 'string' and recorded_inputs.optimizer_factory ~= '' then
          local factory = vim.fn.strcharpart(recorded_inputs.optimizer_factory:gsub('[\r\n%z\1-\31\127]', ' '), 0, 512)
          effects = effects .. tr('\nRecorded optimizer factory (parameters inherited): ', '\n记录的优化器工厂（继承参数）：', '\n記錄的最佳化器工廠（繼承參數）：') .. factory
        end
        local recorded_report = type(data.report) == 'table' and data.report.data or nil
        local recorded_runtime = type(recorded_report) == 'table' and recorded_report.runtime or nil
        local requested_runtime = type(data.inputs) == 'table' and data.inputs.runtime or nil
        effects = effects .. tr('\nRecorded requested device: ', '\n记录的设备选择：', '\n記錄的裝置選擇：')
          .. tostring(type(requested_runtime) == 'table' and requested_runtime.device or '?')
          .. tr('\nLast observed device / backend / name: ', '\n最近观察的设备 / 后端 / 名称：', '\n最近觀察的裝置 / 後端 / 名稱：')
          .. tostring(type(recorded_runtime) == 'table' and recorded_runtime.device or '?') .. ' / '
          .. tostring(type(recorded_runtime) == 'table' and recorded_runtime.device_backend or '?') .. ' / '
          .. tostring(type(recorded_runtime) == 'table' and recorded_runtime.device_name or '?')
          .. tr('\nThe checkpoint is checked when loaded; equal labels do not prove physical identity.',
            '\n载入时会检查检查点中的记录；名称相同不证明是同一物理设备。',
            '\n載入時會檢查檢查點中的記錄；名稱相同不證明是同一實體裝置。')
        run(state, tr('Resume training', '恢复训练', '恢復訓練'), args,
          detached and finished or nil, effects, true, detached and before_start or nil)
        end
        local recorded = type(data.report) == 'table' and type(data.report.data) == 'table'
          and data.report.data.checkpoint_state or nil
        local reset_needed = type(recorded) == 'table' and (recorded.batch == 'reset-on-resume'
          or recorded.training_step == 'reset-on-resume' or recorded.training_loop == 'reset-on-resume')
        if reset_needed and caps['training.resume_allow_state_reset_v1'] == true then
          vim.ui.select({tr('Cancel', '取消', '取消'),
            tr('Resume with unavailable custom state reset', '重置不可恢复的自定义状态后续训', '重設無法恢復的自訂狀態後續訓'),
            tr('Try strict resume without reset', '严格续训（不重置）', '嚴格續訓（不重設）')}, {
            prompt = tr('This checkpoint did not save all custom state; resetting can restart data position or step state.',
              '检查点未保存全部自定义状态；重置可能使数据位置或步骤状态重新开始。',
              '檢查點未儲存全部自訂狀態；重設可能使資料位置或步驟狀態重新開始。'),
          }, function(_, choice) if choice == 2 then start_resume(true) elseif choice == 3 then start_resume(false) end end)
        else
          start_resume(false)
        end
      end)
    end)
  end)
end

evaluate_run = function(state, id)
  if state.busy or state.closed then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  state.busy = tr('Checking evaluation support', '检查评估能力', '檢查評估能力')
  render(state)
  request(state, { '--describe-interface' }, function(interface, err)
    state.busy = nil
    local caps = interface and interface.data and interface.data.capabilities
    if err or not current() or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['evaluation.conditional_checkpoint'] ~= true
        or caps['runtime.historical_python_v1'] ~= true then
      render(state)
      notify(tr('This CLI cannot pin an evaluation checkpoint.', '此 CLI 无法固定评估检查点。', '此 CLI 無法固定評估檢查點。'), vim.log.levels.WARN); return
    end
    state.busy = tr('Reading checkpoint', '读取检查点', '讀取檢查點')
    render(state)
    request(state, { 'runs', 'show', id }, function(report, failure, stderr)
      state.busy = nil
      if not current() then
        render(state)
        notify(tr('Context changed while reading the checkpoint; prepare evaluation again.',
          '读取检查点时上下文已变化，请重新准备评估。', '讀取檢查點時上下文已變更，請重新準備評估。'), vim.log.levels.WARN)
        return
      end
      state.last = { report = report, transport_error = failure, stderr = stderr }
      render(state)
      local data = report and report.data
      local record = type(data) == 'table' and data.record
      local checkpoint = type(data) == 'table' and data.checkpoint
      if failure or not report or report.operation ~= 'runs_show' or report.status ~= 'success'
          or type(record) ~= 'table' or record.id ~= id or type(checkpoint) ~= 'table'
          or not sha256(checkpoint.sha256) then
        notify(tr('A verified checkpoint identity is required for evaluation.', '评估需要已核对的检查点身份。', '評估需要已核對的檢查點身分。'), vim.log.levels.WARN)
        show_report(state); return
      end
      show_report(state)
      local recorded_inputs = type(data.inputs) == 'table' and data.inputs or nil
      local recorded_model = recorded_inputs and recorded_inputs.model
      local module = type(recorded_model) == 'string' and recorded_model:match('^([%w_]+):model$') or nil
      local proposed_evaluator
      if module and (module == 'model_starter' or module:match('^model_maven_build_[a-f0-9]+$')) then
        local path = project .. '/' .. module .. '.py'
        local stat = vim.uv.fs_lstat(path)
        if stat and stat.type == 'file' and stat.size <= 4 * 1024 * 1024 then
          local file = io.open(path, 'rb')
          local source = file and file:read(4 * 1024 * 1024 + 1) or nil
          if file then file:close() end
          if source and #source <= 4 * 1024 * 1024 and source:find('# Model-Maven one-batch evaluator v1', 1, true) then
            proposed_evaluator = module .. ':evaluate'
          end
        end
      end
      local saved_config, config_status = project_config(project)
      local proposed_data = config_status == 'present' and type(saved_config.batch) == 'string' and saved_config.batch or ''
      vim.ui.input({ prompt = proposed_evaluator and tr('Evaluator (suggested starter evaluates one batch): ',
        '评估函数（建议的骨架仅评估一个批次）：', '評估函式（建議的骨架僅評估一個批次）：')
        or tr('Evaluator module:callable: ', '评估函数 module:callable：', '評估函式 module:callable：'),
        default = proposed_evaluator or '' }, function(evaluator)
        if not evaluator or evaluator == '' or state.closed then return end
        vim.ui.input({ prompt = tr('Evaluation data factory module:callable: ', '评估数据工厂 module:callable：', '評估資料工廠 module:callable：'), default = proposed_data }, function(factory)
          if not factory or factory == '' or state.closed then return end
          vim.ui.input({ prompt = tr('Data split: ', '数据切分：', '資料切分：'), default = 'test' }, function(split)
            if not split or split == '' or state.closed then return end
            local function start(spec)
              if not current() then notify(tr('Context changed; prepare evaluation again.', '上下文已变化，请重新准备评估。', '上下文已變更，請重新準備評估。'), vim.log.levels.WARN); return end
              local args = { 'evaluate', '--run', id, '--evaluator', evaluator, '--data', factory,
                '--split', split, '--if-checkpoint-sha256', checkpoint.sha256 }
              local allowed = { samples = true, preview_samples = true, data_fingerprint = true, params = true, data_params = true, device = true }
              for key in pairs(spec) do
                if not allowed[key] then notify(tr('Unknown evaluation option: ', '未知评估选项：', '未知評估選項：') .. tostring(key), vim.log.levels.WARN); return end
              end
              if spec.device ~= nil and spec.device ~= vim.NIL then
                if caps['evaluation.model_device_v1'] ~= true then
                  notify(tr('This CLI cannot select an evaluation model device.', '此 CLI 无法选择评估模型设备。', '此 CLI 無法選擇評估模型裝置。'), vim.log.levels.WARN); return
                end
                if type(spec.device) ~= 'string' or #spec.device == 0 or #spec.device > 128
                    or vim.trim(spec.device) ~= spec.device or spec.device:find('[%z\1-\31\127]') then
                  notify(tr('Invalid evaluation device.', '评估设备无效。', '評估裝置無效。'), vim.log.levels.WARN); return
                end
                vim.list_extend(args, { '--device', spec.device })
              end
              for _, entry in ipairs({ { 'samples', '--samples' }, { 'preview_samples', '--preview-samples' } }) do
                local value = spec[entry[1]]
                if value ~= nil and value ~= vim.NIL then
                  if type(value) ~= 'number' or value ~= math.floor(value) or value < 1 or value > 9007199254740991
                      or (entry[1] == 'preview_samples' and value > 32) then
                    notify(tr('Invalid evaluation sample count.', '评估样本数无效。', '評估樣本數無效。'), vim.log.levels.WARN); return
                  end
                  vim.list_extend(args, { entry[2], string.format('%.0f', value) })
                end
              end
              if type(spec.samples) == 'number' and type(spec.preview_samples) == 'number' and spec.preview_samples > spec.samples then
                notify(tr('Prediction preview count exceeds the sample target.', '预测预览数不能超过样本目标。', '預測預覽數不能超過樣本目標。'), vim.log.levels.WARN); return
              end
              if spec.data_fingerprint ~= nil and spec.data_fingerprint ~= vim.NIL then
                if type(spec.data_fingerprint) ~= 'string' or #spec.data_fingerprint > 256
                    or vim.trim(spec.data_fingerprint) == '' or spec.data_fingerprint:find('[\r\n%z\1-\31\127]') then
                  notify(tr('Invalid data identity.', '数据身份无效。', '資料身分無效。'), vim.log.levels.WARN); return
                end
                vim.list_extend(args, { '--data-fingerprint', spec.data_fingerprint })
              end
              for _, entry in ipairs({ { 'params', '--param' }, { 'data_params', '--data-param' } }) do
                local values = spec[entry[1]]
                if values ~= nil and values ~= vim.NIL then
                  local object_encoded, object_text = pcall(vim.json.encode, values)
                  if type(values) ~= 'table' or not object_encoded or object_text:sub(1, 1) ~= '{' then
                    notify(tr('Evaluation parameters must be JSON objects.', '评估参数必须是 JSON 对象。', '評估參數必須是 JSON 物件。'), vim.log.levels.WARN); return
                  end
                  local names = vim.tbl_keys(values); table.sort(names)
                  for _, name in ipairs(names) do
                    if not parameter_name_candidate(name) then
                      notify(tr('Invalid evaluation parameter name.', '评估参数名无效。', '評估參數名稱無效。'), vim.log.levels.WARN); return
                    end
                    local ok, encoded = pcall(vim.json.encode, values[name])
                    if not ok then notify(tr('Cannot encode evaluation parameter.', '无法编码评估参数。', '無法編碼評估參數。'), vim.log.levels.WARN); return end
                    vim.list_extend(args, { entry[2], name .. '=' .. encoded })
                  end
                end
              end
              local encoded, summary = pcall(vim.json.encode, next(spec) and spec or vim.empty_dict())
              if not encoded then return end
              local effects = tr('Runs the evaluator and data factory, reads checkpoint weights and writes an evaluation record. A data identity is user-declared and does not pin data content.',
                '将执行评估函数和数据工厂、读取检查点权重并写入评估记录；数据身份由用户声明，不能固定数据内容。',
                '將執行評估函式和資料工廠、讀取檢查點權重並寫入評估紀錄；資料身分由使用者宣告，無法固定資料內容。')
                .. tr('\nThe split name is passed to the evaluator; the data factory receives only its explicit data parameters.',
                  '\n切分名称传给评估器；数据工厂只接收显式配置的数据参数。',
                  '\n切分名稱傳給評估器；資料工廠只接收明確設定的資料參數。')
                .. tr('\nThe evaluator owns input device placement; an explicitly selected model device is available as context.device.',
                  '\n输入设备由评估函数负责；显式选择的模型设备可通过 context.device 读取。',
                  '\n輸入裝置由評估函式負責；明確選擇的模型裝置可透過 context.device 讀取。')
                .. tr('\nThe device is resolved in the evaluation Python environment; the report does not independently verify custom model placement.',
                  '\n设备将在评估所用的 Python 环境中解析；报告不会独立验证自定义模型的实际位置。',
                  '\n裝置將在評估所用的 Python 環境中解析；報告不會獨立驗證自訂模型的實際位置。')
                .. '\nRun: ' .. id .. '\nCheckpoint SHA-256: ' .. checkpoint.sha256
                .. '\nEvaluator: ' .. evaluator .. '\nData: ' .. factory .. '\nSplit: ' .. split
                .. '\nOptions: ' .. summary .. '\n' .. historical_python_description(state, data)
              run(state, tr('Evaluate checkpoint', '评估检查点', '評估檢查點'), args, nil, effects, true)
            end
            local options = {tr('Use defaults', '使用默认值', '使用預設值'), tr('Choose model device', '选择模型设备', '選擇模型裝置'),
              tr('Set evaluation options', '设置评估选项', '設定評估選項')}
            if factory == 'model_csv:batch' then
              options[#options + 1] = tr('Use current CSV mapping with this split', '使用当前 CSV 映射和此切分', '使用目前 CSV 對應和此切分')
            end
            vim.ui.select(options, {
              prompt = tr('Evaluation options', '评估选项', '評估選項'),
            }, function(_, choice)
              if not current() or not choice then return end
              if choice == 1 then start({}); return end
              if choice == 4 and factory == 'model_csv:batch' then
                local config, status = project_config(project)
                local values = type(config) == 'table' and config.batch_params or nil
                local weights = type(values) == 'table' and values.split_weights or nil
                local valid = status == 'present' and config.batch == factory and type(values) == 'table'
                  and type(weights) == 'table' and type(values.split_seed) == 'number'
                  and values.split_seed >= 0 and values.split_seed <= 9007199254740991
                  and values.split_seed % 1 == 0 and vim.tbl_contains({'train', 'val', 'test'}, split)
                local sum = 0
                if valid then
                  for key in pairs(weights) do if key ~= 'train' and key ~= 'val' and key ~= 'test' then valid = false end end
                  for _, key in ipairs({'train', 'val', 'test'}) do
                    local value = weights[key]
                    if type(value) ~= 'number' or value < 0 or value > 1000000 or value % 1 ~= 0 then valid = false; break end
                    sum = sum + value
                  end
                end
                if not valid or sum == 0 then
                  notify(tr('The saved CSV mapping needs explicit split weights and seed; use train, val or test and check the actual adapter.',
                    '已保存的 CSV 映射需要明确的切分权重和种子；请选择 train、val 或 test 并检查实际适配器。',
                    '已儲存的 CSV 對應需要明確的切分權重和種子；請選擇 train、val 或 test 並檢查實際配接器。'), vim.log.levels.WARN); return
                end
                local copied = vim.deepcopy(values)
                copied.split = split
                start({data_params = copied}); return
              end
              if choice == 2 then
                if caps['evaluation.model_device_v1'] ~= true then
                  notify(tr('This CLI cannot select an evaluation model device.', '此 CLI 无法选择评估模型设备。', '此 CLI 無法選擇評估模型裝置。'), vim.log.levels.WARN); return
                end
                vim.ui.input({ prompt = tr('Model device (input placement stays with evaluator): ',
                  '模型设备（输入由评估函数迁移）：', '模型裝置（輸入由評估函式遷移）：') }, function(device)
                  if device and current() then start({ device = device }) end
                end)
                return
              end
              vim.ui.input({ prompt = tr('JSON: params, data_params, samples, preview_samples, data_fingerprint, device (recorded; no secrets): ',
                'JSON：params、data_params、samples、preview_samples、data_fingerprint、device（会记录，请勿填密钥）：',
                'JSON：params、data_params、samples、preview_samples、data_fingerprint、device（會記錄，請勿填金鑰）：'), default = '{}' }, function(raw)
                if not raw or not current() then return end
                local ok, spec = pcall(vim.json.decode, raw)
                if #raw > 16384 or not ok or type(spec) ~= 'table' or not raw:match('^%s*{') then
                  notify(tr('Enter a JSON object up to 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
                end
                start(spec)
              end)
            end)
          end)
        end)
      end)
    end)
  end)
end

export_run = function(state, id)
  if state.busy or state.closed then return end
  local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and state.opts.cli == cli and (state.change_epoch or 0) == epoch
  end
  state.busy = tr('Checking export support', '检查导出能力', '檢查匯出能力')
  render(state)
  request(state, { '--describe-interface' }, function(interface, err)
    state.busy = nil
    if not current() then
      render(state)
      notify(tr('Context changed; prepare export again.', '上下文已变化，请重新准备导出。', '上下文已變更，請重新準備匯出。'), vim.log.levels.WARN)
      return
    end
    local caps = interface and interface.data and interface.data.capabilities
    if err or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['export.conditional_checkpoint'] ~= true
        or caps['export.explicit_python_fallback_v1'] ~= true then
      render(state)
      notify(tr('This CLI cannot pin an export checkpoint.', '此 CLI 无法固定导出检查点。', '此 CLI 無法固定匯出檢查點。'), vim.log.levels.WARN); return
    end
    state.busy = tr('Reading checkpoint', '读取检查点', '讀取檢查點')
    render(state)
    request(state, { 'runs', 'show', id }, function(report, failure, stderr)
      state.busy = nil
      if not current() then
        render(state)
        notify(tr('Context changed while reading the checkpoint; prepare export again.',
          '读取检查点时上下文已变化，请重新准备导出。', '讀取檢查點時上下文已變更，請重新準備匯出。'), vim.log.levels.WARN)
        return
      end
      state.last = { report = report, transport_error = failure, stderr = stderr }
      render(state)
      local data = report and report.data
      local record = type(data) == 'table' and data.record
      local checkpoint = type(data) == 'table' and data.checkpoint
      if failure or not report or report.operation ~= 'runs_show' or report.status ~= 'success'
          or type(record) ~= 'table' or record.id ~= id or type(checkpoint) ~= 'table'
          or not sha256(checkpoint.sha256) then
        notify(tr('A verified checkpoint identity is required for export.', '导出需要已核对的检查点身份。', '匯出需要已核對的檢查點身分。'), vim.log.levels.WARN)
        show_report(state); return
      end
      show_report(state)
      vim.ui.input({ prompt = tr('New export directory outside the project: ', '项目外的新导出目录：', '專案外的新匯出目錄：'), completion = 'dir' }, function(destination)
        if not destination or destination == '' then return end
        if not current() then
          notify(tr('Context changed; prepare export again.', '上下文已变化，请重新准备导出。', '上下文已變更，請重新準備匯出。'), vim.log.levels.WARN); return
        end
        local absolute = destination:sub(1, 1) == '/' or destination:match('^%a:[/\\]') or destination:match('^[/\\][/\\]')
        local path = vim.fn.fnamemodify(absolute and destination or (state.opts.project .. '/' .. destination), ':p')
        local args = { 'export', path, '--run', id, '--if-checkpoint-sha256', checkpoint.sha256 }
        local saved_inputs = type(data.inputs) == 'table' and data.inputs or {}
        local report_data = type(data.report) == 'table' and data.report.data or nil
        local actual_runtime = type(report_data) == 'table' and report_data.runtime or nil
        local requested_runtime = type(saved_inputs.runtime) == 'table' and saved_inputs.runtime or nil
        local saved_python = type(actual_runtime) == 'table' and actual_runtime.python_executable or nil
        if type(saved_python) ~= 'string' or saved_python == '' then
          saved_python = type(requested_runtime) == 'table' and requested_runtime.python_executable or nil
        end
        local python_note
        if type(saved_python) == 'string' and saved_python ~= '' then
          python_note = tr('Recorded Python if needed: ', '需要时使用历史 Python：', '需要時使用歷史 Python：') .. saved_python
        elseif state.opts.python and state.opts.python ~= '' then
          python_note = tr('No recorded Python; explicit session Python if needed: ', '未记录 Python；需要时使用明确选择的会话 Python：', '未記錄 Python；需要時使用明確選擇的工作階段 Python：') .. state.opts.python
        else
          python_note = tr('No recorded or explicit Python; environment may remain unknown and extension verification may require a choice.',
            '未记录或明确选择 Python；环境可能保持未知，扩展核验可能需要先选择。',
            '未記錄或明確選擇 Python；環境可能保持未知，擴充套件核驗可能需要先選擇。')
        end
        python_note = vim.fn.strcharpart(python_note:gsub('[\r\n%z\1-\31\127]', ' '), 0, 1024)
        local effects = tr('Writes code and checkpoint to a new directory. Datasets and external resources are not included; checkpoint state may be sensitive. Recorded Python may start to inspect missing environment information.',
          '将源码和检查点写入新目录；不包含数据集或外部资源，检查点状态可能含敏感信息。缺少环境记录时可能启动记录的 Python 进行检查。',
          '將原始碼和檢查點寫入新目錄；不包含資料集或外部資源，檢查點狀態可能含敏感資訊。缺少環境紀錄時可能啟動記錄的 Python 進行檢查。')
          .. '\nRun: ' .. id .. '\nCheckpoint SHA-256: ' .. checkpoint.sha256 .. '\nDestination: ' .. path .. '\n' .. python_note
        local function before_start()
          if not current() then
            notify(tr('Context changed; prepare export again.', '上下文已变化，请重新准备导出。', '上下文已變更，請重新準備匯出。'), vim.log.levels.WARN)
            return false
          end
          local stat, stat_err, code = vim.uv.fs_lstat(path)
          if stat or code ~= 'ENOENT' then
            notify(tr('Export destination exists or cannot be checked: ', '导出目标已存在或无法核查：', '匯出目標已存在或無法核查：') .. tostring(stat_err or path), vim.log.levels.WARN)
            return false
          end
          return true
        end
        run(state, tr('Export run', '导出运行', '匯出執行'), args, function(receipt, result_err)
          local saved = receipt and receipt.data
          if result_err and result_err.operation_started == false then
            notify(tr('Export did not start; no export was requested.', '导出未启动；没有发出导出请求。', '匯出未啟動；沒有發出匯出要求。'), vim.log.levels.INFO)
          elseif result_err or not receipt or receipt.operation ~= 'export' or receipt.status ~= 'success'
              or type(saved) ~= 'table' or saved.run_id ~= id or saved.checkpoint_sha256 ~= checkpoint.sha256
              or type(saved.path) ~= 'string' then
            notify('Export outcome is not acknowledged. Inspect the destination before retrying.', vim.log.levels.WARN)
          end
        end, effects, true, before_start)
      end)
    end)
  end)
end

local function guarded_layer_preview(state, args, mixed_transaction, layer_draft, on_failure)
  if state.pending_source then
    notify(tr('Finish or cancel the current source preview first.', '请先完成或取消当前源码预览。', '請先完成或取消目前原始碼預覽。'), vim.log.levels.WARN)
    return
  end
  local project = state.project_info
  if state.busy or not project or not sha256(project.config_revision) or not (state.batch or project.batch) then
    notify(tr('Source editing requires a configured project and a representative input.',
      '源码编辑需要已配置的项目和代表输入。',
      '原始碼編輯需要已設定的專案和代表輸入。'), vim.log.levels.WARN)
    return
  end
  local captured_epoch, revision = state.change_epoch or 0, project.config_revision
  local initial_project, initial_cli = state.opts.project, state.opts.cli
  local draft_contents = layer_draft and vim.deepcopy({ layer_draft.operations, layer_draft.structures }) or nil
  local previous_draft_status = layer_draft and layer_draft.status or 'draft'
  local function set_draft_status(status)
    if layer_draft and state.layer_draft == layer_draft
        and vim.deep_equal(draft_contents, { layer_draft.operations, layer_draft.structures }) then
      layer_draft.status = status
    end
  end
  local initial_model, initial_batch, initial_python, initial_directory = state.model, state.batch, state.opts.python, state.opts.working_directory
  local initial_binding = state.batch_binding
  local initial_roots = vim.deepcopy(state.opts.project_import_roots)
  -- An explicit session reset is transmitted as the project directory so it
  -- overrides any saved project directory. Compare the resolved identity, not
  -- the empty value shown in the session picker.
  local expected_directory = initial_directory or (state.opts.runtime_paths_override and vim.uv.fs_realpath(state.opts.project) or nil)
  local initial_model_params, initial_batch_params = vim.deepcopy(state.model_params or {}), vim.deepcopy(state.batch_params or {})
  state.busy = tr('Checking source edit capabilities', '检查源码编辑能力', '檢查原始碼編輯能力')
  render(state)
  request(state, { '--describe-interface' }, function(interface, failure)
    if state.closed or state.opts.project ~= initial_project or state.opts.cli ~= initial_cli then
      return
    end
    state.busy = nil
    render(state)
    local caps = interface and interface.data and interface.data.capabilities
    local required = { 'edit.conditional_source_plan', 'edit.conditional_source_input',
      'edit.conditional_source_config', 'edit.conditional_source_project_manifest', 'edit.source_factory_device_v1' }
    if args[1] == 'layer' and args[2] == 'apply' then required[#required + 1] = 'edit.atomic_source_transaction' end
    if mixed_transaction then required[#required + 1] = 'edit.mixed_source_transaction_v1' end
    if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' then
      notify('Cannot verify source edit capabilities. No source was changed.', vim.log.levels.ERROR)
      return
    end
    for _, name in ipairs(required) do
      if caps[name] ~= true then
        notify(tr('CLI capability missing: ', 'CLI 缺少能力：', 'CLI 缺少能力：') .. name
          .. tr('; source commit is unavailable.', '；无法提交源码。', '；無法提交原始碼。'), vim.log.levels.WARN)
        return
      end
    end
    if state.closed or state.opts.project ~= initial_project or state.opts.cli ~= initial_cli
        or (state.change_epoch or 0) ~= captured_epoch or #dirty_buffers(state.opts.project) > 0
        or not state.project_info or state.project_info.config_revision ~= revision then
      notify('Project changed; start a new preview.', vim.log.levels.WARN)
      return
    end
    local function start_preview(snapshot)
    local function cleanup()
      if not snapshot or snapshot.cleaned then return end
      snapshot.cleaned = true
      local _, file_err, file_code = vim.uv.fs_unlink(snapshot.path)
      local removed, dir_err, dir_code = vim.uv.fs_rmdir(snapshot.dir)
      if (file_err and file_code ~= 'ENOENT') or (not removed and dir_code ~= 'ENOENT') then
        notify(tr('Could not remove the temporary input snapshot; inspect it: ', '无法清理临时输入快照，请检查：', '無法清理暫存輸入快照，請檢查：') .. snapshot.path .. ' · ' .. tostring(file_err or dir_err), vim.log.levels.WARN)
      end
      if state.snapshot_cleanup == cleanup then state.snapshot_cleanup = nil end
    end
    if snapshot then
      if state.snapshot_cleanup and state.snapshot_cleanup ~= cleanup then state.snapshot_cleanup() end
      snapshot.cleanup = cleanup
      state.snapshot_cleanup = cleanup
    end
    if state.closed or state.busy or state.opts.project ~= initial_project or state.opts.cli ~= initial_cli
        or (state.change_epoch or 0) ~= captured_epoch
        or state.model ~= initial_model or state.batch ~= initial_batch or state.batch_binding ~= initial_binding or state.opts.python ~= initial_python or state.opts.working_directory ~= initial_directory
        or not vim.deep_equal(state.opts.project_import_roots, initial_roots)
        or not vim.deep_equal(state.model_params or {}, initial_model_params)
        or not vim.deep_equal(state.batch_params or {}, initial_batch_params)
        or not state.project_info or state.project_info.config_revision ~= revision then
      notify('Project changed; start a new preview.', vim.log.levels.WARN)
      cleanup(); return
    end
    local preview_args = vim.deepcopy(args)
    vim.list_extend(preview_args, { '--require-forward', '--if-source-config', revision })
    if snapshot then vim.list_extend(preview_args, { '--replay-input-from', snapshot.path, '--if-input-content', snapshot.digest }) end
    run(state, tr('Preview layer change', '预览 Layer 修改', '預覽 Layer 修改'), preview_args, function(report, err, operation_args, stale, report_buf)
      local data = report and report.data
      local validation = type(data) == 'table' and data.validation or nil
      local content = type(validation) == 'table' and validation.batch_content or nil
      local source = type(data) == 'table' and data.source_manifest_evidence or nil
      local plan = type(data) == 'table' and data.source_plan or nil
      local patch = type(data) == 'table' and data.source_patch or nil
      if err or stale or not report or report.operation ~= 'edit' or report.status ~= 'success'
          or type(data) ~= 'table' or data.target ~= 'source' or data.committed ~= false
          or data.config_revision ~= revision or type(validation) ~= 'table'
          or validation.construction ~= 'passed' or validation.syntax ~= 'passed'
          or validation.forward ~= 'passed' or validation.forward_evidence ~= 'executed' or validation.mode ~= 'eval'
          or type(content) ~= 'table' or content.status ~= 'available' or content.algorithm ~= 'sha256-forward-input-v1' or not sha256(content.digest)
          or type(source) ~= 'table' or source.algorithm ~= 'canonical-json-sha256-v1' or source.scope ~= 'worker-recorded-project-sources' or not sha256(source.digest)
          or type(plan) ~= 'table' or plan.algorithm ~= 'canonical-json-sha256-v1'
          or (initial_roots and (plan.scope ~= 'planned-source-patches-and-runtime-paths-v3'
            or not vim.deep_equal(plan.project_import_roots, initial_roots)
            or (expected_directory and plan.working_directory ~= expected_directory)
            or (not expected_directory and plan.working_directory ~= nil and plan.working_directory ~= vim.NIL)))
          or (not initial_roots and expected_directory and (plan.scope ~= 'planned-source-file-patches-and-working-directory-v2' or plan.working_directory ~= expected_directory))
          or (not initial_roots and not expected_directory and plan.scope ~= 'planned-source-file-patches-v1') or not sha256(plan.digest)
          or type(patch) ~= 'table' or type(patch.unified_diff) ~= 'string' or patch.unified_diff == ''
          or not reviewable_text(patch.unified_diff) then
        notify('Candidate evidence is incomplete or stale; source cannot be committed. Review the report or edit manually.', vim.log.levels.WARN)
        cleanup()
        if on_failure and not stale and not state.closed and state.opts.project == initial_project
            and state.opts.cli == initial_cli and (state.change_epoch or 0) == captured_epoch then
          on_failure()
        end
        return
      end
      if snapshot and (content.digest ~= snapshot.digest or type(validation.batch_snapshot) ~= 'table'
          or validation.batch_snapshot.status ~= 'replayed' or validation.batch_snapshot.format ~= 'model-maven-forward-input-snapshot-v1') then
        notify(tr('Snapshot replay was not confirmed; source cannot be committed.', '未确认输入快照重放，不能提交源码。', '未確認輸入快照重播，不能提交原始碼。'), vim.log.levels.WARN)
        cleanup(); return
      end
      local resolved_python = initial_python
        or (type(project.runtime_python) == 'string' and project.runtime_python or nil)
      for index, arg in ipairs(operation_args) do
        if arg == '--python' then resolved_python = operation_args[index + 1]; break end
      end
      local pending = { epoch = state.change_epoch or 0, revision = revision,
        source = source.digest, plan = plan.digest, input = content.digest,
        model = state.model, batch = state.batch, batch_binding = initial_binding, python = state.opts.python, resolved_python = resolved_python, working_directory = initial_directory, import_roots = initial_roots,
        model_params = initial_model_params, batch_params = initial_batch_params,
        args = vim.tbl_filter(function(arg) return arg ~= '--dry-run' end, operation_args), paths = {} }
      local patches = type(data.source_patches) == 'table' and data.source_patches or { patch }
      for _, item in ipairs(patches) do
        if type(item) ~= 'table' or type(item.path) ~= 'string' or item.path == '' then
          notify(tr('Source paths are unavailable; cannot safely update open buffers.', '无法获取源码路径，不能安全更新已打开的 buffer。', '無法取得原始碼路徑，不能安全更新已開啟的 buffer。'), vim.log.levels.WARN)
          cleanup()
          return
        end
        pending.paths[#pending.paths + 1] = item.path
      end
      if #pending.paths == 0 then cleanup(); return end
      state.pending_source = pending
      set_draft_status('preview_ready')
      review_gate(report_buf, { tr('Cancel', '取消', '取消'), tr('Apply source change', '应用源码修改', '套用原始碼修改') },
        tr('Apply the reviewed source change?', '应用已查看的源码修改？', '套用已檢視的原始碼修改？'), function(_, index)
        if index ~= 2 or state.closed then state.pending_source = nil; set_draft_status(previous_draft_status); cleanup(); return end
        if state.busy or state.opts.project ~= initial_project or state.opts.cli ~= initial_cli
            or state.pending_source ~= pending or (state.change_epoch or 0) ~= pending.epoch
            or #dirty_buffers(state.opts.project) > 0 or #reloads_pending(state) > 0
            or #stale_python_buffers(state.opts.project) > 0 or state.model ~= pending.model or state.batch ~= pending.batch or state.batch_binding ~= pending.batch_binding
            or state.opts.python ~= pending.python or state.opts.working_directory ~= pending.working_directory
            or not vim.deep_equal(state.opts.project_import_roots, pending.import_roots)
            or not vim.deep_equal(state.model_params or {}, pending.model_params)
            or not vim.deep_equal(state.batch_params or {}, pending.batch_params)
            or not state.project_info or state.project_info.config_revision ~= revision then
          state.pending_source = nil
          set_draft_status(previous_draft_status)
          notify('Context changed; source was not changed. Preview again.', vim.log.levels.WARN)
          cleanup()
          return
        end
        state.pending_source = nil
        local apply = vim.deepcopy(pending.args)
        vim.list_extend(apply, { '--if-source-plan', pending.plan, '--if-source-manifest', pending.source })
        if not snapshot then vim.list_extend(apply, { '--if-input-content', pending.input }) end
        local commit_project = state.opts.project
        local commit_cli = state.opts.cli
        local commit_focus_win = vim.api.nvim_get_current_win()
        local commit_focus_buf = vim.api.nvim_get_current_buf()
        local commit_title = tr('Apply source change', '应用源码修改', '套用原始碼修改')
        local marker, marker_error = pending_operation.create(commit_project, commit_title)
        if not marker then
          set_draft_status(previous_draft_status)
          notify(tr('Cannot record the pending source change; nothing was started: ',
            '无法记录待核查的源码修改；操作尚未启动：',
            '無法記錄待核查的原始碼修改；操作尚未啟動：') .. tostring(marker_error), vim.log.levels.ERROR)
          cleanup()
          return
        end
        state.pending_foreground_checked, state.pending_foreground_cache = nil, nil
        state.busy = tr('Applying source change', '应用源码修改', '套用原始碼修改')
        render(state)
        request(state, apply, function(receipt, problem, stderr)
          -- Even a lost receipt may have changed disk. Never overwrite an open buffer.
          mark_source_buffers({ opts = { project = commit_project } }, pending.paths)
          local saved = receipt and receipt.data
          local check = type(saved) == 'table' and saved.source_validation or nil
          local verified = not problem and receipt and receipt.operation == 'edit' and receipt.status == 'success'
              and type(saved) == 'table' and saved.committed == true and saved.target == 'source'
              and type(saved.source_plan) == 'table' and saved.source_plan.digest == pending.plan
              and saved.config_revision == revision and type(check) == 'table' and check.operation == 'probe'
              and check.status == 'passed' and check.source_config_revision == revision
              and check.source_manifest_status == 'passed' and check.source_manifest_digest == pending.source
              and type(check.batch_content) == 'table' and check.batch_content.status == 'available'
              and check.batch_content.algorithm == 'sha256-forward-input-v1' and check.batch_content.digest == pending.input
              and (not snapshot or (type(check.batch_snapshot) == 'table' and check.batch_snapshot.status == 'replayed'
                and check.batch_snapshot.format == 'model-maven-forward-input-snapshot-v1'))
          local no_start = problem and problem.operation_started == false
          local uncertain = not verified and not no_start
          if state.closed or state.opts.project ~= commit_project or state.opts.cli ~= commit_cli then
            if not uncertain then
              local cleared, clear_error = pending_operation.clear(commit_project, marker)
              if not cleared then
                notify(tr('Could not clear the original project marker: ', '无法清除原项目的待核查标记：', '無法清除原專案的待核查標記：') .. tostring(clear_error), vim.log.levels.WARN)
              end
            end
            if state.busy == commit_title then state.busy = nil end
            notify(tr('Source change finished in the original project; inspect it before continuing: ',
              '源码修改已在原项目结束；继续前请返回核查：', '原始碼修改已在原專案結束；繼續前請返回核查：') .. commit_project, vim.log.levels.WARN)
            cleanup()
            return
          end
          state.busy = nil
          state.last = { report = receipt, transport_error = problem, stderr = stderr,
            scope = tr('The requested source checks are not confirmed by a complete success receipt. Inspect files and external effects before continuing.',
              '没有完整成功回执确认请求的源码检查；继续前请检查文件及外部影响。',
              '沒有完整成功回執確認要求的原始碼檢查；繼續前請檢查檔案及外部影響。') }
          if verified then
            state.last.scope = tr('Source plan, project source manifest, saved configuration and this forward input were checked by the CLI. External libraries, target values and later changes are not pinned.',
              'CLI 已核对源码计划、项目源码清单、已保存配置和本次前向输入；外部库、目标值及后续变化未固定。',
              'CLI 已核對原始碼計畫、專案原始碼清單、已儲存設定和本次前向輸入；外部程式庫、目標值及後續變更未固定。')
          elseif no_start then
            state.last.scope = tr('The source change did not start; no source checks were performed by this request.',
              '源码修改未启动；此请求没有执行源码检查。', '原始碼修改未啟動；此要求沒有執行原始碼檢查。')
          end
          if not uncertain then
            local cleared, clear_error = pending_operation.clear(commit_project, marker)
            if not cleared then
              uncertain = true
              notify(tr('Could not clear the pending source marker; inspect before continuing: ',
                '无法清除源码待核查标记；继续前请检查：', '無法清除原始碼待核查標記；繼續前請檢查：') .. tostring(clear_error), vim.log.levels.WARN)
            end
          end
          state.pending_foreground_checked, state.pending_foreground_cache = nil, nil
          if uncertain then
            state.pending_uncertain_operation = { title = commit_title }
            state.last.uncertain_outcome = true
          end
          if verified and not uncertain then
            if not snapshot and state.snapshot_cleanup then state.snapshot_cleanup() end
            state.last_edit = { revision = revision, input_digest = pending.input, model = pending.model,
              batch = pending.batch, batch_binding = pending.batch_binding, python = pending.python, resolved_python = pending.resolved_python, working_directory = pending.working_directory,
              import_roots = pending.import_roots, model_params = pending.model_params, batch_params = pending.batch_params,
              awaiting_recheck = true, snapshot = snapshot }
            state.journey = 'changed'
            set_draft_status('applied')
            if (state.change_epoch or 0) ~= pending.epoch or #dirty_buffers(state.opts.project) > 0 then
              state.result_label = tr('source saved; buffers changed during save—review before continuing', '源码已保存；保存期间缓冲区发生变化，请先检查', '原始碼已儲存；儲存期間緩衝區發生變更，請先檢查')
              state.last.context_changed = true; state.last.observed_context_changed = true
            elseif #reloads_pending(state) > 0 then
              state.result_label = tr('source saved; reload changed files before rechecking',
                '源码已保存；重验前请重新载入修改的文件', '原始碼已儲存；重新驗證前請重新載入修改的檔案')
              state.last.context_changed = true; state.last.observed_context_changed = true
            else
              state.result_label = tr('source saved; independent recheck pending', '源码已保存；尚待独立重验', '原始碼已儲存；尚待獨立重驗')
            end
          elseif no_start and not uncertain then
            set_draft_status(previous_draft_status)
            state.result_label = tr('source change did not start', '源码修改未启动', '原始碼修改未啟動')
          else
            set_draft_status('outcome_unknown')
            state.result_label = tr('save outcome unknown; inspect files before retry', '保存结果未知；重试前请检查文件', '儲存結果未知；重試前請檢查檔案')
          end
          if not verified or uncertain then cleanup() end
          render(state)
          if vim.api.nvim_get_current_win() == commit_focus_win
              and vim.api.nvim_win_is_valid(commit_focus_win)
              and vim.api.nvim_win_get_buf(commit_focus_win) == commit_focus_buf then
            show_report(state)
          else
            notify(tr('Source change finished; return to its project and open the report: ',
              '源码修改已结束；请返回对应项目打开报告：', '原始碼修改已結束；請返回對應專案開啟報告：') .. commit_project, vim.log.levels.INFO)
          end
        end, function()
          if not state.closed and state.opts.project == commit_project and state.opts.cli == commit_cli then
            set_draft_status('outcome_unknown')
          end
          mark_source_buffers({ opts = { project = commit_project } }, pending.paths)
          cleanup()
        end)
      end, function() state.pending_source = nil; set_draft_status(previous_draft_status); cleanup() end)
    end, nil, false, nil, cleanup)
    end
    local choices = { tr('Use a fresh input each time', '每次使用新输入', '每次使用新輸入') }
    local captured = state.canvas_snapshot
    local reuse_index
    if caps['input_snapshot.capture_replay'] == true then
      choices[#choices + 1] = tr('Capture and replay this input', '捕获并重放本次输入', '擷取並重播本次輸入')
      if captured and not captured.cleaned and captured.project == initial_project and sha256(captured.digest) then
        choices[#choices + 1] = tr('Reuse the input captured earlier', '使用之前捕获的输入', '使用之前擷取的輸入')
        reuse_index = #choices
      end
    end
    vim.ui.select(choices, { prompt = tr('How should the candidate input be handled?', '候选输入如何处理？', '候選輸入如何處理？') }, function(_, choice)
      if not choice or state.closed then return end
      if choice == 1 then start_preview(nil); return end
      if choice == reuse_index then
        if state.canvas_snapshot ~= captured or captured.cleaned or state.opts.project ~= initial_project then
          notify(tr('The captured input is no longer available.', '之前捕获的输入已不可用。', '之前擷取的輸入已無法使用。'), vim.log.levels.WARN); return
        end
        local original = vim.uv.fs_lstat(captured.path)
        if not original or original.type ~= 'file' then
          notify(tr('The captured input is no longer available.', '之前捕获的输入已不可用。', '之前擷取的輸入已無法使用。'), vim.log.levels.WARN); return
        end
        local dir = vim.fn.tempname()
        local made, mkdir_error = vim.uv.fs_mkdir(dir, 448)
        if not made then notify(tr('Cannot create an input snapshot directory: ', '无法创建输入快照目录：', '無法建立輸入快照目錄：') .. tostring(mkdir_error), vim.log.levels.ERROR); return end
        local copy = dir .. '/input.snapshot'
        local copied, copy_error = vim.uv.fs_copyfile(captured.path, copy)
        if not copied then
          vim.uv.fs_unlink(copy); vim.uv.fs_rmdir(dir)
          notify(tr('Cannot copy the captured input: ', '无法复制已捕获输入：', '無法複製已擷取輸入：') .. tostring(copy_error), vim.log.levels.ERROR); return
        end
        start_preview({ dir = dir, path = copy, digest = captured.digest })
        return
      end
      local dir = vim.fn.tempname()
      local snapshot = { dir = dir, path = dir .. '/input.snapshot' }
      local function cleanup_capture()
        if snapshot.cleaned then return end
        snapshot.cleaned = true
        local _, file_err, file_code = vim.uv.fs_unlink(snapshot.path)
        local removed, dir_err, dir_code = vim.uv.fs_rmdir(snapshot.dir)
        if (file_err and file_code ~= 'ENOENT') or (not removed and dir_code ~= 'ENOENT') then
          notify(tr('Could not remove the temporary input snapshot; inspect it: ', '无法清理临时输入快照，请检查：', '無法清理暫存輸入快照，請檢查：') .. snapshot.path .. ' · ' .. tostring(file_err or dir_err), vim.log.levels.WARN)
        end
      end
      local function prepare(capture_args)
        if (state.change_epoch or 0) ~= captured_epoch or state.model ~= initial_model or state.batch ~= initial_batch or state.batch_binding ~= initial_binding
            or state.opts.python ~= initial_python or state.opts.working_directory ~= initial_directory
            or not vim.deep_equal(state.opts.project_import_roots, initial_roots)
            or not vim.deep_equal(state.model_params or {}, initial_model_params)
            or not vim.deep_equal(state.batch_params or {}, initial_batch_params)
            or not state.project_info or state.project_info.config_revision ~= revision then
          notify('Project changed; start a new preview.', vim.log.levels.WARN)
          snapshot.cleaned = true
          return false
        end
        local ok, err = vim.uv.fs_mkdir(dir, 448)
        if not ok then
          snapshot.cleaned = true
          notify(tr('Cannot create a private temporary directory: ', '无法创建私有临时目录：', '無法建立私有暫存目錄：') .. tostring(err), vim.log.levels.ERROR)
          return false
        end
        vim.list_extend(capture_args, { '--capture-input-to', snapshot.path })
        return true
      end
      local effect = tr('Captures input values in a temporary file; targets are not captured. Directory access is restricted where supported. After saving, the snapshot is retained for independent recheck and removed after a matching pass or when the workspace closes; abnormal exit may leave it behind.',
        '将在临时文件中捕获输入值，不包含目标；在支持的平台限制目录访问。保存后将保留快照用于独立重验；匹配通过或关闭工作区时尝试清理，异常退出可能留下文件。',
        '將在暫存檔中擷取輸入值，不包含目標；在支援的平台限制目錄存取。儲存後將保留快照用於獨立重新驗證；符合通過或關閉工作區時嘗試清理，異常結束可能留下檔案。') .. '\n' .. snapshot.path
      run(state, tr('Capture representative input', '捕获代表输入', '擷取代表輸入'), { 'model', 'probe' }, function(report, err, _, stale)
        local data = report and report.data
        local content = type(data) == 'table' and data.batch_content
        local recorded = type(data) == 'table' and data.batch_snapshot
        local file = vim.uv.fs_lstat(snapshot.path)
        if err or stale or not report or report.operation ~= 'probe' or type(data) ~= 'table'
            or data.config_revision ~= revision or type(content) ~= 'table' or content.status ~= 'available'
            or content.algorithm ~= 'sha256-forward-input-v1' or not sha256(content.digest)
            or type(recorded) ~= 'table' or recorded.status ~= 'captured'
            or recorded.format ~= 'model-maven-forward-input-snapshot-v1' or not file or file.type ~= 'file' then
          notify(tr('Input capture could not be verified; no source was changed.', '无法确认输入捕获，源码未修改。', '無法確認輸入擷取，原始碼未修改。'), vim.log.levels.WARN)
          cleanup_capture(); return
        end
        snapshot.digest = content.digest
        start_preview(snapshot)
      end, effect, false, prepare, cleanup_capture)
    end)
  end)
end

edit_reported_parameter = function(state, row, current_selection)
  local fields, labels = {}, {}
  local current = type(row.editable_params) == 'table' and row.editable_params or {}
  for _, name in ipairs(row.source_editable_fields or {}) do
    if identifier_candidate(name) then
      local encoded, value = pcall(vim.json.encode, current[name])
      if current[name] == nil or not encoded then value = tr('unknown', '未知', '未知') end
      fields[#fields + 1] = { name = name, default = current[name] ~= nil and encoded and value or '' }
      labels[#labels + 1] = name .. '  ·  ' .. vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, 120)
    end
    if #fields >= 64 then break end
  end
  if #fields == 0 then
    notify(tr('No editable constructor fields were reported.', '报告未提供可编辑的构造参数。', '報告未提供可編輯的建構參數。'), vim.log.levels.INFO)
    return
  end
  vim.ui.select(labels, { prompt = tr('Choose a constructor parameter', '选择构造参数', '選擇建構參數') }, function(_, index)
    local field = index and fields[index]
    if not field or not current_selection() then return end
    vim.ui.input({ prompt = tr('New value as JSON (visible in process arguments; no secrets): ',
      '新值（JSON；会出现在进程参数中，请勿填写密钥）：', '新值（JSON；會出現在程序參數中，請勿填寫金鑰）：'),
      default = field.default }, function(raw)
      if raw == nil or not current_selection() then return end
      if #raw > 16384 then notify(tr('Value is too large.', '值过大。', '值過大。'), vim.log.levels.WARN); return end
      local decoded, value = pcall(vim.json.decode, raw)
      local encoded, canonical = false, nil
      if decoded then encoded, canonical = pcall(vim.json.encode, value) end
      if not decoded or not encoded then
        notify(tr('Enter a valid JSON value.', '请输入有效的 JSON 值。', '請輸入有效的 JSON 值。'), vim.log.levels.WARN); return
      end
      state.last_selection = row.path
      guarded_layer_preview(state, { 'layer', 'set', row.path, '--param', field.name .. '=' .. canonical,
        '--target', 'source', '--dry-run' })
    end)
  end)
end

local function find_component_factories(state, same_context, callback)
  if not same_context() then callback({}); return end
  local remaining, registered, local_factories = 2, {}, {}
  local saved = project_config(state.opts.project)
  local saved_paths = type(saved) == 'table' and saved.runtime_paths or nil
  local roots = state.opts.project_import_roots
  if not state.opts.runtime_paths_override and not roots and type(saved_paths) == 'table'
      and type(saved_paths.project_import_roots) == 'table' then roots = saved_paths.project_import_roots end
  roots = vim.deepcopy(roots or {})
  local function done()
    remaining = remaining - 1
    if remaining == 0 then callback(same_context() and vim.list_extend(registered, local_factories) or {}) end
  end
  request(state, { 'component', 'list' }, function(report)
    local components = report and report.status == 'success' and report.operation == 'component_list'
      and type(report.data) == 'table' and report.data.components
    if type(components) == 'table' and is_list(components) then
      for _, item in ipairs(components) do
        local manifest = type(item) == 'table' and item.manifest
        local cap = type(manifest) == 'table' and manifest.capabilities
        local construct = type(cap) == 'table' and cap.construct
        local id = type(manifest) == 'table' and manifest.component_id
        local version = type(manifest) == 'table' and manifest.component_version
        if type(id) == 'string' and #id <= 129 and id:match('^[%w_-]+/[%w_-]+$')
            and type(version) == 'string' and #version <= 64 and version:match('^%d+%.%d+%.%d+$')
            and manifest.kind == 'layer' and type(construct) == 'table' and construct.state == 'supported' then
          registered[#registered + 1] = 'component:' .. id .. '@' .. version
          if #registered == 32 then break end
        end
      end
    end
    done()
  end)
  local args = { 'discover' }
  for _, root in ipairs(roots) do
    vim.list_extend(args, { '--import-root', root })
  end
  request(state, args, function(report)
    local candidates = report and report.status == 'success' and report.operation == 'project_discover'
      and type(report.data) == 'table' and report.data.executed_project_code == false and report.data.candidates
    if type(candidates) == 'table' and is_list(candidates) then
      local seen = {}
      local function add(entrypoint)
        if type(entrypoint) == 'string' and #entrypoint <= 240 and entrypoint:match('^[^%s:;=@]+:[^%s:;=@]+$')
            and not seen[entrypoint] and #local_factories < 64 then
          seen[entrypoint] = true
          local_factories[#local_factories + 1] = entrypoint
        end
      end
      for _, item in ipairs(candidates) do
        if type(item) == 'table' and (item.kind == 'model' or item.kind == 'callable') then
          -- Prefer import paths that match the runtime roots (or project root).
          local alternatives = type(item.entrypoint_alternatives) == 'table' and item.entrypoint_alternatives or {}
          if item.module_basis == 'project_root' or (item.module_basis == 'explicit_import_root' and vim.tbl_contains(roots, item.suggested_import_root)) then
            add(item.entrypoint)
          end
          for _, alternative in ipairs(alternatives) do
            if type(alternative) == 'table' and (alternative.basis == 'project_root'
                or (alternative.basis == 'explicit_import_root' and vim.tbl_contains(roots, alternative.import_root))) then
              add(alternative.entrypoint)
            end
          end
          add(item.entrypoint)
        end
      end
    end
    done()
  end)
end

local function assemble(state, preferred_slot)
  local project = state.project_info
  if state.busy or not project or not sha256(project.config_revision)
      or (state.model and state.model ~= project.model) or (state.batch and state.batch ~= project.batch)
      or next(state.model_params or {}) or next(state.batch_params or {}) or state.batch_binding then
    local pending_draft = state.assembly_draft
    if pending_draft and not state.busy then
      local ok, text = pcall(vim.inspect, pending_draft.spec)
      if not ok or not reviewable_text(text) then
        notify(tr('The saved session draft cannot be displayed here; it remains in memory.',
          '无法在此显示会话草稿；草稿仍保留在内存中。', '無法在此顯示工作階段草稿；草稿仍保留在記憶體中。'), vim.log.levels.WARN)
        return
      end
      local buf = vim.api.nvim_create_buf(false, true)
      vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
      local lines = { tr('Saved assembly draft', '会话装配草稿', '工作階段裝配草稿'), pending_draft.project,
        tr('Restore a compatible project and input before previewing.', '预览前请恢复兼容的项目和输入。', '預覽前請恢復相容的專案和輸入。'), '' }
      vim.list_extend(lines, vim.split(text, '\n', { plain = true }))
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
      vim.bo[buf].modifiable = false
      if not open_aux_buffer(buf, false, false) then return end
      vim.keymap.set('n', 'q', function() if vim.api.nvim_buf_is_valid(buf) then vim.api.nvim_buf_delete(buf, { force = true }) end end,
        { buffer = buf, silent = true, desc = 'Close assembly draft review' })
      review_gate(buf, { tr('Keep draft', '保留草稿', '保留草稿'), tr('Discard draft', '放弃草稿', '放棄草稿') },
        tr('The draft cannot be previewed in the current context.', '当前上下文不能预览草稿。', '目前上下文不能預覽草稿。'), function(_, choice)
          if choice == 2 and state.assembly_draft == pending_draft then state.assembly_draft = nil; render(state) end
        end)
      return
    end
    notify(tr('Assembly requires the saved model and input without temporary parameter overrides. Check the project and clear overrides with P.',
      '装配需要已保存的模型和输入，且不能有临时参数覆盖；请检查项目并用 P 清除覆盖。',
      '裝配需要已儲存的模型和輸入，且不能有暫時參數覆蓋；請檢查專案並用 P 清除覆蓋。'), vim.log.levels.WARN)
    return
  end
  local revision, epoch, project_root = project.config_revision, state.change_epoch or 0, state.opts.project
  local function choose_assembly_value(kind, callback)
    if kind == 'outputs' then
      vim.ui.select({ tr('Native encoder output', '保留编码器原始输出', '保留編碼器原始輸出'),
        tr('Flatten encoder output', '展平编码器输出', '展平編碼器輸出') }, {
        prompt = tr('Choose the encoder output mode; preview validates the result.',
          '选择编码器输出方式；预览将检查结果。', '選擇編碼器輸出方式；預覽將檢查結果。'),
      }, function(_, index) callback(index == 1 and 'native' or (index == 2 and 'flatten' or nil)) end)
      return
    end
    local inputs, seen = {}, {}
    local function add(name, source)
      if identifier_candidate(name) and not seen[name] and #inputs < 64 then
        inputs[#inputs + 1] = { name = name, source = source }; seen[name] = true
      end
    end
    local last = state.last and not state.last.context_changed and state.last.report
    local data = last and last.status == 'success' and last.data
    local origin = type(data) == 'table' and data.origin or nil
    local declared = type(origin) == 'table' and origin.declared_routes or nil
    if type(origin) == 'table' and origin.model == project.model and type(declared) == 'table'
        and declared.status == 'available' and type(declared.routes) == 'table' and is_list(declared.routes) then
      for _, route in ipairs(declared.routes) do
        if type(route) == 'table' then add(route.input, tr('model declaration', '模型声明', '模型宣告')) end
      end
    end
    local starter = state.starter_slots
    if type(starter) == 'table' and starter.model == project.model and type(starter.inputs) == 'table' then
      for _, name in ipairs(starter.inputs) do add(name, tr('creation plan', '创建计划', '建立計畫')) end
    end
    if #inputs == 0 then
      vim.ui.input({ prompt = tr('Named input: ', '具名输入：', '具名輸入：') }, callback); return
    end
    local labels = { tr('Enter another input', '手动输入其他输入名', '手動輸入其他輸入名稱') }
    for _, input in ipairs(inputs) do labels[#labels + 1] = input.name .. ' · ' .. input.source end
    vim.ui.select(labels, { prompt = tr('Input hints only; preview checks the current model.',
      '输入名称仅为提示；预览将检查当前模型。', '輸入名稱僅為提示；預覽將檢查目前模型。') }, function(_, index)
      if not index then callback(nil)
      elseif index == 1 then vim.ui.input({ prompt = tr('Named input: ', '具名输入：', '具名輸入：') }, callback)
      else callback(inputs[index - 1] and inputs[index - 1].name or nil) end
    end)
  end
  local function plan(spec, retry)
    if not project.batch then
      notify(tr('Choose and save a representative input before previewing assembly changes.',
        '预览装配修改前请先选择并保存代表输入。', '預覽裝配修改前請先選擇並儲存代表輸入。'), vim.log.levels.WARN)
      if retry then retry() end
      return
    end
    if state.closed or state.busy or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
        or not state.project_info or state.project_info.config_revision ~= revision then
      notify(tr('Project context changed; prepare assembly again.', '项目上下文已变化，请重新准备装配。', '專案上下文已變更，請重新準備裝配。'), vim.log.levels.WARN); return
    end
    local args, routes, outputs = { 'assembly', 'patch' }, {}, {}
    local needs_direct_factory_params = false
    local function bindings(field, flag, collected)
      local values = spec[field]
      if values == nil then return true end
      if type(values) ~= 'table' then return false end
      local keys = vim.tbl_keys(values)
      table.sort(keys)
      for _, key in ipairs(keys) do
        local value = values[key]
        if not identifier_candidate(key) or type(value) ~= 'string' or value == '' then return false end
        local entry = key .. '=' .. value
        vim.list_extend(args, { flag, entry })
        if collected then collected[#collected + 1] = entry end
      end
      return true
    end
    if not bindings('sets', '--set') or not bindings('routes', '--route', routes)
        or not bindings('outputs', '--encoder-output', outputs) then
      notify('Use object entries with a slot name and nonempty string value.', vim.log.levels.WARN); return
    end
    if spec.remove ~= nil then
      if type(spec.remove) ~= 'table' or not is_list(spec.remove) then notify('Remove must be a list of slots.', vim.log.levels.WARN); return end
      for _, slot in ipairs(spec.remove) do
        if not identifier_candidate(slot) then notify('Invalid slot.', vim.log.levels.WARN); return end
        vim.list_extend(args, { '--remove', slot })
      end
    end
    if spec.params ~= nil then
      if type(spec.params) ~= 'table' then notify('Parameters must be an object.', vim.log.levels.WARN); return end
      local keys = vim.tbl_keys(spec.params)
      table.sort(keys)
      for _, key in ipairs(keys) do
        local param_slot, param_name
        if type(key) == 'string' then param_slot, param_name = key:match('^([^%.]+)%.([^%.]+)$') end
        if not identifier_candidate(param_slot) or not identifier_candidate(param_name) then
          notify('Component parameter names must be SLOT.NAME.', vim.log.levels.WARN); return
        end
        local ok, value = pcall(vim.json.encode, spec.params[key])
        if not ok then notify('Invalid component parameter.', vim.log.levels.WARN); return end
        local slot = key:match('^([^.]+)%.')
        local factory = type(spec.sets) == 'table' and spec.sets[slot] or nil
        if type(factory) == 'string' and not vim.startswith(factory, 'component:') then needs_direct_factory_params = true end
        vim.list_extend(args, { '--param', key .. '=' .. value })
      end
    end
    if #args == 2 then notify('No assembly changes were provided.', vim.log.levels.INFO); return end
    state.busy = tr('Checking assembly capability', '检查装配能力', '檢查裝配能力')
    render(state)
    request(state, { '--describe-interface' }, function(interface, err)
      state.busy = nil
      render(state)
      local caps = interface and interface.data and interface.data.capabilities
      if err or not interface or interface.operation ~= 'interface' or interface.status ~= 'success' or type(caps) ~= 'table'
          or caps['assembly.atomic_patch'] ~= true or caps['assembly.atomic_patch_evidence'] ~= true
          or (needs_direct_factory_params and caps['assembly.direct_factory_params_v1'] ~= true)
          or (#routes > 0 and caps['assembly.atomic_patch_route'] ~= true)
          or (#outputs > 0 and caps['assembly.atomic_patch_encoder_output'] ~= true) then
        notify('This CLI does not support the requested guarded assembly change.', vim.log.levels.WARN)
        if retry then retry() end
        return
      end
      if (state.change_epoch or 0) ~= epoch then notify('Project changed; prepare assembly again.', vim.log.levels.WARN); return end
      run(state, tr('Preview assembly', '预览装配', '預覽裝配'), args, function(report, failure, _, stale, report_buf)
        local data = report and report.data
        if failure or stale or not report or report.operation ~= 'assembly_patch' or report.status ~= 'success'
            or type(data) ~= 'table' or data.committed ~= false or data.base_config_revision ~= revision
            or type(data.validation) ~= 'table' or data.validation.forward ~= 'passed' then
          notify('Assembly preview did not establish a current candidate; nothing saved.', vim.log.levels.WARN)
          if retry then retry() end
          return
        end
        local inspect_ok, review = pcall(vim.inspect, { sets = data.sets, removes = data.removes, model_injections = data.model_injections,
          route_changes = data.route_changes, input_routes = data.input_routes, encoder_outputs = data.encoder_outputs,
          encoder_output_modes = data.encoder_output_modes, validation = data.validation })
        if not inspect_ok or not reviewable_text(review) then
          notify(tr('Assembly preview is too large to approve here.', '装配预览过大，当前界面不能批准。', '裝配預覽過大，目前介面不能批准。'), vim.log.levels.WARN); return
        end
        for _, route in ipairs(routes) do
          local slot, input = route:match('^([^=]+)=(.+)$')
          if type(data.input_routes) ~= 'table' or data.input_routes[slot] ~= input then
            notify('Assembly preview did not confirm the requested route.', vim.log.levels.WARN); return
          end
        end
        for _, output in ipairs(outputs) do
          local slot, mode = output:match('^([^=]+)=(.+)$')
          if type(data.encoder_output_modes) ~= 'table' or data.encoder_output_modes[slot] ~= mode then
            notify('Assembly preview did not confirm the requested output mode.', vim.log.levels.WARN); return
          end
        end
        local source = type(data.source_evidence) == 'table' and data.source_evidence.algorithm == 'canonical-json-sha256-v1'
          and data.source_evidence.digest or nil
        local custom_paths = state.opts.runtime_paths_override == true or state.opts.working_directory ~= nil or state.opts.project_import_roots ~= nil
        local expected_directory = state.opts.working_directory
          or (state.opts.runtime_paths_override and vim.uv.fs_realpath(state.opts.project) or nil)
        local runtime = type(data.runtime_paths) == 'table' and data.runtime_paths or {}
        local directory, roots = runtime.working_directory, runtime.project_import_roots
        if directory == vim.NIL then directory = nil end
        if roots == vim.NIL then roots = nil end
        if custom_paths and (not sha256(source) or data.source_evidence.scope ~= 'worker-recorded-project-sources-and-runtime-paths-v2'
            or directory ~= expected_directory or not vim.deep_equal(roots, state.opts.project_import_roots)) then
          notify(tr('The preview did not confirm the selected runtime paths; it cannot be saved.',
            '预览未确认所选运行时路径，无法保存。', '預覽未確認所選執行階段路徑，無法儲存。'), vim.log.levels.WARN); return
        end
        local input = type(data.input_evidence) == 'table' and data.input_evidence.status == 'available'
          and data.input_evidence.algorithm == 'sha256-forward-input-v1' and data.input_evidence.digest or nil
        local preview = state.last
        local options = { tr('Cancel', '取消', '取消'), tr('Recheck with a new input', '用新输入重验并保存', '用新輸入重驗並儲存') }
        if sha256(input) then options[#options + 1] = tr('Require the same input', '要求相同输入', '要求相同輸入') end
        review_gate(report_buf, options, tr('How should input be handled when saving?',
          '保存时如何处理输入？', '儲存時如何處理輸入？'), function(_, choice)
          if state.closed or state.last ~= preview or (state.change_epoch or 0) ~= epoch then return end
          if not choice or choice == 1 then if retry then retry() end; return end
          local apply = vim.deepcopy(args)
          vim.list_extend(apply, { '--apply', '--if-config-revision', revision })
          if sha256(source) then vim.list_extend(apply, { '--if-source-revision', source }) end
          if choice == 3 and sha256(input) then vim.list_extend(apply, { '--if-input-sha256', input }) end
          local effects = tr('Re-executes project code and saves the assembly configuration after a forward pass.',
            '将重新执行项目代码，在前向通过后保存装配配置。', '將重新執行專案程式碼，在前向通過後儲存裝配設定。')
            .. (sha256(source) and '' or tr(' Source identity is unavailable.', ' 未能固定源码身份。', ' 未能固定原始碼身分。'))
            .. (choice == 2 and tr(' Input may differ from the preview.', ' 输入可能与预览不同。', ' 輸入可能與預覽不同。') or '')
          run(state, tr('Save assembly', '保存装配', '儲存裝配'), apply, function(receipt, failure2)
            local saved = receipt and receipt.data
            if failure2 or not receipt or receipt.status ~= 'success' or receipt.operation ~= 'assembly_patch'
                or type(saved) ~= 'table' or saved.committed ~= true or not sha256(saved.config_revision)
                or saved.base_config_revision ~= revision
                or not vim.deep_equal(saved.model_injections, data.model_injections)
                or not vim.deep_equal(saved.input_routes, data.input_routes)
                or not vim.deep_equal(saved.encoder_output_modes, data.encoder_output_modes)
                or (custom_paths and (type(saved.source_evidence) ~= 'table' or saved.source_evidence.digest ~= source
                  or not vim.deep_equal(saved.runtime_paths, data.runtime_paths)))
                or type(saved.validation) ~= 'table' or saved.validation.forward ~= 'passed' then
              notify('Assembly outcome requires inspection before retrying.', vim.log.levels.WARN)
            else
              if state.assembly_draft and state.assembly_draft.spec == spec then state.assembly_draft = nil end
              state.journey = 'changed'
              refresh_project(state)
            end
          end, effects, true, nil, retry)
        end, retry)
      end, nil, true, nil, retry)
    end)
  end
  local has_draft = state.assembly_draft ~= nil
  local actions = { tr('Connect a component', '接入组件', '接入元件'), tr('Change input route', '更改输入接线', '變更輸入接線'),
    tr('Change encoder output', '更改编码器输出', '變更編碼器輸出'), tr('Edit several changes together', '同时修改多项', '同時修改多項'),
    tr('Generate an editable Python wrapper', '生成可编辑的 Python 适配代码', '產生可編輯的 Python 配接程式碼'),
    tr('Remove a saved component binding', '移除已保存的组件绑定', '移除已儲存的元件繫結'),
    tr('Build several changes step by step', '逐步组合多项修改', '逐步組合多項修改') }
  if has_draft then table.insert(actions, 1, tr('Return to assembly draft', '返回装配草稿', '返回裝配草稿')) end
  vim.ui.select(actions, {
      prompt = tr('What would you like to assemble?', '要装配什么？', '要裝配什麼？'),
    }, function(_, choice)
      if not choice or state.closed then return end
      if has_draft ~= (state.assembly_draft ~= nil) then
        notify(tr('Draft changed; reopen assembly.', '草稿已变化，请重新打开装配。', '草稿已變更，請重新開啟裝配。'), vim.log.levels.WARN); return
      end
      if has_draft then choice = choice == 1 and 7 or choice - 1 end
      if choice == 7 then
        local saved_draft = state.assembly_draft
        local draft = saved_draft and saved_draft.project == project_root and saved_draft.spec
          or { sets = {}, routes = {}, outputs = {}, remove = {}, params = {} }
        local function current()
          return not state.closed and not state.busy and state.opts.project == project_root
            and (state.change_epoch or 0) == epoch and state.project_info
            and state.project_info.config_revision == revision and project_config_current(state)
        end
        local function choose_component(callback)
          local labels = { tr('Enter a slot', '输入接缝', '輸入接縫') }
          local slots, seen = {}, {}
          local function add(slot, source)
            if identifier_candidate(slot) and not seen[slot] and #slots < 64 then
              slots[#slots + 1] = slot; seen[slot] = true; labels[#labels + 1] = slot .. ' · ' .. source
            end
          end
          for _, slot in ipairs(project.saved_slots or {}) do add(slot, tr('saved', '已保存', '已儲存')) end
          local starter = state.starter_slots
          if type(starter) == 'table' and starter.model == project.model and type(starter.slots) == 'table' then
            for _, slot in ipairs(starter.slots) do add(slot, tr('creation plan', '创建计划', '建立計畫')) end
          end
          local last = state.last and not state.last.context_changed and state.last.report
          local data = last and last.status == 'success' and last.data
          local origin = type(data) == 'table' and data.origin or nil
          local declared = type(origin) == 'table' and origin.declared_routes or nil
          if type(origin) == 'table' and origin.model == project.model and type(declared) == 'table'
              and declared.status == 'available' and type(declared.routes) == 'table' and is_list(declared.routes) then
            for _, route in ipairs(declared.routes) do if type(route) == 'table' then add(route.slot, tr('model declaration', '模型声明', '模型宣告')) end end
          end
          local can_inspect = #slots == 0
          if can_inspect then
            labels[#labels + 1] = tr('Inspect model for slot hints', '检查模型以获取接缝提示', '檢查模型以取得接縫提示')
          end
          vim.ui.select(labels, { prompt = tr('Choose a slot', '选择接缝', '選擇接縫') }, function(_, index)
            if not current() then return end
            if not index then callback(nil); return end
            if index == 1 then
              vim.ui.input({ prompt = tr('Slot name: ', '接缝名称：', '接縫名稱：') }, function(slot)
                if not current() then return end
                if not slot then callback(nil); return end
                if not identifier_candidate(slot) then notify(tr('Invalid slot name.', '接缝名称无效。', '接縫名稱無效。'), vim.log.levels.WARN); callback(nil); return end
                callback(slot)
              end)
            elseif can_inspect and index == 2 then
              run(state, tr('Inspect model for assembly slots', '检查模型装配接缝', '檢查模型裝配接縫'),
                { 'model', 'inspect' }, function(report, err, _, stale)
                  if err or stale or not current() or not report or report.operation ~= 'inspect'
                      or report.status ~= 'success' then return end
                  choose_component(callback)
                end)
            else callback(slots[index - 1]) end
          end)
        end
        local edit_draft
        local function view_draft(title, text, options, prompt, callback, on_close)
          local buf = vim.api.nvim_create_buf(false, true)
          vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
          local lines = { title, '' }
          vim.list_extend(lines, vim.split(text, '\n', { plain = true }))
          vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
          vim.bo[buf].modifiable = false
          if not open_aux_buffer(buf, false, false) then if on_close then on_close() end; return end
          vim.keymap.set('n', 'q', function()
            if vim.api.nvim_buf_is_valid(buf) then vim.api.nvim_buf_delete(buf, { force = true }) end
          end, { buffer = buf, silent = true, desc = 'Close assembly draft review' })
          review_gate(buf, options, prompt, callback, function() if on_close then vim.schedule(on_close) end end)
        end
        edit_draft = function()
          if not current() or not state.assembly_draft or state.assembly_draft.spec ~= draft then return end
          render(state)
          local count = #draft.remove + vim.tbl_count(draft.sets) + vim.tbl_count(draft.routes) + vim.tbl_count(draft.outputs)
          vim.ui.select({ tr('Set or replace component', '设置或替换组件', '設定或取代元件'),
            tr('Remove binding', '移除绑定', '移除繫結'), tr('Set input route', '设置输入接线', '設定輸入接線'),
            tr('Set encoder output', '设置编码器输出', '設定編碼器輸出'),
            tr('Review draft', '查看草稿', '檢視草稿'), tr('Preview assembled model', '预览装配后的模型', '預覽裝配後的模型'),
            tr('Remove a draft change', '移除一项草稿修改', '移除一項草稿修改'), tr('Discard draft', '放弃草稿', '放棄草稿') }, {
              prompt = tr('Assembly draft changes: ', '装配草稿修改项：', '裝配草稿修改項：') .. count,
            }, function(_, action)
            if not action or not current() then return end
            if action == 8 then
              if state.assembly_draft and state.assembly_draft.spec == draft then state.assembly_draft = nil end
              render(state)
              return
            end
            if action == 5 then
              local ok, text = pcall(vim.inspect, draft)
              if not ok or not reviewable_text(text) then notify(tr('Draft is too large to review.', '草稿过大，无法查看。', '草稿過大，無法檢視。'), vim.log.levels.WARN); return end
              view_draft(tr('Assembly draft', '装配草稿', '裝配草稿'), text,
                { tr('Continue editing', '继续编辑', '繼續編輯') }, tr('Return to draft?', '返回草稿？', '返回草稿？'),
                function() if current() then edit_draft() end end, edit_draft)
              return
            end
            if action == 6 then
              if count == 0 then notify(tr('The draft is empty.', '草稿为空。', '草稿為空。'), vim.log.levels.INFO); edit_draft(); return end
              plan(draft, edit_draft); return
            end
            if action == 7 then
              local items, labels = {}, {}
              for _, field in ipairs({ 'sets', 'routes', 'outputs' }) do
                for slot in pairs(draft[field]) do items[#items + 1] = { field = field, slot = slot } end
              end
              for _, slot in ipairs(draft.remove) do items[#items + 1] = { field = 'remove', slot = slot } end
              table.sort(items, function(a, b) return a.field == b.field and a.slot < b.slot or a.field < b.field end)
              for _, item in ipairs(items) do labels[#labels + 1] = item.field .. ' · ' .. item.slot end
              if #items == 0 then notify(tr('The draft is empty.', '草稿为空。', '草稿為空。'), vim.log.levels.INFO); edit_draft(); return end
              vim.ui.select(labels, { prompt = tr('Remove which draft change?', '移除哪项草稿修改？', '移除哪項草稿修改？') }, function(_, selected)
                if not current() then return end
                local item = selected and items[selected]
                if item then
                  if item.field == 'remove' then
                    for i = #draft.remove, 1, -1 do if draft.remove[i] == item.slot then table.remove(draft.remove, i) end end
                  else
                    draft[item.field][item.slot] = nil
                    if item.field == 'sets' then
                      for key in pairs(draft.params) do if key:sub(1, #item.slot + 1) == item.slot .. '.' then draft.params[key] = nil end end
                    end
                  end
                end
                edit_draft()
              end)
              return
            end
            choose_component(function(slot)
              if not current() then return end
              if not slot then edit_draft(); return end
              if action == 2 then
                if not vim.tbl_contains(project.saved_slots or {}, slot) then
                  notify(tr('Only a saved binding can be removed; use Remove a draft change to undo a new binding.',
                    '只能移除已保存的绑定；撤销新绑定请使用“移除一项草稿修改”。',
                    '只能移除已儲存的繫結；撤銷新繫結請使用「移除一項草稿修改」。'), vim.log.levels.WARN)
                  edit_draft(); return
                end
                if not vim.tbl_contains(draft.remove, slot) then draft.remove[#draft.remove + 1] = slot end
                draft.sets[slot] = nil
                for key in pairs(draft.params) do if key:sub(1, #slot + 1) == slot .. '.' then draft.params[key] = nil end end
                edit_draft(); return
              end
              if action == 3 or action == 4 then
                choose_assembly_value(action == 3 and 'routes' or 'outputs', function(value)
                  if not current() then return end
                  if value and value ~= '' then draft[action == 3 and 'routes' or 'outputs'][slot] = value end
                  edit_draft()
                end)
                return
              end
              local function accept_factory(value, manifest)
                if not current() then return end
                if not value or value == '' then edit_draft(); return end
                local params_prompt = tr('Factory parameters as JSON (no secrets): ', '工厂参数 JSON（请勿填写密钥）：', '工廠參數 JSON（請勿填寫密鑰）：')
                local schema = type(manifest) == 'table' and manifest.params_schema
                local required = type(schema) == 'table' and schema.required
                local required_hint
                if type(required) == 'table' and is_list(required) then
                  local names = {}
                  for _, name in ipairs(required) do
                    if identifier_candidate(name) then names[#names + 1] = name end
                    if #names >= 32 then break end
                  end
                  if #names > 0 then
                    required_hint = table.concat(names, ', ') .. (#required > 32 and ', …' or '')
                    params_prompt = tr('Required by component: ', '组件必填参数：', '元件必填參數：') .. table.concat(names, ', ')
                      .. (#required > 32 and ', …' or '')
                      .. tr(' · JSON object (no secrets): ', ' · JSON 对象（请勿填写密钥）：', ' · JSON 物件（請勿填寫密鑰）：')
                  end
                end
                local function accept_values(values)
                  if not current() then return end
                  for name in pairs(values) do if not identifier_candidate(name) then notify(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。'), vim.log.levels.WARN); edit_draft(); return end end
                  for key in pairs(draft.params) do if key:sub(1, #slot + 1) == slot .. '.' then draft.params[key] = nil end end
                  for name, parameter in pairs(values) do draft.params[slot .. '.' .. name] = parameter end
                  for i = #draft.remove, 1, -1 do if draft.remove[i] == slot then table.remove(draft.remove, i) end end
                  draft.sets[slot] = value
                  edit_draft()
                end
                local function edit_json()
                  vim.ui.input({ prompt = params_prompt, default = '{}' }, function(raw)
                    if not current() then return end
                    if not raw then edit_draft(); return end
                    local ok, values = pcall(vim.json.decode, raw)
                    if #raw > 65536 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') or vim.tbl_count(values) > 64 then
                      notify(tr('Enter a JSON object of at most 64 parameters and 64 KiB.', '请输入最多 64 项、64 KiB 的 JSON 对象。', '請輸入最多 64 項、64 KiB 的 JSON 物件。'), vim.log.levels.WARN); edit_draft(); return
                    end
                    accept_values(values)
                  end)
                end
                local values = {}
                local edit_one
                local function cancel_parameters()
                  if next(values) == nil then edit_draft(); return end
                  vim.ui.select({ tr('Continue entering parameters', '继续填写参数', '繼續填寫參數'),
                    tr('Discard these parameters', '放弃已填参数', '放棄已填參數') }, {
                      prompt = tr('Parameter entry is not yet in the assembly draft.',
                        '这些参数尚未加入装配草稿。', '這些參數尚未加入裝配草稿。'),
                    }, function(_, choice)
                    if not current() then return end
                    if choice == 2 then edit_draft() else edit_one() end
                  end)
                end
                edit_one = function()
                  if not current() then return end
                  vim.ui.input({ prompt = tr('Parameter name (empty to finish): ', '参数名（留空完成）：', '參數名稱（留空完成）：') }, function(name)
                    if not current() then return end
                    if name == nil then cancel_parameters(); return end
                    if name == '' then accept_values(values); return end
                    if not identifier_candidate(name) or (values[name] == nil and vim.tbl_count(values) >= 64) then
                      notify(tr('Invalid parameter name or too many parameters.', '参数名无效或参数过多。', '參數名稱無效或參數過多。'), vim.log.levels.WARN); edit_one(); return
                    end
                    vim.ui.input({ prompt = tr('Value (JSON or plain text; no secrets): ', '值（JSON 或普通文本，请勿填写密钥）：', '值（JSON 或一般文字，請勿填寫密鑰）：') }, function(raw)
                      if not current() then return end
                      if raw == nil then cancel_parameters(); return end
                      if #raw > 65536 then notify(tr('Value is too large.', '值过大。', '值過大。'), vim.log.levels.WARN); edit_one(); return end
                      local ok, parsed = pcall(vim.json.decode, raw)
                      local previous = values[name]
                      if ok then values[name] = parsed else values[name] = raw end
                      local encoded, serialized = pcall(vim.json.encode, values)
                      if not encoded or #serialized > 65536 then
                        values[name] = previous
                        notify(tr('Parameters exceed the 64 KiB limit.', '参数超过 64 KiB 上限。', '參數超過 64 KiB 上限。'), vim.log.levels.WARN)
                      end
                      edit_one()
                    end)
                  end)
                end
                vim.ui.select({ tr('Enter parameters one by one', '逐项填写参数', '逐項填寫參數'),
                  tr('Enter a JSON object', '填写 JSON 对象', '填寫 JSON 物件'),
                  tr('Use no parameters', '不传参数', '不傳參數') }, {
                    prompt = tr('How would you like to provide factory parameters?', '如何填写工厂参数？', '如何填寫工廠參數？')
                      .. (required_hint and (tr(' Required by component: ', ' 组件必填：', ' 元件必填：') .. required_hint) or ''),
                  }, function(_, method)
                  if not current() then return end
                  if method == 1 then edit_one() elseif method == 2 then edit_json()
                  elseif method == 3 then accept_values({}) else edit_draft() end
                end)
              end
              local prompt = tr('Factory module:callable, component:ID@VERSION, or ? for registered components: ',
                '工厂 module:callable、component:ID@VERSION，或输入 ? 查看已注册组件：',
                '工廠 module:callable、component:ID@VERSION，或輸入 ? 查看已註冊元件：')
              vim.ui.input({ prompt = prompt }, function(value)
                if not current() then return end
                if value ~= '?' then accept_factory(value); return end
                state.busy = tr('Reading registered components', '读取已注册组件', '讀取已註冊元件'); render(state)
                request(state, { 'component', 'list' }, function(report, err)
                  state.busy = nil; render(state)
                  if not current() then return end
                  local components = report and type(report.data) == 'table' and report.data.components
                  if err or not report or report.operation ~= 'component_list' or report.status ~= 'success'
                      or type(components) ~= 'table' or not is_list(components) then
                    notify(tr('Cannot read registered components; enter a factory manually.',
                      '无法读取已注册组件；请手动输入工厂。', '無法讀取已註冊元件；請手動輸入工廠。'), vim.log.levels.WARN)
                    edit_draft(); return
                  end
                  local rows, labels, values, manifests = {}, {}, {}, {}
                  for _, descriptor in ipairs(components) do
                    local manifest = type(descriptor) == 'table' and descriptor.manifest
                    local id = type(manifest) == 'table' and manifest.component_id
                    local version = type(manifest) == 'table' and manifest.component_version
                    local capability = type(manifest) == 'table' and manifest.capabilities
                    if type(id) == 'string' and #id <= 129 and id:match('^[%w_-]+/[%w_-]+$')
                        and type(version) == 'string' and #version <= 64 and version:match('^%d+%.%d+%.%d+$')
                        and manifest.kind == 'layer' and type(capability) == 'table'
                        and type(capability.construct) == 'table' and capability.construct.state == 'supported' then
                      local reference = id .. '@' .. version
                      rows[#rows + 1], values[#values + 1] = { path = reference }, 'component:' .. reference
                      manifests[#manifests + 1] = manifest
                      labels[#labels + 1] = reference .. ' · ' .. vim.fn.strcharpart(tostring(manifest.description or ''):gsub('[%c]', ' '), 0, 160)
                      if #rows >= 2048 then break end
                    end
                  end
                  if #rows == 0 then
                    notify(tr('No registered Layer component declares construction support; enter a factory manually.',
                      '没有已注册 Layer 组件声明支持构造；请手动输入工厂。', '沒有已註冊 Layer 元件宣告支援建構；請手動輸入工廠。'), vim.log.levels.INFO)
                    edit_draft(); return
                  end
                  module_picker(tr('Choose a registered Layer component', '选择已注册的 Layer 组件', '選擇已註冊的 Layer 元件'), rows, labels, function(_, index)
                    if not current() or not values[index] then return end
                    pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false)
                    accept_factory(values[index], manifests[index])
                  end, function() if current() then edit_draft() end end, true)
                end)
              end)
            end)
          end)
        end
        local function bind_and_edit()
          if not current() or state.assembly_draft ~= saved_draft then return end
          state.assembly_draft = { project = project_root, revision = revision, epoch = epoch, spec = draft }
          edit_draft()
        end
        if saved_draft and saved_draft.project ~= project_root then
          vim.ui.select({ tr('Keep other project draft', '保留其他项目的草稿', '保留其他專案的草稿'),
            tr('Discard it and start here', '放弃它并在此开始', '放棄它並在此開始') }, {
              prompt = tr('An assembly draft belongs to another project: ', '已有装配草稿属于另一个项目：', '已有裝配草稿屬於另一個專案：') .. saved_draft.project,
            }, function(_, selected)
              if selected == 2 and current() then bind_and_edit() end
            end)
        elseif saved_draft and (saved_draft.revision ~= revision or saved_draft.epoch ~= epoch) then
          local ok, text = pcall(vim.inspect, draft)
          if not ok or not reviewable_text(text) then
            notify(tr('Existing draft is too large to review; it remains in this session.', '已有草稿过大，无法查看；草稿仍保留在本次会话。', '既有草稿過大，無法檢視；草稿仍保留在本次工作階段。'), vim.log.levels.WARN)
            return
          end
          view_draft(tr('Context changed: review the assembly draft', '上下文已变化：请审核装配草稿', '上下文已變更：請檢視裝配草稿'), text,
            { tr('Keep draft unchanged', '保留草稿', '保留草稿'),
            tr('Use draft with current configuration', '将草稿用于当前配置', '將草稿用於目前設定'),
            tr('Discard draft', '放弃草稿', '放棄草稿') },
            tr('Choose after review; using the draft requires a new preview.', '审核后选择；使用草稿需要重新预览。', '檢視後選擇；使用草稿需要重新預覽。'), function(_, selected)
              if not current() then return end
              if selected == 2 then bind_and_edit()
              elseif selected == 3 and state.assembly_draft == saved_draft then state.assembly_draft = nil; render(state) end
            end)
        else
          bind_and_edit()
        end
        return
      end
      if choice == 5 then
        vim.ui.input({ prompt = tr('New project-relative Python file: ', '项目内新 Python 文件路径：', '專案內新 Python 檔案路徑：'),
          default = 'generated/model_assembly.py' }, function(output)
          if not output or output == '' or state.closed then return end
          if state.busy or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
              or not state.project_info or state.project_info.config_revision ~= revision then
            notify(tr('Project context changed; prepare generation again.', '项目上下文已变化，请重新准备生成。', '專案上下文已變更，請重新準備產生。'), vim.log.levels.WARN); return
          end
          state.busy = tr('Checking generation capability', '检查生成能力', '檢查產生能力'); render(state)
          request(state, { '--describe-interface' }, function(interface, failure)
            state.busy = nil; render(state)
            local caps = interface and interface.data and interface.data.capabilities
            if failure or state.closed or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
                or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
                or type(caps) ~= 'table' or caps['assembly.generate_runtime_paths_v1'] ~= true then
              notify(tr('Generation needs a compatible CLI and unchanged project context.',
                '生成需要兼容的 CLI 和未变化的项目上下文。', '產生需要相容的 CLI 和未變更的專案上下文。'), vim.log.levels.WARN); return
            end
            run(state, tr('Generate assembly code', '生成装配代码', '產生裝配程式碼'),
              { 'assembly', 'generate', '--output', output, '--if-config-revision', revision }, function(report, err, _, stale)
                if not err and not stale and report and report.operation == 'assembly_generate' and report.status == 'success'
                    and type(report.data) == 'table' and report.data.output == output then
                  notify(tr('Generated file is ready; open it with o and review it.',
                    '生成文件已就绪；按 o 打开并检查。', '產生檔案已就緒；按 o 開啟並檢查。'), vim.log.levels.INFO)
                end
              end, tr('Runs project factories and may run a forward pass, then creates a new file without overwriting. Generated code does not contain trained weights.',
                '将执行项目工厂，可能执行前向，然后创建新文件且不覆盖已有文件。生成代码不包含训练权重。',
                '將執行專案工廠，可能執行前向，然後建立新檔案且不覆寫既有檔案。產生程式碼不包含訓練權重。'), true)
          end)
        end)
        return
      end
      if choice == 4 then
        vim.ui.input({ prompt = tr('Changes as JSON: ', '装配修改 JSON：', '裝配修改 JSON：'), default = '{"sets":{},"routes":{},"outputs":{},"remove":[],"params":{}}' }, function(raw)
          if not raw or state.closed then return end
          local ok, spec = pcall(vim.json.decode, raw)
          if not ok or type(spec) ~= 'table' or not raw:match('^%s*{') then notify('Invalid assembly JSON.', vim.log.levels.WARN); return end
          for key in pairs(spec) do
            if not ({ sets = true, routes = true, outputs = true, remove = true, params = true })[key] then
              notify('Unknown assembly field: ' .. tostring(key), vim.log.levels.WARN); return
            end
          end
          plan(spec)
        end)
        return
      end
      local function choose_slot(slot)
        if not slot or slot == '' or state.closed then return end
        if choice == 6 then
          plan({ remove = { slot } })
          return
        end
        if choice == 2 or choice == 3 then
          choose_assembly_value(choice == 2 and 'routes' or 'outputs', function(value)
            if not value or value == '' or state.closed then return end
            plan({ [choice == 2 and 'routes' or 'outputs'] = { [slot] = value } })
          end)
          return
        end
        local prompt = choice == 1 and tr('Factory module:callable or component:ID@VERSION: ', '工厂 module:callable 或 component:ID@VERSION：', '工廠 module:callable 或 component:ID@VERSION：')
          or (choice == 2 and tr('Named input: ', '具名输入：', '具名輸入：') or tr('Output mode (native / flatten): ', '输出方式（native / flatten）：', '輸出方式（native / flatten）：'))
        local function accept_factory(value)
          if not value or value == '' or state.closed then return end
          if choice == 1 then
            vim.ui.input({ prompt = tr('Factory parameters as JSON (recorded and visible in arguments; no secrets): ',
              '工厂参数 JSON（会被记录并出现在进程参数中，请勿填写密钥）：',
              '工廠參數 JSON（會被記錄並出現在程序參數中，請勿填寫密鑰）：'), default = '{}' }, function(raw)
              if raw == nil or state.closed then return end
              local ok, values = pcall(vim.json.decode, raw)
              if #raw > 65536 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') then
                notify(tr('Enter a JSON object of at most 64 KiB.', '请输入不超过 64 KiB 的 JSON 对象。', '請輸入不超過 64 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
              end
              local parameters, count = {}, 0
              for name, parameter in pairs(values) do
                count = count + 1
                if count > 64 or not identifier_candidate(name) then
                  notify(tr('Use at most 64 valid Python parameter names.', '最多填写 64 个有效的 Python 参数名。', '最多填寫 64 個有效的 Python 參數名稱。'), vim.log.levels.WARN); return
                end
                parameters[slot .. '.' .. name] = parameter
              end
              plan({ sets = { [slot] = value }, params = parameters })
            end)
            return
          end
          local field = choice == 1 and 'sets' or (choice == 2 and 'routes' or 'outputs')
          plan({ [field] = { [slot] = value } })
        end
        local function current()
          return not state.closed and not state.busy and state.opts.project == project_root
            and (state.change_epoch or 0) == epoch and state.project_info
            and state.project_info.config_revision == revision and project_config_current(state)
        end
        if preferred_slot and choice == 1 then
          state.busy = tr('Finding component candidates', '查找组件候选', '尋找元件候選')
          render(state)
          find_component_factories(state, function()
            return not state.closed and state.opts.project == project_root
              and (state.change_epoch or 0) == epoch and state.project_info
              and state.project_info.config_revision == revision and project_config_current(state)
          end, function(candidates)
            state.busy = nil
            render(state)
            if not current() then return end
            local labels = { tr('Enter another factory', '手动输入其他工厂', '手動輸入其他工廠') }
            for _, candidate in ipairs(candidates) do labels[#labels + 1] = candidate end
            vim.ui.select(labels, { prompt = tr('Choose a component for ', '选择组件用于 ', '選擇元件用於 ') .. slot
              .. tr(' (candidates not executed)', '（候选尚未执行）', '（候選尚未執行）') }, function(_, index)
              if not current() or not index then return end
              if index == 1 then vim.ui.input({ prompt = prompt }, accept_factory)
              else accept_factory(candidates[index - 1]) end
            end)
          end)
        else
          vim.ui.input({ prompt = prompt }, accept_factory)
        end
      end
      if preferred_slot and identifier_candidate(preferred_slot)
          and (choice == 1 or choice == 2 or choice == 3 or choice == 6) then
        if (choice == 2 or choice == 3) and not preferred_slot:match('_encoder$') then
          notify(tr('Choose an encoder on the canvas to change its input or output mode.',
            '请在画布中选择编码器，再修改输入接线或输出方式。',
            '請在畫布中選擇編碼器，再修改輸入接線或輸出方式。'), vim.log.levels.INFO)
          return
        end
        if choice == 6 and not vim.tbl_contains(project.saved_slots or {}, preferred_slot) then
          notify(tr('This component has no saved binding to remove.',
            '此组件没有可移除的已保存绑定。', '此元件沒有可移除的已儲存繫結。'), vim.log.levels.INFO)
          return
        end
        choose_slot(preferred_slot)
        return
      end
      local slots, seen = {}, {}
      for _, slot in ipairs(project.saved_slots or {}) do
        if not seen[slot] then slots[#slots + 1] = { name = slot, source = tr('saved', '已保存', '已儲存') }; seen[slot] = true end
      end
      if choice == 6 and #slots == 0 then
        notify(tr('No saved component bindings to remove. Model-defined layers can still be edited from the layer menu.',
          '没有可移除的已保存组件绑定。模型自身的层仍可在 Layer 菜单中编辑。',
          '沒有可移除的已儲存元件繫結。模型自身的層仍可在 Layer 選單中編輯。'), vim.log.levels.INFO)
        return
      end
      local last = state.last
      local observed = last and not last.context_changed and last.report
      local data = observed and observed.status == 'success' and observed.data
      local origin = type(data) == 'table' and data.origin or nil
      local declared = type(origin) == 'table' and origin.declared_routes or nil
      if choice ~= 6 and type(origin) == 'table' and origin.model == project.model and type(declared) == 'table'
          and declared.status == 'available' and type(declared.routes) == 'table' and is_list(declared.routes) then
        for _, route in ipairs(declared.routes) do
          local slot = type(route) == 'table' and route.slot or nil
          if identifier_candidate(slot) and not seen[slot] and #slots < 64 then
            slots[#slots + 1] = { name = slot, source = tr('model declaration', '模型声明', '模型宣告') }; seen[slot] = true
          end
        end
      end
      local starter = state.starter_slots
      if choice ~= 6 and type(starter) == 'table' and starter.model == project.model and type(starter.slots) == 'table' then
        for _, slot in ipairs(starter.slots) do
          if not seen[slot] then slots[#slots + 1] = { name = slot, source = tr('starter plan', '骨架计划', '骨架計畫') }; seen[slot] = true end
        end
      end
      if #slots == 0 then
        vim.ui.input({ prompt = tr('Component slot: ', '组件接缝：', '元件接縫：') }, choose_slot)
      else
        local choices = choice == 6 and {} or { tr('Enter another slot', '手动输入其他接缝', '手動輸入其他接縫') }
        for _, slot in ipairs(slots) do choices[#choices + 1] = slot.name .. ' · ' .. slot.source end
        vim.ui.select(choices, { prompt = choice == 6 and tr('Remove binding; preview checks the resulting model',
          '移除绑定；预览将检查修改后的模型', '移除繫結；預覽將檢查修改後的模型') or tr('Slot hints only; preview verifies the current model',
          '接缝仅为提示；当前模型以预览为准', '接縫僅為提示；目前模型以預覽為準') }, function(_, selected)
          if not selected or state.closed then return end
          if choice == 6 and slots[selected] then choose_slot(slots[selected].name)
          elseif selected == 1 then vim.ui.input({ prompt = tr('Component slot: ', '组件接缝：', '元件接縫：') }, choose_slot)
          elseif slots[selected - 1] then choose_slot(slots[selected - 1].name) end
        end)
      end
    end)
end

preview_layer = function(state, selected_path, selected_source)
  if state.busy then notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN); return end
  local preview_epoch = state.change_epoch or 0
  local preview_project, preview_cli = state.opts.project, state.opts.cli
  local preview_revision = state.project_info and state.project_info.config_revision
  local function current()
    if state.closed then return false end
    if state.busy or state.opts.project ~= preview_project or state.opts.cli ~= preview_cli
        or (state.change_epoch or 0) ~= preview_epoch
        or (state.project_info and state.project_info.config_revision) ~= preview_revision
        or not project_config_current(state) then
      notify(tr('Context changed; start the Layer edit again.', '上下文已变化，请重新开始 Layer 编辑。', '上下文已變更，請重新開始 Layer 編輯。'), vim.log.levels.WARN)
      return false
    end
    return true
  end
  local labels = {
    tr('Change parameters', '修改参数', '修改參數'),
    tr('Add layer', '添加层', '新增層'),
    tr('Replace layer', '替换层', '替換層'),
    tr('Remove layer', '删除层', '刪除層'),
    tr('Plan several changes together', '组合多项修改', '組合多項修改'),
    tr('Choose editable fields from the model', '从模型选择可编辑参数', '從模型選擇可編輯參數'),
  }
  if type(selected_path) ~= 'string' or #selected_path > 512 or selected_path:find('[%c]') then selected_path = nil end
  local prompt = tr('Preview source change (no files will be written)', '预览源码修改（不会写文件）', '預覽原始碼修改（不會寫入檔案）')
  if selected_path then prompt = prompt .. ' · ' .. selected_path end
  vim.ui.select(labels, { prompt = prompt }, function(_, choice)
    if not choice or not current() then return end
    if choice == 5 then compose_layer_transaction(state); return end
    if choice == 6 then
      if has_layer_draft(state.layer_draft) then
        compose_layer_transaction(state)
        return
      end
      local report = state.last and state.last.report
      local modules = report and type(report.data) == 'table' and report.data.modules
      if report and report.status == 'success' and not state.last.context_changed
          and type(modules) == 'table' and is_list(modules) then
        guided_parameter_transaction(state, nil, true)
      else
        run(state, tr('Inspect model to choose editable fields', '检查模型以选择可编辑参数', '檢查模型以選擇可編輯參數'),
          { 'model', 'inspect' }, function(result, err, _, stale)
            if err or stale or not result or result.operation ~= 'inspect' or result.status ~= 'success'
                or state.closed or state.opts.project ~= preview_project or state.opts.cli ~= preview_cli
                or (state.change_epoch or 0) ~= preview_epoch then return end
            guided_parameter_transaction(state, nil, true)
          end)
      end
      return
    end
    local function select_path(path)
      if not path or path == '' or not current() then return end
      local args = { 'layer' }
      local selected_signature = nil
      local function preview()
        if not current() then return end
        vim.list_extend(args, { '--target', 'source', '--dry-run' })
        local fallback = type(selected_source) == 'table' and vim.deepcopy(selected_source) or nil
        guarded_layer_preview(state, args, nil, nil, fallback and function()
          local failed_report = state.last
          vim.ui.select({ tr('Review failure report', '查看失败报告', '查看失敗報告'),
            tr('Open recorded source', '打开记录的源码', '開啟記錄的原始碼') }, {
            prompt = tr('No source change was committed. The recorded location may not explain this failure.',
              '没有提交源码修改。记录的位置不一定是失败原因。', '沒有提交原始碼修改。記錄的位置不一定是失敗原因。'),
          }, function(_, choice)
            if choice ~= 2 or state.closed or state.busy or state.last ~= failed_report
                or state.opts.project ~= preview_project or state.opts.cli ~= preview_cli
                or (state.change_epoch or 0) ~= preview_epoch then return end
            open_verified_implementation(state, fallback, true)
          end)
        end or nil)
      end
      local function parameters()
        local prompt = tr('Parameters as a JSON object: ', '参数 JSON 对象：', '參數 JSON 物件：')
        if type(selected_signature) == 'table' and selected_signature.status == 'observed'
            and type(selected_signature.parameters) == 'table' then
          local required, positional_only = {}, false
          for _, param in ipairs(selected_signature.parameters) do
            if type(param) == 'table' and param.required and type(param.name) == 'string' then
              if param.kind == 'POSITIONAL_ONLY' then positional_only = true
              elseif param.kind == 'POSITIONAL_OR_KEYWORD' or param.kind == 'KEYWORD_ONLY' then
                required[#required + 1] = vim.fn.strcharpart(param.name:gsub('[%c]', '?'), 0, 80)
              end
            end
          end
          if positional_only then
            notify(tr('This signature includes required positional-only arguments; the Layer editor sends keyword arguments. Use a custom factory adapter if needed.',
              '签名包含必填的仅位置参数；Layer 编辑器发送关键字参数。需要时请使用自定义工厂适配。',
              '簽章包含必填的僅位置參數；Layer 編輯器傳送關鍵字參數。需要時請使用自訂工廠適配。'), vim.log.levels.WARN)
          end
          if #required > 0 then
            prompt = tr('Required parameters observed: ', '观察到的必填参数：', '觀察到的必填參數：')
              .. table.concat(required, ', ') .. (selected_signature.truncated and ', …' or '')
              .. tr(' · JSON object: ', ' · JSON 对象：', ' · JSON 物件：')
          end
        end
        vim.ui.input({ prompt = prompt, default = '{}' }, function(raw)
          if raw == nil or not current() then return end
          local ok, values = pcall(vim.json.decode, raw)
          if not ok or type(values) ~= 'table' or not raw:match('^%s*{') then
            notify(tr('Enter a JSON object of parameter names and values.', '请输入参数名和值组成的 JSON 对象。', '請輸入參數名稱和值組成的 JSON 物件。'), vim.log.levels.WARN); return
          end
          local names = vim.tbl_keys(values)
          table.sort(names)
          if choice == 1 and #names == 0 then notify('Choose at least one parameter to change.', vim.log.levels.WARN); return end
          for _, name in ipairs(names) do
            if not identifier_candidate(name) then
              notify('Invalid parameter name: ' .. tostring(name), vim.log.levels.WARN); return
            end
            local encoded, value = pcall(vim.json.encode, values[name])
            if not encoded then notify('Cannot encode parameter: ' .. name, vim.log.levels.WARN); return end
            vim.list_extend(args, { '--param', name .. '=' .. value })
          end
          preview()
        end)
      end
      if choice == 1 then
        vim.list_extend(args, { 'set', path })
        parameters()
      elseif choice == 4 then
        vim.ui.select({ tr('Remove from container', '从容器删除', '從容器刪除'), tr('Replace with Identity', '替换为 Identity', '替換為 Identity') }, {
          prompt = tr('Removal strategy', '删除方式', '刪除方式'),
        }, function(_, strategy)
          if not strategy or not current() then return end
          vim.list_extend(args, { 'remove', path, '--strategy', strategy == 2 and 'bypass' or 'remove' })
          preview()
        end)
      else
        local selected_layer = state.layer_catalog_choice
        local function choose_layer(layer_type)
          if not layer_type or layer_type == '' or not current() then return end
          selected_layer = state.layer_catalog_choice
          if selected_layer and selected_layer.epoch == (state.change_epoch or 0)
              and type(selected_layer.current) == 'function' and selected_layer.current() and layer_type == selected_layer.name then
            selected_signature = selected_layer.signature
          end
          if choice == 2 then vim.list_extend(args, { 'add', '--parent', path })
          else vim.list_extend(args, { 'replace', path }) end
          local component = layer_type:match('^component:(.+)$')
          local use_factory = component ~= nil or layer_type:find(':', 1, true) ~= nil
          vim.list_extend(args, { use_factory and '--component' or '--type', component or layer_type })
          if choice ~= 2 then parameters(); return end
          vim.ui.input({ prompt = tr('Child name (empty for automatic): ', '子层名称（留空自动处理）：', '子層名稱（留空自動處理）：') }, function(name)
            if name == nil or not current() then return end
            if name ~= '' then vim.list_extend(args, { '--name', name }) end
            vim.ui.select({ tr('Append', '追加', '附加'), tr('Before a child', '插入子项之前', '插入子項之前'), tr('After a child', '插入子项之后', '插入子項之後') }, {
              prompt = tr('Insertion position', '插入位置', '插入位置'),
            }, function(_, position)
              if not position or not current() then return end
              if position == 1 then parameters(); return end
              vim.ui.input({ prompt = tr('Child name or index: ', '子项名称或索引：', '子項名稱或索引：') }, function(anchor)
                if not anchor or anchor == '' or not current() then return end
                vim.list_extend(args, { position == 2 and '--before' or '--after', anchor })
                parameters()
              end)
            end)
          end)
        end
        vim.ui.input({ prompt = tr('torch.nn class, module:factory, component:ID@VERSION, or ? to discover: ',
          'torch.nn 类名、module:factory、component:ID@VERSION，或输入 ? 发现类型：',
          'torch.nn 類名、module:factory、component:ID@VERSION，或輸入 ? 探索類型：'),
          default = selected_layer and selected_layer.epoch == (state.change_epoch or 0) and selected_layer.name or '' }, function(layer_type)
          if not layer_type or not current() then return end
          if layer_type == '?' then
            discover_layer_classes(state, function(layer) choose_layer(layer.name) end)
          else
            choose_layer(layer_type)
          end
        end)
      end
    end
    if selected_path then select_path(selected_path)
    else vim.ui.input({ prompt = choice == 2 and tr('Parent module path: ', '父容器路径：', '父容器路徑：') or tr('Module path: ', '模块路径：', '模組路徑：'), default = state.last_selection or '' }, select_path) end
  end)
end

guided_parameter_transaction = function(state, saved_draft, start_with_selection)
  local listed, epoch = state.last, state.change_epoch or 0
  local report = listed and listed.report
  local modules = report and type(report.data) == 'table' and report.data.modules or nil
  if not report or report.status ~= 'success' or listed.context_changed or type(modules) ~= 'table' or not is_list(modules) then
    notify(tr('Inspect the current model first to choose editable fields.', '请先检查当前模型，再选择可编辑参数。', '請先檢查目前模型，再選擇可編輯參數。'), vim.log.levels.INFO); return
  end
  local rows, labels, seen = {}, {}, {}
  for _, row in ipairs(modules) do
    if type(row) == 'table' and type(row.path) == 'string' and row.path ~= '' and not seen[row.path]
        and row.can_source_set == true and type(row.source_editable_fields) == 'table' and #row.source_editable_fields > 0 then
      rows[#rows + 1], labels[#labels + 1], seen[row.path] = row,
        row.path .. ' · ' .. tostring(row.type or '?'), true
      if #rows >= 2048 then break end
    end
  end
  if #rows == 0 then
    notify(tr('No editable constructor fields were reported. You can still draft structural changes; the backend will check whether each change is supported.',
      '报告没有可编辑的构造参数，仍可草拟结构修改；后端会逐项检查是否支持。',
      '報告沒有可編輯的建構參數，仍可草擬結構修改；後端會逐項檢查是否支援。'), vim.log.levels.INFO)
  end
  local draft = saved_draft or { project = state.opts.project, model = state.model or (state.project_info and state.project_info.model), operations = {}, structures = {} }
  local operations, structures, by_path = draft.operations, draft.structures, {}
  for _, operation in ipairs(operations) do by_path[operation.path] = operation end
  local function current()
    return not state.closed and not state.busy and not state.pending_source and state.last == listed
      and state.opts.project == draft.project and (state.layer_draft == nil or state.layer_draft == draft)
      and not listed.context_changed and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  local function remember()
    if #operations + #structures > 0 then state.layer_draft = draft
    elseif state.layer_draft == draft then state.layer_draft = nil end
    render(state)
  end
  local function changed_draft()
    if draft.status == 'applied' then draft.status = 'modified_after_applied'
    elseif draft.status == 'preview_ready' then draft.status = 'draft' end
  end
  local choose_module, review_draft, add_structure
  local function next_action()
    if not current() then return end
    remember()
    vim.ui.select({ tr('Add another parameter', '继续添加参数', '繼續新增參數'),
      tr('Add a structural change', '添加结构修改', '新增結構修改'),
      tr('Review or remove a draft item', '查看或移除草稿项', '查看或移除草稿項'),
      tr('Preview all changes', '预览全部修改', '預覽全部修改'), tr('Cancel', '取消', '取消') }, {
      prompt = tr('Parameters apply before structural changes. Layers / structural operations: ',
        '参数先于结构修改执行。参数层数 / 结构操作数：', '參數先於結構修改執行。參數層數 / 結構操作數：') .. #operations .. ' / ' .. #structures,
    }, function(_, index)
      if not current() then return end
      if index == 1 then choose_module()
      elseif index == 2 then add_structure()
      elseif index == 3 then review_draft()
      elseif index == 4 then
        if #operations + #structures == 0 then
          notify(tr('Add at least one change before preview.', '请先添加至少一项修改再预览。', '請先新增至少一項修改再預覽。'), vim.log.levels.INFO)
          next_action(); return
        end
        local args = { 'layer', 'apply' }
        for _, operation in ipairs(operations) do
          local ok, encoded = pcall(vim.json.encode, operation)
          if not ok then notify('Cannot encode layer operation.', vim.log.levels.WARN); return end
          vim.list_extend(args, { '--operation', encoded })
        end
        for _, operation in ipairs(structures) do
          local ok, encoded = pcall(vim.json.encode, operation)
          if not ok then notify('Cannot encode layer operation.', vim.log.levels.WARN); return end
          vim.list_extend(args, { '--operation', encoded })
        end
        vim.list_extend(args, { '--target', 'source', '--dry-run' })
        guarded_layer_preview(state, args, #operations > 0 and #structures > 0, draft)
      end
    end)
  end
  review_draft = function()
    if not current() then return end
    remember()
    local items, item_labels = {}, {}
    for _, operation in ipairs(operations) do
      local names = vim.tbl_keys(operation.params)
      table.sort(names)
      for _, name in ipairs(names) do
        local ok, encoded = pcall(vim.json.encode, operation.params[name])
        if not ok then notify('Cannot encode draft parameter.', vim.log.levels.WARN); return end
        items[#items + 1] = { operation = operation, name = name, encoded = encoded }
        item_labels[#item_labels + 1] = operation.path .. ' · ' .. name .. ' = '
          .. vim.fn.strcharpart(encoded:gsub('[\r\n%z\1-\31\127]', ' '), 0, 160)
      end
    end
    for position, operation in ipairs(structures) do
      local ok, encoded = pcall(vim.json.encode, operation)
      if not ok then notify('Cannot encode draft operation.', vim.log.levels.WARN); return end
      items[#items + 1] = { structural = true, position = position, encoded = encoded }
      item_labels[#item_labels + 1] = tr('Structure: ', '结构：', '結構：')
        .. vim.fn.strcharpart(encoded:gsub('[\r\n%z\1-\31\127]', ' '), 0, 280)
    end
    if #items == 0 then choose_module(); return end
    vim.ui.select(item_labels, { prompt = tr('Choose a draft item to edit or remove', '选择要修改或移除的草稿项', '選擇要修改或移除的草稿項') }, function(_, index)
      local item = index and items[index]
      if not current() then return end
      if not item then next_action(); return end
      if item.structural then
        vim.ui.select({ tr('Remove operation', '移除此操作', '移除此操作'), tr('Back', '返回', '返回') }, {
          prompt = item_labels[index],
        }, function(_, action)
          if not current() then return end
          if action == 1 then table.remove(structures, item.position); changed_draft() end
          remember()
          if #operations + #structures == 0 then choose_module() else review_draft() end
        end)
        return
      end
      vim.ui.select({ tr('Edit value', '修改值', '修改值'), tr('Remove item', '移除此项', '移除此項'), tr('Back', '返回', '返回') }, {
        prompt = item.operation.path .. ' · ' .. item.name,
      }, function(_, action)
        if not current() then return end
        if action == 1 then
          vim.ui.input({ prompt = tr('New JSON value (no secrets): ', '新 JSON 值（请勿填写密钥）：', '新 JSON 值（請勿填寫金鑰）：'), default = item.encoded }, function(raw)
            if not current() then return end
            if raw == nil then review_draft(); return end
            local ok, value = pcall(vim.json.decode, raw)
            if #raw > 16384 or not ok then
              notify(tr('Enter a valid JSON value up to 16 KiB.', '请输入不超过 16 KiB 的有效 JSON 值。', '請輸入不超過 16 KiB 的有效 JSON 值。'), vim.log.levels.WARN)
              review_draft(); return
            end
            item.operation.params[item.name] = value
            changed_draft()
            review_draft()
          end)
        elseif action == 2 then
          item.operation.params[item.name] = nil
          changed_draft()
          if not next(item.operation.params) then
            by_path[item.operation.path] = nil
            for position, operation in ipairs(operations) do
              if operation == item.operation then table.remove(operations, position); break end
            end
          end
          remember()
          if #operations + #structures == 0 then choose_module() else review_draft() end
        else
          review_draft()
        end
      end)
    end)
  end
  add_structure = function()
    if not current() then return end
    if #operations + #structures >= 64 then
      notify(tr('A plan can contain at most 64 operations.', '计划最多包含 64 项操作。', '計畫最多包含 64 項操作。'), vim.log.levels.WARN)
      next_action(); return
    end
    vim.ui.select({ tr('Add a layer', '添加层', '新增層'), tr('Replace a layer', '替换层', '取代層'),
      tr('Remove or bypass a layer', '删除或旁路层', '刪除或旁路層') }, {
      prompt = tr('Structural change', '结构修改', '結構修改'),
    }, function(_, choice)
      if not current() then return end
      if not choice then next_action(); return end
      local action = ({ 'add', 'replace', 'remove' })[choice]
      local function choose_path(callback)
        local choices = { tr('Enter a path (including a layer added in this draft)',
          '手动输入路径（包括草稿中新添加的层）', '手動輸入路徑（包括草稿中新新增的層）') }
        local paths, seen = {}, {}
        for _, row in ipairs(modules) do
          if type(row) == 'table' and type(row.path) == 'string' and row.path ~= '' and not seen[row.path]
              and (action ~= 'add' or row.can_source_insert == true) then
            paths[#paths + 1], seen[row.path] = row.path, true
            choices[#choices + 1] = row.path .. ' · ' .. tostring(row.type or '?')
            if #paths >= 2048 then break end
          end
        end
        local function enter_path()
          vim.ui.input({ prompt = action == 'add' and tr('Parent container path: ', '父容器路径：', '父容器路徑：')
            or tr('Layer path: ', '层路径：', '層路徑：'), default = state.last_selection or '' }, callback)
        end
        if #paths == 0 then enter_path(); return end
        vim.ui.select(choices, { prompt = tr('Choose an observed path; preview verifies the change',
          '选择观察到的路径；预览时检查修改', '選擇觀察到的路徑；預覽時檢查修改') }, function(_, index)
          if not current() then return end
          if not index then next_action()
          elseif index == 1 then enter_path()
          else callback(paths[index - 1]) end
        end)
      end
      choose_path(function(path)
        if not current() then return end
        if not path or path == '' then next_action(); return end
        local operation = { action = action }
        if action == 'add' then operation.parent = path else operation.path = path end
        local function push()
          if not current() then return end
          structures[#structures + 1] = operation
          changed_draft()
          state.last_selection = path
          next_action()
        end
        if action == 'remove' then
          vim.ui.select({ tr('Remove from container', '从容器删除', '從容器刪除'), tr('Replace with Identity', '替换为 Identity', '取代為 Identity') }, {
            prompt = tr('Removal strategy', '删除方式', '刪除方式'),
          }, function(_, strategy)
            if not current() then return end
            if not strategy then next_action(); return end
            operation.strategy = strategy == 2 and 'bypass' or 'remove'
            push()
          end)
          return
        end
        local function choose_layer(layer_type)
          if not current() then return end
          if not layer_type or layer_type == '' then next_action(); return end
          local component = layer_type:match('^component:(.+)$')
          if component or layer_type:find(':', 1, true) then operation.component = component or layer_type
          else operation.layer_type = layer_type end
          local function ask_parameters()
            vim.ui.input({ prompt = tr('Constructor parameters as JSON (no secrets): ', '构造参数 JSON（请勿填写密钥）：', '建構參數 JSON（請勿填寫金鑰）：'), default = '{}' }, function(raw)
              if not current() then return end
              if raw == nil then next_action(); return end
              local ok, params = pcall(vim.json.decode, raw)
              if #raw > 16384 or not ok or type(params) ~= 'table' or not raw:match('^%s*{') then
                notify(tr('Enter a JSON object up to 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN)
                next_action(); return
              end
              operation.params = next(params) and params or vim.empty_dict()
              push()
            end)
          end
          if action ~= 'add' then ask_parameters(); return end
          vim.ui.input({ prompt = tr('Child name (empty for automatic): ', '子层名称（留空自动处理）：', '子層名稱（留空自動處理）：'), default = '' }, function(name)
            if not current() then return end
            if name == nil then next_action(); return end
            if name ~= '' then operation.name = name end
            vim.ui.select({ tr('Append', '追加', '附加'), tr('Before a child', '插入子项之前', '插入子項之前'), tr('After a child', '插入子项之后', '插入子項之後') }, {
              prompt = tr('Insertion position', '插入位置', '插入位置'),
            }, function(_, position)
              if not current() then return end
              if not position then next_action(); return end
              if position == 1 then ask_parameters(); return end
              vim.ui.input({ prompt = tr('Child name or index: ', '子项名称或索引：', '子項名稱或索引：') }, function(anchor)
                if not current() then return end
                if not anchor or anchor == '' then next_action(); return end
                if position == 2 then operation.before = anchor else operation.after = anchor end
                ask_parameters()
              end)
            end)
          end)
        end
        vim.ui.input({ prompt = tr('Layer type, factory, component:ID@VERSION, or ? to discover: ',
          '层类型、工厂、component:ID@VERSION，或输入 ? 发现类型：', '層類型、工廠、component:ID@VERSION，或輸入 ? 探索類型：') }, function(layer_type)
          if not current() then return end
          if layer_type ~= '?' then choose_layer(layer_type); return end
          local previous = listed
          discover_layer_classes(state, function(layer)
            -- Discovery is a separate confirmed operation and replaces the
            -- latest report. Preserve the draft only if both its original
            -- inspection and the discovery still match the same context.
            if state.closed or state.busy or state.opts.project ~= draft.project
                or (state.change_epoch or 0) ~= epoch or previous.context_changed
                or not state.last or state.last.context_changed
                or (state.layer_draft ~= nil and state.layer_draft ~= draft)
                or not project_config_current(state) then return end
            listed = state.last
            choose_layer(layer.name)
          end)
        end)
      end)
    end)
  end
  choose_module = function()
    if not current() then return end
    if #rows == 0 then
      notify(tr('No editable constructor fields were reported.', '报告未提供可编辑的构造参数。', '報告未提供可編輯的建構參數。'), vim.log.levels.INFO)
      next_action(); return
    end
    module_picker(tr('Choose a layer for this parameter plan', '选择参数计划中的层', '選擇參數計畫中的層'), rows, labels, function(_, index)
      local row = index and rows[index]
      if not row or not current() then return end
      -- The picker is a temporary split; close it before asking for the value
      -- so repeated additions do not accumulate windows.
      pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false)
      local fields, field_labels = {}, {}
      local values = type(row.editable_params) == 'table' and row.editable_params or {}
      local existing = by_path[row.path]
      for _, name in ipairs(row.source_editable_fields) do
        if identifier_candidate(name) then
          local value = existing and existing.params[name]
          if value == nil then value = values[name] end
          local ok, encoded = pcall(vim.json.encode, value)
          fields[#fields + 1] = { name = name, default = value ~= nil and ok and encoded or '' }
          field_labels[#field_labels + 1] = name .. ' · ' .. (value ~= nil and ok and vim.fn.strcharpart(encoded:gsub('[\r\n%z\1-\31\127]', ' '), 0, 120) or tr('unknown', '未知', '未知'))
          if #fields >= 64 then break end
        end
      end
      vim.ui.select(field_labels, { prompt = row.path }, function(_, field_index)
        local field = field_index and fields[field_index]
        if not current() then return end
        if not field then if #operations + #structures > 0 then next_action() else choose_module() end; return end
        vim.ui.input({ prompt = tr('New JSON value (visible in process arguments; no secrets): ',
          '新 JSON 值（会出现在进程参数中，请勿填写密钥）：', '新 JSON 值（會出現在程序參數中，請勿填寫金鑰）：'), default = field.default }, function(raw)
          if not current() then return end
          if raw == nil then if #operations + #structures > 0 then next_action() else choose_module() end; return end
          local decoded, value = pcall(vim.json.decode, raw)
          if #raw > 16384 or not decoded then
            notify(tr('Enter a valid JSON value up to 16 KiB.', '请输入不超过 16 KiB 的有效 JSON 值。', '請輸入不超過 16 KiB 的有效 JSON 值。'), vim.log.levels.WARN)
            if #operations + #structures > 0 then next_action() else choose_module() end; return
          end
          local operation = by_path[row.path]
          if not operation then
            if #operations + #structures >= 64 then notify(tr('A plan can contain at most 64 operations.', '计划最多包含 64 项操作。', '計畫最多包含 64 項操作。'), vim.log.levels.WARN); next_action(); return end
            operation = { action = 'set', path = row.path, params = {} }
            by_path[row.path], operations[#operations + 1] = operation, operation
          end
          operation.params[field.name] = value
          changed_draft()
          state.last_selection = row.path
          next_action()
        end)
      end)
    end, function()
      if current() and #operations + #structures > 0 then next_action() end
    end, true)
  end
  if start_with_selection and #rows > 0 and #operations + #structures == 0 then
    choose_module()
  else
    next_action()
  end
end

compose_layer_transaction = function(state, template)
  if state.busy or state.pending_source then
    notify(tr('Finish the current operation or preview first.', '请先完成当前操作或预览。', '請先完成目前操作或預覽。'), vim.log.levels.WARN)
    return
  end
  if state.layer_draft and not has_layer_draft(state.layer_draft) then state.layer_draft = nil end
  if not template and has_layer_draft(state.layer_draft) then
    local draft, project, epoch = state.layer_draft, state.opts.project, state.change_epoch or 0
    vim.ui.select({ tr('Continue draft', '继续草稿', '繼續草稿'), tr('View draft', '查看草稿', '檢視草稿'),
      tr('Discard draft', '放弃草稿', '放棄草稿'), tr('Back', '返回', '返回') }, {
      prompt = tr('Layer draft project: ', 'Layer 草稿项目：', 'Layer 草稿專案：') .. draft.project
        .. ' · ' .. (({ applied = tr('applied; recheck before reuse', '已应用；复用前需重验', '已套用；重用前須重新驗證'),
          modified_after_applied = tr('modified after an applied version', '上次应用后已修改', '上次套用後已修改'),
          outcome_unknown = tr('save outcome unknown', '保存结果未知', '儲存結果未知'),
          preview_ready = tr('previewed', '已预览', '已預覽') })[draft.status] or tr('draft', '草稿', '草稿')),
    }, function(_, choice)
      if state.closed or state.busy or state.layer_draft ~= draft or state.opts.project ~= project
          or (state.change_epoch or 0) ~= epoch then return end
      if choice == 1 then
        if project ~= draft.project then
          notify(tr('Return to the draft project before continuing.', '请先切回草稿所属项目。', '請先切回草稿所屬專案。'), vim.log.levels.WARN); return
        end
        local reviewed = vim.deepcopy({ draft.operations, draft.structures })
        local inspected = state.last
        local original = tostring(draft.model or '?'):gsub('[%c]', ' ')
        local selected = tostring(state.model or (state.project_info and state.project_info.model) or '?'):gsub('[%c]', ' ')
        local outcome_warning = draft.status == 'applied'
          and tr('This draft was already applied; repeating it may apply the change again. ', '此草稿已经应用；再次执行可能重复修改。', '此草稿已經套用；再次執行可能重複修改。')
          or (draft.status == 'modified_after_applied' and tr('An earlier version was applied; inspect the current source before continuing. ', '此草稿的先前版本已经应用；继续前请检查当前源码。', '此草稿的先前版本已經套用；繼續前請檢查目前原始碼。')
          or (draft.status == 'outcome_unknown' and tr('The previous save outcome is unknown; inspect files before retrying. ', '上次保存结果未知，请检查文件后再重试。', '上次儲存結果未知，請檢查檔案後再重試。') or ''))
        vim.ui.select({ tr('Review against current model', '基于当前模型审核', '根據目前模型檢視'), tr('Cancel', '取消', '取消') }, {
          prompt = outcome_warning .. tr('Original / current model: ', '原模型 / 当前模型：', '原模型 / 目前模型：') .. original .. ' / ' .. selected
            .. tr('. Inspect the current model first; preview checks the current source again.',
              '。请先检查当前模型；预览会重新核对当前源码。', '。請先檢查目前模型；預覽會重新核對目前原始碼。'),
        }, function(_, confirm)
          if confirm ~= 1 or state.closed or state.busy or state.layer_draft ~= draft or state.last ~= inspected
              or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
              or not vim.deep_equal(reviewed, { draft.operations, draft.structures }) then return end
          local report = inspected and inspected.report
          local modules = report and type(report.data) == 'table' and report.data.modules
          if report and report.status == 'success' and not inspected.context_changed and type(modules) == 'table' and is_list(modules) then
            guided_parameter_transaction(state, draft)
            return
          end
          run(state, tr('Inspect current model for Layer draft', '检查当前模型以继续 Layer 草稿', '檢查目前模型以繼續 Layer 草稿'),
            { 'model', 'inspect' }, function(result, err, _, stale)
              if err or stale or not result or result.operation ~= 'inspect' or result.status ~= 'success'
                  or state.closed or state.layer_draft ~= draft or state.opts.project ~= project
                  or (state.change_epoch or 0) ~= epoch
                  or not vim.deep_equal(reviewed, { draft.operations, draft.structures }) then return end
              guided_parameter_transaction(state, draft)
            end)
        end)
      elseif choice == 2 then
        local ok, encoded = pcall(vim.inspect, { project = draft.project, model = draft.model, status = draft.status or 'draft', operations = draft.operations, structures = draft.structures })
        if not ok then notify(tr('Cannot display draft.', '无法显示草稿。', '無法顯示草稿。'), vim.log.levels.WARN); return end
        local buf = vim.api.nvim_create_buf(false, true)
        vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
        vim.api.nvim_buf_set_lines(buf, 0, -1, false, vim.split(encoded, '\n', { plain = true }))
        vim.bo[buf].modifiable = false
        if not open_aux_buffer(buf, false, false) then return end
        vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close draft review' })
      elseif choice == 3 then
        local reviewed = vim.deepcopy({ draft.operations, draft.structures })
        vim.ui.select({ tr('Keep draft', '保留草稿', '保留草稿'), tr('Discard draft', '放弃草稿', '放棄草稿') }, {
          prompt = tr('Discard this session-only Layer draft?', '放弃仅存于本会话的 Layer 草稿？', '放棄僅存於本工作階段的 Layer 草稿？'),
        }, function(_, confirm)
          if confirm == 2 and not state.closed and not state.busy and state.layer_draft == draft
              and state.opts.project == project and (state.change_epoch or 0) == epoch
              and vim.deep_equal(reviewed, { draft.operations, draft.structures }) then state.layer_draft = nil; render(state) end
        end)
      end
    end)
    return
  end
  if not template then
    vim.ui.select({
      tr('Guided parameter and layer changes', '引导式参数与层修改', '引導式參數與層修改'),
      tr('Change parameters together', '同时修改多个层的参数', '同時修改多個層的參數'),
      tr('Add, replace or remove layers together', '同时添加、替换或删除层', '同時新增、替換或刪除層'),
      tr('Combine parameter and structure changes', '组合参数和结构修改', '組合參數和結構修改'),
    }, { prompt = tr('Choose a batch plan template', '选择批量计划模板', '選擇批次計畫範本') }, function(_, choice)
      if choice == 1 and not state.closed then guided_parameter_transaction(state)
      elseif choice and not state.closed then compose_layer_transaction(state, choice - 1) end
    end)
    return
  end
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype = 'acwrite'
  vim.bo[buf].bufhidden = 'hide'
  vim.bo[buf].swapfile = false
  vim.api.nvim_buf_set_name(buf, 'model-maven://layer-plan/' .. buf)
  local selected_path = type(state.last_selection) == 'string' and #state.last_selection <= 512
    and not state.last_selection:find('[%c]') and state.last_selection:match('^model[%.%[]')
    and state.last_selection or 'model.encoder.proj'
  local selected_json = vim.json.encode(selected_path)
  local examples = template == 1 and {
    '[',
    '  {"action": "set", "path": ' .. selected_json .. ', "params": {"out_features": 128}},',
    '  {"action": "set", "path": "model.head", "params": {"in_features": 128}}',
    ']',
  } or template == 2 and {
    '[',
    '  {"action": "add", "parent": ' .. selected_json .. ', "name": "activation", "layer_type": "ReLU", "params": {}},',
    '  {"action": "replace", "path": "model.encoder.output", "layer_type": "Linear", "params": {"in_features": 128, "out_features": 64}}',
    ']',
  } or {
    '[',
    '  {"action": "set", "path": ' .. selected_json .. ', "params": {"out_features": 128}},',
    '  {"action": "replace", "path": "model.head.0", "layer_type": "Linear", "params": {"in_features": 128, "out_features": 64}}',
    ']',
  }
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, examples)
  vim.bo[buf].filetype = 'json'
  vim.bo[buf].modified = false
  -- This buffer can outlive the panel and even a project switch. A plan is
  -- never silently retargeted to whichever model happens to be current.
  local plan_project, plan_epoch = state.opts.project, state.change_epoch or 0
  local draft_state = state
  vim.api.nvim_create_autocmd('BufWriteCmd', {
    buffer = buf,
    callback = function()
      local active = draft_state
      if active.closed then
        local reopened = sessions[vim.fs.normalize(plan_project)]
        if not reopened or reopened.closed then
          notify(tr('Reopen the original project workspace, then write this draft again.',
            '请重新打开原项目工作区，再次写入此草稿。', '請重新開啟原專案工作區，再次寫入此草稿。'), vim.log.levels.WARN)
          return
        end
        local epoch = reopened.change_epoch or 0
        local model = reopened.model or (reopened.project_info and reopened.project_info.model)
          or tr('not selected', '未选择', '未選擇')
        vim.ui.select({ tr('Keep draft unchanged', '保留草稿', '保留草稿'),
          tr('Use reopened workspace', '使用重新打开的工作区', '使用重新開啟的工作區') }, {
          prompt = tr('Review the reopened context before reconnecting the draft:',
            '重新连接草稿前请核对工作区上下文：', '重新連接草稿前請核對工作區上下文：')
            .. '\n' .. tr('Project: ', '项目：', '專案：') .. plan_project
            .. '\n' .. tr('Model: ', '模型：', '模型：') .. tostring(model),
        }, function(_, choice)
          if choice ~= 2 or reopened.closed or reopened.busy or reopened.pending_source
              or sessions[vim.fs.normalize(plan_project)] ~= reopened
              or (reopened.change_epoch or 0) ~= epoch or not project_config_current(reopened)
              or not vim.api.nvim_buf_is_valid(buf) then return end
          draft_state, plan_epoch = reopened, epoch
          notify(tr('Draft reconnected; review it and use :write again to preview.',
            '草稿已重新连接；请检查后再次使用 :write 预览。', '草稿已重新連接；請檢查後再次使用 :write 預覽。'), vim.log.levels.INFO)
        end)
        return
      end
      if active.busy or active.pending_source then
        notify(tr('Finish the current operation or reopen the workspace.', '请先完成当前操作或重新打开工作区。', '請先完成目前操作或重新開啟工作區。'), vim.log.levels.WARN)
        return
      end
      if active.opts.project ~= plan_project or (active.change_epoch or 0) ~= plan_epoch then
        local project, epoch = active.opts.project, active.change_epoch or 0
        local model = active.model or (active.project_info and active.project_info.model)
          or tr('not selected', '未选择', '未選擇')
        vim.ui.select({ tr('Keep draft; do not retarget', '保留草稿，不切换目标', '保留草稿，不切換目標'),
          tr('Use current context for this draft', '将草稿用于当前上下文', '將草稿用於目前上下文') }, {
          prompt = tr('Draft context changed. Review project and model before choosing:',
            '草稿上下文已变化。请选择前先核对项目和模型：', '草稿上下文已變更。請選擇前先核對專案和模型：')
            .. '\n' .. tr('Project: ', '项目：', '專案：') .. project
            .. '\n' .. tr('Model: ', '模型：', '模型：') .. tostring(model),
        }, function(_, choice)
          if choice ~= 2 or active.closed or active.busy or active.pending_source
              or active.opts.project ~= project or (active.change_epoch or 0) ~= epoch
              or not vim.api.nvim_buf_is_valid(buf) or not project_config_current(active) then return end
          plan_project, plan_epoch = project, epoch
          notify(tr('Draft retargeted; review it and use :write again to preview.',
            '草稿已切换目标；请检查后再次使用 :write 预览。', '草稿已切換目標；請檢查後再次使用 :write 預覽。'), vim.log.levels.INFO)
        end)
        return
      end
      local raw = table.concat(vim.api.nvim_buf_get_lines(buf, 0, -1, false), '\n')
      local ok, operations = pcall(vim.json.decode, raw)
      if #raw > 262144 or not ok or not raw:match('^%s*%[') or type(operations) ~= 'table'
          or not is_list(operations) or #operations < 1 or #operations > 64 then
        notify(tr('Enter a JSON array of 1–64 operations, at most 256 KiB.', '请输入包含 1–64 项、最多 256 KiB 的 JSON 操作数组。', '請輸入包含 1–64 項、最多 256 KiB 的 JSON 操作陣列。'), vim.log.levels.WARN)
        return
      end
      local args, saw_set, saw_structure = { 'layer', 'apply' }, false, false
      for _, operation in ipairs(operations) do
        local action = type(operation) == 'table' and operation.action or nil
        local current = action == 'set' and 'set'
          or ((action == 'add' or action == 'replace' or action == 'remove') and 'structure' or nil)
        if not current or (current == 'set' and saw_structure) then
          notify(tr('List all set operations before add/replace/remove operations.', '请先列出所有 set，再列出 add/replace/remove。', '請先列出所有 set，再列出 add/replace/remove。'), vim.log.levels.WARN)
          return
        end
        if current == 'set' then saw_set = true else saw_structure = true end
        local encoded, value = pcall(vim.json.encode, operation)
        if not encoded then notify('Cannot encode layer operation.', vim.log.levels.WARN); return end
        vim.list_extend(args, { '--operation', value })
      end
      vim.list_extend(args, { '--target', 'source', '--dry-run' })
      guarded_layer_preview(active, args, saw_set and saw_structure)
    end,
  })
  if not open_aux_buffer(buf, false, true) then return end
  notify(tr('Example only: replace paths and values, then :write to preview. This draft is held in memory; source changes require confirmation.',
    '这是示例：替换路径和值，执行 :write 预览。草稿仅保存在内存中；源码修改需要确认。',
    '這是範例：替換路徑和值，執行 :write 預覽。草稿僅保存在記憶體中；原始碼修改需要確認。'), vim.log.levels.INFO)
end

-- Alias paths are model identities, so preserve each recorded choice instead
-- of silently substituting the first alias for shared modules.
local function observed_port_choices(calls, preferred_path)
  local rows, labels, seen, truncated = {}, {}, {}, false
  for _, call in ipairs(calls) do
    local paths = type(call) == 'table' and call.paths
    local ports = type(call) == 'table' and call.input_output_paths
    local impl = type(call) == 'table' and call.implementation
    if type(paths) == 'table' and type(ports) == 'table' and type(impl) == 'table'
        and type(impl.source_file) == 'string' and impl.source_file ~= ''
        and (impl.source_file:sub(1, 1) ~= '@' or vim.startswith(impl.source_file, '@external:'))
        and sha256(impl.source_sha256) and type(impl.qualified_type) == 'string' and impl.qualified_type ~= '' then
      local selected = preferred_path and (vim.tbl_contains(paths, preferred_path) and { preferred_path } or {}) or paths
      for path_index, path in ipairs(selected) do
        if path_index > 128 then truncated = true; break end
        if type(path) == 'string' then
          for port_index, port in ipairs(ports) do
            if port_index > 128 then truncated = true; break end
            if type(port) == 'string' and (port:match('^outputs') or port:match('^inputs')) then
              local key = path .. '\0' .. port .. '\0' .. impl.source_file .. '\0' .. impl.source_sha256 .. '\0' .. impl.qualified_type
              if not seen[key] then
                if #rows >= 2048 then return rows, labels, true end
                seen[key] = true
                rows[#rows + 1] = { path = path, port = port, anchor = {
                  source_file = impl.source_file, source_sha256 = impl.source_sha256, qualified_type = impl.qualified_type } }
                labels[#labels + 1] = path .. ' · ' .. port .. ' · ' .. impl.qualified_type .. ' · ' .. impl.source_file .. ' · ' .. impl.source_sha256:sub(1, 12)
                  .. (vim.startswith(impl.source_file, '@external:') and tr(' · external source', ' · 外部源码', ' · 外部原始碼') or '')
              end
            end
          end
        end
      end
    end
  end
  return rows, labels, truncated
end

sessions.port_supervision = function(state, preferred)
  local observed, project, epoch = state.last, state.opts.project, state.change_epoch or 0
  local report = observed and observed.report
  local calls = report and report.operation == 'probe' and report.status == 'success'
    and type(report.data) == 'table' and report.data.calls
  if not observed or observed.context_changed or observed.isolated_variant or observed.historical_observation
      or type(calls) ~= 'table' or not is_list(calls) then
    notify(tr('Run a current forward to inspect port supervision.', '请先运行当前模型的前向，再查看端口监督。', '請先執行目前模型的前向，再查看連接埠監督。'), vim.log.levels.WARN); return
  end
  local rows, labels, truncated = observed_port_choices(calls)
  if #rows == 0 then notify(tr('No observed ports are available.', '没有可用的已观察端口。', '沒有可用的已觀察連接埠。'), vim.log.levels.INFO); return end
  local function inspect_port(_, index, from_picker)
    local port = index and rows[index]
    if not port or state.closed or state.last ~= observed or observed.context_changed then return end
    if from_picker and not pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false) then return end
    state.busy = tr('Reading port supervision', '读取端口监督', '讀取連接埠監督'); render(state)
    request(state, { 'model', 'marks' }, function(result, failure)
      state.busy = nil; render(state)
      local data = result and result.data
      if failure or state.closed or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
          or state.last ~= observed or observed.context_changed or not result or result.status ~= 'success'
          or result.operation ~= 'semantic_mark' or type(data) ~= 'table' or not sha256(data.state_revision)
          or type(data.marks) ~= 'table' or not is_list(data.marks) then
        notify(tr('Cannot read current port marks; observe and try again.', '无法读取当前端口标记；请重新观察后再试。', '無法讀取目前連接埠標記；請重新觀察後再試。'), vim.log.levels.WARN); return
      end
      local matches = {}
      for _, mark in ipairs(data.marks) do
        if type(mark) == 'table' and mark.module_path == port.path and mark.port == port.port then matches[#matches + 1] = mark end
      end
      local function same_draft_rule(existing, draft)
        if type(existing) ~= 'table' or type(draft) ~= 'table' then return false end
        local function normalized(value) if value == vim.NIL then return nil end; return value end
        return existing.kind == draft.kind and existing.mode == draft.mode and normalized(existing.min) == draft.min
          and normalized(existing.max) == draft.max and normalized(existing.weight) == draft.weight
          and normalized(existing.axis) == nil and normalized(existing.target_path) == nil and normalized(existing.plugin) == nil
      end
      local function clean(value) return vim.fn.strcharpart(tostring(value or '?'):gsub('[%c]', ' '), 0, 180) end
      local function training_coverage(row)
        if type(row.steps_observed) ~= 'number' or row.steps_observed < 0 or row.steps_observed % 1 ~= 0 then
          return tr('observation unknown', '观察状态未知', '觀察狀態未知')
        end
        if row.steps_observed == 0 then
          return tr('not observed in this run', '本次运行未观察到', '本次執行未觀察到')
        end
        return tr('steps ', '观察步数 ', '觀察步數 ') .. clean(row.steps_observed)
          .. ' · ' .. tr('violations ', '违规数 ', '違規數 ') .. clean(row.violation_count)
          .. (type(row.element_count) == 'number' and (' / ' .. tostring(row.element_count)) or '')
      end
      local lines = { tr('Port supervision', '端口监督', '連接埠監督'), clean(port.path) .. ' · ' .. clean(port.port),
        tr('Bindings are saved metadata; only a new preview checks this input.', '绑定是已保存的元数据；只有新预览会检查当前输入。', '繫結是已儲存的中繼資料；只有新預覽會檢查目前輸入。'),
        tr('When explicitly enabled at a supported training boundary: observe records; require stops a managed update on violation; penalty adds weighted loss.',
          '在受支持的训练边界明确启用后：observe 记录；require 违反时阻止受管更新；penalty 将加权惩罚加入损失。',
          '在受支援的訓練邊界明確啟用後：observe 記錄；require 違反時阻止受管更新；penalty 將加權懲罰加入損失。'),
        tr('Coverage is limited to executed marked ports; user code may already have side effects.',
          '只覆盖实际执行的标记端口；用户代码可能已经产生副作用。',
          '只涵蓋實際執行的標記連接埠；使用者程式碼可能已產生副作用。'), '' }
      if type(preferred) == 'table' and preferred.path == port.path and preferred.port == port.port
          and type(preferred.semantic_label) == 'string' then
        lines[#lines + 1] = tr('Graph label (not yet a runtime mark): ', '图中语义标签（尚非运行时标记）：', '圖中語意標籤（尚非執行時標記）：') .. clean(preferred.semantic_label)
      end
      if type(preferred) == 'table' and preferred.path == port.path and preferred.port == port.port
          and type(preferred.draft_rules) == 'table' then
        for _, rule in ipairs(preferred.draft_rules) do
          local ok, text = pcall(vim.json.encode, rule)
          local status = tr('binding unknown', '绑定状态未知', '繫結狀態未知')
          if #matches == 1 and matches[1].binding_status == 'current' then
            local equivalent = false
            for _, existing in ipairs(type(matches[1].rules) == 'table' and matches[1].rules or {}) do
              if same_draft_rule(existing, rule) then equivalent = true; break end
            end
            status = equivalent and tr('same parameters on mark; no identity link', '标记中有同参数规则；无身份关联', '標記中有同參數規則；無身分關聯')
              or tr('no equivalent rule on mark', '标记中无同参数规则', '標記中無同參數規則')
          elseif #matches == 0 then status = tr('no observed mark', '没有已观察标记', '沒有已觀察標記') end
          if ok then lines[#lines + 1] = tr('Draft rule: ', '草稿规则：', '草稿規則：') .. clean(text) .. ' · ' .. status end
        end
      end
      if #matches == 0 then lines[#lines + 1] = tr('No marks for this port.', '此端口尚无标记。', '此連接埠尚無標記。') end
      local prior = state.supervision_progress and state.supervision_progress.stage == 'preview'
        and state.supervision_progress.report and state.supervision_progress.report.report
      local results = prior and type(prior.data) == 'table' and prior.data.results or nil
      local prior_by_rule = {}
      for index, row in ipairs(type(results) == 'table' and results or {}) do
        if index > 16384 then break end
        if type(row) == 'table' and type(row.mark_id) == 'string' and type(row.rule_id) == 'string' then
          prior_by_rule[row.mark_id .. '\0' .. row.rule_id] = row
        end
      end
      local trial_by_rule = {}
      local trial = state.last_supervised_trial
      local trial_rules = trial and trial.project == project and type(trial.data) == 'table'
        and type(trial.data.supervision) == 'table' and trial.data.supervision.rules or nil
      for index, row in ipairs(type(trial_rules) == 'table' and trial_rules or {}) do
        if index > 16384 then break end
        if type(row) == 'table' and type(row.mark_id) == 'string' and type(row.rule_id) == 'string' then
          trial_by_rule[row.mark_id .. '\0' .. row.rule_id] = row
        end
      end
      for mark_index, mark in ipairs(matches) do
        if mark_index > 32 then lines[#lines + 1] = tr('Additional marks are available in the mark list.', '其余标记请在标记列表中查看。', '其餘標記請在標記清單中查看。'); break end
        lines[#lines + 1] = clean(mark.role) .. ' · ' .. clean(mark.meaning) .. ' · ' .. clean(mark.binding_status)
        for _, rule in ipairs(type(mark.rules) == 'table' and mark.rules or {}) do
          if type(rule) ~= 'table' then break end
          lines[#lines + 1] = '  ' .. clean(rule.kind) .. ' · ' .. clean(rule.mode) .. ' · ' .. clean(rule.id)
          local settings = {}
          for _, field in ipairs({ 'min', 'max', 'weight', 'axis', 'target_path' }) do
            if rule[field] ~= nil and rule[field] ~= vim.NIL then settings[#settings + 1] = field .. '=' .. clean(rule[field]) end
          end
          if type(rule.plugin) == 'table' and type(rule.plugin.entrypoint) == 'string' then
            settings[#settings + 1] = clean(rule.plugin.entrypoint)
          end
          if #settings > 0 then lines[#lines + 1] = '    ' .. table.concat(settings, ' · ') end
          local result_row = type(mark.id) == 'string' and type(rule.id) == 'string' and prior_by_rule[mark.id .. '\0' .. rule.id] or nil
          if result_row then
              lines[#lines + 1] = tr('    Earlier preview (may differ from current input): ', '    先前预览（可能与当前输入不同）：', '    先前預覽（可能與目前輸入不同）：')
                .. clean(result_row.status) .. ' · ' .. tr('violations ', '违规数 ', '違規數 ') .. clean(result_row.violation_count)
                .. (type(result_row.element_count) == 'number' and (' / ' .. tostring(result_row.element_count)) or '')
                .. (type(result_row.observations) == 'table' and (tr(' · recorded calls ', ' · 已记录调用 ', ' · 已記錄呼叫 ') .. #result_row.observations) or '')
          end
          local trial_row = type(mark.id) == 'string' and type(rule.id) == 'string' and trial_by_rule[mark.id .. '\0' .. rule.id] or nil
          if trial_row then
            lines[#lines + 1] = tr('    Recent session trial (settings may differ): ', '    本会话最近试跑（设置可能不同）：', '    本工作階段最近試跑（設定可能不同）：')
              .. training_coverage(trial_row)
          end
        end
      end
      lines[#lines + 1] = ''
      local action_rows = {}
      if #matches == 1 then
        lines[#lines + 1] = tr('  → Add a rule [a]', '  → 添加规则 [a]', '  → 新增規則 [a]'); action_rows[#lines] = 'a'
        if type(preferred) == 'table' and type(preferred.draft_rules) == 'table' and #preferred.draft_rules > 0
            and preferred.path == port.path and preferred.port == port.port then
          lines[#lines + 1] = tr('  → Bind a draft rule [b]', '  → 绑定一条草稿规则 [b]', '  → 繫結一條草稿規則 [b]'); action_rows[#lines] = 'b'
        end
      elseif #matches == 0 then
        lines[#lines + 1] = tr('  → Mark this module port [t]', '  → 标记此模块端口 [t]', '  → 標記此模組連接埠 [t]'); action_rows[#lines] = 't'
      else
        lines[#lines + 1] = tr('  → Choose a mark [M]', '  → 选择标记 [M]', '  → 選擇標記 [M]'); action_rows[#lines] = 'M'
      end
      if #data.marks > 0 then
        lines[#lines + 1] = tr('  ↻ Rebind a mark to this observed port [B]', '  ↻ 将标记重绑到当前观察端口 [B]', '  ↻ 將標記重綁到目前觀察連接埠 [B]'); action_rows[#lines] = 'B'
      end
      lines[#lines + 1] = tr('  ▶ Preview supervision [u]', '  ▶ 预览监督 [u]', '  ▶ 預覽監督 [u]'); action_rows[#lines] = 'u'
      lines[#lines + 1] = tr('  ▶ Prepare a training trial [y]', '  ▶ 准备训练试跑 [y]', '  ▶ 準備訓練試跑 [y]'); action_rows[#lines] = 'y'
      lines[#lines + 1] = tr('  → Find recent recorded results [h]', '  → 查找最近运行结果 [h]', '  → 尋找最近執行結果 [h]'); action_rows[#lines] = 'h'
      lines[#lines + 1] = tr('  → Open training runs [R]', '  → 查看训练记录 [R]', '  → 查看訓練紀錄 [R]'); action_rows[#lines] = 'R'
      lines[#lines + 1] = tr('  ← Close [q]', '  ← 关闭 [q]', '  ← 關閉 [q]'); action_rows[#lines] = 'q'
      -- Keep the next actions visible even when the surrounding workspace has
      -- little vertical space; the rule details remain scrollable below.
      local ordered_actions = vim.tbl_keys(action_rows)
      table.sort(ordered_actions)
      local reordered, reordered_actions = { lines[1], lines[2] }, {}
      for _, row in ipairs(ordered_actions) do
        reordered[#reordered + 1] = lines[row]
        reordered_actions[#reordered] = action_rows[row]
      end
      reordered[#reordered + 1] = ''
      for row = 3, ordered_actions[1] - 1 do reordered[#reordered + 1] = lines[row] end
      lines, action_rows = reordered, reordered_actions
      local buf = vim.api.nvim_create_buf(false, true)
      vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines); vim.bo[buf].modifiable = false
      for row in pairs(action_rows) do vim.api.nvim_buf_set_extmark(buf, builder_buttons, row - 1, 0, { line_hl_group = 'Pmenu' }) end
      if not open_aux_buffer(buf, false, false) then return end
      pcall(vim.api.nvim_win_set_height, vim.api.nvim_get_current_win(), math.min(math.max(#lines, 12), math.max(8, math.floor(vim.o.lines / 2))))
      local searching = false
      local function find_recorded_results()
        if searching or state.busy or #matches == 0 then
          if #matches == 0 then notify(tr('Mark this port before looking up its runs.', '请先标记此端口，再查找运行记录。', '請先標記此連接埠，再尋找執行紀錄。'), vim.log.levels.INFO) end
          return
        end
        local mark_ids = {}
        for _, mark in ipairs(matches) do if type(mark.id) == 'string' then mark_ids[mark.id] = true end end
        local function still_current()
          return not state.closed and state.opts.project == project and (state.change_epoch or 0) == epoch
            and state.last == observed and not observed.context_changed and vim.api.nvim_buf_is_valid(buf)
        end
        local function append_result(extra)
          searching = false
          if not still_current() then return end
          vim.bo[buf].modifiable = true
          vim.api.nvim_buf_set_lines(buf, -1, -1, false, vim.list_extend({ '' }, extra))
          vim.bo[buf].modifiable = false
          local win = vim.fn.bufwinid(buf)
          if win ~= -1 and vim.api.nvim_win_is_valid(win) then
            pcall(vim.api.nvim_win_set_cursor, win, { vim.api.nvim_buf_line_count(buf), 0 })
          end
        end
        searching = true
        notify(tr('Checking up to eight recent runs…', '正在检查最近八条运行…', '正在檢查最近八筆執行…'), vim.log.levels.INFO)
        request(state, { 'runs', 'list' }, function(list, list_error)
          local runs = list and type(list.data) == 'table' and list.data.runs or nil
          if list_error or not list or list.operation ~= 'runs_list' or list.status ~= 'success'
              or type(runs) ~= 'table' or not is_list(runs) then
            append_result({ tr('Run history is unavailable.', '运行记录不可用。', '執行紀錄無法使用。') }); return
          end
          local candidates, unavailable = {}, false
          for _, row in ipairs(runs) do
            if type(row) == 'table' and type(row.id) == 'string' and row.id:match('^[%w_-]+$')
                and (row.operation == 'train' or row.operation == 'training_probe')
                and row.status ~= 'running' and row.status ~= 'stopping' then
              if type(row.started_at_ms) == 'number' and row.started_at_ms > 0 then candidates[#candidates + 1] = row
              else unavailable = true end
            end
          end
          table.sort(candidates, function(a, b)
            local left, right = tonumber(a.started_at_ms) or 0, tonumber(b.started_at_ms) or 0
            if left ~= right then return left > right end
            return a.id > b.id
          end)
          local index = 0
          local function next_run()
            if not still_current() then searching = false; return end
            index = index + 1
            local candidate = index <= 8 and candidates[index] or nil
            if not candidate then
              append_result({ tr('No matching result in the checked recent runs.', '已检查的近期运行中没有匹配结果。', '已檢查的近期執行中沒有符合結果。')
                .. (unavailable and tr(' Some records could not be read.', ' 部分记录无法读取。', ' 部分紀錄無法讀取。') or '')
                .. (#candidates > 8 and tr(' Older runs were not searched.', ' 未搜索更早运行。', ' 未搜尋更早執行。') or '') }); return
            end
            request(state, { 'runs', 'show', candidate.id }, function(record, read_error)
              if not still_current() then searching = false; return end
              local data = record and type(record.data) == 'table' and record.data
              local report = data and type(data.report) == 'table' and data.report
              local supervision = report and type(report.data) == 'table' and report.data.supervision
              local rules = type(supervision) == 'table' and supervision.rules or nil
              if read_error or not record or record.operation ~= 'runs_show' or record.status ~= 'success' then unavailable = true; next_run(); return end
              local found = {}
              for _, row in ipairs(type(rules) == 'table' and rules or {}) do
                if type(row) == 'table' and mark_ids[row.mark_id] and row.module_path == port.path and row.port == port.port then
                  found[#found + 1] = '  ' .. clean(row.kind) .. ' · ' .. clean(row.mode)
                    .. ' · ' .. training_coverage(row)
                end
              end
              if #found == 0 then next_run(); return end
              table.insert(found, 1, tr('Most recently started matching run (settings may differ): ', '按启动时间最近的匹配运行（设置可能不同）：', '依啟動時間最近符合的執行（設定可能不同）：') .. clean(candidate.id))
              if unavailable then found[#found + 1] = tr('Some newer records were unavailable.', '部分较新的记录无法读取。', '部分較新的紀錄無法讀取。') end
              append_result(found)
            end)
          end
          next_run()
        end)
      end
      local function activate(key)
        if state.closed or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
            or state.last ~= observed or observed.context_changed then return end
        if key == 'h' then find_recorded_results(); return end
        if key == 'b' then
          local mark = #matches == 1 and matches[1] or nil
          if not mark or mark.binding_status ~= 'current' or type(mark.id) ~= 'string'
              or type(preferred) ~= 'table' or type(preferred.draft_rules) ~= 'table'
              or type(preferred.guard) ~= 'function' or not preferred.guard() then
            notify(tr('A current graph, source and observed mark are required.', '需要当前图、源码和已观察标记。', '需要目前的圖、原始碼和已觀察標記。'), vim.log.levels.WARN); return
          end
          local drafts = vim.deepcopy(preferred.draft_rules)
          local labels = {}; for _, rule in ipairs(drafts) do labels[#labels + 1] = vim.json.encode(rule) end
          vim.ui.select(labels, {prompt = tr('Choose a draft rule to bind', '选择要绑定的草稿规则', '選擇要繫結的草稿規則')}, function(_, index)
            local rule = index and drafts[index]
            if not rule or state.closed or state.last ~= observed or observed.context_changed or (state.change_epoch or 0) ~= epoch or not preferred.guard() then return end
            for _, existing in ipairs(type(mark.rules) == 'table' and mark.rules or {}) do
              if same_draft_rule(existing, rule) then
                notify(tr('An identical rule is already bound to this mark.', '此标记已绑定相同规则。', '此標記已繫結相同規則。'), vim.log.levels.INFO); return
              end
            end
            request(state, {'--describe-interface'}, function(interface, failure)
              local caps = interface and interface.data and interface.data.capabilities
              if failure or state.closed or state.last ~= observed or observed.context_changed or (state.change_epoch or 0) ~= epoch
                  or not preferred.guard() or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
                  or type(caps) ~= 'table' or caps['supervision.conditional_rule_add_v1'] ~= true then
                notify(tr('Cannot safely bind this rule; refresh the graph and mark.', '无法安全绑定此规则，请刷新图和标记。', '無法安全繫結此規則，請重新整理圖和標記。'), vim.log.levels.WARN); return
              end
              local args = {'model', 'supervise', 'rule', 'add', '--mark', mark.id, '--kind', rule.kind, '--mode', rule.mode, '--if-state-revision', data.state_revision}
              for _, field in ipairs({'min', 'max', 'weight'}) do if rule[field] ~= nil then vim.list_extend(args, {'--' .. field, tostring(rule[field])}) end end
              if not vim.api.nvim_buf_is_valid(buf) or vim.api.nvim_get_current_buf() ~= buf then
                notify(tr('Focus changed; open port supervision again.', '焦点已变化，请重新打开端口监督。', '焦點已變更，請重新開啟連接埠監督。'), vim.log.levels.WARN); return
              end
              if not pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false) then return end
              run(state, tr('Bind draft rule', '绑定草稿规则', '繫結草稿規則'), args, function(receipt, error, _, stale)
                if not error and not stale and receipt and receipt.operation == 'semantic_supervise' and receipt.status == 'success' then
                  state.supervision_progress = {report = state.last, stage = 'rule'}; render(state)
                  notify(tr('Rule bound; preview before enabling supervision.', '规则已绑定；启用监督前请预览。', '規則已繫結；啟用監督前請預覽。'), vim.log.levels.INFO)
                end
              end, tr('Add this rule to the selected observed mark. It only affects training when supervision is enabled.',
                '将此规则添加到所选已观察标记。只有启用监督时才影响训练。', '將此規則新增至所選已觀察標記。只有啟用監督時才影響訓練。')
                .. '\n' .. clean(mark.role) .. ' · ' .. clean(port.path) .. ' · ' .. clean(port.port) .. '\n' .. labels[index], true,
                function() return not state.closed and state.last == observed and not observed.context_changed
                    and (state.change_epoch or 0) == epoch and project_config_current(state) and preferred.guard() end)
            end)
          end)
          return
        end
        if key == 'B' and state.actions.B then
          local candidates, labels = {}, {}
          for _, mark in ipairs(data.marks) do
            if type(mark) == 'table' and type(mark.id) == 'string' and mark.id ~= '' then
              candidates[#candidates + 1] = mark
              labels[#labels + 1] = clean(mark.role) .. ' · ' .. clean(mark.meaning) .. ' · ' .. clean(mark.module_path) .. ' · ' .. clean(mark.port)
            end
          end
          local function bind(index)
            local mark = candidates[index]
            if not mark or state.closed or state.last ~= observed or observed.context_changed or (state.change_epoch or 0) ~= epoch
                or (type(preferred) == 'table' and preferred.guard and not preferred.guard()) then return end
            state.selected_mark = mark.id
            state.selected_mark_record = {mark = vim.deepcopy(mark), revision = data.state_revision}
            local window = vim.fn.bufwinid(buf)
            if window == -1 or not pcall(vim.api.nvim_win_close, window, false) then return end
            state.actions.B({path = port.path, port = port.port, guard = type(preferred) == 'table' and preferred.guard or nil})
          end
          if #matches == 1 then
            for index, mark in ipairs(candidates) do if mark.id == matches[1].id then return bind(index) end end
          end
          return vim.ui.select(labels, {prompt = tr('Choose a mark to rebind to this port', '选择要重绑到此端口的标记', '選擇要重綁至此連接埠的標記')}, function(_, index)
            if index then bind(index) end
          end)
        end
        if key == 'a' and #matches == 1 then state.selected_mark = matches[1].id end
        if not pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false) then return end
        if key == 'a' and state.actions.d then state.actions.d(true)
        elseif key == 't' then mark_observed_port(state, port.path, port.port,
          type(preferred) == 'table' and preferred.path == port.path and preferred.port == port.port and preferred.semantic_label or nil)
        elseif key ~= 'q' and state.actions[key] then state.actions[key]() end
      end
      for _, key in ipairs({ 'a', 'b', 't', 'B', 'M', 'u', 'y', 'h', 'R', 'q' }) do
        vim.keymap.set('n', key, function() activate(key) end, { buffer = buf, silent = true })
      end
      vim.keymap.set('n', '<CR>', function() local key = action_rows[vim.api.nvim_win_get_cursor(0)[1]]; if key then activate(key) end end, { buffer = buf, silent = true })
      vim.keymap.set('n', '<LeftMouse>', function()
        local mouse = vim.fn.getmousepos(); local key = action_rows[mouse.line]
        if not key or mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= buf then return '<LeftMouse>' end
        vim.schedule(function() if vim.api.nvim_win_is_valid(mouse.winid) then vim.api.nvim_set_current_win(mouse.winid); activate(key) end end)
        return '<Ignore>'
      end, { buffer = buf, expr = true, silent = true })
    end)
  end
  local selected
  if type(preferred) == 'table' then
    for index, row in ipairs(rows) do
      if row.path == preferred.path and row.port == preferred.port then
        if selected then selected = nil; break end
        selected = index
      end
    end
  end
  if selected then inspect_port(nil, selected)
  else
    module_picker(tr('Choose a port to inspect', '选择要查看的端口', '選擇要查看的連接埠')
      .. (truncated and tr(' (list truncated)', '（列表已截断）', '（清單已截斷）') or ''), rows, labels,
      function(_, index) inspect_port(nil, index, true) end, nil, true)
  end
end

mark_observed_port = function(state, preferred_path, preferred_port, suggested_meaning)
  local observed = state.last
  local report = observed and observed.report
  local calls = report and report.operation == 'probe' and type(report.data) == 'table' and report.data.calls
  local variant = observed and observed.isolated_variant and observed.variant_context or nil
  local function observation_changed()
    return not observed or (variant and observed.observed_context_changed or (not variant and observed.context_changed))
  end
  if observation_changed() or observed.historical_observation or not calls or not is_list(calls)
      or report.data.forward_execution ~= 'executed'
      or (type(report.data.evidence_cache) == 'table' and report.data.evidence_cache.status == 'reused') then
    notify(tr('Run a confirmed new forward pass before marking a port.',
      '标记端口前请先运行并确认一次新的前向。', '標記連接埠前請先執行並確認一次新的前向。'), vim.log.levels.WARN)
    return
  end
  local candidates, labels, truncated = observed_port_choices(calls, preferred_path)
  if preferred_port then
    local filtered, names = {}, {}
    for index, candidate in ipairs(candidates) do
      if candidate.port == preferred_port then filtered[#filtered + 1], names[#names + 1] = candidate, labels[index] end
    end
    candidates, labels = filtered, names
  end
  if #candidates == 0 then
    notify(tr('No input or output ports with a readable Python source identity were reported for this selection.',
      '本次选择没有报告具备可读取 Python 源码身份的输入或输出端口。', '本次選擇沒有回報具備可讀取 Python 原始碼身分的輸入或輸出連接埠。'), vim.log.levels.WARN)
    return
  end
  local epoch = state.change_epoch or 0
  module_picker(tr('Choose an observed input or output', '选择已观察的输入或输出', '選擇已觀察的輸入或輸出')
    .. (truncated and tr(' (candidate list truncated)', '（候选列表已截断）', '（候選清單已截斷）') or ''),
    candidates, labels, function(_, index)
    local selected = index and candidates[index]
    if not selected or state.closed then return end
    if not pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false) then return end
    vim.ui.input({ prompt = tr('Semantic role: ', '语义角色：', '語義角色：') }, function(role)
      if not role or role == '' or state.closed then return end
      vim.ui.input({ prompt = tr('Meaning: ', '含义：', '意義：'), default = suggested_meaning or '' }, function(meaning)
        if not meaning or meaning == '' or state.closed then return end
        if state.last ~= observed or observation_changed() or (state.change_epoch or 0) ~= epoch then
          notify(tr('The observation changed; run the forward pass again before marking.', '观察结果已变化；标记前请重新前向。', '觀察結果已變更；標記前請重新前向。'), vim.log.levels.WARN)
          return
        end
        local mark_project, mark_cli = state.opts.project, state.opts.cli
        local mark_window, mark_buffer = vim.api.nvim_get_current_win(), vim.api.nvim_get_current_buf()
        state.busy = tr('Checking mark protection', '检查标记保护', '檢查標記保護'); render(state)
        request(state, { '--describe-interface' }, function(interface, failure)
          state.busy = nil; render(state)
          if state.opts.project ~= mark_project or state.opts.cli ~= mark_cli or state.last ~= observed
              or observation_changed() or (state.change_epoch or 0) ~= epoch
              or not vim.api.nvim_win_is_valid(mark_window) or vim.api.nvim_get_current_win() ~= mark_window
              or vim.api.nvim_win_get_buf(mark_window) ~= mark_buffer then
            notify(tr('The observation or focus changed; choose the port again before marking.',
              '观察结果或焦点已变化，请重新选择端口后再标记。', '觀察結果或焦點已變更，請重新選擇連接埠後再標記。'), vim.log.levels.WARN)
            return
          end
          local caps = interface and interface.data and interface.data.capabilities
          if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
              or type(caps) ~= 'table' or caps['supervision.observed_anchor_guard_v1'] ~= true then
            notify(tr('This CLI cannot protect the selected implementation; update it before marking.',
              '当前 CLI 无法保护所选实现，请更新后再标记。', '目前 CLI 無法保護所選實作，請更新後再標記。'), vim.log.levels.WARN); return
          end
          if vim.startswith(selected.anchor.source_file, '@external:') and caps['supervision.external_source_anchor_v1'] ~= true then
            notify(tr('This CLI cannot protect an external source anchor.', '当前 CLI 无法保护外部源码锚点。', '目前 CLI 無法保護外部原始碼錨點。'), vim.log.levels.WARN); return
          end
          if selected.path == 'model' and caps['supervision.root_mark_v1'] ~= true then
            notify(tr('This CLI cannot mark the root model; update it before marking.', '此 CLI 无法标记根模型，请更新后再标记。', '此 CLI 無法標記根模型，請更新後再標記。'), vim.log.levels.WARN); return
          end
          if variant and caps['supervision.conditional_variant_mark_v1'] ~= true then
            notify(tr('This CLI cannot pin the selected variant while marking. Update it before continuing.',
              '当前 CLI 无法在标记时固定所选变体，请更新后继续。', '目前 CLI 無法在標記時固定所選變體，請更新後繼續。'), vim.log.levels.WARN); return
          end
          if state.closed or state.last ~= observed or observation_changed() or (state.change_epoch or 0) ~= epoch then return end
          if state.probe_device and caps['supervision.mark_device_v1'] ~= true then
            notify(tr('This CLI cannot use the selected device for marking. Update it or clear the forward device.',
              '当前 CLI 无法在标记时使用所选设备；请更新或清除前向设备。', '目前 CLI 無法在標記時使用所選裝置；請更新或清除前向裝置。'), vim.log.levels.WARN); return
          end
          local args = { 'model', 'mark', '--path', selected.path, '--port', selected.port, '--role', role, '--meaning', meaning,
            '--if-anchor', vim.json.encode(selected.anchor) }
          if variant then
            vim.list_extend(args, { '--variant', variant.name, '--if-variant-base', variant.base.token })
            if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
            if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
            local names = vim.tbl_keys(state.batch_params or {}); table.sort(names)
            for _, name in ipairs(names) do
              vim.list_extend(args, { '--batch-param', name .. '=' .. vim.json.encode(state.batch_params[name]) })
            end
          end
          run(state, tr('Save semantic mark', '保存语义标记', '儲存語義標記'), args, function(receipt, failure, _, stale)
          local saved = receipt and receipt.data and receipt.data.mark
          if not failure and not stale and receipt and receipt.operation == 'semantic_mark' and receipt.status == 'success'
              and type(saved) == 'table' and type(saved.id) == 'string' and saved.id ~= '' then
            state.selected_mark = saved.id
            state.supervision_progress = { report = state.last, stage = 'mark' }
            render(state)
            notify(variant and tr('Variant port marked. Use d to add a rule, then choose this variant from Z to preview supervision.',
              '变体端口已标记。按 d 添加规则，再通过 Z 选择此变体预览监督。',
              '變體連接埠已標記。按 d 新增規則，再透過 Z 選擇此變體預覽監督。')
              or tr('Port marked. Use d to add a rule, then u to preview it on a representative input.',
                '端口已标记。按 d 添加规则，再按 u 用代表输入预览。',
                '連接埠已標記。按 d 新增規則，再按 u 用代表輸入預覽。'), vim.log.levels.INFO)
          end
          end,
            tr('This reruns a forward pass and writes the mark only if the implementation is unchanged.',
              '这会重新前向，只有实现来源未变才会写入标记。', '這會重新前向，只有實作來源未變才會寫入標記。')
              .. (vim.startswith(selected.anchor.source_file, '@external:') and tr(' The source file identified at runtime is hashed; this does not prove loaded code or pin other package files, native code or dependencies.',
                ' 将核对运行时识别的源码文件摘要，但这不能证明已加载代码，也不会固定其他包文件、原生代码或依赖。', ' 將核對執行時識別的原始碼檔案摘要，但這不能證明已載入程式碼，也不會固定其他套件檔案、原生程式碼或依賴。') or '')
              .. (selected.port:match('^inputs') and (caps['supervision.post_forward_scope_v1'] == true
                and tr(' Input rules observe arguments after the module call; they cannot prevent that call or its side effects, and in-place mutations may change the observed value.',
                  ' 输入规则在模块调用后观察参数，不能阻止本次调用及其副作用；原地修改也可能改变观察到的值。',
                  ' 輸入規則在模組呼叫後觀察參數，不能阻止本次呼叫及其副作用；原地修改也可能改變觀察到的值。')
                or tr(' This CLI does not report input observation timing; inspect its preview before using the rule.',
                  ' 此 CLI 未声明输入观察时机；使用规则前请检查其预览。', ' 此 CLI 未宣告輸入觀察時機；使用規則前請檢查其預覽。')) or ''), variant ~= nil)
        end)
      end)
    end)
  end, nil, true)
end

local function add_rule(state, use_selected)
  if state.busy then notify('Wait for the current operation.', vim.log.levels.WARN); return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local supports_environment_rule = false
  local supports_extended_axis = false
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  local function begin(mark, revision)
    local id = mark.id
    if not current() then return end
    local function valid_axis(axis)
      local number = type(axis) == 'string' and axis:match('^%d+$') and tonumber(axis) or nil
      if not number or number > 4294967295 then
        notify(tr('Axis must be a nonnegative 32-bit integer.', '轴必须是非负 32 位整数。', '軸必須是非負 32 位整數。'), vim.log.levels.WARN)
        return false
      end
      if number > 16 and not supports_extended_axis then
        notify(tr('The selected CLI does not declare support for axes above 16. Update it before saving this rule.',
          '所选 CLI 未声明支持大于 16 的轴；保存规则前请更新。',
          '所選 CLI 未宣告支援大於 16 的軸；儲存規則前請更新。'), vim.log.levels.WARN)
        return false
      end
      return true
    end
    local function finite_number(text)
      local number = tonumber(text)
      if not number or number ~= number or number == math.huge or number == -math.huge then return nil end
      return number
    end
    local kinds = { 'finite', 'range', 'batch-alignment', 'custom-validator', 'custom-penalty' }
    local labels = {
      tr('Finite values (no NaN or infinity)', '有限值（无 NaN 或无穷大）', '有限值（無 NaN 或無窮大）'),
      tr('Value range', '数值范围', '數值範圍'),
      tr('Match an input target dimension', '与输入目标维度对齐', '與輸入目標維度對齊'),
      tr('Custom validator in your code', '使用自定义校验函数', '使用自訂驗證函式'),
      tr('Custom differentiable penalty in your code', '使用自定义可微惩罚函数', '使用自訂可微懲罰函式'),
    }
    vim.ui.select(labels, { prompt = tr('What should this port satisfy?', '该端口需要满足什么？', '該連接埠需要滿足什麼？') }, function(_, kind_index)
      local kind = kind_index and kinds[kind_index]
      if not kind or state.closed then return end
      local modes = kind == 'range' and { 'observe', 'require', 'penalty' }
        or (kind == 'custom-penalty' and { 'penalty' } or { 'observe', 'require' })
      local descriptions = {
        observe = tr('Observe: report violations', '观察：报告违反情况', '觀察：回報違反情況'),
        require = tr('Require: stop tool-managed backward/update on violation', '阻止：违反时停止工具管理的反向和更新', '阻止：違反時停止工具管理的反向和更新'),
        penalty = tr('Penalty: add weighted differentiable loss during enabled training', '惩罚：启用监督训练时加入加权可微损失', '懲罰：啟用監督訓練時加入加權可微損失'),
      }
      local mode_labels = {}
      for _, mode in ipairs(modes) do mode_labels[#mode_labels + 1] = descriptions[mode] end
      vim.ui.select(mode_labels, { prompt = tr('What happens when the rule is enabled?', '启用规则后如何处理？', '啟用規則後如何處理？') }, function(_, mode_index)
        local mode = mode_index and modes[mode_index]
        if not mode or state.closed then return end
        local args = { 'model', 'supervise', 'rule', 'add', '--mark', id, '--kind', kind, '--mode', mode,
          '--if-state-revision', revision }
        local plugin_preview
        local function save()
          if not current() then
            notify(tr('Context changed; choose the mark again.', '上下文已变化，请重新选择标记。', '上下文已變更，請重新選擇標記。'), vim.log.levels.WARN); return
          end
          local effect = tr('This writes project supervision metadata. Rules affect training only when explicitly enabled.',
            '这会写入项目监督元数据；只有明确启用时才影响训练。', '這會寫入專案監督中繼資料；只有明確啟用時才影響訓練。')
            .. '\n' .. tostring(mark.role or '?') .. ' · ' .. tostring(mark.module_path or '?') .. ' · ' .. tostring(mark.port or '?')
            .. '\n' .. tostring(kind) .. ' · ' .. tostring(mode)
          for index, flag in ipairs(args) do
            if ({ ['--min'] = true, ['--max'] = true, ['--weight'] = true, ['--target-path'] = true,
                ['--axis'] = true, ['--plugin'] = true, ['--plugin-source'] = true })[flag] and type(args[index + 1]) == 'string' then
              effect = effect .. '\n' .. flag:sub(3) .. ': '
                .. vim.fn.strcharpart(args[index + 1]:gsub('[\r\n%z\1-\31\127]', ' '), 0, 512)
            end
          end
          if kind == 'custom-validator' or kind == 'custom-penalty' then
            if vim.tbl_contains(args, 'environment') then
              effect = effect .. tr('\nThe selected Python resolves the module using its configured import order, including project paths.',
                '\n所选 Python 按配置的导入顺序解析模块，其中也可能包含项目路径。', '\n所選 Python 按設定的匯入順序解析模組，其中也可能包含專案路徑。')
            end
            effect = effect .. tr('\nOnly the selected source file is fingerprinted; loaded code and dependencies are not fully pinned.', '\n仅固定所选源码文件的摘要，无法完整固定已加载代码和依赖。', '\n僅固定所選原始碼檔案的摘要，無法完整固定已載入程式碼和依賴。')
            effect = effect .. tr('\nSaving imports your rule code; import side effects cannot be rolled back.',
              '\n保存时会导入规则代码；导入副作用不能回滚。', '\n儲存時會匯入規則程式碼；匯入副作用無法回復。')
            if plugin_preview then
              effect = effect .. tr('\nRule parameters: ', '\n规则参数：', '\n規則參數：') .. plugin_preview
            end
          end
          if not reviewable_text(effect) then
            notify(tr('The rule details cannot be reviewed; no request was sent.', '规则详情无法完整审阅；未发送请求。', '規則詳情無法完整檢視；未傳送要求。'), vim.log.levels.WARN); return
          end
          run(state, tr('Save supervision rule', '保存监督规则', '儲存監督規則'), args, function(receipt, failure, _, stale)
            if not failure and not stale and receipt and receipt.operation == 'semantic_supervise'
                and receipt.status == 'success' and type(receipt.data) == 'table' and type(receipt.data.rule) == 'table' then
              state.supervision_progress = { report = state.last, stage = 'rule' }
              render(state)
            end
          end,
            effect, true)
        end
        local function weight()
          if mode ~= 'penalty' then save(); return end
          vim.ui.input({ prompt = tr('Penalty weight (>0): ', '惩罚权重（>0）：', '懲罰權重（>0）：') }, function(value)
            if not value or value == '' or state.closed then return end
            local number = finite_number(value)
            if not number or number <= 0 then
              notify(tr('Penalty weight must be a finite positive number.', '惩罚权重必须是有限正数。', '懲罰權重必須是有限正數。'), vim.log.levels.WARN); return
            end
            vim.list_extend(args, { '--weight', value }); save()
          end)
        end
        local function sample_axis()
          if kind ~= 'finite' and kind ~= 'range' and kind ~= 'custom-validator' then weight(); return end
          local prompt = kind == 'custom-validator'
            and tr('Optional nonnegative sample axis (requires a matching violation mask and stable sample IDs; empty skips): ',
              '可选非负样本轴（需要同形违规掩码和稳定样本 ID；留空跳过）：',
              '可選非負樣本軸（需要同形違規遮罩和穩定樣本 ID；留空略過）：')
            or tr('Optional nonnegative sample axis (stable sample IDs required for localization; empty skips): ',
              '可选非负样本轴（定位需要稳定样本 ID；留空跳过）：',
              '可選非負樣本軸（定位需要穩定樣本 ID；留空略過）：')
          vim.ui.input({ prompt = prompt, default = '' }, function(axis)
            if axis == nil or state.closed then return end
            if axis ~= '' then
              if not valid_axis(axis) then return end
              vim.list_extend(args, { '--axis', axis })
            end
            weight()
          end)
        end
        if kind == 'batch-alignment' then
          vim.ui.input({ prompt = tr('Target path (e.g. batch.kwargs.labels): ', '目标路径（如 batch.kwargs.labels）：', '目標路徑（如 batch.kwargs.labels）：') }, function(path)
            if not path or path == '' or state.closed then return end
            vim.ui.input({ prompt = tr('Target axis (nonnegative): ', '目标维度（非负整数）：', '目標維度（非負整數）：'), default = '0' }, function(axis)
              if not axis or state.closed or not valid_axis(axis) then return end
              vim.list_extend(args, { '--target-path', path, '--axis', axis })
              weight()
            end)
          end)
          return
        end
        if kind == 'custom-validator' or kind == 'custom-penalty' then
          local sources = { tr('Project source', '项目源码', '專案原始碼') }
          if supports_environment_rule then
            sources[#sources + 1] = tr('Selected Python environment', '所选 Python 环境', '所選 Python 環境')
          end
          vim.ui.select(sources, { prompt = tr('Where is the rule implemented?', '规则实现来自哪里？', '規則實作來自哪裡？') }, function(_, source_index)
            if not source_index or state.closed then return end
            if source_index == 2 then vim.list_extend(args, { '--plugin-source', 'environment' }) end
          vim.ui.input({ prompt = tr('Rule callable module:callable: ', '规则函数 module:callable：', '規則函式 module:callable：') }, function(plugin)
            if not plugin or plugin == '' or state.closed then return end
            vim.list_extend(args, { '--plugin', plugin })
            vim.ui.input({ prompt = tr('Rule parameters as JSON (recorded and visible in arguments; no secrets): ',
              '规则参数 JSON（会记录并出现在进程参数中，请勿填写密钥）：',
              '規則參數 JSON（會記錄並出現在程序參數中，請勿填寫金鑰）：'), default = '{}' }, function(raw)
              if not raw or state.closed then return end
              local ok, values = pcall(vim.json.decode, raw)
              if #raw > 16384 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') then notify(tr('Rule parameters must be a JSON object up to 16 KiB.', '规则参数必须是不超过 16 KiB 的 JSON 对象。', '規則參數必須是不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN); return end
              local names = vim.tbl_keys(values)
              table.sort(names)
              if #names > 64 then notify(tr('At most 64 rule parameters are supported.', '最多支持 64 个规则参数。', '最多支援 64 個規則參數。'), vim.log.levels.WARN); return end
              local printable, preview = pcall(vim.json.encode, next(values) and values or vim.empty_dict())
              if not printable or not reviewable_text(preview) then
                notify(tr('Rule parameters cannot be reviewed.', '规则参数无法审阅。', '規則參數無法檢視。'), vim.log.levels.WARN); return
              end
              plugin_preview = preview
              for _, name in ipairs(names) do
                if not identifier_candidate(name) then notify('Invalid rule parameter name.', vim.log.levels.WARN); return end
                local encoded, value = pcall(vim.json.encode, values[name])
                if not encoded then notify('Invalid rule parameter value.', vim.log.levels.WARN); return end
                vim.list_extend(args, { '--plugin-param', name .. '=' .. value })
              end
              sample_axis()
            end)
          end)
          end)
          return
        end
        if kind == 'finite' then sample_axis(); return end
        vim.ui.input({ prompt = tr('Minimum (empty to omit): ', '下界（留空省略）：', '下界（留空省略）：') }, function(minimum)
          if minimum == nil or state.closed then return end
          vim.ui.input({ prompt = tr('Maximum (empty to omit): ', '上界（留空省略）：', '上界（留空省略）：') }, function(maximum)
            if maximum == nil or state.closed then return end
            if minimum == '' and maximum == '' then notify('Range needs a minimum or maximum.', vim.log.levels.WARN); return end
            local lower = minimum ~= '' and finite_number(minimum) or nil
            local upper = maximum ~= '' and finite_number(maximum) or nil
            if (minimum ~= '' and not lower) or (maximum ~= '' and not upper) or (lower and upper and lower > upper) then
              notify(tr('Bounds must be finite numbers, with the minimum no greater than the maximum.',
                '上下界必须是有限数，且下界不能大于上界。', '上下界必須是有限數，且下界不能大於上界。'), vim.log.levels.WARN); return
            end
            if minimum ~= '' then vim.list_extend(args, { '--min', minimum }) end
            if maximum ~= '' then vim.list_extend(args, { '--max', maximum }) end
            sample_axis()
          end)
        end)
      end)
    end)
  end
  state.busy = tr('Checking rule protection', '检查规则保护', '檢查規則保護'); render(state)
  request(state, { '--describe-interface' }, function(interface, failure)
    state.busy = nil
    local caps = interface and interface.data and interface.data.capabilities
    if failure or not current() or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['supervision.conditional_rule_add_v1'] ~= true then
      render(state); notify(tr('A compatible CLI and unchanged context are required to bind a rule.',
        '需要兼容的 CLI 和未变化的上下文才能绑定规则。', '需要相容的 CLI 和未變更的上下文才能繫結規則。'), vim.log.levels.WARN); return
    end
    supports_environment_rule = caps['supervision.environment_rule_v1'] == true
    supports_extended_axis = caps['supervision.extended_axis_cli_v1'] == true
    state.busy = tr('Reading semantic marks', '读取语义标记', '讀取語義標記'); render(state)
    request(state, { 'model', 'marks' }, function(report, err)
      state.busy = nil; render(state)
      local data = report and report.data
      if err or not current() or not report or report.operation ~= 'semantic_mark' or report.status ~= 'success'
          or type(data) ~= 'table' or not sha256(data.state_revision) or type(data.marks) ~= 'table' or not is_list(data.marks) then
        notify(tr('Cannot read a current mark revision; no rule was saved.', '无法读取当前标记修订；规则未保存。', '無法讀取目前標記修訂；規則未儲存。'), vim.log.levels.WARN); return
      end
      local rows, labels = {}, {}
      for _, mark in ipairs(data.marks) do
        if type(mark) == 'table' and type(mark.id) == 'string' and mark.id ~= '' then
          rows[#rows + 1] = mark
          labels[#labels + 1] = tostring(mark.role or '?') .. ' · ' .. tostring(mark.module_path or '?') .. ' · '
            .. tostring(mark.port or '?') .. ' · ' .. tostring(mark.binding_status or 'unknown')
        end
      end
      if #rows == 0 then notify(tr('No semantic marks yet. Observe and mark a port first.',
        '尚无语义标记，请先观察并标记端口。', '尚無語義標記，請先觀察並標記連接埠。'), vim.log.levels.INFO); return end
      local function choose_mark(_, index)
        if not current() then return end
        local mark = index and rows[index]
        if not mark then return end
        local external = type(mark.anchor) == 'table' and type(mark.anchor.source_file) == 'string'
          and vim.startswith(mark.anchor.source_file, '@external:') and mark.binding_status == 'unverified'
        if mark.binding_status ~= 'current' and not external then
          notify(tr('The mark source is stale or unknown; re-observe and rebind it first.',
            '标记源码已过期或状态未知，请先重新观察并绑定。', '標記原始碼已過期或狀態未知，請先重新觀察並繫結。'), vim.log.levels.WARN); return
        end
        if external then
          vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Continue with unverified source', '继续使用未核验来源', '繼續使用未核驗來源') }, {
            prompt = tr('The external source was not imported by this list. Preview or training will recheck the runtime-identified file; loaded code and dependencies remain unpinned.',
              '列表未导入外部源码；预览或训练会重核运行时识别的文件，已加载代码和依赖仍未固定。',
              '清單未匯入外部原始碼；預覽或訓練會重新核對執行時識別的檔案，已載入程式碼和依賴仍未固定。'),
          }, function(_, confirmed)
            if confirmed ~= 2 or not current() then return end
            state.selected_mark = mark.id
            begin(mark, data.state_revision)
          end)
        else
          state.selected_mark = mark.id
          begin(mark, data.state_revision)
        end
      end
      if use_selected then
        local selected_index
        for index, mark in ipairs(rows) do
          if mark.id == state.selected_mark then selected_index = index; break end
        end
        if not selected_index then
          notify(tr('The selected mark is no longer available. Choose a mark again.',
            '所选标记已不可用，请重新选择标记。', '所選標記已無法使用，請重新選擇標記。'), vim.log.levels.WARN)
          return
        end
        choose_mark(nil, selected_index)
      else
        vim.ui.select(labels, { prompt = tr('Choose a mark for the rule (source status only)',
          '为规则选择标记（此处仅为源码状态）', '為規則選擇標記（此處僅為原始碼狀態）') }, choose_mark)
      end
    end)
  end)
end

-- These commands list saved metadata without asking the worker to construct a
-- user model. Like other history reads, they remain available with dirty code.
local function read_metadata(state, title, args, expected, callback, hide_report)
  if state.closed or state.busy then
    notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN)
    return
  end
  local epoch, project = state.change_epoch or 0, state.opts.project
  local dirty_at_read = #dirty_buffers(project) > 0
  state.busy = title
  render(state)
  request(state, args, function(report, err, stderr)
    state.busy = nil
    if report and report.status == 'success' and report.operation ~= expected then
      report, err = nil, { message = tr('Unexpected metadata operation in CLI response.', 'CLI 返回了非预期的元数据操作。', 'CLI 回傳了非預期的中繼資料操作。') }
    end
    local stale = state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
    state.last = { report = report, transport_error = err, stderr = stderr, context_changed = stale,
      scope = tr('Saved metadata only; current model behavior was not verified.',
        '仅为已保存的元数据；未验证当前模型行为。', '僅為已儲存的中繼資料；未驗證目前模型行為。') }
    if dirty_at_read then
      state.last.scope = state.last.scope .. tr(' Open buffers have unsaved edits that are not included.',
        ' 打开的 buffer 有未保存修改，未包含在此结果中。', ' 開啟的 buffer 有未儲存修改，未包含在此結果中。')
    end
    state.result_label = err and tr('CLI error', 'CLI 错误', 'CLI 錯誤') or (report and report.status or 'unknown')
    render(state)
    local report_buf = not hide_report and show_report(state) or nil
    callback(report, err, report_buf, stale)
  end)
end

preview_variant_supervision = function(state, name, base, project, epoch, cli)
  if state.closed or state.busy or state.opts.project ~= project or state.opts.cli ~= cli
      or (state.change_epoch or 0) ~= epoch then return end
  state.busy = tr('Checking variant supervision support', '检查变体监督能力', '檢查變體監督能力'); render(state)
  request(state, { '--describe-interface' }, function(interface, failure)
    state.busy = nil; render(state)
    if state.closed or state.opts.project ~= project or state.opts.cli ~= cli
        or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then return end
    local caps = interface and interface.operation == 'interface' and interface.status == 'success'
      and type(interface.data) == 'table' and interface.data.capabilities or nil
    if failure or type(caps) ~= 'table' or caps['supervision.conditional_variant_preview_v1'] ~= true
        or (state.probe_device and caps['supervision.preview_device_v1'] ~= true) then
      notify(tr('This CLI cannot safely preview supervision on the selected variant.',
        '当前 CLI 无法安全预览所选变体的监督规则。', '目前 CLI 無法安全預覽所選變體的監督規則。'), vim.log.levels.WARN); return
    end
    local args = { 'model', 'supervise', 'preview', '--variant', name, '--if-variant-base', base.token }
    if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
    if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
    local names = vim.tbl_keys(state.batch_params or {}); table.sort(names)
    for _, key in ipairs(names) do vim.list_extend(args, { '--batch-param', key .. '=' .. vim.json.encode(state.batch_params[key]) }) end
    run(state, tr('Preview variant supervision', '预览变体监督', '預覽變體監督'), args, function(report, err, _, stale)
      if not err and not stale and report and report.operation == 'semantic_supervise'
          and report.status == 'success' then
        state.supervision_progress = { report = state.last, stage = 'preview' }; render(state)
      end
    end, tr('Reruns the selected variant with its current rules and input; user code executes.',
      '使用当前规则和输入重新前向所选变体；会执行用户代码。',
      '使用目前規則和輸入重新前向所選變體；會執行使用者程式碼。'), true)
  end)
end

preview_variant_edit = function(state, name, base, project, epoch, cli, initial_path, initial_row)
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and state.opts.cli == cli and (state.change_epoch or 0) == epoch
  end
  if not current() then return end
  state.busy = tr('Checking variant edit support', '检查变体编辑能力', '檢查變體編輯能力'); render(state)
  request(state, { '--describe-interface' }, function(interface, failure)
    state.busy = nil; render(state)
    local caps = interface and interface.operation == 'interface' and interface.status == 'success'
      and type(interface.data) == 'table' and interface.data.capabilities or nil
    if not current() then
      notify(tr('Context changed; reopen the variant before editing.', '上下文已变化，请重新打开变体后再编辑。', '上下文已變更，請重新開啟變體後再編輯。'), vim.log.levels.WARN); return
    end
    if failure or type(caps) ~= 'table' or caps['edit.conditional_variant_edit_v1'] ~= true then
      notify(tr('This CLI cannot safely edit variants. Update it or use E → Choose CLI, then reopen the variant.',
        '当前 CLI 无法安全编辑变体。请更新 CLI，或按 E → 选择 CLI，再重新打开变体。',
        '目前 CLI 無法安全編輯變體。請更新 CLI，或按 E → 選擇 CLI，再重新開啟變體。'), vim.log.levels.WARN); return
    end
    local function submit(raw, base_rng_args)
      if not raw or not current() then return end
      local ok, operation = pcall(vim.json.decode, raw)
      if #raw > 65536 or not ok or type(operation) ~= 'table' or not raw:match('^%s*{')
          or not vim.tbl_contains({ 'add', 'replace', 'set', 'remove' }, operation.action) then
        notify(tr('Enter an add, replace, set or remove JSON object of at most 64 KiB.', '请输入不超过 64 KiB 的 add、replace、set 或 remove JSON 对象。', '請輸入不超過 64 KiB 的 add、replace、set 或 remove JSON 物件。'), vim.log.levels.WARN); return
      end
      if operation.rng_devices ~= nil and caps['edit.variant_layer_rng_v1'] ~= true then
        notify(tr('This CLI cannot preserve the requested Layer RNG devices.', '此 CLI 无法保留所选 Layer 随机设备。', '此 CLI 無法保留所選 Layer 隨機裝置。'), vim.log.levels.WARN); return
      end
      if base.token == 'absent' and not base_rng_args then
        if caps['edit.variant_base_rng_v1'] ~= true then
          notify(tr('This CLI cannot preserve the base-model RNG selection.', '此 CLI 无法保留基础模型随机设备选择。', '此 CLI 無法保留基礎模型隨機裝置選擇。'), vim.log.levels.WARN); return
        end
        vim.ui.select({ tr('CPU only', '仅 CPU', '僅 CPU'), tr('CPU and selected devices', 'CPU 和所选设备', 'CPU 和所選裝置') }, {
          prompt = tr('Base-model construction RNG scope', '基础模型构造随机范围', '基礎模型建構隨機範圍'),
        }, function(_, choice)
          if not current() or not choice then return end
          if choice == 1 then submit(raw, { '--base-rng-scope', 'cpu' }); return end
          vim.ui.input({ prompt = tr('Same-backend indexed devices, comma separated (e.g. cuda:0): ',
            '同一后端的带索引设备，以逗号分隔（如 cuda:0）：', '同一後端的帶索引裝置，以逗號分隔（如 cuda:0）：') }, function(value)
            if not value or not current() then return end
            local device_args, count = { '--base-rng-scope', 'selected' }, 0
            for item in value:gmatch('[^,]+') do
              local device = vim.trim(item)
              if device == '' then return end
              vim.list_extend(device_args, { '--base-rng-device', device }); count = count + 1
            end
            if count == 0 then notify(tr('Choose at least one device.', '请至少选择一个设备。', '請至少選擇一個裝置。'), vim.log.levels.WARN); return end
            submit(raw, device_args)
          end)
        end)
        return
      end
      local args = { 'layer', 'apply', '--operation', raw, '--target', 'variant', '--variant', name, '--dry-run', '--require-forward' }
      if base_rng_args then vim.list_extend(args, base_rng_args) end
      if base.token == 'absent' and state.model then vim.list_extend(args, { '--model', state.model }) end
      if base.token == 'absent' then
        local model_names = vim.tbl_keys(state.model_params or {}); table.sort(model_names)
        for _, key in ipairs(model_names) do vim.list_extend(args, { '--model-param', key .. '=' .. vim.json.encode(state.model_params[key]) }) end
      end
      if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
      if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
      local names = vim.tbl_keys(state.batch_params or {}); table.sort(names)
      for _, key in ipairs(names) do vim.list_extend(args, { '--batch-param', key .. '=' .. vim.json.encode(state.batch_params[key]) }) end
      local effects = tr('Reconstructs the variant and runs a candidate forward. Explicit RNG devices may initialize their backend. No variant is saved yet.',
        '重建变体并运行候选前向；显式随机设备可能初始化对应后端。此时不会保存变体。',
        '重建變體並執行候選前向；明確隨機裝置可能初始化對應後端。此時不會儲存變體。')
      if base_rng_args then
        local devices = {}
        for index, value in ipairs(base_rng_args) do
          if value == '--base-rng-device' then devices[#devices + 1] = base_rng_args[index + 1] end
        end
        effects = effects .. tr('\nBase construction RNG: CPU', '\n基础模型构造随机范围：CPU', '\n基礎模型建構隨機範圍：CPU')
          .. (#devices > 0 and (' + ' .. table.concat(devices, ', ')) or '')
      end
      run(state, tr('Preview variant edit', '预览变体编辑', '預覽變體編輯'), args, function(report, err, actual_args, stale, report_buf)
        local data = report and report.data
        local observed = type(data) == 'table' and data.variant_base or nil
        local validation = type(data) == 'table' and data.validation or nil
        local input = type(validation) == 'table' and validation.batch_content or nil
        local source = type(data) == 'table' and data.source_manifest_evidence or nil
        local seed = type(data) == 'table' and data.initialization_seed_decimal or nil
        if err or stale or not current() or not report or report.operation ~= 'edit' or report.status ~= 'success'
            or type(data) ~= 'table' or data.committed ~= false
            or type(observed) ~= 'table' or observed.name ~= name or observed.token ~= base.token
            or observed.algorithm ~= 'canonical-json-sha256-v1' or type(validation) ~= 'table'
            or validation.forward ~= 'passed' or validation.forward_evidence ~= 'executed'
            or type(input) ~= 'table' or input.status ~= 'available' or input.algorithm ~= 'sha256-forward-input-v1' or not sha256(input.digest)
            or type(source) ~= 'table' or source.algorithm ~= 'canonical-json-sha256-v1' or not sha256(source.digest)
            or type(seed) ~= 'string' or not seed:match('^%d+$') or #seed > 20 then
          notify(tr('Preview evidence is incomplete or stale; no variant was saved.', '预览证据不完整或已过期；未保存变体。', '預覽證據不完整或已過期；未儲存變體。'), vim.log.levels.WARN); return
        end
        local displayed = state.last
        review_gate(report_buf, { tr('Cancel', '取消', '取消'), tr('Save variant edit', '保存变体编辑', '儲存變體編輯') },
          tr('Save the reviewed variant edit?', '保存已审核的变体编辑？', '儲存已檢視的變體編輯？'), function(_, choice)
            if choice ~= 2 or not current() or state.last ~= displayed then return end
            local commit = vim.tbl_filter(function(arg) return arg ~= '--dry-run' end, vim.deepcopy(actual_args))
            vim.list_extend(commit, { '--if-variant-base', base.token, '--if-input-content', input.digest,
              '--if-source-manifest', source.digest, '--seed', seed })
            run(state, tr('Save variant edit', '保存变体编辑', '儲存變體編輯'), commit, nil,
              tr('Saves a new variant revision after rechecking source and input; external state and device RNGs can still differ.',
                '重新核对源码和输入后保存新变体修订；外部状态及设备随机数仍可能不同。',
                '重新核對原始碼和輸入後儲存新變體修訂；外部狀態及裝置隨機數仍可能不同。'), true, nil, nil, true, true)
          end)
      end, effects, true, nil, nil, true)
    end
    local function review_operation(operation)
      local ok, raw = pcall(vim.json.encode, operation)
      if not ok then notify(tr('Cannot encode this operation.', '无法编码此操作。', '無法編碼此操作。'), vim.log.levels.WARN); return end
      local target = operation.path or operation.parent or '?'
      local params_ok, params = pcall(vim.json.encode, operation.params or {})
      if not params_ok then params = '?' end
      if #params > 500 then params = params:sub(1, 497) .. '...' end
      local description = tr('Review change', '审核修改', '檢視修改') .. ': ' .. tostring(operation.action)
        .. ' · ' .. tostring(target) .. '\n' .. tr('Parameters (recorded; no secrets)', '参数（会被记录，请勿填写密钥）', '參數（會被記錄，請勿填寫密鑰）')
        .. ': ' .. params
      if operation.layer_type or operation.component then
        description = description .. '\n' .. tr('Layer', '层', '層') .. ': ' .. tostring(operation.layer_type or operation.component)
      end
      if operation.name then description = description .. '\n' .. tr('Child name', '子层名称', '子層名稱') .. ': ' .. tostring(operation.name) end
      if operation.strategy then description = description .. '\n' .. tr('Strategy', '方式', '方式') .. ': ' .. tostring(operation.strategy) end
      if operation.rng_devices then
        local devices_ok, devices = pcall(vim.json.encode, operation.rng_devices)
        description = description .. '\n' .. tr('Layer RNG devices', '层随机设备', '層隨機裝置') .. ': ' .. (devices_ok and devices or '?')
      end
      vim.ui.select({ tr('Continue to preview', '继续预览', '繼續預覽'), tr('Edit operation JSON', '编辑操作 JSON', '編輯操作 JSON'),
        tr('Cancel', '取消', '取消') }, { prompt = description }, function(_, choice)
          if not current() then return end
          if choice == 1 then submit(raw)
          elseif choice == 2 then
            vim.ui.input({ prompt = tr('Review operation JSON; values are recorded (no secrets): ',
              '审核操作 JSON；参数会被记录（请勿填写密钥）：', '檢視操作 JSON；參數會被記錄（請勿填寫密鑰）：'), default = raw }, submit)
          end
        end)
    end
    local function choose_rng(operation)
      local choices = { { label = tr('CPU generator only', '仅 CPU 生成器', '僅 CPU 產生器') },
        { label = tr('Enter device IDs', '手动填写设备 ID', '手動填寫裝置 ID'), manual = true } }
      local inventory = state.device_inventory
      if type(inventory) == 'table' and inventory.epoch == epoch and type(inventory.devices) == 'table' then
        for _, device in ipairs(inventory.devices) do
          if type(device.id) == 'string' and device.id:match('^[a-z][a-z0-9_]*:%d+$') then
            choices[#choices + 1] = { label = device.id .. ' · ' .. tostring(device.name), device = device.id }
          end
        end
      end
      vim.ui.select(choices, { prompt = tr('Layer RNG scope (other random sources are not fixed)',
        'Layer 随机数范围（其他随机源不固定）', 'Layer 隨機數範圍（其他隨機來源不固定）'), format_item = function(item) return item.label end }, function(item)
        if not item or not current() then return end
        if item.manual then
          vim.ui.input({ prompt = tr('Same-backend indexed devices, comma separated (e.g. cuda:0,cuda:1): ',
            '同一后端的带索引设备，以逗号分隔（如 cuda:0,cuda:1）：', '同一後端的帶索引裝置，以逗號分隔（如 cuda:0,cuda:1）：') }, function(raw)
            if raw == nil or not current() then return end
            local devices = {}
            for part in raw:gmatch('[^,]+') do devices[#devices + 1] = vim.trim(part) end
            if #devices > 0 then operation.rng_devices = devices end
            review_operation(operation)
          end)
        else
          if item.device then operation.rng_devices = { item.device } end
          review_operation(operation)
        end
      end)
    end
    local function guided(action)
      vim.ui.input({ prompt = action == 'add' and tr('Parent container path: ', '父容器路径：', '父容器路徑：')
          or tr('Layer path: ', '层路径：', '層路徑：'), default = initial_path or '' }, function(path)
        if not path or path == '' or not current() then return end
        if action == 'remove' then
          vim.ui.select({ tr('Remove from container', '从容器删除', '從容器刪除'), tr('Replace with Identity', '替换为 Identity', '替換為 Identity') },
            { prompt = tr('Removal strategy', '删除方式', '刪除方式') }, function(_, strategy)
              if not strategy or not current() then return end
              review_operation({ action = 'remove', path = path, strategy = strategy == 1 and 'remove' or 'bypass' })
            end)
          return
        elseif action == 'set' then
          vim.ui.select({ tr('Change one field', '修改单个字段', '修改單個欄位'), tr('Change fields using JSON', '使用 JSON 修改多个字段', '使用 JSON 修改多個欄位') },
            { prompt = tr('How would you like to edit?', '选择修改方式', '選擇修改方式') }, function(_, choice)
              if not choice or not current() then return end
              if choice == 1 then
                local function edit_field(name, old_value)
                  if not name or not current() then return end
                  if not name:match('^[%a_][%w_]*$') then
                    notify(tr('Enter a valid field name.', '请输入有效字段名。', '請輸入有效欄位名稱。'), vim.log.levels.WARN); return
                  end
                  local ok_default, default = pcall(vim.json.encode, old_value)
                  vim.ui.input({ prompt = tr('Value (JSON or plain text): ', '值（JSON 或普通文本）：', '值（JSON 或一般文字）：'),
                    default = old_value ~= nil and ok_default and default or nil }, function(raw)
                    if raw == nil or not current() then return end
                    if #raw > 65536 then
                      notify(tr('Value is too long.', '值过长。', '值過長。'), vim.log.levels.WARN); return
                    end
                    local ok, value = pcall(vim.json.decode, raw)
                    if not ok then value = raw end
                    review_operation({ action = 'set', path = path, params = { [name] = value } })
                  end)
                end
                local fields = path == initial_path and type(initial_row) == 'table' and initial_row.editable_params or nil
                local names = {}
                if type(fields) == 'table' and fields ~= vim.NIL then
                  for field in pairs(fields) do
                    if type(field) == 'string' and field:match('^[%a_][%w_]*$') then names[#names + 1] = field end
                  end
                end
                table.sort(names)
                local function manual_field()
                  vim.ui.input({ prompt = tr('Field name: ', '字段名：', '欄位名稱：') }, function(field) edit_field(field) end)
                end
                if #names == 0 then manual_field(); return end
                local labels = {}
                for _, field in ipairs(names) do
                  local ok, value = pcall(vim.json.encode, fields[field])
                  if ok and #value > 120 then value = value:sub(1, 117) .. '...' end
                  labels[#labels + 1] = field .. (ok and (' = ' .. value) or '')
                end
                labels[#labels + 1] = tr('Enter another field', '输入其他字段', '輸入其他欄位')
                vim.ui.select(labels, { prompt = tr('Choose a reported constructor field', '选择已报告的构造字段', '選擇已回報的建構欄位') }, function(_, index)
                  if not index or not current() then return end
                  if index > #names then manual_field() else edit_field(names[index], fields[names[index]]) end
                end)
                return
              end
              vim.ui.input({ prompt = tr('Changed constructor fields as JSON object: ', '修改的构造字段 JSON 对象：', '修改的建構欄位 JSON 物件：'), default = '{}' }, function(raw)
                if raw == nil or not current() then return end
                local ok, params = pcall(vim.json.decode, raw)
                if #raw > 65536 or not ok or type(params) ~= 'table' or not raw:match('^%s*{') or next(params) == nil then
                  notify(tr('Enter a nonempty JSON object.', '请输入非空 JSON 对象。', '請輸入非空 JSON 物件。'), vim.log.levels.WARN); return
                end
                review_operation({ action = 'set', path = path, params = params })
              end)
            end)
          return
        end
        local function choose_factory(factory, discovered)
          if not factory or factory == '' or not current() then return end
          local required = {}
          local signature = type(discovered) == 'table' and discovered.signature or nil
          if type(signature) == 'table' and signature.status == 'observed' and type(signature.parameters) == 'table' then
            for _, parameter in ipairs(signature.parameters) do
              if type(parameter) == 'table' and parameter.required == true and identifier_candidate(parameter.name)
                  and parameter.kind ~= 'POSITIONAL_ONLY' then
                required[#required + 1] = parameter.name
                if #required >= 32 then break end
              end
            end
          end
          local required_hint = #required > 0 and table.concat(required, ', ') or nil
          local function accept_params(params)
            if not current() then return end
            local operation = { action = action, params = params }
            if action == 'add' then operation.parent = path else operation.path = path end
            if factory:find(':', 1, true) then operation.component = factory else operation.layer_type = factory end
            if action == 'add' then
              vim.ui.input({ prompt = tr('Child name (leave empty only for ModuleList): ', '子层名称（仅 ModuleList 留空）：', '子層名稱（僅 ModuleList 留空）：') }, function(child)
                if child == nil or not current() then return end
                if child ~= '' then operation.name = child end
                choose_rng(operation)
              end)
            else choose_rng(operation) end
          end
          local params, edit_one = {}, nil
          local function cancel_parameters()
            if next(params) == nil then return end
            vim.ui.select({ tr('Continue entering parameters', '继续填写参数', '繼續填寫參數'),
              tr('Discard these parameters', '放弃已填参数', '放棄已填參數') }, {
                prompt = tr('These parameters have not been applied.', '这些参数尚未应用。', '這些參數尚未套用。'),
              }, function(_, selection)
                if current() and selection ~= 2 then edit_one() end
              end)
          end
          edit_one = function()
            if not current() then return end
            local remaining = {}
            for _, name in ipairs(required) do if params[name] == nil then remaining[#remaining + 1] = name end end
            vim.ui.input({ prompt = (#remaining > 0 and (tr('Reported required parameters: ', '报告的必填参数：', '回報的必填參數：')
                .. table.concat(remaining, ', ') .. ' · ') or '')
                .. tr('Parameter name (empty to finish): ', '参数名（留空完成）：', '參數名稱（留空完成）：') }, function(name)
              if not current() then return end
              if name == nil then cancel_parameters(); return end
              if name == '' then accept_params(params); return end
              if not identifier_candidate(name) or (params[name] == nil and vim.tbl_count(params) >= 64) then
                notify(tr('Invalid parameter name or too many parameters.', '参数名无效或参数过多。', '參數名稱無效或參數過多。'), vim.log.levels.WARN); edit_one(); return
              end
              vim.ui.input({ prompt = tr('Value (JSON or plain text; no secrets): ', '值（JSON 或普通文本，请勿填写密钥）：', '值（JSON 或一般文字，請勿填寫密鑰）：') }, function(raw)
                if not current() then return end
                if raw == nil then cancel_parameters(); return end
                if #raw > 65536 then notify(tr('Value is too large.', '值过大。', '值過大。'), vim.log.levels.WARN); edit_one(); return end
                local ok, value = pcall(vim.json.decode, raw)
                local previous = params[name]
                if ok then params[name] = value else params[name] = raw end
                local encoded, serialized = pcall(vim.json.encode, params)
                if not encoded or #serialized > 65536 then
                  params[name] = previous
                  notify(tr('Parameters exceed the 64 KiB limit.', '参数超过 64 KiB 上限。', '參數超過 64 KiB 上限。'), vim.log.levels.WARN)
                end
                edit_one()
              end)
            end)
          end
          vim.ui.select({ tr('Enter parameters one by one', '逐项填写参数', '逐項填寫參數'),
            tr('Enter a JSON object', '填写 JSON 对象', '填寫 JSON 物件'), tr('Use no parameters', '不传参数', '不傳參數') }, {
              prompt = tr('How would you like to provide constructor parameters?', '如何填写构造参数？', '如何填寫建構參數？')
                .. (required_hint and (tr(' Reported required: ', ' 报告的必填项：', ' 回報的必填項：') .. required_hint) or ''),
            }, function(_, method)
              if not current() then return end
              if method == 1 then edit_one()
              elseif method == 3 then accept_params({})
              elseif method == 2 then
                vim.ui.input({ prompt = tr('Constructor parameters as JSON object (no secrets): ', '构造参数 JSON 对象（请勿填写密钥）：', '建構參數 JSON 物件（請勿填寫密鑰）：'), default = '{}' }, function(raw)
                  if raw == nil or not current() then return end
                  local ok, values = pcall(vim.json.decode, raw)
                  if #raw > 65536 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') or vim.tbl_count(values) > 64 then
                    notify(tr('Enter a JSON object of at most 64 parameters and 64 KiB.', '请输入最多 64 项、64 KiB 的 JSON 对象。', '請輸入最多 64 項、64 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
                  end
                  accept_params(values)
                end)
              end
            end)
        end
        vim.ui.input({ prompt = tr('torch.nn class, module:factory, or ? to discover: ',
          'torch.nn 类名、module:factory，或输入 ? 发现类型：', 'torch.nn 類名、module:factory，或輸入 ? 探索類型：') }, function(factory)
          if not current() then return end
          if factory == '?' then
            discover_layer_classes(state, function(layer) choose_factory(layer.name, layer) end)
          else
            choose_factory(factory)
          end
        end)
      end)
    end
    vim.ui.select({ tr('Add a layer', '添加层', '新增層'), tr('Replace a layer', '替换层', '替換層'),
      tr('Change layer parameters', '修改层参数', '修改層參數'), tr('Remove a layer', '删除层', '刪除層'),
      tr('Enter operation JSON', '填写操作 JSON', '填寫操作 JSON') }, { prompt = tr('Variant edit', '变体编辑', '變體編輯') }, function(_, choice)
      if not choice or not current() then return end
      if choice == 5 then
        vim.ui.input({ prompt = tr('Layer operation as JSON (no secrets): ',
          'Layer 操作 JSON（请勿填写密钥）：', 'Layer 操作 JSON（請勿填寫密鑰）：'),
          default = '{"action":"replace","path":"model.head","layer_type":"Linear","params":{}}' }, submit)
      else guided(({ 'add', 'replace', 'set', 'remove' })[choice]) end
    end)
  end)
end

local function browse_variants(state)
  local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
  read_metadata(state, tr('Browse saved variants', '查看已保存变体', '查看已儲存變體'),
    { 'variant', 'list' }, 'variant_list', function(report, err, _, stale)
      local variants = report and type(report.data) == 'table' and report.data.variants
      if err or stale or not report or report.status ~= 'success' or type(variants) ~= 'table' or not is_list(variants) then return end
      local rows = { { create = true } }
      local labels = { tr('Create a variant from the current model', '从当前模型创建变体', '從目前模型建立變體') }
      local function label(value)
        return vim.fn.strcharpart(tostring(value or '?'):gsub('[%c]', ' '), 0, 200)
      end
      for _, item in ipairs(variants) do
        if type(item) == 'table' and item.readable == true and type(item.name) == 'string'
            and #item.name > 0 and #item.name <= 64 and item.name:match('^[A-Za-z0-9_-]+$') then
          rows[#rows + 1] = item
          labels[#labels + 1] = item.name .. ' · ' .. label(item.model) .. ' · '
            .. tr('device policy: ', '设备策略：', '裝置策略：') .. label(item.device_policy)
        end
      end
      vim.ui.select(labels, { prompt = tr('Choose a variant to inspect saved metadata (does not run it):',
        '选择变体查看已保存的元数据（不会运行）：', '選擇變體查看已儲存的中繼資料（不會執行）：') }, function(_, index)
        if not index or state.closed or state.busy or state.opts.project ~= project
            or state.opts.cli ~= cli or (state.change_epoch or 0) ~= epoch then return end
        local selected = rows[index]
        if not selected then return end
        if selected.create then
          vim.ui.input({ prompt = tr('New variant name (letters, digits, _ or -): ',
            '新变体名称（字母、数字、_ 或 -）：', '新變體名稱（字母、數字、_ 或 -）：') }, function(name)
            if not name or name == '' or state.closed or state.busy or state.opts.project ~= project
                or state.opts.cli ~= cli or (state.change_epoch or 0) ~= epoch then return end
            if #name > 64 or not name:match('^[A-Za-z0-9_-]+$') then
              notify(tr('Invalid variant name.', '变体名称无效。', '變體名稱無效。'), vim.log.levels.WARN); return
            end
            for _, item in ipairs(variants) do
              if type(item) == 'table' and item.name == name then
                notify(tr('This variant name already exists. Choose another name.', '变体名称已存在，请使用其他名称。', '變體名稱已存在，請使用其他名稱。'), vim.log.levels.WARN); return
              end
            end
            preview_variant_edit(state, name, { token = 'absent' }, project, epoch, cli)
          end)
          return
        end
        read_metadata(state, tr('Inspect saved variant', '查看变体详情', '查看變體詳情'),
          { 'variant', 'show', selected.name }, 'variant_show', function(detail, detail_error, _, detail_stale)
            local base = detail and type(detail.data) == 'table' and detail.data.variant_base
            if detail_error or detail_stale or not detail or detail.status ~= 'success'
                or type(base) ~= 'table' or base.name ~= selected.name
                or base.algorithm ~= 'canonical-json-sha256-v1' or not sha256(base.token) then return end
            vim.ui.select({ tr('Close', '关闭', '關閉'), tr('Run one forward on this variant', '对该变体执行一次前向', '對該變體執行一次前向'),
              tr('Preview a Layer edit', '预览 Layer 编辑', '預覽 Layer 編輯'),
              tr('Try a training step on this variant', '使用该变体试跑训练步骤', '使用該變體試跑訓練步驟'),
              tr('Train this variant', '训练该变体', '訓練該變體'),
              tr('Preview supervision on this variant', '预览该变体的监督规则', '預覽該變體的監督規則') }, {
              prompt = tr('The result is separate from the source model. The variant is rechecked before execution.',
                '结果独立于当前源码模型；执行前会重新核对变体。', '結果獨立於目前原始碼模型；執行前會重新核對變體。'),
            }, function(_, choice)
              if choice == 3 then
                preview_variant_edit(state, selected.name, base, project, epoch, cli)
                return
              end
              if choice == 4 then
                if state.closed or state.busy or state.opts.project ~= project or state.opts.cli ~= cli
                    or (state.change_epoch or 0) ~= epoch then return end
                prepare_trial(state, { name = selected.name, token = base.token })
                return
              end
              if choice == 5 then
                if state.closed or state.busy or state.opts.project ~= project or state.opts.cli ~= cli
                    or (state.change_epoch or 0) ~= epoch then return end
                prepare_pytorch_training(state, { name = selected.name, token = base.token })
                return
              end
              if choice == 6 then
                preview_variant_supervision(state, selected.name, base, project, epoch, cli)
                return
              end
              if choice ~= 2 or state.closed or state.busy or state.opts.project ~= project
                  or state.opts.cli ~= cli or (state.change_epoch or 0) ~= epoch then return end
              state.busy = tr('Checking variant observation support', '检查变体观察能力', '檢查變體觀察能力')
              render(state)
              request(state, { '--describe-interface' }, function(interface, failure)
                state.busy = nil
                render(state)
                if state.closed or state.opts.project ~= project or state.opts.cli ~= cli
                    or (state.change_epoch or 0) ~= epoch then return end
                local caps = interface and interface.operation == 'interface' and interface.status == 'success'
                  and type(interface.data) == 'table' and interface.data.capabilities or nil
                if failure or type(caps) ~= 'table' or caps['model.conditional_variant_probe_v1'] ~= true then
                  notify(tr('This CLI cannot guarantee the selected variant revision for a forward pass.',
                    '此 CLI 不能保证前向使用所选变体修订。', '此 CLI 無法保證前向使用所選變體修訂。'), vim.log.levels.WARN)
                  return
                end
                local args = { 'model', 'probe', '--variant', selected.name, '--if-variant-base', base.token }
                if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
                if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
                local names = vim.tbl_keys(state.batch_params or {})
                table.sort(names)
                for _, name in ipairs(names) do
                  vim.list_extend(args, { '--batch-param', name .. '=' .. vim.json.encode(state.batch_params[name]) })
                end
                run(state, tr('Observe saved variant', '观察已保存变体', '觀察已儲存變體'), args,
                  function(result, err, _, stale)
                    if not err and not stale and not state.closed and result and result.operation == 'probe'
                        and result.status == 'success' and state.last and state.last.report == result
                        and state.last.isolated_variant and state.opts.project == project and state.opts.cli == cli
                        and (state.change_epoch or 0) == epoch then
                      state.last.variant_context = { name = selected.name, base = vim.deepcopy(base),
                        project = project, epoch = epoch, cli = cli }
                      render(state)
                    end
                  end, nil, true, nil, nil, true)
              end)
            end)
          end)
      end)
    end)
end

local function transfer_supervision(state, importing, graph_reference, graph_guard)
  local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
  local function current()
    return not state.closed and not state.busy and state.opts.project == project and state.opts.cli == cli
      and (state.change_epoch or 0) == epoch and project_config_current(state) and (not graph_guard or graph_guard())
  end
  local function path_for(value)
    if type(value) ~= 'string' or value == '' or value:find('[%c]') then return nil end
    local absolute = value:sub(1, 1) == '/' or value:match('^%a:[/\\]') or value:match('^\\\\')
    return vim.fs.normalize(absolute and value or (project .. '/' .. value))
  end
  local saved = importing and require('model_maven.model_builder').load(project) or nil
  local reference = graph_reference or (saved and saved.supervision or nil)
  read_metadata(state, tr('Read supervision', '读取监督声明', '讀取監督宣告'), { 'model', 'marks' }, 'semantic_mark', function(report, err, _, stale)
    local data = report and report.data
    if err or stale or not current() or not report or report.status ~= 'success'
        or type(data) ~= 'table' or not sha256(data.state_revision) then return end
    local revision = data.state_revision
    if not importing then
      read_metadata(state, tr('Export supervision', '导出监督声明', '匯出監督宣告'),
        { 'model', 'supervise', 'export', '--if-state-revision', revision }, 'semantic_supervise', function(result, failure, _, changed)
        local exported = result and result.data
        if failure or changed or not current() or not result or result.status ~= 'success' or type(exported) ~= 'table'
            or exported.state_revision ~= revision or type(exported.bundle_json) ~= 'string'
            or #exported.bundle_json > 2 * 1024 * 1024 or vim.fn.sha256(exported.bundle_json) ~= exported.bundle_sha256 then return end
        local listed = state.last
        vim.ui.input({ prompt = tr('Save supervision bundle to: ', '监督声明保存到：', '監督宣告儲存至：'), default = 'supervision.json' }, function(value)
          local path = path_for(value)
          if not path or not current() or state.last ~= listed then return end
          vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Save new file', '保存新文件', '儲存新檔案') }, {
            prompt = tr('Save rule settings and source identities to ', '保存规则设置与源码身份到 ', '儲存規則設定與原始碼身分至 ') .. path
          }, function(_, choice)
            if choice ~= 2 or not current() or state.last ~= listed then return end
            local fd, open_err = vim.uv.fs_open(path, 'wx', 384)
            if not fd then notify(tostring(open_err), vim.log.levels.ERROR); return end
            local written, write_err = vim.uv.fs_write(fd, exported.bundle_json, 0)
            local ok = written == #exported.bundle_json
            if ok then ok, write_err = vim.uv.fs_fsync(fd) end
            vim.uv.fs_close(fd)
            if not ok then vim.uv.fs_unlink(path); notify(tostring(write_err or 'Incomplete write'), vim.log.levels.ERROR); return end
            notify(tr('Supervision saved: ', '监督声明已保存：', '監督宣告已儲存：') .. path, vim.log.levels.INFO)
          end)
        end)
      end)
      return
    end
    vim.ui.input({ prompt = tr('Supervision bundle to import: ', '要导入的监督声明：', '要匯入的監督宣告：'), default = reference and reference.file or 'supervision.json' }, function(value)
      local path = path_for(value)
      if not path or not current() then return end
      local stat = vim.uv.fs_lstat(path)
      if not stat or stat.type ~= 'file' or stat.size > 2 * 1024 * 1024 then
        notify(tr('Choose a regular bundle file of at most 2 MiB.', '请选择不超过 2 MiB 的普通声明文件。', '請選擇不超過 2 MiB 的一般宣告檔案。'), vim.log.levels.ERROR); return
      end
      if reference and path == path_for(reference.file) then
        local resolved = vim.uv.fs_realpath(path)
        if not resolved or not in_project(project, resolved) then
          notify(tr('The referenced file no longer resolves inside this project.',
            '引用文件当前未解析到项目内。', '參照檔案目前未解析至專案內。'), vim.log.levels.WARN); return
        end
      end
      local file = io.open(path, 'rb')
      if not file then notify(tr('Cannot read bundle.', '无法读取声明。', '無法讀取宣告。'), vim.log.levels.ERROR); return end
      local raw = file:read(2 * 1024 * 1024 + 1); file:close()
      if not raw or #raw > 2 * 1024 * 1024 then return end
      local digest = vim.fn.sha256(raw)
      if reference and path == path_for(reference.file) and digest ~= reference.sha256 then
        notify(tr('The referenced supervision file changed; review and relink it before importing.',
          '引用的监督文件已变化；请审核后重新关联再导入。', '參照的監督檔案已變更；請檢視並重新連結後再匯入。'), vim.log.levels.WARN); return
      end
      local args = { 'model', 'supervise', 'import', '--file', path, '--if-sha256', digest, '--if-state-revision', revision }
      read_metadata(state, tr('Preview supervision import', '预览监督导入', '預覽監督匯入'), args, 'semantic_supervise', function(preview, failure, report_buf, changed)
        local incoming = preview and preview.data
        if failure or changed or not current() or not preview or preview.status ~= 'success' or type(incoming) ~= 'table'
            or incoming.committed ~= false or incoming.bundle_sha256 ~= digest or incoming.state_revision ~= revision
            or type(incoming.marks) ~= 'table' or not is_list(incoming.marks) then return end
        local listed = state.last
        review_gate(report_buf, { tr('Cancel', '取消', '取消'), tr('Import and rebind', '导入并重新绑定', '匯入並重新繫結') },
          tr('Import marks: ', '导入标记数：', '匯入標記數：') .. #incoming.marks
            .. tr('; each needs a fresh forward and rebind.', '；每个标记都需要重新前向并绑定。', '；每個標記都需要重新前向並繫結。'), function(_, choice)
          if choice ~= 2 or not current() or state.last ~= listed then return end
          local apply_args = vim.deepcopy(args); apply_args[#apply_args + 1] = '--apply'
          run(state, tr('Import supervision', '导入监督声明', '匯入監督宣告'), apply_args, function(receipt, problem, _, outdated)
            local result = receipt and receipt.data
            if problem or outdated or not receipt or receipt.status ~= 'success' or type(result) ~= 'table'
                or result.committed ~= true or result.imported ~= #incoming.marks or result.bundle_sha256 ~= digest then
              notify(tr('Import not confirmed; inspect marks.', '导入未获确认，请检查标记。', '匯入未獲確認，請檢查標記。'), vim.log.levels.WARN)
            end
          end, tr('Adds unbound marks and their rules; the bundle and project revision will be checked again.',
            '添加未绑定标记及其规则；再次核对声明文件和项目修订。', '新增未繫結標記及其規則；再次核對宣告檔案和專案修訂。'), true,
            graph_guard and function() return current() end or nil)
        end, nil, true)
      end)
    end)
  end, true)
end

sessions.transfer_supervision = transfer_supervision

local function browse_marks(state, repair)
  read_metadata(state, tr('Browse semantic marks', '浏览语义标记', '瀏覽語義標記'), { 'model', 'marks' }, 'semantic_mark', function(report, err, _, stale)
    local marks = report and type(report.data) == 'table' and report.data.marks
    if err or stale or not report or report.operation ~= 'semantic_mark' or report.status ~= 'success'
        or type(marks) ~= 'table' or not is_list(marks) then return end
    local rows, choices = {}, {}
    for _, mark in ipairs(marks) do
      if type(mark) == 'table' and type(mark.id) == 'string' and mark.id ~= '' then
        rows[#rows + 1] = mark
        local source_status = mark.imported_unbound == true
          and tr('imported; rebind required', '已导入；需要重新绑定', '已匯入；需要重新繫結')
          or mark.binding_status == 'current'
          and tr('source unchanged; binding unverified', '源码未变；绑定未验证', '原始碼未變；繫結未驗證')
          or (mark.binding_status == 'stale' and tr('source stale', '源码已过期', '原始碼已過期')
            or tr('source status unknown', '源码状态未知', '原始碼狀態未知'))
        local variant_hint = type(mark.variant_name_at_binding) == 'string' and #mark.variant_name_at_binding <= 64
          and mark.variant_name_at_binding:match('^[A-Za-z0-9_-]+$') and mark.variant_name_at_binding or nil
        choices[#choices + 1] = mark.id .. '  ·  ' .. tostring(mark.role or '?') .. '  ·  '
          .. tostring(mark.module_path or '?') .. '  ·  ' .. source_status
          .. (type(mark.binding_context) == 'table' and sha256(mark.binding_context.variant_sha256)
            and (variant_hint and (tr(' · variant at binding: ', ' · 绑定时的变体：', ' · 繫結時的變體：') .. variant_hint)
              or tr(' · variant-bound', ' · 绑定变体', ' · 繫結變體')) or '')
      end
    end
    if #rows == 0 then notify(tr('No semantic marks yet.', '尚无语义标记。', '尚無語義標記。'), vim.log.levels.INFO); return end
    local listed = state.last
    vim.ui.select(choices, { prompt = repair
      and tr('Choose a mark to rebind', '选择要重新绑定的标记', '選擇要重新繫結的標記')
      or tr('Choose a mark for a rule', '选择要添加规则的标记', '選擇要新增規則的標記') }, function(_, index)
      local mark = index and rows[index]
      if not mark or state.closed or state.last ~= listed or listed.context_changed then return end
      state.selected_mark = mark.id
      state.selected_mark_record = { mark = vim.deepcopy(mark), revision = report.data.state_revision }
      if repair and not (type(mark.binding_context) == 'table' and sha256(mark.binding_context.variant_sha256)) then
        vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Run forward and choose a new port', '运行前向并选择新端口', '執行前向並選擇新連接埠') }, {
          prompt = tr('Rebind this mark after a new forward? Existing rules will be kept.',
            '运行新的前向后重新绑定此标记？现有规则将保留。', '執行新的前向後重新繫結此標記？現有規則將保留。')
        }, function(_, choice)
          if choice == 2 and not state.closed and state.last == listed and not listed.context_changed
              and state.selected_mark_record and state.selected_mark_record.mark.id == mark.id
              and state.actions and state.actions.p then state.actions.p() end
        end)
        return
      end
      if type(mark.binding_context) == 'table' and sha256(mark.binding_context.variant_sha256) then
        notify(tr('This mark is bound to a variant. Use Z to choose that variant and preview supervision, or d to add a rule. Any recorded name is a hint; the variant revision is checked when used.',
          '此标记绑定变体。按 Z 选择对应变体预览监督，或按 d 添加规则。记录的名称仅供参考，使用时会核对变体修订。',
          '此標記繫結變體。按 Z 選擇對應變體預覽監督，或按 d 新增規則。記錄的名稱僅供參考，使用時會核對變體修訂。'), vim.log.levels.INFO)
        return
      end
      if mark.binding_status == 'unverified' and type(mark.anchor) == 'table'
          and type(mark.anchor.source_file) == 'string' and vim.startswith(mark.anchor.source_file, '@external:') then
        notify(tr('The external source was not imported by the list. Use u to inspect the runtime-identified source file, or d to add a rule with this limitation.',
          '列表未导入外部源码。按 u 核对运行时识别的源码文件，或了解该限制后按 d 添加规则。',
          '清單未匯入外部原始碼。按 u 核對執行時識別的原始碼檔案，或了解該限制後按 d 新增規則。'), vim.log.levels.INFO)
      elseif mark.binding_status ~= 'current' then
        notify(tr('This binding is stale or unknown; re-observe and rebind before using it.',
          '此绑定已过期或状态未知；使用前请重新观察并绑定。', '此繫結已過期或狀態未知；使用前請重新觀察並繫結。'), vim.log.levels.WARN)
      else
        notify(tr('Mark selected. Only its source file was checked; use u to verify the current binding, or d to add a rule.',
          '已选择标记；目前只核对了源码文件。按 u 预览并核对当前绑定，或按 d 添加规则。',
          '已選擇標記；目前只核對了原始碼檔案。按 u 預覽並核對目前繫結，或按 d 新增規則。'), vim.log.levels.INFO)
      end
    end)
  end)
end

local function rebind_mark(state, preferred_port)
  local selection = state.selected_mark_record
  local observation = state.last
  local report = observation and observation.report
  local variant = observation and observation.isolated_variant and observation.variant_context or nil
  local function observation_changed()
    return not observation or (variant and observation.observed_context_changed or (not variant and observation.context_changed))
      or (type(preferred_port) == 'table' and preferred_port.guard and not preferred_port.guard())
  end
  local calls = report and report.operation == 'probe' and report.status == 'success'
    and type(report.data) == 'table' and report.data.calls
  if state.busy or not selection or not sha256(selection.revision) or not observation
      or observation_changed() or observation.historical_observation or type(calls) ~= 'table' or not is_list(calls)
      or report.data.forward_execution ~= 'executed'
      or (type(report.data.evidence_cache) == 'table' and report.data.evidence_cache.status == 'reused') then
    notify(tr('Select a mark with M, then run a fresh forward pass before rebinding.',
      '请先按 M 选择标记，再运行新的前向后重新绑定。', '請先按 M 選擇標記，再執行新的前向後重新繫結。'), vim.log.levels.WARN)
    return
  end
  local rows, choices, truncated = observed_port_choices(calls)
  if #rows == 0 then notify(tr('No observed ports with a readable Python source identity.', '没有具备可读取 Python 源码身份的已观察端口。', '沒有具備可讀取 Python 原始碼身分的已觀察連接埠。'), vim.log.levels.WARN); return end
  local epoch = state.change_epoch or 0
  state.busy = tr('Checking rebind support', '检查重新绑定能力', '檢查重新繫結能力')
  render(state)
  request(state, { '--describe-interface' }, function(interface, err)
    state.busy = nil
    render(state)
    local caps = interface and interface.data and interface.data.capabilities
    if err or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['supervision.conditional_retag'] ~= true
        or caps['supervision.observed_anchor_guard_v1'] ~= true
        or (variant and caps['supervision.conditional_variant_retag_v1'] ~= true) then
      notify(tr('This CLI cannot protect a rebind against concurrent changes.', '当前 CLI 无法防止重新绑定时的并发冲突。', '目前 CLI 無法防止重新繫結時的並行衝突。'), vim.log.levels.WARN); return
    end
    if state.probe_device and caps['supervision.mark_device_v1'] ~= true then
      notify(tr('This CLI cannot use the selected device for rebinding. Update it or clear the forward device.',
        '当前 CLI 无法在重新绑定时使用所选设备；请更新或清除前向设备。', '目前 CLI 無法在重新繫結時使用所選裝置；請更新或清除前向裝置。'), vim.log.levels.WARN); return
    end
    if state.last ~= observation or observation_changed() or state.selected_mark_record ~= selection
        or (state.change_epoch or 0) ~= epoch then return end
    local function select_port(_, index)
      local row = index and rows[index]
      if not row or state.closed then return end
      if vim.startswith(row.anchor.source_file, '@external:') and caps['supervision.external_source_anchor_v1'] ~= true then
        notify(tr('This CLI cannot protect an external source anchor.', '当前 CLI 无法保护外部源码锚点。', '目前 CLI 無法保護外部原始碼錨點。'), vim.log.levels.WARN); return
      end
      if row.path == 'model' and caps['supervision.root_mark_v1'] ~= true then
        notify(tr('This CLI cannot mark the root model; update it before rebinding.', '此 CLI 无法标记根模型，请更新后再重新绑定。', '此 CLI 無法標記根模型，請更新後再重新繫結。'), vim.log.levels.WARN); return
      end
      vim.ui.input({ prompt = tr('Semantic role: ', '语义角色：', '語義角色：'), default = selection.mark.role or '' }, function(role)
        if not role or role == '' or state.closed then return end
        vim.ui.input({ prompt = tr('Meaning: ', '含义：', '意義：'), default = selection.mark.meaning or '' }, function(meaning)
          if not meaning or meaning == '' or state.closed then return end
          if state.last ~= observation or observation_changed() or state.selected_mark_record ~= selection
              or (state.change_epoch or 0) ~= epoch then
            notify(tr('The observation or selection changed; start again.', '观察结果或选择已变化，请重新开始。', '觀察結果或選擇已變更，請重新開始。'), vim.log.levels.WARN); return
          end
          local args = { 'model', 'retag', '--id', selection.mark.id, '--path', row.path, '--port', row.port,
            '--role', role, '--meaning', meaning, '--if-state-revision', selection.revision,
            '--if-anchor', vim.json.encode(row.anchor) }
          if variant then
            vim.list_extend(args, { '--variant', variant.name, '--if-variant-base', variant.base.token })
            if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
            if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
            local names = vim.tbl_keys(state.batch_params or {}); table.sort(names)
            for _, name in ipairs(names) do
              vim.list_extend(args, { '--batch-param', name .. '=' .. vim.json.encode(state.batch_params[name]) })
            end
          end
          run(state, tr('Rebind semantic mark', '重新绑定语义标记', '重新繫結語義標記'), args, function(receipt, failure)
            local data = receipt and receipt.data
            if failure or not receipt or receipt.operation ~= 'semantic_mark' or receipt.status ~= 'success'
                or type(data) ~= 'table' or data.status ~= 'rebound' or type(data.mark) ~= 'table'
                or data.mark.id ~= selection.mark.id or not sha256(data.state_revision) then
              notify(tr('Rebind outcome requires inspection before retry.', '重新绑定结果需要核查后再重试。', '重新繫結結果需要核查後再重試。'), vim.log.levels.WARN)
            else
              state.selected_mark_record = nil
            end
          end, tr('Re-runs a forward pass and updates this mark while preserving its rules, only if the reviewed semantic state is unchanged.',
            '将重新前向并更新此标记、保留其规则；只有查看后的语义状态未变化才会保存。',
            '將重新前向並更新此標記、保留其規則；只有檢視後的語義狀態未變更才會儲存。')
            .. (vim.startswith(row.anchor.source_file, '@external:') and tr(' Only the runtime-identified source file is checked; loaded code, other package files and dependencies are not pinned.',
              ' 仅核对运行时识别的源码文件，已加载代码、其他包文件和依赖未固定。', ' 僅核對執行時識別的原始碼檔案，已載入程式碼、其他套件檔案和依賴未固定。') or '')
            .. (row.port:match('^inputs') and (caps['supervision.post_forward_scope_v1'] == true
              and tr(' Input is observed after the module call; it cannot prevent that call or its side effects.',
                ' 输入在模块调用后观察，不能阻止该调用及其副作用。', ' 輸入在模組呼叫後觀察，不能阻止該呼叫及其副作用。')
              or tr(' This CLI does not report input observation timing; inspect its preview before using the rule.',
                ' 此 CLI 未声明输入观察时机；使用规则前请检查其预览。', ' 此 CLI 未宣告輸入觀察時機；使用規則前請檢查其預覽。')) or ''), variant ~= nil,
            function()
              return state.last == observation and not observation_changed() and state.selected_mark_record == selection
                and (state.change_epoch or 0) == epoch
            end)
        end)
      end)
    end
    if type(preferred_port) == 'table' then
      local match, count = nil, 0
      for index, row in ipairs(rows) do
        if row.path == preferred_port.path and row.port == preferred_port.port then match, count = index, count + 1 end
      end
      if count ~= 1 then
        return notify(tr('The selected port is not uniquely observed; run forward again.', '所选端口未被唯一观察到，请重新运行前向。', '所選連接埠未被唯一觀察到，請重新執行前向。'), vim.log.levels.WARN)
      end
      select_port(nil, match)
    else
      module_picker(tr('Choose the new observed port', '选择新的观察端口', '選擇新的觀察連接埠')
        .. (truncated and tr(' (candidate list truncated)', '（候选列表已截断）', '（候選清單已截斷）') or ''), rows, choices, select_port, nil, true)
    end
  end)
end

local function browse_rules(state)
  read_metadata(state, tr('Browse supervision rules', '浏览监督规则', '瀏覽監督規則'), { 'model', 'supervise', 'rule', 'list' }, 'semantic_supervise', function(report, err, _, stale)
    local rules = report and type(report.data) == 'table' and report.data.rules
    if err or stale or not report or report.operation ~= 'semantic_supervise' or report.status ~= 'success'
        or type(rules) ~= 'table' or not is_list(rules) then return end
    local rows, choices, ids = {}, {}, {}
    for _, rule in ipairs(rules) do
      if type(rule) == 'table' and type(rule.id) == 'string' and rule.id ~= '' then
        rows[#rows + 1] = rule
        ids[rule.id] = (ids[rule.id] or 0) + 1
        choices[#choices + 1] = rule.id .. '  ·  ' .. tostring(rule.kind or '?') .. ' / '
          .. tostring(rule.mode or '?') .. '  ·  ' .. tostring(rule.mark_role or '?')
      end
    end
    if #rows == 0 then notify(tr('No supervision rules yet.', '尚无监督规则。', '尚無監督規則。'), vim.log.levels.INFO); return end
    local listed = state.last
    vim.ui.select(choices, { prompt = tr('Select a rule to inspect or remove', '选择要查看或移除的规则', '選擇要查看或移除的規則') }, function(_, index)
      local rule = index and rows[index]
      if not rule or state.closed or state.last ~= listed or listed.context_changed then return end
      if ids[rule.id] ~= 1 then notify(tr('Rule ID is ambiguous; refresh before editing.', '规则 ID 不唯一，请刷新后再修改。', '規則 ID 不唯一，請重新整理後再修改。'), vim.log.levels.WARN); return end
      local encoded, expected = pcall(vim.json.encode, rule)
      if not encoded then notify('Cannot encode the selected rule.', vim.log.levels.WARN); return end
      local detail = vim.api.nvim_create_buf(false, true)
      vim.bo[detail].buftype, vim.bo[detail].bufhidden, vim.bo[detail].swapfile = 'nofile', 'wipe', false
      local lines = {
        tr('Selected supervision rule', '所选监督规则', '所選監督規則'),
        tr('Rules affect training only when explicitly enabled.', '规则仅在训练时明确启用才生效。', '規則僅在訓練時明確啟用才生效。'),
        tr('→ Copy to another mark [c]', '→ 复制到其他标记 [c]', '→ 複製到其他標記 [c]'),
        tr('− Remove this rule [d]', '− 移除此规则 [d]', '− 移除此規則 [d]'),
        tr('← Close [q]', '← 关闭 [q]', '← 關閉 [q]'), '',
        tr('Bounded details; see the complete report for all fields.', '以下为有界详情；完整字段见完整报告。', '以下為有界詳情；完整欄位見完整報告。'),
      }
      vim.list_extend(lines, vim.split(vim.inspect(bounded_summary(rule)), '\n', { plain = true }))
      vim.api.nvim_buf_set_lines(detail, 0, -1, false, lines)
      vim.bo[detail].modifiable = false
      local opened = pcall(vim.cmd, 'botright split')
      if not opened then opened = pcall(vim.cmd, 'botright vsplit') end
      if not opened then
        pcall(vim.api.nvim_buf_delete, detail, { force = true })
        notify(tr('Cannot open the rule details.', '无法打开规则详情。', '無法開啟規則詳情。'), vim.log.levels.WARN); return
      end
      vim.api.nvim_win_set_buf(0, detail)
      vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = detail, silent = true, desc = 'Close rule details' })
      vim.keymap.set('n', 'c', function()
        if state.closed or state.busy or state.last ~= listed or listed.context_changed or not project_config_current(state) then return end
        if not vim.tbl_contains({ 'finite', 'range', 'batch-alignment', 'custom-validator', 'custom-penalty' }, rule.kind)
            or not vim.tbl_contains({ 'observe', 'require', 'penalty' }, rule.mode)
            or type(report.data.state_revision) ~= 'string' or not sha256(report.data.state_revision) then
          notify(tr('This rule cannot be copied because its type or revision is unavailable.',
            '规则类型或修订不可用，无法复制。', '規則類型或修訂無法使用，無法複製。'), vim.log.levels.WARN); return
        end
        local revision, project, epoch = report.data.state_revision, state.opts.project, state.change_epoch or 0
        local function current()
          return not state.closed and not state.busy and state.opts.project == project
            and (state.change_epoch or 0) == epoch and state.last == listed and not listed.context_changed and project_config_current(state)
        end
        request(state, { '--describe-interface' }, function(interface, failure)
          local caps = interface and type(interface.data) == 'table' and interface.data.capabilities
          if not current() then return end
          if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
              or type(caps) ~= 'table' or caps['supervision.conditional_rule_add_v1'] ~= true then
            notify(tr('The CLI cannot protect rule copying.', '当前 CLI 无法保护规则复制。', '目前 CLI 無法保護規則複製。'), vim.log.levels.WARN); return
          end
          local native_copy = caps['supervision.rule_copy_v1'] == true
          if not native_copy and (rule.kind == 'custom-validator' or rule.kind == 'custom-penalty') then
            notify(tr('Update the CLI and worker to copy custom rules with their pinned source.',
              '请更新 CLI 和 worker，以保留源码身份复制自定义规则。', '請更新 CLI 與 worker，以保留原始碼身分複製自訂規則。'), vim.log.levels.WARN); return
          end
          request(state, { 'model', 'marks' }, function(result, problem)
            local data = result and result.data
            if not current() then return end
            if problem or not result or result.operation ~= 'semantic_mark' or result.status ~= 'success'
                or type(data) ~= 'table' or data.state_revision ~= revision or type(data.marks) ~= 'table' or not is_list(data.marks) then
              notify(tr('Marks or rules changed; reopen the rule list.', '标记或规则已变化，请重新打开规则列表。', '標記或規則已變更，請重新開啟規則清單。'), vim.log.levels.WARN); return
            end
            local targets, labels = {}, {}
            for _, mark in ipairs(data.marks) do
              local external = type(mark) == 'table' and mark.binding_status == 'unverified'
                and type(mark.anchor) == 'table' and type(mark.anchor.source_file) == 'string'
                and vim.startswith(mark.anchor.source_file, '@external:')
              if type(mark) == 'table' and type(mark.id) == 'string' and mark.id ~= '' and mark.id ~= rule.mark_id
                  and (mark.binding_status == 'current' or external) then
                targets[#targets + 1] = mark
                labels[#labels + 1] = mark.id .. ' · ' .. tostring(mark.role or '?') .. ' · ' .. tostring(mark.module_path or '?') .. ' · ' .. tostring(mark.port or '?')
              end
            end
            if #targets == 0 then notify(tr('No available target marks.', '没有可用的目标标记。', '沒有可用的目標標記。'), vim.log.levels.INFO); return end
            vim.ui.select(labels, { prompt = tr('Copy this rule to which mark? Binding will be checked at preview.',
              '将规则复制到哪个标记？预览时会检查绑定。', '將規則複製到哪個標記？預覽時會檢查繫結。') }, function(_, choice)
              local target = choice and targets[choice]
              if not target or not current() then return end
              local args
              if native_copy then
                args = { 'model', 'supervise', 'rule', 'copy', '--id', rule.id, '--mark', target.id, '--if-state-revision', revision }
              else
                args = { 'model', 'supervise', 'rule', 'add', '--mark', target.id,
                  '--kind', rule.kind, '--mode', rule.mode, '--if-state-revision', revision }
                for _, field in ipairs({ {'min', '--min'}, {'max', '--max'}, {'weight', '--weight'}, {'target_path', '--target-path'}, {'axis', '--axis'} }) do
                  local value = rule[field[1]]
                  if value ~= nil and value ~= vim.NIL then vim.list_extend(args, { field[2], tostring(value) }) end
                end
              end
              run(state, tr('Copy supervision rule', '复制监督规则', '複製監督規則'), args, function(receipt, error)
                if error or not receipt or receipt.operation ~= 'semantic_supervise' or receipt.status ~= 'success'
                    or type(receipt.data) ~= 'table' or receipt.data.mark_id ~= target.id
                    or type(receipt.data.rule) ~= 'table' or receipt.data.rule.kind ~= rule.kind or receipt.data.rule.mode ~= rule.mode
                    or (native_copy and (receipt.data.source_rule_id ~= rule.id or not vim.deep_equal(receipt.data.rule.plugin, rule.plugin))) then
                  notify(tr('Copy was not confirmed; inspect the rule list.', '复制未获确认，请检查规则列表。', '複製未獲確認，請檢查規則清單。'), vim.log.levels.WARN)
                end
              end, tr('Creates a new rule with the same settings and pinned source; the target binding still needs a preview.',
                '将按相同设置与源码身份创建新规则；目标绑定仍需预览。', '將依相同設定與原始碼身分建立新規則；目標繫結仍需預覽。')
                .. '\n' .. vim.inspect(bounded_summary(rule)) .. '\n→ ' .. target.id, true)
            end)
          end)
        end)
      end, { buffer = detail, silent = true, desc = 'Copy rule to another mark' })
      vim.keymap.set('n', 'd', function()
        if state.closed or state.last ~= listed or listed.context_changed then
          notify(tr('The rule report is stale; refresh it first.', '规则报告已过期，请先刷新。', '規則報告已過期，請先重新整理。'), vim.log.levels.WARN); return
        end
        local args = { 'model', 'supervise', 'rule', 'remove', '--id', rule.id, '--expected-rule', expected }
        run(state, tr('Remove supervision rule', '移除监督规则', '移除監督規則'), args, function(receipt, failure)
          if failure or not receipt or receipt.status ~= 'success' or receipt.operation ~= 'semantic_supervise'
              or type(receipt.data) ~= 'table' or receipt.data.removed ~= rule.id then
            notify(tr('Rule removal was not acknowledged. Refresh rules before retrying.', '未收到规则移除确认；重试前请刷新规则。', '未收到規則移除確認；重試前請重新整理規則。'), vim.log.levels.WARN)
          end
        end, tr('This removes the selected rule only if its saved contents are unchanged.',
          '只有保存的规则内容未变化时才会移除。', '只有儲存的規則內容未變更時才會移除。'), true)
      end, { buffer = detail, silent = true, desc = 'Remove selected rule' })
      local function activate(row)
        local key = ({ [3] = 'c', [4] = 'd', [5] = 'q' })[row]
        if not key or not vim.api.nvim_buf_is_valid(detail) then return end
        vim.api.nvim_buf_call(detail, function()
          local mapping = vim.fn.maparg(key, 'n', false, true)
          if type(mapping) == 'table' and type(mapping.callback) == 'function' then mapping.callback()
          elseif key == 'q' then vim.cmd('close') end
        end)
      end
      vim.keymap.set('n', '<CR>', function() activate(vim.api.nvim_win_get_cursor(0)[1]) end, { buffer = detail, silent = true })
      for _, mouse_key in ipairs({ '<LeftMouse>', '<2-LeftMouse>', '<3-LeftMouse>', '<4-LeftMouse>' }) do
        vim.keymap.set('n', mouse_key, function()
          local mouse = vim.fn.getmousepos()
          if mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= detail or mouse.line < 3 or mouse.line > 5 then return mouse_key end
          vim.schedule(function()
            if vim.api.nvim_win_is_valid(mouse.winid) and vim.api.nvim_win_get_buf(mouse.winid) == detail then
              vim.api.nvim_set_current_win(mouse.winid); activate(mouse.line)
            end
          end)
          return '<Ignore>'
        end, { buffer = detail, expr = true, silent = true })
      end
    end)
  end)
end

local function discover_entries(state)
  if state.busy then return end
  if #dirty_buffers(state.opts.project) > 0 then
    notify(tr('Save project buffers before scanning disk for entrypoints.', '扫描磁盘入口前请保存项目 buffer。', '掃描磁碟入口前請儲存專案 buffer。'), vim.log.levels.WARN)
    return
  end
  local project, cli, epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
  local previous_last, previous_label = state.last, state.result_label
  local function current()
    return not state.closed and state.opts.project == project and state.opts.cli == cli
      and (state.change_epoch or 0) == epoch
  end
  local discovery_roots = vim.deepcopy(state.opts.project_import_roots or {})
  state.busy = tr('Checking discovery support', '检查入口发现能力', '檢查入口發現能力')
  render(state)
  request(state, { '--describe-interface' }, function(interface, failure, stderr)
    if not current() then
      state.busy = nil; render(state)
      notify(tr('Context changed; scan entrypoints again.', '上下文已变化，请重新扫描入口。', '上下文已變更，請重新掃描入口。'), vim.log.levels.WARN)
      return
    end
    local caps = interface and interface.data and interface.data.capabilities
    if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['project.static_entrypoint_discovery'] ~= true then
      state.busy = nil
      state.last = { report = interface, transport_error = failure, stderr = stderr }
      render(state)
      notify(tr('This CLI cannot scan entrypoints; enter them manually with a, m or b.',
        '当前 CLI 无法扫描入口；可用 a、m 或 b 手动填写。', '目前 CLI 無法掃描入口；可用 a、m 或 b 手動填寫。'), vim.log.levels.WARN)
      return
    end
    local discovery_args = { 'discover' }
    if caps['project.static_entrypoint_discovery_roots_v1'] == true then
      for _, root in ipairs(discovery_roots) do vim.list_extend(discovery_args, { '--import-root', root }) end
    elseif #discovery_roots > 0 then
      notify(tr('This CLI cannot prioritize selected module directories; some candidates may be omitted.',
        '当前 CLI 无法优先扫描所选模块目录，可能遗漏候选。', '目前 CLI 無法優先掃描所選模組目錄，可能遺漏候選。'), vim.log.levels.WARN)
    end
    state.busy = tr('Scanning source names', '扫描源码名称', '掃描原始碼名稱')
    render(state)
    request(state, discovery_args, function(report, err, output)
      state.busy = nil
      if not current() then
        render(state)
        notify(tr('Context changed while scanning; scan entrypoints again.', '扫描期间上下文已变化，请重新扫描入口。', '掃描期間上下文已變更，請重新掃描入口。'), vim.log.levels.WARN)
        return
      end
      state.last = { report = report, transport_error = err, stderr = output,
        scope = tr('Static function and class hints only. Roles, imports, signatures and runtime behavior are not verified.',
          '仅静态列出函数和类；角色、导入、签名及运行行为尚未验证。', '僅靜態列出函式和類別；角色、匯入、簽章及執行行為尚未驗證。'),
        context_changed = (state.change_epoch or 0) ~= epoch or #dirty_buffers(state.opts.project) > 0 }
      render(state)
      local data = report and report.data
      if err or not report or report.operation ~= 'project_discover' or report.status ~= 'success'
          or type(data) ~= 'table' or data.executed_project_code ~= false
          or type(data.candidates) ~= 'table' or not is_list(data.candidates)
          or (caps['project.static_entrypoint_discovery_roots_v1'] == true
            and not vim.deep_equal(data.prioritized_import_roots, discovery_roots)) then
        show_report(state); return
      end
      local rows, aliases, seen_aliases = {}, {}, {}
      for _, item in ipairs(data.candidates) do
        if type(item) == 'table' and type(item.entrypoint) == 'string'
            and ({ model = true, batch = true, step = true, loop = true, callable = true })[item.kind] then
          rows[#rows + 1] = item
          local file = type(item.file) == 'string' and item.file:gsub('\\', '/') or ''
          local attribute = item.entrypoint:match('^[^:]+:([^:]+)$')
          if not identifier_candidate(attribute) then attribute = nil end
          for _, root in ipairs(discovery_roots) do
            local prefix = root .. '/'
            if #aliases < 256 and attribute and file:sub(1, #prefix) == prefix and file:sub(-3) == '.py' then
              local relative = file:sub(#prefix + 1, -4)
              if relative:sub(-9) == '/__init__' then relative = relative:sub(1, -10) end
              local parts = vim.split(relative, '/', { plain = true })
              local valid = #parts > 0 and relative ~= '__init__'
              for _, part in ipairs(parts) do
                if not module_part_candidate(part) then valid = false; break end
              end
              local entrypoint = valid and (table.concat(parts, '.') .. ':' .. attribute) or nil
              local key = entrypoint and (item.kind .. '\0' .. entrypoint .. '\0' .. file) or nil
              if entrypoint and entrypoint ~= item.entrypoint and not seen_aliases[key] then
                seen_aliases[key] = true
                local alternative = vim.deepcopy(item)
                alternative.entrypoint, alternative.import_root = entrypoint, root
                aliases[#aliases + 1] = alternative
              end
            end
          end
        end
      end
      vim.list_extend(rows, aliases)
      if #rows == 0 then
        notify(tr('No callable suggestions were found in the scanned files. Review scan limits or enter a factory manually.',
          '已扫描文件中未发现函数候选；请查看扫描范围或手动填写工厂。', '已掃描檔案中未發現函式候選；請查看掃描範圍或手動填寫工廠。'), vim.log.levels.INFO)
        show_report(state); return
      end
      show_report(state)
      local listed = state.last
      local changed = false
      local filter = ''
      local function choose_more()
        if state.closed or state.last ~= listed or listed.context_changed then return end
        if (state.change_epoch or 0) ~= epoch or #dirty_buffers(state.opts.project) > 0 then
          listed.context_changed = true
          notify(tr('Project changed during discovery; scan again.', '入口扫描期间项目发生变化，请重新扫描。', '入口掃描期間專案發生變更，請重新掃描。'), vim.log.levels.WARN)
          render(state); return
        end
        local choices = { tr('Done selecting', '完成选择', '完成選擇'),
          tr('Filter candidates', '筛选候选', '篩選候選') .. (filter ~= '' and (': ' .. filter) or '') }
        local visible = {}
        for _, item in ipairs(rows) do
          local searchable = (item.kind .. ' ' .. item.entrypoint .. ' ' .. tostring(item.file or '')
            .. ' ' .. tostring(item.import_root or '')):lower()
          if filter == '' or searchable:find(filter:lower(), 1, true) then
            visible[#visible + 1] = item
            choices[#choices + 1] = (state[item.kind] == item.entrypoint and '✓ ' or '  ')
              .. item.kind .. ' · ' .. item.entrypoint .. ' · ' .. tostring(item.file or '?') .. ':' .. tostring(item.line or '?')
              .. (item.import_root and (' · ' .. tr('via ', '模块目录 ', '模組目錄 ') .. item.import_root) or '')
          end
        end
        vim.ui.select(choices, { prompt = tr('Unverified name hints; choose model and input, then finish',
          '名称候选尚未验证；可分别选择模型和输入，再完成选择', '名稱候選尚未驗證；可分別選擇模型和輸入，再完成選擇') }, function(_, index)
          if state.closed or state.last ~= listed or listed.context_changed then return end
          if not index or index == 1 then
            if changed then
              listed.context_changed = true
              state.result_label = tr('candidates selected; not verified', '已选择候选；尚未验证', '已選擇候選；尚未驗證')
              render(state)
              if state.project_status == 'unconfigured' then
                notify(tr('Candidates are session choices, not verified. Use a to save setup, then p to run a forward.',
                  '候选仅在本会话生效，尚未验证。按 a 保存接入配置，之后可按 p 前向。',
                  '候選僅在本工作階段生效，尚未驗證。按 a 儲存接入設定，之後可按 p 前向。'), vim.log.levels.INFO)
              else
                notify(tr('Candidates are session choices, not verified. Use Q or S to save model or input defaults, or p to run a forward.',
                  '候选仅在本会话生效，尚未验证。按 Q 或 S 保存模型或输入默认值，或按 p 前向。',
                  '候選僅在本工作階段生效，尚未驗證。按 Q 或 S 儲存模型或輸入預設值，或按 p 前向。'), vim.log.levels.INFO)
              end
            else
              -- A read-only scan that did not change selection should not
              -- replace the model result the user was working with.
              state.last, state.result_label = previous_last, previous_label
              render(state)
            end
            return
          end
          if index == 2 then
            vim.ui.input({ prompt = tr('Filter by name, file, role or import root (empty clears): ',
              '按名称、文件、角色或模块目录筛选（留空清除）：', '按名稱、檔案、角色或模組目錄篩選（留空清除）：'), default = filter }, function(value)
              if state.closed or state.last ~= listed or listed.context_changed then return end
              if value == nil then choose_more(); return end
              if #value > 256 or value:find('[\r\n%z\1-\31\127]') then
                notify(tr('Use at most 256 bytes of single-line text.', '请输入不超过 256 字节的单行文字。', '請輸入不超過 256 位元組的單行文字。'), vim.log.levels.WARN)
              else filter = vim.trim(value) end
              choose_more()
            end)
            return
          end
          local selected = visible[index - 2]
          if not selected then return end
          local function assign(role)
            if state.closed or state.last ~= listed or listed.context_changed then return end
            if (state.change_epoch or 0) ~= epoch or #dirty_buffers(state.opts.project) > 0 then
              listed.context_changed = true; render(state); return
            end
            if state[role] ~= selected.entrypoint then
              if role == 'model' or role == 'batch' then
                switch_factory(state, role, selected.entrypoint)
              else
                state[role] = selected.entrypoint
              end
              epoch = epoch + 1
              state.change_epoch = epoch
              state.journey = nil
            end
            if role == 'model' then
              state.auto_opened_source = nil
              -- Discovery is a static hint, not proof of the imported module.
              -- Retain its source only as an editable-file suggestion.
              state.discovered_model_source = type(selected.file) == 'string' and {
                project = state.opts.project, entrypoint = selected.entrypoint, file = selected.file,
              } or nil
            end
            changed = true
            render(state)
            choose_more()
          end
          if selected.kind ~= 'callable' then assign(selected.kind); return end
          vim.ui.select({ 'model', 'batch', 'step', 'loop' }, {
            prompt = tr('Choose a role for this unverified callable: ', '为未验证的可调用对象选择角色：', '為未驗證的可呼叫物件選擇角色：') .. selected.entrypoint,
            format_item = function(role)
              return ({ model = tr('Model factory', '模型工厂', '模型工廠'),
                batch = tr('Input factory', '输入工厂', '輸入工廠'),
                step = tr('Training step', '训练步骤', '訓練步驟'),
                loop = tr('Training loop', '训练循环', '訓練迴圈') })[role]
            end,
          }, function(role)
            if role then assign(role) end
          end)
        end)
      end
      choose_more()
    end)
  end)
end

local function capability_overview(state)
  if state.busy then return end
  local project, cli, epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
  local inspected = state.last
  local config = project_config(state.opts.project) or {}
  local source_buffer = state.code_buf and vim.api.nvim_buf_is_valid(state.code_buf) and state.code_buf or nil
  if not source_buffer and state.code_win and vim.api.nvim_win_is_valid(state.code_win) then
    local candidate = vim.api.nvim_win_get_buf(state.code_win)
    if candidate ~= state.panel and vim.api.nvim_buf_is_valid(candidate) and vim.bo[candidate].buftype == '' then
      source_buffer = candidate
    end
  end
  state.busy = tr('Reading CLI capabilities', '读取 CLI 能力', '讀取 CLI 能力')
  render(state)
  request(state, { '--describe-interface' }, function(report, err, stderr)
    state.busy = nil
    render(state)
    if state.closed or state.opts.project ~= project or state.opts.cli ~= cli or (state.change_epoch or 0) ~= epoch then
      notify(tr('Context changed; reopen the capability overview.', '上下文已变化，请重新打开能力概览。', '上下文已變更，請重新開啟能力概覽。'), vim.log.levels.WARN)
      return
    end
    local capabilities = report and report.data and report.data.capabilities
    local unavailable = err or not report or report.operation ~= 'interface'
      or report.status ~= 'success' or type(capabilities) ~= 'table'
    if unavailable then capabilities = {} end
    local lines = {
      tr('Capability and evidence overview', '能力与证据概览', '能力與證據概覽'), '',
      tr('These are CLI declarations, not proof that this model supports them.',
        '以下是 CLI 声明，不代表当前模型一定支持。', '以下是 CLI 宣告，不代表目前模型一定支援。'), '',
    }
    if unavailable then
      lines[#lines + 1] = tr('Capability information is unavailable for this CLI; declarations are unknown. Existing operations may still be tried explicitly.',
        '此 CLI 的能力信息不可用；声明状态为未知，仍可明确尝试已有操作。',
        '此 CLI 的能力資訊無法使用；宣告狀態為未知，仍可明確嘗試既有操作。')
      local detail = stderr and stderr ~= '' and stderr or (type(err) == 'table' and err.message or nil)
      if detail and detail ~= '' then
        lines[#lines + 1] = tr('CLI detail: ', 'CLI 详情：', 'CLI 詳情：')
          .. vim.fn.strcharpart(tostring(detail):gsub('[%c]', ' '), 0, 512)
      end
      lines[#lines + 1] = ''
    end
    local entries = {
      { 'project.static_entrypoint_discovery', tr('Static entrypoint suggestions', '静态入口候选', '靜態入口候選') },
      { 'project.custom_scaffold', tr('Editable custom starter', '可编辑自定义骨架', '可編輯自訂骨架') },
      { 'probe.force_fresh_environment', tr('Request a new forward', '请求执行新前向', '要求執行新前向') },
      { 'assembly.atomic_patch', tr('Multi-part assembly preview', '多项装配预览', '多項裝配預覽') },
      { 'edit.conditional_source_plan', tr('Guarded source edit', '条件源码编辑', '條件原始碼編輯') },
      { 'training.conditional_config_start', tr('Training configuration guard', '训练配置保护', '訓練設定保護') },
      { 'training.conditional_supervision', tr('Supervision revision guard', '监督修订保护', '監督修訂保護') },
      { 'training.conditional_resume_checkpoint', tr('Checkpoint identity guard', '续训检查点身份保护', '續訓檢查點身分保護') },
    }
    for _, entry in ipairs(entries) do
      lines[#lines + 1] = entry[2] .. ': ' .. (capabilities[entry[1]] == true
        and tr('declared', '已声明', '已宣告') or tr('not advertised / unknown', '未声明 / 未知', '未宣告 / 未知'))
    end
    lines[#lines + 1] = tr('[C] View all reported CLI capabilities', '[C] 查看全部已报告 CLI 能力', '[C] 查看全部已回報 CLI 能力')
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Current model evidence', '当前模型证据', '目前模型證據')
    local current = inspected == state.last and inspected and not inspected.context_changed and inspected.report or nil
    if current and current.status == 'success' and (current.operation == 'inspect' or current.operation == 'layers')
        and type(current.data) == 'table' and type(current.data.modules) == 'table' then
      local total, editable, insertable = 0, 0, 0
      for _, item in ipairs(current.data.modules) do
        if type(item) == 'table' then
          total = total + 1
          if item.can_source_set == true then editable = editable + 1 end
          if item.can_source_insert == true then insertable = insertable + 1 end
        end
      end
      lines[#lines + 1] = tr('Inspected modules: ', '已检查模块数：', '已檢查模組數：') .. total
      lines[#lines + 1] = tr('Source parameter edits advertised: ', '报告可源码改参的模块数：', '回報可原始碼改參的模組數：') .. editable
      lines[#lines + 1] = tr('Source insertion containers advertised: ', '报告可源码插入的容器数：', '回報可原始碼插入的容器數：') .. insertable
      lines[#lines + 1] = tr('These are reported candidates; preview still determines whether the requested edit is safe.',
        '这些只是报告中的候选；具体修改仍需预览判断。', '這些只是報告中的候選；具體修改仍需預覽判斷。')
    elseif current and current.operation == 'probe' then
      lines[#lines + 1] = tr('Last forward result: ', '最近前向结果：', '最近前向結果：') .. tostring(current.status)
      local execution = type(current.data) == 'table' and current.data.forward_execution or nil
      if type(current.data) == 'table' and type(current.data.evidence_cache) == 'table'
          and current.data.evidence_cache.status == 'reused' then execution = 'reused' end
      lines[#lines + 1] = tr('Forward execution: ', '前向执行：', '前向執行：')
        .. (execution == 'executed' and tr('newly executed', '本次执行', '本次執行')
          or (execution == 'reused' and tr('previous evidence reused', '复用先前证据', '重用先前證據')
            or tr('unknown', '未知', '未知')))
      lines[#lines + 1] = tr('Only observed input and paths are covered; unobserved paths remain unknown.',
        '只覆盖观察到的输入和路径；未观察路径仍为未知。', '只涵蓋觀察到的輸入和路徑；未觀察路徑仍為未知。')
    elseif current and current.status == 'success' and current.operation == 'training_probe' then
      lines[#lines + 1] = tr('A current training trial is available; its reported coverage appears below.',
        '已有当前训练试跑；其报告的覆盖范围见下方。', '已有目前訓練試跑；其回報的涵蓋範圍見下方。')
    else
      lines[#lines + 1] = tr('No current instance evidence. Inspect or run a forward pass after confirmation.',
        '没有当前模型实例证据；可在确认后检查或前向。', '沒有目前模型實例證據；可在確認後檢查或前向。')
    end
    local preflight = capability_preflight.summarize(capabilities, current, current ~= nil, source_buffer)
    local candidate = { state = 'unknown', can_edit = false }
    if current and type(current.data) == 'table' and type(current.data.modules) == 'table' then
      for _, module in ipairs(current.data.modules) do
        if type(module) == 'table' and (module.can_source_set == true or module.can_source_insert == true) then
          candidate = { state = 'observed', can_edit = true, module = module.path }
          break
        end
      end
    end
    local edit_route = capability_preflight.edit_decision(capabilities, candidate,
      { safe = false, current = false }, current ~= nil, source_buffer)
    local state_labels = {
      declared = tr('declared', '已声明', '已宣告'), observed = tr('observed', '已观察', '已觀察'),
      reused = tr('reused', '已复用', '已重用'), conditional = tr('conditional', '有条件', '有條件'),
      unsupported = tr('unsupported', '不支持', '不支援'), unknown = tr('unknown', '未知', '未知'),
    }
    local kind_labels = { structure = tr('structure', '结构', '結構'),
      forward_execution = tr('forward', '前向', '前向'), training_probe = tr('training trial', '训练试跑', '訓練試跑') }
    local instance_reasons = {
      ['No current instance report.'] = tr('No current instance report.', '没有当前实例报告。', '沒有目前執行個體報告。'),
      ['Candidates are report-specific; each requested edit still requires preview.'] = tr('Candidates are report-specific; each edit still requires preview.', '候选仅适用于该报告；每项修改仍需预览。', '候選僅適用於該報告；每項修改仍需預覽。'),
      ['Evidence covers only observed inputs and paths; other branches remain unknown.'] = tr('Evidence covers observed inputs and paths; other branches remain unknown.', '证据只覆盖已观察输入和路径；其他分支未知。', '證據只涵蓋已觀察輸入和路徑；其他分支未知。'),
      ['This is evidence from the reported trial only; it does not establish behavior for other inputs or unreported supervision seams.'] = tr('This trial does not establish behavior for other inputs or unreported supervision.', '本次试跑不能证明其他输入或未报告的监督行为。', '本次試跑不能證明其他輸入或未回報的監督行為。'),
      ['The report is stale or belongs to another model context.'] = tr('The report is stale or belongs to another model context.', '报告已过期或属于其他模型上下文。', '報告已過期或屬於其他模型上下文。'),
    }
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('Normalized capability and evidence states', '归一化能力与证据状态', '標準化能力與證據狀態')
    for _, entry in ipairs(preflight.declarations) do
      local scope = entry.scope == 'cli_or_runtime' and tr('CLI / runtime', 'CLI / 运行时', 'CLI / 執行階段') or tostring(entry.scope)
      lines[#lines + 1] = entry.id .. ' · ' .. scope .. ' · ' .. (state_labels[entry.state] or tr('unknown', '未知', '未知'))
    end
    lines[#lines + 1] = tr('Model-instance evidence: ', '模型实例证据：', '模型執行個體證據：')
      .. (kind_labels[preflight.instance.kind] or tr('unknown', '未知', '未知')) .. ' · '
      .. (state_labels[preflight.instance.state] or tr('unknown', '未知', '未知')) .. ' · '
      .. (instance_reasons[preflight.instance.reason] or tostring(preflight.instance.reason or ''))
    if preflight.instance.kind == 'training_probe' then
      local instance = preflight.instance
      lines[#lines + 1] = tr('Observed training mode: ', '本次训练模式：', '本次訓練模式：')
        .. tostring(instance.training_mode or 'unknown')
      for _, entry in ipairs({
        { 'forward_contract', tr('Forward contract', '前向契约', '前向契約') },
        { 'loss_contract', tr('Loss contract', '损失契约', '損失契約') },
        { 'backward_and_optimizer_updates', tr('Backward and optimizer updates', '反向传播与优化器更新', '反向傳播與最佳化器更新') },
        { 'resume_cursor', tr('Resume cursor', '续训位置', '續訓位置') },
      }) do
        local seam = instance.training_seams[entry[1]]
        lines[#lines + 1] = entry[2] .. ': ' .. (seam and seam.value or 'unknown')
      end
      local supervision = instance.supervision
      lines[#lines + 1] = tr('Supervision in this trial: ', '本次试跑监督：', '本次試跑監督：')
        .. tostring(supervision.status or supervision.state or 'unknown')
        .. tr('; reported rules: ', '；报告规则数：', '；回報規則數：') .. tostring(supervision.rule_count or 'unknown')
        .. tr('; coverage: ', '；覆盖：', '；涵蓋：') .. tostring(supervision.coverage_status or 'unknown')
      if instance.reported_coverage_limit then
        lines[#lines + 1] = tr('Reported trial coverage: ', '试跑覆盖说明：', '試跑涵蓋說明：') .. instance.reported_coverage_limit
      end
    else
      lines[#lines + 1] = tr('Training and supervision seams: unknown until a current trial reports them.',
        '训练和监督接缝：当前试跑报告提供前为未知。', '訓練和監督接縫：目前試跑報告提供前為未知。')
    end
    lines[#lines + 1] = tr('Input binding source: ', '输入绑定来源：', '輸入繫結來源：')
      .. (state.batch_binding and (state.batch_binding .. tr(' (session selection)', '（会话选择）', '（工作階段選擇）'))
        or (state.batch and tr('automatic for session input; actual binding depends on the input',
          '会话输入自动选择；实际绑定取决于输入', '工作階段輸入自動選擇；實際繫結取決於輸入'))
        or (config and config.batch_binding and (tostring(config.batch_binding) .. tr(' (project configuration)', '（项目配置）', '（專案設定）')))
        or tr('automatic or not reported; source unknown', '自动或未报告；来源未知', '自動或未回報；來源未知'))
    local current_data = current and type(current.data) == 'table' and current.data or nil
    local provenance_input = current_data and type(current_data.run_provenance) == 'table'
      and type(current_data.run_provenance.input) == 'table' and current_data.run_provenance.input or nil
    local adapter_observation = provenance_input and type(provenance_input.data_observation) == 'table'
      and provenance_input.data_observation or nil
    if adapter_observation then
      local function safe_provenance(value)
        return type(value) == 'string' and vim.fn.strcharpart(value:gsub('[\r\n%z\1-\31\127]', ' '), 0, 128) or 'unknown'
      end
      lines[#lines + 1] = tr('Observed adapter / version / source digest: ', '已观察适配器 / 版本 / 来源摘要：', '已觀察配接器 / 版本 / 來源摘要：')
        .. safe_provenance(adapter_observation.adapter) .. ' / '
        .. safe_provenance(adapter_observation.adapter_version) .. ' / '
        .. safe_provenance(adapter_observation.source_sha256)
    else
      lines[#lines + 1] = tr('Observed adapter provenance: unknown until a current Probe report provides it.',
        '当前 Probe 报告提供前，实际适配器来源未知。', '目前 Probe 報告提供前，實際配接器來源未知。')
    end
    lines[#lines + 1] = tr('Manual source handoff: ', '手工源码接管：', '手動原始碼接管：')
      .. (preflight.manual_source.available and tr('available in source buffer ', '可返回源码 buffer ', '可返回原始碼 buffer ') .. tostring(source_buffer)
        or tr('source buffer unavailable', '源码 buffer 不可用', '原始碼 buffer 無法使用'))
      .. tr('; preview and revalidation are still required.', '；仍须预览并重验。', '；仍須預覽並重新驗證。')
    local edit_modes = { manual_source = tr('manual source', '手工源码编辑', '手動原始碼編輯'),
      automatic_candidate = tr('automatic candidate', '自动候选', '自動候選') }
    local edit_reasons = {
      ['Model or source evidence is stale; automatic editing is not authorized.'] = tr('Model or source evidence is stale; automatic editing is not authorized.', '模型或源码证据已过期，不能自动编辑。', '模型或原始碼證據已過期，不能自動編輯。'),
      ['The CLI did not declare the required guarded source-edit capabilities.'] = tr('The CLI did not declare the required guarded source-edit capabilities.', 'CLI 未声明所需的条件源码编辑能力。', 'CLI 未宣告所需的條件原始碼編輯能力。'),
      ['This model instance did not report an editable source candidate.'] = tr('This model instance did not report an editable source candidate.', '此模型实例未报告可编辑的源码候选。', '此模型執行個體未回報可編輯的原始碼候選。'),
      ['A fresh successful preview for this candidate and source revision is missing.'] = tr('A fresh successful preview for this candidate and source revision is missing.', '缺少此候选和源码修订的最新成功预览。', '缺少此候選和原始碼修訂的最新成功預覽。'),
      ['The exact edit still requires the normal apply confirmation and revision guard.'] = tr('The exact edit still requires confirmation and a revision guard.', '具体修改仍需确认并核对修订。', '具體修改仍需確認並核對修訂。'),
    }
    lines[#lines + 1] = tr('Automatic edit decision: ', '自动编辑判定：', '自動編輯判定：')
      .. (edit_modes[edit_route.mode] or tr('unknown', '未知', '未知')) .. ' · '
      .. (edit_reasons[edit_route.reason] or tostring(edit_route.reason or ''))
    lines[#lines + 1] = ''
    lines[#lines + 1] = tr('[m] Return to the source buffer; [q] close. From the workspace, [o] opens a file.',
      '[m] 返回源码 buffer；[q] 关闭。工作区中可按 [o] 打开文件。', '[m] 返回原始碼 buffer；[q] 關閉。工作區中可按 [o] 開啟檔案。')
    lines[#lines + 1] = tr('[d] Check the selected Python and its runtime capabilities after confirmation.',
      '[d] 确认后检查所选 Python 及其运行时能力。', '[d] 確認後檢查所選 Python 及其執行階段能力。')
    local function reuse_label()
      return state.confirmation_reuse_enabled
        and tr('[r] Session confirmation reuse: on (press to disable and revoke)',
          '[r] 会话确认复用：已开启（按下关闭并撤销授权）', '[r] 工作階段確認重用：已開啟（按下關閉並撤銷授權）')
        or tr('[r] Session confirmation reuse: off (press to enable)',
          '[r] 会话确认复用：已关闭（按下开启）', '[r] 工作階段確認重用：已關閉（按下開啟）')
    end
    lines[#lines + 1] = reuse_label()
    local reuse_line = #lines - 1
    local buf = vim.api.nvim_create_buf(false, true)
    vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
    vim.bo[buf].modifiable = false
    if not open_aux_buffer(buf, false, false) then return end
    vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close capability overview' })
    vim.keymap.set('n', 'C', function()
      if state.closed or state.opts.project ~= project or state.opts.cli ~= cli or (state.change_epoch or 0) ~= epoch then
        notify(tr('Context changed; reopen the capability overview.', '上下文已变化，请重新打开能力概览。', '上下文已變更，請重新開啟能力概覽。'), vim.log.levels.WARN); return
      end
      local names = {}
      for name in pairs(capabilities) do
        if type(name) == 'string' and #name <= 256 and not name:find('[%c]') then names[#names + 1] = name end
      end
      table.sort(names)
      local all = { tr('Reported CLI capabilities · declarations only', '报告的 CLI 能力 · 仅为声明', '回報的 CLI 能力 · 僅為宣告'),
        tr('[q] Close', '[q] 关闭', '[q] 關閉'), '' }
      for index, name in ipairs(names) do
        if index > 2048 then
          all[#all + 1] = tr('Further capabilities are omitted.', '更多能力已省略。', '更多能力已省略。'); break
        end
        all[#all + 1] = name .. ': ' .. (capabilities[name] == true
          and tr('declared', '已声明', '已宣告') or tr('not advertised / unknown', '未声明 / 未知', '未宣告 / 未知'))
      end
      if #names == 0 then all[#all + 1] = tr('No capabilities were reported.', '未报告能力。', '未回報能力。') end
      local detail = vim.api.nvim_create_buf(false, true)
      vim.bo[detail].buftype, vim.bo[detail].bufhidden, vim.bo[detail].swapfile = 'nofile', 'wipe', false
      vim.api.nvim_buf_set_lines(detail, 0, -1, false, all)
      vim.bo[detail].modifiable = false
      if open_aux_buffer(detail, false, false) then
        vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = detail, silent = true, desc = 'Close CLI capabilities' })
      end
    end, { buffer = buf, silent = true, desc = 'View all reported CLI capabilities' })
    vim.keymap.set('n', 'd', function()
      run(state, tr('Check selected Python runtime', '检查所选 Python 环境', '檢查所選 Python 環境'),
        { 'doctor' }, function() show_report(state) end, nil, true)
    end, { buffer = buf, silent = true, desc = 'Check selected Python runtime' })
    vim.keymap.set('n', 'm', function()
      if source_buffer and vim.api.nvim_buf_is_valid(source_buffer) then
        local target = state.code_win
        if target and vim.api.nvim_win_is_valid(target) and target ~= vim.api.nvim_get_current_win()
            and vim.api.nvim_win_get_buf(target) == source_buffer then
          local overview = vim.api.nvim_get_current_win()
          vim.api.nvim_set_current_win(target)
          if vim.api.nvim_win_is_valid(overview) and vim.api.nvim_win_get_buf(overview) == buf then
            pcall(vim.api.nvim_win_close, overview, false)
          end
        else
          vim.api.nvim_win_set_buf(0, source_buffer)
        end
      else
        notify(tr('The original source buffer is no longer available.', '原源码 buffer 已不可用。', '原始碼 buffer 已無法使用。'), vim.log.levels.WARN)
      end
    end, { buffer = buf, silent = true, desc = 'Return to same source buffer for manual editing' })
    vim.keymap.set('n', 'r', function()
      state.confirmation_reuse_enabled = not state.confirmation_reuse_enabled
      if not state.confirmation_reuse_enabled then confirmation.revoke() end
      if vim.api.nvim_buf_is_valid(buf) then
        vim.bo[buf].modifiable = true
        vim.api.nvim_buf_set_lines(buf, reuse_line, reuse_line + 1, false, { reuse_label() })
        vim.bo[buf].modifiable = false
      end
      notify(state.confirmation_reuse_enabled
        and tr('Session reuse enabled. The workspace asks for per-run confirmation whenever the operation or its identity cannot be verified for reuse.',
          '已启用会话复用。操作或身份无法复核时仍逐次确认。',
          '已啟用工作階段重用。操作或身分無法複核時仍逐次確認。')
        or tr('Session confirmation reuse disabled and all grants revoked.', '已关闭会话确认复用并撤销全部授权。', '已關閉工作階段確認重用並撤銷全部授權。'))
    end, { buffer = buf, silent = true, desc = 'Toggle exact-scope confirmation reuse' })
  end)
end

local function save_project_python(state, clear)
  local project, epoch, selected = state.opts.project, state.change_epoch or 0, state.opts.python
  local revision = state.project_info and state.project_info.config_revision
  if not sha256(revision) or (not clear and not selected) then
    notify(tr('Choose a session Python and open a configured project first.', '请先选择会话 Python 并打开已配置的项目。', '請先選擇工作階段 Python 並開啟已設定的專案。'), vim.log.levels.WARN); return
  end
  local function current()
    return not state.closed and not state.busy and state.opts.project == project and state.opts.python == selected
      and (state.change_epoch or 0) == epoch and state.project_info and state.project_info.config_revision == revision
      and project_config_current(state)
  end
  state.busy = tr('Checking Python configuration support', '检查 Python 配置能力', '檢查 Python 設定能力'); render(state)
  request(state, { '--describe-interface' }, function(interface, err)
    state.busy = nil
    if err or not current() or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(interface.data) ~= 'table' or type(interface.data.capabilities) ~= 'table'
        or interface.data.capabilities['runtime.project_python_config_v1'] ~= true then
      render(state); notify(tr('A compatible CLI is required; no configuration was saved.', '需要兼容的 CLI；配置未保存。', '需要相容的 CLI；設定未儲存。'), vim.log.levels.WARN); return
    end
    local args = { 'config', 'set-python' }
    if clear then args[#args + 1] = '--clear' else vim.list_extend(args, { '--executable', selected }) end
    state.busy = tr('Previewing Python choice', '预览 Python 选择', '預覽 Python 選擇'); render(state)
    request(state, args, function(report, failure, stderr)
      state.busy = nil
      if not current() then
        render(state)
        notify(tr('Context changed; preview the Python choice again.', '上下文已变化，请重新预览 Python 选择。', '上下文已變更，請重新預覽 Python 選擇。'), vim.log.levels.WARN)
        return
      end
      state.last = { report = report, transport_error = failure, stderr = stderr }
      local data = report and report.data
      local python = type(data) == 'table' and data.runtime_python or nil
      if python == vim.NIL then python = nil end
      if failure or not report or report.operation ~= 'config_set_python' or report.status ~= 'success'
          or type(data) ~= 'table' or data.committed ~= false or data.from_revision ~= revision
          or python ~= (not clear and selected or nil) or type(data.redacted_fields) ~= 'table' or #data.redacted_fields > 0 then
        render(state); show_report(state); return
      end
      local preview = state.last
      local buf = show_report(state)
      if data.unchanged then
        if not clear then
          state.opts.python = nil
          state.change_epoch = (state.change_epoch or 0) + 1
          state.journey = nil
          state.last.context_changed = true; state.last.observed_context_changed = true
        end
        refresh_project(state); return
      end
      review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Save', '保存', '儲存') },
        tr('Save this project Python selection? Future runs may use it.', '保存此项目 Python 选择？后续运行可能使用它。', '儲存此專案 Python 選擇？後續執行可能使用它。'), function(_, choice)
        if choice ~= 2 or not current() or state.last ~= preview then return end
        local apply = vim.deepcopy(args); vim.list_extend(apply, { '--apply', '--if-current', revision })
        local tracked = begin_tracked_commit(state, tr('Save project Python', '保存项目 Python', '儲存專案 Python'))
        if not tracked then return end
        state.busy = tr('Saving Python choice', '保存 Python 选择', '儲存 Python 選擇'); render(state)
        request(state, apply, function(receipt, problem, output)
          state.busy = nil
          local same_context = tracked_commit_current(state, tracked) and state.opts.python == selected
          if same_context then state.last = { report = receipt, transport_error = problem, stderr = output } end
          local saved = receipt and receipt.data
          local saved_python = type(saved) == 'table' and saved.runtime_python or nil
          if saved_python == vim.NIL then saved_python = nil end
          local verified = not problem and receipt and receipt.operation == 'config_set_python' and receipt.status == 'success'
              and type(saved) == 'table' and saved.committed == true and saved.from_revision == revision
              and sha256(saved.config_revision) and saved_python == python
          local settled = settle_tracked_commit(state, tracked, verified, problem)
          if not same_context then
            render(state)
            notify(tr('Python save finished in the original project; reopen it to inspect the result.',
              'Python 保存操作已在原项目结束；请返回原项目核查结果。', 'Python 儲存操作已在原專案結束；請返回原專案核查結果。'), vim.log.levels.WARN)
            return
          end
          if verified and settled then
            if not clear then state.opts.python = nil end
            state.change_epoch = (state.change_epoch or 0) + 1
            state.journey = nil
            state.result_label = tr('project Python saved; recheck', '项目 Python 已保存，请重验', '專案 Python 已儲存，請重驗')
          else
            state.result_label = tr('save outcome requires inspection', '保存结果待核查', '儲存結果待核查')
          end
          refresh_project(state); show_report(state)
        end)
      end)
    end)
  end)
end

local function choose_runtime_paths(state)
  if state.busy or state.closed then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local old_directory, old_roots = state.opts.working_directory, vim.deepcopy(state.opts.project_import_roots)
  local old_override = state.opts.runtime_paths_override
  state.busy = tr('Checking runtime path support', '检查运行时路径能力', '檢查執行階段路徑能力')
  render(state)
  request(state, { '--describe-interface' }, function(report, err)
    state.busy = nil
    render(state)
    if err or not report or report.status ~= 'success' or report.operation ~= 'interface'
        or type(report.data) ~= 'table' or type(report.data.capabilities) ~= 'table'
        or report.data.capabilities['runtime.workspace_paths_v1'] ~= true then
      notify(tr('This CLI does not support session runtime paths.', '此 CLI 不支持本会话运行时路径。', '此 CLI 不支援本工作階段執行階段路徑。'), vim.log.levels.WARN); return
    end
    local function current()
      return not state.closed and not state.busy and state.opts.project == project and (state.change_epoch or 0) == epoch
        and state.opts.working_directory == old_directory and vim.deep_equal(state.opts.project_import_roots, old_roots)
        and state.opts.runtime_paths_override == old_override
    end
    if not current() then return end
    vim.ui.select({ tr('Set working directory', '设置运行目录', '設定執行目錄'),
      tr('Set project import roots', '设置项目模块搜索目录', '設定專案模組搜尋目錄'),
      tr('Use saved project paths', '使用项目保存的路径', '使用專案儲存的路徑'),
      tr('Save current paths to project', '将当前路径保存到项目', '將目前路徑儲存到專案'),
      tr('Add one project import directory', '添加一个项目模块目录', '新增一個專案模組目錄'),
      tr('Remove a project import directory', '移除一个项目模块目录', '移除一個專案模組目錄'),
      tr('Reorder project import directories', '调整模块搜索目录顺序', '調整模組搜尋目錄順序'),
      tr('Load migration path hints into this session', '将迁移路径提示载入本会话', '將遷移路徑提示載入本工作階段') }, {
      prompt = tr('Session paths; some actions do not support them yet', '会话路径；部分操作尚不支持', '工作階段路徑；部分操作尚不支援'),
    }, function(_, choice)
      if not choice or not current() then return end
      local function save(directory, roots, use_project)
        if not current() then return end
        if not use_project and directory == nil then directory = vim.uv.fs_realpath(project) or project end
        if directory == old_directory and vim.deep_equal(roots, old_roots)
            and state.opts.runtime_paths_override == not use_project then return end
        state.opts.working_directory, state.opts.project_import_roots = directory, roots
        state.opts.runtime_paths_override = not use_project
        state.change_epoch = epoch + 1
        if not vim.deep_equal(roots, old_roots) then
          state.auto_open_attempted, state.auto_opened_source = false, nil
          local model = state.model or (state.project_info and state.project_info.model)
          if model then open_initial_source(state, model) end
        end
        if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
        state.journey = nil
        state.result_label = tr('runtime paths changed; recheck', '运行时路径已变化，请重验', '執行階段路徑已變更，請重驗')
        render(state)
      end
      if choice == 8 then
        local hint_path = project .. '/model-maven-transfer.json'
        local function read_hints()
          local stat = vim.uv.fs_lstat(hint_path)
          if not stat or stat.type ~= 'file' or stat.size > 64 * 1024 then return nil end
          local file = io.open(hint_path, 'rb'); local raw = file and file:read(64 * 1024 + 1) or nil
          if file then file:close() end
          if not raw or #raw > 64 * 1024 then return nil end
          local ok, value = pcall(vim.json.decode, raw)
          if not ok or type(value) ~= 'table' or value.format ~= 'model-maven-transfer-runtime-v1'
              or type(value.runtime_paths) ~= 'table' or value.runtime_paths.status ~= 'recorded' then return nil end
          return value.runtime_paths, vim.fn.sha256(raw)
        end
        local hints, digest = read_hints()
        local root = vim.uv.fs_realpath(project)
        if not hints or not root or type(hints.working_directory) ~= 'table'
            or type(hints.project_import_roots) ~= 'table' or not is_list(hints.project_import_roots)
            or #hints.project_import_roots > 32 then
          return notify(tr('No valid recorded runtime hints were found in this project.',
            '项目中没有有效的运行路径提示。', '專案中沒有有效的執行路徑提示。'), vim.log.levels.WARN)
        end
        root = vim.fs.normalize(root)
        local function relative_directory(value)
          if type(value) ~= 'string' or value == '' or #value > 1024 or value:find('[%c\\:]')
              or value:sub(1, 1) == '/' or value:find('//', 1, true) or value:sub(-1) == '/'
              or value == '.' or value == '..' or value:match('^%.%./') or value:match('/%.%./')
              or value:match('/%.%.$') or value:match('^%./') or value:match('/%./') or value:match('/%.$') then return nil end
          local full = vim.fs.normalize(root .. '/' .. value)
          local resolved = vim.uv.fs_realpath(full)
          local stat = resolved and vim.uv.fs_stat(resolved)
          if not stat or stat.type ~= 'directory' or vim.fs.normalize(resolved) ~= full then return nil end
          return full
        end
        local working, missing = hints.working_directory, {}
        local directory, relative_working_selected = old_directory, false
        if working.kind == 'project_root' or working.kind == 'default_project' then directory = root
        elseif working.kind == 'project_relative' then
          directory = relative_directory(working.path)
          if not directory then missing[#missing + 1] = tr('working directory unavailable', '运行目录不可用', '執行目錄無法使用'); directory = old_directory end
          relative_working_selected = directory ~= nil and relative_directory(working.path) == directory
        elseif working.kind == 'external' then
          missing[#missing + 1] = tr('external working directory must be selected again', '外部运行目录需重新选择', '外部執行目錄需重新選擇')
        else return notify(tr('Unsupported working directory hint.', '不支持此运行目录提示。', '不支援此執行目錄提示。'), vim.log.levels.WARN) end
        local roots, seen = {}, {}
        for _, item in ipairs(hints.project_import_roots) do
          if type(item) ~= 'string' or seen[item] then return notify(tr('Invalid import directory hints.', '模块目录提示无效。', '模組目錄提示無效。'), vim.log.levels.WARN) end
          seen[item] = true
          if relative_directory(item) then roots[#roots + 1] = item
          else missing[#missing + 1] = tr('unavailable import directory: ', '不可用的模块目录：', '無法使用的模組目錄：') .. item:gsub('[%c]', ' ') end
        end
        local detail = tr('Working directory: ', '运行目录：', '執行目錄：') .. tostring(directory or root)
          .. tr(' · import directories: ', ' · 模块目录：', ' · 模組目錄：') .. (#roots > 0 and table.concat(roots, ', ') or tr('none', '无', '無'))
        if #missing > 0 then detail = detail .. '\n' .. table.concat(missing, '\n') end
        vim.ui.select({tr('Cancel', '取消', '取消'), tr('Use available paths for this session', '本会话使用可用路径', '本工作階段使用可用路徑')}, {
          prompt = detail .. tr('\nProject configuration is unchanged; save session paths separately if desired.',
            '\n项目配置不会改变；如需持久化，可另行保存会话路径。', '\n專案設定不會變更；如需保留，可另行儲存工作階段路徑。'),
        }, function(_, selected)
          local _, now = read_hints()
          if selected ~= 2 or not current() or now ~= digest then return end
          for _, item in ipairs(roots) do if not relative_directory(item) then return notify(tr('A directory changed; load hints again.', '目录已变化，请重新载入提示。', '目錄已變更，請重新載入提示。'), vim.log.levels.WARN) end end
          if relative_working_selected and relative_directory(working.path) ~= directory then
            return notify(tr('Working directory changed; load hints again.', '运行目录已变化，请重新载入提示。', '執行目錄已變更，請重新載入提示。'), vim.log.levels.WARN)
          end
          save(directory, #roots > 0 and roots or nil)
          notify(tr('Session paths loaded; select Python and recheck before running.', '会话路径已载入；运行前请选择 Python 并重新检查。', '工作階段路徑已載入；執行前請選擇 Python 並重新檢查。'), vim.log.levels.INFO)
        end)
        return
      end
      if choice == 3 then
        local info = state.project_info or {}
        save(info.working_directory, vim.deepcopy(info.project_import_roots), true); return
      end
      if choice == 5 then
        vim.ui.input({ prompt = tr('Existing project directory to add: ', '要添加的项目内目录：', '要新增的專案內目錄：'),
          default = project .. '/', completion = 'dir' }, function(value)
          if not value or value == '' or not current() then return end
          local root = vim.uv.fs_realpath(project)
          local absolute = value:sub(1, 1) == '/' or value:match('^%a:[/\\]') or value:match('^[/\\][/\\]')
          local full = vim.fs.normalize(absolute and value or (project .. '/' .. value))
          local resolved = vim.uv.fs_realpath(full)
          local stat = resolved and vim.uv.fs_stat(resolved)
          local prefix = root and (vim.fs.normalize(root):gsub('/+$', '') .. '/')
          if not prefix or not stat or stat.type ~= 'directory' or vim.fs.normalize(resolved) ~= full
              or full:sub(1, #prefix) ~= prefix then
            notify(tr('Choose an existing directory inside the project without symlinks.',
              '请选择项目内不经过符号链接的已有目录。', '請選擇專案內不經過符號連結的既有目錄。'), vim.log.levels.WARN); return
          end
          local relative = full:sub(#prefix + 1)
          local roots = vim.deepcopy(old_roots or {})
          if relative == '' or vim.tbl_contains(roots, relative) or #roots >= 32 then
            notify(tr('Directory already selected or the 32-directory limit was reached.',
              '目录已选择，或已达到 32 个目录的上限。', '目錄已選擇，或已達到 32 個目錄的上限。'), vim.log.levels.WARN); return
          end
          roots[#roots + 1] = relative
          save(old_directory, roots)
          notify(tr('Directories are searched in the displayed order; training snapshots copy their Python sources.',
            '按显示顺序搜索目录；训练快照会复制其中的 Python 源码。',
            '按顯示順序搜尋目錄；訓練快照會複製其中的 Python 原始碼。'), vim.log.levels.INFO)
        end)
        return
      end
      if choice == 6 then
        if not old_roots or #old_roots == 0 then
          notify(tr('No import directories are selected.', '尚未选择模块目录。', '尚未選擇模組目錄。'), vim.log.levels.INFO); return
        end
        vim.ui.select(old_roots, { prompt = tr('Remove which directory?', '移除哪个目录？', '移除哪個目錄？') }, function(_, index)
          if not index or not current() then return end
          local roots = vim.deepcopy(old_roots)
          table.remove(roots, index)
          save(old_directory, #roots > 0 and roots or nil)
        end)
        return
      end
      if choice == 7 then
        if not old_roots or #old_roots < 2 then
          notify(tr('Choose at least two import directories to reorder.', '至少选择两个模块目录才能调整顺序。', '至少選擇兩個模組目錄才能調整順序。'), vim.log.levels.INFO); return
        end
        vim.ui.select(old_roots, { prompt = tr('Choose an import directory to move (earlier means higher priority)',
          '选择要移动的模块目录（越靠前优先级越高）', '選擇要移動的模組目錄（越靠前優先順序越高）') }, function(_, index)
          if not index or not current() then return end
          local choices, positions = {}, {}
          if index > 1 then
            choices[#choices + 1] = tr('Move earlier', '向前移动', '向前移動'); positions[#positions + 1] = index - 1
          end
          if index < #old_roots then
            choices[#choices + 1] = tr('Move later', '向后移动', '向後移動'); positions[#positions + 1] = index + 1
          end
          vim.ui.select(choices, { prompt = tr('Choose a direction', '选择移动方向', '選擇移動方向') }, function(_, choice_index)
            local target = choice_index and positions[choice_index]
            if not target or not current() then return end
            local roots = vim.deepcopy(old_roots)
            roots[index], roots[target] = roots[target], roots[index]
            save(old_directory, roots)
            notify(tr('Import order updated for this session; save project paths to keep it.',
              '本会话的搜索顺序已更新；可保存项目路径以持久化。', '本工作階段的搜尋順序已更新；可儲存專案路徑以保留。'), vim.log.levels.INFO)
          end)
        end)
        return
      end
      if choice == 4 then
        if report.data.capabilities['runtime.project_paths_config_v1'] ~= true or not state.project_info
            or not sha256(state.project_info.config_revision) then
          notify(tr('A configured project and compatible CLI are required.', '需要已配置项目和兼容的 CLI。', '需要已設定專案和相容的 CLI。'), vim.log.levels.WARN); return
        end
        local revision = state.project_info.config_revision
        local args = { 'config', 'set-runtime-paths' }
        if old_directory then vim.list_extend(args, { '--working-directory', old_directory }) end
        for _, root in ipairs(old_roots or {}) do vim.list_extend(args, { '--import-root', root }) end
        state.busy = tr('Previewing runtime paths', '预览运行时路径', '預覽執行階段路徑'); render(state)
        request(state, args, function(preview_report, failure, stderr)
          state.busy = nil
          if not current() then
            render(state)
            notify(tr('Context changed; preview the paths again.', '上下文已变化，请重新预览路径。', '上下文已變更，請重新預覽路徑。'), vim.log.levels.WARN)
            return
          end
          state.last = { report = preview_report, transport_error = failure, stderr = stderr }
          render(state)
          local data = preview_report and preview_report.data
          local paths = type(data) == 'table' and data.runtime_paths or nil
          local directory = type(paths) == 'table' and paths.working_directory or nil
          if directory == vim.NIL then directory = nil end
          if failure or not preview_report or preview_report.operation ~= 'config_set_runtime_paths'
              or preview_report.status ~= 'success' or type(data) ~= 'table' or data.committed ~= false
              or data.from_revision ~= revision or directory ~= old_directory or type(paths) ~= 'table'
              or not vim.deep_equal(paths.project_import_roots, old_roots or {})
              or type(data.redacted_fields) ~= 'table' or #data.redacted_fields > 0 then
            notify(tr('Runtime path preview is unavailable; no configuration was saved.',
              '运行时路径预览不可用；配置未保存。', '執行階段路徑預覽無法使用；設定未儲存。'), vim.log.levels.WARN)
            show_report(state); return
          end
          local preview = state.last
          local buf = show_report(state)
          if data.unchanged then
            state.opts.runtime_paths_override = false
            refresh_project(state)
            notify(tr('Project paths already match.', '项目路径已相同。', '專案路徑已相同。'), vim.log.levels.INFO); return
          end
          review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Save paths', '保存路径', '儲存路徑') },
            tr('Save these project paths? They may affect future imports.', '保存这些项目路径？它们会影响后续导入。', '儲存這些專案路徑？它們會影響後續匯入。'), function(_, selected)
            if selected ~= 2 or not current() or state.last ~= preview or not state.project_info
                or state.project_info.config_revision ~= revision then return end
            local apply = vim.deepcopy(args)
            vim.list_extend(apply, { '--apply', '--if-current', revision })
            if not project_config_current(state) then
              notify(tr('Project configuration changed; review the paths again.', '项目配置已变化，请重新检查路径。', '專案設定已變更，請重新檢查路徑。'), vim.log.levels.WARN)
              return
            end
            local tracked = begin_tracked_commit(state, tr('Save runtime paths', '保存运行时路径', '儲存執行階段路徑'))
            if not tracked then return end
            state.busy = tr('Saving runtime paths', '保存运行时路径', '儲存執行階段路徑'); render(state)
            request(state, apply, function(receipt, problem, output)
              state.busy = nil
              local same_context = tracked_commit_current(state, tracked)
              if same_context then state.last = { report = receipt, transport_error = problem, stderr = output } end
              local saved = receipt and receipt.data
              local verified = not problem and receipt and receipt.operation == 'config_set_runtime_paths' and receipt.status == 'success'
                  and type(saved) == 'table' and saved.committed == true and saved.from_revision == revision
                  and sha256(saved.config_revision) and vim.deep_equal(saved.runtime_paths, data.runtime_paths)
              local settled = settle_tracked_commit(state, tracked, verified, problem)
              if not same_context then render(state); notify_tracked_context_changed(tracked); return end
              if verified and settled then
                state.opts.runtime_paths_override = false
                state.change_epoch = (state.change_epoch or 0) + 1
                state.result_label = tr('project paths saved; recheck', '项目路径已保存，请重验', '專案路徑已儲存，請重驗')
              else
                state.result_label = tr('save outcome requires inspection', '保存结果待核查', '儲存結果待核查')
              end
              refresh_project(state)
              show_report(state)
            end)
          end)
        end)
        return
      end
      if choice == 1 then
        vim.ui.input({ prompt = tr('Existing working directory (empty = project): ', '已有运行目录（留空用项目目录）：', '既有執行目錄（留空用專案目錄）：'),
          default = old_directory or '', completion = 'dir' }, function(value)
          if value == nil or not current() then return end
          if value == '' then save(nil, old_roots); return end
          local absolute = value:sub(1, 1) == '/' or value:match('^%a:[/\\]') or value:match('^[/\\][/\\]')
          local path = vim.uv.fs_realpath(absolute and value or (project .. '/' .. value))
          local stat = path and vim.uv.fs_stat(path)
          if not stat or stat.type ~= 'directory' then
            notify(tr('Choose an existing directory.', '请选择已有目录。', '請選擇既有目錄。'), vim.log.levels.WARN); return
          end
          save(path, old_roots)
        end)
      elseif choice == 2 then
        local default = old_roots and vim.json.encode(old_roots) or '[]'
        vim.ui.input({ prompt = tr('JSON array of project-relative import directories: ', '项目相对模块搜索目录 JSON 数组：', '專案相對模組搜尋目錄 JSON 陣列：'), default = default }, function(raw)
          if raw == nil or not current() then return end
          local ok, roots = pcall(vim.json.decode, raw)
          if #raw > 32768 or not ok or type(roots) ~= 'table' or not is_list(roots) or not raw:match('^%s*%[') or #roots > 32 then
            notify(tr('Enter a JSON array of up to 32 project-relative directories.', '请输入最多 32 个项目相对目录的 JSON 数组。', '請輸入最多 32 個專案相對目錄的 JSON 陣列。'), vim.log.levels.WARN); return
          end
          local root, seen = vim.uv.fs_realpath(project), {}
          for _, item in ipairs(roots) do
            if type(item) ~= 'string' or item == '' or #item > 1024 or item:find('\\', 1, true)
                or item:sub(1, 1) == '/' or item:match('^%a:') or item:find('//', 1, true) or item:sub(-1) == '/'
                or item == '.' or item == '..' or item:match('^%.%./') or item:match('/%.%./') or item:match('/%.%.$')
                or item:match('^%./') or item:match('/%./') or item:match('/%.$') or seen[item] then
              notify(tr('Import roots must be distinct project-relative directories.', '模块搜索目录必须是互不重复的项目相对目录。', '模組搜尋目錄必須是互不重複的專案相對目錄。'), vim.log.levels.WARN); return
            end
            seen[item] = true
            local full = root and vim.fs.normalize(root .. '/' .. item)
            local resolved = full and vim.uv.fs_realpath(full)
            local stat = resolved and vim.uv.fs_stat(resolved)
            if not stat or stat.type ~= 'directory' or vim.fs.normalize(resolved) ~= full then
              notify(tr('Choose existing project directories without symlinks.', '请选择不经过符号链接的已有项目目录。', '請選擇不經過符號連結的既有專案目錄。'), vim.log.levels.WARN); return
            end
          end
          save(old_directory, #roots > 0 and roots or nil)
          if #roots > 0 then
            notify(tr('Training snapshots copy Python sources under selected import roots; large directories can take time and space.',
              '训练快照会复制所选模块目录中的 Python 源码；大目录可能消耗较多时间和空间。',
              '訓練快照會複製所選模組目錄中的 Python 原始碼；大目錄可能消耗較多時間和空間。'), vim.log.levels.INFO)
          end
        end)
      end
    end)
  end)
end

local function choose_session_cli(state)
  if state.busy or state.pending_source then
    notify(tr('Finish the current operation or preview first.', '请先完成当前操作或预览。', '請先完成目前操作或預覽。'), vim.log.levels.WARN); return
  end
  local project, epoch, old_cli = state.opts.project, state.change_epoch or 0, state.opts.cli
  local function current()
    return not state.closed and not state.busy and not state.pending_source and state.opts.project == project
      and state.opts.cli == old_cli and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  vim.ui.input({ prompt = tr('CLI path or command: ', 'CLI 路径或命令：', 'CLI 路徑或指令：'),
    default = old_cli or 'm-model', completion = 'file' }, function(value)
    if not value or value == '' or not current() then return end
    if #value > 4096 or value:find('[%c]') then
      notify(tr('Enter a single executable path or command.', '请输入单个可执行文件路径或命令。', '請輸入單一可執行檔路徑或命令。'), vim.log.levels.WARN); return
    end
    local selected = require('model_maven').resolve_cli(value)
    if type(selected) ~= 'string' or selected == '' or vim.fn.executable(selected) ~= 1 then
      notify(tr('CLI executable was not found in this editor environment.', '当前编辑器环境找不到该 CLI 可执行文件。', '目前編輯器環境找不到該 CLI 可執行檔。'), vim.log.levels.WARN); return
    end
    vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Run interface check', '运行接口检查', '執行介面檢查') }, {
      prompt = tr('Run trusted CLI to check interface?',
        '执行可信 CLI 以检查接口？', '執行可信 CLI 以檢查介面？'),
    }, function(_, choice)
      if choice ~= 2 or not current() then return end
      local candidate = vim.tbl_extend('force', {}, state.opts, { cli = selected, cli_unresolved = false })
      state.busy = tr('Checking selected CLI', '检查所选 CLI', '檢查所選 CLI'); render(state)
      transport.request(candidate, { '--describe-interface' }, function(report, err)
        state.busy = nil; render(state)
        if not current() then return end
        if err or not report or report.operation ~= 'interface' or report.status ~= 'success'
            or type(report.data) ~= 'table' or type(report.data.cli_version) ~= 'string' then
          notify(tr('The selected CLI did not return a compatible interface. The current CLI is unchanged: ',
            '所选 CLI 未返回兼容接口，当前 CLI 未更改：', '所選 CLI 未回傳相容介面，目前 CLI 未變更：')
            .. tostring(err and err.message or (report and report.status) or '?'), vim.log.levels.WARN); return
        end
        local checked_version = report.data.cli_version
        local version_text = checked_version:gsub('[%c]', ' ')
        if vim.fn.strchars(version_text) > 12 then version_text = vim.fn.strcharpart(version_text, 0, 12) .. '…' end
        vim.ui.select({ tr('Keep current CLI', '保留当前 CLI', '保留目前 CLI'), tr('Use selected CLI for this session', '本会话使用所选 CLI', '本工作階段使用所選 CLI') }, {
          prompt = tr('CLI ', 'CLI ', 'CLI ') .. version_text
            .. tr(' · file may change', ' · 文件可能变化', ' · 檔案可能變更'),
        }, function(_, accept)
          if accept ~= 2 or not current() then return end
          state.opts.cli, state.opts.cli_unresolved = selected, false
          state.change_epoch = (state.change_epoch or 0) + 1
          state.journey = nil
          if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
          state.result_label = state.last
            and tr('CLI changed; review previous results', 'CLI 已更换，请核对先前结果', 'CLI 已更換，請核對先前結果')
            or tr('CLI selected; no model run', '已选择 CLI；尚未运行模型', '已選擇 CLI；尚未執行模型')
          refresh_project(state)
        end)
      end)
    end)
  end)
end

local function discovery_snapshot(state)
  local epoch = state.change_epoch or 0
  local project, cli, python, working_directory = state.opts.project, state.opts.cli, state.opts.python, state.opts.working_directory
  local roots = vim.deepcopy(state.opts.project_import_roots)
  local _, config_status, config_digest = project_config(project)
  return function()
    local _, status, digest = project_config(project)
    return not state.closed and (state.change_epoch or 0) == epoch and state.opts.project == project
      and state.opts.cli == cli and state.opts.python == python and state.opts.working_directory == working_directory
      and vim.deep_equal(state.opts.project_import_roots, roots) and status == config_status and digest == config_digest
  end
end

discover_layer_classes = function(state, on_selected)
local epoch = state.change_epoch or 0
local current = discovery_snapshot(state)
state.busy = tr('Checking Layer discovery support', '检查 Layer 发现能力', '檢查 Layer 探索能力'); render(state)
request(state, { '--describe-interface' }, function(interface, err)
  state.busy = nil
  local caps = interface and interface.data and interface.data.capabilities
  if state.closed then return end
  if not current() then
    render(state); notify(tr('Context changed; try Layer discovery again.', '上下文已变化，请重新发现 Layer。', '上下文已變更，請重新探索 Layer。'), vim.log.levels.WARN); return
  end
  if err or not interface or interface.operation ~= 'interface'
      or interface.status ~= 'success' or type(caps) ~= 'table' or caps['runtime.torch_layer_catalog_v1'] ~= true then
    render(state); notify(tr('This CLI cannot discover Layer classes. Update it or use E → Choose CLI, then try again.',
      '当前 CLI 无法发现 Layer 类型。请更新 CLI，或按 E → 选择 CLI，然后重试。',
      '目前 CLI 無法探索 Layer 類型。請更新 CLI，或按 E → 選擇 CLI，然後重試。'), vim.log.levels.WARN); return
  end
  run(state, tr('Discover Layer classes', '发现 Layer 类型', '探索 Layer 類型'),
    { 'env', 'probe', '--library', 'torch', '--layer-catalog' }, function(report, failure, _, stale)
      local data = report and report.data
      local probe = type(data) == 'table' and type(data.probes) == 'table' and data.probes[1] or nil
      local catalog = type(probe) == 'table' and probe.layer_catalog or nil
      if failure or stale or not current() then return end
      if not report or report.status ~= 'success' or type(catalog) ~= 'table' or catalog.status ~= 'observed'
          or type(catalog.layers) ~= 'table' then
        local reason = type(probe) == 'table' and (probe.failure_reason or probe.failure_type)
          or type(catalog) == 'table' and (catalog.failure_reason or catalog.reason)
          or type(probe) == 'table' and probe.status or nil
        local message = tr('Layer discovery is unavailable; a factory can still be entered manually.',
          'Layer 发现不可用，仍可手动输入工厂。', 'Layer 探索無法使用，仍可手動輸入工廠。')
        if type(reason) == 'string' and reason ~= '' then message = message .. ' ' .. reason:gsub('[%c]', ' '):sub(1, 500) end
        notify(message, vim.log.levels.WARN); return
      end
      local names = {}
      for _, layer in ipairs(catalog.layers) do
        if type(layer) == 'table' and type(layer.name) == 'string' and #layer.name <= 200
            and not layer.name:find('[%c%s]') then names[#names + 1] = layer end
      end
      if #names == 0 then notify(tr('No Layer classes were observed.', '未发现 Layer 类型。', '未發現 Layer 類型。'), vim.log.levels.INFO); return end
      if catalog.truncated then
        notify(tr('Layer discovery was truncated; enter other class names manually.', 'Layer 发现结果已截断；其他类名仍可手动输入。', 'Layer 探索結果已截斷；其他類名仍可手動輸入。'), vim.log.levels.WARN)
      end
      local rows, labels = {}, {}
      for _, layer in ipairs(names) do
        rows[#rows + 1] = { path = layer.name }
        local function label()
          local signature = layer.signature
          if type(signature) ~= 'table' or signature.status ~= 'observed' or type(signature.parameters) ~= 'table' then
            return layer.name .. ' · ' .. tr('signature unavailable', '签名不可用', '簽章不可用')
          end
          local fields = {}
          for _, param in ipairs(signature.parameters) do
            if type(param) == 'table' and type(param.name) == 'string' then
              fields[#fields + 1] = vim.fn.strcharpart(param.name:gsub('[%c]', '?'), 0, 80) .. (param.required and '*' or '')
            end
          end
          return layer.name .. '(' .. table.concat(fields, ', ') .. (signature.truncated and ', …' or '') .. ')'
        end
        labels[#labels + 1] = label()
      end
      module_picker(tr('Choose a Layer class to prefill', '选择层类型以预填', '選擇層類型以預填'), rows, labels, function(_, index)
        local layer = names[index]
        if layer and current() then
          pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false)
          state.layer_catalog_choice = { name = layer.name, signature = layer.signature, epoch = epoch, current = current }
          notify(tr('Selected for Layer editing: ', '已选择供 Layer 编辑：', '已選擇供 Layer 編輯：') .. layer.name, vim.log.levels.INFO)
          if on_selected then on_selected(layer) end
        end
      end, nil, true)
    end, tr('Imports torch and inspects class signatures in the selected Python; import-time code may run. No Layer is constructed.',
      '将在所选 Python 中导入 torch 并检查类签名，可能执行导入时代码；不会构造 Layer。',
      '將在所選 Python 中匯入 torch 並檢查類別簽章，可能執行匯入時程式碼；不會建構 Layer。'), true)
end)
end

local function discover_module_operators(state, on_selected, initial_module)
  local current = discovery_snapshot(state)
  vim.ui.input({ prompt = tr('Python module to inspect (e.g. package.layers): ',
    '要检查的 Python 模块（例如 package.layers）：', '要檢查的 Python 模組（例如 package.layers）：'), default = initial_module or '' }, function(name)
    if not current() or not name or name == '' then return end
    local valid = #name <= 200 and not name:find('%.%.', 1, false) and name:sub(1, 1) ~= '.' and name:sub(-1) ~= '.'
    if valid then for _, part in ipairs(vim.split(name, '.', {plain = true})) do if not module_part_candidate(part) then valid = false; break end end end
    if not valid then
      notify(tr('Enter a Python module name.', '请输入 Python 模块名。', '請輸入 Python 模組名稱。'), vim.log.levels.WARN); return
    end
    request(state, { '--describe-interface' }, function(interface, failure)
      if not current() then return end
      local caps = interface and interface.data and interface.data.capabilities
      if failure or not interface or interface.status ~= 'success' or type(caps) ~= 'table'
          or caps['runtime.operator_catalog_v1'] ~= true then
        notify(tr('This CLI cannot discover module operators.', '当前 CLI 不支持模块算子发现。', '目前 CLI 不支援模組運算子探索。'), vim.log.levels.WARN); return
      end
      run(state, tr('Discover module operators', '发现模块算子', '探索模組運算子'),
        { 'env', 'probe', '--library', name, '--operator-catalog' }, function(report, error, _, stale)
          if error or stale or not current() then return end
          local probe = report and report.data and report.data.probes and report.data.probes[1]
          local catalog = type(probe) == 'table' and probe.operator_catalog or nil
          if not report or report.status ~= 'success' or type(catalog) ~= 'table'
              or catalog.status ~= 'observed' or type(catalog.operators) ~= 'table' then
            local reason = type(probe) == 'table' and (probe.failure_reason or probe.failure_type)
              or type(catalog) == 'table' and (catalog.failure_reason or catalog.reason)
              or type(probe) == 'table' and probe.status or nil
            local message = tr('Module candidates could not be observed.', '无法读取模块候选。', '無法讀取模組候選。')
            if type(reason) == 'string' and reason ~= '' then message = message .. ' ' .. reason:gsub('[%c]', ' '):sub(1, 500) end
            notify(message, vim.log.levels.WARN); return
          end
          local candidates, rows, labels = {}, {}, {}
          local operators = vim.deepcopy(catalog.operators)
          table.sort(operators, function(a, b)
            local ak = type(a) == 'table' and tostring(a.kind or '') or ''
            local bk = type(b) == 'table' and tostring(b.kind or '') or ''
            if ak ~= bk then return ak < bk end
            return tostring(type(a) == 'table' and a.reference or '') < tostring(type(b) == 'table' and b.reference or '')
          end)
          for _, item in ipairs(operators) do
            if type(item) == 'table' and type(item.reference) == 'string' and #item.reference <= 240
                and item.reference:match('^[^%s:;=@]+:[^%s:;=@]+$') then
              candidates[#candidates + 1] = item
              rows[#rows + 1] = { path = item.reference }
              local params = {}
              local signature = item.signature
              if type(signature) == 'table' and signature.status == 'observed' and type(signature.parameters) == 'table' then
                for _, param in ipairs(signature.parameters) do
                  if type(param) == 'table' and type(param.name) == 'string' then
                    params[#params + 1] = param.name:gsub('[%c]', '?') .. (param.required and '*' or '')
                  end
                end
              else
                params[1] = tr('signature unavailable', '签名不可用', '簽章不可用')
                if type(signature) == 'table' and type(signature.reason) == 'string' then
                  params[1] = params[1] .. ': ' .. signature.reason:gsub('[%c]', ' '):sub(1, 120)
                end
              end
              local category = item.kind == 'class' and tr('class', '类', '類別') or tr('function', '函数', '函式')
              local origin = type(item.source_module) == 'string' and item.source_module ~= ''
                and (' · ' .. tr('origin: ', '来源：', '來源：') .. item.source_module:gsub('[%c]', ' '):sub(1, 240)) or ''
              labels[#labels + 1] = '[' .. category .. '] ' .. item.reference .. ' (' .. table.concat(params, ', ') .. ')' .. origin .. ' · '
                .. tr('compatibility unknown', '兼容性未知', '相容性未知')
            end
          end
          if #candidates == 0 then
            notify(tr('No module candidates found.', '没有发现模块候选。', '沒有發現模組候選。'), vim.log.levels.INFO); return
          end
          if catalog.truncated then notify(tr('Results truncated.', '结果已截断。', '結果已截斷。'), vim.log.levels.WARN) end
          module_picker(tr('Choose a factory candidate', '选择工厂候选', '選擇工廠候選'), rows, labels, function(_, index)
            local item = candidates[index]
            if item and current() then
              pcall(vim.api.nvim_win_close, vim.api.nvim_get_current_win(), false)
              on_selected(item)
            end
          end, nil, true)
        end, tr('Imports the specified module and inspects signatures; import and introspection may execute code. No object is constructed or compatibility verified.',
          '将导入指定模块并检查签名；导入和检查可能执行代码，不构造对象，也不证明兼容。',
          '將匯入指定模組並檢查簽章；匯入和檢查可能執行程式碼，不建構物件，也不證明相容。'), true)
    end)
  end)
end

local function show_execution_location(state)
  local function safe(value)
    return vim.fn.strcharpart(tostring(value or '?'):gsub('[%c]', ' '), 0, 512)
  end
  local config, status = project_config(state.opts.project)
  local python = state.opts.python or (status == 'present' and type(config.runtime_python) == 'string' and config.runtime_python)
  local container_marker = vim.uv.fs_stat('/.dockerenv') and '/.dockerenv'
    or vim.uv.fs_stat('/run/.containerenv') and '/run/.containerenv' or nil
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
  local lines = {
    tr('Execution location', '执行位置', '執行位置'), '',
    tr('Editor host name: ', '编辑器主机名：', '編輯器主機名稱：') .. safe(vim.fn.hostname()),
    tr('Container marker: ', '容器标记：', '容器標記：') .. (container_marker and safe(container_marker)
      or tr('not observed; execution environment unknown', '未观察到；运行环境未知', '未觀察到；執行環境未知')),
    tr('Project path visible to editor: ', '编辑器可见的项目路径：', '編輯器可見的專案路徑：') .. safe(state.opts.project),
    tr('Selected CLI command: ', '所选 CLI 命令：', '所選 CLI 指令：') .. safe(state.opts.cli),
    tr('Selected Python: ', '所选 Python：', '所選 Python：') .. (python and safe(python)
      or tr('project/default discovery', '项目或默认发现', '專案或預設探索')),
    '',
    tr('Paths are interpreted in the editor environment. Normal CLI and Python subprocesses inherit that context.',
      '路径按编辑器环境解析。普通 CLI 和 Python 子进程继承该上下文。',
      '路徑依編輯器環境解析。一般 CLI 與 Python 子程序繼承該上下文。'),
    tr('A wrapper or user training code can run elsewhere; its execution location is not verified here.',
      '包装命令或用户训练代码可能在其他位置执行；此处未核实其执行位置。',
      '包裝指令或使用者訓練程式碼可能在其他位置執行；此處未核實其執行位置。'),
    tr('For SSH or a container, run the editor, CLI and Python in the same environment. Cross-host path mapping and container orchestration are not supported.',
      '使用 SSH 或容器时，请在同一环境运行编辑器、CLI 和 Python；不支持跨主机路径映射或容器编排。',
      '使用 SSH 或容器時，請在同一環境執行編輯器、CLI 與 Python；不支援跨主機路徑對應或容器編排。'),
    tr('After a disconnect, inspect pending requests and run records before retrying.',
      '断线后请先核查待确认请求和运行记录，再决定是否重试。',
      '斷線後請先核查待確認要求與執行記錄，再決定是否重試。'),
    '', tr('Press q to close.', '按 q 关闭。', '按 q 關閉。'),
  }
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
  vim.bo[buf].modifiable = false
  if not open_aux_buffer(buf, false, false) then return end
  vim.keymap.set('n', 'q', '<cmd>close<cr>', {buffer = buf, silent = true})
end

local function environment_menu(state)
  if state.busy then return end
  vim.ui.select({ tr('Check selected environment', '检查所选环境', '檢查所選環境'),
    tr('List installed Python distributions', '列出已安装的 Python 发行包', '列出已安裝的 Python 發行套件'),
    tr('Explicitly import a library', '明确导入一个库', '明確匯入一個程式庫'),
    tr('Query visible training devices', '查询可见训练设备', '查詢可見訓練裝置'),
    tr('Choose CLI for this session', '为本会话选择 CLI', '為本工作階段選擇 CLI'),
    tr('Discover torch.nn Layer classes', '发现 torch.nn 层类型', '探索 torch.nn 層類型'),
    tr('Resolve a dependency lock', '解析依赖锁', '解析相依套件鎖定檔'),
    tr('Prepare a new project environment', '准备新的项目环境', '準備新的專案環境'),
    tr('Inspect or archive locked wheels', '检查或归档锁定的 wheel', '檢查或封存鎖定的 wheel'),
    tr('Show execution location and boundaries', '查看执行位置与边界', '查看執行位置與邊界') }, {
      prompt = tr('Environment actions', '环境操作', '環境操作'),
    }, function(_, choice)
      if not choice or state.closed then return end
      if choice == 10 then
        show_execution_location(state)
      elseif choice == 1 then
        run(state, tr('Check environment', '检查环境', '檢查環境'), { 'env', 'check' }, nil, nil, true)
      elseif choice == 2 then
        run(state, tr('Inspect installed library metadata', '查看已安装库的元数据', '查看已安裝程式庫的中繼資料'), { 'env', 'libraries' }, nil, nil, true)
      elseif choice == 5 then
        choose_session_cli(state)
      elseif choice == 6 then
        discover_layer_classes(state)
      elseif choice == 7 or choice == 8 then
        local project, cli, epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
        local function current()
          return not state.closed and not state.busy and state.opts.project == project and state.opts.cli == cli
            and (state.change_epoch or 0) == epoch
        end
        local default = vim.fn.filereadable(project .. '/requirements.txt') == 1 and 'requirements.txt' or ''
        vim.ui.input({prompt = tr('Project requirements file: ', '项目依赖文件：', '專案相依套件檔案：'), default = default, completion = 'file'}, function(requirements)
          if not requirements or requirements == '' or requirements:find('[%c]') or not current() then return end
          if choice == 7 then
            return run(state, tr('Resolve dependency lock', '解析依赖锁', '解析相依套件鎖定檔'),
              {'env', 'lock', '--requirements', requirements}, nil,
              tr('Resolves the chosen requirements using configured package sources and writes lock metadata. It may access the network; it does not install packages into the selected environment.',
                '使用已配置的软件包源解析所选依赖并写入锁文件，可能访问网络；不会向所选环境安装包。',
                '使用已設定的套件來源解析所選相依套件並寫入鎖定檔，可能存取網路；不會向所選環境安裝套件。')
                .. tr('\nRequirements: ', '\n依赖文件：', '\n相依套件檔案：') .. requirements, true)
          end
          vim.ui.input({prompt = tr('New project-relative environment directory: ', '新建的项目相对环境目录：', '新建的專案相對環境目錄：'), completion = 'dir'}, function(venv)
            if not venv or venv == '' or venv:find('[%c]') or not current() then return end
            if venv:sub(1, 1) == '/' or venv:match('^%a:') or venv:find('\\', 1, true)
                or venv == '.' or venv == '..' or venv:match('^%.%./') or venv:match('/%.%./') or venv:match('/%.%.$')
                or vim.uv.fs_lstat(project .. '/' .. venv) then
              return notify(tr('Choose a new project-relative directory; existing paths are not modified.',
                '请选择尚不存在的项目相对目录；不会修改已有路径。', '請選擇尚不存在的專案相對目錄；不會修改既有路徑。'), vim.log.levels.WARN)
            end
            run(state, tr('Prepare project environment', '准备项目环境', '準備專案環境'),
              {'env', 'setup', '--requirements', requirements, '--venv', venv}, nil,
              tr('May resolve dependencies over the network, writes a lock and creates the selected new virtual environment using the saved system-package inheritance policy. Existing incompatible environments are not overwritten; no library is bound automatically.',
                '可能联网解析依赖、写入锁文件并按已保存的系统包继承策略创建新虚拟环境。不会覆盖现有不兼容环境，也不会自动绑定库。',
                '可能連網解析相依套件、寫入鎖定檔並依已儲存的系統套件繼承策略建立新虛擬環境。不會覆蓋現有不相容環境，也不會自動繫結程式庫。')
                .. tr('\nRequirements: ', '\n依赖文件：', '\n相依套件檔案：') .. requirements
                .. tr('\nNew environment: ', '\n新环境：', '\n新環境：') .. venv, true, function()
                  local stat, _, code = vim.uv.fs_lstat(project .. '/' .. venv)
                  if not current() or stat or code ~= 'ENOENT' then
                    notify(tr('The target is no longer confirmed absent; choose a new directory.',
                      '目标不能确认仍不存在；请选择新目录。', '目標無法確認仍不存在；請選擇新目錄。'), vim.log.levels.WARN)
                    return false
                  end
                  return true
                end)
          end)
        end)
      elseif choice == 9 then
        vim.ui.select({tr('Check wheel archive', '检查 wheel 归档', '檢查 wheel 封存'),
          tr('Archive locked wheels', '归档锁定的 wheel', '封存鎖定的 wheel'),
          tr('Create a new environment offline', '离线创建新环境', '離線建立新環境'), tr('Cancel', '取消', '取消')}, {
            prompt = tr('Wheel archives are tied to the recorded Python ABI; OS, drivers and GPU compatibility require separate checks.',
              'wheel 归档受记录的 Python ABI 约束；系统、驱动和 GPU 兼容性需另行检查。',
              'wheel 封存受記錄的 Python ABI 約束；系統、驅動和 GPU 相容性需另行檢查。'),
          }, function(_, action)
            if not action or action == 4 or state.closed or state.busy then return end
            if action == 3 then
              local project, cli, epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
              local function current()
                return not state.closed and not state.busy and state.opts.project == project and state.opts.cli == cli
                  and (state.change_epoch or 0) == epoch
              end
              state.busy = tr('Checking offline environment support', '检查离线环境能力', '檢查離線環境能力'); render(state)
              request(state, {'--describe-interface'}, function(interface, failure)
                state.busy = nil; render(state)
                if not current() then return end
                local caps = interface and interface.data and interface.data.capabilities
                if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
                    or type(caps) ~= 'table' or caps['runtime.offline_environment_create_v1'] ~= true then
                  return notify(tr('The selected CLI cannot create an offline environment.', '所选 CLI 不支持离线创建环境。', '所選 CLI 不支援離線建立環境。'), vim.log.levels.WARN)
                end
                vim.ui.input({prompt = tr('New project-relative environment directory: ', '新建的项目相对环境目录：', '新建的專案相對環境目錄：'), completion = 'dir'}, function(venv)
                  if not venv or venv == '' or venv:find('[%c]') or not current() then return end
                  if venv:sub(1, 1) == '/' or venv:match('^%a:') or venv:find('\\', 1, true)
                      or venv == '.' or venv == '..' or venv:match('^%.%./') or venv:match('/%.%./') or venv:match('/%.%.$') then
                    return notify(tr('Choose a new project-relative directory.', '请选择新的项目相对目录。', '請選擇新的專案相對目錄。'), vim.log.levels.WARN)
                  end
                  local function absent()
                    local stat, _, code = vim.uv.fs_lstat(project .. '/' .. venv)
                    return current() and not stat and code == 'ENOENT'
                  end
                  if not absent() then return notify(tr('The target must not exist.', '目标目录必须不存在。', '目標目錄必須不存在。'), vim.log.levels.WARN) end
                  run(state, tr('Create offline environment', '离线创建环境', '離線建立環境'),
                    {'env', 'wheelhouse', 'replay', '--create', '--venv', venv}, nil,
                    tr('Creates only the selected new environment and installs locked wheels without network access. The saved lock controls system-package inheritance. No interpreter is automatically selected; OS, drivers and GPU compatibility are not proven.',
                      '仅创建所选新环境并从归档离线安装锁定的 wheel。锁文件决定系统包继承；不会自动选择解释器，系统、驱动和 GPU 兼容性尚未证明。',
                      '僅建立所選新環境並從封存離線安裝鎖定的 wheel。鎖定檔決定系統套件繼承；不會自動選擇直譯器，系統、驅動和 GPU 相容性尚未證明。')
                      .. tr('\nNew environment: ', '\n新环境：', '\n新環境：') .. venv, true, function()
                        if absent() then return true end
                        notify(tr('The target is no longer confirmed absent.', '不能确认目标仍不存在。', '無法確認目標仍不存在。'), vim.log.levels.WARN); return false
                      end)
                end)
              end)
              return
            end
            local subcommand = action == 1 and 'check' or 'archive'
            run(state, action == 1 and tr('Check wheel archive', '检查 wheel 归档', '檢查 wheel 封存')
                or tr('Archive locked wheels', '归档锁定的 wheel', '封存鎖定的 wheel'),
              {'env', 'wheelhouse', subcommand}, nil,
              action == 1 and tr('Reads and verifies the selected lock and wheel archive; it does not install packages.',
                '读取并核对所选锁文件和 wheel 归档，不安装软件包。', '讀取並核對所選鎖定檔和 wheel 封存，不安裝套件。')
              or tr('Downloads wheels from configured package sources into a project archive; existing incompatible archives are not overwritten.',
                '从已配置的软件包源下载 wheel 到项目归档；不会覆盖已有的不兼容归档。',
                '從已設定的套件來源下載 wheel 至專案封存；不會覆蓋既有的不相容封存。'), true)
          end)
      elseif choice == 4 then
        local epoch = state.change_epoch or 0
        state.busy = tr('Checking device query support', '检查设备查询能力', '檢查裝置查詢能力'); render(state)
        request(state, { '--describe-interface' }, function(interface, err)
          state.busy = nil
          local caps = interface and interface.data and interface.data.capabilities
          if err or state.closed or (state.change_epoch or 0) ~= epoch or not interface or interface.operation ~= 'interface'
              or interface.status ~= 'success' or type(caps) ~= 'table' or caps['runtime.device_inventory_v1'] ~= true then
            render(state); notify(tr('A compatible CLI and unchanged context are required.', '需要兼容的 CLI 和未变化的上下文。', '需要相容的 CLI 和未變更的上下文。'), vim.log.levels.WARN); return
          end
          run(state, tr('Query training devices', '查询训练设备', '查詢訓練裝置'), { 'env', 'devices' }, function(report, failure, _, stale)
            state.device_inventory = nil
            local data = report and report.data
            local probe = type(data) == 'table' and type(data.probes) == 'table' and data.probes[1] or nil
            local inventory = type(probe) == 'table' and probe.device_inventory or nil
            if not failure and not stale and report and report.operation == 'environment_devices' and report.status == 'success'
                and type(probe) == 'table' and probe.status == 'imported' and type(inventory) == 'table'
                and (inventory.status == 'observed' or inventory.status == 'partial') and type(inventory.devices) == 'table' then
              local devices, seen = {}, {}
              for _, device in ipairs(inventory.devices) do
                if type(device) == 'table' and type(device.id) == 'string' and #device.id <= 80
                    and device.id ~= 'cpu' and device.id ~= 'meta'
                    and (device.id:match('^[a-z][a-z0-9_]*$') or device.id:match('^[a-z][a-z0-9_]*:%d+$'))
                    and not seen[device.id] then
                  seen[device.id] = true
                  devices[#devices + 1] = { id = device.id,
                    name = vim.fn.strcharpart(tostring(device.name or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 160),
                    backend = vim.fn.strcharpart(tostring(device.backend or '?'):gsub('[\r\n%z\1-\31\127]', ' '), 0, 32) }
                  if #devices == 128 then break end
                end
              end
              state.device_inventory = { devices = devices, epoch = state.change_epoch or 0,
                observed_at = os.date('%H:%M:%S'), status = inventory.status }
            end
          end,
            tr('Queries the selected interpreter; no device is selected and no dependency is installed.',
              '查询所选解释器；不会选择设备或安装依赖。', '查詢所選解譯器；不會選擇裝置或安裝依賴。'), true)
        end)
      else
        vim.ui.input({ prompt = tr('Known library ID or Python module name: ', '已知库 ID 或 Python 模块名：', '已知程式庫 ID 或 Python 模組名稱：') }, function(name)
          if not name or name == '' or state.closed then return end
          if #name > 800 or name:find('[%c%s]') then
            notify(tr('Enter a module name without whitespace or control characters.', '请输入不含空格或控制字符的模块名。', '請輸入不含空白或控制字元的模組名稱。'), vim.log.levels.WARN); return
          end
          local effects = tr('Imports this library in the selected Python; import-time code may execute. Nothing is installed or automatically bound.',
            '将在所选 Python 中导入此库，可能执行导入时代码；不会安装或自动绑定。',
            '將在所選 Python 中匯入此程式庫，可能執行匯入時程式碼；不會安裝或自動繫結。')
            .. tr('\nLibrary: ', '\n库：', '\n程式庫：') .. name
          run(state, tr('Import library', '导入库', '匯入程式庫'), { 'env', 'probe', '--library', name }, nil, effects, true)
        end)
      end
    end)
end

local function show_help()
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
  local lines = {
    tr('Model-Maven · work with your model', 'Model-Maven · 开始使用你的模型', 'Model-Maven · 開始使用你的模型'),
    '',
    tr('The source buffer is your normal Neovim buffer. The panel provides actions and reports.',
      '源码区是原生 Neovim buffer；面板提供操作和报告。', '原始碼區是原生 Neovim buffer；面板提供操作和報告。'),
    tr('New to Neovim? In source, press i to insert, Esc for normal mode, :write to save, / to search and u to undo. Your own mappings may change these keys.',
      '不熟悉 Neovim？在源码区按 i 输入、Esc 返回普通模式、:write 保存、/ 搜索、u 撤销；你自己的键位配置可能改变这些操作。',
      '不熟悉 Neovim？在原始碼區按 i 輸入、Esc 返回一般模式、:write 儲存、/ 搜尋、u 復原；你自己的按鍵設定可能改變這些操作。'),
    tr('Use U to choose or name a goal. Suggested actions follow a chosen goal after the model is observed; nothing runs automatically.',
      '按 U 选择或填写目标；观察模型后会按所选目标建议操作，不会自动执行。',
      '按 U 選擇或填寫目標；觀察模型後會按所選目標建議操作，不會自動執行。'),
    tr('Use Ctrl-w and a direction to move between windows. In a narrow window, z returns to source and :ModelMaven reopens the panel.',
      '使用 Ctrl-w 加方向键切换窗口。窄窗口中按 z 返回源码，用 :ModelMaven 重新打开面板。',
      '使用 Ctrl-w 加方向鍵切換視窗。窄視窗中按 z 返回原始碼，用 :ModelMaven 重新開啟面板。'),
    tr('Press q in the panel to close it. To leave a standalone Neovim session, use :qa; Neovim will warn about unsaved changes.',
      '在面板按 q 关闭面板。要退出单独启动的 Neovim，请输入 :qa；有未保存修改时 Neovim 会提示。',
      '在面板按 q 關閉面板。要結束獨立啟動的 Neovim，請輸入 :qa；有未儲存修改時 Neovim 會提示。'),
    tr('Use x in the panel for all actions, e to choose Python, E to inspect the environment.',
      '在面板按 x 展开操作，e 选择 Python，E 检查环境。', '在面板按 x 展開操作，e 選擇 Python，E 檢查環境。'),
    tr('E can select a CLI for this session. Paths and commands resolve in this editor environment; checking runs the selected executable.',
      '在 E 中可选择本会话 CLI。路径和命令按当前编辑器环境解析；接口检查会执行所选文件。',
