  }
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
  vim.bo[buf].modifiable = false
  if not open_aux_buffer(buf, false, false) then return end
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close Model-Maven help' })
end

-- Project augmentations are revision-guarded separately from the canvas draft.
local function edit_input_augmentation(state, input)
  if state.closed or state.busy or not project_config_current(state) then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  local function failure(message)
    notify(message, vim.log.levels.WARN)
  end
  vim.ui.select({tr('Training transforms', '训练变换', '訓練變換'), tr('Evaluation transforms', '评估变换', '評估變換')}, {
    prompt = tr('Choose a project pipeline', '选择项目流水线', '選擇專案流水線'),
  }, function(_, chosen)
    if not chosen or not current() then return end
    local split = chosen == 1 and 'train' or 'eval'
    state.busy = tr('Reading transforms', '读取变换', '讀取變換'); render(state)
    request(state, {'augment', 'list', '--split', split}, function(report, error, stderr)
      state.busy = nil
      if not current() then render(state); return end
      state.last = {report = report, transport_error = error, stderr = stderr}; render(state)
      local data = report and report.data
      if error or not report or report.operation ~= 'augment_list' or report.status ~= 'success'
          or type(data) ~= 'table' or data.split ~= split or type(data.steps) ~= 'table'
          or not is_list(data.steps) or not sha256(data.config_revision) then
        show_report(state); return failure(tr('Cannot read this pipeline.', '无法读取此流水线。', '無法讀取此流水線。'))
      end
      local revision, steps = data.config_revision, data.steps
      local catalog, by_kind = {}, {}
      if type(data.catalog) == 'table' and is_list(data.catalog) and #data.catalog <= 128 then
        for _, item in ipairs(data.catalog) do
          if type(item) == 'table' and type(item.kind) == 'string' and item.kind:match('^[%w_]+$')
              and #item.kind <= 64 and type(item.parameters) == 'table' and is_list(item.parameters)
              and #item.parameters <= 64 and not by_kind[item.kind] then
            local valid = true
            for _, field in ipairs(item.parameters) do
              if type(field) ~= 'table' or not parameter_name_candidate(field.name)
                  or type(field.required) ~= 'boolean' or type(field.example) ~= 'string'
                  or #field.example > 160 or field.example:find('[%c]') then valid = false; break end
            end
            if valid then catalog[#catalog + 1], by_kind[item.kind] = item, item end
          end
        end
      end
      local function plan(args)
        if not current() then return end
        local preview_args = vim.deepcopy(args)
        vim.list_extend(preview_args, {'--split', split, '--if-config-revision', revision, '--dry-run'})
        state.busy = tr('Planning transform change', '规划变换修改', '規劃變換修改'); render(state)
        request(state, preview_args, function(candidate, problem, output)
          state.busy = nil
          if not current() then render(state); return end
          state.last = {report = candidate, transport_error = problem, stderr = output}; render(state)
          local result = candidate and candidate.data
          if problem or not candidate or candidate.operation ~= 'augment_' .. tostring(args[2])
              or candidate.status ~= 'success' or type(result) ~= 'table' or result.committed ~= false or result.split ~= split or result.base_config_revision ~= revision
              or type(result.steps) ~= 'table' or not is_list(result.steps) then
            show_report(state); return failure(tr('Could not plan this transform change.', '无法规划此变换修改。', '無法規劃此變換修改。'))
          end
          local planned, displayed = vim.deepcopy(result.steps), state.last
          local proposal = vim.inspect(planned)
          if not reviewable_text(proposal) then return failure(tr('Pipeline is too large to review here.', '流水线过大，无法在此审核。', '流水線過大，無法在此檢視。')) end
          local review = show_report(state)
          if not review or not vim.api.nvim_buf_is_valid(review) then return end
          vim.bo[review].modifiable = true
          local header = {tr('Proposed ordered pipeline (configuration checked; runtime not run):',
            '拟保存的有序流水线（仅检查配置，尚未运行）：', '擬儲存的有序流水線（僅檢查設定，尚未執行）：'), ''}
          vim.list_extend(header, vim.split(proposal, '\n', {plain = true})); header[#header + 1] = ''
          vim.api.nvim_buf_set_lines(review, 0, 0, false, header)
          vim.bo[review].modifiable = false
          review_gate(review, {tr('Cancel', '取消', '取消'), tr('Save pipeline', '保存流水线', '儲存流水線')},
            tr('Save this ordered project pipeline? It has not run.', '保存此有序项目流水线？尚未运行验证。', '儲存此有序專案流水線？尚未執行驗證。'), function(_, choice)
            if choice ~= 2 or not current() or state.last ~= displayed then return end
            local commit = vim.deepcopy(args)
            vim.list_extend(commit, {'--split', split, '--if-config-revision', revision})
            local tracked = begin_tracked_commit(state, tr('Save transform pipeline', '保存变换流水线', '儲存變換流水線'))
            if not tracked then return end
            state.busy = tr('Saving transforms', '保存变换', '儲存變換'); render(state)
            request(state, commit, function(receipt, problem2, stderr2)
              state.busy = nil
              local same = tracked_commit_current(state, tracked)
              local result2 = receipt and receipt.data
              local verified = not problem2 and receipt and receipt.operation == 'augment_' .. tostring(args[2])
                and receipt.status == 'success' and type(result2) == 'table'
                and result2.committed == true and result2.split == split and result2.base_config_revision == revision
                and sha256(result2.config_revision) and vim.deep_equal(result2.steps, planned)
              local settled = settle_tracked_commit(state, tracked, verified, problem2)
              if not same then notify_tracked_context_changed(tracked); return end
              state.last = {report = receipt, transport_error = problem2, stderr = stderr2}
              if verified and settled then
                state.change_epoch = (state.change_epoch or 0) + 1
                state.result_label = tr('transform pipeline saved; not run', '变换流水线已保存；尚未运行', '變換流水線已儲存；尚未執行')
                refresh_project(state)
              end
              render(state); show_report(state)
            end)
          end)
        end)
      end
      local function parameters(args, original, schema)
        local values = type(original) == 'table' and vim.deepcopy(original) or vim.empty_dict()
        local function submit()
          local names = vim.tbl_keys(values); table.sort(names)
          for _, name in ipairs(names) do
            if not parameter_name_candidate(name) then return failure(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。')) end
            local encoded_ok, value_text = pcall(vim.json.encode, values[name])
            if not encoded_ok then return failure(tr('Cannot encode parameter.', '参数无法编码。', '參數無法編碼。')) end
            vim.list_extend(args, {'--param', name .. '=' .. value_text})
          end
          plan(args)
        end
        if schema and not schema.custom_parameters then
          local function field_at(index)
            if not current() then return end
            local field = schema.parameters[index]
            if not field then submit(); return end
            local prior = values[field.name]
            local encoded, previous = pcall(vim.json.encode, prior)
            local optional = field.required and tr('required', '必填', '必填') or tr('optional', '可选', '可選')
            local prompt = field.name .. ' · ' .. optional .. ' · ' .. field.example .. ': '
            vim.ui.input({prompt = prompt, default = prior ~= nil and encoded and previous or ''}, function(raw)
              if raw == nil or not current() then return end
              if vim.trim(raw) == '' then
                if field.required and prior == nil then return failure(tr('This parameter is required.', '此参数为必填项。', '此參數為必填項。')) end
              else
                local ok, value = pcall(vim.json.decode, raw)
                if #raw > 16384 or not ok then return failure(tr('Enter a JSON value for this parameter.', '请输入该参数的 JSON 值。', '請輸入該參數的 JSON 值。')) end
                values[field.name] = value
              end
              field_at(index + 1)
            end)
          end
          field_at(1); return
        end
        local ok, encoded = pcall(vim.json.encode, values)
        vim.ui.input({prompt = tr('Transform parameters as JSON object (no secrets): ',
          '变换参数 JSON 对象（请勿填写密钥）：', '變換參數 JSON 物件（請勿填寫密鑰）：'), default = ok and encoded or '{}'}, function(raw)
          if not raw or not current() then return end
          local parsed, value = pcall(vim.json.decode, raw)
          if #raw > 16384 or not parsed or type(value) ~= 'table' or not raw:match('^%s*{') then
            return failure(tr('Enter a JSON object up to 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'))
          end
          values = value
          submit()
        end)
      end
      local choices = {tr('+ Add transform', '+ 添加变换', '+ 新增變換')}
      for index, step in ipairs(steps) do
        if type(step) ~= 'table' or type(step.id) ~= 'string' or type(step.type) ~= 'string' then
          return failure(tr('Pipeline contains an unsupported step.', '流水线包含无法识别的步骤。', '流水線包含無法辨識的步驟。'))
        end
        choices[#choices + 1] = index .. '. ' .. step.id:gsub('[%c]', ' ') .. ' · ' .. step.type:gsub('[%c]', ' ')
          .. ' → ' .. tostring(step.target or '?'):gsub('[%c]', ' ')
      end
      vim.ui.select(choices, {prompt = tr('Ordered pipeline; choose a step or add one', '有序流水线：选择步骤或添加', '有序流水線：選擇步驟或新增')}, function(_, index)
        if not index or not current() then return end
        if index == 1 then
          local function add_kind(kind)
            if not kind or not current() then return end
            if not kind:match('^[%w_]+$') or #kind > 64 then return failure(tr('Invalid transform type.', '变换类型无效。', '變換類型無效。')) end
            local schema = by_kind[kind]
            vim.ui.input({prompt = tr('Unique step ID: ', '唯一的步骤 ID：', '唯一的步驟 ID：')}, function(id)
              if not id or not current() then return end
              if not id:match('^[%w_%-]+$') or #id > 64 then return failure(tr('Invalid step ID.', '步骤 ID 无效。', '步驟 ID 無效。')) end
              local args = {'augment', 'add', kind, '--id', id, '--target', 'kwargs.' .. input}
              if (schema and schema.requires_entrypoint) or (not schema and kind == 'custom') then
                vim.ui.input({prompt = tr('Transform factory module:callable: ', '变换工厂 module:callable：', '變換工廠 module:callable：')}, function(entry)
                  if not entry or not current() then return end
                  vim.list_extend(args, {'--entrypoint', entry}); parameters(args, nil, schema)
                end)
              else parameters(args, nil, schema) end
            end)
          end
          if #catalog == 0 then
            vim.ui.input({prompt = tr('Transform type (CLI catalog unavailable): ', '变换类型（CLI 未提供目录）：', '變換類型（CLI 未提供目錄）：')}, add_kind)
          else
            local kinds = {}; for _, item in ipairs(catalog) do kinds[#kinds + 1] = item.kind end
            vim.ui.select(kinds, {prompt = tr('Choose transform type', '选择变换类型', '選擇變換類型')}, add_kind)
          end
          return
        end
        local selected = steps[index - 1]
        vim.ui.select({tr('Edit parameters and target', '修改参数和目标', '修改參數和目標'),
          tr('Move before another step / to end', '移动到其他步骤之前或末尾', '移動到其他步驟之前或末尾'),
          tr('Remove step', '删除步骤', '刪除步驟')}, {prompt = selected.id}, function(_, action)
          if not action or not current() then return end
          if action == 1 then
            vim.ui.input({prompt = tr('Batch target path: ', '批次目标路径：', '批次目標路徑：'), default = selected.target or ('kwargs.' .. input)}, function(target)
              if not target or not current() then return end
              parameters({'augment', 'set', selected.id, '--target', target}, selected.parameters, by_kind[selected.type])
            end)
          elseif action == 2 then
            local destinations, ids = {}, {}
            for _, step in ipairs(steps) do if step.id ~= selected.id then ids[#ids + 1] = step.id; destinations[#destinations + 1] = step.id end end
            destinations[#destinations + 1] = tr('End of pipeline', '流水线末尾', '流水線末尾')
            vim.ui.select(destinations, {prompt = tr('Move before:', '移动到此前：', '移動到此前：')}, function(_, destination)
              if not destination or not current() then return end
              local args = {'augment', 'move', selected.id}
              if ids[destination] then vim.list_extend(args, {'--before', ids[destination]}) end
              plan(args)
            end)
          else plan({'augment', 'remove', selected.id}) end
        end)
      end)
    end)
  end)
end

local function configure_csv_adapter(state, preferred_input, on_draft, preferred_output, target_only, input_only, draft_override)
  if state.closed or state.busy then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local edit_one = target_only or input_only
  local draft_context = on_draft and (draft_override or state.builder_draft) or nil
  local original_data = edit_one and draft_context and vim.deepcopy(draft_context.data) or nil
  local original_params = original_data and original_data.params or nil
  if edit_one and (not original_data or original_data.factory ~= 'model_csv:batch'
      or type(original_params) ~= 'table' or type(original_params.path) ~= 'string'
      or type(original_params.inputs) ~= 'table' or vim.islist(original_params.inputs)
      or (input_only and type(preferred_input) ~= 'string')
      or (target_only and (type(original_params.targets) ~= 'table' or vim.islist(original_params.targets)
        or original_params.targets['$tensor'] ~= nil or type(preferred_output) ~= 'string'))) then
    notify(tr('This CSV mapping cannot be edited here; configure it again.',
      '此 CSV 映射无法在此编辑，请重新配置。', '此 CSV 對應無法在此編輯，請重新設定。'), vim.log.levels.WARN)
    return
  end
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  local function columns(text)
    if type(text) ~= 'string' or #text > 65536 then return nil end
    local result, pos, length = {}, 1, #text
    while pos <= length do
      while pos <= length and text:sub(pos, pos):match('[ \t]') do pos = pos + 1 end
      local column
      if text:sub(pos, pos) == '"' then
        pos = pos + 1
        local pieces, closed = {}, false
        while pos <= length do
          local char = text:sub(pos, pos)
          if char == '"' then
            if text:sub(pos + 1, pos + 1) == '"' then
              pieces[#pieces + 1], pos = '"', pos + 2
            else
              pos, closed = pos + 1, true
              break
            end
          else
            pieces[#pieces + 1], pos = char, pos + 1
          end
        end
        if not closed then return nil end
        column = table.concat(pieces)
        while pos <= length and text:sub(pos, pos):match('[ \t]') do pos = pos + 1 end
        if pos <= length and text:sub(pos, pos) ~= ',' then return nil end
      else
        local delimiter = text:find(',', pos, true) or (length + 1)
        column, pos = vim.trim(text:sub(pos, delimiter - 1)), delimiter
      end
      if column == '' then return nil end
      result[#result + 1] = column
      if pos <= length then
        pos = pos + 1
        if pos > length then return nil end
      end
    end
    return #result > 0 and result or nil
  end
  local function choose_declared_name(kind, used, prompt, callback)
    local info = state.project_info
    local model = state.model or (info and info.model)
    local module = type(model) == 'string' and model:match('^([^:]+):model$') or nil
    local eligible = info and model == info.model and module
      and (module == 'model_starter' or module:match('^model_maven_build_[a-f0-9]+$'))
    local draft = draft_context or (not on_draft and eligible and require('model_maven.model_builder').load(project) or nil)
    local rows, labels = {}, {}
    for _, item in ipairs(draft and draft[kind] or {}) do
      if type(item.name) == 'string' and not used[item.name] then
        rows[#rows + 1] = item.name
        labels[#labels + 1] = item.name .. ' · ' .. (kind == 'inputs' and tostring(item.shape or '?') or tostring(item.width or '?'))
      end
    end
    local preferred = kind == 'inputs' and preferred_input or (kind == 'outputs' and preferred_output or nil)
    if preferred then
      for index, name in ipairs(rows) do
        if name == preferred and index > 1 then
          table.insert(rows, 1, table.remove(rows, index))
          table.insert(labels, 1, table.remove(labels, index))
          break
        end
      end
    end
    local function enter_custom()
      vim.ui.input({ prompt = prompt }, function(value) if current() then callback(value) end end)
    end
    if #rows == 0 then enter_custom(); return end
    labels[#labels + 1] = tr('Enter another name', '输入其他名称', '輸入其他名稱')
    vim.ui.select(labels, { prompt = kind == 'inputs'
      and tr('Choose a declared model input (checked at forward)', '选择声明的模型输入（前向时检查）', '選擇宣告的模型輸入（前向時檢查）')
      or tr('Choose a declared output (checked at training)', '选择声明的模型输出（训练时检查）', '選擇宣告的模型輸出（訓練時檢查）') }, function(_, index)
      if not current() or not index then return end
      if index <= #rows then callback(rows[index]) else enter_custom() end
    end)
  end
  local function configure_path(path)
    if not path or path == '' or not current() then return end
    local inputs = edit_one and vim.deepcopy(original_params.inputs) or {}
    local function read_header()
      local absolute = path:sub(1, 1) == '/' or path:match('^%a:[/\\]') or path:match('^\\\\')
      local filename = vim.fs.normalize(absolute and path or ((state.opts.working_directory or project) .. '/' .. path))
      local stat = vim.uv.fs_stat(filename)
      if not stat or stat.type ~= 'file' then return nil end
      local file = io.open(filename, 'rb'); if not file then return nil end
      local bytes = file:read(65537); file:close()
      if not bytes then return nil end
      local ending = bytes:find('\n', 1, true)
      if not ending and #bytes > 65536 then return nil end
      local line = (ending and bytes:sub(1, ending - 1) or bytes):gsub('\r$', ''):gsub('^\239\187\191', '')
      local fields, seen, pos, length = {}, {}, 1, #line
      while pos <= length do
        local value
        if line:sub(pos, pos) == '"' then
          pos = pos + 1
          local pieces, closed = {}, false
          while pos <= length do
            local char = line:sub(pos, pos)
            if char == '"' then
              if line:sub(pos + 1, pos + 1) == '"' then pieces[#pieces + 1], pos = '"', pos + 2
              else pos, closed = pos + 1, true; break end
            else pieces[#pieces + 1], pos = char, pos + 1 end
          end
          if not closed or (pos <= length and line:sub(pos, pos) ~= ',') then return nil end
          value = table.concat(pieces)
        else
          local stop = line:find(',', pos, true) or (length + 1)
          value, pos = line:sub(pos, stop - 1), stop
          if value:find('"', 1, true) then return nil end
        end
        if value == '' or value:find('[%c]') or not pcall(vim.str_utfindex, value) or seen[value] then return nil end
        fields[#fields + 1], seen[value] = value, true
        if #fields > 256 then return nil end
        if pos <= length then pos = pos + 1; if pos > length then return nil end end
      end
      return #fields > 0 and fields or nil
    end
    local header = read_header()
    local function choose_columns(prompt, callback, initial)
      local function enter_manually()
        local encoded = {}
        for _, name in ipairs(type(initial) == 'table' and vim.islist(initial) and initial or {}) do
          if type(name) == 'string' then encoded[#encoded + 1] = '"' .. name:gsub('"', '""') .. '"' end
        end
        vim.ui.input({ prompt = prompt, default = table.concat(encoded, ',') }, callback)
      end
      if not header then enter_manually(); return end
      local chosen, present = {}, {}
      if type(initial) == 'table' and vim.islist(initial) then
        local available = {}; for _, name in ipairs(header) do available[name] = true end
        for _, name in ipairs(initial) do
          if not available[name] or present[name] then
            notify(tr('Existing columns are missing or repeated in this header; review the full mapping manually.',
              '已有列在表头中缺失或重复，请手动检查完整映射。', '既有欄位在標頭中缺失或重複，請手動檢查完整對應。'), vim.log.levels.WARN)
            enter_manually(); return
          end
          chosen[#chosen + 1] = name; present[name] = #chosen
        end
      end
      local function menu()
        if not current() then return end
        local options = {}
        for _, name in ipairs(header) do options[#options + 1] = (present[name] and (tostring(present[name]) .. '. ') or '  ') .. name end
        options[#options + 1] = tr('Use selected columns', '使用所选列', '使用所選欄') .. ' (' .. #chosen .. ')'
        options[#options + 1] = tr('Reorder selected columns', '调整所选列顺序', '調整所選欄順序')
        options[#options + 1] = tr('Enter column names manually', '手动输入列名', '手動輸入欄名')
        vim.ui.select(options, { prompt = tr('Choose CSV columns in order; select again to remove.',
          '按顺序选择 CSV 列；再次选择可移除。', '依序選擇 CSV 欄；再次選擇可移除。') }, function(_, index)
          if not current() or not index then return end
          if index <= #header then
            local name = header[index]
            if present[name] then
              present[name] = nil
              for i, item in ipairs(chosen) do if item == name then table.remove(chosen, i); break end end
              for i, item in ipairs(chosen) do present[item] = i end
            else chosen[#chosen + 1] = name; present[name] = #chosen end
            menu()
          elseif index == #header + 1 then
            if #chosen == 0 then notify(tr('Select at least one column.', '请至少选择一列。', '請至少選擇一欄。'), vim.log.levels.WARN); menu(); return end
            local encoded = {}
            for _, name in ipairs(chosen) do encoded[#encoded + 1] = '"' .. name:gsub('"', '""') .. '"' end
            callback(table.concat(encoded, ','))
          elseif index == #header + 2 then
            if #chosen < 2 then
              notify(tr('Select at least two columns to reorder.', '请至少选择两列后调整顺序。', '請至少選擇兩欄後調整順序。'), vim.log.levels.INFO)
              return menu()
            end
            local labels = {}
            for position, name in ipairs(chosen) do labels[position] = tostring(position) .. '. ' .. name end
            vim.ui.select(labels, {prompt = tr('Choose a selected column to move', '选择要移动的已选列', '選擇要移動的已選欄')}, function(_, position)
              if not current() or not position then return end
              local destinations = {}
              for i, name in ipairs(chosen) do
                destinations[i] = tostring(i) .. '. ' .. name
              end
              vim.ui.select(destinations, {prompt = tr('Move to this position', '移动到此位置', '移動至此位置')}, function(_, target)
                if not current() or not target then return end
                local name = table.remove(chosen, position)
                table.insert(chosen, target, name)
                for i, item in ipairs(chosen) do present[item] = i end
                menu()
              end)
            end)
          else enter_manually() end
        end)
      end
      menu()
    end
    local function finish_targets(target_spec)
        local function finish_size(raw_size)
          if not raw_size or not current() then return end
          local size = edit_one and 2 or (raw_size:match('^%d+$') and tonumber(raw_size) or nil)
          if not size or size < 1 or size > 9007199254740991 then
            notify(tr('Enter a positive integer representable exactly by the editor.',
              '请输入编辑器可精确表示的正整数。', '請輸入編輯器可精確表示的正整數。'), vim.log.levels.WARN); return
          end
          local params = edit_one and vim.deepcopy(original_params) or {}
          params.path, params.inputs, params.targets = path, vim.deepcopy(inputs), target_spec
          if not edit_one then params.batch_size = size end
          local warnings = {}
          local draft = draft_context
          if draft then
            local known_inputs, known_outputs = {}, {}
            for _, port in ipairs(draft.inputs or {}) do
              known_inputs[port.name] = true
              local field = inputs[port.name]
              if not field then
                warnings[#warnings + 1] = tr('Missing input: ', '缺少输入：', '缺少輸入：') .. port.name
              elseif type(field) == 'table' and type(port.shape) == 'string' then
                local actual_shape = field.columns and field.shape or {#field}
                local actual_dtype = field.columns and field.dtype or 'float32'
                if type(actual_shape) == 'table' then
                  local expected, dynamic = {}, {}
                  for part in port.shape:gmatch('[^,]+') do
                    local cleaned = vim.trim(part)
                    expected[#expected + 1] = tonumber((cleaned:gsub('^%?', '')))
                    dynamic[#dynamic + 1] = cleaned:sub(1, 1) == '?'
                  end
                  local mismatch = #expected ~= #actual_shape
                  if not mismatch then for i, dim in ipairs(expected) do
                    if not dynamic[i] and dim ~= actual_shape[i] then mismatch = true; break end
                  end end
                  if mismatch then warnings[#warnings + 1] = tr('Input shape differs from declaration: ', '输入形状与声明不同：', '輸入形狀與宣告不同：') .. port.name end
                end
                if type(port.dtype) == 'string' and port.dtype ~= '' and actual_dtype and port.dtype ~= actual_dtype then
                  warnings[#warnings + 1] = tr('Input dtype names differ: ', '输入 dtype 名称不同：', '輸入 dtype 名稱不同：') .. port.name
                end
              end
            end
            for name in pairs(inputs) do if not known_inputs[name] then
              warnings[#warnings + 1] = tr('Input not declared in model: ', '模型未声明的输入：', '模型未宣告的輸入：') .. name
            end end
            for _, port in ipairs(draft.outputs or {}) do known_outputs[port.name] = port end
            local named = type(target_spec) == 'table' and not vim.islist(target_spec) and target_spec['$tensor'] == nil
            if target_spec == nil then
              warnings[#warnings + 1] = tr('No targets: the generated training step needs targets.', '没有目标：生成的训练步骤需要目标。', '沒有目標：產生的訓練步驟需要目標。')
            elseif not named then
              warnings[#warnings + 1] = tr('The generated model uses named targets, even for one output.', '生成的模型使用具名目标，即使只有一个输出也是如此。', '產生的模型使用具名目標，即使只有一個輸出也是如此。')
            else
              for name, port in pairs(known_outputs) do
                local field = target_spec[name]
                if not field then warnings[#warnings + 1] = tr('Missing target for output: ', '输出缺少目标：', '輸出缺少目標：') .. name
                elseif type(field) ~= 'table' then
                  warnings[#warnings + 1] = tr('Target format could not be checked: ', '无法检查目标格式：', '無法檢查目標格式：') .. name
                elseif port.loss == 'ce' and (not field.columns or field.dtype ~= 'int64' or type(field.shape) ~= 'table' or #field.shape ~= 0) then
                  warnings[#warnings + 1] = tr('Cross-entropy normally needs one scalar int64 class index: ', '交叉熵通常需要单个 int64 类别索引：', '交叉熵通常需要單一 int64 類別索引：') .. name
                elseif port.loss == 'mse' and tonumber(port.width) then
                  local shape = field.columns and field.shape or (vim.islist(field) and {#field} or nil)
                  if type(shape) == 'table' and (#shape ~= 1 or shape[1] ~= tonumber(port.width)) then
                    warnings[#warnings + 1] = tr('MSE target shape should match the generated output width: ', '均方误差目标形状应与生成的输出宽度一致：', '均方誤差目標形狀應與產生的輸出寬度一致：') .. name
                  end
                end
              end
              for name in pairs(target_spec) do if not known_outputs[name] then
                warnings[#warnings + 1] = tr('Target not declared in model: ', '模型未声明的目标：', '模型未宣告的目標：') .. name
              end end
            end
          end
          table.sort(warnings)
          local summary = vim.inspect(params)
          local function has_high_rank(fields)
            if type(fields) ~= 'table' then return false end
            for _, field in pairs(fields) do
              if type(field) == 'table' and type(field.shape) == 'table' and #field.shape > 4 then return true end
            end
            return false
          end
          local rank_note = ''
          if has_high_rank(inputs) or has_high_rank(target_spec) then
            rank_note = tr('\nShapes above four dimensions require a compatible model_csv adapter. Existing or edited adapters may need changes; preview to check.\n',
              '\n超过四维的形状需要兼容的 model_csv 适配器；已有或修改过的适配器可能需要调整，请通过预览检查。\n',
              '\n超過四維的形狀需要相容的 model_csv 配接器；既有或修改過的配接器可能需要調整，請透過預覽檢查。\n')
          end
          if not reviewable_text(summary) then
            notify(tr('The CSV configuration is too large to review here. Use an input factory or session parameters instead.',
              'CSV 配置过大，无法在此审核；请使用输入工厂或会话参数。',
              'CSV 設定過大，無法在此檢視；請使用輸入工廠或工作階段參數。'), vim.log.levels.WARN)
            return
          end
          local review_buf = vim.api.nvim_create_buf(false, true)
          vim.bo[review_buf].buftype, vim.bo[review_buf].bufhidden, vim.bo[review_buf].swapfile = 'nofile', 'wipe', false
          local review_lines = { on_draft and tr('CSV draft parameters (only the header may have been read):',
            'CSV 草稿参数（可能已读取表头）：', 'CSV 草稿參數（可能已讀取標頭）：') or tr('CSV session parameters (only the header may have been read):',
            'CSV 会话参数（可能已读取表头）：', 'CSV 工作階段參數（可能已讀取標頭）：'), '' }
          if #warnings > 0 then
            review_lines[#review_lines + 1] = tr('Check these differences before running (custom code may use other contracts):',
              '运行前请检查以下差异（自定义代码可能使用其他契约）：', '執行前請檢查以下差異（自訂程式碼可能使用其他契約）：')
            for _, warning in ipairs(warnings) do review_lines[#review_lines + 1] = '  • ' .. warning end
            review_lines[#review_lines + 1] = ''
          end
          review_lines[#review_lines + 1] = tr('Static comparison only; batch data and model execution have not been checked.',
            '仅做静态对照，尚未检查批次数据或模型执行。', '僅做靜態對照，尚未檢查批次資料或模型執行。')
          review_lines[#review_lines + 1] = ''
          vim.list_extend(review_lines, vim.split(summary .. rank_note, '\n', { plain = true }))
          vim.api.nvim_buf_set_lines(review_buf, 0, -1, false, review_lines)
          vim.bo[review_buf].modifiable = false
          local return_win = vim.api.nvim_get_current_win()
          local return_buf = vim.api.nvim_win_get_buf(return_win)
          if not open_aux_buffer(review_buf, false, false) then return end
          local review_win = vim.api.nvim_get_current_win()
          vim.wo[review_win].wrap = true
          local function close_review()
            local was_focused = vim.api.nvim_get_current_win() == review_win
            if vim.api.nvim_win_is_valid(review_win) and vim.api.nvim_win_get_buf(review_win) == review_buf then
              pcall(vim.api.nvim_win_close, review_win, false)
            end
            if was_focused and vim.api.nvim_win_is_valid(return_win) and vim.api.nvim_win_get_buf(return_win) == return_buf then
              pcall(vim.api.nvim_set_current_win, return_win)
            end
          end
          vim.keymap.set('n', 'q', close_review, { buffer = review_buf, silent = true, desc = 'Cancel CSV configuration' })
          review_gate(review_buf, { tr('Cancel', '取消', '取消'), on_draft and tr('Add to draft', '加入草稿', '加入草稿') or tr('Use for this session', '用于本次会话', '用於本工作階段') },
            on_draft and tr('Add this data declaration to the model draft?', '将此数据声明加入模型草稿？', '將此資料宣告加入模型草稿？') or
            tr('Use these CSV parameters for this session?', '在本次会话使用这些 CSV 参数？', '在本工作階段使用這些 CSV 參數？'), function(_, choice)
            close_review()
            if choice ~= 2 or not current() then return end
            if on_draft then
              local data = edit_one and vim.deepcopy(original_data) or { factory = 'model_csv:batch', binding = 'envelope' }
              data.params = vim.deepcopy(params)
              on_draft(data)
              return
            end
            switch_factory(state, 'batch', 'model_csv:batch')
            state.batch_params, state.batch_binding = params, 'envelope'
            state.change_epoch = (state.change_epoch or 0) + 1
            state.journey = nil
            if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
            state.result_label = tr('CSV input selected; not loaded', '已选择 CSV 输入；尚未加载', '已選擇 CSV 輸入；尚未載入')
            render(state)
            vim.ui.select({
              tr('Preview CSV input', '预览 CSV 输入', '預覽 CSV 輸入'),
              tr('Save input to project', '保存输入到项目', '儲存輸入至專案'),
              tr('Continue in workspace', '返回工作区', '返回工作區'),
            }, { prompt = tr('CSV input is ready', 'CSV 输入已就绪', 'CSV 輸入已就緒') }, function(_, next_step)
              local selected_epoch = state.change_epoch
              vim.schedule(function()
                if state.closed or state.opts.project ~= project or state.change_epoch ~= selected_epoch then return end
                if next_step == 1 and state.actions.j then state.actions.j()
                elseif next_step == 2 and state.actions.S then state.actions.S(true) end
              end)
            end)
          end, nil, true)
        end
        if edit_one then finish_size(tostring(original_params.batch_size or 2))
        else vim.ui.input({ prompt = tr('Batch size (adapter checks its own limit; bundled adapter: 1–256): ',
          '批次大小（由适配器检查限制；内置适配器为 1–256）：', '批次大小（由配接器檢查限制；內建配接器為 1–256）：'), default = '2' }, finish_size) end
    end
    local function configure_custom_field(selected_columns, done)
          vim.ui.input({ prompt = tr('PyTorch dtype name (resolved at runtime): ', 'PyTorch dtype 名称（运行时解析）：', 'PyTorch dtype 名稱（執行時解析）：') }, function(dtype)
            if not dtype or not current() then return end
            if #dtype > 64 or not dtype:match('^[a-zA-Z][a-zA-Z0-9_]*$') then
              notify(tr('Enter a public PyTorch dtype name.', '请输入公开的 PyTorch dtype 名称。', '請輸入公開的 PyTorch dtype 名稱。'), vim.log.levels.WARN); return
            end
            vim.ui.input({ prompt = tr('Shape excluding batch, comma-separated; [] for scalar: ', '不含批次维度的形状，以逗号分隔；标量输入 []：', '不含批次維度的形狀，以逗號分隔；純量輸入 []：'), default = tostring(#selected_columns) }, function(raw_shape)
              if not raw_shape or not current() then return end
              local shape, product = {}, 1
              if vim.trim(raw_shape) ~= '[]' then
                local dimensions = columns(raw_shape)
                if not dimensions or #dimensions > 8 then
                  notify(tr('Use at most eight positive dimensions, or [] for scalar.', '请输入最多八个正整数维度，或用 [] 表示标量。', '請輸入最多八個正整數維度，或用 [] 表示純量。'), vim.log.levels.WARN); return
                end
                for _, item in ipairs(dimensions) do
                  local dim = item:match('^%d+$') and tonumber(item) or nil
                  if not dim or dim < 1 or dim > #selected_columns then
                    notify(tr('Shape dimensions must be positive and match the selected columns.', '形状维度必须为正整数，且与所选列数匹配。', '形狀維度必須為正整數，且與所選欄數相符。'), vim.log.levels.WARN); return
                  end
                  product = product * dim
                  shape[#shape + 1] = dim
                end
              end
              if product ~= #selected_columns then
                notify(tr('The shape product must equal the number of selected columns.', '形状维度的乘积必须等于所选列数。', '形狀維度的乘積必須等於所選欄數。'), vim.log.levels.WARN); return
              end
              done({ columns = selected_columns, shape = shape, dtype = dtype })
            end)
          end)
    end
    local function configure_target(named, done, output_name)
      choose_columns(tr('Target CSV columns; use CSV quotes, e.g. "a,b","say""hi": ',
        '目标 CSV 列名；可用 CSV 引号，例如 "a,b","say""hi"：', '目標 CSV 欄名；可用 CSV 引號，例如 "a,b","say""hi"：'), function(raw_targets)
        if raw_targets == nil or not current() then return end
        local targets = columns(raw_targets)
        if not targets then notify(tr('Enter one or more nonempty column names.', '请输入一个或多个非空列名。', '請輸入一個或多個非空欄名。'), vim.log.levels.WARN); return end
        local loss, width
        for _, port in ipairs(draft_context and draft_context.outputs or {}) do
          if port.name == output_name then loss, width = port.loss, port.width; break end
        end
        local vector = tr('Floating-point target vector', '浮点目标向量', '浮點目標向量')
        local index = tr('Integer class index (one column)', '整数类别索引（单列）', '整數類別索引（單欄）')
        local custom = tr('Custom runtime dtype and shape', '自定义运行时 dtype 和形状', '自訂執行時 dtype 和形狀')
        local ce = loss == 'ce'
        local hint = ce and tr('Cross entropy: scalar int64 class index.', '交叉熵：标量 int64 类别索引。', '交叉熵：純量 int64 類別索引。')
          or loss == 'mse' and (tr('Mean squared error: vector matching output width ', '均方误差：向量匹配输出宽度 ', '均方誤差：向量符合輸出寬度 ') .. tostring(width) .. '.')
          or tr('Choose the target format required by your loss.', '选择损失函数需要的目标格式。', '選擇損失函式需要的目標格式。')
        vim.ui.select(ce and {index, vector, custom} or {vector, index, custom}, {prompt = hint}, function(_, choice)
        if not choice or not current() then return end
        local target_choice = ce and (choice == 1 and 2 or choice == 2 and 1 or choice) or choice
        if target_choice == 2 and #targets ~= 1 then
          notify(tr('A class index needs exactly one target column.', '类别索引需要且只能有一个目标列。', '類別索引需要且只能有一個目標欄。'), vim.log.levels.WARN); return
        end
        local function finish_field(field)
          if not named and type(field) == 'table' and field.columns then field = { ['$tensor'] = field } end
          done(field)
        end
        if target_choice == 3 then configure_custom_field(targets, finish_field); return end
        finish_field(target_choice == 2 and { columns = targets, shape = {}, dtype = 'int64' } or targets)
        end)
      end, target_only and (function()
        local old = original_params.targets[output_name]
        if type(old) == 'table' then return old.columns or old end
      end)() or nil)
    end
    local function ask_target()
      local named_first = draft_context and #(draft_context.outputs or {}) > 0
      local one = tr('One unnamed target (for tensor outputs)', '单个无名目标（适用于张量输出）', '單一無名目標（適用於張量輸出）')
      local named = tr('Named targets for declared outputs', '为声明的输出设置具名目标', '為宣告的輸出設定具名目標')
      local none = tr('No targets (inference; requires an adapter that supports it)', '无目标（推理；适配器须支持）', '無目標（推論；配接器須支援）')
      vim.ui.select(named_first and {named, one, none} or {one, named, none}, {
        prompt = tr('How does the model provide its predictions?', '模型如何提供预测结果？', '模型如何提供預測結果？'),
      }, function(_, mode)
        if not mode or not current() then return end
        if (named_first and mode == 2) or (not named_first and mode == 1) then configure_target(false, finish_targets); return end
        if mode == 3 then finish_targets(nil); return end
        local named_targets = {}
        local function ask_named_target()
          choose_declared_name('outputs', named_targets, tr('Output name matching the model result: ', '与模型结果对应的输出名：', '與模型結果對應的輸出名稱：'), function(name)
            if not name or not current() then return end
            if name == '' or vim.fn.strchars(name) > 128 or name == '$tensor' or name:find('%c') then
              notify(tr('Enter a nonempty output name (up to 128 characters; $tensor is reserved).', '请输入非空输出名（最多 128 字符；$tensor 为保留名称）。', '請輸入非空輸出名稱（最多 128 字元；$tensor 為保留名稱）。'), vim.log.levels.WARN); return
            end
            if named_targets[name] then notify(tr('This output name is already configured.', '该输出名已配置。', '該輸出名稱已設定。'), vim.log.levels.WARN); return end
            configure_target(true, function(spec)
              named_targets[name] = spec
              vim.ui.select({ tr('Continue', '继续', '繼續'), tr('Add another target', '添加另一个目标', '新增另一個目標') }, {
                prompt = tr('Targets configured: ', '已配置目标数：', '已設定目標數：') .. tostring(vim.tbl_count(named_targets)),
              }, function(_, choice)
                if not current() then return end
                if choice == 1 then finish_targets(vim.deepcopy(named_targets))
                elseif choice == 2 and vim.tbl_count(named_targets) < 64 then ask_named_target()
                elseif choice == 2 then notify(tr('At most 64 targets are supported.', '最多支持 64 个目标。', '最多支援 64 個目標。'), vim.log.levels.WARN) end
              end)
            end, name)
          end)
        end
        ask_named_target()
      end)
    end
    local function ask_input()
    local function configure_input(input)
      if not input or not current() then return end
      if input == '' or vim.fn.strchars(input) > 128 or input:find('%c') then
        notify(tr('Enter a nonempty input keyword of at most 128 characters without control characters.',
          '请输入非空输入关键字，最多 128 个字符且不含控制字符。',
          '請輸入非空輸入關鍵字，最多 128 個字元且不含控制字元。'), vim.log.levels.WARN); return
      end
      if inputs[input] and not input_only then notify(tr('This input name is already configured.', '该输入名已配置。', '該輸入名稱已設定。'), vim.log.levels.WARN); return end
      choose_columns(tr('Input CSV columns, e.g. "a,b","say""hi" (bundled adapter: 256 distinct columns): ',
        '输入 CSV 列名，例如 "a,b","say""hi"（内置适配器最多 256 个不同列）：',
        '輸入 CSV 欄名，例如 "a,b","say""hi"（內建配接器最多 256 個不同欄）：'), function(raw_inputs)
        if raw_inputs == nil or not current() then return end
        local input_columns = columns(raw_inputs)
        if not input_columns then notify(tr('Enter one or more nonempty column names.', '请输入一个或多个非空列名。', '請輸入一個或多個非空欄名。'), vim.log.levels.WARN); return end
        local function finish_input(field)
          if not current() then return end
          inputs[input] = field
          if input_only then finish_targets(vim.deepcopy(original_params.targets)); return end
          vim.ui.select({ tr('Continue to targets', '继续设置目标', '繼續設定目標'), tr('Add another input', '添加另一个输入', '新增另一個輸入') }, {
            prompt = tr('Inputs configured: ', '已配置输入数：', '已設定輸入數：') .. tostring(vim.tbl_count(inputs)),
          }, function(_, choice)
            if not current() then return end
            if choice == 1 then ask_target()
            elseif choice == 2 and vim.tbl_count(inputs) < 64 then ask_input()
            elseif choice == 2 then notify(tr('At most 64 inputs are supported.', '最多支持 64 个输入。', '最多支援 64 個輸入。'), vim.log.levels.WARN) end
          end)
        end
        local declared, candidate = draft_context, nil
        for _, row in ipairs(declared and declared.inputs or {}) do
          if row.name == input and type(row.dtype) == 'string' and row.dtype ~= '' and type(row.shape) == 'string' then
            local shape, product = {}, 1
            for token in row.shape:gmatch('[^,]+') do
              local value = tonumber((vim.trim(token):gsub('^%?', '')))
              if not value or value < 1 or value % 1 ~= 0 then product = 0; break end
              shape[#shape + 1], product = value, product * value
            end
            if #shape > 0 and #shape <= 8 and product == #input_columns then
              candidate = {columns = input_columns, shape = shape, dtype = row.dtype}
            end
            break
          end
        end
        local preserved
        local old_field = input_only and original_params.inputs[input]
        if type(old_field) == 'table' and type(old_field.columns) == 'table'
            and type(old_field.shape) == 'table' and vim.islist(old_field.shape)
            and type(old_field.dtype) == 'string' then
          local product = 1
          for _, dim in ipairs(old_field.shape) do
            if type(dim) ~= 'number' or dim < 1 or dim % 1 ~= 0 then product = 0; break end
            product = product * dim
          end
          if product == #input_columns then preserved = vim.deepcopy(old_field); preserved.columns = input_columns end
        end
        local choices = {}
        if preserved then choices[#choices + 1] = tr('Keep current shape and dtype', '保留当前形状和 dtype', '保留目前形狀和 dtype') end
        if candidate then choices[#choices + 1] = tr('Use declared shape and dtype', '使用已声明的形状和 dtype', '使用已宣告的形狀和 dtype')
          .. ' · ' .. table.concat(candidate.shape, '×') .. ' · ' .. candidate.dtype end
        choices[#choices + 1] = tr('Float32 vector', 'float32 向量', 'float32 向量')
        choices[#choices + 1] = tr('Custom runtime dtype and shape', '自定义运行时 dtype 和形状', '自訂執行時 dtype 和形狀')
        vim.ui.select(choices, {
          prompt = tr('Choose this input format (dynamic dimensions use their declared sample size):',
            '选择输入格式（动态维度使用声明的样本大小）：', '選擇輸入格式（動態維度使用宣告的樣本大小）：'),
        }, function(_, choice)
          if not current() then return end
          if not choice then return end
          if preserved then
            if choice == 1 then finish_input(preserved); return end
            choice = choice - 1
          end
          if candidate and choice == 1 then finish_input(candidate); return end
          local index = candidate and choice - 1 or choice
          if index == 1 then finish_input(input_columns)
          elseif index == 2 then configure_custom_field(input_columns, finish_input) end
        end)
      end, input_only and (function()
        local old = original_params.inputs[input]
        if type(old) == 'table' then return old.columns or old end
      end)() or nil)
    end
    if input_only then configure_input(preferred_input)
    else choose_declared_name('inputs', inputs, tr('Model input keyword (checked by the model when run): ',
      '模型输入关键字（运行时由模型检查）：', '模型輸入關鍵字（執行時由模型檢查）：'), configure_input) end
    end
    if target_only then
      configure_target(true, function(spec)
        local targets = vim.deepcopy(original_params.targets)
        targets[preferred_output] = spec
        finish_targets(targets)
      end, preferred_output)
    else ask_input() end
  end
  if edit_one then configure_path(original_params.path)
  else vim.ui.input({ prompt = tr('CSV path (relative to runtime working directory or absolute): ',
    'CSV 路径（相对运行目录或绝对路径）：', 'CSV 路徑（相對執行目錄或絕對路徑）：'), completion = 'file' }, configure_path) end
end

local function create_csv_adapter(state, preferred_input, on_draft, preferred_output, draft_override)
  if state.closed or state.busy then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local function current()
    return not state.closed and not state.busy and state.opts.project == project
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  state.busy = tr('Checking CSV adapter support', '检查 CSV 适配能力', '檢查 CSV 配接能力'); render(state)
  request(state, { '--describe-interface' }, function(interface, failure)
    state.busy = nil
    local caps = interface and interface.data and interface.data.capabilities
    if failure or not current() or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
        or type(caps) ~= 'table' or caps['data.csv_batch_runtime_dtype_v1'] ~= true then
      render(state)
      notify(tr('A compatible CLI and unchanged project context are required.', '需要兼容的 CLI 和未变化的项目上下文。', '需要相容的 CLI 和未變更的專案上下文。'), vim.log.levels.WARN); return
    end
    state.busy = tr('Planning CSV adapter', '规划 CSV 适配器', '規劃 CSV 配接器'); render(state)
    request(state, { 'data', 'csv-template' }, function(report, err, stderr)
      state.busy = nil
      if not current() then render(state); return end
      state.last = { report = report, transport_error = err, stderr = stderr }
      render(state)
      local data = report and report.data
      local plan = type(data) == 'table' and data.plan or nil
      if err or not report or report.operation ~= 'data_csv_template' or report.status ~= 'success'
          or type(data) ~= 'table' or data.committed ~= false or not sha256(data.plan_revision)
          or type(plan) ~= 'table' or plan.file ~= 'model_csv.py' or plan.entrypoint ~= 'model_csv:batch'
          or not reviewable_text(plan.source) or plan.source == '' then
        show_report(state); notify(tr('CSV adapter plan could not be reviewed; no file was created.',
          'CSV 适配计划无法审阅；没有创建文件。', 'CSV 配接計畫無法檢視；沒有建立檔案。'), vim.log.levels.WARN); return
      end
      local listed = state.last
      local buf = show_report(state)
      if not buf or not vim.api.nvim_buf_is_valid(buf) then return end
      vim.bo[buf].modifiable = true
      local source_lines = { tr('Proposed CSV adapter source (new project file):', '拟创建的 CSV 适配器源码：', '擬建立的 CSV 配接器原始碼：'), '' }
      vim.list_extend(source_lines, vim.split(plan.source, '\n', { plain = true }))
      vim.api.nvim_buf_set_lines(buf, 0, 0, false, source_lines)
      vim.bo[buf].modifiable = false
      review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Create adapter', '创建适配器', '建立配接器') },
        tr('Create this file without overwriting? It does not load or configure data.',
          '创建此文件且不覆盖已有文件？此操作不会加载或配置数据。', '建立此檔案且不覆寫既有檔案？此操作不會載入或設定資料。'), function(_, choice)
        if choice ~= 2 or not current() or state.last ~= listed then return end
        local tracked = begin_tracked_commit(state, tr('Create CSV adapter', '创建 CSV 适配器', '建立 CSV 配接器'))
        if not tracked then return end
        state.busy = tr('Creating CSV adapter', '创建 CSV 适配器', '建立 CSV 配接器'); render(state)
        request(state, { 'data', 'csv-template', '--apply', '--if-plan', data.plan_revision }, function(receipt, problem, output)
          state.busy = nil
          if not current() then
            settle_tracked_commit(state, tracked, false, problem)
            render(state)
            notify(tr('Project context changed during creation; inspect model_csv.py in the original project before retrying.',
              '创建期间项目上下文已变化；重试前请检查原项目中的 model_csv.py。',
              '建立期間專案上下文已變更；重試前請檢查原專案中的 model_csv.py。'), vim.log.levels.WARN); return
          end
          state.last = { report = receipt, transport_error = problem, stderr = output }
          local saved = receipt and receipt.data
          local verified = not problem and receipt and receipt.operation == 'data_csv_template' and receipt.status == 'success'
              and type(saved) == 'table' and saved.committed == true and saved.plan_revision == data.plan_revision
              and saved.entrypoint == 'model_csv:batch'
          local settled = settle_tracked_commit(state, tracked, verified, problem)
          if not verified or not settled then
            render(state); show_report(state)
            notify(tr('Creation outcome needs inspection before retry.', '重试前请核查创建结果。', '重試前請核查建立結果。'), vim.log.levels.WARN); return
          end
          state.result_label = tr('CSV adapter created; configure its inputs', 'CSV 适配器已创建；请配置输入', 'CSV 配接器已建立；請設定輸入')
          render(state)
          local review_window = vim.fn.bufwinid(buf)
          if review_window ~= -1 and vim.api.nvim_win_is_valid(review_window)
              and vim.api.nvim_win_get_buf(review_window) == buf then
            pcall(vim.api.nvim_win_close, review_window, false)
          end
          vim.ui.select({
            tr('Configure CSV input', '配置 CSV 输入', '設定 CSV 輸入'),
            tr('Open adapter source', '打开适配器源码', '開啟配接器原始碼'),
            tr('Return to workspace', '返回工作区', '返回工作區'),
          }, { prompt = tr('CSV adapter created', 'CSV 适配器已创建', 'CSV 配接器已建立') }, function(_, choice)
            if state.closed or state.opts.project ~= project then return end
            if choice == 1 then configure_csv_adapter(state, preferred_input, on_draft, preferred_output, nil, nil, draft_override)
            elseif choice == 2 then
              local path = vim.uv.fs_realpath(project .. '/model_csv.py')
              if path and in_project(project, path) then focus_source(state, path) end
            end
          end)
        end)
      end, nil, true)
    end)
  end)
end

local function choose_factory_parameters(state)
  if state.busy then notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN); return end
  vim.ui.select({ tr('Model factory parameters', '模型工厂参数', '模型工廠參數'), tr('Input factory parameters', '输入工厂参数', '輸入工廠參數'),
    tr('Input binding', '输入绑定方式', '輸入繫結方式'), tr('Forward / assembly / source-edit seed', '前向 / 装配 / 源码编辑种子', '前向 / 裝配 / 原始碼編輯種子'),
    tr('Forward model device', '前向模型设备', '前向模型裝置'), tr('Training seed', '训练种子', '訓練種子'),
    tr('Training model initialization', '训练模型初始化', '訓練模型初始化') }, {
    prompt = tr('Choose session input settings', '选择本会话的输入设置', '選擇本工作階段的輸入設定'),
  }, function(_, choice)
    if not choice or state.closed or state.busy then return end
    if choice == 7 then
      local project, epoch = state.opts.project, state.change_epoch or 0
      request(state, { '--describe-interface' }, function(report, err)
        if err or state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch then return end
        local caps = report and report.data and report.data.capabilities
        if not caps or caps['training.model_initialization_v1'] ~= true then
          notify(tr('The selected CLI does not support separate model initialization.', '所选 CLI 不支持独立模型初始化。', '所選 CLI 不支援獨立模型初始化。'), vim.log.levels.WARN)
          return
        end
        vim.ui.select({ tr('Use CLI default', '使用 CLI 默认值', '使用 CLI 預設值'),
          tr('Runtime random state', '运行时随机状态', '執行階段隨機狀態'),
          tr('Choose construction seed', '指定构造种子', '指定建構種子') },
          { prompt = tr('Model initialization for new training', '新训练的模型初始化', '新訓練的模型初始化') }, function(_, selected)
            if not selected or state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch then return end
            local function save(policy, seed)
              if state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch then return end
              state.model_initialization, state.model_initialization_seed = policy, seed
              state.change_epoch = epoch + 1
              if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
              state.result_label = tr('model initialization changed', '模型初始化已变化', '模型初始化已變更')
              render(state)
            end
            if selected == 1 then save(nil, nil); return end
            if selected == 2 then save('runtime', nil); return end
            vim.ui.input({ prompt = tr('Construction seed, unsigned 64-bit: ', '构造种子，无符号 64 位整数：', '建構種子，無符號 64 位整數：') }, function(value)
              if not value then return end
              local normalized = value:gsub('^0+', '')
              if value ~= '' and normalized == '' then normalized = '0' end
              if not value:match('^%d+$') or #normalized > 20 or (#normalized == 20 and normalized > '18446744073709551615') then
                notify(tr('Enter an unsigned 64-bit integer.', '请输入无符号 64 位整数。', '請輸入無符號 64 位整數。'), vim.log.levels.WARN); return
              end
              save('seeded', normalized)
            end)
          end)
      end)
      return
    end
    if choice == 6 then
      local project, epoch, original = state.opts.project, state.change_epoch or 0, state.training_seed
      vim.ui.input({ prompt = tr('New training execution seed, unsigned 64-bit (empty uses CLI default): ',
        '新训练执行种子，无符号 64 位整数（留空使用 CLI 默认值）：',
        '新訓練執行種子，無符號 64 位整數（留空使用 CLI 預設值）：'), default = original or '' }, function(value)
        if value == nil or state.closed or state.busy or state.opts.project ~= project
            or (state.change_epoch or 0) ~= epoch or state.training_seed ~= original then return end
        local normalized = value:gsub('^0+', '')
        if value ~= '' and normalized == '' then normalized = '0' end
        if value ~= '' and (not value:match('^%d+$') or #normalized > 20
            or (#normalized == 20 and normalized > '18446744073709551615')) then
          notify(tr('Enter an unsigned 64-bit integer.', '请输入无符号 64 位整数。', '請輸入無符號 64 位整數。'), vim.log.levels.WARN); return
        end
        local chosen = value ~= '' and normalized or nil
        if chosen == original then return end
        state.training_seed = chosen
        state.change_epoch = epoch + 1
        state.journey = nil
        if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
        state.result_label = tr('training seed changed', '训练种子已变化', '訓練種子已變更')
        render(state)
      end)
      return
    end
    if choice == 5 then
      local project, epoch, original, cli = state.opts.project, state.change_epoch or 0, state.probe_device, state.opts.cli
      local function current()
        return not state.closed and not state.busy and state.opts.project == project
          and (state.change_epoch or 0) == epoch and state.probe_device == original and state.opts.cli == cli
      end
      vim.ui.input({ prompt = tr('Model device (e.g. cpu, cuda:0 or auto; empty keeps factory placement): ',
        '模型设备（如 cpu、cuda:0 或 auto；留空保留工厂位置）：',
        '模型裝置（如 cpu、cuda:0 或 auto；留空保留工廠位置）：'), default = original or '' }, function(value)
        if value == nil or not current() then return end
        if #value > 128 or value:find('[%c%s]') then
          notify(tr('Enter a device identifier without whitespace or controls.', '请输入不含空白或控制字符的设备标识。', '請輸入不含空白或控制字元的裝置識別碼。'), vim.log.levels.WARN); return
        end
        local chosen
        if value ~= '' then chosen = value end
        if chosen == original then return end
        local function save()
          if not current() then return end
          state.probe_device = chosen
          state.change_epoch = epoch + 1
          state.journey = nil
          if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
          state.result_label = tr('forward device changed; recheck', '前向设备已变化，请重验', '前向裝置已變更，請重新驗證')
          render(state)
        end
        if not chosen then save(); return end
        request(state, { '--describe-interface' }, function(report, err)
          if not current() then return end
          local caps = not err and report and report.status == 'success' and type(report.data) == 'table' and report.data.capabilities or nil
          if type(caps) ~= 'table' or caps['probe.model_device_v1'] ~= true then
            notify(tr('This CLI cannot select a forward model device. Update it or keep factory placement.',
              '当前 CLI 不支持选择前向模型设备；请更新或保留工厂位置。', '目前 CLI 不支援選擇前向模型裝置；請更新或保留工廠位置。'), vim.log.levels.WARN); return
          end
          save()
        end)
      end)
      return
    end
    if choice == 4 then
      local project, epoch, original = state.opts.project, state.change_epoch or 0, state.probe_seed
      vim.ui.input({ prompt = tr('Forward, assembly and source-edit seed, unsigned 64-bit (empty uses runtime policy): ',
        '前向、装配和源码编辑种子，无符号 64 位整数（留空使用运行时策略）：',
        '前向、裝配與原始碼編輯種子，無符號 64 位整數（留空使用執行時策略）：'), default = original or '' }, function(value)
        if value == nil or state.closed or state.busy or state.opts.project ~= project
            or (state.change_epoch or 0) ~= epoch or state.probe_seed ~= original then return end
        local normalized = value:gsub('^0+', '')
        if value ~= '' and normalized == '' then normalized = '0' end
        if value ~= '' and (not value:match('^%d+$') or #normalized > 20
            or (#normalized == 20 and normalized > '18446744073709551615')) then
          notify(tr('Enter an unsigned 64-bit integer.', '请输入无符号 64 位整数。', '請輸入無符號 64 位整數。'), vim.log.levels.WARN); return
        end
        local chosen
        if value ~= '' then chosen = normalized end
        if chosen == original then return end
        state.probe_seed = chosen
        state.change_epoch = epoch + 1
        state.journey = nil
        if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
        state.result_label = tr('forward seed changed; recheck', '前向种子已变化，请重验', '前向種子已變更，請重新驗證')
        render(state)
      end)
      return
    end
    if choice == 3 then
      local project, epoch, batch = state.opts.project, state.change_epoch or 0, state.batch
      local values = { false, 'single', 'args', 'kwargs', 'envelope', 'single-raw' }
      local labels = {
        batch and tr('Automatic', '自动', '自動') or (tr('Use project binding: ', '使用项目绑定：', '使用專案繫結：')
          .. (state.project_info and state.project_info.batch_binding or tr('automatic', '自动', '自動'))),
        tr('Single value (after dataset sampling)', '单个值（数据集会先采样）', '單個值（資料集會先取樣）'), tr('Positional arguments', '位置参数', '位置參數'),
        tr('Keyword arguments', '关键字参数', '關鍵字參數'), tr('Explicit args/kwargs envelope', '显式 args/kwargs 封装', '明確 args/kwargs 封裝'),
        tr('Whole factory result (no dataset sampling)', '整个工厂返回值（不进行数据集采样）', '整個工廠回傳值（不進行資料集取樣）'),
      }
      if not batch and state.project_info and state.project_info.batch then
        labels[#labels + 1] = tr('Automatic for the current project input', '当前项目输入使用自动绑定', '目前專案輸入使用自動繫結')
      elseif batch and state.project_info and state.project_info.batch then
        labels[#labels + 1] = tr('Restore project input and binding', '恢复项目输入和绑定', '還原專案輸入與繫結')
      end
      vim.ui.select(labels, { prompt = tr('How should this input reach forward?', '此输入如何传给 forward？', '此輸入如何傳給 forward？') }, function(_, index)
        if not index or state.closed or state.busy or state.opts.project ~= project
            or (state.change_epoch or 0) ~= epoch or state.batch ~= batch then return end
        if index == 7 then
          local config, status = project_config(project)
          if status ~= 'present' or not project_config_current(state) or type(config.batch) ~= 'string'
              or not state.project_info or config.batch ~= state.project_info.batch then
            notify(tr('Project input changed; refresh the project before choosing a binding.',
              '项目输入已变化；请刷新项目后再选择绑定。', '專案輸入已變更；請重新整理專案後再選擇繫結。'), vim.log.levels.WARN); return
          end
          if batch then
            -- Keep the current factory draft for later, but actually fall
            -- back to the project's factory, parameters and binding now.
            switch_factory(state, 'batch', nil)
            state.batch_params, state.batch_binding = {}, nil
            state.preserved_batch_draft = batch
            state.change_epoch = epoch + 1
            state.journey = nil
            if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
            state.result_label = tr('project input restored; recheck', '已恢复项目输入，请重验', '已還原專案輸入，請重新驗證')
            render(state)
            return
          end
          local params = type(config.batch_params) == 'table' and vim.deepcopy(config.batch_params) or {}
          for name, value in pairs(state.batch_params or {}) do params[name] = vim.deepcopy(value) end
          local count = 0
          for name, value in pairs(params) do
            count = count + 1
            if count > 64 or not parameter_name_candidate(name) or not pcall(vim.json.encode, value) then
              notify(tr('Project input parameters cannot be passed safely; choose the factory and edit parameters manually.',
                '无法安全传递项目输入参数；请选择工厂并手动编辑参数。',
                '無法安全傳遞專案輸入參數；請選擇工廠並手動編輯參數。'), vim.log.levels.WARN); return
            end
          end
          vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Use automatic binding for this session', '本会话使用自动绑定', '本工作階段使用自動繫結') }, {
            prompt = tr('The current factory and parameters become session overrides. Parameter values may appear in process arguments and run records. Continue?',
              '当前工厂与参数将成为会话覆盖。参数值可能出现在进程参数和运行记录中，是否继续？',
              '目前工廠與參數將成為工作階段覆蓋。參數值可能出現在程序參數與執行紀錄中，是否繼續？'),
          }, function(_, confirmed)
            if confirmed ~= 2 or state.closed or state.busy or state.opts.project ~= project
                or (state.change_epoch or 0) ~= epoch or state.batch ~= batch or not project_config_current(state) then return end
            switch_factory(state, 'batch', config.batch)
            state.batch_params, state.batch_binding = params, nil
            state.change_epoch = epoch + 1
            state.journey = nil
            if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
            state.result_label = tr('input binding changed; recheck', '输入绑定已变化，请重验', '輸入繫結已變更，請重新驗證')
            render(state)
          end)
          return
        end
        local value = values[index] or nil
        if state.batch_binding == value then return end
        local function apply_binding()
          if state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
              or state.batch ~= batch or not project_config_current(state) then return end
          state.batch_binding = value
          state.change_epoch = epoch + 1
          state.journey = nil
          if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
          state.result_label = tr('input binding changed; recheck', '输入绑定已变化，请重验', '輸入繫結已變更，請重驗')
          render(state)
        end
        if value ~= 'single-raw' then apply_binding(); return end
        request(state, { '--describe-interface' }, function(report, err)
          local caps = not err and report and report.status == 'success' and type(report.data) == 'table' and report.data.capabilities or nil
          if type(caps) ~= 'table' or caps['data.raw_batch_binding_v1'] ~= true then
            notify(tr('This CLI cannot bind the whole factory result. Update it first.',
              '当前 CLI 不支持整体绑定工厂返回值，请先更新。', '目前 CLI 不支援整體繫結工廠回傳值，請先更新。'), vim.log.levels.WARN); return
          end
          apply_binding()
        end)
      end)
      return
    end
    local field = choice == 1 and 'model_params' or 'batch_params'
    local original = vim.deepcopy(state[field] or {})
    local project, epoch, model, batch = state.opts.project, state.change_epoch or 0, state.model, state.batch
    local encoded, default = pcall(vim.json.encode, next(original) and original or vim.empty_dict())
    if not encoded then
      notify(tr('Current overrides cannot be displayed as JSON.', '当前覆盖参数无法显示为 JSON。', '目前覆蓋參數無法顯示為 JSON。'), vim.log.levels.WARN); return
    end
    vim.ui.input({ prompt = tr('JSON object; replaces overrides. Values may appear in process arguments and records; no secrets: ',
      'JSON 对象，将替换当前覆盖；值可能出现在进程参数和记录中，请勿填密钥：',
      'JSON 物件，將取代目前覆蓋；值可能出現在程序參數和紀錄中，請勿填金鑰：'), default = default }, function(raw)
      if not raw or state.closed or state.busy then return end
      if state.opts.project ~= project or (state.change_epoch or 0) ~= epoch or state.model ~= model or state.batch ~= batch
          or not vim.deep_equal(state[field] or {}, original) then
        notify(tr('The project or overrides changed; reopen the parameter editor.',
          '项目或覆盖参数已变化，请重新打开参数编辑。', '專案或覆蓋參數已變更，請重新開啟參數編輯。'), vim.log.levels.WARN); return
      end
      local decoded, values = pcall(vim.json.decode, raw)
      if #raw > 16384 or not decoded or type(values) ~= 'table' or not raw:match('^%s*{') then
        notify(tr('Enter a JSON object no larger than 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
      end
      local count = 0
      for name, value in pairs(values) do
        count = count + 1
        if count > 64 or not parameter_name_candidate(name)
            or not pcall(vim.json.encode, value) then
          notify(tr('Parameter names or values are invalid, or there are more than 64 parameters.',
            '参数名或值无效，或参数超过 64 个。', '參數名稱或值無效，或參數超過 64 個。'), vim.log.levels.WARN); return
        end
      end
      if vim.deep_equal(original, values) then return end
      state[field] = values
      state.change_epoch = (state.change_epoch or 0) + 1
      state.journey = nil
      if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
      state.result_label = tr('parameters changed; recheck', '参数已变化，请重验', '參數已變更，請重驗')
      render(state)
    end)
  end)
end

local function choose_training_device(state, mode, callback)
  local epoch, project = state.change_epoch or 0, state.opts.project
  local function selected_device(device)
    if mode == 'external-loop' then callback(device, nil); return end
    vim.ui.select({
      tr('Move tensors strictly; stop if supported structure or shared views cannot be preserved', '严格迁移；无法保留受支持结构或共享视图时中止', '嚴格遷移；無法保留受支援結構或共享視圖時中止'),
      tr('Keep the batch as supplied; my code manages its device', '保留批次原样，由我的代码处理设备', '保留批次原樣，由我的程式碼處理裝置'),
    }, { prompt = tr('How should the batch reach your training step?', '批次如何进入训练步骤？', '批次如何進入訓練步驟？') }, function(_, choice)
      if not choice or state.closed or state.busy or state.opts.project ~= project
          or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then return end
      callback(device, choice == 1 and 'recursive-strict' or 'preserve')
    end)
  end
  local observed = state.device_inventory
  local choices = {
    { id = 'cpu', label = tr('CPU (checked at execution)', 'CPU（运行时检查）', 'CPU（執行時檢查）') },
    { id = 'auto', label = tr('Automatic (resolved at execution)', '自动选择（运行时解析）', '自動選擇（執行時解析）') },
  }
  if observed and observed.epoch == epoch then
    for _, device in ipairs(observed.devices) do
      choices[#choices + 1] = { id = device.id, label = device.id .. ' · ' .. device.backend .. ' · ' .. device.name
        .. tr(' (observed ', '（观察于 ', '（觀察於 ') .. observed.observed_at
        .. (observed.status == 'partial' and tr(', partial query)', '，查询不完整）', '，查詢不完整）') or tr(')', '）', '）')) }
    end
  end
  choices[#choices + 1] = { manual = true, label = tr('Enter a supported device identifier', '手动输入支持的设备标识', '手動輸入支援的裝置識別碼') }
  vim.ui.select(choices, { prompt = tr('Choose a device; other PyTorch backends can be entered manually', '选择设备；其他 PyTorch 后端可手动输入', '選擇裝置；其他 PyTorch 後端可手動輸入'),
    format_item = function(item) return item.label end }, function(item)
    if not item or state.closed or state.busy or state.opts.project ~= project
        or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then return end
    if item.manual then
      vim.ui.input({ prompt = tr('PyTorch device or auto (checked at runtime): ', 'PyTorch 设备标识或 auto（运行时检查）：', 'PyTorch 裝置識別碼或 auto（執行時檢查）：'), default = '' }, function(value)
        if not value or value == '' or state.closed or state.busy or state.opts.project ~= project
            or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then return end
        selected_device(value)
      end)
    else
      selected_device(item.id)
    end
  end)
end

local function choose_optimizer_parameters(mode, callback)
  if mode == 'external-loop' then callback({}, ''); return end
  local function choose_default()
  vim.ui.input({ prompt = tr('AdamW learning rate (empty = backend default): ', 'AdamW 学习率（留空使用后端默认值）：', 'AdamW 學習率（留空使用後端預設值）：'), default = '' }, function(lr)
    if lr == nil then return end
    local number = lr ~= '' and tonumber(lr) or nil
    if lr ~= '' and (not number or number ~= number or number == math.huge or number == -math.huge or number <= 0) then
      notify(tr('Learning rate must be a positive finite number.', '学习率必须是有限正数。', '學習率必須是有限正數。'), vim.log.levels.WARN); return
    end
    vim.ui.input({ prompt = tr('Weight decay (empty = backend default): ', '权重衰减（留空使用后端默认值）：', '權重衰減（留空使用後端預設值）：'), default = '' }, function(decay)
      if decay == nil then return end
      local value = decay ~= '' and tonumber(decay) or nil
      if decay ~= '' and (not value or value ~= value or value == math.huge or value == -math.huge or value < 0) then
        notify(tr('Weight decay must be a nonnegative finite number.', '权重衰减必须是有限非负数。', '權重衰減必須是有限非負數。'), vim.log.levels.WARN); return
      end
      local args = {}
      if lr ~= '' then vim.list_extend(args, { '--lr', lr }) end
      if decay ~= '' then vim.list_extend(args, { '--weight-decay', decay }) end
      local description = tr('\nLearning rate: ', '\n学习率：', '\n學習率：') .. (lr ~= '' and lr or tr('backend default', '后端默认', '後端預設'))
        .. tr('\nWeight decay: ', '\n权重衰减：', '\n權重衰減：') .. (decay ~= '' and decay or tr('backend default', '后端默认', '後端預設'))
      if mode == 'manual-step' then
        description = description .. tr('\nThese are AdamW fallback values; the user step may override them.',
          '\n这些是 AdamW 默认值；用户步骤可以覆盖。', '\n這些是 AdamW 預設值；使用者步驟可以覆寫。')
      end
      callback(args, description)
    end)
  end)
  end
  if mode == 'manual-step' then
    vim.ui.select({
      tr('Use backend defaults', '使用后端默认值', '使用後端預設值'),
      tr('Configure fallback AdamW parameters', '设置 AdamW 默认参数', '設定 AdamW 預設參數'),
    }, { prompt = tr('Defaults apply only when your step registers AdamW without its own values',
      '仅当你的步骤注册 AdamW 且未指定参数时使用这些默认值',
      '僅當你的步驟註冊 AdamW 且未指定參數時使用這些預設值') }, function(_, choice)
      if choice == 1 then
        callback({}, tr('\nAdamW fallback: backend defaults; user step may override them.',
          '\nAdamW 默认参数：后端默认；用户步骤可以覆盖。',
          '\nAdamW 預設參數：後端預設；使用者步驟可以覆寫。'))
      elseif choice == 2 then choose_default() end
    end)
    return
  end
  if mode ~= 'managed-step' then choose_default(); return end
  vim.ui.select({
    tr('AdamW with backend defaults', 'AdamW（后端默认参数）', 'AdamW（後端預設參數）'),
    tr('Configure AdamW parameters', '设置 AdamW 参数', '設定 AdamW 參數'),
    tr('Use my optimizer factory', '使用自定义优化器工厂', '使用自訂最佳化器工廠'),
  }, {
    prompt = tr('Choose optimizer', '选择优化器', '選擇最佳化器'),
  }, function(_, choice)
    if choice == 1 then
      callback({}, tr('\nLearning rate: backend default\nWeight decay: backend default',
        '\n学习率：后端默认\n权重衰减：后端默认', '\n學習率：後端預設\n權重衰減：後端預設'))
      return
    end
    if choice == 2 then choose_default(); return end
    if choice ~= 3 then return end
    vim.ui.input({ prompt = tr('Optimizer factory module:callable: ', '优化器工厂 module:callable：', '最佳化器工廠 module:callable：') }, function(factory)
      if not factory or factory == '' then return end
      vim.ui.input({ prompt = tr('Factory parameters as JSON (recorded; no secrets): ',
        '工厂参数 JSON（会记录，请勿填写密钥）：', '工廠參數 JSON（會記錄，請勿填寫密鑰）：'), default = '{}' }, function(raw)
        if raw == nil then return end
        local ok, values = pcall(vim.json.decode, raw)
        if #raw > 65536 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') then
          notify(tr('Enter a JSON object of at most 64 KiB.', '请输入不超过 64 KiB 的 JSON 对象。', '請輸入不超過 64 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
        end
        local names, args = vim.tbl_keys(values), { '--optimizer-factory', factory }
        if #names > 64 then notify(tr('At most 64 parameters are supported.', '最多支持 64 个参数。', '最多支援 64 個參數。'), vim.log.levels.WARN); return end
        table.sort(names)
        for _, name in ipairs(names) do
          if not identifier_candidate(name) then
            notify(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。'), vim.log.levels.WARN); return
          end
          local encoded, value = pcall(vim.json.encode, values[name])
          if not encoded then notify(tr('Invalid parameter value.', '参数值无效。', '參數值無效。'), vim.log.levels.WARN); return end
          vim.list_extend(args, { '--optimizer-param', name .. '=' .. value })
        end
        callback(args, tr('\nOptimizer factory: ', '\n优化器工厂：', '\n最佳化器工廠：') .. factory
          .. tr('\nOptimizer parameter names: ', '\n优化器参数名：', '\n最佳化器參數名稱：') .. (#names > 0 and table.concat(names, ', ') or tr('none', '无', '無'))
          .. tr('\nThe factory runs user code and receives the model.', '\n工厂接收模型并执行用户代码。', '\n工廠接收模型並執行使用者程式碼。'), true)
      end)
    end)
  end)
end

local declared_training

local function optimizer_profile(args)
  local profile = {}
  for index = 1, #args, 2 do
    local key, value = args[index], args[index + 1]
    if key == '--lr' then profile.lr = tonumber(value)
    elseif key == '--weight-decay' then profile.weight_decay = tonumber(value)
    elseif key == '--optimizer-factory' then profile.factory = value
    elseif key == '--optimizer-param' then
      local name, raw = value:match('^([^=]+)=(.*)$')
      local ok, decoded = pcall(vim.json.decode, raw or '')
      if not name or not ok then return nil end
      profile.params = profile.params or {}
      profile.params[name] = decoded
    else return nil end
  end
  return next(profile) and profile or vim.empty_dict()
end

local function choose_and_remember_optimizer(state, project, mode, entry, callback, graph_optimizer)
  local root, cli, python = state.opts.project, state.opts.cli, state.opts.python
  local revision, model = project.config_revision, state.model or project.model
  local function current()
    return not state.closed and not state.busy and state.opts.project == root and state.opts.cli == cli
      and state.opts.python == python and state.project_info and state.project_info.config_revision == revision
      and (state.model or state.project_info.model) == model and project_config_current(state)
  end
  local function choose_new()
    choose_optimizer_parameters(mode, function(args, description, custom)
      if not current() then
        notify(tr('Project or environment changed; prepare training again.', '项目或环境已变化，请重新准备训练。', '專案或環境已變更，請重新準備訓練。'), vim.log.levels.WARN)
        return
      end
      state.last_training_optimizer = { project = root, cli = cli, python = python, revision = revision,
        model = model, mode = mode, entry = entry, args = vim.deepcopy(args), description = description, custom = custom }
      callback(args, description, custom)
    end)
  end
  local previous = state.last_training_optimizer
  if previous and (previous.project ~= root or previous.cli ~= cli or previous.python ~= python
      or previous.revision ~= revision or previous.model ~= model or previous.mode ~= mode or previous.entry ~= entry) then previous = nil end
  local source = tr('this session', '本会话', '本工作階段')
  if mode ~= 'external-loop' and type(graph_optimizer) == 'table' then
    local args = {}
    if graph_optimizer.factory then vim.list_extend(args, {'--optimizer-factory', graph_optimizer.factory}) end
    for _, name in ipairs(vim.fn.sort(vim.tbl_keys(graph_optimizer.params or {}))) do
      vim.list_extend(args, {'--optimizer-param', name .. '=' .. vim.json.encode(graph_optimizer.params[name])})
    end
    if graph_optimizer.lr ~= nil then vim.list_extend(args, {'--lr', tostring(graph_optimizer.lr)}) end
    if graph_optimizer.weight_decay ~= nil then vim.list_extend(args, {'--weight-decay', tostring(graph_optimizer.weight_decay)}) end
    previous = {project = root, cli = cli, python = python, revision = revision, model = model,
      mode = mode, entry = entry, args = args, description = '\n' .. vim.json.encode(graph_optimizer), custom = graph_optimizer.factory ~= nil}
    source = tr('saved graph', '已保存图', '已儲存圖')
  end
  if not previous and mode ~= 'external-loop' then
    local training = declared_training(state, project, mode)
    local optimizer = training and training.entry == entry and training.optimizer
    if type(optimizer) == 'table' then
      local args = {}
      if optimizer.factory then vim.list_extend(args, { '--optimizer-factory', optimizer.factory }) end
      for _, name in ipairs(vim.fn.sort(vim.tbl_keys(optimizer.params or {}))) do
        vim.list_extend(args, { '--optimizer-param', name .. '=' .. vim.json.encode(optimizer.params[name]) })
      end
      if optimizer.lr ~= nil then vim.list_extend(args, { '--lr', tostring(optimizer.lr) }) end
      if optimizer.weight_decay ~= nil then vim.list_extend(args, { '--weight-decay', tostring(optimizer.weight_decay) }) end
      local description = optimizer.factory and (tr('\nOptimizer factory: ', '\n优化器工厂：', '\n最佳化器工廠：') .. optimizer.factory
        .. tr('\nOptimizer parameters: ', '\n优化器参数：', '\n最佳化器參數：') .. vim.json.encode(optimizer.params or vim.empty_dict()))
        or (tr('\nLearning rate: ', '\n学习率：', '\n學習率：') .. tostring(optimizer.lr or tr('backend default', '后端默认', '後端預設'))
          .. tr('\nWeight decay: ', '\n权重衰减：', '\n權重衰減：') .. tostring(optimizer.weight_decay or tr('backend default', '后端默认', '後端預設')))
      previous = { project = root, cli = cli, python = python, revision = revision, model = model,
        mode = mode, entry = entry, args = args, description = description, custom = optimizer.factory ~= nil }
      source = tr('saved declaration', '已保存声明', '已儲存宣告')
    end
  end
  if mode == 'external-loop' or not current() or not previous then
    choose_new()
    return
  end
  vim.ui.select({ tr('Reuse selected optimizer', '沿用已选优化器', '沿用已選最佳化器'),
      tr('Choose another optimizer', '重新选择优化器', '重新選擇最佳化器') }, {
    prompt = tr('Optimizer from ', '优化器来源：', '最佳化器來源：') .. source .. previous.description,
  }, function(_, choice)
    if not current() or (source == tr('this session', '本会话', '本工作階段') and state.last_training_optimizer ~= previous) then return end
    if choice == 1 then
      state.last_training_optimizer = previous
      callback(vim.deepcopy(previous.args), previous.description, previous.custom)
    elseif choice == 2 then choose_new() end
  end)
end

local function prepare_generic_trial(state, formal)
  if state.closed or state.busy then return end
  local project, epoch, cli = state.opts.project, state.change_epoch or 0, state.opts.cli
  local function current()
    return not state.closed and not state.busy and state.opts.project == project and state.opts.cli == cli
      and (state.change_epoch or 0) == epoch and project_config_current(state)
  end
  state.busy = tr('Checking loop capability', '检查循环能力', '檢查迴圈能力'); render(state)
  request(state, { '--describe-interface' }, function(report, err)
    state.busy = nil; render(state)
    local data = report and report.operation == 'interface' and report.status == 'success' and report.data
    if not current() then return end
    if err or type(data) ~= 'table' or type(data.capabilities) ~= 'table'
        or data.capabilities[formal and 'training.generic_loop_train_cli_v1' or 'training.generic_loop_trial_cli_v1'] ~= true then
      notify(tr('The selected CLI does not advertise framework-neutral trials.',
        '所选 CLI 未声明支持无框架试跑。', '所選 CLI 未宣告支援無框架試跑。'), vim.log.levels.WARN); return
    end
    local function collect(interface)
    vim.ui.input({ prompt = tr('User loop module:callable (discovered names are unverified): ',
      '用户循环 module:callable（发现的入口尚未验证）：', '使用者迴圈 module:callable（探索的入口尚未驗證）：'),
      default = state.loop or '' }, function(reference)
      if not reference or reference == '' or not current() then return end
      vim.ui.input({ prompt = tr('Loop parameters as JSON (recorded; no secrets): ',
        '循环参数 JSON（会记录，请勿填写密钥）：', '迴圈參數 JSON（會記錄，請勿填寫密鑰）：'), default = '{}' }, function(raw)
        if not raw or not current() then return end
        local ok, params = pcall(vim.json.decode, raw)
        if #raw > 65536 or not ok or type(params) ~= 'table' or not raw:match('^%s*{') then
          notify(tr('Enter a JSON object of at most 64 KiB.', '请输入不超过 64 KiB 的 JSON 对象。', '請輸入不超過 64 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
        end
        local names = vim.tbl_keys(params)
        if #names > 64 then notify(tr('At most 64 parameters are supported.', '最多支持 64 个参数。', '最多支援 64 個參數。'), vim.log.levels.WARN); return end
        table.sort(names)
        local args = { formal and 'loop-run' or 'loop-trial', '--loop', reference }
        if data.capabilities['training.generic_loop_interface_v1'] == true then
          vim.list_extend(args, { '--loop-interface', interface })
        end
        for _, name in ipairs(names) do
          if not parameter_name_candidate(name) then notify(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。'), vim.log.levels.WARN); return end
          local encoded, value = pcall(vim.json.encode, params[name])
          if not encoded then notify(tr('Invalid parameter value.', '参数值无效。', '參數值無效。'), vim.log.levels.WARN); return end
          vim.list_extend(args, { '--loop-param', name .. '=' .. value })
        end
        vim.ui.input({ prompt = formal and tr('Total step target (1–1000000): ', '总步数目标（1–1000000）：', '總步數目標（1–1000000）：') or tr('Maximum reported steps (1–1000): ', '最多报告步数（1–1000）：', '最多回報步數（1–1000）：'), default = formal and '100' or '1' }, function(raw_steps)
          if not raw_steps or not current() then return end
          local steps = raw_steps:match('^%d+$') and tonumber(raw_steps) or nil
          if not steps or steps < 1 or steps > (formal and 1000000 or 1000) then notify(tr('Invalid step target.', '步数目标无效。', '步數目標無效。'), vim.log.levels.WARN); return end
          vim.list_extend(args, { '--steps', tostring(steps) })
          local detached = formal and data.capabilities['training.generic_loop_detached_cli_v1'] == true
          local effects = (formal and ((detached and tr('Starts in the background. ', '将在后台启动。', '將在背景啟動。') or tr('Runs in the foreground. ', '将以前台方式运行。', '將以前景方式執行。'))
            .. tr('Creates a run record and source snapshot. The loop owns its libraries, model, data and updates. Only explicitly reported JSON state is saved; external files and random state are not captured.',
            '将创建运行记录和源码快照。循环自行管理库、模型、数据和更新。只保存循环明确报告的 JSON 状态；外部文件和随机状态不包含在内。',
            '將建立執行紀錄和原始碼快照。迴圈自行管理程式庫、模型、資料和更新。只儲存迴圈明確回報的 JSON 狀態；外部檔案和隨機狀態不包含在內。')
            .. tr(' Each non-None state report rechecks source and writes a checkpoint; omitted or None state does not. The loop controls the interval. Interrupted progress after the last state may be lost.',
              ' 每次报告非 None 状态都会重核源码并写入检查点；省略状态或使用 None 不会保存。间隔由循环控制；中断时，最近状态之后的进度可能丢失。',
              ' 每次回報非 None 狀態都會重新核對原始碼並寫入檢查點；省略狀態或使用 None 不會儲存。間隔由迴圈控制；中斷時，最近狀態之後的進度可能遺失。')) or tr('Executes the user loop and creates a run record. The loop owns its libraries, models, data and updates; no framework is selected automatically. Trial state is not saved.',
            '将执行用户循环并创建运行记录。循环自行管理库、模型、数据和更新；工具不会自动选择框架。试跑状态不会保存。',
            '將執行使用者迴圈並建立執行紀錄。迴圈自行管理程式庫、模型、資料和更新；工具不會自動選擇框架。試跑狀態不會儲存。'))
            .. tr('\nLoop: ', '\n循环：', '\n迴圈：') .. reference
            .. tr('\nLoop signature: ', '\n循环签名：', '\n迴圈簽名：') .. (interface == 'context' and 'loop(context, **params)' or 'loop(None, context, **params)')
            .. tr('\nSteps: ', '\n步数：', '\n步數：') .. tostring(steps)
            .. tr('\nParameter names: ', '\n参数名：', '\n參數名稱：') .. (#names > 0 and table.concat(names, ', ') or tr('none', '无', '無'))
          if formal then start_generic_run(state, tr('Run user loop', '运行用户循环', '執行使用者迴圈'), args, effects, detached)
          else run(state, tr('Run framework-neutral trial', '运行无框架试跑', '執行無框架試跑'), args, nil, effects, true) end
        end)
      end)
    end)
    end
    if data.capabilities['training.generic_loop_interface_v1'] == true then
      vim.ui.select({ 'loop(context, **params)', 'loop(None, context, **params)' }, {
        prompt = tr('Choose your loop signature', '选择用户循环签名', '選擇使用者迴圈簽名'),
      }, function(_, selected)
        if not current() or not selected then return end
        collect(selected == 1 and 'context' or 'model-context')
      end)
    else
      vim.ui.select({ tr('Cancel', '取消', '取消'), tr('Use legacy signature', '使用旧版签名', '使用舊版簽章') }, {
        prompt = tr('This CLI only advertises loop(None, context, **params). Context-only drafts require a compatible CLI or code changes.',
          '此 CLI 仅声明支持 loop(None, context, **params)。仅 context 的草稿需要兼容的 CLI 或修改代码。',
          '此 CLI 僅宣告支援 loop(None, context, **params)。僅 context 的草稿需要相容的 CLI 或修改程式碼。'),
      }, function(_, selected)
        if selected == 2 and current() then collect('model-context') end
      end)
    end
  end)
end

-- Reuse only choices explicitly entered for the same project, model and mode.
-- Both the entry and parameter object are still presented for review before execution.
declared_training = function(state, project, mode)
  if not project or not project_config_current(state) or (state.model and state.model ~= project.model) then return nil end
  local builder = require('model_maven.model_builder')
  local draft = builder.load(state.opts.project)
  local training = draft and draft.training
  if training and (mode == nil or training.mode == mode) then
    if training.entry == '$model:step' then
      local module = type(project.model) == 'string' and project.model:match('^(.+):model$') or nil
      if not module then return nil end
      training = vim.deepcopy(training)
      training.entry = module .. ':step'
    end
    return training
  end
end

local function training_entry_default(state, project, mode)
  local previous = state.last_training_entry
  local model = state.model or (project and project.model)
  if previous and project and previous.config_revision == project.config_revision
      and previous.project == state.opts.project and previous.model == model and previous.mode == mode then
    return previous.value, 'session'
  end
  local training = declared_training(state, project, mode)
  return training and training.entry or nil, training and 'declaration' or nil
end

local function remember_training_entry(state, project, mode, value)
  local previous = state.last_training_entry
  local model = state.model or project.model
  if not previous or previous.project ~= state.opts.project or previous.model ~= model
      or previous.mode ~= mode or previous.value ~= value or previous.config_revision ~= project.config_revision then
    state.last_training_entry = { project = state.opts.project, model = model, mode = mode, value = value,
      config_revision = project.config_revision }
  end
end

local function training_params_default(state, project, mode, value)
  local previous = state.last_training_entry
  if previous and previous.value == value and training_entry_default(state, project, mode) == value
      and previous.config_revision == project.config_revision and type(previous.params) == 'string' then
    return previous.params, 'session'
  end
  local training = declared_training(state, project, mode)
  if training and training.entry == value then
    local ok, encoded = pcall(vim.json.encode, next(training.params) and training.params or vim.empty_dict())
    if ok then return encoded, 'declaration' end
  end
  return '{}', nil
end

local function remember_training_params(state, project, mode, value, raw)
  if training_entry_default(state, project, mode) == value and state.last_training_entry then
    state.last_training_entry.params = raw
    state.last_training_entry.config_revision = project.config_revision
  end
end

local function starter_training_suggestion(state, project)
  local suggested = state.starter_step
  return project and type(suggested) == 'table' and suggested.model == project.model
    and (not state.model or state.model == suggested.model) and suggested.step or nil
end

local function training_mode_choices(state, project, include_generic)
  local items = {
    { id = 'managed-step', label = tr('Managed step: tool runs backward and selected optimizer', '受管步骤：工具负责反向与所选优化器', '受管步驟：工具負責反向與所選最佳化器') },
    { id = 'manual-step', label = tr('Manual step: your code registers optimizer groups and updates', '手动步骤：你的代码登记优化器组并更新', '手動步驟：你的程式碼登記最佳化器組並更新') },
    { id = 'external-loop', label = tr('External loop: your code owns training and data (PyTorch runtime)', '完整循环：代码负责训练和数据（PyTorch 运行时）', '完整迴圈：程式碼負責訓練和資料（PyTorch 執行階段）') },
  }
  local preferred, source
  local previous = state.last_training_entry
  if project and project_config_current(state) and previous and previous.project == state.opts.project
      and previous.model == (state.model or project.model) and previous.config_revision == project.config_revision then
    preferred, source = previous.mode, tr('session choice', '会话选择', '工作階段選擇')
  else
    local saved = declared_training(state, project, nil)
    if saved then preferred, source = saved.mode, tr('saved declaration', '已保存声明', '已儲存宣告') end
  end
  for index, item in ipairs(items) do
    if item.id == preferred then
      table.remove(items, index)
      item.label = item.label .. ' · ' .. source
      table.insert(items, 1, item)
      break
    end
  end
  if include_generic then
    items[#items + 1] = { id = 'generic', label = tr('Framework-neutral user loop', '无框架绑定的用户循环', '無框架繫結的使用者迴圈') }
  end
  local labels = {}
  for _, item in ipairs(items) do labels[#labels + 1] = item.label end
  return items, labels
end

prepare_trial = function(state, variant, graph_suggestion)
  local graph_training = type(graph_suggestion) == 'table' and graph_suggestion.training or nil
  local graph_rules = type(graph_suggestion) == 'table' and graph_suggestion.rules_notice or nil
  local graph_needs_loss = type(graph_suggestion) == 'table' and graph_suggestion.generated_step_needs_loss == true
  local graph_guard = type(graph_suggestion) == 'table' and graph_suggestion.guard or nil
  local graph_prepare = type(graph_suggestion) == 'table' and graph_suggestion.prepare_data or nil
  local graph_mode = graph_training and graph_training.mode or 'managed-step'
  if type(graph_suggestion) == 'table' then graph_suggestion = graph_suggestion.entry end
  local project = state.project_info
  if state.busy then return end
  local revision, epoch, project_root = project and project.config_revision, state.change_epoch or 0, state.opts.project
  local suggestion = starter_training_suggestion(state, project)
  local items, trial_modes = training_mode_choices(state, project, not variant)
  if graph_suggestion then
    for index, item in ipairs(items) do
      if item.id == graph_mode then
        table.remove(items, index)
        item.label = item.label .. tr(' · saved graph', ' · 已保存图', ' · 已儲存圖')
        table.insert(items, 1, item)
        trial_modes = {}; for _, value in ipairs(items) do trial_modes[#trial_modes + 1] = value.label end
        break
      end
    end
  end
  vim.ui.select(trial_modes, {
      prompt = variant and tr('Choose a variant trial mode (requires PyTorch)', '选择变体试跑模式（需要 PyTorch）', '選擇變體試跑模式（需要 PyTorch）')
        or tr('Choose a trial mode (the first three require PyTorch)',
          '选择试跑模式（前三项需要 PyTorch）', '選擇試跑模式（前三項需要 PyTorch）'),
    }, function(_, mode_choice)
  if not mode_choice or state.closed then return end
  if state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
      or (state.project_info and state.project_info.config_revision) ~= revision then
    notify(tr('Project changed; prepare the trial again.', '项目已变化，请重新准备试跑。', '專案已變更，請重新準備試跑。'), vim.log.levels.WARN)
    return
  end
  local mode = items[mode_choice] and items[mode_choice].id
  if mode == 'generic' then prepare_generic_trial(state); return end
  if not mode then return end
  if not project or not sha256(revision) then
    notify(tr('These modes need a saved model project; check project status first.',
      '这些模式需要已保存的模型项目，请先检查项目状态。', '這些模式需要已儲存的模型專案，請先檢查專案狀態。'), vim.log.levels.WARN); return
  end
  local external = mode == 'external-loop'
  local function start_entry()
  if state.closed or state.opts.project ~= project_root then return end
  project, epoch = state.project_info, state.change_epoch or 0
  revision = project and project.config_revision
  if not project or not sha256(revision) then return end
  local entry, source = training_entry_default(state, project, mode)
  if mode == graph_mode and graph_suggestion then entry, source = graph_suggestion, 'graph' end
  entry = entry or (external and (state.loop or '') or (state.step or suggestion or ''))
  local prompt = external and tr('Training loop module:callable', '训练循环 module:callable', '訓練迴圈 module:callable')
    or tr('Training step module:callable', '训练步骤 module:callable', '訓練步驟 module:callable')
  if source == 'declaration' then
    prompt = prompt .. tr(' (from saved model-maven.json; review)', '（来自已保存的 model-maven.json，请审核）', '（來自已儲存的 model-maven.json，請檢視）')
  elseif source == 'session' then
    prompt = prompt .. tr(' (session selection)', '（会话选择）', '（工作階段選擇）')
  elseif source == 'graph' then
    prompt = prompt .. tr(' (graph training suggestion; review)', '（图训练建议，请审核）', '（圖訓練建議，請檢視）')
    if graph_needs_loss then prompt = prompt .. tr(' (generated step needs losses or an objectives parameter)',
      '（生成的步骤需要损失或 objectives 参数）', '（產生的步驟需要損失或 objectives 參數）') end
  elseif suggestion and entry == suggestion then
    prompt = prompt .. tr(' (suggested example)', '（示例）', '（範例）')
  end
  vim.ui.input({ prompt = prompt .. ': ', default = entry }, function(step)
    if not step or step == '' or state.closed or state.opts.project ~= project_root
        or (state.change_epoch or 0) ~= epoch then return end
    remember_training_entry(state, project, mode, step)
    local parameter_default, parameter_source = training_params_default(state, project, mode, step)
    if source == 'graph' and step == graph_suggestion then
      local ok, encoded = pcall(vim.json.encode, graph_training and graph_training.step_params or vim.empty_dict())
      parameter_default, parameter_source = ok and encoded or '{}', 'graph'
    end
    local parameter_prompt = tr('Step/loop parameters as JSON', '步骤或循环参数 JSON', '步驟或迴圈參數 JSON')
      .. (parameter_source == 'declaration' and tr(' (from saved model-maven.json)', '（来自已保存声明）', '（來自已儲存宣告）')
        or parameter_source == 'session' and tr(' (session selection)', '（会话选择）', '（工作階段選擇）')
        or parameter_source == 'graph' and tr(' (from graph; review)', '（来自图，请审核）', '（來自圖，請檢視）') or '')
      .. tr(' (may be recorded; do not enter secrets): ', '（可能被记录，请勿填写密钥）：', '（可能被記錄，請勿填寫金鑰）：')
    vim.ui.input({ prompt = parameter_prompt, default = parameter_default }, function(raw_params)
      if not raw_params or state.closed then return end
      local decoded, params = pcall(vim.json.decode, raw_params)
      if not decoded or type(params) ~= 'table' or not raw_params:match('^%s*{') then
        notify(tr('Training parameters must be a JSON object.', '训练参数必须是 JSON 对象。', '訓練參數必須是 JSON 物件。'), vim.log.levels.WARN); return
      end
      local param_args, names = {}, vim.tbl_keys(params)
      table.sort(names)
      for _, name in ipairs(names) do
        if not parameter_name_candidate(name) then
          notify(tr('Invalid training parameter name.', '训练参数名无效。', '訓練參數名稱無效。'), vim.log.levels.WARN); return
        end
        local ok, value = pcall(vim.json.encode, params[name])
        if not ok then notify(tr('Invalid training parameter value.', '训练参数值无效。', '訓練參數值無效。'), vim.log.levels.WARN); return end
        vim.list_extend(param_args, { external and '--loop-param' or '--step-param', name .. '=' .. value })
      end
    remember_training_params(state, project, mode, step, raw_params)
    vim.ui.input({ prompt = tr('Trial steps (1–1000): ', '试跑步数（1–1000）：', '試跑步數（1–1000）：'), default = tostring(source == 'graph' and step == graph_suggestion and graph_training and graph_training.trial_steps or 1) }, function(steps)
      if not steps or not steps:match('^%d+$') or tonumber(steps) < 1 or tonumber(steps) > 1000 or state.closed then return end
    choose_and_remember_optimizer(state, project, mode, step, function(optimizer_args, optimizer_description, custom_optimizer)
    if state.closed then return end
    choose_training_device(state, mode, function(device, batch_device_policy)
      if not device or device == '' or state.closed then return end
      if state.busy or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch or not state.project_info
          or state.project_info.config_revision ~= revision then
        notify(tr('Project changed; prepare the trial again.', '项目已变化，请重新准备试跑。', '專案已變更，請重新準備試跑。'), vim.log.levels.WARN)
        return
      end
      state.busy = tr('Checking training capability', '检查训练能力', '檢查訓練能力')
      render(state)
      request(state, { '--describe-interface' }, function(interface, err)
        state.busy = nil
        render(state)
        local caps = interface and interface.data and interface.data.capabilities
        if err or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
            or type(caps) ~= 'table' or caps['training.conditional_config_start'] ~= true
            or (not external and state.batch_binding and caps['training.batch_binding_v1'] ~= true)
            or (batch_device_policy and caps['training.batch_device_policy_v1'] ~= true)
            or (custom_optimizer and caps['training.custom_optimizer_factory_v1'] ~= true) then
          notify(tr('This CLI cannot verify the project configuration before a trial.', '此 CLI 无法在试跑前核对项目配置。', '此 CLI 無法在試跑前核對專案設定。'), vim.log.levels.WARN)
          return
        end
        if needs_generic_device(device) and caps['training.generic_device_v1'] ~= true then
          notify(tr('This CLI cannot use a custom PyTorch device; select a compatible CLI.', '当前 CLI 不支持自定义 PyTorch 设备，请选择兼容版本。', '目前 CLI 不支援自訂 PyTorch 裝置，請選擇相容版本。'), vim.log.levels.WARN); return
        end
        if state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch or not state.project_info
            or state.project_info.config_revision ~= revision then
          notify(tr('Project changed; prepare the trial again.', '项目已变化，请重新准备试跑。', '專案已變更，請重新準備試跑。'), vim.log.levels.WARN)
          return
        end
        local function launch_trial(supervision_revision, no_model)
          if state.closed or state.busy or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch or not state.project_info
              or state.project_info.config_revision ~= revision then
            notify(tr('Project changed; prepare the trial again.', '项目已变化，请重新准备试跑。', '專案已變更，請重新準備試跑。'), vim.log.levels.WARN); return
          end
          if graph_guard and not graph_guard(mode) then
            notify(tr('Graph, data or source changed; prepare the trial again.', '图、数据或源码已变化，请重新准备试跑。', '圖、資料或原始碼已變更，請重新準備試跑。'), vim.log.levels.WARN); return
          end
          local args = { 'try', external and '--loop' or '--step', step, '--steps', steps, '--device', device,
            '--training-mode', mode, '--if-config-revision', revision }
          if variant then
            vim.list_extend(args, { '--variant', variant.name, '--if-variant-base', variant.token })
            if not external then
              if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
              if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
              local batch_names = vim.tbl_keys(state.batch_params or {}); table.sort(batch_names)
              for _, key in ipairs(batch_names) do
                vim.list_extend(args, { '--batch-param', key .. '=' .. vim.json.encode(state.batch_params[key]) })
              end
            end
          end
          if no_model then args[#args + 1] = '--no-model' end
          if batch_device_policy then vim.list_extend(args, { '--batch-device-policy', batch_device_policy }) end
          vim.list_extend(args, param_args)
          vim.list_extend(args, optimizer_args)
          if supervision_revision then
            vim.list_extend(args, { '--apply-supervision', '--if-supervision-revision', supervision_revision })
          end
          local effects = (supervision_revision
            and tr('This trial uses the reviewed rules; penalty rules change the objective. User code may update parameters and write run artifacts.',
              '试跑将使用已查看的规则；惩罚规则会改变目标。用户代码可能更新参数并写入运行产物。',
              '試跑將使用已檢視的規則；懲罰規則會改變目標。使用者程式碼可能更新參數並寫入執行產物。')
            or tr('This trial executes user training code and may update parameters and write run artifacts. Supervision is not enabled.',
              '试跑将执行用户训练代码，可能更新参数并写入运行产物；监督规则未启用。',
              '試跑將執行使用者訓練程式碼，可能更新參數並寫入執行產物；監督規則未啟用。'))
            .. (external and tr('\nYour loop owns data, updates and progress reporting; input factory overrides are not passed.',
              '\n你的循环负责数据、参数更新与进度上报；不会传入输入工厂覆盖。',
              '\n你的迴圈負責資料、參數更新與進度回報；不會傳入輸入工廠覆蓋。')
              or (mode == 'manual-step' and tr('\nYour step owns backward and optimizer updates.',
                '\n你的步骤负责反向传播和优化器更新。', '\n你的步驟負責反向傳播與最佳化器更新。') or ''))
            .. (supervision_revision and mode ~= 'managed-step'
              and tr('\nYour code must use the supervision context protocol.', '\n你的代码必须遵循监督 context 协议。', '\n你的程式碼必須遵循監督 context 協議。') or '')
            .. (caps['training.random_run_seed_v1'] == true and not state.training_seed and tr('\nA new execution seed will be generated and recorded; variant construction can use a separate seed.',
              '\n将生成并记录本次执行种子；变体构造可能使用独立种子。', '\n將產生並記錄本次執行種子；變體建構可能使用獨立種子。') or '')
            .. '\nMode: ' .. mode .. '\nEntry: ' .. step .. '\nSteps: ' .. steps .. '\nDevice: ' .. device
            .. (batch_device_policy and (tr('\nBatch device policy: ', '\n批次设备策略：', '\n批次裝置策略：') .. batch_device_policy
              .. (batch_device_policy == 'preserve' and tr(' (your step manages placement)', '（由步骤管理设备）', '（由步驟管理裝置）')
                or tr(' (unsupported container types stop the run)', '（不支持的容器类型会中止运行）', '（不支援的容器類型會中止執行）'))) or '')
            .. '\nParameters: ' .. raw_params .. optimizer_description
          if suggestion and step == suggestion then
            effects = effects .. tr('\nThis starter step uses an example objective; confirm it matches your input and task.',
              '\n此骨架步骤使用示例目标；请确认与输入和任务匹配。', '\n此骨架步驟使用範例目標；請確認與輸入和任務相符。')
          end
          if supervision_revision then
            effects = effects .. tr('\nYour step can have side effects before checks; the tool does not roll them back.',
              '\n用户步骤可能在检查前产生副作用，工具不会回滚。', '\n使用者步驟可能在檢查前產生副作用，工具不會回復。')
          end
          run(state, tr('Start training trial', '启动训练试跑', '啟動訓練試跑'), args, nil, effects, external or variant ~= nil,
            graph_guard and function()
              if graph_guard(mode) then return true end
              notify(tr('Graph, data or source changed; prepare the trial again.', '图、数据或源码已变化，请重新准备试跑。', '圖、資料或原始碼已變更，請重新準備試跑。'), vim.log.levels.WARN)
              return false
            end or nil)
        end
        local function start_trial(supervision_revision)
          if not external then launch_trial(supervision_revision, false); return end
          if variant then launch_trial(supervision_revision, false); return end
          if caps['training.external_loop_model_choice_v1'] ~= true then
            notify(tr('This CLI does not advertise explicit external-loop model selection; update it to choose safely.',
              '此 CLI 未声明支持完整循环的明确模型选择；请更新后选择。',
              '此 CLI 未宣告支援完整迴圈的明確模型選擇；請更新後選擇。'), vim.log.levels.WARN)
            return
          end
          vim.ui.select({ tr('Use selected or project model', '使用会话或项目模型', '使用工作階段或專案模型'),
            tr('No model: my loop manages it', '不使用模型：循环自行管理', '不使用模型：迴圈自行管理') }, {
            prompt = tr('What should the loop receive as its model?', '循环应接收哪个模型？', '迴圈應接收哪個模型？'),
          }, function(_, choice)
            if choice == 1 and not state.model and not (project and type(project.model) == 'string' and project.model ~= '') then
              notify(tr('No model is selected. Choose a model first or select the no-model option.',
                '尚未选择模型；请先选择模型或选择无模型。', '尚未選擇模型；請先選擇模型或選擇無模型。'), vim.log.levels.WARN)
              return
            end
            if choice then launch_trial(supervision_revision, choice == 2) end
          end)
        end
        vim.ui.select({ tr('Without supervision', '不启用监督', '不啟用監督'),
          tr('Review and enable supervision', '查看并启用监督', '檢視並啟用監督') }, {
            prompt = tr('Supervision for this trial', '本次试跑的监督', '本次試跑的監督') .. (graph_rules or ''),
          }, function(_, choice)
            if not choice or state.closed or state.busy then return end
            if choice == 1 then start_trial(nil); return end
            if caps['training.conditional_supervision'] ~= true then
              notify(tr('This CLI cannot pin the supervision revision.', '此 CLI 无法固定监督规则修订。', '此 CLI 無法固定監督規則修訂。'), vim.log.levels.WARN); return
            end
            state.busy = tr('Reading supervision rules', '读取监督规则', '讀取監督規則')
            render(state)
            request(state, { 'model', 'supervise', 'rule', 'list' }, function(catalog, failure, stderr)
              state.busy = nil
              if state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
                  or not state.project_info or state.project_info.config_revision ~= revision then
                render(state)
                notify(tr('Context changed; prepare the trial again.', '上下文已变化，请重新准备试跑。', '上下文已變更，請重新準備試跑。'), vim.log.levels.WARN); return
              end
              state.last = { report = catalog, transport_error = failure, stderr = stderr }
              render(state)
              local data = catalog and catalog.data
              if failure or not catalog or catalog.operation ~= 'semantic_supervise' or catalog.status ~= 'success'
                  or type(data) ~= 'table' or type(data.rules) ~= 'table' or not is_list(data.rules)
                  or not sha256(data.state_revision) then
                notify(tr('Cannot verify supervision rules; training was not started.', '无法核对监督规则，训练未启动。', '無法核對監督規則，訓練未啟動。'), vim.log.levels.WARN)
                show_report(state); return
              end
              local listed = state.last
              local review = show_report(state)
              review_gate(review, { tr('Cancel', '取消', '取消'), tr('Continue with these rules', '使用这些规则继续', '使用這些規則繼續') },
                tr('Review the rule report first; [J] opens all fields. Continue to trial confirmation?',
                  '请先查看规则报告；[J] 可打开完整字段。继续确认试跑？',
                  '請先檢視規則報告；[J] 可開啟完整欄位。繼續確認試跑？'), function(_, selected)
                if selected ~= 2 or state.closed or state.last ~= listed or listed.context_changed then return end
                start_trial(data.state_revision)
              end, nil, true)
            end)
          end)
      end)
    end)
    end, source == 'graph' and step == graph_suggestion and graph_training and graph_training.optimizer or nil)
  end)
    end)
    end)
  end
  if graph_prepare and not external then graph_prepare(start_entry) else start_entry() end
  end)
end

local function resolve_pending(state)
  if state.busy then return end
  local project, epoch = state.opts.project, state.change_epoch or 0
  local function current()
    return not state.closed and not state.busy and state.opts.project == project and (state.change_epoch or 0) == epoch
  end
  local items, err = pending.list(project)
  if not items then notify(tr('Cannot read pending requests: ', '无法读取待确认请求：', '無法讀取待確認要求：') .. tostring(err), vim.log.levels.ERROR); return end
  if #items == 0 then
    local lock, lock_err = pending.lock_status(project)
    if lock == nil then
      notify(tr('Cannot inspect the training admission lock: ', '无法检查训练准入锁：', '無法檢查訓練准入鎖：') .. tostring(lock_err), vim.log.levels.ERROR)
    elseif lock then
      vim.ui.select({ tr('Keep lock', '保留锁', '保留鎖'), tr('Remove after checking', '核查后移除', '核查後移除') }, {
        prompt = tr('A launcher may be preparing a request, or may have exited. Check launchers and runs before removing this lock: ',
          '可能有启动器正在准备请求，也可能已异常退出。移除锁前请检查启动器和运行记录：',
          '可能有啟動器正在準備要求，也可能已異常結束。移除鎖前請檢查啟動器和執行紀錄：') .. lock,
      }, function(_, choice)
        if choice ~= 2 or not current() then return end
        local outstanding, inspect_err = pending.list(project)
        if not outstanding or #outstanding > 0 then
          notify(tr('Pending requests appeared or could not be read; inspect them before removing the lock: ', '出现待确认请求或无法读取，请先核查再移除锁：', '出現待確認要求或無法讀取，請先核查再移除鎖：') .. tostring(inspect_err or table.concat(outstanding or {}, ', ')), vim.log.levels.WARN)
          return
        end
        local cleared, clear_err = pending.clear_lock(project)
        if not cleared then notify(tr('Could not remove the admission lock: ', '无法移除准入锁：', '無法移除准入鎖：') .. tostring(clear_err), vim.log.levels.WARN) end
      end)
    else
      notify(tr('No unconfirmed starts.', '没有未确认的启动。', '沒有未確認的啟動。'), vim.log.levels.INFO)
    end
    return
  end
  vim.ui.select(items, { prompt = tr('Choose an unconfirmed request', '选择未确认请求', '選擇未確認請求') }, function(id)
    if not id or not current() then return end
    state.busy = tr('Looking up request', '查询请求', '查詢請求')
    render(state)
    request(state, { 'runs', 'find-request', id }, function(report, failure, stderr)
      state.busy = nil
      if not current() then
        render(state)
        notify(tr('Context changed; inspect pending requests in the original project.', '上下文已变化，请在原项目中核查待确认请求。', '上下文已變更，請在原專案中核查待確認要求。'), vim.log.levels.WARN)
        return
      end
      if report and report.status == 'success' and (report.operation ~= 'runs_find_request'
          or type(report.data) ~= 'table' or report.data.request_id ~= id) then
        report, failure = nil, { message = tr('Unexpected request lookup receipt.', '请求查询返回了非预期的回执。', '要求查詢回傳了非預期的回執。') }
      end
      state.last = { report = report, transport_error = failure, stderr = stderr,
        scope = tr('An empty lookup does not prove a delayed worker cannot still create a run.',
          '未查到记录不能证明延迟启动的 worker 不会创建运行。', '未查到紀錄不能證明延遲啟動的 worker 不會建立執行。') }
      local listed = state.last
      render(state)
      local report_buf = show_report(state)
      if failure or not report or report.status ~= 'success' then return end
      review_gate(report_buf, { tr('Keep marker', '保留标记', '保留標記'), tr('Acknowledge and remove marker', '确认并移除标记', '確認並移除標記') },
        tr('Review the lookup and running processes first. Removing the marker permits another start; proceed?',
          '请先核对查询结果和运行中的进程。移除标记后允许再次启动，继续吗？',
          '請先核對查詢結果和執行中的程序。移除標記後允許再次啟動，繼續嗎？'), function(_, choice)
        if choice ~= 2 or not current() or state.last ~= listed or listed.context_changed then return end
        local ok, clear_err = pending.clear(project, id)
        if not ok then notify('Could not remove pending marker: ' .. tostring(clear_err), vim.log.levels.ERROR) end
      end)
    end)
  end)
end

prepare_pytorch_training = function(state, variant, graph_suggestion)
  local graph_training = type(graph_suggestion) == 'table' and graph_suggestion.training or nil
  local graph_rules = type(graph_suggestion) == 'table' and graph_suggestion.rules_notice or nil
  local graph_needs_loss = type(graph_suggestion) == 'table' and graph_suggestion.generated_step_needs_loss == true
  local graph_guard = type(graph_suggestion) == 'table' and graph_suggestion.guard or nil
  local graph_prepare = type(graph_suggestion) == 'table' and graph_suggestion.prepare_data or nil
  local graph_mode = graph_training and graph_training.mode or 'managed-step'
  local graph_entry = type(graph_suggestion) == 'table' and graph_suggestion.entry or nil
  local project = state.project_info
  if state.busy or not project or not sha256(project.config_revision) then
    notify('A saved project and current configuration revision are required. Check project status first.', vim.log.levels.WARN)
    return
  end
  local revision, epoch, project_root = project.config_revision, state.change_epoch or 0, state.opts.project
  local suggestion = starter_training_suggestion(state, project)
  local items, modes = training_mode_choices(state, project, false)
  if graph_entry then
    for index, item in ipairs(items) do
      if item.id == graph_mode then
        table.remove(items, index); item.label = item.label .. tr(' · saved graph', ' · 已保存图', ' · 已儲存圖')
        table.insert(items, 1, item)
        modes = {}; for _, value in ipairs(items) do modes[#modes + 1] = value.label end
        break
      end
    end
  end
  vim.ui.select(modes, {
      prompt = tr('Training mode (all modes currently require PyTorch in the selected Python)',
        '训练模式（当前所有模式都要求所选 Python 可导入 PyTorch）',
        '訓練模式（目前所有模式都要求所選 Python 可匯入 PyTorch）'),
    }, function(_, choice)
  if not choice or state.closed then return end
  if state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
      or (state.project_info and state.project_info.config_revision) ~= revision then
    notify(tr('Project changed; prepare training again.', '项目已变化，请重新准备训练。', '專案已變更，請重新準備訓練。'), vim.log.levels.WARN); return
  end
  local mode = items[choice] and items[choice].id
  if not mode then return end
  local external = mode == 'external-loop'
  local function start_entry()
  if state.closed or state.opts.project ~= project_root then return end
  project, epoch = state.project_info, state.change_epoch or 0
  revision = project and project.config_revision
  if not project or not sha256(revision) then return end
  local entry, source = training_entry_default(state, project, mode)
  if mode == graph_mode and graph_entry then entry, source = graph_entry, 'graph' end
  entry = entry or (external and (state.loop or '') or (state.step or suggestion or ''))
  local prompt = external and tr('Training loop module:callable', '训练循环 module:callable', '訓練迴圈 module:callable')
    or tr('Training step module:callable', '训练步骤 module:callable', '訓練步驟 module:callable')
  if source == 'declaration' then
    prompt = prompt .. tr(' (from saved model-maven.json; review)', '（来自已保存的 model-maven.json，请审核）', '（來自已儲存的 model-maven.json，請檢視）')
  elseif source == 'session' then
    prompt = prompt .. tr(' (session selection)', '（会话选择）', '（工作階段選擇）')
  elseif source == 'graph' then
    prompt = prompt .. tr(' (graph training suggestion; review)', '（图训练建议，请审核）', '（圖訓練建議，請檢視）')
    if graph_needs_loss then prompt = prompt .. tr(' (generated step needs losses or an objectives parameter)',
      '（生成的步骤需要损失或 objectives 参数）', '（產生的步驟需要損失或 objectives 參數）') end
  elseif suggestion and entry == suggestion then
    prompt = prompt .. tr(' (suggested example)', '（示例）', '（範例）')
  end
  vim.ui.input({ prompt = prompt .. ': ', default = entry }, function(step)
    if not step or step == '' or state.closed or state.opts.project ~= project_root
        or (state.change_epoch or 0) ~= epoch then return end
    remember_training_entry(state, project, mode, step)
    local parameter_default, parameter_source = training_params_default(state, project, mode, step)
    if source == 'graph' and step == graph_entry then
      local ok, encoded = pcall(vim.json.encode, graph_training and graph_training.step_params or vim.empty_dict())
      parameter_default, parameter_source = ok and encoded or '{}', 'graph'
    end
    local parameter_prompt = tr('Step/loop parameters as JSON', '步骤或循环参数 JSON', '步驟或迴圈參數 JSON')
      .. (parameter_source == 'declaration' and tr(' (from saved model-maven.json)', '（来自已保存声明）', '（來自已儲存宣告）')
        or parameter_source == 'session' and tr(' (session selection)', '（会话选择）', '（工作階段選擇）')
        or parameter_source == 'graph' and tr(' (from graph; review)', '（来自图，请审核）', '（來自圖，請檢視）') or '')
      .. tr(' (may be recorded; do not enter secrets): ', '（可能被记录，请勿填写密钥）：', '（可能被記錄，請勿填寫金鑰）：')
    vim.ui.input({ prompt = parameter_prompt, default = parameter_default }, function(raw_params)
      if not raw_params or state.closed then return end
      local decoded, params = pcall(vim.json.decode, raw_params)
      if not decoded or type(params) ~= 'table' or not raw_params:match('^%s*{') then
        notify(tr('Training parameters must be a JSON object.', '训练参数必须是 JSON 对象。', '訓練參數必須是 JSON 物件。'), vim.log.levels.WARN); return
      end
      local param_args = {}
      local names = vim.tbl_keys(params)
      table.sort(names)
      for _, name in ipairs(names) do
        if not parameter_name_candidate(name) then
          notify(tr('Invalid training parameter name.', '训练参数名称无效。', '訓練參數名稱無效。'), vim.log.levels.WARN); return
        end
        local ok, value = pcall(vim.json.encode, params[name])
        if not ok then notify(tr('Invalid training parameter value.', '训练参数值无效。', '訓練參數值無效。'), vim.log.levels.WARN); return end
        vim.list_extend(param_args, { external and '--loop-param' or '--step-param', name .. '=' .. value })
      end
    remember_training_params(state, project, mode, step, raw_params)
    vim.ui.input({ prompt = tr('Number of steps: ', '训练步数：', '訓練步數：'), default = '100' }, function(steps)
      if not steps or not steps:match('^%d+$') or tonumber(steps) < 1 or tonumber(steps) > 1000000 or state.closed then return end
      choose_and_remember_optimizer(state, project, mode, step, function(optimizer_args, optimizer_description, custom_optimizer)
      if state.closed then return end
      choose_training_device(state, mode, function(device, batch_device_policy)
        if not device or device == '' or state.closed then return end
        if state.busy or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch or not state.project_info
            or state.project_info.config_revision ~= revision then
          notify(tr('Project changed; prepare training again.', '项目已变化，请重新准备训练。', '專案已變更，請重新準備訓練。'), vim.log.levels.WARN); return
        end
        state.busy = tr('Checking training capability', '检查训练能力', '檢查訓練能力')
        render(state)
        request(state, { '--describe-interface' }, function(interface, failure)
          state.busy = nil
          render(state)
          local caps = interface and interface.data and interface.data.capabilities
          local detached = type(caps) == 'table' and caps['training.detached_cli_v1'] == true
          if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
              or type(caps) ~= 'table' or caps['training.conditional_config_start'] ~= true
              or (not external and state.batch_binding and caps['training.batch_binding_v1'] ~= true)
              or (batch_device_policy and caps['training.batch_device_policy_v1'] ~= true)
              or (custom_optimizer and caps['training.custom_optimizer_factory_v1'] ~= true)
              or (detached and caps['training.request_identity'] ~= true) or caps['training.atomic_run_admission'] ~= true then
            notify('This CLI cannot safely start and track this training request.', vim.log.levels.WARN); return
          end
          if needs_generic_device(device) and caps['training.generic_device_v1'] ~= true then
            notify(tr('This CLI cannot use a custom PyTorch device; select a compatible CLI.', '当前 CLI 不支持自定义 PyTorch 设备，请选择兼容版本。', '目前 CLI 不支援自訂 PyTorch 裝置，請選擇相容版本。'), vim.log.levels.WARN); return
          end
          if state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch or not state.project_info
              or state.project_info.config_revision ~= revision then
            notify(tr('Project changed; prepare training again.', '项目已变化，请重新准备训练。', '專案已變更，請重新準備訓練。'), vim.log.levels.WARN); return
          end
          local function launch_training(supervision_revision, no_model)
          if state.closed or state.busy or state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch or not state.project_info
              or state.project_info.config_revision ~= revision then
            notify(tr('Project changed; prepare training again.', '项目已变化，请重新准备训练。', '專案已變更，請重新準備訓練。'), vim.log.levels.WARN); return
          end
          if graph_guard and not graph_guard(mode) then
            notify(tr('Graph, data or source changed; prepare training again.', '图、数据或源码已变化，请重新准备训练。', '圖、資料或原始碼已變更，請重新準備訓練。'), vim.log.levels.WARN); return
          end
          local args = { 'train', external and '--loop' or '--step', step, '--steps', steps, '--device', device,
            '--training-mode', mode, '--if-config-revision', revision }
          if detached then args[#args + 1] = '--detach' end
          if variant then
            vim.list_extend(args, { '--variant', variant.name, '--if-variant-base', variant.token })
            if not external then
              if state.batch then vim.list_extend(args, { '--batch', state.batch }) end
              if state.batch_binding then vim.list_extend(args, { '--batch-binding', state.batch_binding }) end
              local batch_names = vim.tbl_keys(state.batch_params or {}); table.sort(batch_names)
              for _, key in ipairs(batch_names) do
                vim.list_extend(args, { '--batch-param', key .. '=' .. vim.json.encode(state.batch_params[key]) })
              end
            end
          end
          if no_model then args[#args + 1] = '--no-model' end
          if batch_device_policy then vim.list_extend(args, { '--batch-device-policy', batch_device_policy }) end
          vim.list_extend(args, param_args)
          vim.list_extend(args, optimizer_args)
          if supervision_revision then
            vim.list_extend(args, { '--apply-supervision', '--if-supervision-revision', supervision_revision })
          end
          local request_id
          local effects = (detached and tr('Starts training in the background.', '将启动后台训练。', '將啟動背景訓練。')
            or tr('Runs training in the foreground; keep this session open.', '将以前台方式训练，请保持会话打开。', '將以前景方式訓練，請保持工作階段開啟。'))
            .. (supervision_revision
              and tr(' Uses reviewed rules; penalty rules change the objective. Writes checkpoints and logs.',
                ' 使用已查看的规则；惩罚规则会改变训练目标，并写入检查点和日志。',
                ' 使用已檢視的規則；懲罰規則會改變訓練目標，並寫入檢查點和日誌。')
              or tr(' Writes checkpoints and logs. Supervision is not enabled.',
                ' 写入检查点和日志；未启用监督规则。', ' 寫入檢查點和日誌；未啟用監督規則。'))
            .. (external and tr('\nYour loop owns data, updates and progress reporting; input factory overrides are not passed.', '\n你的循环负责数据、参数更新与进度上报；不会传入输入工厂覆盖。', '\n你的迴圈負責資料、參數更新與進度回報；不會傳入輸入工廠覆蓋。')
              or (mode == 'manual-step' and tr('\nYour step owns backward and optimizer updates.', '\n你的步骤负责反向传播和优化器更新。', '\n你的步驟負責反向傳播與最佳化器更新。') or ''))
            .. (supervision_revision and mode ~= 'managed-step'
              and tr('\nYour code must use the supervision context protocol.', '\n你的代码必须遵循监督 context 协议。', '\n你的程式碼必須遵循監督 context 協議。') or '')
            .. (supervision_revision and tr('\nUser code can have side effects before checks; the tool does not roll them back.',
              '\n用户代码可能在检查前产生副作用，工具不会回滚。', '\n使用者程式碼可能在檢查前產生副作用，工具不會回復。') or '')
            .. (caps['training.random_run_seed_v1'] == true and not state.training_seed and tr('\nA new execution seed will be generated and recorded; variant construction can use a separate seed.',
              '\n将生成并记录本次执行种子；变体构造可能使用独立种子。', '\n將產生並記錄本次執行種子；變體建構可能使用獨立種子。') or '')
            .. '\nMode: ' .. mode .. '\nEntry: ' .. step .. '\nSteps: ' .. steps .. '\nDevice: ' .. device
            .. (batch_device_policy and (tr('\nBatch device policy: ', '\n批次设备策略：', '\n批次裝置策略：') .. batch_device_policy
              .. (batch_device_policy == 'preserve' and tr(' (your step manages placement)', '（由步骤管理设备）', '（由步驟管理裝置）')
                or tr(' (unsupported container types stop the run)', '（不支持的容器类型会中止运行）', '（不支援的容器類型會中止執行）'))) or '')
            .. '\nParameters: ' .. raw_params .. optimizer_description
          local function before_start(operation_args)
            if graph_guard and not graph_guard(mode) then
              notify(tr('Graph, data or source changed; prepare training again.', '图、数据或源码已变化，请重新准备训练。', '圖、資料或原始碼已變更，請重新準備訓練。'), vim.log.levels.WARN)
              return false
            end
            if not detached then return true end
            local existing, err = pending.list(project_root)
            if not existing or #existing > 0 then
              notify(tr('Resolve pending training requests before starting: ', '启动前请核查待确认的训练请求：', '啟動前請核查待確認的訓練要求：') .. tostring(err or table.concat(existing, ', ')), vim.log.levels.WARN)
              return false
            end
            request_id, err = pending.create(project_root)
            if not request_id then notify(tr('Could not record the training request: ', '无法记录训练请求：', '無法記錄訓練要求：') .. tostring(err), vim.log.levels.ERROR); return false end
            vim.list_extend(operation_args, { '--request-id', request_id })
            return true
          end
          local function finished(report, err)
            if not request_id then return end
            if err and err.operation_started == false then
              local ok, clear_err = pending.clear(project_root, request_id)
              if not ok then notify(tr('No training was started, but its pending marker needs inspection: ', '训练未启动，但待确认标记需要检查：', '訓練未啟動，但待確認標記需要檢查：') .. tostring(clear_err), vim.log.levels.WARN) end
            elseif not err and report and report.operation == 'train' and report.status == 'success'
                and type(report.data) == 'table' and report.data.detached == true and report.data.request_id == request_id
                and type(report.data.run_id) == 'string' and report.data.run_id ~= '' then
              local ok, clear_err = pending.clear(project_root, request_id)
              if not ok then notify(tr('Training started, but its pending marker remains: ', '训练已启动，但待确认标记仍存在：', '訓練已啟動，但待確認標記仍存在：') .. tostring(clear_err), vim.log.levels.WARN) end
            else
              notify(tr('Training outcome is not acknowledged. Use H to inspect request ', '训练结果尚未确认，请按 H 核查请求 ', '訓練結果尚未確認，請按 H 核查要求 ') .. request_id
                .. tr(' before another start.', '，然后再启动。', '，然後再啟動。'), vim.log.levels.WARN)
            end
          end
          run(state, detached and tr('Start background training', '启动后台训练', '啟動背景訓練')
              or tr('Run foreground training', '运行前台训练', '執行前景訓練'), args,
            detached and finished or nil, effects, external or variant ~= nil, (detached or graph_guard) and before_start or nil)
          end
          local function start_training(supervision_revision)
            if not external then launch_training(supervision_revision, false); return end
            if variant then launch_training(supervision_revision, false); return end
            if caps['training.external_loop_model_choice_v1'] ~= true then
              notify(tr('This CLI does not advertise explicit external-loop model selection; update it to choose safely.',
                '此 CLI 未声明支持完整循环的明确模型选择；请更新后选择。',
                '此 CLI 未宣告支援完整迴圈的明確模型選擇；請更新後選擇。'), vim.log.levels.WARN)
              return
            end
            vim.ui.select({ tr('Use selected or project model', '使用会话或项目模型', '使用工作階段或專案模型'),
              tr('No model: my loop manages it', '不使用模型：循环自行管理', '不使用模型：迴圈自行管理') }, {
              prompt = tr('What should the loop receive as its model?', '循环应接收哪个模型？', '迴圈應接收哪個模型？'),
            }, function(_, choice)
              if choice == 1 and not state.model and not (project and type(project.model) == 'string' and project.model ~= '') then
                notify(tr('No model is selected. Choose a model first or select the no-model option.',
                  '尚未选择模型；请先选择模型或选择无模型。', '尚未選擇模型；請先選擇模型或選擇無模型。'), vim.log.levels.WARN)
                return
              end
              if choice then launch_training(supervision_revision, choice == 2) end
            end)
          end
          vim.ui.select({ tr('Without supervision', '不启用监督', '不啟用監督'),
            tr('Review and enable supervision', '查看并启用监督', '檢視並啟用監督') }, {
              prompt = tr('Supervision for this run', '本次运行的监督', '本次執行的監督') .. (graph_rules or ''),
            }, function(_, choice)
              if not choice or state.closed or state.busy then return end
              if choice == 1 then start_training(nil); return end
              if caps['training.conditional_supervision'] ~= true then
                notify(tr('This CLI cannot pin the supervision revision.', '此 CLI 无法固定监督规则修订。', '此 CLI 無法固定監督規則修訂。'), vim.log.levels.WARN); return
              end
              state.busy = tr('Reading supervision rules', '读取监督规则', '讀取監督規則')
              render(state)
              request(state, { 'model', 'supervise', 'rule', 'list' }, function(catalog, err, stderr)
                state.busy = nil
                if state.opts.project ~= project_root or (state.change_epoch or 0) ~= epoch
                    or not state.project_info or state.project_info.config_revision ~= revision then
                  render(state)
                  notify(tr('Context changed; prepare training again.', '上下文已变化，请重新准备训练。', '上下文已變更，請重新準備訓練。'), vim.log.levels.WARN); return
                end
                state.last = { report = catalog, transport_error = err, stderr = stderr }
                render(state)
                local data = catalog and catalog.data
                if err or not catalog or catalog.operation ~= 'semantic_supervise' or catalog.status ~= 'success'
                    or type(data) ~= 'table' or type(data.rules) ~= 'table' or not is_list(data.rules)
                    or not sha256(data.state_revision) then
                  notify(tr('Cannot verify supervision rules; training was not started.', '无法核对监督规则，训练未启动。', '無法核對監督規則，訓練未啟動。'), vim.log.levels.WARN)
                  show_report(state); return
                end
                local listed = state.last
                local review = show_report(state)
                review_gate(review, { tr('Cancel', '取消', '取消'), tr('Continue with these rules', '使用这些规则继续', '使用這些規則繼續') },
                  tr('Review the rule report first; [J] opens all fields. Continue to training confirmation?',
                    '请先查看规则报告；[J] 可打开完整字段。继续确认训练？',
                    '請先檢視規則報告；[J] 可開啟完整欄位。繼續確認訓練？'), function(_, selected)
                  if selected ~= 2 or state.closed or state.last ~= listed or listed.context_changed then return end
                  start_training(data.state_revision)
                end)
              end)
            end)
        end)
      end)
    end, source == 'graph' and step == graph_entry and graph_training and graph_training.optimizer or nil)
  end)
  end)
  end)
  end
  if graph_prepare and not external then graph_prepare(start_entry) else start_entry() end
  end)
end

local function prepare_training(state)
  if state.closed or state.busy then return end
  vim.ui.select({
    tr('Framework-neutral user loop', '无框架用户循环', '無框架使用者迴圈'),
    tr('PyTorch training modes', 'PyTorch 训练模式', 'PyTorch 訓練模式'),
  }, { prompt = tr('Choose how to run training', '选择训练运行方式', '選擇訓練執行方式') }, function(_, choice)
    if state.closed or state.busy then return end
    if choice == 1 then prepare_generic_trial(state, true)
    elseif choice == 2 then prepare_pytorch_training(state) end
  end)
end

local function create_adapter_draft(state, loop_draft)
  if state.busy then
    notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN)
    return
  end
  local project, adapter_epoch = state.opts.project, state.change_epoch or 0
  local project_root = vim.uv.fs_realpath(project)
  if not project_root then notify(tr('Project directory is unavailable.', '项目目录不可用。', '專案目錄無法使用。'), vim.log.levels.ERROR); return end
  local roots = { { path = project_root, label = tr('Project root', '项目根目录', '專案根目錄') } }
  local seen = { [vim.fs.normalize(project_root)] = true }
  local omitted_roots = 0
  for _, relative in ipairs(state.opts.project_import_roots or {}) do
    if type(relative) == 'string' and relative ~= '' then
      local source = vim.fs.normalize(project_root .. '/' .. relative)
      local resolved = vim.uv.fs_realpath(source)
      local stat = resolved and vim.uv.fs_stat(resolved)
      if resolved and stat and stat.type == 'directory' and in_project(project_root, resolved)
          and vim.fs.normalize(resolved) == source and not seen[vim.fs.normalize(resolved)] then
        roots[#roots + 1] = { path = resolved, source = source,
          label = tr('Selected import root: ', '所选模块目录：', '所選模組目錄：') .. relative }
        seen[vim.fs.normalize(resolved)] = true
      else
        omitted_roots = omitted_roots + 1
      end
    else
      omitted_roots = omitted_roots + 1
    end
  end
  vim.ui.select(roots, {
    prompt = tr('Where should the adapter module be saved?', '适配器模块保存在哪里？', '配接器模組儲存在哪裡？')
      .. (omitted_roots > 0 and tr(' Some selected import roots are unavailable, duplicated or use symlinks; review K.',
        ' 部分模块目录不可用、重复或经过符号链接；请在 K 中检查。',
        ' 部分模組目錄無法使用、重複或經過符號連結；請在 K 中檢查。') or ''),
    format_item = function(item) return item.label end,
  }, function(location)
    if not location or state.closed or state.busy or state.opts.project ~= project
        or (state.change_epoch or 0) ~= adapter_epoch then return end
  vim.ui.input({ prompt = tr('New adapter module name (no .py; CLI and Python validate it when used): ',
    '新适配器模块名（不含 .py；使用时由 CLI 和 Python 校验）：', '新配接器模組名稱（不含 .py；使用時由 CLI 和 Python 驗證）：'),
    default = loop_draft and 'model_maven_loop' or 'model_maven_adapter' }, function(name)
    if not name or state.closed or state.opts.project ~= project then return end
    if state.busy or (state.change_epoch or 0) ~= adapter_epoch then
      notify(tr('Context changed; reopen adapter creation.', '上下文已变化，请重新创建适配器。', '上下文已變更，請重新建立配接器。'), vim.log.levels.WARN)
      return
    end
    if not module_part_candidate(name) then
      notify(tr('Enter a module name without separators, whitespace or control characters.',
        '请输入不含分隔符、空格或控制字符的模块名。', '請輸入不含分隔符、空格或控制字元的模組名稱。'), vim.log.levels.WARN)
      return
    end
    local root = vim.uv.fs_realpath(location.path)
    if not root or vim.fs.normalize(root) ~= vim.fs.normalize(location.path)
        or (location.source and vim.uv.fs_realpath(location.source) ~= root)
        or (root ~= project_root and not in_project(project_root, root)) then
      notify(tr('Adapter directory changed; reopen adapter creation.', '适配器目录已变化，请重新创建。', '配接器目錄已變更，請重新建立。'), vim.log.levels.WARN); return
    end
    local path = root .. '/' .. name .. '.py'
    if vim.uv.fs_lstat(path) or vim.fn.bufnr(path) ~= -1 then
      notify(tr('That file or buffer already exists; choose another name.', '该文件或 buffer 已存在，请换一个名称。', '該檔案或 buffer 已存在，請換一個名稱。'), vim.log.levels.WARN)
      return
    end
    local buf = vim.api.nvim_create_buf(true, false)
    local ok, error_message = pcall(vim.api.nvim_buf_set_name, buf, path)
    if not ok then
      vim.api.nvim_buf_delete(buf, { force = true })
      notify(tostring(error_message), vim.log.levels.ERROR)
      return
    end
    local draft_lines = loop_draft and {
      '# Your loop owns its framework, model, data and updates.',
      '# Choose the context-only signature in Model-Maven when running.',
      '# State and metrics may be saved; do not put credentials in them.',
      '# Omitted state or state=None does not create a checkpoint.',
      '',
      'def loop(context):',
      '    """Run user-defined steps; restore context.resume_state if needed."""',
      '    # Use context.completed_steps and context.total_steps for resumption.',
      '    # After each step: if not context.report_step(metrics, state=state): break',
      '    raise NotImplementedError("Implement your own training loop")',
    } or {
      '# Adapt your existing project here. Nothing runs until you choose an action.',
      '# Replace the placeholders; do not put credentials in this file.',
      '',
      'def model():',
      '    """Return the model instance to inspect and run."""',
      '    raise NotImplementedError("Connect your existing model here")',
      '',
      'def batch():',
      '    """Return e.g. {"args": [input_tensor], "kwargs": {}}."""',
      '    raise NotImplementedError("Connect a representative input here")',
      '',
      '# Optional: add a training step or use your existing training loop.',
    }
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, draft_lines)
    vim.bo[buf].filetype = 'python'
    vim.api.nvim_create_autocmd('BufWritePost', { buffer = buf, once = true, callback = function()
      if state.closed or state.opts.project ~= project or vim.api.nvim_buf_get_name(buf) ~= path then return end
      local saved_epoch = state.change_epoch or 0
      vim.ui.select({ tr('Keep current choices', '保留当前选择', '保留目前選擇'),
        loop_draft and tr('Use this loop for this session', '本次会话使用此循环', '本工作階段使用此迴圈')
          or tr('Use adapter model and input for this session', '本次会话使用适配器模型和输入', '本工作階段使用配接器模型和輸入') }, {
          prompt = (loop_draft and tr('Loop saved. Select it for this session?', '循环已保存。将其用于本次会话？', '迴圈已儲存。將其用於本工作階段？')
            or tr('Adapter saved. Select its factories?', '适配器已保存。选择其中的工厂？', '配接器已儲存。選擇其中的工廠？'))
            .. tr(' Import order may resolve the same name elsewhere.', ' 相同模块名可能因搜索顺序解析到其他位置。', ' 相同模組名稱可能因搜尋順序解析到其他位置。'),
        }, function(_, choice)
          if choice ~= 2 or state.closed or state.busy or state.opts.project ~= project then return end
          if (state.change_epoch or 0) ~= saved_epoch
              or (location.source and vim.uv.fs_realpath(location.source) ~= root) then
            notify(loop_draft and tr('Context changed; find the loop with F or enter it when preparing training.',
              '上下文已变化，请用 F 查找循环，或在准备训练时填写。', '上下文已變更，請用 F 尋找迴圈，或在準備訓練時填寫。')
              or tr('Context changed; choose the adapter factories again with m and b.',
              '上下文已变化，请使用 m 和 b 重新选择适配器工厂。', '上下文已變更，請使用 m 和 b 重新選擇配接器工廠。'), vim.log.levels.WARN)
            return
          end
          if loop_draft then
            state.loop = name .. ':loop'
          else
            switch_factory(state, 'model', name .. ':model')
            switch_factory(state, 'batch', name .. ':batch')
          end
          state.change_epoch = (state.change_epoch or 0) + 1
          state.journey = nil
          if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
          state.result_label = loop_draft and tr('loop selected; finish code and choose context-only signature',
            '已选择循环；请完成代码并选择仅 context 签名', '已選擇迴圈；請完成程式碼並選擇僅 context 簽章')
            or tr('adapter selected; complete its code before running', '已选择适配器；运行前请完成代码', '已選擇配接器；執行前請完成程式碼')
          render(state)
        end)
    end })
    if state.code_win and vim.api.nvim_win_is_valid(state.code_win)
        and vim.api.nvim_win_get_tabpage(state.code_win) == vim.api.nvim_get_current_tabpage() then
      vim.api.nvim_set_current_win(state.code_win)
    end
    if not open_aux_buffer(buf, true, true) then return end
    state.code_win = vim.api.nvim_get_current_win()
    notify(tr('Edit the placeholders and :write to save. No file has been created yet.',
      '请修改占位代码并用 :write 保存；文件尚未创建。', '請修改佔位程式碼並用 :write 儲存；檔案尚未建立。'), vim.log.levels.INFO)
  end)
  end)
end

local function open_source(state, on_open)
  local origin_project = state.opts.project
  local report = state.last and not state.last.context_changed and state.last.report
  local generated = report and report.operation == 'assembly_generate' and report.status == 'success'
    and type(report.data) == 'table' and type(report.data.output) == 'string' and report.data.output or nil
  local suggested = generated and (state.opts.project .. '/' .. generated) or state.opts.project
  local hint_used = false
  local hint = state.discovered_model_source
  if not generated and hint and hint.project == state.opts.project and hint.entrypoint == state.model then
    local absolute = hint.file:sub(1, 1) == '/' or hint.file:match('^%a:[/\\]')
    local candidate = vim.uv.fs_realpath(absolute and hint.file or (state.opts.project .. '/' .. hint.file))
    if candidate and in_project(state.opts.project, candidate) and vim.fn.filereadable(candidate) == 1 then
      suggested = candidate
      hint_used = true
    end
  end
  if not generated and not hint_used then
    local model = state.model or (state.project_info and state.project_info.model)
    local module = type(model) == 'string' and model:match('^([^:]+):[^:]+$') or nil
    local parts = module and vim.split(module, '.', {plain = true}) or {}
    local valid = #parts > 0
    for _, part in ipairs(parts) do if not module_part_candidate(part) then valid = false end end
    if valid then
      local roots = vim.deepcopy(state.opts.project_import_roots or {}); roots[#roots + 1] = ''
      for _, root in ipairs(roots) do
        local base = state.opts.project .. '/' .. (root ~= '' and root .. '/' or '') .. table.concat(parts, '/')
        for _, path in ipairs({base .. '.py', base .. '/__init__.py'}) do
          local candidate = vim.uv.fs_realpath(path)
          if candidate and in_project(state.opts.project, candidate) and vim.fn.filereadable(candidate) == 1 then
            suggested, hint_used = candidate, true; break
          end
        end
        if hint_used then break end
      end
    end
  end
  local prompt = hint_used and tr('Python file (unverified discovery suggestion): ', 'Python 文件（未验证的发现候选）：', 'Python 檔案（未驗證的探索候選）：')
    or tr('Python file: ', 'Python 文件路径：', 'Python 檔案路徑：')
  vim.ui.input({ prompt = prompt, default = suggested }, function(value)
    if not value or value == '' or state.closed then return end
    if state.opts.project ~= origin_project then
      notify(tr('Project changed; choose the source file again.', '项目已变化，请重新选择源码文件。', '專案已變更，請重新選擇原始碼檔案。'), vim.log.levels.WARN)
      return
    end
    local absolute = value:sub(1, 1) == '/' or value:match('^%a:[/\\]') or value:match('^[/\\][/\\]')
    local path = vim.fn.fnamemodify(absolute and value or (state.opts.project .. '/' .. value), ':p')
    if vim.fn.filereadable(path) ~= 1 then
      notify('Model-Maven: file is not readable: ' .. path, vim.log.levels.ERROR)
      return
    end
    if generated and report and type(report.data.generated_source_sha256) == 'string'
        and sha256(report.data.generated_source_sha256)
        and path == vim.fn.fnamemodify(state.opts.project .. '/' .. generated, ':p') then
      local stat = vim.uv.fs_stat(path)
      local file = stat and stat.type == 'file' and stat.size <= 4 * 1024 * 1024 and io.open(path, 'rb') or nil
      local contents = file and file:read(4 * 1024 * 1024 + 1) or nil
      if file then file:close() end
      if not contents or #contents > 4 * 1024 * 1024 or vim.fn.sha256(contents) ~= report.data.generated_source_sha256 then
        notify(tr('This file differs from the generated source, or could not be checked. Review its current contents.',
          '文件与生成源码不同或无法核对，请检查当前内容。', '檔案與產生的原始碼不同或無法核對，請檢查目前內容。'), vim.log.levels.WARN)
      end
      local existing = vim.fn.bufnr(path)
      if existing ~= -1 and vim.api.nvim_buf_is_loaded(existing) and vim.bo[existing].modified then
        notify(tr('An open buffer has unsaved changes; its contents may differ from disk.',
          '已打开的 buffer 有未保存修改，内容可能不同于磁盘。', '已開啟的 buffer 有未儲存修改，內容可能不同於磁碟。'), vim.log.levels.WARN)
      end
    end
    if focus_source(state, path) and on_open then on_open() end
  end)
end

local function save_project_model(state, suggested_model, on_saved)
  local project = state.project_info
  if state.busy or not project or not sha256(project.config_revision)
      or #dirty_buffers(state.opts.project) > 0 or #reloads_pending(state) > 0 then
    notify(tr('Check project status and reconcile open buffers first.', '请先检查项目状态并处理打开的 buffer。', '請先檢查專案狀態並處理開啟的 buffer。'), vim.log.levels.WARN); return
  end
  local revision, epoch = project.config_revision, state.change_epoch or 0
  local origin_project, origin_cli = state.opts.project, state.opts.cli
  local function same_context()
    return not state.closed and state.opts.project == origin_project and state.opts.cli == origin_cli
      and (state.change_epoch or 0) == epoch and state.project_info
      and state.project_info.config_revision == revision and project_config_current(state)
  end
  local initial_model, initial_params = state.model, vim.deepcopy(state.model_params or {})
  local project_defaults = project_config(state.opts.project) or {}
  vim.ui.input({ prompt = tr('Project model factory module:callable: ', '项目模型工厂 module:callable：', '專案模型工廠 module:callable：'),
    default = suggested_model or state.model or project.model or '' }, function(model)
    if not model or model == '' or state.closed then return end
    local saved_params = model == project.model and type(project_defaults.model_params) == 'table'
      and vim.deepcopy(project_defaults.model_params) or {}
    if model == (initial_model or project.model) then
      for name, value in pairs(initial_params) do saved_params[name] = value end
    end
    local encoded, default_params = pcall(vim.json.encode, next(saved_params) and saved_params or vim.empty_dict())
    if not encoded or #default_params > 16384 then
      notify(tr('Current model parameters cannot be displayed safely.', '无法安全显示当前模型参数。', '無法安全顯示目前模型參數。'), vim.log.levels.WARN); return
    end
    vim.ui.input({ prompt = tr('Replacement model parameters as JSON ({} clears all); saved in project, no secrets: ',
      '替换后的模型参数 JSON（{} 清空全部）；将保存在项目中，请勿填写密钥：', '替換後的模型參數 JSON（{} 清空全部）；將儲存在專案中，請勿填寫金鑰：'),
      default = default_params }, function(raw)
      if not raw or state.closed then return end
      local ok, params = pcall(vim.json.decode, raw)
      if #raw > 16384 or not ok or type(params) ~= 'table' or not raw:match('^%s*{') then
        notify(tr('Enter a JSON object no larger than 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
      end
      vim.ui.select({ tr('Keep current assembly injections', '保留现有装配注入', '保留現有裝配注入'),
        tr('Clear assembly injections', '清除装配注入', '清除裝配注入') }, {
          prompt = tr('Changing factories can invalidate injections. Choose what to save:',
            '切换工厂可能使装配注入失效。请选择保存方式：', '切換工廠可能使裝配注入失效。請選擇儲存方式：'),
        }, function(_, choice)
        if not choice or state.closed then return end
        local args = { 'config', 'set-model', '--model', model }
        if choice == 2 then args[#args + 1] = '--clear-injections' end
        local names = vim.tbl_keys(params)
        table.sort(names)
        if #names > 64 then notify(tr('Too many parameters.', '参数数量过多。', '參數數量過多。'), vim.log.levels.WARN); return end
        for _, name in ipairs(names) do
          if not parameter_name_candidate(name) then
            notify('Invalid parameter name: ' .. tostring(name), vim.log.levels.WARN); return
          end
          local encoded, value = pcall(vim.json.encode, params[name])
          if not encoded then notify('Cannot encode parameter: ' .. name, vim.log.levels.WARN); return end
          vim.list_extend(args, { '--model-param', name .. '=' .. value })
        end
        if state.busy or not same_context() or state.model ~= initial_model
            or not vim.deep_equal(state.model_params or {}, initial_params)
            or not state.project_info
            or state.project_info.config_revision ~= revision then
          notify(tr('Project changed; prepare the model again.', '项目已变化，请重新准备模型。', '專案已變更，請重新準備模型。'), vim.log.levels.WARN); return
        end
        state.busy = tr('Checking model configuration support', '检查模型配置能力', '檢查模型設定能力'); render(state)
        request(state, { '--describe-interface' }, function(interface, failure)
          if not same_context() then
            state.busy = nil; render(state)
            notify(tr('Context changed; prepare the model again.', '上下文已变化，请重新准备模型。', '上下文已變更，請重新準備模型。'), vim.log.levels.WARN); return
          end
          local caps = interface and interface.data and interface.data.capabilities
          if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
              or type(caps) ~= 'table' or caps['project.conditional_model_edit'] ~= true then
            state.busy = nil; render(state)
            notify(tr('This CLI cannot safely update the project model.', '当前 CLI 无法安全更新项目模型。', '目前 CLI 無法安全更新專案模型。'), vim.log.levels.WARN); return
          end
          state.busy = tr('Previewing project model', '预览项目模型', '預覽專案模型'); render(state)
          request(state, args, function(report, err, stderr)
            state.busy = nil
            if not same_context() then
              render(state)
              notify(tr('Context changed; preview the model again.', '上下文已变化，请重新预览模型。', '上下文已變更，請重新預覽模型。'), vim.log.levels.WARN); return
            end
            state.last = { report = report, transport_error = err, stderr = stderr }
            render(state)
            local data = report and report.data
            if err or not report or report.operation ~= 'config_set_model' or report.status ~= 'success'
                or type(data) ~= 'table' or data.committed ~= false or data.from_revision ~= revision
                or data.model ~= model or data.clear_injections ~= (choice == 2)
                or not vim.deep_equal(data.model_params, params) or type(data.redacted_fields) ~= 'table'
                or #data.redacted_fields > 0 then
              notify(tr('Model preview is unavailable or redacted; configuration was not changed.',
                '模型预览不可用或已脱敏；配置未修改。', '模型預覽無法使用或已去識別；設定未修改。'), vim.log.levels.WARN)
              show_report(state); return
            end
            local ok_preview, text = pcall(vim.inspect, { previous_model = data.previous_model, previous_model_params = data.previous_model_params, model = data.model,
              model_params = data.model_params, previous_model_injections = data.previous_model_injections,
              model_injections = data.model_injections, clear_injections = data.clear_injections })
            if not ok_preview or not reviewable_text(text) then notify('Model preview is too large to approve.', vim.log.levels.WARN); return end
            local review_buf = show_report(state)
            if data.unchanged then notify(tr('The saved model is already identical.', '项目默认模型已相同。', '專案預設模型已相同。'), vim.log.levels.INFO); return end
            local preview = state.last
            review_gate(review_buf, { tr('Cancel', '取消', '取消'), tr('Save model', '保存模型', '儲存模型') },
              tr('Save this configuration? The model and injections have not been run.',
                '保存此配置？模型和装配注入尚未运行。', '儲存此設定？模型和裝配注入尚未執行。'), function(_, selected)
              if selected ~= 2 or state.closed then return end
              if state.busy or state.last ~= preview or (state.change_epoch or 0) ~= epoch
                  or #dirty_buffers(state.opts.project) > 0 or #reloads_pending(state) > 0
                  or state.model ~= initial_model or not vim.deep_equal(state.model_params or {}, initial_params)
                  or not state.project_info or state.project_info.config_revision ~= revision
                  or not project_config_current(state) then
                notify(tr('Project or model changed; preview again.', '项目或模型已变化，请重新预览。', '專案或模型已變更，請重新預覽。'), vim.log.levels.WARN); return
              end
              local apply = vim.deepcopy(args)
              vim.list_extend(apply, { '--apply', '--if-current', revision })
              local tracked = begin_tracked_commit(state, tr('Save project model', '保存项目模型', '儲存專案模型'))
              if not tracked then return end
              state.busy = tr('Saving project model', '保存项目模型', '儲存專案模型'); render(state)
              request(state, apply, function(receipt, problem, output)
                state.busy = nil
                local same_context = tracked_commit_current(state, tracked)
                if same_context then state.last = { report = receipt, transport_error = problem, stderr = output } end
                local saved = receipt and receipt.data
                local verified = not problem and receipt and receipt.operation == 'config_set_model' and receipt.status == 'success'
                    and type(saved) == 'table' and saved.committed == true and saved.from_revision == revision
                    and sha256(saved.config_revision) and saved.model == model
                    and saved.clear_injections == (choice == 2) and vim.deep_equal(saved.model_params, params)
                    and vim.deep_equal(saved.model_injections, data.model_injections)
                local settled = settle_tracked_commit(state, tracked, verified, problem)
                if not same_context then render(state); notify_tracked_context_changed(tracked); return end
                if verified and settled then
                  state.model, state.model_params = nil, {}
                  if state.factory_drafts then state.factory_drafts.model[model] = nil end
                  if state.known_project_defaults then state.known_project_defaults.model = model end
                  state.journey, state.last_edit = nil, nil
                  state.change_epoch = (state.change_epoch or 0) + 1
                  state.result_label = tr('project model saved; not run', '项目模型已保存；尚未运行', '專案模型已儲存；尚未執行')
                else
                  state.result_label = tr('model save outcome requires inspection', '模型保存结果需要核查', '模型儲存結果需要核查')
                end
                show_report(state)
                refresh_project(state, function()
                  if verified and settled and on_saved and not state.closed and state.opts.project == origin_project
                      and state.opts.cli == origin_cli and state.project_info
                      and state.project_info.config_revision == saved.config_revision and state.project_info.model == model
                      and project_config_current(state) then on_saved(model) end
                end)
              end)
            end)
          end)
        end)
      end)
    end)
  end)
end

local function save_project_input(state, use_current, suggested, guard, on_saved)
  local project = state.project_info
  if state.busy or not project or not sha256(project.config_revision)
      or #dirty_buffers(state.opts.project) > 0 or #reloads_pending(state) > 0 then
    notify(tr('Check project status and save or reconcile open buffers first.', '请先检查项目状态，并保存或处理打开的 buffer。', '請先檢查專案狀態，並儲存或處理開啟的 buffer。'), vim.log.levels.WARN); return
  end
  local revision, epoch = project.config_revision, state.change_epoch or 0
  local origin_project, origin_cli = state.opts.project, state.opts.cli
  local function same_context()
    return not state.closed and state.opts.project == origin_project and state.opts.cli == origin_cli
      and (state.change_epoch or 0) == epoch and state.project_info
      and state.project_info.config_revision == revision and project_config_current(state)
      and (not guard or guard())
  end
  local initial_batch, initial_params = state.batch, vim.deepcopy(state.batch_params or {})
  local initial_binding = state.batch_binding
  local project_defaults = project_config(state.opts.project) or {}
  local function choose_input(options, callback)
    if suggested then callback(suggested.factory)
    elseif use_current then callback(initial_batch or project.batch) else vim.ui.input(options, callback) end
  end
  local function choose_binding(options, settings, callback)
    if suggested then callback(suggested.binding or 'auto')
    elseif use_current then callback(initial_binding or 'auto') else vim.ui.select(options, settings, callback) end
  end
  local function choose_parameters(options, callback)
    if suggested then
      local ok, raw = pcall(vim.json.encode, suggested.params or vim.empty_dict())
      if ok then callback(raw) else notify(tr('Cannot encode data parameters.', '无法编码数据参数。', '無法編碼資料參數。'), vim.log.levels.WARN) end
    elseif use_current then callback(options.default) else vim.ui.input(options, callback) end
  end
  choose_input({ prompt = tr('Project input factory module:callable: ', '项目输入工厂 module:callable：', '專案輸入工廠 module:callable：'),
    default = state.batch or project.batch or '' }, function(batch)
    if not batch or batch == '' or state.closed then return end
    local is_current = batch == (initial_batch or project.batch)
    local preferred = is_current and (initial_binding or (not initial_batch and type(project_defaults.batch_binding) == 'string'
      and project_defaults.batch_binding) or 'auto') or 'auto'
    if not vim.tbl_contains({ 'auto', 'envelope', 'single', 'single-raw', 'args', 'kwargs' }, preferred) then preferred = 'auto' end
    local bindings = { preferred }
    for _, option in ipairs({ 'auto', 'envelope', 'single', 'single-raw', 'args', 'kwargs' }) do
      if option ~= preferred then bindings[#bindings + 1] = option end
    end
    local saved_params = {}
    if is_current and not initial_batch and type(project_defaults.batch_params) == 'table' then
      saved_params = vim.deepcopy(project_defaults.batch_params)
    end
    if is_current then for name, value in pairs(initial_params) do saved_params[name] = value end end
    local encoded, default_params = pcall(vim.json.encode, next(saved_params) and saved_params or vim.empty_dict())
    if not encoded or #default_params > 16384 then
      notify(tr('Current input parameters cannot be displayed safely.', '无法安全显示当前输入参数。', '無法安全顯示目前輸入參數。'), vim.log.levels.WARN); return
    end
    choose_binding(bindings, {
      prompt = tr('Replacement input binding (auto clears the saved binding)', '替换后的输入绑定方式（auto 清除已保存的绑定）', '替換後的輸入繫結方式（auto 清除已儲存的繫結）'),
    }, function(binding)
      if not binding or state.closed then return end
      choose_parameters({ prompt = tr('Replacement input parameters as JSON ({} clears all); saved in project, no secrets: ',
        '替换后的输入参数 JSON（{} 清空全部）；将保存在项目中，请勿填写密钥：', '替換後的輸入參數 JSON（{} 清空全部）；將儲存在專案中，請勿填寫金鑰：'), default = default_params }, function(raw)
        if not raw or state.closed then return end
        local ok, params = pcall(vim.json.decode, raw)
        if #raw > 16384 or not ok or type(params) ~= 'table' or not raw:match('^%s*{') then
          notify(tr('Enter a JSON object no larger than 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
        end
        local args = { 'config', 'set-batch', '--batch', batch }
        if binding ~= 'auto' then vim.list_extend(args, { '--batch-binding', binding }) end
        local names = vim.tbl_keys(params)
        table.sort(names)
        if #names > 64 then notify(tr('Too many parameters.', '参数数量过多。', '參數數量過多。'), vim.log.levels.WARN); return end
        for _, name in ipairs(names) do
          if not parameter_name_candidate(name) then
            notify('Invalid parameter name: ' .. tostring(name), vim.log.levels.WARN); return
          end
          local encoded, value = pcall(vim.json.encode, params[name])
          if not encoded then notify('Cannot encode parameter: ' .. name, vim.log.levels.WARN); return end
          vim.list_extend(args, { '--batch-param', name .. '=' .. value })
        end
        if state.busy or not same_context() or state.batch ~= initial_batch
            or state.batch_binding ~= initial_binding or not vim.deep_equal(state.batch_params or {}, initial_params)
            or not state.project_info
            or state.project_info.config_revision ~= revision then
          notify(tr('Project changed; prepare the input again.', '项目已变化，请重新准备输入。', '專案已變更，請重新準備輸入。'), vim.log.levels.WARN); return
        end
        state.busy = tr('Checking input configuration support', '检查输入配置能力', '檢查輸入設定能力')
        render(state)
        request(state, { '--describe-interface' }, function(interface, failure)
          if not same_context() then
            state.busy = nil; render(state)
            notify(tr('Context changed; prepare the input again.', '上下文已变化，请重新准备输入。', '上下文已變更，請重新準備輸入。'), vim.log.levels.WARN); return
          end
          local caps = interface and interface.data and interface.data.capabilities
          if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
              or type(caps) ~= 'table' or caps['project.conditional_batch_edit'] ~= true
              or caps['project.conditional_batch_edit_previous'] ~= true
              or (binding == 'single-raw' and caps['data.raw_batch_binding_v1'] ~= true) then
            state.busy = nil; render(state)
            notify(tr('This CLI cannot safely update the project input.', '当前 CLI 无法安全更新项目输入。', '目前 CLI 無法安全更新專案輸入。'), vim.log.levels.WARN); return
          end
          state.busy = tr('Previewing project input', '预览项目输入', '預覽專案輸入')
          render(state)
          request(state, args, function(report, err, stderr)
            state.busy = nil
            if not same_context() then
              render(state)
              notify(tr('Context changed; preview the input again.', '上下文已变化，请重新预览输入。', '上下文已變更，請重新預覽輸入。'), vim.log.levels.WARN); return
            end
            state.last = { report = report, transport_error = err, stderr = stderr }
            render(state)
            local data = report and report.data
            local expected_binding = binding == 'auto' and vim.NIL or binding
            if err or not report or report.operation ~= 'config_set_batch' or report.status ~= 'success'
                or type(data) ~= 'table' or data.committed ~= false or data.from_revision ~= revision
                or data.batch ~= batch or data.batch_binding ~= expected_binding or not vim.deep_equal(data.batch_params, params)
                or data.previous_batch_params == nil or type(data.redacted_fields) ~= 'table' or #data.redacted_fields > 0 then
              notify(tr('Input preview is unavailable or contains redacted parameters; no configuration was changed.',
                '输入预览不可用或参数已脱敏；配置未修改。', '輸入預覽無法使用或參數已去識別；設定未修改。'), vim.log.levels.WARN)
              show_report(state); return
            end
            local inspect_ok, review = pcall(vim.inspect, { previous_batch = data.previous_batch,
              previous_batch_binding = data.previous_batch_binding, previous_batch_params = data.previous_batch_params,
              batch = data.batch, batch_binding = data.batch_binding, batch_params = data.batch_params })
            if not inspect_ok or not reviewable_text(review) then
              notify(tr('Input preview is too large to approve here.', '输入预览过大，当前界面不能批准。', '輸入預覽過大，目前介面不能批准。'), vim.log.levels.WARN)
              show_report(state); return
            end
            local review_buf = show_report(state)
            if data.unchanged == true then
              notify(tr('The saved input is already identical.', '项目默认输入已相同。', '專案預設輸入已相同。'), vim.log.levels.INFO); return
            end
            local preview = state.last
            review_gate(review_buf, { tr('Cancel', '取消', '取消'), tr('Save input', '保存输入', '儲存輸入') },
              tr('Save the reviewed input configuration? It does not run the factory.',
                '保存已查看的输入配置？此操作不会运行工厂。', '儲存已檢視的輸入設定？此操作不會執行工廠。'), function(_, choice)
              if choice ~= 2 or state.closed then return end
              if state.busy or state.last ~= preview or (state.change_epoch or 0) ~= epoch
                  or #dirty_buffers(state.opts.project) > 0 or #reloads_pending(state) > 0
                  or state.batch ~= initial_batch or state.batch_binding ~= initial_binding
                  or not vim.deep_equal(state.batch_params or {}, initial_params)
                  or not state.project_info or state.project_info.config_revision ~= revision
                  or not project_config_current(state) or (guard and not guard()) then
                notify(tr('Project or input changed; preview again.', '项目或输入已变化，请重新预览。', '專案或輸入已變更，請重新預覽。'), vim.log.levels.WARN); return
              end
              local apply = vim.deepcopy(args)
              vim.list_extend(apply, { '--apply', '--if-current', revision })
              local tracked = begin_tracked_commit(state, tr('Save project input', '保存项目输入', '儲存專案輸入'))
              if not tracked then return end
              state.busy = tr('Saving project input', '保存项目输入', '儲存專案輸入')
              render(state)
              request(state, apply, function(receipt, problem, output)
                state.busy = nil
                local same_context = tracked_commit_current(state, tracked)
                if same_context then state.last = { report = receipt, transport_error = problem, stderr = output } end
                local saved = receipt and receipt.data
                local verified = not problem and receipt and receipt.operation == 'config_set_batch' and receipt.status == 'success'
                    and type(saved) == 'table' and saved.committed == true and saved.from_revision == revision
                    and sha256(saved.config_revision) and saved.batch == batch and saved.batch_binding == expected_binding
                    and vim.deep_equal(saved.batch_params, params)
                local settled = settle_tracked_commit(state, tracked, verified, problem)
                if not same_context then render(state); notify_tracked_context_changed(tracked); return end
                if verified and settled then
                  state.batch, state.batch_params, state.batch_binding = nil, {}, nil
                  if state.factory_drafts then state.factory_drafts.batch[batch] = nil end
                  if state.known_project_defaults then state.known_project_defaults.batch = batch end
                  -- This revision is the confirmed write, not an external context change.
                  state.known_config_revision = saved.config_revision
                  state.journey, state.last_edit = nil, nil
                  state.change_epoch = (state.change_epoch or 0) + 1
                  state.result_label = tr('project input saved; not run', '项目输入已保存；尚未运行', '專案輸入已儲存；尚未執行')
                else
                  state.result_label = tr('input save outcome requires inspection', '输入保存结果需要核查', '輸入儲存結果需要核查')
                end
                show_report(state)
                refresh_project(state, function()
                  if verified and settled and on_saved and not state.closed
                      and state.opts.project == origin_project and state.opts.cli == origin_cli
                      and state.project_info and state.project_info.config_revision == saved.config_revision
                      and project_config_current(state) and (not guard or guard()) then
                    on_saved()
                  end
                end)
              end)
            end, nil, true)
          end)
        end)
      end)
    end)
  end)
end

local function setup_existing(state, suggested_model, on_saved)
  if state.busy then notify(tr('Wait for the current operation.', '请等待当前操作完成。', '請等待目前操作完成。'), vim.log.levels.WARN); return end
  local _, config_state = project_config(state.opts.project)
  if config_state ~= 'missing' then
    notify('This project has a configuration or its state is unknown. No changes were made.', vim.log.levels.WARN)
    return
  end
  local setup_project, setup_cli, setup_start_epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
  if #dirty_buffers(state.opts.project) > 0 then
    notify(tr('Save project buffers or cancel before planning configuration.', '规划配置前请保存项目内容或取消。', '規劃設定前請儲存專案內容或取消。'), vim.log.levels.WARN)
    return
  end
  vim.ui.input({ prompt = tr('Model factory module:callable: ', '模型工厂 module:callable：', '模型工廠 module:callable：'), default = suggested_model or state.model or '' }, function(model)
    if not model or model == '' then return end
    vim.ui.input({ prompt = tr('Input factory module:callable (optional): ', '输入工厂 module:callable（选填）：', '輸入工廠 module:callable（選填）：'), default = state.batch or '' }, function(batch)
      if batch == nil or state.closed then return end
      if state.busy or state.opts.project ~= setup_project or (state.change_epoch or 0) ~= setup_start_epoch
          or #dirty_buffers(setup_project) > 0 or select(2, project_config(setup_project)) ~= 'missing' then
        notify(tr('Project context changed; start setup again.', '项目上下文已变化，请重新接入。', '專案上下文已變更，請重新接入。'), vim.log.levels.WARN)
        return
      end
      local args = { 'init', '--model', model }
      if batch ~= '' then vim.list_extend(args, { '--batch', batch }) end
      local setup_epoch = state.change_epoch or 0
      local preview = vim.deepcopy(args)
      preview[#preview + 1] = '--dry-run'
      state.busy = tr('Planning project setup', '预览项目配置', '預覽專案設定')
      render(state)
      request(state, preview, function(report, err, stderr)
        state.busy = nil
        if state.closed or state.opts.project ~= setup_project or (state.change_epoch or 0) ~= setup_epoch then
          render(state)
          notify(tr('Context changed; prepare project setup again.', '上下文已变化，请重新准备项目接入。', '上下文已變更，請重新準備專案接入。'), vim.log.levels.WARN)
          return
        end
        state.last = { report = report, transport_error = err, stderr = stderr }
        render(state)
        local data = report and report.data
        local config = type(data) == 'table' and data.config or nil
        if err or not report or report.operation ~= 'init' or report.status ~= 'success'
            or type(data) ~= 'table' or data.committed ~= false or type(config) ~= 'table'
            or not sha256(data.config_revision)
            or config.model ~= model or (batch ~= '' and config.batch ~= batch)
            or (batch == '' and config.batch ~= vim.NIL and config.batch ~= nil) then
          notify('Project setup preview is unavailable; no files were changed.', vim.log.levels.ERROR)
          show_report(state)
          return
        end
        local inspected, config_text = pcall(vim.inspect, config)
        if not inspected or not reviewable_text(config_text) then
          notify(tr('Configuration preview is too large to approve here.', '配置预览过大，当前界面不能批准。', '設定預覽過大，目前介面不能批准。'), vim.log.levels.WARN)
          show_report(state); return
        end
        local review_buf = show_report(state)
        review_gate(review_buf, { tr('Cancel', '取消', '取消'), tr('Save setup', '保存配置', '儲存設定') },
          tr('Save the reviewed project setup?', '保存已查看的项目配置？', '儲存已檢視的專案設定？'), function(_, index)
          if index ~= 2 or state.closed then return end
          if state.busy or state.opts.project ~= setup_project or (state.change_epoch or 0) ~= setup_epoch or #dirty_buffers(state.opts.project) > 0 or select(2, project_config(state.opts.project)) ~= 'missing' then
            notify(tr('Project changed; create a new setup preview.', '项目已变化，请重新预览配置。', '專案已變更，請重新預覽設定。'), vim.log.levels.WARN)
            return
          end
          local tracked = begin_tracked_commit(state, tr('Save project setup', '保存项目配置', '儲存專案設定'))
          if not tracked then return end
          state.busy = tr('Saving project setup', '保存项目配置', '儲存專案設定')
          render(state)
          request(state, args, function(receipt, failure, output)
            state.busy = nil
            local same_context = tracked_commit_current(state, tracked)
            if same_context then state.last = { report = receipt, transport_error = failure, stderr = output } end
            local verified = not failure and receipt and receipt.operation == 'init' and receipt.status == 'success'
                and type(receipt.data) == 'table' and receipt.data.committed == true
                and receipt.data.config_revision == data.config_revision
                and type(receipt.data.config) == 'table' and receipt.data.config.model == model
                and ((batch ~= '' and receipt.data.config.batch == batch)
                  or (batch == '' and (receipt.data.config.batch == nil or receipt.data.config.batch == vim.NIL)))
            local settled = settle_tracked_commit(state, tracked, verified, failure)
            if not same_context then render(state); notify_tracked_context_changed(tracked); return end
            if verified and settled then
              switch_factory(state, 'model', nil)
              switch_factory(state, 'batch', nil)
              state.change_epoch = (state.change_epoch or 0) + 1
              state.result_label = tr('project configured; forward not run', '项目已配置；尚未运行前向', '專案已設定；尚未執行前向')
            elseif failure and failure.operation_started == false and settled then
              state.result_label = tr('project setup did not start', '项目配置未启动', '專案設定未啟動')
            else
              state.result_label = tr('setup outcome requires inspection before retry', '配置结果待核查；重试前请检查', '設定結果待核查；重試前請檢查')
            end
            show_report(state)
            refresh_project(state, function()
              if verified and settled and on_saved and not state.closed and state.opts.project == setup_project and state.opts.cli == setup_cli
                  and state.project_info and state.project_info.config_revision == data.config_revision
                  and state.project_info.model == model and project_config_current(state) then on_saved(model) end
            end)
          end)
        end)
      end)
    end)
  end)
end

local function create_model(state, draft)
  local updating = draft and draft.base_revision
  if state.busy then
    notify('Model-Maven: wait for the current operation.', vim.log.levels.WARN)
    return
  end
  if #dirty_buffers(state.opts.project) > 0 then
    notify(tr('Save project buffers before planning project creation.', '规划创建前请先保存项目中的修改。', '規劃建立前請先儲存專案中的修改。'), vim.log.levels.WARN)
    return
  end
  local function can_plan()
    local _, status = project_config(state.opts.project)
    return status == 'missing' or (updating and status == 'present' and project_config_current(state))
  end
  if not can_plan() then
    notify('This project has a configuration or its state is unknown; creation will not overwrite it.', vim.log.levels.WARN)
    return
  end
  local creation_project, creation_epoch = state.opts.project, state.change_epoch or 0
  local function prepare(first, second, outputs)
      if not first or first == '' or second == nil or outputs == nil or state.closed then return end
      local args = { 'scaffold', '--input', first }
      if draft then
        args[#args + 1] = '--write-recipe'
        if updating then vim.list_extend(args, { '--update-recipe', updating }) end
        if draft.reconcile_assembly then args[#args + 1] = '--reconcile-assembly' end
        if draft.training then vim.list_extend(args, { '--training-profile', vim.json.encode(draft.training) }) end
        if draft.supervision then vim.list_extend(args, { '--supervision-ref', vim.json.encode(draft.supervision) }) end
        if draft.data then
          if draft.data.binding then vim.list_extend(args, { '--batch-binding', draft.data.binding }) end
          for _, name in ipairs(vim.fn.sort(vim.tbl_keys(draft.data.params or {}))) do
            vim.list_extend(args, { '--batch-param', name .. '=' .. vim.json.encode(draft.data.params[name]) })
          end
        end
        for _, field in ipairs({ {'routes', '--route'}, {'components', '--inject'} }) do
          for _, slot in ipairs(vim.fn.sort(vim.tbl_keys(draft[field[1]]))) do
            vim.list_extend(args, {field[2], slot .. '=' .. draft[field[1]][slot]})
          end
        end
        for _, slot in ipairs(vim.fn.sort(vim.tbl_keys(draft.encoder_layers))) do
          vim.list_extend(args, { '--encoder-layers', slot .. '=' .. vim.json.encode(draft.encoder_layers[slot]) })
        end
        for _, slot in ipairs(vim.fn.sort(vim.tbl_keys(draft.encoder_widths))) do
          vim.list_extend(args, { '--encoder-width', slot .. '=' .. tostring(draft.encoder_widths[slot]) })
        end
        for _, slot in ipairs(draft.native_encoders) do
          vim.list_extend(args, { '--native-encoder', slot })
        end
        for _, slot in ipairs(vim.fn.sort(vim.tbl_keys(draft.component_params))) do
          vim.list_extend(args, { '--component-params-slot', slot })
          for _, name in ipairs(vim.fn.sort(vim.tbl_keys(draft.component_params[slot]))) do
            vim.list_extend(args, { '--inject-param', slot .. '.' .. name .. '=' .. vim.json.encode(draft.component_params[slot][name]) })
          end
        end
      end
      for _, input in ipairs(vim.split(second, ';', { plain = true, trimempty = true })) do
        input = vim.trim(input)
        if input ~= '' then vim.list_extend(args, { '--input', input }) end
      end
      for _, output in ipairs(vim.split(outputs, ';', { plain = true, trimempty = true })) do
        output = vim.trim(output)
        if output ~= '' then vim.list_extend(args, { '--output', output }) end
      end
      local function inputs_match_plan(planned)
        if type(planned) ~= 'table' or not is_list(planned) then return false end
        local expected = {}
        for index, value in ipairs(args) do
          if value == '--input' then
            local spec = args[index + 1]
            if type(spec) ~= 'string' then return false end
            local typed, dimensions = spec:match('^([^=]+)=(.+)$')
            if not typed or not dimensions then return false end
            local name, dtype = typed:match('^([^:]+):([^:]+)$')
            if not name then
              if typed:find(':', 1, true) then return false end
              name = typed
            end
            local shape, axes = {}, {}
            for axis, part in ipairs(vim.split(dimensions, ',', { plain = true })) do
              if part:sub(1, 1) == '?' then axes[#axes + 1], part = axis - 1, part:sub(2) end
              if not part:match('^%d+$') or not tonumber(part) then return false end
              shape[#shape + 1] = tonumber(part)
            end
            expected[#expected + 1] = { name = name, dtype = dtype, shape = shape, axes = axes }
          end
        end
        if #expected ~= #planned then return false end
        for index, input in ipairs(expected) do
          local item = planned[index]
          local actual_dtype = type(item) == 'table' and item.dtype or nil
          if actual_dtype == vim.NIL then actual_dtype = nil end
          if type(item) ~= 'table' or item.name ~= input.name or actual_dtype ~= input.dtype
              or not vim.deep_equal(item.shape, input.shape) or not vim.deep_equal(item.dynamic_axes, input.axes)
              or (not input.dtype and item.dtype_source ~= 'pytorch_default_at_batch_execution') then return false end
        end
        return true
      end
      local function named_outputs_match_plan(planned)
        local expected = {}
        for index, value in ipairs(args) do
          if value == '--output' then
            local spec = args[index + 1]
            if type(spec) ~= 'string' then return false end
            local name, raw = spec:match('^([^=]+)=(.+)$')
            if not name then return false end
            local descriptor, weight = raw:match('^([^@]+)@(.+)$')
            if not descriptor then descriptor, weight = raw, '1' end
            local width, objective = descriptor:match('^([^:]+):(.+)$')
            if not width then width, objective = descriptor, 'mse' end
            if objective == 'ce' then objective = 'cross_entropy' end
            if not width:match('^%d+$') or not tonumber(width) or not tonumber(weight) then return false end
            expected[#expected + 1] = { name = name, features = tonumber(width),
              objective = objective, weight = tonumber(weight) }
          end
        end
        if #expected == 0 then return type(planned) == 'table' and planned.kind ~= 'named' end
        if type(planned) ~= 'table' or planned.kind ~= 'named' or type(planned.heads) ~= 'table'
            or not is_list(planned.heads) or #planned.heads ~= #expected then return false end
        for index, output in ipairs(expected) do
          local head = planned.heads[index]
          if type(head) ~= 'table' or head.name ~= output.name or head.features ~= output.features
              or head.objective ~= output.objective or head.weight ~= output.weight then return false end
        end
        return true
      end
      local requested_binding, requested_batch_params, requested_output_dim, requested_loss
      local function plan_creation(module, batch)
      if state.closed or state.busy or state.opts.project ~= creation_project
          or (state.change_epoch or 0) ~= creation_epoch or #dirty_buffers(creation_project) > 0
          or not can_plan() then
        notify(tr('Project context changed; start model creation again.', '项目上下文已变化，请重新创建模型。', '專案上下文已變更，請重新建立模型。'), vim.log.levels.WARN)
        return
      end
      if module ~= '' then vim.list_extend(args, { '--module', module }) end
      if draft and draft.data then batch = draft.data.factory end
      if batch ~= '' then vim.list_extend(args, { '--batch', batch }) end
      state.busy = tr('Checking project creation capability', '检查项目创建能力', '檢查專案建立能力')
      render(state)
      request(state, { '--describe-interface' }, function(interface, err)
        if err or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
            or type(interface.data) ~= 'table' or type(interface.data.capabilities) ~= 'table'
            or interface.data.capabilities['project.custom_scaffold'] ~= true then
          state.busy = nil
          render(state)
          notify('Model-Maven: this CLI cannot safely create a model, or its capability report is invalid.', vim.log.levels.ERROR)
          return
        end
        if draft and (interface.data.capabilities['project.scaffold_recipe_v1'] ~= true
            or (updating and interface.data.capabilities['project.scaffold_recipe_update_v1'] ~= true)
            or ((next(draft.routes) or next(draft.components))
              and interface.data.capabilities['project.scaffold_recipe_assembly_v1'] ~= true)
            or (next(draft.encoder_layers)
              and interface.data.capabilities['project.scaffold_recipe_encoder_layers_v1'] ~= true)
            or (vim.iter(vim.tbl_values(draft.encoder_layers)):any(function(layers)
              return vim.iter(layers):any(function(layer) return layer.type == 'factory' end)
            end) and interface.data.capabilities['project.scaffold_recipe_factory_layers_v1'] ~= true)
            or (next(draft.encoder_widths)
              and interface.data.capabilities['project.scaffold_recipe_encoder_widths_v1'] ~= true)
            or (#draft.native_encoders > 0
              and interface.data.capabilities['project.scaffold_recipe_native_encoders_v1'] ~= true)
            or (next(draft.component_params)
              and interface.data.capabilities['project.scaffold_recipe_component_params_v1'] ~= true)
            or (draft.data and interface.data.capabilities['project.scaffold_recipe_data_v1'] ~= true)
            or (draft.training and interface.data.capabilities['project.scaffold_recipe_training_v1'] ~= true)
            or (draft.training and draft.training.optimizer and interface.data.capabilities['project.scaffold_recipe_optimizer_v1'] ~= true)
            or (draft.supervision and interface.data.capabilities['project.scaffold_recipe_supervision_ref_v1'] ~= true)
            or (draft.reconcile_assembly and interface.data.capabilities['project.scaffold_reconcile_assembly_v1'] ~= true)) then
          state.busy = nil; render(state)
          notify(tr('Update the CLI to generate model-maven.json, or use Advanced setup.',
            '请更新 CLI 以生成 model-maven.json，也可以使用高级创建选项。',
            '請更新 CLI 以產生 model-maven.json，也可以使用進階建立選項。'), vim.log.levels.WARN)
          return
        end
        local needs_default_dtype, needs_rank8, needs_unicode_inputs = false, false, false
        if requested_binding == 'single-raw' and interface.data.capabilities['data.raw_batch_binding_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot save whole-result binding. Update it before creating the project.',
            '当前 CLI 无法保存整体返回值绑定，请更新后再创建项目。', '目前 CLI 無法儲存整體回傳值繫結，請更新後再建立專案。'), vim.log.levels.WARN)
          return
        end
        local input_count, output_count = 0, 0
        for index, value in ipairs(args) do
          if value == '--input' and type(args[index + 1]) == 'string' then
            input_count = input_count + 1
            local name = args[index + 1]:match('^([^=]+)=')
            local input_name = name and name:match('^([^:]+)')
            if input_name and input_name:find('[\128-\255]') then needs_unicode_inputs = true end
            if name and not name:find(':', 1, true) then needs_default_dtype = true end
            local dimensions = args[index + 1]:match('^[^=]+=(.+)$')
            if dimensions and #vim.split(dimensions, ',', { plain = true }) > 4 then needs_rank8 = true end
          elseif value == '--output' then
            output_count = output_count + 1
          end
        end
        if needs_rank8 and interface.data.capabilities['project.scaffold_rank8_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot scaffold inputs with more than four dimensions. Use a compatible CLI or write your own model.',
            '此 CLI 不能创建超过四维的输入。请使用兼容的 CLI 或自行编写模型。',
            '此 CLI 不能建立超過四維的輸入。請使用相容的 CLI 或自行編寫模型。'), vim.log.levels.WARN)
          return
        end
        if (input_count > 8 or output_count > 8)
            and interface.data.capabilities['project.scaffold_32_inputs_outputs_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot create more than eight inputs or outputs. Use a compatible CLI or start with user code.',
            '此 CLI 不能创建超过八个输入或输出。请使用兼容的 CLI 或从用户代码开始。',
            '此 CLI 不能建立超過八個輸入或輸出。請使用相容的 CLI 或從使用者程式碼開始。'), vim.log.levels.WARN)
          return
        end
        if (needs_unicode_inputs or outputs:find('[\128-\255]'))
            and interface.data.capabilities['project.scaffold_nfkc_collision_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot check Unicode normalization collisions. Update it before creating this model.',
            '此 CLI 无法检查 Unicode 规范化后的名称冲突；请更新后再创建模型。',
            '此 CLI 無法檢查 Unicode 正規化後的名稱衝突；請更新後再建立模型。'), vim.log.levels.WARN)
          return
        end
        if outputs:find('[\128-\255]') and interface.data.capabilities['project.scaffold_unicode_outputs_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot create Unicode output names. Update it or use ASCII names.',
            '当前 CLI 不支持 Unicode 输出名；请更新或使用 ASCII 名称。', '目前 CLI 不支援 Unicode 輸出名稱；請更新或使用 ASCII 名稱。'), vim.log.levels.WARN)
          return
        end
        if needs_unicode_inputs and interface.data.capabilities['project.scaffold_unicode_inputs_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot create Unicode input names. Update it or use ASCII names.',
            '当前 CLI 不支持 Unicode 输入名；请更新或使用 ASCII 名称。', '目前 CLI 不支援 Unicode 輸入名稱；請更新或使用 ASCII 名稱。'), vim.log.levels.WARN)
          return
        end
        if needs_default_dtype and interface.data.capabilities['project.scaffold_default_dtype_v1'] ~= true then
          state.busy = nil; render(state)
          notify(tr('This CLI cannot guarantee runtime default input dtype. Specify a dtype or use a compatible CLI.',
            '此 CLI 无法保证使用运行时默认输入 dtype。请明确指定 dtype 或使用兼容的 CLI。',
            '此 CLI 無法保證使用執行時預設輸入 dtype。請明確指定 dtype 或使用相容的 CLI。'), vim.log.levels.WARN)
          return
        end
        state.busy = tr('Planning model creation', '规划模型创建', '規劃模型建立')
        render(state)
        request(state, args, function(report, problem, stderr)
          state.busy = nil
          if state.closed or state.opts.project ~= creation_project or (state.change_epoch or 0) ~= creation_epoch then
            render(state)
            notify(tr('Context changed; plan model creation again.', '上下文已变化，请重新规划模型创建。', '上下文已變更，請重新規劃模型建立。'), vim.log.levels.WARN)
            return
          end
          state.last = { report = report, transport_error = problem, stderr = stderr,
            selected_scaffold_layer = draft and draft.selected_layer_id or nil }
          render(state)
          local function reopen_draft()
            if draft and not state.closed and state.opts.project == creation_project
                and (state.change_epoch or 0) == creation_epoch then open_model_builder(state) end
          end
          local function show_failed_review()
            local buf = show_report(state)
            if not draft or not buf then return end
            local back = tr('  ← Edit model and retry [n]', '  ← 返回画布修改 [n]', '  ← 返回畫布修改 [n]')
            vim.bo[buf].modifiable = true
            vim.api.nvim_buf_set_lines(buf, 0, 0, false, { back, '' })
            vim.bo[buf].modifiable = false
            vim.api.nvim_buf_set_extmark(buf, builder_buttons, 0, 0, { line_hl_group = 'PmenuSel' })
            local function resume()
              if vim.api.nvim_get_current_buf() ~= buf then return end
              vim.api.nvim_win_close(0, false)
              reopen_draft()
            end
            vim.keymap.set('n', 'n', resume, { buffer = buf, silent = true })
            vim.keymap.set('n', '<LeftMouse>', function()
              local mouse = vim.fn.getmousepos()
              if mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= buf
                  or mouse.line ~= 1 or mouse.column > #back then return '<LeftMouse>' end
              vim.schedule(resume)
              return '<Ignore>'
            end, { buffer = buf, expr = true, silent = true })
          end
          if problem or not report or report.status ~= 'success' or report.operation ~= 'scaffold'
              or type(report.data) ~= 'table' or report.data.committed ~= false
              or type(report.data.plan) ~= 'table' or type(report.data.plan_revision) ~= 'string'
              or not reviewable_text(report.data.plan.source) or report.data.plan.source == ''
              or not report.data.plan_revision:match('^%x+$') or #report.data.plan_revision ~= 64 then
            notify('Model-Maven: creation plan unavailable; nothing was created.', vim.log.levels.ERROR)
            show_failed_review()
            return
          end
          local setup_ok, setup_text = pcall(vim.inspect, { files = report.data.plan.files, inputs = report.data.plan.inputs,
            output = report.data.plan.output, routes = report.data.plan.routes, batch_source = report.data.plan.batch_source,
            starter_step = report.data.plan.starter_step, config = report.data.plan.config, recipe = report.data.plan.recipe })
          local current_config = updating and project_config(creation_project) or nil
          local retained_input = updating and report.data.plan.batch_source == 'existing'
            and type(current_config) == 'table'
            and report.data.plan.config.batch == current_config.batch
            and vim.deep_equal(report.data.plan.config.batch_binding, current_config.batch_binding)
            and vim.deep_equal(report.data.plan.config.batch_params, current_config.batch_params)
            and type(report.data.plan.update) == 'table'
            and report.data.plan.update.previous_batch == current_config.batch
          if not setup_ok or not reviewable_text(setup_text) or type(report.data.plan.config) ~= 'table'
              or (draft and (type(report.data.plan.recipe) ~= 'table' or report.data.plan.recipe.version ~= 1
                or not vim.deep_equal(draft.routes, report.data.plan.recipe.routes or {})
                or not vim.deep_equal(draft.components, report.data.plan.recipe.components or {})
                or not vim.deep_equal(draft.encoder_layers, report.data.plan.recipe.encoder_layers or {})
                or not vim.deep_equal(draft.encoder_widths, report.data.plan.recipe.encoder_widths or {})
                or not vim.deep_equal(draft.native_encoders, report.data.plan.recipe.native_encoders or {})
                or not vim.deep_equal(draft.component_params, report.data.plan.recipe.component_params or {})
                or (draft.data and (type(report.data.plan.recipe.data) ~= 'table'
                  or draft.data.factory ~= report.data.plan.recipe.data.factory
                  or draft.data.binding ~= report.data.plan.recipe.data.binding
                  or not vim.deep_equal(draft.data.params or {}, report.data.plan.recipe.data.params or {})))
                or (not draft.data and report.data.plan.recipe.data ~= nil)
                or (draft.training and (type(report.data.plan.recipe.training) ~= 'table'
                  or draft.training.mode ~= report.data.plan.recipe.training.mode
                  or draft.training.entry ~= report.data.plan.recipe.training.entry
                  or not vim.deep_equal(draft.training.params or {}, report.data.plan.recipe.training.params or {})
                  or not vim.deep_equal(draft.training.optimizer, report.data.plan.recipe.training.optimizer)))
                or (not draft.training and report.data.plan.recipe.training ~= nil)
                or not vim.deep_equal(draft.supervision, report.data.plan.recipe.supervision)
                or type(report.data.plan.files) ~= 'table' or not vim.tbl_contains(report.data.plan.files, 'model-maven.json')))
              or (updating and (type(report.data.plan.update) ~= 'table' or report.data.plan.update.recipe_revision ~= updating))
              or not inputs_match_plan(report.data.plan.inputs)
              or not named_outputs_match_plan(report.data.plan.output)
              or (not retained_input and report.data.plan.batch_source ~= (batch ~= '' and 'external' or 'synthetic'))
              or (batch ~= '' and report.data.plan.config.batch ~= batch)
              or (requested_binding and report.data.plan.config.batch_binding ~= requested_binding)
              or (requested_output_dim and (type(report.data.plan.output) ~= 'table' or report.data.plan.output.features ~= requested_output_dim))
              or (requested_loss and (type(report.data.plan.output) ~= 'table' or report.data.plan.output.objective ~= requested_loss)) then
            notify(tr('The creation plan does not match the selections or cannot be reviewed.',
              '创建计划与所选配置不一致或无法查看。', '建立計畫與所選設定不一致或無法檢視。'), vim.log.levels.ERROR)
            show_failed_review(); return
          end
          if requested_batch_params then
            local planned_params = report.data.plan.config.batch_params
            for name, value in pairs(requested_batch_params) do
              if type(planned_params) ~= 'table' or not vim.deep_equal(planned_params[name], value) then
                notify(tr('The planned input parameters differ or are redacted; review and replan without sensitive values.',
                  '计划中的输入参数不一致或已脱敏；请检查并避免填写敏感值。',
                  '計畫中的輸入參數不一致或已遮蔽；請檢查並避免填入敏感值。'), vim.log.levels.WARN)
                show_report(state); return
              end
            end
          end
          local revision = report.data.plan_revision
          local project = state.opts.project
          local planned_files = vim.deepcopy(report.data.plan.files)
          local planned_step, planned_model = report.data.plan.starter_step, report.data.plan.config.model
          local source_map = report.data.plan.layer_source_locations
          local selected_layer = draft and draft.selected_layer_id
          local planned_location
          if type(source_map) == 'table' and source_map.scope == 'proposed_generated_default_encoders_only'
              and type(report.data.plan.source) == 'string' and source_map.source_sha256 == vim.fn.sha256(report.data.plan.source)
              and type(source_map.locations) == 'table' and type(selected_layer) == 'string' then
            local item = source_map.locations[selected_layer]
            if type(item) == 'table' and type(item.line) == 'number' and item.line % 1 == 0 and item.line >= 1
                and item.line <= #vim.split(report.data.plan.source, '\n', {plain = true}) then
              planned_location = {digest = source_map.source_sha256, line = item.line}
            end
          end
          local prior_source = type(report.data.plan.update) == 'table' and report.data.plan.update.previous_source or nil
          local planned_inputs = {}
          if type(report.data.plan.inputs) == 'table' and is_list(report.data.plan.inputs) then
            for _, input in ipairs(report.data.plan.inputs) do
              if type(input) == 'table' and identifier_candidate(input.name) then planned_inputs[#planned_inputs + 1] = input.name end
            end
          end
          local planned_slots, seen_slots = {}, {}
          local function remember_slot(slot)
            if identifier_candidate(slot) and not seen_slots[slot] and #planned_slots < 34 then
              planned_slots[#planned_slots + 1], seen_slots[slot] = slot, true
            end
          end
          if type(report.data.plan.inputs) == 'table' and is_list(report.data.plan.inputs) then
            for _, input in ipairs(report.data.plan.inputs) do
              if type(input) == 'table' then remember_slot(input.encoder_slot) end
            end
          end
          if type(report.data.plan.slots) == 'table' and is_list(report.data.plan.slots) then
            for _, slot in ipairs(report.data.plan.slots) do remember_slot(slot) end
          end
          local review_buf = show_report(state)
          review_gate(review_buf, { tr('Cancel', '取消', '取消'), tr('Create files', '创建文件', '建立檔案') },
            tr('Create the reviewed files?', '创建已查看的文件？', '建立已檢視的檔案？'), function(_, index)
            if index ~= 2 or state.closed then return end
            if state.busy or state.opts.project ~= creation_project or (state.change_epoch or 0) ~= creation_epoch
                or #dirty_buffers(state.opts.project) > 0 or not can_plan() then
              notify(tr('Project changed or contains unsaved buffers; create a new plan.', '项目已变化或有未保存内容，请重新规划。', '專案已變更或有未儲存內容，請重新規劃。'), vim.log.levels.WARN)
              return
            end
            local commit = vim.deepcopy(args)
            vim.list_extend(commit, { '--apply', '--if-plan', revision })
            local tracked = begin_tracked_commit(state, tr('Create model files', '创建模型文件', '建立模型檔案'))
            if not tracked then return end
            state.busy = tr('Creating model files', '创建模型文件', '建立模型檔案')
            render(state)
            request(state, commit, function(receipt, failure, output)
              state.busy = nil
              local same_context = tracked_commit_current(state, tracked)
              if same_context then state.last = { report = receipt, transport_error = failure, stderr = output } end
              local created = not failure and receipt and receipt.status == 'success' and receipt.operation == 'scaffold'
                  and type(receipt.data) == 'table' and receipt.data.committed == true
                  and (not updating or receipt.data.updated == true)
                  and receipt.data.plan_revision == revision
                  and receipt.data.model == planned_model and vim.deep_equal(receipt.data.files, planned_files)
              local settled = settle_tracked_commit(state, tracked, created, failure)
              if not same_context then render(state); notify_tracked_context_changed(tracked); return end
              created = created and settled
              if created then
                state.builder_draft = nil
                state.result_label = updating
                  and tr('new build active; forward not run', '新构建已激活；尚未运行前向', '新建置已啟用；尚未執行前向')
                  or tr('model created; forward not run', '模型已创建；尚未运行前向', '模型已建立；尚未執行前向')
                state.change_epoch = (state.change_epoch or 0) + 1
                state.journey = nil
                if type(planned_model) == 'string' and type(planned_step) == 'string'
                    and receipt.data.model == planned_model and receipt.data.starter_step == planned_step then
                  state.starter_step = { model = planned_model, step = planned_step }
                  state.starter_slots = { model = planned_model, slots = planned_slots, inputs = planned_inputs }
                else
                  state.starter_step = nil
                  state.starter_slots = nil
                end
              elseif failure and failure.operation_started == false and settled then
                state.result_label = tr('model creation did not start', '模型创建未启动', '模型建立未啟動')
              else
                state.result_label = tr('creation outcome requires inspection before retry', '创建结果待核查；重试前请检查文件', '建立結果待核查；重試前請檢查檔案')
              end
              local _, _, created_config_digest = project_config(project)
              refresh_project(state)
              local result_buf = show_report(state)
              local creation_result = state.last
              if not result_buf or not vim.api.nvim_buf_is_valid(result_buf) then
                if created then
                  notify(tr('Model files were created. Return to the workspace, use o to open the source or p for the first forward.',
                    '模型文件已创建。返回工作区后可按 o 打开源码，或按 p 执行首次前向。',
                    '模型檔案已建立。返回工作區後可按 o 開啟原始碼，或按 p 執行首次前向。'), vim.log.levels.INFO)
                else
                  notify(tr('Creation outcome needs inspection before retry; use r to reopen the report.',
                    '重试前请核查创建结果；可按 r 重新打开报告。', '重試前請核查建立結果；可按 r 重新開啟報告。'), vim.log.levels.WARN)
                end
                return
              end
              local relative = type(planned_files) == 'table' and planned_files[1] or nil
              if created and type(receipt.data.files) == 'table' and vim.deep_equal(planned_files, receipt.data.files)
                  and type(relative) == 'string' and relative:match('%.py$') then
                local next_steps = {
                  tr('  → Run the first forward pass [p]', '  → 运行首次前向 [p]', '  → 執行首次前向 [p]'),
                  tr('  ◇ Connect CSV data [Y]', '  ◇ 接入 CSV 数据 [Y]', '  ◇ 接入 CSV 資料 [Y]'),
                  tr('  ◇ Continue editing the canvas [n]', '  ◇ 继续编辑画布 [n]', '  ◇ 繼續編輯畫布 [n]'),
                  planned_location and tr('  ↗ Open selected layer in generated Python [e]', '  ↗ 在生成的 Python 中打开所选层 [e]', '  ↗ 在產生的 Python 中開啟所選層 [e]')
                    or tr('  ↗ Open generated Python [e]', '  ↗ 打开生成的 Python [e]', '  ↗ 開啟產生的 Python [e]'),
                  tr('  ◇ Capture input and run forward [1]', '  ◇ 捕获输入并运行前向 [1]', '  ◇ 擷取輸入並執行前向 [1]'),
                }
                local has_replay = state.canvas_snapshot and state.canvas_snapshot.project == project
                if has_replay then
                  next_steps[#next_steps + 1] = tr('  ↻ Replay captured input [2]', '  ↻ 重放已捕获输入 [2]', '  ↻ 重播已擷取輸入 [2]')
                end
                if draft and draft.supervision then
                  next_steps[#next_steps + 1] = tr('  → Import referenced supervision [5]', '  → 导入引用的监督 [5]', '  → 匯入參照的監督 [5]')
                end
                local can_compare_source = type(prior_source) == 'table' and prior_source.status == 'different'
                  and type(prior_source.file) == 'string' and prior_source.file:match('^[%w_]+%.py$')
                  and relative:match('^[%w_]+%.py$') and prior_source.file ~= relative
                if can_compare_source then
                  next_steps[#next_steps + 1] = tr('  ⇄ Compare and merge source edits [d]', '  ⇄ 对照并合并源码改动 [d]', '  ⇄ 對照並合併原始碼變更 [d]')
                end
                vim.bo[result_buf].modifiable = true
                vim.api.nvim_buf_set_lines(result_buf, 0, 0, false, vim.list_extend(vim.deepcopy(next_steps), {
                  tr('The starter input is synthetic unless you supplied your own batch.',
                    '除非提供了自己的批次，否则骨架使用合成输入。', '除非提供了自己的批次，否則骨架使用合成輸入。'),
                  '',
                }))
                vim.bo[result_buf].modifiable = false
                local function open_generated_source()
                  if state.closed or state.opts.project ~= project then return end
                  local path = vim.uv.fs_realpath(project .. '/' .. relative)
                  if not path or not in_project(project, path) or vim.fn.filereadable(path) ~= 1 then
                    notify(tr('The created source is no longer available in this project.',
                      '创建的源码已不在此项目中或不可读取。', '建立的原始碼已不在此專案中或無法讀取。'), vim.log.levels.WARN)
                    return
                  end
                  if planned_location then
                    open_verified_implementation(state, {path = '', source = relative, digest = planned_location.digest,
                      line = planned_location.line, location_kind = 'generated'})
                  else focus_source(state, path) end
                end
                local function check_forward()
                  local _, _, current_digest = project_config(project)
                  if state.closed or state.opts.project ~= project or state.last ~= creation_result
                      or not created_config_digest or current_digest ~= created_config_digest
                      or (state.model and state.model ~= receipt.data.model)
                      or (state.batch and state.batch ~= receipt.data.batch) then
                    notify(tr('The creation result is no longer current; return to the workspace.',
                      '创建结果已过期，请返回工作区。', '建立結果已過期，請返回工作區。'), vim.log.levels.WARN); return
                  end
                  if state.project_status ~= 'configured' or not state.project_info then
                    notify(tr('Project configuration is still being checked; wait or refresh it in the workspace.',
                      '项目配置仍在检查或不可用；请等待或在工作区刷新。', '專案設定仍在檢查或無法使用；請等待或在工作區重新整理。'), vim.log.levels.INFO); return
                  end
                  run(state, tr('Run forward pass', '执行前向', '執行前向'), { 'model', 'probe' }, nil, nil, false, nil, nil, true)
                end
                local function return_to_canvas()
                  if state.closed or state.opts.project ~= project or state.last ~= creation_result then return end
                  vim.api.nvim_win_close(0, false)
                  open_model_builder(state)
                end
                local function connect_data()
                  if state.closed or state.opts.project ~= project or state.last ~= creation_result
                      or not state.actions or not state.actions.Y then return end
                  vim.api.nvim_win_close(0, false)
                  state.actions.Y()
                end
                local actions = { check_forward, connect_data, return_to_canvas, open_generated_source,
                  function() if not state.closed and state.last == creation_result then capture_canvas_forward(state) end end }
                local keys = { 'p', 'Y', 'n', 'e', '1' }
                if has_replay then
                  actions[#actions + 1] = function() if not state.closed and state.last == creation_result then replay_canvas_forward(state) end end
                  keys[#keys + 1] = '2'
                end
                if draft and draft.supervision then
                  actions[#actions + 1] = function()
                    if state.closed or state.last ~= creation_result or not state.actions or not state.actions['5'] then return end
                    vim.api.nvim_win_close(0, false)
                    state.actions['5']()
                  end
                  keys[#keys + 1] = '5'
                end
                if can_compare_source then
                  actions[#actions + 1] = function()
                    if state.closed or state.opts.project ~= project or state.last ~= creation_result then return end
                    local old = vim.uv.fs_realpath(project .. '/' .. prior_source.file)
                    local new = vim.uv.fs_realpath(project .. '/' .. relative)
                    if not old or not new or not in_project(project, old) or not in_project(project, new)
                        or vim.fn.filereadable(old) ~= 1 or vim.fn.filereadable(new) ~= 1 then
                      notify(tr('Source files are no longer available in this project.', '项目中的源码文件已不可用。', '專案中的原始碼檔案已無法使用。'), vim.log.levels.WARN); return
                    end
                    local ok = pcall(function()
                      vim.cmd({ cmd = 'tabnew', args = { old } })
                      vim.cmd('diffthis')
                      vim.cmd({ cmd = 'diffsplit', args = { new }, mods = { vertical = true } })
                    end)
                    if ok then
                      notify(tr('Use ]c / [c to navigate; do copies a change into the new file. Save and run forward after reviewing.',
                        '用 ]c / [c 跳转差异；在新文件中按 do 可复制旧文件的改动。审核、保存后再运行前向。',
                        '用 ]c / [c 跳轉差異；在新檔案中按 do 可複製舊檔案的變更。檢視、儲存後再執行前向。'), vim.log.levels.INFO)
                    else notify(tr('Could not open the source comparison.', '无法打开源码对照。', '無法開啟原始碼對照。'), vim.log.levels.ERROR) end
                  end
                  keys[#keys + 1] = 'd'
                end
                for i, key in ipairs(keys) do
                  vim.keymap.set('n', key, actions[i], { buffer = result_buf, silent = true, desc = next_steps[i] })
                  vim.api.nvim_buf_set_extmark(result_buf, builder_buttons, i - 1, 0,
                    { line_hl_group = i == 1 and 'PmenuSel' or 'Pmenu' })
                end
                vim.keymap.set('n', '<CR>', function()
                  local action = actions[vim.api.nvim_win_get_cursor(0)[1]]
                  if action then action() end
                end, { buffer = result_buf, silent = true })
                for _, mouse_key in ipairs({ '<LeftMouse>', '<2-LeftMouse>', '<3-LeftMouse>', '<4-LeftMouse>' }) do
                  vim.keymap.set('n', mouse_key, function()
                    local mouse = vim.fn.getmousepos()
                    local action = actions[mouse.line]
                    if mouse.winid == 0 or vim.api.nvim_win_get_buf(mouse.winid) ~= result_buf
                        or not action or mouse.column > #next_steps[mouse.line] then return mouse_key end
                    vim.schedule(function()
                      if vim.api.nvim_get_current_buf() == result_buf then action() end
                    end)
                    return '<Ignore>'
                  end, { buffer = result_buf, expr = true, silent = true })
                end
              end
            end)
          end, draft and function() vim.schedule(reopen_draft) end or nil, updating and 'update' or draft ~= nil)
        end)
      end)
      end
      local function choose_start()
      vim.ui.select({
        tr('Starter + synthetic input', '默认模块与合成输入', '預設模組與合成輸入'),
        tr('Choose module or input factory', '选择模块或已有输入工厂', '選擇模組或現有輸入工廠'),
      }, { prompt = tr('Choose a starting point:', '选择起点：', '選擇起點：') }, function(_, choice)
        if not choice or state.closed then return end
        if choice == 1 then plan_creation('', ''); return end
        vim.ui.input({ prompt = tr('New Python module (empty = starter default): ', '新建 Python 模块（留空使用默认值）：', '新建 Python 模組（留空使用預設值）：') }, function(module)
          if module == nil or state.closed then return end
          vim.ui.input({ prompt = tr('Existing input factory module:callable (empty = synthetic): ',
            '已有输入工厂 module:callable（留空使用合成输入）：', '現有輸入工廠 module:callable（留空使用合成輸入）：') }, function(batch)
            if batch == nil or state.closed then return end
            batch = vim.trim(batch)
            if batch == '' then plan_creation(vim.trim(module), batch); return end
            local bindings = { 'auto', 'single', 'args', 'kwargs', 'envelope', 'single-raw' }
            vim.ui.select({ tr('Automatic binding', '自动绑定', '自動繫結'), 'single', 'args', 'kwargs', 'envelope', 'single-raw' }, {
              prompt = tr('How does this factory provide model inputs?', '该工厂如何提供模型输入？', '此工廠如何提供模型輸入？'),
            }, function(_, binding_index)
              if not binding_index or state.closed then return end
              requested_binding = bindings[binding_index] ~= 'auto' and bindings[binding_index] or nil
              vim.ui.input({ prompt = tr('Input factory parameters as JSON object (saved locally; no secrets): ',
                '输入工厂参数 JSON 对象（保存在本地；不要填写密钥）：', '輸入工廠參數 JSON 物件（儲存在本機；不要填寫金鑰）：'), default = '{}' }, function(raw)
                if not raw or state.closed then return end
                local ok, params = pcall(vim.json.decode, raw)
                if #raw > 16384 or not ok or type(params) ~= 'table' or not raw:match('^%s*{') then
                  notify(tr('Enter a JSON object up to 16 KiB.', '请输入不超过 16 KiB 的 JSON 对象。', '請輸入不超過 16 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
                end
                local names = vim.tbl_keys(params)
                table.sort(names)
                if #names > 64 then notify(tr('At most 64 parameters are supported.', '最多支持 64 个参数。', '最多支援 64 個參數。'), vim.log.levels.WARN); return end
                for _, name in ipairs(names) do
                  if not parameter_name_candidate(name) then
                    notify(tr('Invalid input parameter name.', '输入参数名无效。', '輸入參數名稱無效。'), vim.log.levels.WARN); return
                  end
                  local encoded, value = pcall(vim.json.encode, params[name])
                  if not encoded then notify(tr('Cannot encode input parameter.', '无法编码输入参数。', '無法編碼輸入參數。'), vim.log.levels.WARN); return end
                  vim.list_extend(args, { '--batch-param', name .. '=' .. value })
                end
                if requested_binding then vim.list_extend(args, { '--batch-binding', requested_binding }) end
                requested_batch_params = params
                plan_creation(vim.trim(module), batch)
              end)
            end)
          end)
        end)
      end)
      end
      if draft then plan_creation('', ''); return end
      if vim.tbl_contains(args, '--output') then
        choose_start()
      else
        vim.ui.input({ prompt = tr('Single-output feature count (empty = fused width): ',
          '单输出特征数（留空使用融合宽度）：', '單一輸出特徵數（留空使用融合寬度）：') }, function(raw_width)
          if raw_width == nil or state.closed then return end
          local width = vim.trim(raw_width)
          if width ~= '' and (not width:match('^%d+$') or not tonumber(width) or tonumber(width) < 1 or tonumber(width) > 65536) then
            notify(tr('Output feature count must be 1–65536.', '输出特征数必须为 1–65536。', '輸出特徵數必須為 1–65536。'), vim.log.levels.WARN); return
          end
          vim.ui.select({ tr('Regression example (MSE)', '回归示例（MSE）', '迴歸範例（MSE）'),
            tr('Classification example (cross entropy)', '分类示例（交叉熵）', '分類範例（交叉熵）') }, {
            prompt = tr('Choose the editable example loss:', '选择可编辑的示例损失：', '選擇可編輯的範例損失：'),
          }, function(_, choice)
            if not choice or state.closed then return end
            if choice == 2 and width ~= '' and tonumber(width) < 2 then
              notify(tr('Cross entropy needs at least two output classes.', '交叉熵需要至少两个输出类别。', '交叉熵需要至少兩個輸出類別。'), vim.log.levels.WARN); return
            end
            if width ~= '' then requested_output_dim = tonumber(width); vim.list_extend(args, { '--output-dim', width }) end
            if choice == 2 then requested_loss = 'cross_entropy'; vim.list_extend(args, { '--loss', requested_loss }) end
            choose_start()
          end)
        end)
      end
  end
  if draft then
    prepare(draft.inputs[1], table.concat(draft.inputs, ';', 2), table.concat(draft.outputs, ';'))
    return
  end
  vim.ui.input({ prompt = tr('Input (e.g. image=3,224,224): ',
    '输入（如 image=3,224,224）：', '輸入（如 image=3,224,224）：') }, function(first)
    if not first or first == '' then return end
    vim.ui.input({ prompt = tr('More inputs (;, optional): ', '其他输入（; 分隔，选填）：', '其他輸入（; 分隔，選填）：') }, function(second)
      if second == nil or state.closed then return end
      vim.ui.input({ prompt = tr('Outputs (; e.g. score=1): ', '输出（; 分隔，如 score=1）：', '輸出（; 分隔，如 score=1）：') }, function(outputs)
      if outputs == nil or state.closed then return end
      prepare(first, second, outputs)
      end)
    end)
  end)
end

sessions.create_image_project = function(state)
  local project, cli, epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
  local python, directory = state.opts.python, state.opts.working_directory
  local import_roots, paths_override = vim.deepcopy(state.opts.project_import_roots), state.opts.runtime_paths_override
  local function stable()
    local _, status = project_config(project)
    return not state.closed and state.opts.project == project and state.opts.cli == cli
      and state.opts.python == python and state.opts.working_directory == directory
      and state.opts.runtime_paths_override == paths_override and vim.deep_equal(state.opts.project_import_roots, import_roots)
      and (state.change_epoch or 0) == epoch and status == 'missing'
  end
  if state.busy or not stable() or #dirty_buffers(project) > 0 then
    notify(tr('Open an unconfigured project and save project buffers first.', '请打开未配置的项目并先保存项目缓冲区。', '請開啟未設定的專案並先儲存專案緩衝區。'), vim.log.levels.WARN); return
  end
  state.busy = tr('Finding image presets', '查找图像预设', '尋找影像預設'); render(state)
  request(state, { '--describe-interface' }, function(interface, error)
    if error or not stable() or not interface or interface.status ~= 'success' or interface.operation ~= 'interface'
        or type(interface.data) ~= 'table' or type(interface.data.capabilities) ~= 'table'
        or interface.data.capabilities['project.classification_create'] ~= true
        or type(interface.data.classification_create_presets) ~= 'table' or not is_list(interface.data.classification_create_presets) then
      state.busy = nil; render(state)
      notify(tr('This CLI cannot discover image-project presets.', '当前 CLI 无法发现图像项目预设。', '目前 CLI 無法探索影像專案預設。'), vim.log.levels.WARN); return
    end
    local allowed = {}
    for _, id in ipairs(interface.data.classification_create_presets) do
      if type(id) == 'string' and #id <= 80 and id:match('^[%w_-]+$') then allowed[id] = true end
    end
    request(state, { 'data', 'presets' }, function(catalog, failure)
      state.busy = nil; render(state)
      if failure or not stable() or not catalog or catalog.operation ~= 'preset_catalog' or catalog.status ~= 'success'
          or type(catalog.data) ~= 'table' or type(catalog.data.presets) ~= 'table' then
        notify(tr('Image preset catalog is unavailable in the selected environment.', '所选环境中的图像预设目录不可用。', '所選環境中的影像預設目錄無法使用。'), vim.log.levels.WARN); return
      end
      local ids, labels = {}, {}
      for _, id in ipairs(vim.fn.sort(vim.tbl_keys(allowed))) do
        local preset = catalog.data.presets[id]
        if type(preset) == 'table' and preset.task == 'image-classification' then
          local shape = type(preset.default_input) == 'table' and preset.default_input or {}
          ids[#ids + 1] = id
          labels[#labels + 1] = id .. ' · ' .. tostring(shape.channels or '?') .. ' × '
            .. tostring(shape.height or '?') .. ' × ' .. tostring(shape.width or '?')
        end
      end
      if #ids == 0 then notify(tr('No supported image-project preset was found.', '没有找到可创建的图像项目预设。', '沒有找到可建立的影像專案預設。'), vim.log.levels.INFO); return end
      vim.ui.select(labels, { prompt = tr('Choose an image model', '选择图像模型', '選擇影像模型') }, function(_, selected)
        local preset = selected and ids[selected]
        if not preset or not stable() then return end
        vim.ui.input({ prompt = tr('Class-folder dataset directory: ', '按类别分目录的图像数据路径：', '依類別分目錄的影像資料路徑：'), completion = 'dir' }, function(path)
          if not path or path == '' or path:find('[%c]') or not stable() then return end
          vim.ui.select({ tr('Continue', '继续', '繼續'), tr('Cancel', '取消', '取消') }, {
            prompt = tr('Preview checks class folders; some presets import the selected Python environment. Weights are not downloaded.',
              '预览检查类别目录；部分预设会导入所选 Python 环境，不会下载权重。',
              '預覽檢查類別目錄；部分預設會匯入所選 Python 環境，不會下載權重。'),
          }, function(_, choice)
            if choice ~= 1 or not stable() then return end
            local args = { 'create', '--preset', preset, '--data', path }
            state.busy = tr('Planning image project', '规划图像项目', '規劃影像專案'); render(state)
            request(state, args, function(plan, problem, stderr)
              state.busy = nil
              if not stable() then render(state); return end
              state.last = { report = plan, transport_error = problem, stderr = stderr }
              state.result_label = problem and tr('CLI error', 'CLI 错误', 'CLI 錯誤') or (plan and plan.status or 'unknown')
              render(state)
              local buf = show_report(state)
              local data = plan and plan.data
              if problem or not plan or plan.operation ~= 'create' or plan.status ~= 'success' or type(data) ~= 'table'
                  or data.committed ~= false or not sha256(data.plan_revision) or type(data.plan) ~= 'table'
                  or data.plan.preset ~= preset or type(data.plan.classes) ~= 'table' or not is_list(data.plan.classes)
                  or type(data.plan.files) ~= 'table' or not is_list(data.plan.files)
                  or type(data.plan.source) ~= 'string' or not reviewable_text(data.plan.source) then return end
              local displayed = state.last
              local review_window = buf and vim.fn.bufwinid(buf) or -1
              if review_window ~= -1 and vim.api.nvim_win_is_valid(review_window) then
                pcall(vim.api.nvim_win_set_height, review_window, math.max(8, math.floor(vim.o.lines * 0.65)))
              end
              if buf and vim.api.nvim_buf_is_valid(buf) then
                local names = {}
                for index, name in ipairs(data.plan.classes) do
                  if index > 3 then break end
                  names[#names + 1] = vim.fn.strcharpart(tostring(name):gsub('[%c]', ' '), 0, 48)
                end
                local clean_preset = vim.fn.strcharpart(preset:gsub('[%c]', ' '), 0, 80)
                local clean_path = vim.fn.strcharpart(tostring(data.plan.data_root or path):gsub('[%c]', ' '), 0, 200)
                vim.bo[buf].modifiable = true
                vim.api.nvim_buf_set_lines(buf, 0, 0, false, {
                  tr('Model: ', '模型：', '模型：') .. clean_preset,
                  tr('Image folder: ', '图像目录：', '影像目錄：') .. clean_path,
                  tr('Classes: ', '类别：', '類別：') .. table.concat(names, ', ')
                    .. (#data.plan.classes > #names and (' … (' .. #data.plan.classes .. ')') or ''),
                  '',
                })
                vim.bo[buf].modifiable = false
              end
              review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Create project', '创建项目', '建立專案') },
                tr('Create this image project?', '创建此图像项目？', '建立此影像專案？'), function(_, accepted)
                if accepted ~= 2 or not stable() or state.last ~= displayed or #dirty_buffers(project) > 0 then return end
                local tracked = begin_tracked_commit(state, tr('Create image project', '创建图像项目', '建立影像專案'))
                if not tracked then return end
                local apply = vim.deepcopy(args); vim.list_extend(apply, { '--apply', '--if-plan', data.plan_revision })
                state.busy = tr('Creating image project', '创建图像项目', '建立影像專案'); render(state)
                request(state, apply, function(receipt, apply_error, apply_stderr)
                  state.busy = nil
                  local created = receipt and receipt.operation == 'create' and receipt.status == 'success'
                    and type(receipt.data) == 'table' and receipt.data.committed == true
                    and receipt.data.plan_revision == data.plan_revision and vim.deep_equal(receipt.data.files, data.plan.files)
                    and receipt.data.model == 'classification:model' and receipt.data.batch == 'classification:batch'
                  local settled = settle_tracked_commit(state, tracked, created, apply_error)
                  if state.closed or state.opts.project ~= project then notify_tracked_context_changed(tracked); return end
                  created = created and settled
                  state.last = { report = receipt, transport_error = apply_error, stderr = apply_stderr }
                  if created then
                    state.builder_draft = nil
                    state.change_epoch = (state.change_epoch or 0) + 1
                    state.journey = nil
                    state.starter_step = { model = receipt.data.model, step = 'classification:step' }
                    state.result_label = tr('image project created; preview input', '图像项目已创建；请预览输入', '影像專案已建立；請預覽輸入')
                  else state.result_label = tr('creation outcome needs inspection', '创建结果需要核查', '建立結果需要核查') end
                  refresh_project(state); render(state); show_report(state)
                end, nil, false, function() return stable() and #dirty_buffers(project) == 0 end)
              end, nil, true)
            end)
          end)
        end)
      end)
    end)
  end)
end

sessions.sync_scaffold_declaration = function(state, kind)
  if state.closed or state.busy or not project_config_current(state) then return end
  local project, cli, epoch = state.opts.project, state.opts.cli, state.change_epoch or 0
  local info = state.project_info
  local builder = require('model_maven.model_builder')
  local saved, error = builder.load(project)
  if error or not saved or saved.kind == 'image_classification' or not info or not sha256(info.config_revision)
      or (state.model and state.model ~= info.model) then
    notify(tr('Open the saved canvas model with its project configuration first.', '请先打开使用项目配置的已保存画布模型。', '請先開啟使用專案設定的已儲存畫布模型。'), vim.log.levels.WARN); return
  end
  local previous = state.last_training_entry
  local profile
  if kind == 'training' then
    if not previous or previous.project ~= project or previous.model ~= (state.model or info.model)
        or previous.config_revision ~= info.config_revision or type(previous.params) ~= 'string' then
      notify(tr('Prepare training settings in this project first.', '请先在当前项目准备训练设置。', '請先在目前專案準備訓練設定。'), vim.log.levels.WARN); return
    end
    local ok, params = pcall(vim.json.decode, previous.params)
    if not ok or type(params) ~= 'table' then notify(tr('Training parameters are unavailable.', '训练参数不可用。', '訓練參數無法使用。'), vim.log.levels.WARN); return end
    local entry = previous.value
    local module = type(info.model) == 'string' and info.model:match('^(.+):model$') or nil
    if previous.mode ~= 'external-loop' and module and entry == module .. ':step' then entry = '$model:step' end
    local optimizer, chosen = nil, state.last_training_optimizer
    if previous.mode ~= 'external-loop' and chosen and chosen.project == project and chosen.model == previous.model
        and chosen.mode == previous.mode and chosen.entry == previous.value and chosen.revision == previous.config_revision
        and chosen.cli == cli and chosen.python == state.opts.python then
      optimizer = optimizer_profile(chosen.args)
      if not optimizer then notify(tr('Optimizer settings cannot be saved.', '无法保存优化器设置。', '無法儲存最佳化器設定。'), vim.log.levels.WARN); return end
      if not next(optimizer) then optimizer = nil end
    elseif previous.mode ~= 'external-loop' and saved.training and saved.training.entry == entry then
      optimizer = vim.deepcopy(saved.training.optimizer)
    end
    profile = { mode = previous.mode, entry = entry, params = next(params) and params or vim.empty_dict(), optimizer = optimizer }
  elseif kind ~= 'data' then return end
  local previous_snapshot = kind == 'training' and vim.deepcopy(previous) or nil
  local optimizer_snapshot = kind == 'training' and vim.deepcopy(state.last_training_optimizer) or nil
  local revision, config_revision, python = saved.base_revision, info.config_revision, state.opts.python
  local roots, directory, override = vim.deepcopy(state.opts.project_import_roots), state.opts.working_directory, state.opts.runtime_paths_override
  local function current()
    if state.closed or state.opts.project ~= project or state.opts.cli ~= cli or state.opts.python ~= python
        or state.opts.working_directory ~= directory or state.opts.runtime_paths_override ~= override
        or not vim.deep_equal(state.opts.project_import_roots, roots) or (state.change_epoch or 0) ~= epoch
        or not state.project_info or state.project_info.config_revision ~= config_revision or not project_config_current(state)
        or (state.model and state.model ~= state.project_info.model) or #dirty_buffers(project) > 0 then return false end
    local latest = builder.load(project)
    return latest and latest.base_revision == revision and latest.kind ~= 'image_classification'
      and (kind ~= 'training' or (vim.deep_equal(state.last_training_entry, previous_snapshot)
        and vim.deep_equal(state.last_training_optimizer, optimizer_snapshot)))
  end
  if not current() then notify(tr('Save project buffers and reopen this action.', '请保存项目缓冲区后重新操作。', '請儲存專案緩衝區後重新操作。'), vim.log.levels.WARN); return end
  local args = { 'recipe-sync', '--if-recipe', revision, '--if-config-revision', config_revision }
  if kind == 'data' then args[#args + 1] = '--data'
  else vim.list_extend(args, { '--training-profile', vim.json.encode(profile) }) end
  state.busy = tr('Planning declaration sync', '规划声明同步', '規劃宣告同步'); render(state)
  request(state, args, function(report, problem, stderr)
    state.busy = nil
    if not current() then render(state); return end
    state.last = { report = report, transport_error = problem, stderr = stderr }; render(state)
    local data = report and report.data
    local review = show_report(state)
    if problem or not report or report.operation ~= 'recipe_sync' or report.status ~= 'success'
        or type(data) ~= 'table' or data.committed ~= false or not sha256(data.plan_revision)
        or type(data.plan) ~= 'table' or data.plan.recipe_revision ~= revision or data.plan.config_revision ~= config_revision
        or data.plan.sync_data ~= (kind == 'data') or data.plan.sync_training ~= (kind == 'training')
        or type(data.redacted_fields) ~= 'table' or #data.redacted_fields > 0 then
      notify(tr('The declaration preview could not be fully reviewed; nothing was saved.', '声明预览无法完整审核，未保存。', '宣告預覽無法完整檢視，未儲存。'), vim.log.levels.WARN); return
    end
    local ok, text = pcall(vim.inspect, data.plan)
    if not ok or not reviewable_text(text) then notify(tr('The declaration preview is too large to review here.', '声明预览过大，无法在此审核。', '宣告預覽過大，無法在此檢視。'), vim.log.levels.WARN); return end
    local displayed = state.last
    review_gate(review, { tr('Cancel', '取消', '取消'), tr('Save declaration', '保存声明', '儲存宣告') },
      tr('Save the reviewed declaration without rebuilding?', '不重建模型，保存已审核的声明？', '不重建模型，儲存已檢視的宣告？'), function(_, accepted)
      if accepted ~= 2 or not current() or state.last ~= displayed then return end
      local tracked = begin_tracked_commit(state, tr('Sync model declaration', '同步模型声明', '同步模型宣告'))
      if not tracked then return end
      local apply = vim.deepcopy(args); vim.list_extend(apply, { '--apply', '--if-plan', data.plan_revision })
      state.busy = tr('Saving model declaration', '保存模型声明', '儲存模型宣告'); render(state)
      request(state, apply, function(receipt, failure, output)
        state.busy = nil
        local result = receipt and receipt.data
        local latest = builder.load(project)
        local verified = not failure and receipt and receipt.operation == 'recipe_sync' and receipt.status == 'success'
          and type(result) == 'table' and result.committed == true and result.plan_revision == data.plan_revision
          and result.config_revision == config_revision and sha256(result.recipe_revision)
          and result.sync_data == (kind == 'data') and result.sync_training == (kind == 'training')
          and latest and latest.base_revision == result.recipe_revision
        local settled = settle_tracked_commit(state, tracked, verified, failure)
        if state.closed or state.opts.project ~= project then notify_tracked_context_changed(tracked); return end
        state.last = { report = receipt, transport_error = failure, stderr = output }
        if verified and settled then
          local draft = state.builder_draft
          if draft and draft.base_revision == revision then
            if kind == 'data' and vim.deep_equal(draft.data, saved.data) then draft.data = vim.deepcopy(latest.data) end
            if kind == 'training' and vim.deep_equal(draft.training, saved.training) then draft.training = vim.deepcopy(latest.training) end
            draft.base_revision = latest.base_revision
          end
          state.change_epoch = (state.change_epoch or 0) + 1
          state.result_label = tr('declaration saved; model unchanged', '声明已保存；模型未变', '宣告已儲存；模型未變')
        else state.result_label = tr('declaration outcome requires inspection', '声明保存结果需要核查', '宣告儲存結果需要核查') end
        refresh_project(state); render(state); show_report(state)
      end, nil, false, current)
    end, nil, true)
  end)
end

-- One graph canvas lives in this workspace; graph drafts are separate from the
-- scaffold declaration until the unified representation is implemented.
local function package_project(state, mode, base, stable, callback)
  local project = state.opts.project
  local declaration = mode == 'graph' and 'model-graph.json' or 'model-maven.json'
  local function fail(message) notify(message, vim.log.levels.WARN) end
        if not stable() then return fail(tr('Save the declaration before packaging.', '打包前请保存声明。', '打包前請儲存宣告。')) end
        vim.ui.input({prompt = tr('New package directory: ', '新项目包目录：', '新專案包目錄：'), default = 'model-maven-bundle'}, function(output)
          if not output or not stable() then return end
          if #output > 128 or output == '.' or output == '..' or not output:match('^[%w_.-]+$') then
            return fail(tr('Choose a new directory name in the project root.', '请选择项目根目录中的新目录名。', '請選擇專案根目錄中的新目錄名稱。'))
          end
          local includes, choose = {}, nil
          local function plan()
            if not stable() then return fail(tr('Declaration changed; save and try again.', '声明已变化，请保存后重试。', '宣告已變更，請儲存後重試。')) end
            local args = {'recipe-bundle', '--' .. mode, '--output', output}
            for _, path in ipairs(includes) do vim.list_extend(args, {'--include', path}) end
            state.busy = tr('Planning project package', '规划项目包', '規劃專案包'); render(state)
            request(state, args, function(result, error, stderr)
              state.busy = nil; render(state)
              if not stable() then return end
              state.last = {report = result, transport_error = error, stderr = stderr}
              local review, data = show_report(state), result and result.data
              if error or not result or result.operation ~= 'recipe_bundle' or result.status ~= 'success'
                  or type(data) ~= 'table' or data.committed ~= false or not sha256(data.plan_revision)
                  or type(data.plan) ~= 'table' or data.plan.kind ~= mode or data.plan.output ~= output
                  or not vim.deep_equal(data.plan.includes, includes) or type(data.plan.files) ~= 'table'
                  or type(data.plan.files[declaration]) ~= 'table'
                  or data.plan.files[declaration][2] ~= base then return end
              local displayed = state.last
              review_gate(review, {tr('Cancel', '取消', '取消'), tr('Create package', '创建文件包', '建立檔案包')},
                tr('Copy the reviewed files to a new directory?', '将审核过的文件复制到新目录？', '將檢視過的檔案複製到新目錄？'), function(_, choice)
                  if choice ~= 2 or not stable() or state.last ~= displayed then return end
                  local tracked = begin_tracked_commit(state, tr('Create project package', '创建项目包', '建立專案包'))
                  if not tracked then return end
                  local apply = vim.deepcopy(args); vim.list_extend(apply, {'--apply', '--if-plan', data.plan_revision})
                  state.busy = tr('Creating project package', '创建项目包', '建立專案包'); render(state)
                  request(state, apply, function(receipt, problem, output_text)
                    state.busy = nil
                    local created = receipt and receipt.operation == 'recipe_bundle' and receipt.status == 'success'
                      and type(receipt.data) == 'table' and receipt.data.committed == true and receipt.data.plan_revision == data.plan_revision
                    local settled = settle_tracked_commit(state, tracked, created, problem)
                    if state.closed or state.opts.project ~= project then return notify_tracked_context_changed(tracked) end
                    state.last = {report = receipt, transport_error = problem, stderr = output_text}
                    if created and settled and callback then callback(tr('Project package created.', '项目包已创建。', '專案包已建立。')) end
                    render(state); show_report(state)
                  end, nil, false, stable)
                end, nil, true)
            end)
          end
          choose = function()
            if not stable() then return end
            vim.ui.select({tr('Add project file or directory', '添加项目文件或目录', '新增專案檔案或目錄'),
              tr('Choose discovered files', '选择发现的文件', '選擇探索到的檔案'),
              tr('Remove a selected path', '移除已选路径', '移除已選路徑'), tr('Review package', '审核文件包', '檢視檔案包'), tr('Cancel', '取消', '取消')}, {
                prompt = tr('Selected: ', '已选择：', '已選擇：') .. (#includes > 0 and table.concat(includes, ', ') or tr('none', '无', '無'))
                  .. tr(' · saved declaration included; add source, data and environment explicitly', ' · 已包含保存的声明；请自行选择源码、数据和环境', ' · 已包含儲存的宣告；請自行選擇原始碼、資料和環境'),
              }, function(_, action)
                if not action or not stable() then return end
                if action == 1 then
                  vim.ui.input({prompt = tr('Project-relative path: ', '项目内相对路径：', '專案內相對路徑：'), completion = 'file'}, function(path)
                    if not path or not stable() then return end
                    if path ~= '' and #includes < 128 then includes[#includes + 1] = path end
                    choose()
                  end)
                elseif action == 2 then
                  local args = {'discover'}
                  for _, root in ipairs(state.opts.project_import_roots or {}) do vim.list_extend(args, {'--import-root', root}) end
                  state.busy = tr('Discovering project files', '查找项目文件', '尋找專案檔案'); render(state)
                  request(state, args, function(found, error)
                    state.busy = nil; render(state)
                    if not stable() then return end
                    local data = found and found.data
                    if error or not found or found.status ~= 'success' or found.operation ~= 'project_discover' or type(data) ~= 'table'
                        or type(data.source_files) ~= 'table' or not is_list(data.source_files)
                        or type(data.environment_candidates) ~= 'table' or not is_list(data.environment_candidates) then
                      fail(tr('Discovery unavailable; add paths manually.', '无法发现文件；请手动添加路径。', '無法探索檔案；請手動新增路徑。')); return choose()
                    end
                    local paths, labels, seen = {}, {}, {}
                    local observed = {}
                    for _, entry in ipairs(state.observations or {}) do
                      if entry.project == project and not entry.stale_on_arrival and type(entry.observed_sources) == 'table' then
                        for path in pairs(entry.observed_sources) do if type(path) == 'string' then observed[#observed + 1] = path end end
                      end
                    end
                    table.sort(observed)
                    for _, group in ipairs({
                      {observed, tr('Previously observed source (may have changed)', '曾观察到的源码（可能已变化）', '曾觀察到的原始碼（可能已變更）')},
                      {(state.project_info and state.project_info.project_import_roots) or {}, tr('Configured import directory', '已配置的模块目录', '已設定的模組目錄')},
                      {data.source_files, tr('Static source candidate', '静态源码候选', '靜態原始碼候選')},
                      {data.environment_candidates, tr('Possible environment file', '可能的环境文件', '可能的環境檔案')},
                    }) do
                      for _, path in ipairs(group[1]) do
                        if type(path) == 'string' and #path <= 1024 and not path:find('[%c]') and not seen[path]
                            and path:sub(1, 1) ~= '@' and not vim.startswith(path, '/')
                            and not vim.tbl_contains(includes, path) and path ~= declaration then
                          paths[#paths + 1], labels[#labels + 1], seen[path] = path, group[2] .. ' · ' .. path, true
                        end
                      end
                    end
                    if #paths == 0 then fail(tr('No additional candidates.', '没有其他候选文件。', '沒有其他候選檔案。')); return choose() end
                    vim.ui.select(labels, {prompt = tr('Suggestions are incomplete; observed files may have changed.', '候选可能不完整，已观察文件也可能变化。', '候選可能不完整，已觀察檔案也可能變更。')}, function(_, index)
                      if not stable() then return end
                      if index and paths[index] and #includes < 128 then includes[#includes + 1] = paths[index] end
                      choose()
                    end)
                  end)
                elseif action == 3 then
                  if #includes == 0 then return choose() end
                  local listed = vim.deepcopy(includes)
                  vim.ui.select(listed, {prompt = tr('Choose a selected path to remove', '选择要移除的已选路径', '選擇要移除的已選路徑')}, function(_, index)
                    if not stable() or not index or not vim.deep_equal(includes, listed) then return end
                    table.remove(includes, index); choose()
                  end)
                elseif action == 4 then plan() end
              end)
          end
          choose()
        end)
end

sessions.open_graph_canvas = function(state, initial_graph)
  if state.closed or state.busy then return end
  local project, cli = state.opts.project, state.opts.cli
  local file_name, target = 'model-graph.json', state.opts.project .. '/model-graph.json'
  local function context()
    return not state.closed and not state.busy and state.opts.project == project and state.opts.cli == cli
  end
  local function fail(message) notify(message, vim.log.levels.WARN) end
  local function open_buffer_conflict()
    local normalized = vim.fs.normalize(vim.uv.fs_realpath(target) or target)
    for _, b in ipairs(vim.api.nvim_list_bufs()) do
      local name = vim.api.nvim_buf_get_name(b)
      if vim.api.nvim_buf_is_loaded(b) and name ~= ''
          and vim.fs.normalize(vim.uv.fs_realpath(name) or name) == normalized
          and (vim.bo[b].modified or vim.b[b].model_maven_reload_required) then return true end
    end
    return false
  end
  local function graph_id(value)
    return type(value) == 'string' and #value > 0 and #value <= 128
      and not value:find('[^A-Za-z0-9_%-\128-\255]') and pcall(vim.str_utfindex, value)
  end
  -- JSON null and an absent key are equivalent only for the backend's
  -- Option fields. Leave unknown keys and non-optional fields untouched so
  -- the normal version/field checks can refuse them without discarding data.
  local function normalize_graph_options(doc)
    if type(doc) ~= 'table' then return doc end
    local function clear_null(object, keys)
      if type(object) ~= 'table' then return end
      for _, key in ipairs(keys) do if object[key] == vim.NIL then object[key] = nil end end
    end
    clear_null(doc, {'component_storage', 'data', 'training', 'supervision', 'legacy_import'})
    clear_null(doc.data, {'binding'})
    clear_null(doc.training, {'mode', 'step', 'trial_steps', 'optimizer'})
    if type(doc.training) == 'table' then clear_null(doc.training.optimizer, {'factory', 'lr', 'weight_decay'}) end
    for _, node in ipairs(type(doc.nodes) == 'table' and doc.nodes or {}) do
      clear_null(node, {'label', 'definition', 'axis', 'call_style', 'output_style', 'output_name'})
      if type(node) == 'table' and type(node.draft_rules) == 'table' then
        for _, rules in pairs(node.draft_rules) do
          for _, rule in ipairs(type(rules) == 'table' and rules or {}) do clear_null(rule, {'min', 'max', 'weight'}) end
        end
      end
    end
    for _, definition in ipairs(type(doc.definitions) == 'table' and doc.definitions or {}) do clear_null(definition, {'children_style'}) end
    for _, group in ipairs(type(doc.groups) == 'table' and doc.groups or {}) do clear_null(group, {'parent'}) end
    return doc
  end
  local function readable_graph(doc)
    local function fields(value, allowed)
      if type(value) ~= 'table' then return false end
      for key in pairs(value) do if not allowed[key] then return false end end
      return true
    end
    if type(doc) ~= 'table' or doc.version ~= 1 or type(doc.nodes) ~= 'table' or not is_list(doc.nodes)
        or type(doc.edges) ~= 'table' or not is_list(doc.edges)
        or (doc.definitions ~= nil and (type(doc.definitions) ~= 'table' or not is_list(doc.definitions)))
        or (doc.objectives ~= nil and (type(doc.objectives) ~= 'table' or not is_list(doc.objectives)))
        or (doc.groups ~= nil and (type(doc.groups) ~= 'table' or not is_list(doc.groups)))
        or #doc.nodes > 512 or #doc.edges > 4096 or #(doc.definitions or {}) > 512 or #(doc.objectives or {}) > 64 or #(doc.groups or {}) > 512 then return false end
    if not fields(doc, {version=true, component_storage=true, definitions=true, objectives=true, data=true,
        training=true, supervision=true, legacy_import=true, groups=true, nodes=true, edges=true}) then return false end
    if doc.component_storage ~= nil and doc.component_storage ~= 'named' then return false end
    if doc.legacy_import ~= nil then
      local snapshot = doc.legacy_import
      if not fields(snapshot, {kind=true, sha256=true, content=true})
          or (snapshot.kind ~= 'scaffold' and snapshot.kind ~= 'image_classification')
          or not sha256(snapshot.sha256) or type(snapshot.content) ~= 'string' or #snapshot.content > 128 * 1024
          or vim.fn.sha256(snapshot.content) ~= snapshot.sha256 then return false end
      local ok = pcall(vim.json.decode, snapshot.content)
      if not ok then return false end
    end
    if doc.supervision ~= nil then
      local ref = doc.supervision
      if type(ref) ~= 'table' or vim.tbl_count(ref) ~= 2 or type(ref.file) ~= 'string' or ref.file == ''
          or #ref.file > 1024 or ref.file:find('[%c\\:]') or ref.file:sub(1, 1) == '/'
          or ref.file:match('^%./') or ref.file:match('/%./') or ref.file:match('/%.$')
          or ref.file:match('^%.%.$') or ref.file:match('^%.%./') or ref.file:match('/%.%./') or ref.file:match('/%.%.$')
          or not sha256(ref.sha256) then return false end
    end
    if doc.training ~= nil then
      local training = doc.training
      if type(training) ~= 'table' or (training.trial_steps ~= nil and (type(training.trial_steps) ~= 'number'
          or training.trial_steps % 1 ~= 0 or training.trial_steps < 1 or training.trial_steps > 1000))
          or (training.optimizer ~= nil and type(training.optimizer) ~= 'table') then return false end
      for key in pairs(training) do if not vim.tbl_contains({'trial_steps', 'optimizer', 'step', 'step_params', 'mode'}, key) then return false end end
      if training.mode ~= nil and not vim.tbl_contains({'managed-step', 'manual-step', 'external-loop'}, training.mode) then return false end
      if training.mode ~= nil and training.mode ~= 'managed-step' and training.step == nil then return false end
      if training.step ~= nil and (type(training.step) ~= 'string' or #training.step > 240
          or (training.step ~= '$model:step' and not training.step:match('^[^%s:]+:[^%s:]+$'))
          or (training.mode == 'external-loop' and training.step == '$model:step')) then return false end
      if training.step_params ~= nil then
        if type(training.step_params) ~= 'table' or (next(training.step_params) and is_list(training.step_params))
            or vim.tbl_count(training.step_params) > 64 then return false end
        for key in pairs(training.step_params) do if not identifier_candidate(key) then return false end end
        local ok, raw = pcall(vim.json.encode, training.step_params)
        if not ok or #raw > 65536 then return false end
      end
      local optimizer = training.optimizer or {}
      for key in pairs(optimizer) do if not vim.tbl_contains({'factory', 'params', 'lr', 'weight_decay'}, key) then return false end end
      if optimizer.factory ~= nil and (type(optimizer.factory) ~= 'string' or #optimizer.factory > 240
          or not optimizer.factory:match('^[^%s:]+:[^%s:]+$') or optimizer.lr ~= nil or optimizer.weight_decay ~= nil) then return false end
      if training.mode == 'manual-step' and optimizer.factory ~= nil then return false end
      if training.mode == 'external-loop' and next(optimizer) ~= nil then return false end
      if optimizer.params ~= nil then
        if type(optimizer.params) ~= 'table' or (next(optimizer.params) and is_list(optimizer.params)) or vim.tbl_count(optimizer.params) > 64 then return false end
        if optimizer.factory == nil and next(optimizer.params) then return false end
        for name in pairs(optimizer.params) do if not parameter_name_candidate(name) then return false end end
      end
      for _, key in ipairs({'lr', 'weight_decay'}) do
        local value = optimizer[key]
        if value ~= nil and (type(value) ~= 'number' or value ~= value or math.abs(value) == math.huge
            or (key == 'lr' and value <= 0) or (key == 'weight_decay' and value < 0)) then return false end
      end
    end
    for _, node in ipairs(doc.nodes) do
      if type(node) ~= 'table' or not graph_id(node.id) or not vim.tbl_contains({'input', 'call', 'cast', 'clone', 'mean_dynamic', 'assert_flat', 'assert_batch', 'after', 'add', 'concat', 'output'}, node.kind)
          or (node.definition ~= nil and not graph_id(node.definition))
          or (node.inputs ~= nil and (type(node.inputs) ~= 'table' or not is_list(node.inputs)))
          or (node.outputs ~= nil and (type(node.outputs) ~= 'table' or not is_list(node.outputs))) then return false end
      if not fields(node, {id=true, kind=true, label=true, definition=true, dtype_definitions=true, track_sequence=true, output_name=true, axis=true, axes=true, width=true, call_style=true,
          output_style=true, inputs=true, outputs=true, input_shapes=true, output_shapes=true,
          input_dtypes=true, output_dtypes=true, semantics=true, draft_rules=true}) then return false end
      if node.label ~= nil and node.label ~= vim.NIL and type(node.label) ~= 'string' then return false end
      if node.output_name ~= nil and (node.kind ~= 'output' or not graph_id(node.output_name)) then return false end
      for _, ports in ipairs({node.inputs or {}, node.outputs or {}}) do
        if #ports > 64 then return false end
        for _, port in ipairs(ports) do if not graph_id(port) then return false end end
      end
      if node.axis ~= nil and (type(node.axis) ~= 'number' or node.axis % 1 ~= 0
          or node.axis < -2147483648 or node.axis > 2147483647) then return false end
      if node.axes ~= nil then
        if type(node.axes) ~= 'table' or not is_list(node.axes) or #node.axes > 8
            or (node.kind ~= 'mean_dynamic' and #node.axes > 0) then return false end
        local seen = {}
        for _, axis in ipairs(node.axes) do
          if type(axis) ~= 'number' or axis % 1 ~= 0 or axis < 0 or axis > 7 or seen[axis] then return false end
          seen[axis] = true
        end
      end
      if node.kind == 'mean_dynamic' and (node.axes == nil or #node.axes == 0) then return false end
      if node.width ~= nil and (node.kind ~= 'assert_flat' or type(node.width) ~= 'number'
          or node.width % 1 ~= 0 or node.width < 1 or node.width > 65536) then return false end
      if node.kind == 'assert_flat' and node.width == nil then return false end
      if node.dtype_definitions ~= nil then
        if node.kind ~= 'cast' or type(node.dtype_definitions) ~= 'table' or not is_list(node.dtype_definitions)
            or #node.dtype_definitions > 64 or (node.definition ~= nil and #node.dtype_definitions > 0) then return false end
        local seen = {}
        for _, id in ipairs(node.dtype_definitions) do
          if not graph_id(id) or seen[id] then return false end
          seen[id] = true
        end
      end
      if node.track_sequence ~= nil and (type(node.track_sequence) ~= 'boolean'
          or (node.track_sequence and (node.kind ~= 'cast' or node.definition ~= nil))) then return false end
      if node.call_style ~= nil and (node.kind ~= 'call'
          or not vim.tbl_contains({'positional', 'keyword', 'list'}, node.call_style)) then return false end
      if node.output_style ~= nil and (node.kind ~= 'call'
          or not vim.tbl_contains({'mapping', 'sequence'}, node.output_style)) then return false end
      for _, field in ipairs({'input_dtypes', 'output_dtypes'}) do
        local dtypes = node[field]
        if dtypes ~= nil then
          if type(dtypes) ~= 'table' or (next(dtypes) and is_list(dtypes)) then return false end
          for port, dtype in pairs(dtypes) do
            if not graph_id(port) or type(dtype) ~= 'string' or #dtype > 64
                or not dtype:match('^[A-Za-z][A-Za-z0-9_]*$') then return false end
          end
        end
      end
      if node.semantics ~= nil then
        if not vim.tbl_contains({'input', 'output'}, node.kind) or type(node.semantics) ~= 'table'
            or (next(node.semantics) and is_list(node.semantics)) then return false end
        local ports = node.kind == 'input' and (node.outputs or {}) or (node.inputs or {})
        for port, label in pairs(node.semantics) do
          if not vim.tbl_contains(ports, port) or type(label) ~= 'string' or #label > 256
              or vim.trim(label) == '' or label:find('[%c]') then return false end
        end
      end
      if node.draft_rules ~= nil then
        if not vim.tbl_contains({'input', 'output'}, node.kind) or type(node.draft_rules) ~= 'table'
            or (next(node.draft_rules) and is_list(node.draft_rules)) then return false end
        local ports = node.kind == 'input' and (node.outputs or {}) or (node.inputs or {})
        for port, rules in pairs(node.draft_rules) do
          if not vim.tbl_contains(ports, port) or type(rules) ~= 'table' or not is_list(rules) or #rules == 0 or #rules > 32 then return false end
          for _, rule in ipairs(rules) do
            if type(rule) ~= 'table' or not vim.tbl_contains({'finite', 'range'}, rule.kind)
                or not vim.tbl_contains({'observe', 'require', 'penalty'}, rule.mode) then return false end
            for key, value in pairs(rule) do
              if not vim.tbl_contains({'kind', 'mode', 'min', 'max', 'weight'}, key) then return false end
              if key ~= 'kind' and key ~= 'mode' and (type(value) ~= 'number' or value ~= value or math.abs(value) == math.huge) then return false end
            end
            if rule.kind == 'finite' and (rule.min ~= nil or rule.max ~= nil or rule.mode == 'penalty') then return false end
            if rule.kind == 'range' and (rule.min == nil and rule.max == nil or rule.min and rule.max and rule.min > rule.max) then return false end
            if rule.mode == 'penalty' and (not rule.weight or rule.weight <= 0) or rule.mode ~= 'penalty' and rule.weight ~= nil then return false end
          end
        end
      end
      for _, key in ipairs({'input_shapes', 'output_shapes'}) do
        local shapes = node[key]
        if shapes ~= nil then
          if type(shapes) ~= 'table' or (next(shapes) and is_list(shapes)) then return false end
          for name, shape in pairs(shapes) do
            if not graph_id(name) or type(shape) ~= 'table' or not is_list(shape) or #shape > 16 then return false end
            for _, dim in ipairs(shape) do
              if dim ~= vim.NIL and (type(dim) ~= 'number' or dim % 1 ~= 0 or dim < 1 or dim > 1000000000000) then return false end
            end
          end
        end
      end
    end
    for _, edge in ipairs(doc.edges) do
      if type(edge) ~= 'table' or type(edge.from) ~= 'table' or type(edge.to) ~= 'table'
          or not graph_id(edge.from.node) or not graph_id(edge.from.port)
          or not graph_id(edge.to.node) or not graph_id(edge.to.port) then return false end
      if not fields(edge, {from=true, to=true}) or not fields(edge.from, {node=true, port=true})
          or not fields(edge.to, {node=true, port=true}) then return false end
    end
    for _, def in ipairs(doc.definitions or {}) do
      if type(def) ~= 'table' or not graph_id(def.id) or type(def.factory) ~= 'string'
          or #def.factory > 240 or def.factory:find('[%c]')
          or (def.params ~= nil and (type(def.params) ~= 'table' or (next(def.params) and is_list(def.params)))) then return false end
      if not fields(def, {id=true, factory=true, params=true, children=true, children_style=true}) then return false end
      if def.children_style ~= nil and def.children_style ~= 'list' then return false end
      if def.children ~= nil then
        if type(def.children) ~= 'table' or not is_list(def.children) or #def.children > 64 then return false end
        for _, id in ipairs(def.children) do if not graph_id(id) then return false end end
      end
      for key in pairs(def.params or {}) do if type(key) ~= 'string' then return false end end
    end
    for _, objective in ipairs(doc.objectives or {}) do
      if type(objective) ~= 'table' or not graph_id(objective.output) or not graph_id(objective.target)
          or type(objective.loss) ~= 'string' or #objective.loss > 240 or type(objective.weight) ~= 'number'
          or objective.weight ~= objective.weight or objective.weight == math.huge or objective.weight < 0 then return false end
      if not fields(objective, {output=true, target=true, loss=true, weight=true}) then return false end
    end
    local group_parents = {}
    for _, group in ipairs(doc.groups or {}) do
      if type(group) ~= 'table' or not graph_id(group.id) or type(group.nodes) ~= 'table'
          or not is_list(group.nodes) or #group.nodes > 512 or group_parents[group.id] ~= nil
          or (group.parent ~= nil and not graph_id(group.parent)) then return false end
      if not fields(group, {id=true, parent=true, nodes=true}) then return false end
      group_parents[group.id] = group.parent or false
      for _, id in ipairs(group.nodes) do if not graph_id(id) then return false end end
    end
    for id in pairs(group_parents) do
      local visited, current = {[id] = true}, group_parents[id]
      while current do
        if visited[current] or group_parents[current] == nil then return false end
        visited[current], current = true, group_parents[current]
      end
    end
    if doc.data ~= nil and (type(doc.data) ~= 'table' or type(doc.data.factory) ~= 'string'
        or #doc.data.factory > 240 or (doc.data.binding ~= nil and type(doc.data.binding) ~= 'string')
        or (doc.data.params ~= nil and (type(doc.data.params) ~= 'table' or (next(doc.data.params) and is_list(doc.data.params))))) then return false end
    if doc.data ~= nil and not fields(doc.data, {factory=true, binding=true, params=true}) then return false end
    return true
  end
  local function recoverable_history(history, graph)
    if type(history) ~= 'table' or not vim.deep_equal(history.document, graph)
        or type(history.undo) ~= 'table' or not is_list(history.undo) or #history.undo > 8
        or type(history.redo) ~= 'table' or not is_list(history.redo) or #history.redo > 8 then return false end
    local function valid_layout(order, positions)
      if type(order) ~= 'table' or not is_list(order) or #order > 512
          or type(positions) ~= 'table' or vim.tbl_count(positions) > 512 then return false end
      local seen = {}
      for _, id in ipairs(order) do if not graph_id(id) or seen[id] then return false end; seen[id] = true end
      for id, point in pairs(positions) do
        if not graph_id(id) or type(point) ~= 'table' or type(point.x) ~= 'number' or type(point.y) ~= 'number'
            or point.x % 1 ~= 0 or point.y % 1 ~= 0 or point.x < 0 or point.y < 0 or point.x > 2048 or point.y > 2048
            or vim.tbl_count(point) ~= 2 then return false end
      end
      return true
    end
    if not valid_layout(history.layout, history.positions) then return false end
    for _, stack in ipairs({history.undo, history.redo}) do
      for _, entry in ipairs(stack) do
        if type(entry) ~= 'table' then return false end
        normalize_graph_options(entry.document)
        if not readable_graph(entry.document) or not valid_layout(entry.layout, entry.positions) then return false end
      end
    end
    return true
  end
  if not state.graph_canvas or state.graph_canvas.project ~= project then
    if open_buffer_conflict() then return fail(tr('Save or reconcile the open graph buffer first.', '请先保存或处理打开的图文件缓冲区。', '請先儲存或處理開啟的圖檔緩衝區。')) end
    local stat, _, code = vim.uv.fs_lstat(target)
    local doc, base, saved_doc, seeded, saved_raw
    if not stat and code == 'ENOENT' then
      doc, base = {version = 1, definitions = {}, nodes = {}, edges = {}}, 'absent'
      saved_doc = vim.deepcopy(doc)
      if initial_graph then
        if not readable_graph(initial_graph) then
          return fail(tr('The proposed graph has unsupported or invalid fields; no draft was opened.',
            '提议的图包含不支持或无效的字段，未打开草稿。', '提議的圖包含不支援或無效的欄位，未開啟草稿。'))
        end
        doc, seeded = vim.deepcopy(initial_graph), true
      end
    elseif not stat or stat.type ~= 'file' or stat.size > 128 * 1024 then
      return fail(tr('Graph file must be a regular JSON file up to 128 KiB.', '图文件须为不超过 128 KiB 的普通 JSON 文件。', '圖檔須為不超過 128 KiB 的一般 JSON 檔案。'))
    else
      local fd = io.open(target, 'rb')
      local raw = fd and fd:read(128 * 1024 + 1) or nil
      if fd then fd:close() end
      local ok, decoded = pcall(vim.json.decode, raw or '')
      if ok then decoded = normalize_graph_options(decoded) end
      if not raw or #raw > 128 * 1024 or not ok or not readable_graph(decoded) then
        return fail(tr('This graph has an unsupported version, field or invalid structure. Nothing was changed; inspect its JSON in the source editor or use a compatible version.',
          '图的版本、字段或结构不受支持。文件未修改；请在源码编辑器检查 JSON，或使用兼容版本。',
          '圖的版本、欄位或結構不受支援。檔案未修改；請在原始碼編輯器檢查 JSON，或使用相容版本。'))
      end
      doc, base, saved_raw = decoded, vim.fn.sha256(raw), raw
      doc.definitions = doc.definitions or {}
      for _, node in ipairs(doc.nodes) do node.inputs, node.outputs = node.inputs or {}, node.outputs or {} end
    end
    local layout_handle, layout_order, layout_error, layout_collapsed, layout_positions, layout_view = require('model_maven.builder_drafts').graph_layout(project)
    if layout_error then notify(tr('Graph layout cannot be loaded: ', '无法载入图布局：', '無法載入圖佈局：') .. tostring(layout_error), vim.log.levels.WARN) end
    state.graph_canvas = {project = project, draft = doc, saved_doc = saved_doc or vim.deepcopy(doc), base = base, saved_revision = base, saved_raw = saved_raw,
      needs_initial_checkpoint = seeded, layout_handle = layout_handle, layout_order = layout_order,
      layout_collapsed = layout_collapsed, layout_positions = layout_positions or {}, layout_view = layout_view}
  end
  local session = state.graph_canvas
  if session.recovery_prompt then return end
  state.graph_recovery_seen = state.graph_recovery_seen or {}
  if not state.graph_recovery_seen[project] then
    state.graph_recovery_seen[project] = true
    local recovery = require('model_maven.builder_drafts')
    local files, error = recovery.list(project, 'graph')
    if error then notify(tr('Could not read graph recovery files: ', '无法读取图恢复文件：', '無法讀取圖復原檔案：') .. tostring(error), vim.log.levels.WARN) end
    local candidates, choices = {}, {session.base == 'absent'
      and tr('Continue current new graph', '继续当前新图', '繼續目前新圖')
      or tr('Open the saved graph', '打开已保存的图', '開啟已儲存的圖')}
    for _, file in ipairs(files or {}) do
      local ok, value = pcall(vim.json.decode, file.raw)
      if ok and type(value) == 'table' then value.graph = normalize_graph_options(value.graph) end
      if ok and type(value) == 'table' and value.version == 1 and readable_graph(value.graph)
          and (value.base_revision == 'absent' or sha256(value.base_revision)) then
        candidates[#candidates + 1] = {snapshot = value, base_raw = file.base}
        local time_ok, modified = false, nil
        if type(file.modified) == 'number' then time_ok, modified = pcall(os.date, '%Y-%m-%d %H:%M:%S', file.modified) end
        choices[#choices + 1] = tr('Recovery ', '恢复草稿 ', '復原草稿 ') .. tostring(#candidates)
          .. ' · ' .. #(value.graph.nodes or {}) .. tr(' nodes, ', ' 个节点，', ' 個節點，')
          .. #(value.graph.edges or {}) .. tr(' connections', ' 条连接', ' 條連線')
          .. (time_ok and type(modified) == 'string' and (' · ' .. modified) or '')
          .. (value.base_revision ~= session.base and tr(' · base changed', ' · 保存基线已变化', ' · 儲存基準已變更') or '')
      end
    end
    if #candidates > 0 then
      session.recovery_prompt = true
      vim.ui.select(choices, {prompt = tr('Recover a graph draft? Recovery files are not saved project declarations.',
        '恢复图草稿？恢复文件不等于已保存的项目声明。', '復原圖草稿？復原檔案不等於已儲存的專案宣告。')}, function(_, choice)
        session.recovery_prompt = false
        if not context() or state.graph_canvas ~= session then return end
        if not choice then state.graph_recovery_seen[project] = nil; return end
        if choice > 1 and candidates[choice - 1] then
          local selected_recovery = candidates[choice - 1]
          local candidate = selected_recovery.snapshot
          -- The file currently on disk is not the recovered draft's base when
          -- its revision differs. Do not reuse it as evidence of a save or a
          -- three-way merge base if the original base snapshot is unavailable.
          if session.saved_revision ~= candidate.base_revision then
            session.saved_doc, session.saved_revision, session.saved_raw = nil, nil, nil
          end
          session.draft, session.base = vim.deepcopy(candidate.graph), candidate.base_revision
          local base_raw = selected_recovery.base_raw
          if candidate.base_revision == 'absent' then
            session.saved_doc, session.saved_revision, session.saved_raw = {version = 1, definitions = {}, nodes = {}, edges = {}}, 'absent', nil
          elseif type(base_raw) == 'string' and #base_raw <= 128 * 1024
              and vim.fn.sha256(base_raw) == candidate.base_revision then
            local ok, base_graph = pcall(vim.json.decode, base_raw)
            if ok then base_graph = normalize_graph_options(base_graph) end
            if ok and readable_graph(base_graph) then
              base_graph.definitions = base_graph.definitions or {}
              for _, node in ipairs(base_graph.nodes) do node.inputs, node.outputs = node.inputs or {}, node.outputs or {} end
              session.saved_doc, session.saved_revision, session.saved_raw = base_graph, candidate.base_revision, base_raw
            end
          end
          if candidate.base_revision ~= 'absent' and session.saved_revision ~= candidate.base_revision then
            notify(tr('The original recovery base is unavailable. Compare the draft with the current file before saving.',
              '恢复草稿的原始基线不可用。保存前请先与当前文件比较。',
              '復原草稿的原始基準無法使用。儲存前請先與目前檔案比較。'), vim.log.levels.WARN)
          end
          session.draft.definitions = session.draft.definitions or {}
          for _, node in ipairs(session.draft.nodes) do node.inputs, node.outputs = node.inputs or {}, node.outputs or {} end
          if type(candidate.history) == 'table' then
            normalize_graph_options(candidate.history.document)
            if recoverable_history(candidate.history, session.draft) then session.history = vim.deepcopy(candidate.history) end
          end
        end
        sessions.open_graph_canvas(state)
      end)
      return
    end
  end
  local function checkpoint(force)
    session.checkpoint_ticket = (session.checkpoint_ticket or 0) + 1
    local ticket = session.checkpoint_ticket
    local function write()
      if ticket ~= session.checkpoint_ticket then return end
      if not session.checkpoint_handle and vim.deep_equal(session.draft, session.saved_doc)
          and not (session.history and (#session.history.undo > 0 or #session.history.redo > 0)) then return end
      local history
      if type(session.history) == 'table' and type(session.history.undo) == 'table' and type(session.history.redo) == 'table' then
        history = {document = vim.deepcopy(session.history.document), layout = vim.deepcopy(session.history.layout),
          positions = vim.deepcopy(session.history.positions), undo = {}, redo = {}}
        for _, key in ipairs({'undo', 'redo'}) do
          local stack = session.history[key]
          for index = math.max(1, #stack - 7), #stack do history[key][#history[key] + 1] = vim.deepcopy(stack[index]) end
        end
      end
      if history and vim.deep_equal(history.document, session.draft) then
        if not recoverable_history(history, session.draft) then history = nil end
      else history = nil end
      local payload = {version = 1, base_revision = session.base, graph = session.draft, history = history}
      local ok, raw = pcall(vim.json.encode, payload)
      while ok and #raw > 1024 * 1024 and history and (#history.undo > 0 or #history.redo > 0) do
        if #history.undo >= #history.redo and #history.undo > 0 then table.remove(history.undo, 1)
        else table.remove(history.redo, 1) end
        ok, raw = pcall(vim.json.encode, payload)
      end
      if not ok or #raw > 1024 * 1024 then
        if not session.checkpoint_failed then notify(tr('Graph recovery draft is too large or cannot be encoded.', '图恢复草稿过大或无法编码。', '圖復原草稿過大或無法編碼。'), vim.log.levels.WARN) end
        session.checkpoint_failed = true; return
      end
      local recovery = require('model_maven.builder_drafts')
      if session.saved_revision == session.base and type(session.saved_raw) == 'string'
          and vim.fn.sha256(session.saved_raw) == session.base then
        local packed, pack_error = recovery.pack(raw, session.saved_raw)
        if not packed then
          if not session.checkpoint_failed then notify(tr('Could not encode graph recovery: ', '无法编码图恢复文件：', '無法編碼圖復原檔案：') .. tostring(pack_error), vim.log.levels.WARN) end
          session.checkpoint_failed = true; return
        end
        raw = packed
      end
      if not session.checkpoint_handle then
        local handle, error = recovery.create(project, 'graph')
        if not handle then
          if not session.checkpoint_failed then notify(tr('Could not create graph recovery: ', '无法创建图恢复文件：', '無法建立圖復原檔案：') .. tostring(error), vim.log.levels.WARN) end
          session.checkpoint_failed = true; return
        end
        session.checkpoint_handle = handle
      end
      local saved, error = recovery.write(session.checkpoint_handle, raw)
      if not saved then
        if not session.checkpoint_failed then notify(tr('Could not save graph recovery: ', '无法保存图恢复文件：', '無法儲存圖復原檔案：') .. tostring(error), vim.log.levels.WARN) end
        session.checkpoint_failed = true; return
      end
      session.checkpoint_failed = false
    end
    if force then write() else vim.defer_fn(write, 500) end
  end
  if session.needs_initial_checkpoint then
    session.needs_initial_checkpoint = nil
    checkpoint(true)
  end
  local function checkpoint_layout(force)
    session.layout_ticket = (session.layout_ticket or 0) + 1
    local ticket = session.layout_ticket
    local function write()
      if ticket ~= session.layout_ticket or not session.layout_handle or not session.layout_order then return end
      local ok, error = require('model_maven.builder_drafts').write_graph_layout(session.layout_handle, session.layout_order, session.layout_collapsed, session.layout_positions or {}, session.layout_view)
      if not ok and not session.layout_failed then
        notify(tr('Could not save graph layout: ', '无法保存图布局：', '無法儲存圖佈局：') .. tostring(error), vim.log.levels.WARN)
      end
      session.layout_failed = not ok
    end
    if force then write() else vim.defer_fn(write, 500) end
  end
  local function current(snapshot)
    return context() and state.graph_canvas == session and vim.deep_equal(session.draft, snapshot)
  end
  local function temp(snapshot)
    local ok, raw = pcall(vim.json.encode, snapshot)
    if not ok or #raw > 128 * 1024 then return nil, nil end
    local path = vim.fn.tempname()
    local fd = vim.uv.fs_open(path, 'wx', 384)
    if not fd then return nil, nil end
    local written = vim.uv.fs_write(fd, raw, 0)
    vim.uv.fs_close(fd)
    if written ~= #raw then vim.uv.fs_unlink(path); return nil, nil end
    return path, vim.fn.sha256(raw)
  end
  local function show_review(title, content, can_apply, done)
    if not reviewable_text(content) then
      if done then done(false) end
      return fail(tr('Preview is too large to review in this window.', '预览过大，无法在此窗口审核。', '預覽過大，無法在此視窗檢視。'))
    end
    local buffer = vim.api.nvim_create_buf(false, true)
    vim.bo[buffer].bufhidden, vim.bo[buffer].swapfile = 'wipe', false
    local header = {title, can_apply and tr('[a] Confirm  [q] Cancel', '[a] 确认  [q] 取消', '[a] 確認  [q] 取消') or tr('[q] Close', '[q] 关闭', '[q] 關閉'), ''}
    vim.list_extend(header, vim.split(content, '\n', {plain = true}))
    vim.api.nvim_buf_set_lines(buffer, 0, -1, false, header); vim.bo[buffer].modifiable = false
    local w, col = require('model_maven.model_preview').layout(110, function()
      local view = state.model_preview
      if view and vim.api.nvim_win_is_valid(view.win) then return vim.api.nvim_win_get_position(view.win)[2] end
    end)
    local h = math.min(32, vim.o.lines - 5)
    local opened, window = pcall(vim.api.nvim_open_win, buffer, true, {relative='editor', style='minimal', border='rounded',
      width=w, height=h, row=1, col=col})
    if not opened then
      pcall(vim.api.nvim_buf_delete, buffer, {force=true})
      if done then done(false) end
      return fail(tr('Cannot open review.', '无法打开审核页。', '無法開啟檢視頁。'))
    end
    local finished = false
    local function finish(accepted)
      if finished then return end
      finished = true
      if vim.api.nvim_win_is_valid(window) then vim.api.nvim_win_close(window, true) end
      if done then done(accepted) end
    end
    vim.keymap.set('n', 'q', function() finish(false) end, {buffer=buffer, nowait=true})
    vim.keymap.set('n', '<Esc>', function() finish(false) end, {buffer=buffer, nowait=true})
    if can_apply then vim.keymap.set('n', 'a', function() finish(true) end, {buffer=buffer, nowait=true}) end
    vim.api.nvim_create_autocmd('BufWipeout', {buffer=buffer, once=true, callback=function() if not finished then finished=true; if done then done(false) end end end})
  end
  local function reconcile(snapshot, callback)
    if not current(snapshot) or open_buffer_conflict() then
      return fail(tr('Save or reconcile the open graph buffer first.', '请先保存或处理打开的图文件缓冲区。', '請先儲存或處理開啟的圖檔緩衝區。'))
    end
    local function read_latest()
      local stat, _, code = vim.uv.fs_lstat(target)
      if not stat and code == 'ENOENT' then return 'absent', {version=1, definitions={}, nodes={}, edges={}} end
      if not stat or stat.type ~= 'file' or stat.size > 128 * 1024 then return nil end
      local fd = io.open(target, 'rb')
      local raw = fd and fd:read(128 * 1024 + 1) or nil
      if fd then fd:close() end
      local ok, decoded = pcall(vim.json.decode, raw or '')
      if ok then decoded = normalize_graph_options(decoded) end
      if not raw or #raw > 128 * 1024 or not ok or not readable_graph(decoded) then return nil end
      decoded.definitions = decoded.definitions or {}
      for _, node in ipairs(decoded.nodes) do node.inputs, node.outputs = node.inputs or {}, node.outputs or {} end
      return vim.fn.sha256(raw), decoded, raw
    end
    local revision, latest, latest_raw = read_latest()
    if not revision then return fail(tr('Cannot safely read the current graph file.', '无法安全读取当前图文件。', '無法安全讀取目前圖檔。')) end
    local function merge_graph()
      if session.saved_revision ~= session.base then return nil, 'base unavailable' end
      local base = session.saved_doc
      local structural = {'component_storage', 'definitions', 'nodes', 'edges', 'groups'}
      local settings = {'data', 'objectives', 'training', 'supervision'}
      local allowed = {version = true, legacy_import = true}
      for _, group in ipairs({structural, settings}) do for _, key in ipairs(group) do allowed[key] = true end end
      for _, doc in ipairs({base, snapshot, latest}) do
        for key in pairs(doc) do if not allowed[key] then return nil, 'unknown field: ' .. tostring(key) end end
      end
      -- A source declaration is an immutable recovery record. Never merge a
      -- changed or deleted snapshot implicitly, even when model edits do not
      -- overlap. The explicit compare-and-keep path remains available.
      if not vim.deep_equal(base.legacy_import, snapshot.legacy_import)
          or not vim.deep_equal(base.legacy_import, latest.legacy_import) then
        return nil, 'legacy declaration snapshot changed'
      end
      local function changed(a, b, fields)
        for _, key in ipairs(fields) do if not vim.deep_equal(a[key], b[key]) then return true end end
        return false
      end
      if (changed(base, snapshot, structural) and changed(base, latest, settings))
          or (changed(base, latest, structural) and changed(base, snapshot, settings)) then
        return nil, 'structure and data/training dependencies'
      end
      for _, fields in ipairs({structural, settings}) do
        if changed(base, snapshot, fields) and changed(base, latest, fields)
            and changed(snapshot, latest, fields) then
          return nil, 'concurrent related changes'
        end
      end
      local merged = vim.deepcopy(latest)
      for _, fields in ipairs({structural, settings}) do
        for _, key in ipairs(fields) do
          local mine, theirs = not vim.deep_equal(base[key], snapshot[key]), not vim.deep_equal(base[key], latest[key])
          if mine and theirs and not vim.deep_equal(snapshot[key], latest[key]) then return nil, key end
          if mine then merged[key] = vim.deepcopy(snapshot[key]) end
        end
      end
      if not readable_graph(merged) then return nil, 'merged graph invalid' end
      return merged
    end
    local merged, merge_error = merge_graph()
    local choices = {tr('Compare and keep my draft', '比较并保留我的草稿', '比較並保留我的草稿')}
    if merged then choices[#choices + 1] = tr('Review a conservative merge', '审核保守合并', '檢視保守合併') end
    choices[#choices + 1] = tr('Cancel', '取消', '取消')
    vim.ui.select(choices, {prompt = merged and tr('Choose how to resolve the changed graph.',
      '选择如何处理已变化的图。', '選擇如何處理已變更的圖。') or tr('Automatic merge unavailable: ', '无法自动合并：', '無法自動合併：') .. tostring(merge_error)}, function(_, choice)
    if not current(snapshot) or not choice or choice > (merged and 2 or 1) then return end
    local proposed = choice == 2 and merged or snapshot
    local ok, difference = pcall(vim.diff, vim.inspect(latest) .. '\n', vim.inspect(proposed) .. '\n', {result_type = 'unified'})
    if not ok then return fail(tr('Could not compare graph versions.', '无法比较图版本。', '無法比較圖版本。')) end
    local explanation = choice == 2 and tr('Current saved graph → merged draft. Confirming updates only the draft and save baseline; review and save separately.',
      '当前已保存图 → 合并草稿。确认只更新草稿和保存基线；请另行审核保存。',
      '目前已儲存圖 → 合併草稿。確認只更新草稿和儲存基準；請另行檢視儲存。') or tr('Current saved graph → current draft. Confirming selects the current file as the save baseline; it does not merge or write. A later save would replace the file with this draft.',
      '当前已保存图 → 当前草稿。确认仅将当前文件设为保存基线，不会合并或写入；之后保存会用草稿替换该文件。',
      '目前已儲存圖 → 目前草稿。確認僅將目前檔案設為儲存基準，不會合併或寫入；之後儲存會以草稿取代該檔案。')
    show_review(tr('Compare graph versions', '比较图版本', '比較圖版本'), explanation .. '\n\n' .. (difference ~= '' and difference or tr('(No semantic differences)', '（无语义差异）', '（無語意差異）')), true, function(accepted)
      if not accepted or not current(snapshot) or open_buffer_conflict() then return end
      local now = read_latest()
      if now ~= revision then return fail(tr('The saved graph changed during review; compare again.', '审核期间已保存图发生变化，请重新比较。', '檢視期間已儲存圖發生變更，請重新比較。')) end
      if choice == 2 and callback then
        local applied = callback(tr('Merged into draft; review the save separately.', '已合并到草稿；请另行审核保存。', '已合併至草稿；請另行檢視儲存。'), nil, merged)
        if not applied then return end
        session.base, session.saved_doc, session.saved_revision, session.saved_raw = revision, latest, revision, latest_raw
        checkpoint(true)
      else
        session.base, session.saved_doc, session.saved_revision, session.saved_raw = revision, latest, revision, latest_raw
        checkpoint(true)
        if callback then callback(tr('Save baseline updated; review the save separately.', '保存基线已更新；请另行审核保存。', '儲存基準已更新；請另行檢視儲存。')) end
      end
    end)
    end)
  end
  local apply_graph_data
  local function execute(snapshot, mode, output, callback, source_revision)
    if not current(snapshot) or open_buffer_conflict() then return fail(tr('Graph draft or file buffer changed; reopen the operation.', '图草稿或文件缓冲区已变化，请重新操作。', '圖草稿或檔案緩衝區已變更，請重新操作。')) end
    local path, digest = temp(snapshot)
    if not path then return fail(tr('Could not prepare bounded graph draft.', '无法准备有界图草稿。', '無法準備有界圖草稿。')) end
    if mode == 'generate' and (session.base == 'absent' or not vim.deep_equal(snapshot, session.saved_doc)) then
      vim.uv.fs_unlink(path)
      return fail(tr('Save this exact graph draft before generating source.', '生成源码前请先保存当前图草稿。', '產生原始碼前請先儲存目前圖草稿。'))
    end
    local cleaned = false
    local function cleanup() if not cleaned then cleaned = true; vim.uv.fs_unlink(path) end end
    local args
    if mode == 'validate' then args = {'graph-plan', '--graph', path, '--if-graph', digest}
    elseif mode == 'save' then args = {'graph-save', '--draft', path, '--if-draft', digest, '--output', file_name, '--if-base', session.base}
    else
      args = {'graph-generate', '--graph', target, '--if-graph', session.base, '--output', output}
      if source_revision then vim.list_extend(args, {'--if-source', source_revision}) end
    end
    state.busy = tr('Planning graph', '规划图', '規劃圖'); render(state)
    request(state, args, function(report, error)
      state.busy = nil; render(state)
      if not current(snapshot) then cleanup(); return fail(tr('Graph or workspace changed; plan again.', '图或工作区已变化，请重新规划。', '圖或工作區已變更，請重新規劃。')) end
      local expected = mode == 'validate' and 'graph_plan' or mode == 'save' and 'graph_save' or 'graph_generate'
      if error or not report or report.operation ~= expected then cleanup(); return fail(tr('Graph operation failed.', '图操作失败。', '圖操作失敗。')) end
      if mode == 'validate' or report.status ~= 'success' then
        if mode == 'validate' and report.status == 'success' and (type(report.data) ~= 'table' or report.data.input_sha256 ~= digest) then
          cleanup(); return fail(tr('Graph plan digest differs.', '图规划摘要不一致。', '圖規劃摘要不一致。'))
        end
        if mode == 'validate' and type(report.data) == 'table' and report.data.input_sha256 == digest then
          local data, choices, destinations = report.data, {}, {}
          if report.status == 'success' and type(data.unconnected_inputs) == 'table' then
            for _, kind in ipairs(type(data.missing_boundaries) == 'table' and data.missing_boundaries or {}) do
              if kind == 'input' or kind == 'output' then
                choices[#choices + 1] = tr('Missing boundary: ', '缺少边界节点：', '缺少邊界節點：') .. kind
                destinations[#destinations + 1] = false
              end
            end
            for _, item in ipairs(data.unconnected_inputs) do
              if type(item) == 'table' and graph_id(item.node) and graph_id(item.port) then
                choices[#choices + 1] = tr('Unconnected input: ', '未连接输入：', '未連接輸入：') .. item.node .. '.' .. item.port
                destinations[#destinations + 1] = item.node
              end
            end
            for _, item in ipairs(type(data.dtype_advisories) == 'table' and data.dtype_advisories or {}) do
              local from, to = type(item) == 'table' and item.from, type(item) == 'table' and item.to
              if type(from) == 'table' and type(to) == 'table' and graph_id(from.node) and graph_id(from.port)
                  and graph_id(to.node) and graph_id(to.port) and type(from.dtype) == 'string' and type(to.dtype) == 'string' then
                choices[#choices + 1] = tr('Review dtype names (may be aliases): ', '核对 dtype 名称（可能是别名）：', '核對 dtype 名稱（可能是別名）：')
                  .. from.node .. '.' .. from.port .. ' ' .. vim.fn.strcharpart(from.dtype:gsub('[%c]', ' '), 0, 64)
                  .. ' → ' .. to.node .. '.' .. to.port .. ' ' .. vim.fn.strcharpart(to.dtype:gsub('[%c]', ' '), 0, 64)
                destinations[#destinations + 1] = to.node
              end
            end
            local review = data.data_review
            for _, issue in ipairs(type(review) == 'table' and type(review.issues) == 'table' and review.issues or {}) do
              if type(issue) == 'table' and type(issue.kind) == 'string' then
                local descriptions = {
                  missing_input = tr('Missing CSV input: ', '缺少 CSV 输入：', '缺少 CSV 輸入：'),
                  csv_input_name_too_long = tr('CSV input name too long: ', 'CSV 输入名过长：', 'CSV 輸入名稱過長：'),
                  invalid_input_field = tr('Invalid CSV input shape or columns: ', 'CSV 输入形状或列无效：', 'CSV 輸入形狀或欄無效：'),
                  input_shape_conflict = tr('CSV/input shape mismatch: ', 'CSV 与输入形状不一致：', 'CSV 與輸入形狀不一致：'),
                  input_dtype_review = tr('Review CSV/input dtype names: ', '请核对 CSV 和输入 dtype 名称：', '請核對 CSV 和輸入 dtype 名稱：'),
                  invalid_batch_size = tr('Invalid CSV batch size', 'CSV 批大小无效', 'CSV 批次大小無效'),
                  invalid_csv_path = tr('CSV batch needs a nonempty path', 'CSV 批次需要非空路径', 'CSV 批次需要非空路徑'),
                  invalid_csv_split = tr('Invalid CSV split, weights or seed', 'CSV 切分、权重或种子无效', 'CSV 切分、權重或種子無效'),
                  unexpected_input = tr('Unexpected CSV input: ', '多余的 CSV 输入：', '多餘的 CSV 輸入：'),
                  missing_target = tr('Missing CSV target: ', '缺少 CSV 目标：', '缺少 CSV 目標：'),
                  invalid_target_field = tr('Invalid CSV target shape or columns: ', 'CSV 目标形状或列无效：', 'CSV 目標形狀或欄無效：'),
                  target_shape_conflict = tr('Loss target/output shape mismatch: ', '损失目标与输出形状不一致：', '損失目標與輸出形狀不一致：'),
                  target_dtype_review = tr('Review cross-entropy target dtype: ', '请检查交叉熵目标 dtype：', '請檢查交叉熵目標 dtype：'),
                  image_missing_input = tr('Image batch does not provide input: ', '图像批次未提供输入：', '影像批次未提供輸入：'),
                  image_unknown_input = tr('Image batch refers to an unknown input: ', '图像批次引用未知输入：', '影像批次參照未知輸入：'),
                  image_missing_target = tr('Image batch does not provide target: ', '图像批次未提供目标：', '影像批次未提供目標：'),
                  image_invalid_target = tr('Image batch needs a valid label target: ', '图像批次需要有效的标签目标：', '影像批次需要有效的標籤目標：'),
                  image_invalid_root = tr('Image batch needs a dataset path', '图像批次需要数据集路径', '影像批次需要資料集路徑'),
                  image_invalid_split = tr('Invalid image data split', '图像数据切分无效', '影像資料切分無效'),
                  image_invalid_batch_size = tr('Image batch size must be positive', '图像批大小须为正整数', '影像批次大小須為正整數'),
                  image_invalid_transforms = tr('Image split transforms conflict or omit the active split', '图像按切分变换冲突或缺少当前切分', '影像依切分變換衝突或缺少目前切分'),
                  unexpected_binding = tr('This batch needs envelope binding; selected: ', '此批次需要 envelope 绑定；当前：', '此批次需要 envelope 繫結；目前：'),
                }
                local label = descriptions[issue.kind]
                if label then
                  local name = type(issue.name) == 'string' and vim.fn.strcharpart(issue.name:gsub('[%c]', ' '), 0, 260) or '?'
                  local details = ''
                  if issue.kind == 'input_shape_conflict' or issue.kind == 'target_shape_conflict' then
                    local ok_expected, expected = pcall(vim.json.encode, issue.declared_shape or issue.prediction_shape)
                    local ok_actual, actual = pcall(vim.json.encode, issue.csv_shape or issue.target_shape)
                    if ok_expected and ok_actual then details = ' · ' .. expected .. ' / ' .. actual end
                  elseif issue.kind == 'target_dtype_review' and type(issue.dtype) == 'string' then
                    details = ' · ' .. vim.fn.strcharpart(issue.dtype:gsub('[%c]', ' '), 0, 64)
                  elseif issue.kind == 'input_dtype_review' and type(issue.csv_dtype) == 'string' and type(issue.declared_dtype) == 'string' then
                    details = ' · ' .. issue.csv_dtype:gsub('[%c]', ' ') .. ' / ' .. issue.declared_dtype:gsub('[%c]', ' ')
                  end
                  choices[#choices + 1] = label .. ((issue.kind == 'invalid_batch_size' or issue.kind == 'image_invalid_root'
                    or issue.kind == 'invalid_csv_path' or issue.kind == 'invalid_csv_split' or issue.kind == 'image_invalid_split'
                    or issue.kind == 'image_invalid_batch_size' or issue.kind == 'image_invalid_transforms') and '' or name) .. details
                  destinations[#destinations + 1] = graph_id(issue.node) and issue.node or false
                end
              end
            end
          elseif report.status ~= 'success' and graph_id(data.node_id) then
            local diagnostic = type(report.diagnostics) == 'table' and report.diagnostics[1] or nil
            if type(diagnostic) == 'table' and type(diagnostic.message) == 'string' then
              choices[#choices + 1] = diagnostic.message:gsub('[%c]', ' ')
              destinations[#destinations + 1] = data.node_id
            end
          end
          if #choices > 0 then
            cleanup()
            vim.ui.select(choices, {prompt = tr('Select an issue to locate its node', '选择问题并定位节点', '選擇問題並定位節點')}, function(_, index)
              if not index or not current(snapshot) then return end
              if callback then callback(index and destinations[index] and tr('Review the selected node; runtime remains unverified.', '请检查所选节点；运行尚未验证。', '請檢查所選節點；執行尚未驗證。')
                or tr('Review the selected issue; runtime remains unverified.', '请检查所选问题；运行尚未验证。', '請檢查所選問題；執行尚未驗證。'), index and destinations[index] or nil) end
            end)
            return
          end
        end
        cleanup(); show_review(tr('Graph planning · not runtime verified', '图规划 · 尚未运行验证', '圖規劃 · 尚未執行驗證'), vim.inspect(report), false)
        if callback then callback(report.status == 'success' and report.data and report.data.status == 'structurally_connected'
          and tr('Structurally connected; runtime unverified.', '结构已连接；运行尚未验证。', '結構已連接；執行尚未驗證。')
          or tr('Graph needs attention.', '图需要处理。', '圖需要處理。')) end
        return
      end
      local data = report.data
      if type(data) ~= 'table' or data.committed ~= false or not sha256(data.plan_revision)
          or (mode == 'generate' and (type(data.plan) ~= 'table' or data.plan.output ~= output
            or data.plan.input_sha256 ~= session.base or data.plan.source_sha256 ~= data.source_sha256
            or (source_revision and data.plan.previous_source_sha256 ~= source_revision)
            or type(data.source) ~= 'string' or data.input_sha256 ~= session.base or not sha256(data.source_sha256) or vim.fn.sha256(data.source) ~= data.source_sha256))
          or (mode == 'save' and (type(data.plan) ~= 'table' or data.plan.draft_sha256 ~= digest or data.plan.base_revision ~= session.base or data.plan.output ~= file_name)) then
        cleanup(); return fail(tr('Graph plan could not be verified.', '无法核对图计划。', '無法核對圖計畫。'))
      end
      local view = mode == 'generate' and data.source or vim.inspect(data.plan)
      if mode == 'generate' then
        local model = state.project_info and state.project_info.model
        local previous_module = type(model) == 'string' and model:match('^([%a_][%w_]*):model$') or nil
        local previous_path = source_revision and project .. '/' .. output or (previous_module and project .. '/' .. previous_module .. '.py' or nil)
        local stat = previous_path and vim.uv.fs_lstat(previous_path) or nil
        local file = stat and stat.type == 'file' and stat.size <= 128 * 1024 and io.open(previous_path, 'rb') or nil
        local previous = file and file:read(128 * 1024 + 1) or nil
        if file then file:close() end
        if source_revision and (not previous or #previous > 128 * 1024 or vim.fn.sha256(previous) ~= source_revision) then
          cleanup(); return fail(tr('Source changed or cannot be reviewed; no file was updated.', '源码已变化或无法审核；文件未更新。', '原始碼已變更或無法檢視；檔案未更新。'))
        end
        if previous and #previous <= 128 * 1024 then
          local ok, diff = pcall(vim.diff, previous, data.source, {result_type = 'unified'})
          if ok and diff ~= '' and reviewable_text(diff) then
            view = (source_revision and tr('Review changes to the selected file. Confirming conditionally replaces it and records recoverable source history:',
              '审核所选文件的改动。确认后将条件更新该文件并记录可恢复的源码历史：', '檢視所選檔案的改動。確認後將條件更新該檔案並記錄可復原的原始碼歷史：')
              or tr('Changes against the project model on disk (the original file is retained):',
                '与磁盘上项目模型的差异（保留原文件）：', '與磁碟上專案模型的差異（保留原檔案）：')) .. '\n\n' .. diff
          elseif ok and diff == '' then
            view = tr('The generated source matches the project model on disk. Unsaved buffers are not included; the original file is retained.',
              '生成源码与磁盘上的项目模型一致；不含缓冲区未保存的修改，原文件会保留。',
              '產生的原始碼與磁碟上的專案模型一致；不含緩衝區未儲存的修改，原檔案會保留。') .. '\n\n' .. data.source
          else
            if source_revision then cleanup(); return fail(tr('Cannot show a safe source diff; no file was updated.', '无法显示可审核的源码差异；文件未更新。', '無法顯示可檢視的原始碼差異；檔案未更新。')) end
            view = tr('The source diff could not be displayed; review the full proposed source below. The original file is retained.',
              '无法显示源码差异；请审核下方完整拟生成源码，原文件会保留。',
              '無法顯示原始碼差異；請檢視下方完整擬產生原始碼，原檔案會保留。') .. '\n\n' .. data.source
          end
        elseif previous_path then
          view = tr('The current project source could not be compared. Review the full proposed source below; the original file is retained.',
            '无法比较当前项目源码；请审核下方完整拟生成源码，原文件会保留。',
            '無法比較目前專案原始碼；請檢視下方完整擬產生原始碼，原檔案會保留。') .. '\n\n' .. data.source
        end
        if source_revision then
          view = tr('Confirming updates the selected file only if its contents are unchanged since this review; source history records the previous contents.\n\n',
            '确认后仅在所选文件内容与本次审核一致时更新，并将原内容记录到源码历史。\n\n',
            '確認後僅在所選檔案內容與本次檢視一致時更新，並將原內容記錄至原始碼歷史。\n\n') .. view
        end
        if type(data.plan.component_prefixes) == 'table' and is_list(data.plan.component_prefixes) then
          local lines = {tr('Checkpoint prefix suggestions for this graph only; verify the original graph and every state key before migration.',
            '仅为当前图的检查点前缀建议；迁移前请核对原图和每个状态键。',
            '僅為目前圖的檢查點前綴建議；遷移前請核對原圖和每個狀態鍵。')}
          for index, item in ipairs(data.plan.component_prefixes) do
            if index > 64 then lines[#lines + 1] = tr('… additional prefixes are available in the CLI plan.', '… 更多前缀可在 CLI 计划中查看。', '… 更多前綴可在 CLI 計畫中檢視。'); break end
            if type(item) == 'table' and type(item.definition) == 'string' and type(item.legacy) == 'string' and type(item.named) == 'string' then
              lines[#lines + 1] = item.definition:gsub('[%c]', ' ') .. ': ' .. item.legacy:gsub('[%c]', ' ') .. ' → ' .. item.named:gsub('[%c]', ' ')
            end
          end
          view = table.concat(lines, '\n') .. '\n\n' .. view
        end
      end
      show_review(mode == 'generate' and tr('Proposed graph source', '拟生成的图源码', '擬產生的圖原始碼') or tr('Proposed graph save', '拟保存的图草稿', '擬儲存的圖草稿'), view, true, function(accepted)
        if not accepted or not current(snapshot) or open_buffer_conflict() then cleanup(); return end
        if source_revision and (#dirty_buffers(project) > 0 or #reloads_pending(state) > 0) then
          cleanup(); return fail(tr('Project buffers changed; review the source update again.', '项目缓冲区已变化；请重新审核源码更新。', '專案緩衝區已變更；請重新檢視原始碼更新。'))
        end
        local apply_args = vim.deepcopy(args); vim.list_extend(apply_args, {'--apply', '--if-plan', data.plan_revision})
        local tracked = begin_tracked_commit(state, mode == 'save' and tr('Save graph', '保存图', '儲存圖') or tr('Create graph source', '创建图源码', '建立圖原始碼'))
        if not tracked then cleanup(); return end
        state.busy = tr('Saving graph work', '保存图工作', '儲存圖工作'); render(state)
        request(state, apply_args, function(receipt, problem)
          state.busy = nil; cleanup()
          local same = tracked_commit_current(state, tracked)
          local result = receipt and receipt.data
          local valid = not problem and receipt and receipt.operation == expected and receipt.status == 'success'
            and type(result) == 'table' and result.committed == true and result.plan_revision == data.plan_revision
            and (mode == 'save' and result.graph_sha256 == digest and result.output == file_name
              or mode == 'generate' and result.source_sha256 == data.source_sha256 and result.output == output
                and (not source_revision or result.previous_source_sha256 == source_revision))
          -- GRAPH_BASE_CONFLICT is emitted before any graph write, including
          -- after the locked recheck. A complete matching error receipt is a
          -- known rejection, not the same as an interrupted/lost receipt.
          local rejected_conflict = mode == 'save' and not problem and receipt
            and receipt.operation == 'graph_save' and receipt.status == 'error'
            and type(receipt.diagnostics) == 'table' and #receipt.diagnostics == 1
            and type(receipt.diagnostics[1]) == 'table'
            and receipt.diagnostics[1].code == 'GRAPH_BASE_CONFLICT'
          local settled = settle_tracked_commit(state, tracked, valid or rejected_conflict, problem)
          if not same then notify_tracked_context_changed(tracked); return end
          if rejected_conflict and settled then
            render(state)
            fail(tr('The graph changed on disk; no graph was saved. Reopen it and merge your draft.',
              '磁盘上的图已变化，本次没有保存；请重新打开并合并草稿。',
              '磁碟上的圖已變更，本次沒有儲存；請重新開啟並合併草稿。'))
            return
          end
          if valid and settled then
            if mode == 'save' then
              session.base = digest; session.saved_revision = digest; session.saved_doc = vim.deepcopy(snapshot)
              require('model_maven.model_preview').refresh(state)
              local file = io.open(target, 'rb'); local raw = file and file:read(128 * 1024 + 1) or nil
              if file then file:close() end
              session.saved_raw = raw and #raw <= 128 * 1024 and vim.fn.sha256(raw) == digest and raw or nil
              mark_source_buffers(state, {target}); checkpoint(false)
            else
              mark_source_buffers(state, {output})
            end
            state.change_epoch = (state.change_epoch or 0) + 1
            if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
          end
          render(state)
          if valid and settled then
            local unchanged = state.graph_canvas == session and vim.deep_equal(session.draft, snapshot)
            if callback then callback(not unchanged and tr('An earlier snapshot was processed; newer graph edits remain unsaved.',
                '已处理先前快照；较新的图修改尚未保存。', '已處理先前快照；較新的圖修改尚未儲存。')
              or mode == 'save' and tr('Graph saved; model not run.', '图已保存；模型尚未运行。', '圖已儲存；模型尚未執行。')
              or source_revision and tr('Source updated; runtime remains unverified.', '源码已更新；运行尚未验证。', '原始碼已更新；執行尚未驗證。')
              or tr('Source created; connect data and training separately.', '源码已创建；请另行接入数据和训练。', '原始碼已建立；請另行接入資料和訓練。')) end
            if mode == 'generate' and unchanged then
              local entry = output:sub(1, -4) .. ':model'
              local _, config_status = project_config(project)
              local setup = config_status == 'missing'
              local options = {tr('Continue editing', '继续编辑', '繼續編輯'), setup
                and tr('Set up project with this model…', '用此模型初始化项目…', '以此模型初始化專案…')
                or tr('Set as project model…', '设为项目模型…', '設為專案模型…')}
              local can_bind = session.capabilities and session.capabilities['project.graph_bind_project_v1'] == true
                and (not setup or session.capabilities['project.graph_bind_create_v1'] == true)
              if can_bind then options[#options + 1] = snapshot.data
                and tr('Bind model and declared data together…', '同时绑定模型和声明的数据…', '同時繫結模型和宣告的資料…')
                or tr('Bind model to project…', '将模型绑定到项目…', '將模型繫結至專案…') end
              vim.ui.select(options,
                {prompt = tr('Source created. Configure its model factory?', '源码已创建。配置其模型工厂？', '原始碼已建立。設定其模型工廠？')}, function(_, choice)
                  if not context() or state.graph_canvas ~= session then return end
                  if choice == 3 and can_bind then
                    local info, base = state.project_info, session.base
                    local revision = setup and 'absent' or (info and info.config_revision)
                    if not (revision == 'absent' or sha256(revision)) or not current(snapshot) or not project_config_current(state)
                        or open_buffer_conflict() or #dirty_buffers(project) > 0 then
                      return fail(tr('Project or graph changed; review before binding.', '项目或图已变化，请审核后绑定。', '專案或圖已變更，請檢視後繫結。'))
                    end
                    local function stable()
                      local _, status = project_config(project)
                      local config_matches = revision == 'absent' and status == 'missing'
                        or revision ~= 'absent' and state.project_info and state.project_info.config_revision == revision
                      return current(snapshot) and session.base == base and config_matches and project_config_current(state)
                        and not open_buffer_conflict() and #dirty_buffers(project) == 0
                    end
                    local args = {'graph-bind', '--graph', target, '--if-graph', base, '--source', output, '--if-config', revision}
                    if snapshot.data then args[#args + 1] = '--include-data' end
                    state.busy = tr('Planning project binding', '规划项目绑定', '規劃專案繫結'); render(state)
                    request(state, args, function(preview, error)
                      state.busy = nil; render(state)
                      if not stable() then return end
                      local plan = preview and preview.data and preview.data.plan
                      if error or not preview or preview.operation ~= 'graph_bind' or preview.status ~= 'success'
                          or type(plan) ~= 'table' or preview.data.committed ~= false or not sha256(preview.data.plan_revision)
                          or plan.graph_sha256 ~= base or plan.source ~= output or plan.source_sha256 ~= data.source_sha256
                          or plan.from_revision ~= revision or plan.model ~= entry or plan.creates_project ~= setup
                          or plan.include_data ~= (snapshot.data ~= nil) then
                        return fail(tr('Binding preview failed; project settings were not changed.', '绑定预览失败，项目设置未更改。', '繫結預覽失敗，專案設定未變更。'))
                      end
                      local explanation = setup and tr('A new project configuration will bind this model and selected graph data. Training, losses and supervision remain declared in the graph and are not enabled by this binding.',
                        '将创建项目配置，绑定此模型和所选图数据。训练、损失与监督保留在图中，本次绑定不会启用它们。', '將建立專案設定，繫結此模型與所選圖資料。訓練、損失及監督保留在圖中，本次繫結不會啟用它們。')
                        or tr('One configuration update binds the generated model and selected graph data. Existing model parameters and injections will be cleared. Training, losses and supervision remain declared in the graph and are not enabled by this binding.',
                          '一次配置更新会绑定生成的模型和所选图数据，并清除原模型参数与组件注入。训练、损失与监督保留在图中，本次绑定不会启用它们。',
                          '一次設定更新會繫結產生的模型與所選圖資料，並清除原模型參數和元件注入。訓練、損失及監督保留在圖中，本次繫結不會啟用它們。')
                      show_review(tr('Bind graph to project', '将图绑定到项目', '將圖繫結至專案'), explanation .. '\n\n' .. vim.inspect(plan), true, function(accepted)
                        if not accepted or not stable() then return end
                        local tracked = begin_tracked_commit(state, tr('Bind graph project', '绑定图项目', '繫結圖專案'))
                        if not tracked then return end
                        local apply = vim.deepcopy(args); vim.list_extend(apply, {'--apply', '--if-plan', preview.data.plan_revision})
                        state.busy = tr('Binding graph project', '绑定图项目', '繫結圖專案'); render(state)
                        request(state, apply, function(result, failure)
                          state.busy = nil
                          local same = tracked_commit_current(state, tracked)
                          local valid_bind = not failure and result and result.operation == 'graph_bind' and result.status == 'success'
                            and type(result.data) == 'table' and result.data.committed == true
                            and result.data.plan_revision == preview.data.plan_revision
                            and sha256(result.data.config_revision) and result.data.config_revision == plan.candidate_revision
                          local settled_bind = settle_tracked_commit(state, tracked, valid_bind, failure)
                          if not same then return notify_tracked_context_changed(tracked) end
                          if valid_bind and settled_bind then
                            state.change_epoch = (state.change_epoch or 0) + 1
                            if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
                            refresh_project(state); render(state)
                            notify(tr('Graph project settings saved; model and data have not run.',
                              '图项目设置已保存；模型和数据尚未运行。', '圖專案設定已儲存；模型和資料尚未執行。'), vim.log.levels.INFO)
                          else fail(tr('Binding outcome needs inspection before retry.', '重试前请核查绑定结果。', '重試前請核查繫結結果。')) end
                        end)
                      end)
                    end)
                    return
                  end
                  if choice ~= 2 then return end
                  local function offer_data(saved_model)
                    if saved_model ~= entry or not snapshot.data or not current(snapshot)
                        or not state.project_info or state.project_info.model ~= entry then return end
                    vim.ui.select({tr('Review graph data', '审核图中的数据', '檢視圖中的資料'), tr('Later', '稍后', '稍後')}, {
                      prompt = tr('Model configured. Review the data already declared in this graph?',
                        '模型已配置。继续审核此图已声明的数据？', '模型已設定。繼續檢視此圖已宣告的資料？'),
                    }, function(_, selected)
                      if selected == 1 and current(snapshot) and state.project_info and state.project_info.model == entry
                          and project_config_current(state) then apply_graph_data(snapshot) end
                    end)
                  end
                  local _, latest_status = project_config(project)
                  if setup and latest_status == 'missing' then setup_existing(state, entry, offer_data)
                  elseif not setup and latest_status == 'present' then save_project_model(state, entry, offer_data)
                  else fail(tr('Project configuration changed; review it before continuing.', '项目配置已变化，请检查后继续。', '專案設定已變更，請檢查後繼續。')) end
                end)
            end
          else fail(tr('Operation outcome needs inspection before retry.', '重试前请核查操作结果。', '重試前請核查操作結果。')) end
        end, cleanup)
      end)
    end, cleanup)
  end
  local function verify_graph_source(snapshot, on_ready)
        if not current(snapshot) then return end
        local pending_buffers = dirty_buffers(project)
        if #pending_buffers == 0 then pending_buffers = reloads_pending(state) end
        if #pending_buffers > 0 then
          return offer_buffer_recovery(state, pending_buffers, tr('Choose a project buffer to inspect or reload before continuing.',
            '继续前请选择要检查或重新载入的项目缓冲区。', '繼續前請選擇要檢查或重新載入的專案緩衝區。'))
        end
        local info = state.project_info
        local model = info and info.model
        local module = type(model) == 'string' and model:match('^([%a_][%w_]*):model$') or nil
        if not module or session.base == 'absent' or not vim.deep_equal(snapshot, session.saved_doc)
            or (state.model and state.model ~= model) or open_buffer_conflict() or not project_config_current(state) then
          return fail(tr('Generate this saved graph and set its model as the project model before a trial.',
            '请先生成当前已保存图的源码，并设为项目模型，再准备试跑。', '請先產生目前已儲存圖的原始碼，並設為專案模型，再準備試跑。'))
        end
        local file_name, base, revision = module .. '.py', session.base, info.config_revision
        state.busy = tr('Checking graph source', '核对图源码', '核對圖原始碼'); render(state)
        request(state, {'graph-generate', '--graph', target, '--if-graph', base, '--output', file_name}, function(report, error)
          state.busy = nil; render(state)
          if not current(snapshot) or session.base ~= base or not state.project_info
              or state.project_info.config_revision ~= revision or not project_config_current(state)
              or #dirty_buffers(project) > 0 or #reloads_pending(state) > 0 or open_buffer_conflict() then
            return fail(tr('Graph or project changed; prepare the trial again.', '图或项目已变化，请重新准备试跑。', '圖或專案已變更，請重新準備試跑。'))
          end
          local data = report and report.data
          if error or not report or report.operation ~= 'graph_generate' or report.status ~= 'success'
              or type(data) ~= 'table' or data.committed ~= false or data.input_sha256 ~= base
              or type(data.plan) ~= 'table' or data.plan.output ~= file_name or data.plan.model ~= model
              or not sha256(data.source_sha256) or data.plan.source_sha256 ~= data.source_sha256 then
            return fail(tr('Cannot establish the saved graph source; inspect the project before a trial.',
              '无法核对已保存图的源码，请在试跑前检查项目。', '無法核對已儲存圖的原始碼，請在試跑前檢查專案。'))
          end
          local graph_stat = vim.uv.fs_lstat(target)
          local graph_file = graph_stat and graph_stat.type == 'file' and graph_stat.size <= 128 * 1024 and io.open(target, 'rb') or nil
          local graph_raw = graph_file and graph_file:read(128 * 1024 + 1) or nil
          if graph_file then graph_file:close() end
          if not graph_raw or #graph_raw > 128 * 1024 or vim.fn.sha256(graph_raw) ~= base then
            return fail(tr('Saved graph changed; prepare the trial again.', '已保存图发生变化，请重新准备试跑。', '已儲存圖發生變更，請重新準備試跑。'))
          end
          local path = project .. '/' .. file_name
          local stat = vim.uv.fs_lstat(path)
          local file = stat and stat.type == 'file' and stat.size <= 4 * 1024 * 1024 and io.open(path, 'rb') or nil
          local raw = file and file:read(4 * 1024 * 1024 + 1) or nil
          if file then file:close() end
          if not raw or #raw > 4 * 1024 * 1024 or vim.fn.sha256(raw) ~= data.source_sha256 then
            return fail(tr('Source differs from this graph. Use Generate to review a new file or a conditional update.',
              '源码与当前图不一致；请使用“生成”审核新文件或条件更新。', '原始碼與目前圖不一致；請使用「產生」檢視新檔案或條件更新。'))
          end
          session.source_check = {graph = base, model = model, config = revision,
            stat = {size = stat.size, dev = stat.dev, ino = stat.ino, mtime = stat.mtime, ctime = stat.ctime}}
          on_ready(module, data)
        end)
  end
  local function graph_project_data_matches(snapshot)
    if not snapshot.data then return false end
    local config = project_config(project)
    local binding = type(config) == 'table' and config.batch_binding or nil
    if binding == vim.NIL then binding = nil end
    return type(config) == 'table' and config.batch == snapshot.data.factory
      and binding == snapshot.data.binding and vim.deep_equal(config.batch_params or {}, snapshot.data.params or {})
  end
  local function graph_data_matches(snapshot)
    return graph_project_data_matches(snapshot) and state.batch == nil
      and state.batch_binding == nil and next(state.batch_params or {}) == nil
  end
  local function graph_source_status(snapshot)
    local checked, info = session.source_check, state.project_info
    if not checked or not info or session.base ~= checked.graph or info.model ~= checked.model
        or info.config_revision ~= checked.config or not vim.deep_equal(snapshot, session.saved_doc) then return 'unknown' end
    local module = type(info.model) == 'string' and info.model:match('^([%a_][%w_]*):model$') or nil
    local stat = module and vim.uv.fs_lstat(project .. '/' .. module .. '.py') or nil
    if not stat or stat.type ~= 'file' then return 'unknown' end
    local identity = {size = stat.size, dev = stat.dev, ino = stat.ino, mtime = stat.mtime, ctime = stat.ctime}
    return vim.deep_equal(identity, checked.stat) and 'last_checked' or 'unknown'
  end
  local function graph_rules_notice(snapshot)
    local count = 0
    for _, node in ipairs(snapshot.nodes or {}) do
      for _, rules in pairs(node.draft_rules or {}) do count = count + #rules end
    end
    local notice = ''
    if count > 0 then
      notice = notice .. tr('\nGraph draft rules not automatically enforced: ', '\n图中的草稿规则不会自动生效：', '\n圖中的草稿規則不會自動生效：') .. count
    end
    if snapshot.supervision then
      notice = notice .. tr('\nLinked supervision is not automatically imported or rebound; review the currently bound rules.',
        '\n关联的监督文件不会自动导入或重绑定；请审核当前已绑定的规则。',
        '\n連結的監督檔案不會自動匯入或重新繫結；請檢視目前已繫結的規則。')
    end
    return notice
  end
  local data_status_cache
  local function graph_data_status(snapshot)
    if not snapshot.data then return 'not_declared' end
    if state.project_status == 'unconfigured' then return 'project_missing' end
    if state.project_status ~= 'configured' or not state.config_file_digest then return 'unknown' end
    local stat = vim.uv.fs_lstat(project .. '/.model-maven/project.json')
    if not stat or stat.type ~= 'file' then data_status_cache = nil; return 'unknown' end
    local identity = {size = stat.size, dev = stat.dev, ino = stat.ino, mtime = stat.mtime, ctime = stat.ctime}
    if not data_status_cache or not vim.deep_equal(data_status_cache.identity, identity) then
      local config, status, digest = project_config(project)
      data_status_cache = {identity = identity, config = config, status = status, digest = digest}
    end
    if data_status_cache.status ~= 'present' or data_status_cache.digest ~= state.config_file_digest then return 'unknown' end
    local config, data = data_status_cache.config, snapshot.data
    local binding = config.batch_binding
    if binding == vim.NIL then binding = nil end
    if config.batch ~= data.factory or binding ~= data.binding or not vim.deep_equal(config.batch_params or {}, data.params or {}) then
      return 'different'
    end
    if state.batch ~= nil or state.batch_binding ~= nil or next(state.batch_params or {}) ~= nil then return 'session_override' end
    return 'matching'
  end
  local function graph_revision_guard(snapshot, generated, require_data)
    local source_name, source_hash, base = generated.plan.output, generated.source_sha256, session.base
    return function()
      if not current(snapshot) or session.base ~= base or not project_config_current(state)
          or #dirty_buffers(project) > 0 or #reloads_pending(state) > 0 or open_buffer_conflict()
          or (require_data and not graph_data_matches(snapshot)) then return false end
      local function matches(path, limit, expected)
        local stat = vim.uv.fs_lstat(path)
        if not stat or stat.type ~= 'file' or stat.size > limit then return false end
        local file = io.open(path, 'rb'); local raw = file and file:read(limit + 1) or nil
        if file then file:close() end
        return raw ~= nil and #raw <= limit and vim.fn.sha256(raw) == expected
      end
      return matches(target, 128 * 1024, base) and matches(project .. '/' .. source_name, 4 * 1024 * 1024, source_hash)
    end
  end
  apply_graph_data = function(snapshot, on_saved)
    if not current(snapshot) then return end
    if not snapshot.data then return fail(tr('Configure data on an input or output node first.', '请先在输入或输出节点配置数据。', '請先在輸入或輸出節點設定資料。')) end
    local function saved_graph_current()
      if session.base == 'absent' or not vim.deep_equal(snapshot, session.saved_doc) then return false end
      local stat = vim.uv.fs_lstat(target)
      if not stat or stat.type ~= 'file' or stat.size > 128 * 1024 then return false end
      local file = io.open(target, 'rb')
      local raw = file and file:read(128 * 1024 + 1) or nil
      if file then file:close() end
      return raw ~= nil and #raw <= 128 * 1024 and vim.fn.sha256(raw) == session.base
    end
    if not saved_graph_current() then
      return fail(tr('Save the graph before applying its data configuration.', '应用数据配置前请先保存图。', '套用資料設定前請先儲存圖。'))
    end
    save_project_input(state, false, vim.deepcopy(snapshot.data), function()
      return not state.closed and state.opts.project == project and state.opts.cli == cli
        and state.graph_canvas == session and vim.deep_equal(session.draft, snapshot) and saved_graph_current()
    end, on_saved)
  end
  local function ensure_graph_data(snapshot, on_ready)
    if graph_data_matches(snapshot) then return on_ready() end
    if not snapshot.data then
      local previous_batch, previous_binding, previous_params = state.batch, state.batch_binding, vim.deepcopy(state.batch_params or {})
      vim.ui.select({tr('Use current project/session input', '使用当前项目或会话输入', '使用目前專案或工作階段輸入'), tr('Cancel', '取消', '取消')}, {
        prompt = tr('This graph has no declared data. Current input compatibility is unverified.',
          '图中尚未声明数据。当前输入与模型是否兼容尚未验证。', '圖中尚未宣告資料。目前輸入與模型是否相容尚未驗證。'),
      }, function(_, choice)
        if choice ~= 1 or not current(snapshot) or not project_config_current(state)
            or state.batch ~= previous_batch or state.batch_binding ~= previous_binding
            or not vim.deep_equal(state.batch_params or {}, previous_params) then return end
        on_ready()
      end)
      return
    end
    if graph_project_data_matches(snapshot) then
      local previous_batch, previous_binding, previous_params = state.batch, state.batch_binding, vim.deepcopy(state.batch_params or {})
      vim.ui.select({tr('Clear session input overrides', '清除会话输入覆盖', '清除工作階段輸入覆蓋'), tr('Cancel', '取消', '取消')}, {
        prompt = tr('Project data matches the graph; session overrides would change this run.',
          '项目数据与图一致；会话输入覆盖会改变本次运行。', '專案資料與圖一致；工作階段輸入覆蓋會改變這次執行。'),
      }, function(_, choice)
        if choice ~= 1 or not current(snapshot) or not project_config_current(state) or not graph_project_data_matches(snapshot)
            or state.batch ~= previous_batch or state.batch_binding ~= previous_binding
            or not vim.deep_equal(state.batch_params or {}, previous_params) then return end
        state.batch, state.batch_binding, state.batch_params = nil, nil, {}
        state.change_epoch = (state.change_epoch or 0) + 1
        render(state)
        if current(snapshot) and project_config_current(state) and graph_data_matches(snapshot) then
          on_ready()
        else
          fail(tr('Input changed while clearing overrides; review it before continuing.',
            '清除覆盖时输入发生变化，请检查后再继续。', '清除覆蓋時輸入發生變化，請檢查後再繼續。'))
        end
      end)
      return
    end
    vim.ui.select({tr('Review graph data for this project', '审核并应用图数据', '審核並套用圖資料'), tr('Cancel', '取消', '取消')}, {
      prompt = tr('Project data differs; review the change before running. Session overrides must also be cleared.',
        '项目数据不一致；运行前请审核变更，并清除会话输入覆盖。', '專案資料不一致；執行前請審核變更，並清除工作階段輸入覆蓋。'),
    }, function(_, choice)
      if choice == 1 and current(snapshot) then
        apply_graph_data(snapshot, function()
          verify_graph_source(snapshot, function()
            if graph_data_matches(snapshot) then on_ready()
            else fail(tr('Input changed after saving; review it before continuing.',
              '保存后输入发生变化，请检查后再继续。', '儲存後輸入發生變化，請檢查後再繼續。')) end
          end)
        end)
      end
    end)
  end
  local function source_is_on_right()
    local win = state.code_win
    local position = win and vim.api.nvim_win_is_valid(win) and vim.api.nvim_win_get_position(win) or nil
    return position ~= nil and position[2] >= math.floor(vim.o.columns / 2)
  end
  session.ui_helpers = {graph_data_status = graph_data_status, graph_source_status = graph_source_status,
    checkpoint_layout = checkpoint_layout, verify_graph_source = verify_graph_source, source_is_on_right = source_is_on_right}
  session.ui_locale = locale
  state.busy = tr('Checking graph support', '检查图能力', '檢查圖能力'); render(state)
  for name, value in pairs({context = context, fail = fail, open_buffer_conflict = open_buffer_conflict, normalize_graph_options = normalize_graph_options, checkpoint = checkpoint, temp = temp, show_review = show_review, reconcile = reconcile, graph_data_matches = graph_data_matches, graph_rules_notice = graph_rules_notice, graph_revision_guard = graph_revision_guard, ensure_graph_data = ensure_graph_data}) do session.ui_helpers[name] = value end
  request(state, {'--describe-interface'}, function(report, error)
    state.busy = nil; render(state)
    if not session.ui_helpers.context() or error or not report or report.status ~= 'success' or report.operation ~= 'interface'
        or type(report.data) ~= 'table' or type(report.data.capabilities) ~= 'table'
        or report.data.capabilities['project.graph_topology_plan_v1'] ~= true
        or report.data.capabilities['project.graph_edit_batch_plan_v1'] ~= true
        or report.data.capabilities['project.graph_boundary_annotations_v1'] ~= true
        or report.data.capabilities['project.graph_data_objectives_v1'] ~= true
        or report.data.capabilities['project.graph_edit_settings_v1'] ~= true
        or report.data.capabilities['project.graph_edit_group_set_v1'] ~= true
        or report.data.capabilities['project.graph_save_v1'] ~= true
        or report.data.capabilities['project.graph_source_create_v1'] ~= true then
      return session.ui_helpers.fail(tr('Select a CLI that supports graph edit planning and saving.', '请选择支持图编辑规划与保存的 CLI。', '請選擇支援圖編輯規劃與儲存的 CLI。'))
    end
    if session.draft.legacy_import and report.data.capabilities['project.graph_legacy_snapshot_v1'] ~= true then
      return session.ui_helpers.fail(tr('This graph retains a legacy declaration; select a CLI that supports its snapshot.',
        '此图保留了旧声明，请选择支持旧声明快照的 CLI。', '此圖保留了舊宣告，請選擇支援舊宣告快照的 CLI。'))
    end
    local caps = report.data.capabilities
    if session.draft.component_storage and caps['project.graph_named_components_v1'] ~= true then
      return session.ui_helpers.fail(tr('Select a CLI that supports named component storage.', '请选择支持具名组件存储的 CLI。', '請選擇支援具名元件儲存的 CLI。'))
    end
    if session.draft.supervision and caps['project.graph_supervision_reference_v1'] ~= true then
      return session.ui_helpers.fail(tr('Select a CLI that supports supervision references.', '请选择支持监督引用的 CLI。', '請選擇支援監督參照的 CLI。'))
    end
    if session.draft.training then
      local training = session.draft.training
      if (training.mode ~= nil and training.mode ~= 'managed-step') and caps['project.graph_training_modes_v1'] ~= true then
        return session.ui_helpers.fail(tr('Select a CLI that supports this training mode.', '请选择支持此训练模式的 CLI。', '請選擇支援此訓練模式的 CLI。'))
      end
      if (training.step ~= nil or (training.step_params and next(training.step_params)))
          and caps['project.graph_training_step_v1'] ~= true then
        return session.ui_helpers.fail(tr('Select a CLI that supports declared training steps.', '请选择支持声明训练步骤的 CLI。', '請選擇支援宣告訓練步驟的 CLI。'))
      end
    end
    for _, node in ipairs(session.draft.nodes) do
      if (next(node.input_shapes or {}) or next(node.output_shapes or {})) and caps['project.graph_declared_shapes_v1'] ~= true then
        return session.ui_helpers.fail(tr('Select a CLI that supports declared port shapes.', '请选择支持声明端口形状的 CLI。', '請選擇支援宣告連接埠形狀的 CLI。'))
      end
      if (node.kind == 'add' or node.kind == 'concat') and next(node.output_shapes or {})
          and caps['project.graph_merge_output_shapes_v1'] ~= true then
        return session.ui_helpers.fail(tr('Select a CLI that supports merge output shapes.', '请选择支持汇合输出形状的 CLI。', '請選擇支援匯合輸出形狀的 CLI。'))
      end
      if (next(node.input_dtypes or {}) or next(node.output_dtypes or {})) and caps['project.graph_port_dtype_v1'] ~= true then
        return session.ui_helpers.fail(tr('Select a CLI that supports declared port dtypes.', '请选择支持声明端口类型的 CLI。', '請選擇支援宣告連接埠型別的 CLI。'))
      end
      if node.output_style and caps['project.graph_call_output_style_v1'] ~= true then
        return session.ui_helpers.fail(tr('Select a CLI that supports component output mapping.', '请选择支持组件输出映射的 CLI。', '請選擇支援元件輸出對應的 CLI。'))
      end
    end
    if report.data.capabilities['project.graph_cast_parameter_dtype_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.kind == 'cast' then
          return session.ui_helpers.fail(tr('Select a CLI that supports this dtype conversion node.',
            '请选择支持此类型转换节点的 CLI。', '請選擇支援此型別轉換節點的 CLI。'))
        end
      end
    end
    if report.data.capabilities['project.graph_dynamic_mean_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.kind == 'mean_dynamic' then
          return session.ui_helpers.fail(tr('Select a CLI that supports dynamic-axis reduction.',
            '请选择支持动态轴归约的 CLI。', '請選擇支援動態軸歸約的 CLI。'))
        end
      end
    end
    if report.data.capabilities['project.graph_factory_contract_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.kind == 'assert_flat' or (node.dtype_definitions and #node.dtype_definitions > 0) then
          return session.ui_helpers.fail(tr('Select a CLI that supports factory-layer contracts.',
            '请选择支持工厂层契约的 CLI。', '請選擇支援工廠層契約的 CLI。'))
        end
      end
    end
    if report.data.capabilities['project.graph_dtype_sequence_guard_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.track_sequence then return session.ui_helpers.fail(tr('Select a CLI that supports dtype sequence tracking.',
          '请选择支持类型来源顺序跟踪的 CLI。', '請選擇支援型別來源順序追蹤的 CLI。')) end
      end
    end
    if report.data.capabilities['project.graph_clone_node_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.kind == 'clone' then return session.ui_helpers.fail(tr('Select a CLI that supports branch copies.',
          '请选择支持分支复制的 CLI。', '請選擇支援分支複製的 CLI。')) end
      end
    end
    if report.data.capabilities['project.graph_assert_batch_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.kind == 'assert_batch' then return session.ui_helpers.fail(tr('Select a CLI that supports batch contract checks.',
          '请选择支持批次契约检查的 CLI。', '請選擇支援批次契約檢查的 CLI。')) end
      end
    end
    if report.data.capabilities['project.graph_after_node_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.kind == 'after' then return session.ui_helpers.fail(tr('Select a CLI that supports ordered branches.',
          '请选择支持分支顺序的 CLI。', '請選擇支援分支順序的 CLI。')) end
      end
    end
    if report.data.capabilities['project.graph_list_call_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.call_style == 'list' then return session.ui_helpers.fail(tr('Select a CLI that supports list-style component calls.',
          '请选择支持列表参数调用的 CLI。', '請選擇支援清單參數呼叫的 CLI。')) end
      end
    end
    if report.data.capabilities['project.graph_output_name_v1'] ~= true then
      for _, node in ipairs(session.draft.nodes) do
        if node.output_name then return session.ui_helpers.fail(tr('Select a CLI that supports named graph outputs.',
          '请选择支持图输出名称的 CLI。', '請選擇支援圖輸出名稱的 CLI。')) end
      end
    end
    if session.draft.training and report.data.capabilities['project.graph_optional_training_v1'] ~= true
        and (session.draft.training.trial_steps == nil or session.draft.training.optimizer == nil
          or session.draft.training.step == '$model:step') then
      return session.ui_helpers.fail(tr('Select a CLI that supports this training declaration.',
        '请选择支持此训练声明的 CLI。', '請選擇支援此訓練宣告的 CLI。'))
    end
    if report.data.capabilities['project.graph_unicode_ids_v1'] ~= true then
      local function non_ascii(value) return type(value) == 'string' and value:find('[\128-\255]') ~= nil end
      local unicode = false
      for _, node in ipairs(session.draft.nodes) do
        unicode = unicode or non_ascii(node.id) or non_ascii(node.definition)
        for _, port in ipairs(node.inputs or {}) do unicode = unicode or non_ascii(port) end
        for _, port in ipairs(node.outputs or {}) do unicode = unicode or non_ascii(port) end
        for _, id in ipairs(node.dtype_definitions or {}) do unicode = unicode or non_ascii(id) end
      end
      for _, definition in ipairs(session.draft.definitions or {}) do unicode = unicode or non_ascii(definition.id) end
      for _, objective in ipairs(session.draft.objectives or {}) do unicode = unicode or non_ascii(objective.output) or non_ascii(objective.target) end
      for _, group in ipairs(session.draft.groups or {}) do
        unicode = unicode or non_ascii(group.id) or non_ascii(group.parent)
        for _, id in ipairs(group.nodes or {}) do unicode = unicode or non_ascii(id) end
      end
      if unicode then return session.ui_helpers.fail(tr('Select a CLI that supports Unicode graph identifiers.',
        '请选择支持 Unicode 图标识的 CLI。', '請選擇支援 Unicode 圖識別碼的 CLI。')) end
    end
    if report.data.capabilities['project.graph_runtime_containers_v1'] ~= true then
      for _, definition in ipairs(session.draft.definitions or {}) do
        if definition.children and #definition.children > 0 then return session.ui_helpers.fail(tr('Select a CLI that supports runtime container children.',
          '请选择支持运行时容器子组件的 CLI。', '請選擇支援執行時容器子元件的 CLI。')) end
      end
    end
    if report.data.capabilities['project.graph_container_list_children_v1'] ~= true then
      for _, definition in ipairs(session.draft.definitions or {}) do
        if definition.children_style == 'list' then return session.ui_helpers.fail(tr('Select a CLI that supports list-style container children.',
          '请选择支持列表式容器子组件的 CLI。', '請選擇支援清單式容器子元件的 CLI。')) end
      end
    end
    if session.draft.data and session.draft.data.factory == 'model_maven_worker.data.pipeline:batch'
        and report.data.capabilities['project.graph_generic_batch_transforms_v1'] ~= true then
      return session.ui_helpers.fail(tr('This graph uses a batch transform pipeline; select a CLI that supports it.',
        '此图使用批次变换流水线，请选择支持该功能的 CLI。', '此圖使用批次變換流水線，請選擇支援此功能的 CLI。'))
    end
    session.capabilities = vim.deepcopy(report.data.capabilities)
    require('model_maven.model_preview').refresh(state)
    require('model_maven.graph_canvas').open(session.draft, {
      tr = tr,
      preview_boundary = function()
        local view = state.model_preview
        if view and vim.api.nvim_win_is_valid(view.win) and vim.api.nvim_win_get_tabpage(view.win) == state.tab then
          return vim.api.nvim_win_get_position(view.win)[2]
        end
      end,
      is_saved = function(snapshot)
        return session.base ~= 'absent' and vim.deep_equal(snapshot, session.saved_doc)
      end,
      merge_output_shapes = report.data.capabilities['project.graph_merge_output_shapes_v1'] == true,
      port_dtypes = report.data.capabilities['project.graph_port_dtype_v1'] == true,
      call_output_style = report.data.capabilities['project.graph_call_output_style_v1'] == true,
      named_components = report.data.capabilities['project.graph_named_components_v1'] == true,
      reorder_after = report.data.capabilities['project.graph_reorder_after_v1'] == true,
      factory_contract = report.data.capabilities['project.graph_factory_contract_v1'] == true,
      list_call = report.data.capabilities['project.graph_list_call_v1'] == true,
      output_name = report.data.capabilities['project.graph_output_name_v1'] == true,
      dtype_sequence_guard = report.data.capabilities['project.graph_dtype_sequence_guard_v1'] == true,
      reorder_dtype_sync = report.data.capabilities['project.graph_reorder_dtype_sync_v1'] == true,
      edit_group_copy = report.data.capabilities['project.graph_edit_group_copy_v1'] == true,
      edit_group_set = report.data.capabilities['project.graph_edit_group_set_v1'] == true,
      runtime_containers = report.data.capabilities['project.graph_runtime_containers_v1'] == true,
      container_list_children = report.data.capabilities['project.graph_container_list_children_v1'] == true,
      generic_batch_transforms = report.data.capabilities['project.graph_generic_batch_transforms_v1'] == true,
      edit_graph_settings = report.data.capabilities['project.graph_edit_settings_v1'] == true,
      workspace_source = function(snapshot, done)
        if not current(snapshot) then return end
        open_source(state, function()
          if current(snapshot) and done then
            done(session.ui_helpers.source_is_on_right())
          end
        end)
      end,
      plan_edits = report.data.capabilities['project.graph_edit_batch_plan_v1'] == true and function(snapshot, operations, done)
        if not current(snapshot) or state.busy then return done(nil, tr('Graph or workspace changed.', '图或工作区已变化。', '圖或工作區已變更。')) end
        local path, digest = session.ui_helpers.temp(snapshot)
        local operations_path, operations_digest = session.ui_helpers.temp(operations)
        if not path or not operations_path then
          if path then vim.uv.fs_unlink(path) end
          if operations_path then vim.uv.fs_unlink(operations_path) end
          return done(nil, tr('Cannot prepare the graph edit.', '无法准备图编辑。', '無法準備圖編輯。'))
        end
        local function cleanup() vim.uv.fs_unlink(path); vim.uv.fs_unlink(operations_path) end
        state.busy = tr('Planning graph edit', '规划图编辑', '規劃圖編輯'); render(state)
        request(state, {'graph-edit-plan', '--graph', path, '--if-graph', digest,
          '--operations', operations_path, '--if-operations', operations_digest}, function(result, failure)
          cleanup(); state.busy = nil; render(state)
          if not current(snapshot) then return done(nil, tr('Graph changed; plan again.', '图已变化，请重新规划。', '圖已變更，請重新規劃。')) end
          local data = result and result.data
          if failure or not result or result.operation ~= 'graph_edit_plan' or result.status ~= 'success'
              or type(data) ~= 'table' or data.committed ~= false or data.input_sha256 ~= digest
              or data.operations_sha256 ~= operations_digest or type(data.graph) ~= 'table'
              or type(data.outcomes) ~= 'table' or #data.outcomes ~= #operations then
            local diagnostic = result and type(result.diagnostics) == 'table' and result.diagnostics[1]
            return done(nil, session.ui_locale.graph_diagnostic(diagnostic,
              tr('The backend could not plan this edit.', '后端无法规划此次编辑。', '後端無法規劃這次編輯。')))
          end
          for index, operation in ipairs(operations) do
            if type(data.outcomes[index]) ~= 'table' or data.outcomes[index].action ~= operation.action then
              return done(nil, tr('Backend operation order differs.', '后端操作顺序不一致。', '後端操作順序不一致。'))
            end
          end
          local review = data.structural_review
          local diagnostic = type(review) == 'table' and review.status ~= 'success'
            and type(review.diagnostics) == 'table' and review.diagnostics[1] or nil
          if type(review) ~= 'table' or (review.status ~= 'success'
              and (type(diagnostic) ~= 'table' or not vim.tbl_contains({'GRAPH_SHAPE_CONFLICT', 'GRAPH_DTYPE_ORDER_CONFLICT', 'GRAPH_AXIS_INVALID'}, diagnostic.code))) then
            return done(nil, tr('Backend structural review is invalid.', '后端结构检查结果无效。', '後端結構檢查結果無效。'))
          end
          local warning = diagnostic and session.ui_locale.graph_diagnostic(diagnostic, nil) or nil
          done(session.ui_helpers.normalize_graph_options(data.graph), nil, warning)
        end, cleanup)
      end or nil,
      plan_reorder = function(snapshot, node, anchor, after, done)
        if not current(snapshot) or state.busy then return done(nil, tr('Graph or workspace changed.', '图或工作区已变化。', '圖或工作區已變更。')) end
        if report.data.capabilities['project.graph_reorder_plan_v1'] ~= true then
          return done(nil, tr('The selected CLI does not support graph reorder planning.', '所选 CLI 不支持图重排规划。', '所選 CLI 不支援圖重排規劃。'))
        end
        if after and report.data.capabilities['project.graph_reorder_after_v1'] ~= true then
          return done(nil, tr('The selected CLI cannot plan insertion after a node.', '所选 CLI 不支持规划插入到节点之后。', '所選 CLI 不支援規劃插入至節點之後。'))
        end
        local path, digest = session.ui_helpers.temp(snapshot)
        if not path then return done(nil, tr('Cannot prepare the graph draft.', '无法准备图草稿。', '無法準備圖草稿。')) end
        state.busy = tr('Planning graph reorder', '规划图重排', '規劃圖重排'); render(state)
        request(state, {'graph-reorder-plan', '--graph', path, '--if-graph', digest, '--node', node, after and '--after' or '--before', anchor}, function(result, failure)
          vim.uv.fs_unlink(path)
          state.busy = nil; render(state)
          if not current(snapshot) then return done(nil, tr('Graph changed; plan again.', '图已变化，请重新规划。', '圖已變更，請重新規劃。')) end
          local data = result and result.data
          if failure or not result or result.operation ~= 'graph_reorder_plan' or result.status ~= 'success'
              or type(data) ~= 'table' or data.committed ~= false or data.input_sha256 ~= digest or type(data.graph) ~= 'table' then
            local diagnostic = result and type(result.diagnostics) == 'table' and result.diagnostics[1]
            return done(nil, session.ui_locale.graph_diagnostic(diagnostic,
              tr('The backend could not plan this reorder.', '后端无法规划此次重排。', '後端無法規劃這次重排。')))
          end
          done(data.graph)
        end)
      end,
      metadata_context = function()
        local _, status, digest = project_config(project)
        local roots_ok, roots = pcall(vim.json.encode, state.opts.project_import_roots or {})
        local env_ok, environment = pcall(vim.fn.environ)
        local environment_digest
        if env_ok and type(environment) == 'table' then
          local names, entries = vim.tbl_keys(environment), {}
          table.sort(names)
          for _, name in ipairs(names) do entries[#entries + 1] = {name, environment[name]} end
          local encoded, serialized = pcall(vim.json.encode, entries)
          if encoded then environment_digest = vim.fn.sha256(serialized) end
        end
        if not environment_digest then
          -- Unknown session.ui_helpers.context must invalidate earlier metadata, not reuse it.
          environment_digest = 'unknown:' .. tostring(vim.uv.hrtime())
        end
        return table.concat({tostring(state.change_epoch or 0), tostring(state.opts.python or ''), tostring(state.opts.cli or ''),
          tostring(state.project_info and state.project_info.runtime_python or ''), tostring(state.opts.working_directory or ''),
          roots_ok and roots or '?', tostring(status or ''), tostring(digest or ''), environment_digest}, '\0')
      end,
      layout_order = session.layout_order,
      collapsed_groups = session.layout_collapsed,
      layout_positions = session.layout_positions,
      layout_view = session.layout_view,
      history = session.history,
      input_drafts = (function()
        session.input_drafts = session.input_drafts or {}
        return session.input_drafts
      end)(),
      history_changed = function(history)
        if state.graph_canvas == session then session.history = history; session.ui_helpers.checkpoint(false) end
      end,
      data_status = session.ui_helpers.graph_data_status,
      source_status = session.ui_helpers.graph_source_status,
      language = function(snapshot, callback)
        if not current(snapshot) then return end
        session.ui_locale.choose(function()
          if not current(snapshot) then return end
          render(state)
          if callback then callback(tr('Language updated.', '语言已更新。', '語言已更新。')) end
        end)
      end,
      check_source = function(snapshot, callback)
        session.ui_helpers.verify_graph_source(snapshot, function()
          if callback then callback(tr('Graph source matched at the last check; run will check again.',
            '上次检查时图与源码匹配；运行前会再次核对。', '上次檢查時圖與原始碼相符；執行前會再次核對。')) end
        end)
      end,
      view_changed = function(view, force)
        if state.graph_canvas ~= session then return end
        if vim.deep_equal(session.layout_view, view) then
          if force then session.ui_helpers.checkpoint_layout(true) end
          return
        end
        session.layout_view = view
        session.ui_helpers.checkpoint_layout(force == true)
      end,
      layout_changed = function(order, collapsed, positions)
        session.layout_order, session.layout_collapsed, session.layout_positions = order, collapsed, positions
        session.ui_helpers.checkpoint_layout(false)
      end,
      changed = function() session.ui_helpers.checkpoint(false); require('model_maven.model_preview').refresh(state) end,
      checkpoint = function(force) session.ui_helpers.checkpoint(force); session.ui_helpers.checkpoint_layout(force) end,
      reconcile = session.ui_helpers.reconcile,
      environment = function(snapshot)
        if current(snapshot) and state.actions and state.actions.e then state.actions.e() end
      end,
      open_generated_node = function(snapshot, node_id, done)
        session.ui_helpers.verify_graph_source(snapshot, function(module, generated)
          local line = type(generated.node_lines) == 'table' and generated.node_lines[node_id] or nil
          if type(line) ~= 'number' or line < 1 or line % 1 ~= 0 then
            return session.ui_helpers.fail(tr('No generated source location is available for this node.', '此节点没有可用的生成源码位置。', '此節點沒有可用的產生原始碼位置。'))
          end
          local guard = session.ui_helpers.graph_revision_guard(snapshot, generated, false)
          if not guard() then return session.ui_helpers.fail(tr('Graph or source changed; check again.', '图或源码已变化，请重新核对。', '圖或原始碼已變更，請重新核對。')) end
          local path = project .. '/' .. module .. '.py'
          if not focus_source(state, path) or not guard() then return end
          local win = vim.api.nvim_get_current_win()
          local buf = vim.api.nvim_win_get_buf(win)
          if vim.bo[buf].modified or vim.api.nvim_buf_line_count(buf) < line then
            return session.ui_helpers.fail(tr('Source buffer changed; location is no longer certain.', '源码缓冲区已变化，无法确定位置。', '原始碼緩衝區已變更，無法確定位置。'))
          end
          vim.api.nvim_win_set_cursor(win, {line, 0})
          vim.api.nvim_win_call(win, function() vim.cmd('normal! zz') end)
          if done then done(session.ui_helpers.source_is_on_right()) end
        end)
      end,
      source_to_node = function(snapshot, callback)
        local win = state.code_win
        if not win or not vim.api.nvim_win_is_valid(win) then
          return session.ui_helpers.fail(tr('Open the generated source and select a line first.', '请先打开生成源码并选择一行。', '請先開啟產生的原始碼並選擇一行。'))
        end
        local buffer, line = vim.api.nvim_win_get_buf(win), vim.api.nvim_win_get_cursor(win)[1]
        local path = vim.uv.fs_realpath(vim.api.nvim_buf_get_name(buffer))
        if vim.bo[buffer].modified or not path then return session.ui_helpers.fail(tr('Save or session.ui_helpers.reconcile the source buffer first.', '请先保存或处理源码缓冲区。', '請先儲存或處理原始碼緩衝區。')) end
        session.ui_helpers.verify_graph_source(snapshot, function(module, generated)
          if not vim.api.nvim_win_is_valid(win) or vim.api.nvim_win_get_buf(win) ~= buffer
              or vim.api.nvim_win_get_cursor(win)[1] ~= line or vim.bo[buffer].modified
              or path ~= vim.uv.fs_realpath(project .. '/' .. module .. '.py') then
            return session.ui_helpers.fail(tr('Source selection changed; select the line again.', '源码选择已变化，请重新选择行。', '原始碼選擇已變更，請重新選擇列。'))
          end
          local ending
          for index, text in ipairs(vim.split(generated.source or '', '\n', {plain = true})) do
            if text == '        return outputs' then ending = index; break end
          end
          local id, start
          for node, value in pairs(type(generated.node_lines) == 'table' and generated.node_lines or {}) do
            if type(value) == 'number' and value <= line and ending and line < ending and (not start or value > start) then id, start = node, value end
          end
          if not id then return session.ui_helpers.fail(tr('Select a generated forward node line.', '请选择生成的前向节点代码行。', '請選擇產生的前向節點程式碼列。')) end
          if callback then callback(tr('Selected the corresponding generated graph node.', '已选中对应的生成图节点。', '已選取對應的產生圖節點。'), id) end
        end)
      end,
      open_component_source = function(snapshot, reference, done)
        if not current(snapshot) or type(reference) ~= 'string' then return end
        local module = reference:match('^([^:]+):[^:]+$')
        local parts = module and vim.split(module, '.', {plain = true}) or {}
        local candidates, seen = {}, {}
        local valid = #parts > 0
        for _, part in ipairs(parts) do if not module_part_candidate(part) then valid = false end end
        if valid then
          local roots = vim.deepcopy(state.opts.project_import_roots or {}); roots[#roots + 1] = ''
          for _, root in ipairs(roots) do
            local base = project .. '/' .. (root ~= '' and root .. '/' or '') .. table.concat(parts, '/')
            for _, candidate in ipairs({base .. '.py', base .. '/__init__.py'}) do
              local path = vim.uv.fs_realpath(candidate)
              if path and in_project(project, path) and vim.fn.filereadable(path) == 1 and not seen[path] then
                seen[path] = true; candidates[#candidates + 1] = path
              end
            end
          end
        end
        local choices = vim.deepcopy(candidates)
        choices[#choices + 1] = tr('Choose a project file…', '选择项目文件…', '選擇專案檔案…')
        vim.ui.select(choices, {prompt = tr('Static source candidates; runtime origin is not verified',
          '静态源码候选；尚未验证运行时来源', '靜態原始碼候選；尚未驗證執行時來源')}, function(_, index)
          if not index or not current(snapshot) then return end
          local function open(path)
            if not path or not current(snapshot) then return end
            local absolute = path:sub(1, 1) == '/' and path or project .. '/' .. path
            local real = vim.uv.fs_realpath(absolute)
            if not real or not in_project(project, real) or vim.fn.filereadable(real) ~= 1 then
              return session.ui_helpers.fail(tr('Choose a readable file inside this project.', '请选择项目内可读取的文件。', '請選擇專案內可讀取的檔案。'))
            end
            if focus_source(state, real) and current(snapshot) and done then done(session.ui_helpers.source_is_on_right()) end
          end
          if index <= #candidates then open(candidates[index])
          else vim.ui.input({prompt = tr('Project source file: ', '项目源码文件：', '專案原始碼檔案：'), completion = 'file'}, open) end
        end)
      end,
      configure_training = function(snapshot, done)
        if not current(snapshot) or not project_config_current(state) then return end
        local old = snapshot.training
        vim.ui.input({prompt = tr('Trial steps (1–1000): ', '试跑步数（1–1000）：', '試跑步數（1–1000）：'),
          default = tostring(old and old.trial_steps or 1)}, function(raw)
          if not raw or not current(snapshot) or not project_config_current(state) then return end
          local steps = raw:match('^%d+$') and tonumber(raw) or nil
          if not steps or steps < 1 or steps > 1000 then return session.ui_helpers.fail(tr('Enter a trial count from 1 to 1000.', '请输入 1 到 1000 的试跑步数。', '請輸入 1 到 1000 的試跑步數。')) end
          local function optimizer_for(step, params, mode)
            mode = mode or 'managed-step'
            local function finish_optimizer(optimizer)
              if not current(snapshot) or not project_config_current(state) then return end
              if not optimizer then return session.ui_helpers.fail(tr('Optimizer settings cannot be saved.', '无法保存优化器设置。', '無法儲存最佳化器設定。')) end
              local training = {trial_steps = steps, optimizer = optimizer}
              if mode ~= 'managed-step' then training.mode = mode end
              if step then training.step = step end
              if params and next(params) then training.step_params = params end
              done(training)
            end
            if mode == 'external-loop' then return finish_optimizer(vim.empty_dict()) end
            local function choose_new()
              choose_optimizer_parameters(mode, function(args) finish_optimizer(optimizer_profile(args)) end)
            end
            if not old or not old.optimizer or (old.mode or 'managed-step') ~= mode then return choose_new() end
            vim.ui.select({tr('Keep current optimizer', '保留当前优化器', '保留目前最佳化器'),
              tr('Choose another optimizer', '重新选择优化器', '重新選擇最佳化器')}, {
              prompt = tr('Optimizer for this graph', '此图使用的优化器', '此圖使用的最佳化器'),
            }, function(_, choice)
              if not current(snapshot) or not project_config_current(state) then return end
              if choice == 1 then finish_optimizer(vim.deepcopy(old.optimizer)) elseif choice == 2 then choose_new() end
            end)
          end
          if report.data.capabilities['project.graph_training_step_v1'] ~= true then
            if old and (old.step or old.step_params or old.mode) then
              return session.ui_helpers.fail(tr('This CLI cannot preserve the declared training step; use a compatible CLI.',
                '当前 CLI 无法保留已声明的训练步骤；请选择兼容版本。', '目前 CLI 無法保留已宣告的訓練步驟；請選擇相容版本。'))
            end
            return optimizer_for(nil, nil)
          end
          local modes_supported = report.data.capabilities['project.graph_training_modes_v1'] == true
          if old and old.mode and old.mode ~= 'managed-step' and not modes_supported then
            return session.ui_helpers.fail(tr('This CLI cannot preserve the training mode; use a compatible CLI.',
              '当前 CLI 无法保留训练模式；请选择兼容版本。', '目前 CLI 無法保留訓練模式；請選擇相容版本。'))
          end
          local choices = {tr('Generated graph step', '图生成的训练步骤', '圖產生的訓練步驟'),
            tr('Custom managed step', '自定义受管训练步骤', '自訂受管訓練步驟')}
          if modes_supported then
            choices[#choices + 1] = tr('Custom manual step', '自定义手动训练步骤', '自訂手動訓練步驟')
            choices[#choices + 1] = tr('Custom external training loop', '自定义完整训练循环', '自訂完整訓練迴圈')
          end
          vim.ui.select(choices, {
            prompt = tr('Choose training mode and entry (not executed here)', '选择训练模式和入口（此处不会执行）', '選擇訓練模式和入口（此處不會執行）'),
          }, function(_, choice)
            if not choice or not current(snapshot) or not project_config_current(state) then return end
            if choice == 1 then return optimizer_for(nil, nil) end
            local mode = choice == 3 and 'manual-step' or choice == 4 and 'external-loop' or 'managed-step'
            vim.ui.input({prompt = mode == 'external-loop' and tr('Loop module:callable: ', '训练循环 module:callable：', '訓練迴圈 module:callable：')
                or tr('Step module:callable: ', '训练步骤 module:callable：', '訓練步驟 module:callable：'),
              default = old and old.step or ''}, function(step)
              if not step or not current(snapshot) or not project_config_current(state) then return end
              if #step > 240 or not step:match('^[^%s:]+:[^%s:]+$') then
                return session.ui_helpers.fail(tr('Enter a valid module:callable.', '请输入有效的 module:callable。', '請輸入有效的 module:callable。'))
              end
              local ok, default = pcall(vim.json.encode, old and old.step_params or vim.empty_dict())
              vim.ui.input({prompt = tr('Step parameters as JSON object (no secrets): ',
                '训练步骤参数 JSON 对象（请勿填写密钥）：', '訓練步驟參數 JSON 物件（請勿填寫金鑰）：'),
                default = ok and default or '{}'}, function(raw_params)
                if not raw_params or not current(snapshot) or not project_config_current(state) then return end
                local decoded, params = pcall(vim.json.decode, raw_params)
                if #raw_params > 65536 or not decoded or type(params) ~= 'table' or not raw_params:match('^%s*{') or vim.tbl_count(params) > 64 then
                  return session.ui_helpers.fail(tr('Enter a JSON object up to 64 KiB and 64 parameters.', '请输入不超过 64 KiB、64 项的 JSON 对象。', '請輸入不超過 64 KiB、64 項的 JSON 物件。'))
                end
                for name in pairs(params) do if not identifier_candidate(name) then return session.ui_helpers.fail(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。')) end end
                optimizer_for(step, params, mode)
              end)
            end)
          end)
        end)
      end,
      import_training = function(snapshot, done)
        if not current(snapshot) or not project_config_current(state) then return end
        local info, previous = state.project_info, state.last_training_entry
        local model = info and (state.model or info.model)
        if not info or not previous or previous.project ~= project or previous.model ~= model
            or previous.config_revision ~= info.config_revision or type(previous.params) ~= 'string'
            or not vim.tbl_contains({'managed-step', 'manual-step', 'external-loop'}, previous.mode)
            or type(previous.value) ~= 'string' or #previous.value > 240
            or not previous.value:match('^[^%s:]+:[^%s:]+$') then
          return session.ui_helpers.fail(tr('Prepare a complete training selection for this project and model first.',
            '请先为当前项目和模型准备完整的训练选择。', '請先為目前專案和模型準備完整的訓練選擇。'))
        end
        local caps = report.data.capabilities
        if caps['project.graph_training_step_v1'] ~= true
            or (previous.mode ~= 'managed-step' and caps['project.graph_training_modes_v1'] ~= true) then
          return session.ui_helpers.fail(tr('The selected CLI cannot store this training mode and entry in a graph.',
            '所选 CLI 无法在图中保存此训练模式与入口。', '所選 CLI 無法在圖中儲存此訓練模式與入口。'))
        end
        local ok, params = pcall(vim.json.decode, previous.params)
        if not ok or type(params) ~= 'table' or not previous.params:match('^%s*{')
            or #previous.params > 65536 or vim.tbl_count(params) > 64 then
          return session.ui_helpers.fail(tr('The session training parameters are unavailable.', '会话训练参数不可用。', '工作階段訓練參數無法使用。'))
        end
        for name in pairs(params) do if not identifier_candidate(name) then return session.ui_helpers.fail(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。')) end end
        local chosen = state.last_training_optimizer
        local optimizer = vim.empty_dict()
        if previous.mode ~= 'external-loop' then
          if not chosen or chosen.project ~= project or chosen.model ~= model or chosen.revision ~= info.config_revision
              or chosen.cli ~= state.opts.cli or chosen.python ~= state.opts.python
              or chosen.mode ~= previous.mode or chosen.entry ~= previous.value then
            return session.ui_helpers.fail(tr('Select an optimizer for this training entry first.', '请先为此训练入口选择优化器。', '請先為此訓練入口選擇最佳化器。'))
          end
          optimizer = optimizer_profile(chosen.args)
          if not optimizer or (previous.mode == 'manual-step' and optimizer.factory) then
            return session.ui_helpers.fail(tr('This optimizer cannot be saved for the selected mode.', '此优化器无法用于所选模式的声明。', '此最佳化器無法用於所選模式的宣告。'))
          end
        end
        local training = {trial_steps = snapshot.training and snapshot.training.trial_steps or 1,
          optimizer = optimizer, step = previous.value}
        if previous.mode ~= 'managed-step' then training.mode = previous.mode end
        if next(params) then training.step_params = params end
        local before_entry, before_optimizer = vim.deepcopy(previous), vim.deepcopy(chosen)
        local function review()
        session.ui_helpers.show_review(tr('Load session training into graph draft', '将会话训练设置载入图草稿', '將工作階段訓練設定載入圖草稿'),
          tr('This replaces the draft training declaration only. Save the graph separately; the entry and parameters may depend on the current model.',
            '这只替换草稿中的训练声明，图需要另行保存；入口和参数可能依赖当前模型。',
            '這只取代草稿中的訓練宣告，圖需要另行儲存；入口與參數可能依賴目前模型。')
            .. (training.step == nil and tr('\nUses the generated graph step; its behavior may differ from the session entry.',
              '\n使用图生成的训练步骤，行为可能与会话入口不同。', '\n使用圖產生的訓練步驟，行為可能與工作階段入口不同。') or '')
            .. '\n\n' .. vim.inspect(training), true, function(accepted)
              if not accepted or not current(snapshot) or not project_config_current(state)
                  or not vim.deep_equal(state.last_training_entry, before_entry)
                  or not vim.deep_equal(state.last_training_optimizer, before_optimizer)
                  or not state.project_info or state.project_info.config_revision ~= info.config_revision then return end
              done(training)
            end)
        end
        local module = type(model) == 'string' and model:match('^([%a_][%w_]*):model$') or nil
        if previous.mode == 'managed-step' and module and previous.value == module .. ':step' then
          vim.ui.select({tr('Keep the exact session entry', '保留会话中的固定入口', '保留工作階段中的固定入口'),
            tr('Use the generated step of the selected graph model', '使用所选图模型生成的步骤', '使用所選圖模型產生的步驟'), tr('Cancel', '取消', '取消')}, {
            prompt = tr('The generated step can follow a new graph model; it may behave differently from your current step.',
              '生成步骤可跟随新的图模型，但行为可能与当前步骤不同。', '產生的步驟可跟隨新的圖模型，但行為可能與目前步驟不同。'),
          }, function(_, choice)
            if not choice or choice == 3 or not current(snapshot) or not project_config_current(state)
                or not vim.deep_equal(state.last_training_entry, before_entry)
                or not vim.deep_equal(state.last_training_optimizer, before_optimizer) then return end
            if choice == 2 then training.step = nil end
            review()
          end)
        else review() end
      end,
      training_compare = function(snapshot)
        if not current(snapshot) or not project_config_current(state) then return end
        local info, previous = state.project_info, state.last_training_entry
        local model = info and (state.model or info.model)
        local current_session = info and previous and previous.project == project
          and previous.model == model and previous.config_revision == info.config_revision
        local graph = snapshot.training
        local entry = graph and graph.step
        if graph and (not entry or entry == '$model:step') then
          local module = type(model) == 'string' and model:match('^([%a_][%w_]*):model$') or nil
          entry = module and (module .. ':step') or tr('generated step; select a project model', '生成的步骤；请先选择项目模型', '產生的步驟；請先選擇專案模型')
        end
        local graph_view = graph and {mode = graph.mode or 'managed-step', entry = entry,
          params = graph.step_params or vim.empty_dict(), optimizer = graph.optimizer,
          trial_steps = graph.trial_steps} or nil
        local session_view
        if current_session then
          local ok, params = pcall(vim.json.decode, previous.params or '{}')
          session_view = {mode = previous.mode, entry = previous.value,
            params = ok and params or tr('unavailable', '不可用', '無法使用')}
          local optimizer = state.last_training_optimizer
          if optimizer and optimizer.project == project and optimizer.model == model and optimizer.revision == info.config_revision
              and optimizer.cli == state.opts.cli and optimizer.python == state.opts.python
              and optimizer.mode == previous.mode and optimizer.entry == previous.value then
            session_view.optimizer = optimizer_profile(optimizer.args)
          end
        end
        local content = tr('Graph draft (save before graph-launched runs):', '图草稿（从图启动运行前需保存）：', '圖草稿（從圖啟動執行前須儲存）：')
          .. '\n' .. (graph_view and vim.inspect(graph_view) or tr('No training declaration.', '未声明训练设置。', '未宣告訓練設定。'))
          .. '\n\n' .. tr('Last applicable session selection:', '最近适用的会话选择：', '最近適用的工作階段選擇：')
          .. '\n' .. (session_view and vim.inspect(session_view) or tr('None recorded for this project and model.', '当前项目和模型没有记录。', '目前專案和模型沒有記錄。'))
          .. '\n\n' .. tr('Graph-launched runs suggest the saved graph settings; every mode, entry and optimizer remains reviewable. These values do not prove a run was started.',
            '从图启动时会建议已保存的图设置；模式、入口和优化器均需审核。这些值不代表运行已经启动。',
            '從圖啟動時會建議已儲存的圖設定；模式、入口和最佳化器均須檢視。這些值不代表執行已經啟動。')
        session.ui_helpers.show_review(tr('Training settings', '训练设置', '訓練設定'), content, false)
      end,
      trial = function(snapshot) session.ui_helpers.verify_graph_source(snapshot, function(module, generated)
        local guard_with_data = session.ui_helpers.graph_revision_guard(snapshot, generated, snapshot.data ~= nil)
        local guard_without_data = session.ui_helpers.graph_revision_guard(snapshot, generated, false)
        local step = snapshot.training and snapshot.training.step
        local generated_step = not step or step == '$model:step'
        prepare_trial(state, nil, {entry = generated_step and module .. ':step' or step, training = vim.deepcopy(snapshot.training),
          generated_step_needs_loss = generated_step and #(snapshot.objectives or {}) == 0,
          rules_notice = session.ui_helpers.graph_rules_notice(snapshot),
          prepare_data = function(continue) session.ui_helpers.ensure_graph_data(snapshot, continue) end,
          guard = function(mode) return (mode == 'external-loop' and guard_without_data or guard_with_data)() end})
      end) end,
      train = function(snapshot) session.ui_helpers.verify_graph_source(snapshot, function(module, generated)
        local guard_with_data = session.ui_helpers.graph_revision_guard(snapshot, generated, snapshot.data ~= nil)
        local guard_without_data = session.ui_helpers.graph_revision_guard(snapshot, generated, false)
        local step = snapshot.training and snapshot.training.step
        local generated_step = not step or step == '$model:step'
        prepare_pytorch_training(state, nil, {entry = generated_step and module .. ':step' or step,
          generated_step_needs_loss = generated_step and #(snapshot.objectives or {}) == 0,
          rules_notice = session.ui_helpers.graph_rules_notice(snapshot),
          training = vim.deepcopy(snapshot.training), prepare_data = function(continue) session.ui_helpers.ensure_graph_data(snapshot, continue) end,
          guard = function(mode) return (mode == 'external-loop' and guard_without_data or guard_with_data)() end})
      end) end,
      runs = function(snapshot) if current(snapshot) then browse_runs(state) end end,
      pending_runs = function(snapshot) if current(snapshot) then resolve_pending(state) end end,
      locate_failure = function(snapshot, callback)
        local observed = state.last
        local report = observed and observed.report
        if observed and not observed.context_changed and not observed.isolated_variant and report
            and report.operation == 'graph_draft_probe' and report.status == 'error'
            and type(report.data) == 'table' and report.data.location_scope == 'generated_forward_stack_frame_not_root_cause'
            and vim.deep_equal(observed.draft_graph, snapshot) and current(snapshot) then
          local id = report.data.possible_node_id
          for _, node in ipairs(snapshot.nodes or {}) do
            if node.id == id then
              if callback then callback(tr('Possible failing draft node; inspect its inputs and parameters. The frame may not be the root cause.',
                '可能出错的草稿节点；请检查输入和参数，调用栈位置不一定是根因。',
                '可能出錯的草稿節點；請檢查輸入和參數，呼叫堆疊位置不一定是根因。'), id) end
              return
            end
          end
        end
        local location = report and report.operation == 'probe' and report.status == 'error'
          and type(report.data) == 'table' and report.data.failure_location or nil
        local frames = type(location) == 'table' and location.project_stack or nil
        if not observed or observed.context_changed or observed.isolated_variant or observed.historical_observation
            or type(frames) ~= 'table' or not is_list(frames) then
          return session.ui_helpers.fail(tr('No current forward failure with project frames is available.',
            '当前没有包含项目调用栈的前向失败记录。', '目前沒有包含專案呼叫堆疊的前向失敗紀錄。'))
        end
        session.ui_helpers.verify_graph_source(snapshot, function(module, generated)
          if state.last ~= observed or observed.context_changed or type(generated.source) ~= 'string'
              or vim.fn.sha256(generated.source) ~= generated.source_sha256 or type(generated.node_lines) ~= 'table' then return end
          local ending
          for index, line in ipairs(vim.split(generated.source, '\n', {plain = true})) do
            if line == '        return outputs' then ending = index; break end
          end
          if not ending then return session.ui_helpers.fail(tr('Cannot locate the generated forward boundary.', '无法定位生成前向的边界。', '無法定位產生前向的邊界。')) end
          local node_ids = {}
          for _, node in ipairs(snapshot.nodes) do node_ids[node.id] = true end
          local best_id, best_line
          for _, frame in ipairs(frames) do
            if type(frame) == 'table' and frame.file == module .. '.py' and frame['function'] == 'forward'
                and frame.source_sha256 == generated.source_sha256 and type(frame.line) == 'number'
                and frame.line % 1 == 0 and frame.line < ending then
              for id, line in pairs(generated.node_lines) do
                if node_ids[id] and type(line) == 'number' and line % 1 == 0 and line <= frame.line
                    and line < ending and (not best_line or line > best_line) then best_id, best_line = id, line end
              end
            end
          end
          if not best_id then
            return session.ui_helpers.fail(tr('No generated graph node could be located from this failure.',
              '无法从此次失败定位生成图节点。', '無法從此次失敗定位產生圖節點。'))
          end
          if callback then callback(tr('Possible failing node; inspect its inputs and parameters. The frame may not be the root cause.',
            '可能出错的节点；请检查输入和参数，调用栈位置不一定是根因。', '可能出錯的節點；請檢查輸入和參數，呼叫堆疊位置不一定是根因。'), best_id) end
        end)
      end,
      capture_input = function(snapshot)
        session.ui_helpers.verify_graph_source(snapshot, function(_, generated)
          session.ui_helpers.ensure_graph_data(snapshot, function()
            local guard = session.ui_helpers.graph_revision_guard(snapshot, generated, snapshot.data ~= nil)
            if not guard() then return session.ui_helpers.fail(tr('Graph or input changed; prepare capture again.', '图或输入已变化，请重新准备捕获。', '圖或輸入已變更，請重新準備擷取。')) end
            capture_canvas_forward(state, guard, session.base)
          end)
        end)
      end,
      replay_input = function(snapshot)
        if session.base ~= 'absent' and vim.deep_equal(snapshot, session.saved_doc) then
          return session.ui_helpers.verify_graph_source(snapshot, function(_, generated)
            replay_canvas_forward(state, session.ui_helpers.graph_revision_guard(snapshot, generated, false), session.base)
          end)
        end
        local capture = state.canvas_snapshot
        local revision = state.project_info and state.project_info.config_revision
        if not session.capabilities or session.capabilities['project.graph_draft_replay_v1'] ~= true then
          return session.ui_helpers.fail(tr('This CLI cannot preview an unsaved graph.', '此 CLI 不支持预览未保存的图。', '此 CLI 不支援預覽未儲存的圖。'))
        end
        if not capture or capture.cleaned or capture.project ~= project or not sha256(capture.digest) then
          return session.ui_helpers.fail(tr('Capture an input first.', '请先捕获输入。', '請先擷取輸入。'))
        end
        if not sha256(revision) or not current(snapshot) or not project_config_current(state) then
          return session.ui_helpers.fail(tr('Project configuration changed; review it before preview.', '项目配置已变化，请在预览前检查。', '專案設定已變更，請在預覽前檢查。'))
        end
        local path, digest = session.ui_helpers.temp(snapshot)
        if not path then return session.ui_helpers.fail(tr('Cannot prepare graph draft.', '无法准备图草稿。', '無法準備圖草稿。')) end
        local cleaned = false
        local function cleanup() if not cleaned then cleaned = true; vim.uv.fs_unlink(path) end end
        local args = {'graph-draft-probe', '--graph', path, '--if-graph', digest,
          '--snapshot', capture.path, '--input-sha256', capture.digest, '--if-config', revision}
        local function guard()
          return current(snapshot) and state.canvas_snapshot == capture and not capture.cleaned
            and state.project_info and state.project_info.config_revision == revision and project_config_current(state)
        end
        run(state, tr('Preview unsaved graph with captured input', '用捕获输入预览未保存的图', '以擷取輸入預覽未儲存的圖'), args,
          function(result, failure, _, stale, report_buf)
            cleanup()
            local data = result and result.data
            local same = not failure and not stale and guard() and result and result.operation == 'graph_draft_probe'
              and type(data) == 'table' and data.draft_graph_sha256 == digest
              and data.preview_scope == 'fresh-worker-graph-draft' and data.weights_loaded == false
              and type(data.batch_content) == 'table' and data.batch_content.algorithm == 'sha256-forward-input-v1'
              and data.batch_content.digest == capture.digest and type(data.batch_snapshot) == 'table'
              and data.batch_snapshot.status == 'replayed' and data.batch_snapshot.format == 'model-maven-forward-input-snapshot-v1'
            local passed = same and result.status == 'success' and data.forward_execution == 'executed'
            local summary = passed and tr('Unsaved graph ran with the captured input; weights were freshly initialized, not copied from the saved model.',
              '未保存图已使用捕获输入完成前向；权重是新初始化的，没有复制已保存模型的权重。',
              '未儲存圖已使用擷取輸入完成前向；權重為新初始化，沒有複製已儲存模型的權重。')
              or tr('Draft preview failed or replay could not be confirmed; the input capture remains available.',
                '草稿预览失败或无法确认重放；输入快照仍可使用。', '草稿預覽失敗或無法確認重播；輸入快照仍可使用。')
            if passed then
              local before, after = capture.identity or {}, canvas_forward_identity(data)
              local function compare(left, right)
                if not left or not right then return tr('unknown', '未知', '未知') end
                return left == right and tr('same fingerprint', '指纹相同', '指紋相同') or tr('different fingerprint', '指纹不同', '指紋不同')
              end
              summary = summary .. tr(' Weights: ', ' 权重：', ' 權重：') .. compare(before.weights, after.weights)
                .. tr(' · runtime packages: ', ' · 运行时包：', ' · 執行階段套件：') .. compare(before.environment, after.environment)
                .. tr(' · model class source: ', ' · 模型类源码：', ' · 模型類別原始碼：') .. compare(before.source, after.source)
                .. tr('. Other dependencies and state are not fully covered.', '。其他依赖和状态未被完整覆盖。', '。其他相依項目和狀態未被完整涵蓋。')
            elseif same and type(data.possible_node_id) == 'string'
                and data.location_scope == 'generated_forward_stack_frame_not_root_cause' then
              summary = summary .. tr(' Use Locate failure to inspect the possible node.', ' 可使用“定位失败”查看可能出错的节点。', ' 可使用「定位失敗」查看可能出錯的節點。')
            end
            if state.last then
              state.last.recheck_summary = summary
              if same then state.last.draft_graph = vim.deepcopy(snapshot) end
            end
            state.result_label = summary
            if report_buf and vim.api.nvim_buf_is_valid(report_buf) then
              vim.b[report_buf].model_maven_action_offset = (vim.b[report_buf].model_maven_action_offset or 0) + 2
              vim.bo[report_buf].modifiable = true; vim.api.nvim_buf_set_lines(report_buf, 0, 0, false, {summary, ''}); vim.bo[report_buf].modifiable = false
            end
            render(state)
          end, nil, true, function() if not guard() then cleanup(); return false end; return true end, cleanup, true)
      end,
      discard_input = function(snapshot)
        if current(snapshot) then discard_canvas_forward(state) end
      end,
      link_supervision = report.data.capabilities['project.graph_supervision_reference_v1'] == true and function(snapshot, done)
        if not current(snapshot) or not project_config_current(state) then return end
        vim.ui.input({prompt = tr('Project-relative supervision bundle: ', '项目内监督声明路径：', '專案內監督宣告路徑：'),
          default = snapshot.supervision and snapshot.supervision.file or 'supervision.json', completion = 'file'}, function(value)
          if not value or not current(snapshot) then return end
          if value == '' or #value > 1024 or value:find('[%c\\:]') or value:sub(1, 1) == '/'
              or value:match('^%./') or value:match('/%./') or value:match('/%.$')
              or value:match('^%.%.$') or value:match('^%.%./') or value:match('/%.%./') or value:match('/%.%.$') then
            return session.ui_helpers.fail(tr('Choose a project-relative path without parent segments.', '请选择不含上级目录的项目相对路径。', '請選擇不含上層目錄的專案相對路徑。'))
          end
          local root = vim.uv.fs_realpath(project)
          local path = root and vim.fs.normalize(root .. '/' .. value) or nil
          local function read_bundle()
            local stat, real = path and vim.uv.fs_lstat(path), path and vim.uv.fs_realpath(path)
            if not stat or stat.type ~= 'file' or stat.size > 2 * 1024 * 1024 or real ~= path then return nil end
            local file = io.open(path, 'rb'); local raw = file and file:read(2 * 1024 * 1024 + 1) or nil
            if file then file:close() end
            if not raw or #raw > 2 * 1024 * 1024 then return nil end
            local ok, bundle = pcall(vim.json.decode, raw)
            if not ok or type(bundle) ~= 'table' or bundle.format ~= 'model-maven-supervision-bundle-v1'
                or type(bundle.state) ~= 'table' or type(bundle.state.marks) ~= 'table' or not is_list(bundle.state.marks) then return nil end
            return vim.fn.sha256(raw), #bundle.state.marks
          end
          local digest, count = read_bundle()
          if not digest then return session.ui_helpers.fail(tr('Choose a regular project-local supervision bundle without symlinks.',
            '请选择项目内不经过符号链接的有效监督声明文件。', '請選擇專案內不經過符號連結的有效監督宣告檔案。')) end
          vim.ui.select({tr('Link to graph draft', '关联到图草稿', '連結至圖草稿'), tr('Cancel', '取消', '取消')}, {
            prompt = tr('Marks: ', '标记数：', '標記數：') .. count
              .. tr(' · import and rebind explicitly on the target project.', ' · 目标项目需明确导入并重新绑定。', ' · 目標專案須明確匯入並重新繫結。'),
          }, function(_, choice)
            if choice ~= 1 or not current(snapshot) or not project_config_current(state) then return end
            if read_bundle() ~= digest then return session.ui_helpers.fail(tr('Bundle changed; review it again.', '声明文件已变化，请重新审核。', '宣告檔案已變更，請重新檢視。')) end
            done({file = value, sha256 = digest})
          end)
        end)
      end or nil,
      import_supervision = function(snapshot)
        if not snapshot.supervision or not current(snapshot) or session.base == 'absent'
            or not vim.deep_equal(snapshot, session.saved_doc) then
          return session.ui_helpers.fail(tr('Save a graph with a supervision reference before importing.', '请先保存包含监督引用的图。', '請先儲存包含監督參照的圖。'))
        end
        local base = session.base
        local function guard()
          if not current(snapshot) or session.base ~= base or session.ui_helpers.open_buffer_conflict() then return false end
          local stat = vim.uv.fs_lstat(target)
          local file = stat and stat.type == 'file' and stat.size <= 128 * 1024 and io.open(target, 'rb') or nil
          local raw = file and file:read(128 * 1024 + 1) or nil
          if file then file:close() end
          return raw ~= nil and #raw <= 128 * 1024 and vim.fn.sha256(raw) == base
        end
        if guard() then transfer_supervision(state, true, vim.deepcopy(snapshot.supervision), guard) end
      end,
      export_supervision = function(snapshot) if current(snapshot) then transfer_supervision(state, false) end end,
      supervision = function(snapshot, node_id, selected_port)
        session.ui_helpers.verify_graph_source(snapshot, function(_, generated)
          local observed = state.last
          local report = observed and observed.report
          local calls = report and report.status == 'success' and report.operation == 'probe' and report.data and report.data.calls
          if not observed or observed.context_changed or observed.isolated_variant or observed.historical_observation
              or type(calls) ~= 'table' or not is_list(calls) then
            return session.ui_helpers.fail(tr('Run the saved graph forward before inspecting supervision.',
              '请先运行已保存图的前向，再查看监督。', '請先執行已儲存圖的前向，再檢視監督。'))
          end
          local node
          for _, item in ipairs(snapshot.nodes) do if item.id == node_id then node = item; break end end
          if not node then return end
          local candidates = {}
          if node.kind == 'output' then
            local name = node.output_name or node_id
            candidates['outputs.' .. name] = true
            candidates['outputs[' .. vim.json.encode(name) .. ']'] = true
          elseif node.kind == 'input' and selected_port and vim.tbl_contains(node.outputs, selected_port) then
            candidates['inputs.args[0].' .. node_id .. '.' .. selected_port] = true
            local input_ports = 0
            for _, item in ipairs(snapshot.nodes) do if item.kind == 'input' then input_ports = input_ports + #(item.outputs or {}) end end
            if input_ports == 1 then candidates['inputs.args[0]'] = true end
            if #node.outputs == 1 then candidates['inputs.kwargs.' .. node_id] = true
            else
              candidates['inputs.kwargs.' .. node_id .. '.' .. selected_port] = true
              candidates['inputs.kwargs[' .. vim.json.encode(node_id .. '.' .. selected_port) .. ']'] = true
            end
          else return end
          local preferred, matches = nil, 0
          for _, row in ipairs(observed_port_choices(calls)) do
            if row.path == 'model' and candidates[row.port] then preferred, matches = {path = row.path, port = row.port}, matches + 1 end
          end
          if matches ~= 1 then
            return session.ui_helpers.fail(tr('This port was not uniquely observed; inspect the forward report.',
              '当前端口未被唯一观察到，请检查前向报告。', '目前連接埠未被唯一觀察到，請檢查前向報告。'))
          end
          local semantic_port = node.kind == 'input' and selected_port or node.inputs[1]
          preferred.semantic_label = type(node.semantics) == 'table' and node.semantics[semantic_port] or nil
          preferred.draft_rules = type(node.draft_rules) == 'table' and vim.deepcopy(node.draft_rules[semantic_port]) or nil
          preferred.guard = session.ui_helpers.graph_revision_guard(snapshot, generated, false)
          sessions.port_supervision(state, preferred)
        end)
      end,
      preview_data = function(snapshot)
        local data = snapshot.data
        if not current(snapshot) or not project_config_current(state) or type(data) ~= 'table' or type(data.factory) ~= 'string' then
          return session.ui_helpers.fail(tr('Configure graph data before previewing.', '请先配置图数据再预览。', '請先設定圖資料再預覽。'))
        end
        local graph_image = data.factory == 'model_maven_worker.data.presets:graph_image_batch'
        local args = {'data', 'preview', '--batch', data.factory, '--whole-batch', '--no-split', '--renderer', graph_image and 'auto' or 'summary'}
        local names = vim.tbl_keys(data.params or {}); table.sort(names)
        for _, name in ipairs(names) do
          local ok, value = pcall(vim.json.encode, data.params[name])
          if not ok or not parameter_name_candidate(name) then return session.ui_helpers.fail(tr('Invalid data parameter.', '数据参数无效。', '資料參數無效。')) end
          vim.list_extend(args, {'--param', name .. '=' .. value})
        end
        request(state, {'--describe-interface'}, function(interface, failure)
          if not current(snapshot) or not project_config_current(state) then return end
          local caps = not failure and interface and interface.status == 'success' and interface.data and interface.data.capabilities
          if type(caps) ~= 'table' or caps['data.preview_whole_batch_v1'] ~= true or caps['data.preview_no_split_v1'] ~= true then
            return session.ui_helpers.fail(tr('This CLI cannot preview the full batch without a split.', '当前 CLI 不支持无切分的完整批次预览。', '目前 CLI 不支援無切分的完整批次預覽。'))
          end
          run(state, tr('Preview graph batch', '预览图批次', '預覽圖批次'), args, nil,
            (graph_image and tr('Runs the image factory using its declared split and transforms and writes a local image preview.',
              '将按声明的切分和变换运行图像工厂，并写入本地图像预览。', '將依宣告的切分和變換執行影像工廠，並寫入本機影像預覽。')
              or tr('Runs the selected batch factory and writes a local summary.', '将运行所选批次工厂并写入本地摘要。', '將執行所選批次工廠並寫入本機摘要。'))
              .. tr(' Project-level augmentation is not applied; model binding and dataset coverage remain unverified.',
                ' 未应用项目级增强；尚未验证模型绑定和数据集覆盖范围。', ' 未套用專案級增強；尚未驗證模型繫結和資料集涵蓋範圍。'), true,
            function() return current(snapshot) and project_config_current(state) end)
        end)
      end,
      forward = function(snapshot)
        session.ui_helpers.verify_graph_source(snapshot, function()
          session.ui_helpers.ensure_graph_data(snapshot, function() if state.actions and state.actions.p then state.actions.p() end end)
        end)
      end,
      observed_links = function(snapshot)
        local observed = state.last
        local report = observed and observed.report
        local data = report and report.data
        local model = type(data) == 'table' and type(data.run_provenance) == 'table' and data.run_provenance.model
        local implementation = type(model) == 'table' and model.implementation or nil
        if not current(snapshot) or not observed or observed.context_changed or observed.historical_observation
            or observed.isolated_variant or not report or report.operation ~= 'probe' or report.status ~= 'success'
            or type(data) ~= 'table' or data.forward_execution ~= 'executed' or type(implementation) ~= 'table'
            or not sha256(implementation.source_sha256) then
          return session.ui_helpers.fail(tr('Run a fresh saved-graph forward with source identity before browsing links.',
            '请先对已保存的图运行带源码身份的真实前向，再查看连接。', '請先對已儲存的圖執行帶原始碼身分的真實前向，再檢視連線。'))
        end
        session.ui_helpers.verify_graph_source(snapshot, function(_, generated)
          if state.last ~= observed or observed.context_changed or implementation.source_sha256 ~= generated.source_sha256 then
            return session.ui_helpers.fail(tr('Observation or source changed; run the forward again.', '观察或源码已变化，请重新运行前向。', '觀察或原始碼已變更，請重新執行前向。'))
          end
          browse_tensor_links(state)
        end)
      end,
      apply_data = apply_graph_data,
      bundle = function(snapshot, callback)
        if report.data.capabilities['project.graph_recipe_bundle_v1'] ~= true then
          return session.ui_helpers.fail(tr('This CLI cannot package graph projects.', '当前 CLI 不支持打包图项目。', '目前 CLI 不支援打包圖專案。'))
        end
        local base = session.base
        local function stable()
          if not current(snapshot) or base == 'absent' or session.base ~= base
              or not vim.deep_equal(snapshot, session.saved_doc) or session.ui_helpers.open_buffer_conflict() then return false end
          local stat = vim.uv.fs_lstat(target)
          if not stat or stat.type ~= 'file' or stat.size > 128 * 1024 then return false end
          local file = io.open(target, 'rb'); local raw = file and file:read(128 * 1024 + 1) or nil
          if file then file:close() end
          return raw ~= nil and #raw <= 128 * 1024 and vim.fn.sha256(raw) == base
        end
        package_project(state, 'graph', base, stable, callback)
      end,
      configure_data = function(snapshot, node_id, selected_port, done)
        if not current(snapshot) then return end
        local selected, draft = nil, {inputs = {}, outputs = {}, data = vim.deepcopy(snapshot.data)}
        local targets = {}
        local function graph_input(node, port, name)
          local row = {name = name}
          local shape = (node.output_shapes or {})[port]
          local dtype = (node.output_dtypes or {})[port]
          if type(dtype) == 'string' and type(shape) == 'table' and #shape > 1 then
            local sample = {}
            for index = 2, #shape do
              local dim = shape[index]
              if type(dim) ~= 'number' or dim < 1 or dim % 1 ~= 0 then return row end
              sample[#sample + 1] = tostring(dim)
            end
            row.shape, row.dtype = table.concat(sample, ','), dtype
          end
          return row
        end
        for _, node in ipairs(snapshot.nodes) do
          if node.id == node_id then selected = node end
          if node.kind == 'input' then
            if #(node.outputs or {}) == 1 then draft.inputs[#draft.inputs + 1] = graph_input(node, node.outputs[1], node.id)
            else
              for _, port in ipairs(node.outputs) do
                local name = node.id .. '.' .. port
                if #name <= 128 then draft.inputs[#draft.inputs + 1] = graph_input(node, port, name) end
              end
            end
          end
        end
        for _, objective in ipairs(snapshot.objectives or {}) do
          if not targets[objective.target] then
            targets[objective.target] = true
            draft.outputs[#draft.outputs + 1] = {name = objective.target, loss = objective.loss == 'cross_entropy' and 'ce' or objective.loss}
          end
        end
        if not selected then return end
        local preferred_input = selected.kind == 'input' and selected.id or nil
        if preferred_input and #(selected.outputs or {}) > 1 then
          if not selected_port or not vim.tbl_contains(selected.outputs, selected_port) then return end
          preferred_input = selected.id .. '.' .. selected_port
          if #preferred_input > 128 then
            return session.ui_helpers.fail(tr('This port name is too long for the CSV adapter; shorten it or use a custom batch factory.',
              '此端口名称超过 CSV 适配器限制，请缩短名称或使用自定义批次工厂。', '此連接埠名稱超過 CSV 配接器限制，請縮短名稱或使用自訂批次工廠。'))
          end
        end
        local preferred_output
        if selected.kind == 'output' then
          for _, objective in ipairs(snapshot.objectives or {}) do
            if objective.output == selected.id then preferred_output = objective.target; break end
          end
          if not preferred_output then
            preferred_output = selected.id
            if not targets[preferred_output] then draft.outputs[#draft.outputs + 1] = {name = preferred_output} end
          end
        end
        local params = draft.data and draft.data.factory == 'model_csv:batch' and draft.data.params or nil
        local edit_input = preferred_input and type(params) == 'table' and type(params.inputs) == 'table' and type(params.path) == 'string'
        local edit_target = preferred_output and type(params) == 'table' and type(params.targets) == 'table'
          and params.targets['$tensor'] == nil and type(params.inputs) == 'table' and type(params.path) == 'string'
        local choices = {}
        if edit_input or edit_target then choices[#choices + 1] = tr('Edit only this mapping', '只编辑此映射', '只編輯此對應') end
        choices[#choices + 1] = tr('Configure CSV mapping', '配置 CSV 映射', '設定 CSV 對應')
        choices[#choices + 1] = tr('Create CSV adapter and configure', '创建 CSV 适配器并配置', '建立 CSV 配接器並設定')
        choices[#choices + 1] = tr('Connect class-folder images', '连接分类目录图像', '連接分類目錄影像')
        choices[#choices + 1] = tr('Use an existing batch or dataset factory', '使用已有批次或数据集工厂', '使用既有批次或資料集工廠')
        vim.ui.select(choices, {prompt = tr('Connect a data source to this graph', '为此图连接数据源', '為此圖連接資料來源')}, function(_, choice)
          if not choice or not current(snapshot) then return end
          local function accept(data)
            if current(snapshot) then done(data) else session.ui_helpers.fail(tr('Graph changed; configure data again.', '图已变化，请重新配置数据。', '圖已變更，請重新設定資料。')) end
          end
          if edit_input or edit_target then
            if choice == 1 then return configure_csv_adapter(state, preferred_input, accept, preferred_output, edit_target, edit_input, draft) end
            choice = choice - 1
          end
          if choice == 1 then configure_csv_adapter(state, preferred_input, accept, preferred_output, nil, nil, draft)
          elseif choice == 2 then create_csv_adapter(state, preferred_input, accept, preferred_output, draft)
          elseif choice == 4 then
            local previous = type(snapshot.data) == 'table' and snapshot.data or nil
            vim.ui.input({prompt = tr('Factory module:callable: ', '工厂 module:callable：', '工廠 module:callable：'),
              default = previous and previous.factory or ''}, function(reference)
              if not reference or not current(snapshot) then return end
              if #reference > 240 or not reference:match('^[^%s:]+:[^%s:]+$') then
                return session.ui_helpers.fail(tr('Enter a valid factory reference.', '请输入有效工厂引用。', '請輸入有效工廠參照。'))
              end
              vim.ui.select({'auto', 'envelope', 'single', 'single-raw', 'args', 'kwargs'}, {
                prompt = tr('Choose input binding; automatic mode resolves it at runtime', '选择输入绑定方式；自动模式在运行时解析', '選擇輸入繫結方式；自動模式在執行時解析'),
              }, function(binding)
                if not binding or not current(snapshot) then return end
                local params = previous and previous.factory == reference and previous.params or vim.empty_dict()
                local encoded, initial = pcall(vim.json.encode, params)
                vim.ui.select({tr('Use current/default parameters', '使用当前或默认参数', '使用目前或預設參數'),
                  tr('Edit parameter object', '编辑参数对象', '編輯參數物件'), tr('Cancel', '取消', '取消')}, {
                  prompt = tr('The factory has not run. Recognized dataset objects are sampled by the worker; sample count and output mapping depend on the run. single-raw passes the object unchanged.',
                    '工厂尚未运行。worker 会对识别出的数据集对象采样；样本数及输出映射取决于运行设置。single-raw 会原样传递对象。',
                    '工廠尚未執行。worker 會對識別出的資料集物件取樣；樣本數及輸出對應取決於執行設定。single-raw 會原樣傳遞物件。'),
                }, function(_, option)
                  if not option or not current(snapshot) then return end
                  local function submit(value)
                    for name in pairs(value) do
                      if not parameter_name_candidate(name) then return session.ui_helpers.fail(tr('Invalid factory parameter name.', '工厂参数名无效。', '工廠參數名稱無效。')) end
                    end
                    accept({factory = reference, binding = binding ~= 'auto' and binding or nil, params = value})
                  end
                  if option == 1 then return submit(vim.deepcopy(params)) end
                  if option ~= 2 then return end
                  vim.ui.input({prompt = tr('Parameters (JSON object): ', '参数（JSON 对象）：', '參數（JSON 物件）：'), default = encoded and initial or '{}'}, function(raw)
                    if not raw or not current(snapshot) then return end
                    local ok, value = pcall(vim.json.decode, raw)
                    if #raw > 65536 or not ok or type(value) ~= 'table' or not raw:match('^%s*{') or vim.tbl_count(value) > 64 then
                      return session.ui_helpers.fail(tr('Enter an object up to 64 KiB with at most 64 parameters.', '请输入不超过 64 KiB、最多 64 个参数的对象。', '請輸入不超過 64 KiB、最多 64 個參數的物件。'))
                    end
                    submit(value)
                  end)
                end)
              end)
            end)
          elseif choice == 3 then
            local inputs, output_targets = {}, {}
            for _, item in ipairs(draft.inputs) do inputs[#inputs + 1] = item.name end
            for _, item in ipairs(draft.outputs) do output_targets[#output_targets + 1] = item.name end
            local inferred_targets = #(snapshot.objectives or {}) == 0
            if #output_targets == 0 then
              for _, node in ipairs(snapshot.nodes) do
                if node.kind == 'output' then output_targets[#output_targets + 1] = node.id end
              end
            end
            if #inputs == 0 then return session.ui_helpers.fail(tr('Add an input port first.', '请先添加输入端口。', '請先新增輸入連接埠。')) end
            if #output_targets == 0 then return session.ui_helpers.fail(tr('Add an output node first.', '请先添加输出节点。', '請先新增輸出節點。')) end
            local function choose_target(input)
              if not current(snapshot) then return end
              local prompt = inferred_targets
                and tr('Choose a label name; add a loss with this target before training', '选择标签名称；训练前为输出添加使用此目标的损失', '選擇標籤名稱；訓練前為輸出新增使用此目標的損失')
                or tr('Choose the image label target', '选择图像标签目标', '選擇影像標籤目標')
              vim.ui.select(output_targets, {prompt = prompt}, function(target_name)
                if not target_name or not current(snapshot) then return end
                local image_recipe = require('model_maven.model_builder').load(project)
                local suggested_root = image_recipe and image_recipe.kind == 'image_classification'
                  and type(image_recipe.image_data) == 'string' and image_recipe.image_data or ''
                vim.ui.input({prompt = tr('Class-folder dataset directory (review the suggested path): ',
                  '按类别分目录的图像数据路径（请核对建议路径）：', '依類別分目錄的影像資料路徑（請核對建議路徑）：'),
                  default = suggested_root, completion = 'dir'}, function(root)
                  if not root or root == '' or not current(snapshot) then return end
                  vim.ui.input({prompt = tr('Resize images to square pixels: ', '图像缩放后的边长：', '影像縮放後的邊長：'), default = '32'}, function(raw_size)
                    if not raw_size or not current(snapshot) then return end
                    local size = tonumber(raw_size)
                    if not size or size % 1 ~= 0 or size < 1 or size > 8192 then return session.ui_helpers.fail(tr('Enter a positive image size up to 8192.', '请输入不超过 8192 的正整数边长。', '請輸入不超過 8192 的正整數邊長。')) end
                    vim.ui.input({prompt = tr('Batch size: ', '批大小：', '批次大小：'), default = '8'}, function(raw_batch)
                      if not raw_batch or not current(snapshot) then return end
                      local batch = tonumber(raw_batch)
                      if not batch or batch % 1 ~= 0 or batch < 1 or batch > 256 then return session.ui_helpers.fail(tr('Enter a batch size from 1 to 256.', '请输入 1 到 256 的批大小。', '請輸入 1 到 256 的批次大小。')) end
                      vim.ui.input({prompt = tr('Train, validation, test weights (e.g. 8,1,1): ', '训练、验证、测试权重（如 8,1,1）：', '訓練、驗證、測試權重（如 8,1,1）：'), default = '8,1,1'}, function(raw_ratios)
                        if not raw_ratios or not current(snapshot) then return end
                        local a, b, c = raw_ratios:match('^%s*(%d+)%s*,%s*(%d+)%s*,%s*(%d+)%s*$')
                        a, b, c = tonumber(a), tonumber(b), tonumber(c)
                        if not a or not b or not c or a + b + c == 0 or a + b + c > 1000000 then
                          return session.ui_helpers.fail(tr('Enter three nonnegative whole-number weights with a positive sum up to 1000000.',
                            '请输入三个非负整数权重，总和在 1 到 1000000 之间。', '請輸入三個非負整數權重，總和在 1 到 1000000 之間。'))
                        end
                        local total = a + b + c
                        local ratios = {train = a / total, validation = b / total, test = c / total}
                        local splits = {}; for _, name in ipairs({'train', 'validation', 'test'}) do if ratios[name] > 0 then splits[#splits + 1] = name end end
                        vim.ui.select(splits, {prompt = tr('Choose the active split', '选择当前使用的切分', '選擇目前使用的切分')}, function(split)
                          if not split or not current(snapshot) then return end
                          vim.ui.select({tr('Resize and convert only', '仅缩放并转张量', '僅縮放並轉張量'), tr('Also flip training images randomly', '训练图像增加随机水平翻转', '訓練影像增加隨機水平翻轉')}, {
                            prompt = tr('Choose ordered image transforms', '选择有序图像变换', '選擇有序影像變換'),
                          }, function(_, augment)
                            if not augment or not current(snapshot) then return end
                            local function pipeline(flip)
                              local result = {{type = 'Resize', size = size}}
                              if flip then result[#result + 1] = {type = 'RandomHorizontalFlip', p = 0.5} end
                              result[#result + 1] = {type = 'ToTensor'}
                              return result
                            end
                            local transforms = {train = pipeline(augment == 2), validation = pipeline(false), test = pipeline(false)}
                            vim.ui.select({tr('Use this mapping', '使用此映射', '使用此對應'), tr('Cancel', '取消', '取消')}, {
                              prompt = tr('One image input and one label target; split ', '一个图像输入和一个标签目标；当前切分 ', '一個影像輸入和一個標籤目標；目前切分 ') .. split
                                .. tr('. Preview before running.', '。运行前请预览。', '。執行前請預覽。'),
                            }, function(_, confirm)
                              if confirm ~= 1 or not current(snapshot) then return end
                              accept({factory = 'model_maven_worker.data.presets:graph_image_batch', binding = 'envelope', params = {
                                root = root, input_name = input, target_name = target_name, batch_size = batch,
                                split = split, split_ratios = ratios, split_transforms = transforms,
                              }})
                            end)
                          end)
                        end)
                      end)
                    end)
                  end)
                end)
              end)
            end
            if preferred_input then choose_target(preferred_input)
            else vim.ui.select(inputs, {prompt = tr('Choose the graph image input', '选择图像输入端口', '選擇影像輸入連接埠')}, function(input)
              if input then choose_target(input) end
            end) end
          end
        end)
      end,
      discover_layers = function(callback)
        discover_layer_classes(state, function(layer)
          if session.ui_helpers.context() and state.graph_canvas == session then callback(layer) end
        end)
      end,
      project_factories = function(callback)
        local epoch = state.change_epoch or 0
        local function still_current() return session.ui_helpers.context() and state.graph_canvas == session and (state.change_epoch or 0) == epoch end
        find_component_factories(state, still_current, function(items)
          if not still_current() then return end
          local references = {}
          for _, item in ipairs(items) do
            if type(item) == 'string' and not item:match('^component:') then references[#references + 1] = item end
          end
          callback(references)
        end)
      end,
      registered_factories = report.data.capabilities['project.graph_registered_components_v1'] == true and function(callback)
        local epoch = state.change_epoch or 0
        request(state, {'component', 'list'}, function(result, failure)
          if not session.ui_helpers.context() or state.graph_canvas ~= session or (state.change_epoch or 0) ~= epoch then return end
          local items = not failure and result and result.status == 'success' and result.operation == 'component_list'
            and type(result.data) == 'table' and result.data.components or nil
          local references = {}
          for _, item in ipairs(type(items) == 'table' and items or {}) do
            local manifest = type(item) == 'table' and type(item.manifest) == 'table' and item.manifest or nil
            local id, version = manifest and manifest.component_id, manifest and manifest.component_version
            local capabilities = manifest and type(manifest.capabilities) == 'table' and manifest.capabilities or nil
            local construct = capabilities and capabilities.construct
            if type(id) == 'string' and #id <= 129 and id:match('^[%w_-]+/[%w_-]+$')
                and type(version) == 'string' and #version <= 64 and version:match('^%d+%.%d+%.%d+$')
                and manifest.kind == 'layer' and type(construct) == 'table' and construct.state == 'supported' then
              local signature = {status = 'declared', parameters = {}}
              local schema = manifest.params_schema
              local required = type(schema) == 'table' and type(schema.required) == 'table' and schema.required or {}
              local properties = type(schema) == 'table' and type(schema.properties) == 'table' and schema.properties or {}
              local names = {}
              for name in pairs(properties) do if type(name) == 'string' and #name <= 128 then names[#names + 1] = name end end
              table.sort(names)
              for _, name in ipairs(names) do
                local property = type(properties[name]) == 'table' and properties[name] or {}
                local type_hint = ({integer='number', number='number', string='text', boolean='boolean', array='collection', object='collection'})[property.type]
                local parameter = {name = name, required = vim.tbl_contains(required, name), type_hint = type_hint}
                if type(property.default) == 'number' or type(property.default) == 'boolean' or property.default == vim.NIL then
                  parameter.default, parameter.default_available = property.default, true
                end
                signature.parameters[#signature.parameters + 1] = parameter
              end
              references[#references + 1] = {reference = 'component:' .. id .. '@' .. version, signature = signature}
              if #references >= 512 then
                notify(tr('Component choices are limited to the first 512 results.', '组件候选仅显示前 512 项。', '元件候選僅顯示前 512 項。'), vim.log.levels.WARN)
                break
              end
            end
          end
          callback(references)
        end)
      end or nil,
      discover_module_operators = function(callback, initial_module)
        discover_module_operators(state, function(item)
          if session.ui_helpers.context() and state.graph_canvas == session then callback(item) end
        end, initial_module)
      end,
      image_transform_catalog = function(snapshot, callback)
        if not current(snapshot) or not project_config_current(state) then return end
        request(state, {'augment', 'list', '--split', 'train'}, function(result, failure)
          if not current(snapshot) or not project_config_current(state) then return end
          local catalog = not failure and result and result.status == 'success' and result.operation == 'augment_list'
            and type(result.data) == 'table' and result.data.catalog or nil
          if type(catalog) ~= 'table' or not is_list(catalog) or #catalog > 128 then
            return session.ui_helpers.fail(tr('Transform catalogue is unavailable; use a compatible CLI.', '无法读取变换目录，请使用兼容 CLI。', '無法讀取變換目錄，請使用相容 CLI。'))
          end
          callback(catalog)
        end)
      end,
      delivery_review = report.data.capabilities['project.graph_delivery_review_v1'] == true and function(snapshot)
        if not current(snapshot) or session.ui_helpers.open_buffer_conflict() then return end
        local model = state.project_info and state.project_info.model
        local module = type(model) == 'string' and model:match('^([%a_][%w_]*):model$') or nil
        vim.ui.input({prompt = tr('Source file to review: ', '要审核的源码文件：', '要檢視的原始碼檔案：'),
          default = module and (module .. '.py') or 'model_graph.py'}, function(source)
          if not source or not current(snapshot) or session.ui_helpers.open_buffer_conflict() then return end
          local draft, digest = session.ui_helpers.temp(snapshot)
          if not draft then return session.ui_helpers.fail(tr('Could not prepare graph draft.', '无法准备图草稿。', '無法準備圖草稿。')) end
          local base = session.base
          local function cleanup() pcall(vim.uv.fs_unlink, draft) end
          state.busy = tr('Reviewing graph delivery', '审核图交付', '檢視圖交付'); render(state)
          request(state, {'graph-delivery-plan', '--draft', draft, '--if-draft', digest, '--output', file_name,
            '--if-base', base, '--source', source}, function(result, error)
            state.busy = nil; cleanup(); render(state)
            if not current(snapshot) or session.base ~= base then return end
            if error or not result or result.operation ~= 'graph_delivery_plan' or result.status ~= 'success'
                or type(result.data) ~= 'table' or result.data.committed ~= false
                or not sha256(result.data.plan_revision) or type(result.data.plan) ~= 'table'
                or result.data.plan.draft_sha256 ~= digest or result.data.plan.graph_base ~= base
                or result.data.plan.source_output ~= source then
              return session.ui_helpers.fail(tr('Delivery review failed; nothing was saved.', '联合审核失败；没有保存任何内容。', '聯合檢視失敗；沒有儲存任何內容。'))
            end
            local body = tr('Read-only overview. Save, generate and bind are separate conditional operations; this review does not reserve or change files. Training and supervision are not enabled by binding.',
              '这是只读总览。保存、生成和绑定是分别进行的条件操作；本次审核不锁定或修改文件。绑定不会启用训练或监督。',
              '這是唯讀總覽。儲存、產生和繫結是分別進行的條件操作；本次檢視不鎖定或修改檔案。繫結不會啟用訓練或監督。')
            local can_start = report.data.capabilities['project.graph_delivery_recovery_v1'] == true
              and type(result.data.plan.source_review) == 'table' and result.data.plan.source_review.status == 'success'
            session.ui_helpers.show_review(tr('Graph delivery review', '图交付联合审核', '圖交付聯合檢視'), body .. '\n\n' .. vim.inspect(result.data.plan), can_start, function(accepted)
              if not accepted or not can_start or not current(snapshot) or session.base ~= base
                  or session.ui_helpers.open_buffer_conflict() or #dirty_buffers(project) > 0 or #reloads_pending(state) > 0 then return end
              local apply_draft, apply_digest = session.ui_helpers.temp(snapshot)
              if not apply_draft or apply_digest ~= digest then
                if apply_draft then pcall(vim.uv.fs_unlink, apply_draft) end
                return session.ui_helpers.fail(tr('Graph draft changed; review again.', '图草稿已变化，请重新审核。', '圖草稿已變更，請重新檢視。'))
              end
              local function cleanup_apply() pcall(vim.uv.fs_unlink, apply_draft) end
              local tracked = begin_tracked_commit(state, tr('Deliver graph project', '提交图项目', '提交圖專案'))
              if not tracked then cleanup_apply(); return end
              state.busy = tr('Delivering graph project', '提交图项目', '提交圖專案'); render(state)
              request(state, {'graph-delivery-start', '--draft', apply_draft, '--if-draft', digest, '--output', file_name,
                '--if-base', base, '--source', source, '--if-plan', result.data.plan_revision}, function(receipt, problem)
                state.busy = nil; cleanup_apply()
                local same = tracked_commit_current(state, tracked)
                local data = receipt and receipt.data
                local valid = not problem and receipt and receipt.operation == 'graph_delivery' and receipt.status == 'success'
                  and type(data) == 'table' and data.committed == true and data.graph_sha256 == digest
                  and data.plan_revision == result.data.plan_revision and sha256(data.source_sha256) and sha256(data.config_revision)
                local partial = receipt and receipt.operation == 'graph_delivery' and receipt.status == 'error'
                  and type(data) == 'table' and data.journal_retained == true and data.plan_revision == result.data.plan_revision
                local settled = settle_tracked_commit(state, tracked, valid or partial, problem)
                if not same then return notify_tracked_context_changed(tracked) end
                if valid and settled then
                  session.base, session.saved_revision, session.saved_doc = digest, digest, vim.deepcopy(snapshot)
                  require('model_maven.model_preview').refresh(state)
                  local f = io.open(target, 'rb'); local raw = f and f:read(128 * 1024 + 1) or nil; if f then f:close() end
                  session.saved_raw = raw and #raw <= 128 * 1024 and vim.fn.sha256(raw) == digest and raw or nil
                  mark_source_buffers(state, {target, source}); session.ui_helpers.checkpoint(false)
                  state.change_epoch = (state.change_epoch or 0) + 1
                  if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
                  refresh_project(state); render(state)
                  notify(tr('Graph, source and project binding saved; model has not run.', '图、源码和项目绑定已保存；模型尚未运行。', '圖、原始碼和專案繫結已儲存；模型尚未執行。'), vim.log.levels.INFO)
                elseif partial and settled then
                  state.change_epoch = (state.change_epoch or 0) + 1
                  refresh_project(state); render(state)
                  session.ui_helpers.fail(tr('Delivery stopped at ', '交付停在：', '交付停在：') .. tostring(data.stage)
                    .. tr('. The recovery record is retained; reopen the canvas and use Resume delivery.', '。恢复记录已保留；请重开画布并使用“恢复交付”。', '。還原記錄已保留；請重開畫布並使用「恢復交付」。'))
                else render(state); session.ui_helpers.fail(tr('Delivery outcome needs inspection before retry.', '重试前请核查交付结果。', '重試前請核查交付結果。')) end
              end, cleanup_apply)
            end)
          end, cleanup)
        end)
      end or nil,
      delivery_resume = report.data.capabilities['project.graph_delivery_recovery_v1'] == true and function(snapshot)
        if not current(snapshot) or session.ui_helpers.open_buffer_conflict() or #dirty_buffers(project) > 0 or #reloads_pending(state) > 0 then
          return session.ui_helpers.fail(tr('Save or session.ui_helpers.reconcile project buffers before recovery.', '恢复前请保存或处理项目缓冲区。', '恢復前請儲存或處理專案緩衝區。'))
        end
        local function begin_resume(expected_plan)
        vim.ui.select({tr('Cancel', '取消', '取消'), tr('Resume recorded delivery', '恢复记录的交付', '恢復記錄的交付')}, {
          prompt = tr('Resume the recorded graph, source and project changes; conflicts stop recovery.',
            '继续记录中的图、源码和项目修改；遇到冲突会停止。', '繼續記錄中的圖、原始碼和專案修改；遇到衝突會停止。')}, function(_, choice)
          if choice ~= 2 or not current(snapshot) or session.ui_helpers.open_buffer_conflict() or #dirty_buffers(project) > 0 then return end
          local tracked = begin_tracked_commit(state, tr('Resume graph delivery', '恢复图交付', '恢復圖交付'))
          if not tracked then return end
          state.busy = tr('Resuming graph delivery', '恢复图交付', '恢復圖交付'); render(state)
          local resume_args = {'graph-delivery-resume'}
          if expected_plan then vim.list_extend(resume_args, {'--if-plan', expected_plan}) end
          request(state, resume_args, function(receipt, problem)
            state.busy = nil
            local same, data = tracked_commit_current(state, tracked), receipt and receipt.data
            local valid = not problem and receipt and receipt.operation == 'graph_delivery' and receipt.status == 'success'
              and type(data) == 'table' and data.committed == true and sha256(data.graph_sha256) and sha256(data.source_sha256) and sha256(data.config_revision)
            local partial = receipt and receipt.operation == 'graph_delivery' and receipt.status == 'error'
              and type(data) == 'table' and data.journal_retained == true
            local settled = settle_tracked_commit(state, tracked, valid or partial, problem)
            if not same then return notify_tracked_context_changed(tracked) end
            state.change_epoch = (state.change_epoch or 0) + 1
            if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
            refresh_project(state); render(state)
            if valid and settled then
              notify(tr('Delivery recovered. Reopen the graph to load its saved state.', '交付已恢复；请重新打开图以加载保存状态。', '交付已恢復；請重新開啟圖以載入儲存狀態。'), vim.log.levels.INFO)
            elseif partial and settled then
              session.ui_helpers.fail(tr('Recovery stopped at ', '恢复停在：', '恢復停在：') .. tostring(data.stage) .. tr('; the record is retained.', '；记录已保留。', '；記錄已保留。'))
            else session.ui_helpers.fail(tr('Recovery outcome needs inspection.', '请核查恢复结果。', '請核查恢復結果。')) end
          end)
        end)
        end
        if report.data.capabilities['project.graph_delivery_status_v1'] ~= true then return begin_resume() end
        state.busy = tr('Checking delivery recovery', '检查交付恢复状态', '檢查交付恢復狀態'); render(state)
        request(state, {'graph-delivery-status'}, function(status, problem)
          state.busy = nil; render(state)
          if not current(snapshot) then return end
          local data = status and status.data
          if problem or not status or status.operation ~= 'graph_delivery_status' or status.status ~= 'success' or type(data) ~= 'table' then
            return session.ui_helpers.fail(tr('Cannot inspect the delivery record.', '无法检查交付记录。', '無法檢查交付記錄。'))
          end
          if data.pending ~= true then return session.ui_helpers.fail(tr('No delivery recovery is pending.', '没有待恢复的交付。', '沒有待恢復的交付。')) end
          local function state_of(item)
            return type(item) == 'table' and type(item.comparison) == 'table' and item.comparison.state or 'unknown'
          end
          if not sha256(data.plan_revision) then return session.ui_helpers.fail(tr('Invalid recovery identity.', '恢复记录身份无效。', '恢復記錄身分無效。')) end
          local graph_state, source_state = state_of(data.graph), state_of(data.source)
          local project_state = type(data.project) == 'table' and data.project.state or 'unknown'
          local function allowed(value) return value == 'before' or value == 'target' end
          local ready = allowed(graph_state) and allowed(source_state) and allowed(project_state)
          local text = tr('Each file is checked again when recovery starts. Conflicts and unknown states stop recovery.',
            '开始恢复时会再次检查每个文件；冲突或未知状态会阻止恢复。', '開始恢復時會再次檢查每個檔案；衝突或未知狀態會阻止恢復。')
            .. '\n\n' .. vim.inspect(data)
          local can_archive = report.data.capabilities['project.graph_delivery_archive_v1'] == true
          session.ui_helpers.show_review(tr('Delivery recovery status', '交付恢复状态', '交付恢復狀態'), text, ready or can_archive, function(accepted)
            if not accepted or not current(snapshot) then return end
            local choices, actions = {tr('Cancel', '取消', '取消')}, {'cancel'}
            if ready then choices[#choices + 1], actions[#actions + 1] = tr('Resume delivery', '继续交付', '繼續交付'), 'resume' end
            if can_archive then choices[#choices + 1], actions[#actions + 1] = tr('Archive record; keep existing files', '归档记录，保留现有文件', '封存記錄，保留現有檔案'), 'archive' end
            vim.ui.select(choices, {prompt = tr('Choose recovery action; archiving does not undo any completed writes.',
              '选择恢复操作；归档不会撤销已完成的写入。', '選擇恢復操作；封存不會撤銷已完成的寫入。')}, function(_, choice)
              if not choice or not current(snapshot) then return end
              if actions[choice] == 'resume' then return begin_resume(data.plan_revision) end
              if actions[choice] ~= 'archive' then return end
              local tracked = begin_tracked_commit(state, tr('Archive delivery record', '归档交付记录', '封存交付記錄'))
              if not tracked then return end
              state.busy = tr('Archiving delivery record', '归档交付记录', '封存交付記錄'); render(state)
              request(state, {'graph-delivery-archive', '--if-plan', data.plan_revision}, function(receipt, problem)
                state.busy = nil
                local same, result = tracked_commit_current(state, tracked), receipt and receipt.data
                local valid = not problem and receipt and receipt.operation == 'graph_delivery_archive' and receipt.status == 'success'
                  and type(result) == 'table' and result.archived == true and result.plan_revision == data.plan_revision
                  and type(result.archive) == 'string' and result.archive:match('^%.model%-maven/graph%-delivery%.archived%-%d+%-%d+%.json$')
                local settled = settle_tracked_commit(state, tracked, valid, problem)
                if not same then return notify_tracked_context_changed(tracked) end
                render(state)
                if valid and settled then notify(tr('Recovery record archived; existing project files were not rolled back.',
                  '恢复记录已归档；现有项目文件没有回滚。', '恢復記錄已封存；現有專案檔案沒有回復。'), vim.log.levels.INFO)
                else session.ui_helpers.fail(tr('Archive outcome needs inspection.', '请核查归档结果。', '請核查封存結果。')) end
              end)
            end)
          end)
        end)
      end or nil,
      validate = function(snapshot, callback) execute(snapshot, 'validate', nil, callback) end,
      save = function(snapshot, callback) execute(snapshot, 'save', nil, callback) end,
      save_and_apply_data = function(snapshot, callback)
        if not snapshot.data then return session.ui_helpers.fail(tr('Configure graph data first.', '请先配置图数据。', '請先設定圖資料。')) end
        if not state.project_info or not project_config_current(state) then
          return session.ui_helpers.fail(tr('Set up or refresh the project before saving its input.', '保存项目输入前请初始化或刷新项目。', '儲存專案輸入前請初始化或重新整理專案。'))
        end
        execute(snapshot, 'save', nil, function(info)
          if callback then callback(info) end
          if not current(snapshot) or not vim.deep_equal(snapshot, session.saved_doc) or not project_config_current(state) then
            return session.ui_helpers.fail(tr('Graph or project changed; review the data again.', '图或项目已变化，请重新审核数据。', '圖或專案已變更，請重新檢視資料。'))
          end
          if session.ui_helpers.graph_data_matches(snapshot) then
            if callback then callback(tr('Graph saved; project input already matches. No data was run.',
              '图已保存；项目输入已匹配，未运行数据。', '圖已儲存；專案輸入已相符，未執行資料。')) end
            return
          end
          apply_graph_data(snapshot)
        end)
      end,
      generate = function(snapshot, callback)
        local previous = state.project_info and state.project_info.model
        local module = type(previous) == 'string' and previous:match('^([%a_][%w_]*):model$') or nil
        local stem = module and module:match('^(.-)_%d+$') or module or 'graph_model'
        if #stem > 110 then stem = 'graph_model' end
        local suggested
        for index = 1, 10000 do
          local name = stem .. (index == 1 and '' or ('_' .. index)) .. '.py'
          local stat, _, code = vim.uv.fs_lstat(project .. '/' .. name)
          if not stat and code == 'ENOENT' then suggested = name; break end
          if not stat and code ~= 'ENOENT' then break end
        end
        if not suggested then return session.ui_helpers.fail(tr('Could not choose an unused module name.', '无法选择未使用的模块名。', '無法選擇未使用的模組名稱。')) end
        local function create_new()
          vim.ui.input({prompt = tr('New Python module filename (existing files are retained): ', '新 Python 模块文件名（保留已有文件）：', '新 Python 模組檔名（保留既有檔案）：'), default=suggested}, function(name)
            if not name or not current(snapshot) then return end
            execute(snapshot, 'generate', name, callback)
          end)
        end
        if not module or not session.capabilities or session.capabilities['project.graph_generate_replace_v1'] ~= true then return create_new() end
        local filename, file_path = module .. '.py', project .. '/' .. module .. '.py'
        local stat = vim.uv.fs_lstat(file_path)
        if not stat or stat.type ~= 'file' or stat.size > 128 * 1024 then return create_new() end
        vim.ui.select({tr('Update current model source…', '更新当前模型源码…', '更新目前模型原始碼…'),
          tr('Create a new source file…', '创建新源码文件…', '建立新原始碼檔案…'), tr('Cancel', '取消', '取消')}, {
          prompt = tr('Choose how to generate source. Existing changes will be reviewed before updating.',
            '选择源码生成方式。更新前会审核已有改动。', '選擇原始碼產生方式。更新前會檢視既有改動。'),
        }, function(_, choice)
          if not current(snapshot) or not choice then return end
          if choice == 2 then return create_new() end
          if choice ~= 1 then return end
          if #dirty_buffers(project) > 0 or #reloads_pending(state) > 0 then
            return session.ui_helpers.fail(tr('Save or session.ui_helpers.reconcile project buffers before updating source.', '更新源码前请保存或处理项目缓冲区。', '更新原始碼前請儲存或處理專案緩衝區。'))
          end
          local latest = vim.uv.fs_lstat(file_path)
          local file = latest and latest.type == 'file' and latest.size <= 128 * 1024 and io.open(file_path, 'rb') or nil
          local contents = file and file:read(128 * 1024 + 1) or nil
          if file then file:close() end
          if not contents or #contents > 128 * 1024 then
            return session.ui_helpers.fail(tr('Cannot read the selected source file.', '无法读取所选源码文件。', '無法讀取所選原始碼檔案。'))
          end
          execute(snapshot, 'generate', filename, callback, vim.fn.sha256(contents))
        end)
      end,
      back = function()
        if not session.ui_helpers.context() then return end
        render(state)
        if state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
          pcall(vim.api.nvim_set_current_win, state.panel_win)
        end
      end,
    })
  end)
end

open_model_builder = function(state)
  if state.closed or state.busy then return end
  local builder = require('model_maven.model_builder')
  local saved, failure = builder.load(state.opts.project)
  if failure then notify(failure, vim.log.levels.WARN); return end
  if saved and saved.kind == 'image_classification' then
    local project, cli, epoch, revision = state.opts.project, state.opts.cli, state.change_epoch or 0, saved.base_revision
    local _, status = project_config(project)
    if status ~= 'missing' then
      local function current()
        if state.closed or state.opts.project ~= project or state.opts.cli ~= cli
            or (state.change_epoch or 0) ~= epoch or not project_config_current(state) or #dirty_buffers(project) > 0 then return false end
        local latest = builder.load(project)
        return latest and latest.kind == 'image_classification' and latest.base_revision == revision
      end
      local function save_declaration(field, value)
        if not current() then notify(tr('Project changed or has unsaved files; reopen the image project.',
          '项目已变化或有未保存文件，请重新打开图像项目。', '專案已變更或有未儲存檔案，請重新開啟影像專案。'), vim.log.levels.WARN); return end
        local args = { 'recipe-update', '--if-recipe', revision, '--' .. field, vim.json.encode(value) }
        state.busy = tr('Planning declaration update', '规划声明更新', '規劃宣告更新'); render(state)
        request(state, args, function(report, err, stderr)
          state.busy = nil
          if not current() then render(state); return end
          state.last = { report = report, transport_error = err, stderr = stderr }; render(state)
          local buf, data = show_report(state), report and report.data
          if err or not report or report.operation ~= 'recipe_update' or report.status ~= 'success'
              or type(data) ~= 'table' or data.committed ~= false or not sha256(data.plan_revision)
              or type(data.plan) ~= 'table' or data.plan.recipe_revision ~= revision
              or type(data.plan.recipe) ~= 'table' or not vim.deep_equal(data.plan.recipe[field] or vim.NIL, value) then return end
          local displayed = state.last
          review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Save declaration', '保存声明', '儲存宣告') },
            tr('Save the reviewed declaration?', '保存已审核的声明？', '儲存已檢視的宣告？'), function(_, accepted)
            if accepted ~= 2 or not current() or state.last ~= displayed then return end
            local tracked = begin_tracked_commit(state, tr('Save declaration', '保存声明', '儲存宣告'))
            if not tracked then return end
            local apply = vim.deepcopy(args); vim.list_extend(apply, { '--apply', '--if-plan', data.plan_revision })
            state.busy = tr('Saving declaration', '保存声明', '儲存宣告'); render(state)
            request(state, apply, function(receipt, failure, output)
              state.busy = nil
              local updated = receipt and receipt.operation == 'recipe_update' and receipt.status == 'success'
                and type(receipt.data) == 'table' and receipt.data.committed == true and receipt.data.plan_revision == data.plan_revision
              local settled = settle_tracked_commit(state, tracked, updated, failure)
              if state.closed or state.opts.project ~= project then notify_tracked_context_changed(tracked); return end
              state.last = { report = receipt, transport_error = failure, stderr = output }
              if updated and settled then state.change_epoch = (state.change_epoch or 0) + 1 end
              refresh_project(state); render(state); show_report(state)
            end, nil, false, current)
          end, nil, true)
        end)
      end
      local snapshot_status = ''
      if saved.source then
        local path = project .. '/classification.py'
        local stat = vim.uv.fs_lstat(path)
        local file = stat and stat.type == 'file' and stat.size <= 2 * 1024 * 1024 and io.open(path, 'rb') or nil
        local raw = file and file:read(2 * 1024 * 1024 + 1) or nil
        if file then file:close() end
        if not raw or #raw > 2 * 1024 * 1024 then
          snapshot_status = tr(' · current source unavailable', ' · 当前源码不可用', ' · 目前原始碼無法使用')
        elseif vim.fn.sha256(raw) ~= saved.source.sha256 then
          snapshot_status = tr(' · source changed since snapshot', ' · 源码在快照后已修改', ' · 原始碼在快照後已修改')
        else snapshot_status = tr(' · source matches snapshot', ' · 源码与快照一致', ' · 原始碼與快照一致') end
      else snapshot_status = tr(' · no source snapshot', ' · 尚未保存源码快照', ' · 尚未儲存原始碼快照') end
      local info = state.project_info
      local binding_status = ''
      if type(info) == 'table' then
        if info.model ~= 'classification:model' or info.batch ~= 'classification:batch' then
          binding_status = tr(' · project model or input differs from this classification declaration',
            ' · 项目模型或输入与此分类声明不同', ' · 專案模型或輸入與此分類宣告不同')
        else
          binding_status = tr(' · project uses classification entrypoints (parameters and behavior not verified)',
            ' · 项目使用分类入口（参数与行为尚未验证）', ' · 專案使用分類入口（參數與行為尚未驗證）')
        end
      end
      vim.ui.select({ tr('Open editable classification source', '打开可编辑的分类源码', '開啟可編輯的分類原始碼'),
        tr('Save current training settings', '保存当前训练设置', '儲存目前訓練設定'),
        tr('Link supervision file', '关联监督文件', '連結監督檔案'),
        tr('Remove supervision reference', '移除监督引用', '移除監督參照'),
        tr('Snapshot editable source for rebuild', '保存源码快照以供重建', '儲存原始碼快照以供重建'),
        tr('Remove source snapshot reference', '移除源码快照引用', '移除原始碼快照參照'),
        tr('Package project for transfer', '打包项目以供迁移', '打包專案以供遷移'),
        tr('Save project runtime paths', '保存项目运行路径', '儲存專案執行路徑'),
        tr('Design another model in the graph canvas', '在图画布设计另一个模型', '在圖畫布設計另一個模型'),
        tr('Cancel', '取消', '取消') }, {
        prompt = tr('Image classification declaration: ', '图像分类声明：', '影像分類宣告：') .. saved.preset .. snapshot_status .. binding_status,
      }, function(_, choice)
        if choice == 1 and not state.closed and state.opts.project == project then
          vim.cmd({ cmd = 'edit', args = { project .. '/classification.py' } })
        elseif choice == 2 and current() then
          local previous, info = state.last_training_entry, state.project_info
          if not previous or not info or previous.project ~= project or previous.model ~= (state.model or info.model)
              or previous.config_revision ~= info.config_revision or type(previous.params) ~= 'string' then
            notify(tr('Prepare a training trial in this project first.', '请先在当前项目准备一次训练试跑。', '請先在目前專案準備一次訓練試跑。'), vim.log.levels.WARN); return
          end
          local ok, params = pcall(vim.json.decode, previous.params)
          if not ok or type(params) ~= 'table' then notify(tr('Training parameters are unavailable.', '训练参数不可用。', '訓練參數無法使用。'), vim.log.levels.WARN); return end
          local entry = previous.value == 'classification:step' and previous.mode ~= 'external-loop' and '$model:step' or previous.value
          local optimizer, chosen = nil, state.last_training_optimizer
          if previous.mode ~= 'external-loop' and chosen and chosen.project == project and chosen.model == previous.model
              and chosen.mode == previous.mode and chosen.entry == previous.value and chosen.revision == previous.config_revision
              and chosen.cli == state.opts.cli and chosen.python == state.opts.python then
            optimizer = optimizer_profile(chosen.args)
            if not optimizer then notify(tr('Optimizer settings cannot be saved.', '无法保存优化器设置。', '無法儲存最佳化器設定。'), vim.log.levels.WARN); return end
          elseif previous.mode ~= 'external-loop' and saved.training and saved.training.entry == entry then
            optimizer = vim.deepcopy(saved.training.optimizer)
          end
          save_declaration('training', { mode = previous.mode, entry = entry, params = params, optimizer = optimizer })
        elseif choice == 3 and current() then
          vim.ui.input({ prompt = tr('Project-relative supervision file: ', '项目内监督文件路径：', '專案內監督檔案路徑：'),
            default = 'supervision.json', completion = 'file' }, function(value)
            if not value or not current() then return end
            if value == '' or #value > 1024 or value:find('[%c\\:]') or value:sub(1, 1) == '/'
                or value:match('^%./') or value:match('/%./') or value:match('/%.$')
                or value:match('^%.%.$') or value:match('^%.%./') or value:match('/%.%./') or value:match('/%.%.$') then
              notify(tr('Choose a project-relative path without parent segments.', '请选择不含上级目录的项目相对路径。', '請選擇不含上層目錄的專案相對路徑。'), vim.log.levels.WARN); return
            end
            local path = project .. '/' .. value
            local stat, resolved = vim.uv.fs_lstat(path), vim.uv.fs_realpath(path)
            if not stat or stat.type ~= 'file' or stat.size > 2 * 1024 * 1024 or not resolved or not in_project(project, resolved) then
              notify(tr('Choose a regular supervision file inside the project (at most 2 MiB).', '请选择项目内不超过 2 MiB 的普通监督文件。', '請選擇專案內不超過 2 MiB 的一般監督檔案。'), vim.log.levels.WARN); return
            end
            local file = io.open(path, 'rb'); local raw = file and file:read(2 * 1024 * 1024 + 1) or nil
            if file then file:close() end
            local ok, bundle = pcall(vim.json.decode, raw or '')
            if not raw or #raw > 2 * 1024 * 1024 or not ok or type(bundle) ~= 'table'
                or bundle.format ~= 'model-maven-supervision-bundle-v1' or type(bundle.state) ~= 'table'
                or not is_list(bundle.state.marks) then
              notify(tr('The file is not a supported supervision bundle.', '该文件不是受支持的监督声明。', '該檔案不是受支援的監督宣告。'), vim.log.levels.WARN); return
            end
            save_declaration('supervision', { file = value, sha256 = vim.fn.sha256(raw) })
          end)
        elseif choice == 4 and current() then
          save_declaration('supervision', vim.NIL)
        elseif choice == 5 and current() then
          vim.ui.input({ prompt = tr('New source snapshot filename in project (will not overwrite): ',
            '项目内新源码快照文件名（不会覆盖）：', '專案內新原始碼快照檔名（不會覆蓋）：'), default = 'classification.snapshot.py' }, function(name)
            if not name or not current() then return end
            if #name > 200 or not name:match('^[%w_.-]+%.py$') or name == 'classification.py' or name == '.' or name == '..' then
              notify(tr('Choose a new Python filename in the project root.', '请选择项目根目录中的新 Python 文件名。', '請選擇專案根目錄中的新 Python 檔名。'), vim.log.levels.WARN); return
            end
            local path = project .. '/classification.py'
            local stat, resolved = vim.uv.fs_lstat(path), vim.uv.fs_realpath(path)
            if not stat or stat.type ~= 'file' or stat.size > 2 * 1024 * 1024 or not resolved or not in_project(project, resolved) then
              notify(tr('Current classification source is not a readable project file up to 2 MiB.', '当前分类源码不是项目内不超过 2 MiB 的可读文件。', '目前分類原始碼不是專案內不超過 2 MiB 的可讀檔案。'), vim.log.levels.WARN); return
            end
            local input = io.open(path, 'rb'); local raw = input and input:read(2 * 1024 * 1024 + 1) or nil
            if input then input:close() end
            if not raw or #raw > 2 * 1024 * 1024 then notify(tr('Cannot read source.', '无法读取源码。', '無法讀取原始碼。'), vim.log.levels.WARN); return end
            vim.ui.select({ tr('Create snapshot', '创建快照', '建立快照'), tr('Cancel', '取消', '取消') }, {
              prompt = tr('Create a new copy before reviewing the reference; cancelled reviews keep the copy.',
                '审核引用前创建新副本；取消审核时副本仍会保留。', '檢視參照前建立新副本；取消檢視時副本仍會保留。'),
            }, function(_, approved)
              if approved ~= 1 or not current() then return end
              local target = project .. '/' .. name
              local fd, err = vim.uv.fs_open(target, 'wx', 384)
              if not fd then notify(tr('Cannot create snapshot: ', '无法创建快照：', '無法建立快照：') .. tostring(err), vim.log.levels.ERROR); return end
              local written = vim.uv.fs_write(fd, raw, 0)
              local synced = written == #raw and vim.uv.fs_fsync(fd)
              vim.uv.fs_close(fd)
              if not synced then vim.uv.fs_unlink(target); notify(tr('Could not finish snapshot.', '无法完成源码快照。', '無法完成原始碼快照。'), vim.log.levels.ERROR); return end
              save_declaration('source', { file = name, sha256 = vim.fn.sha256(raw) })
            end)
          end)
        elseif choice == 6 and current() then
          save_declaration('source', vim.NIL)
        elseif choice == 7 and current() then
          vim.ui.input({ prompt = tr('New package directory name: ', '新项目包目录名：', '新專案包目錄名稱：'), default = 'model-maven-bundle' }, function(output)
            if not output or not current() then return end
            if #output > 128 or not output:match('^[%w_.-]+$') or output == '.' or output == '..' then
              notify(tr('Choose a new directory name in the project root.', '请选择项目根目录中的新目录名。', '請選擇專案根目錄中的新目錄名稱。'), vim.log.levels.WARN); return
            end
            local includes = {}
            local function plan_package()
              if not current() then return end
              local args = { 'recipe-bundle', '--output', output }
              for _, path in ipairs(includes) do vim.list_extend(args, { '--include', path }) end
              state.busy = tr('Planning project package', '规划项目文件包', '規劃專案檔案包'); render(state)
              request(state, args, function(report, err, stderr)
                state.busy = nil
                if not current() then render(state); return end
                state.last = { report = report, transport_error = err, stderr = stderr }; render(state)
                local buf, data = show_report(state), report and report.data
                if err or not report or report.operation ~= 'recipe_bundle' or report.status ~= 'success'
                    or type(data) ~= 'table' or data.committed ~= false or not sha256(data.plan_revision)
                    or type(data.plan) ~= 'table' or data.plan.output ~= output or not vim.deep_equal(data.plan.includes, includes)
                    or type(data.plan.files) ~= 'table' then return end
                local displayed = state.last
                review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Create package', '创建文件包', '建立檔案包') },
                  tr('Create the reviewed project package?', '创建已审核的项目文件包？', '建立已檢視的專案檔案包？'), function(_, accepted)
                  if accepted ~= 2 or not current() or state.last ~= displayed then return end
                  local tracked = begin_tracked_commit(state, tr('Create project package', '创建项目文件包', '建立專案檔案包'))
                  if not tracked then return end
                  local apply = vim.deepcopy(args); vim.list_extend(apply, { '--apply', '--if-plan', data.plan_revision })
                  state.busy = tr('Creating project package', '创建项目文件包', '建立專案檔案包'); render(state)
                  request(state, apply, function(receipt, failure, stderr2)
                    state.busy = nil
                    local created = receipt and receipt.operation == 'recipe_bundle' and receipt.status == 'success'
                      and type(receipt.data) == 'table' and receipt.data.committed == true and receipt.data.plan_revision == data.plan_revision
                    local settled = settle_tracked_commit(state, tracked, created, failure)
                    if state.closed or state.opts.project ~= project then notify_tracked_context_changed(tracked); return end
                    state.last = { report = receipt, transport_error = failure, stderr = stderr2 }
                    if created and settled then state.change_epoch = (state.change_epoch or 0) + 1 end
                    refresh_project(state); render(state); show_report(state)
                  end, nil, false, current)
                end, nil, true)
              end)
            end
            local choose
            choose = function()
              if not current() then return end
              local choices = { tr('Add project file or directory', '添加项目内文件或目录', '新增專案內檔案或目錄'),
                tr('Choose discovered source or environment files', '选择发现的源码或环境文件', '選擇探索到的原始碼或環境檔案'),
                tr('Remove last selection', '移除最后一项', '移除最後一項'),
                tr('Review package', '审核文件包', '檢視檔案包'), tr('Cancel', '取消', '取消') }
              vim.ui.select(choices, { prompt = tr('Selected: ', '已选择：', '已選擇：') .. (#includes > 0 and table.concat(includes, ', ') or tr('none', '无', '無'))
                .. tr(' · recipe and referenced files are included automatically', ' · 自动包含声明和引用文件', ' · 自動包含宣告和參照檔案') }, function(_, action)
                if not action or not current() then return end
                if action == 1 then
                  vim.ui.input({ prompt = tr('Project-relative file or directory (data and dependency files are optional): ',
                    '项目内文件或目录（可选择数据和依赖文件）：', '專案內檔案或目錄（可選擇資料和相依檔案）：'),
                    default = #includes == 0 and saved.image_data or '', completion = 'file' }, function(path)
                    if not path or not current() then return end
                    if path == '' or #includes >= 128 then notify(tr('Choose a path; at most 128 selections.', '请选择路径；最多 128 项。', '請選擇路徑；最多 128 項。'), vim.log.levels.WARN); return end
                    includes[#includes + 1] = path; choose()
                  end)
                elseif action == 2 then
                  local args = { 'discover' }
                  for _, root in ipairs(state.opts.project_import_roots or {}) do vim.list_extend(args, { '--import-root', root }) end
                  state.busy = tr('Discovering project files', '查找项目文件', '尋找專案檔案'); render(state)
                  request(state, args, function(report, err)
                    state.busy = nil; render(state)
                    if not current() then return end
                    local data = report and report.data
                    if err or not report or report.status ~= 'success' or report.operation ~= 'project_discover'
                        or type(data) ~= 'table' or type(data.source_files) ~= 'table' or not is_list(data.source_files)
                        or type(data.environment_candidates) ~= 'table' or not is_list(data.environment_candidates) then
                      notify(tr('This CLI cannot discover package candidates; add paths manually.', '当前 CLI 无法发现打包候选，请手动添加路径。', '目前 CLI 無法探索打包候選，請手動新增路徑。'), vim.log.levels.WARN); choose(); return
                    end
                    local paths, labels, seen = {}, {}, {}
                    for _, group in ipairs({ { (state.project_info and state.project_info.project_import_roots) or {}, tr('Configured import directory', '已配置的模块目录', '已設定的模組目錄') },
                        { data.source_files, tr('Source', '源码', '原始碼') },
                        { data.environment_candidates, tr('Possible environment file', '可能的环境文件', '可能的環境檔案') } }) do
                      for _, path in ipairs(group[1]) do
                        if type(path) == 'string' and path ~= 'classification.py' and #path <= 1024 and not path:find('[%c]')
                            and not seen[path] and not vim.tbl_contains(includes, path) then
                          seen[path] = true; paths[#paths + 1] = path; labels[#labels + 1] = group[2] .. ' · ' .. path
                        end
                      end
                    end
                    if #paths == 0 then notify(tr('No additional candidates were found.', '没有发现其他候选文件。', '沒有探索到其他候選檔案。'), vim.log.levels.INFO); choose(); return end
                    vim.ui.select(labels, { prompt = (data.truncated and tr('Scan truncated. ', '扫描已截断。', '掃描已截斷。') or '')
                      .. tr('Static candidates only; imports and dynamic dependencies are not verified.',
                        '仅为静态候选，未验证导入或动态依赖。', '僅為靜態候選，未驗證匯入或動態相依。') }, function(_, index)
                      if not current() then return end
                      if index and paths[index] and #includes < 128 then includes[#includes + 1] = paths[index] end
                      choose()
                    end)
                  end)
                elseif action == 3 then table.remove(includes); choose()
                elseif action == 4 then plan_package() end
              end)
            end
            choose()
          end)
        elseif choice == 8 and current() then
          local info, root = state.project_info, vim.uv.fs_realpath(project)
          if type(info) ~= 'table' or not root then return end
          local directory = info.working_directory
          if type(directory) == 'string' then
            local resolved = vim.uv.fs_realpath(directory)
            if not resolved or (resolved ~= root and not in_project(root, resolved)) then
              notify(tr('The saved working directory is outside this project; choose a project-local directory first.',
                '已保存的运行目录位于项目之外；请先选择项目内目录。', '已儲存的執行目錄位於專案之外；請先選擇專案內目錄。'), vim.log.levels.WARN); return
            end
            directory = resolved == root and nil or resolved:sub(#root + 2)
          else directory = nil end
          save_declaration('runtime', { working_directory = directory or vim.NIL,
            project_import_roots = vim.deepcopy(info.project_import_roots or {}) })
        elseif choice == 9 and current() then
          local graph_stat, _, graph_error = vim.uv.fs_lstat(project .. '/model-graph.json')
          local can_wrap = not graph_stat and graph_error == 'ENOENT'
            and (not state.graph_canvas or state.graph_canvas.project ~= project)
          local options = {tr('Open graph canvas', '打开图画布', '開啟圖畫布')}
          if can_wrap then options[#options + 1] = tr('Review the selected model as one custom block',
            '审核将当前模型作为一个自定义块', '檢視將目前模型作為一個自訂區塊') end
          options[#options + 1] = tr('Cancel', '取消', '取消')
          vim.ui.select(options, {
            prompt = tr('The graph is a separate draft. Existing classification source and declaration are not converted; review the dataset and model binding separately.',
              '图是独立草稿，不会自动转换现有分类源码和声明；数据集与模型绑定需分别审核。',
              '圖是獨立草稿，不會自動轉換既有分類原始碼和宣告；資料集與模型繫結須分別檢視。'),
          }, function(_, selected)
            if not current() then return end
            if selected == 1 then sessions.open_graph_canvas(state)
            elseif selected == 2 and can_wrap then
              local stat, _, code = vim.uv.fs_lstat(project .. '/model-graph.json')
              if stat or code ~= 'ENOENT' or (state.graph_canvas and state.graph_canvas.project == project) then
                return notify(tr('A graph or graph draft appeared; reopen the canvas to review it.',
                  '图文件或图草稿已出现，请重新打开画布审核。', '圖檔或圖草稿已出現，請重新開啟畫布檢視。'), vim.log.levels.WARN)
              end
              local model = state.project_info and state.project_info.model
              local config_revision = state.project_info and state.project_info.config_revision
              if type(model) ~= 'string' or model == '' then
                return notify(tr('Choose a model factory in project settings first.', '请先在项目设置中选择模型工厂。', '請先在專案設定中選擇模型工廠。'), vim.log.levels.WARN)
              end
              local function stable()
                local latest, _, latest_code = vim.uv.fs_lstat(project .. '/model-graph.json')
                return current() and not state.busy and not latest and latest_code == 'ENOENT'
                  and (not state.graph_canvas or state.graph_canvas.project ~= project)
                  and state.project_info and state.project_info.model == model and state.project_info.config_revision == config_revision
              end
              state.busy = tr('Checking graph import support', '检查图导入能力', '檢查圖匯入能力'); render(state)
              request(state, {'--describe-interface'}, function(interface, failure)
                state.busy = nil; render(state)
                if not stable() then return end
                local caps = interface and interface.data and interface.data.capabilities
                if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
                    or type(caps) ~= 'table' or caps['project.graph_import_scaffold_preview_v1'] ~= true then
                  return notify(tr('The selected CLI cannot preview this graph import.', '所选 CLI 无法预览此图导入。', '所選 CLI 無法預覽此圖匯入。'), vim.log.levels.WARN)
                end
                state.busy = tr('Planning graph import', '规划图导入', '規劃圖匯入'); render(state)
                local args = {'graph-import-scaffold', '--recipe', project .. '/model-maven.json', '--if-recipe', revision, '--model', model}
                local carry_project = caps['project.graph_import_project_data_v1'] == true and sha256(config_revision)
                if carry_project then vim.list_extend(args, {'--if-project', config_revision}) end
                request(state, args, function(report, error, stderr)
                  state.busy = nil; render(state)
                  if not stable() then return end
                  state.last = {report = report, transport_error = error, stderr = stderr}
                  local buffer, data = show_report(state), report and report.data
                  if error or not report or report.operation ~= 'graph_import_scaffold' or report.status ~= 'success'
                      or type(data) ~= 'table' or data.committed ~= false or data.recipe_sha256 ~= revision
                      or data.representation ~= 'opaque_model_wrapper' or data.source_kind ~= 'image_classification'
                      or (carry_project and data.project_revision ~= config_revision)
                      or type(data.graph) ~= 'table' then return end
                  local shown = state.last
                  review_gate(buffer, {tr('Cancel', '取消', '取消'), tr('Open graph draft', '打开图草稿', '開啟圖草稿')},
                    data.data_origin == 'project_config' and tr('Open this wrapper draft? Review the copied data, loss and training before running.',
                      '打开此包装草稿？运行前请审核带入的数据、损失和训练。', '開啟此包裝草稿？執行前請檢視帶入的資料、損失與訓練。')
                    or tr('Open this wrapper draft? Data and loss need configuration; review any retained training.',
                      '打开此包装草稿？数据和损失需要配置；请审核保留的训练声明。', '開啟此包裝草稿？資料與損失需要設定；請檢視保留的訓練宣告。'), function(_, accepted)
                      if accepted == 2 and stable() and state.last == shown then sessions.open_graph_canvas(state, data.graph) end
                    end, nil, false)
                end)
              end)
            end
          end)
        end
      end)
      return
    end
    local function stable()
      if state.closed or state.opts.project ~= project or state.opts.cli ~= cli or (state.change_epoch or 0) ~= epoch
          or select(2, project_config(project)) ~= 'missing' or #dirty_buffers(project) > 0 then return false end
      local current = builder.load(project)
      return current and current.kind == 'image_classification' and current.base_revision == revision
    end
    if not stable() then notify(tr('Save project buffers before rebuilding.', '重建前请保存项目缓冲区。', '重建前請儲存專案緩衝區。'), vim.log.levels.WARN); return end
    vim.ui.select({ tr('Review rebuild', '审核重建', '檢視重建'), tr('Cancel', '取消', '取消') }, {
      prompt = tr('Rebuild image project from declaration; data path: ', '从声明重建图像项目；数据路径：', '從宣告重建影像專案；資料路徑：') .. saved.image_data,
    }, function(_, choice)
      if choice ~= 1 or not stable() then return end
      local args = { 'create', '--recipe', project .. '/model-maven.json' }
      state.busy = tr('Planning image project', '规划图像项目', '規劃影像專案'); render(state)
      request(state, args, function(plan, err, stderr)
        state.busy = nil
        if not stable() then render(state); return end
        state.last = { report = plan, transport_error = err, stderr = stderr }; render(state)
        local buf, data = show_report(state), plan and plan.data
        if err or not plan or plan.operation ~= 'create' or plan.status ~= 'success' or type(data) ~= 'table'
            or data.committed ~= false or not sha256(data.plan_revision) or type(data.plan) ~= 'table'
            or data.plan.preset ~= saved.preset or not vim.deep_equal(data.plan.classes, saved.classes) then return end
        local displayed = state.last
        review_gate(buf, { tr('Cancel', '取消', '取消'), tr('Rebuild project', '重建项目', '重建專案') },
          tr('Rebuild this image project?', '重建此图像项目？', '重建此影像專案？'), function(_, accepted)
          if accepted ~= 2 or not stable() or state.last ~= displayed then return end
          local tracked = begin_tracked_commit(state, tr('Rebuild image project', '重建图像项目', '重建影像專案'))
          if not tracked then return end
          local apply = vim.deepcopy(args); vim.list_extend(apply, { '--apply', '--if-plan', data.plan_revision })
          state.busy = tr('Rebuilding image project', '重建图像项目', '重建影像專案'); render(state)
          request(state, apply, function(receipt, problem, output)
            state.busy = nil
            local created = receipt and receipt.operation == 'create' and receipt.status == 'success'
              and type(receipt.data) == 'table' and receipt.data.committed == true and receipt.data.plan_revision == data.plan_revision
              and receipt.data.model == 'classification:model' and receipt.data.batch == 'classification:batch'
            local settled = settle_tracked_commit(state, tracked, created, problem)
            if state.closed or state.opts.project ~= project then notify_tracked_context_changed(tracked); return end
            state.last = { report = receipt, transport_error = problem, stderr = output }
            if created and settled then
              state.change_epoch = (state.change_epoch or 0) + 1
              state.starter_step = { model = receipt.data.model, step = 'classification:step' }
            end
            refresh_project(state); render(state); show_report(state)
          end, nil, false, stable)
        end, nil, true)
      end)
    end)
    return
  end
  if not saved and select(2, project_config(state.opts.project)) ~= 'missing' then
    notify(tr('Open an unconfigured project to create a starter.', '请在未配置的项目中创建模型。',
      '請在未設定的專案中建立模型。'), vim.log.levels.WARN)
    return
  end
  local project, epoch = state.opts.project, state.change_epoch
  local canvas_project_config = saved and project_config(project) or nil
  local saved_encoder_names = {}
  for _, input in ipairs(saved and saved.inputs or {}) do saved_encoder_names[input.name] = true end
  state.builder_recovery_checked = state.builder_recovery_checked or {}
  if not state.builder_draft and not state.builder_recovery_checked[project] then
    state.builder_recovery_checked[project] = true
    local files, error = builder_drafts.list(project)
    if error then notify(tr('Could not read model draft recovery files: ', '无法读取模型草稿恢复文件：', '無法讀取模型草稿復原檔案：') .. tostring(error), vim.log.levels.WARN) end
    local candidates, choices = {}, {tr('Start from the saved declaration', '从已保存声明开始', '從已儲存宣告開始'), tr('Cancel', '取消', '取消')}
    for _, file in ipairs(files) do
      local ok, recovered = pcall(builder.restore_snapshot, file.raw)
      if ok and recovered then
        candidates[#candidates + 1] = {draft = recovered, base = file.base}
        choices[#choices + 1] = tr('Recover ', '恢复 ', '復原 ') .. file.name
          .. ((recovered.base_revision == (saved and saved.base_revision))
            and tr(' · current base', ' · 基础版本一致', ' · 基礎版本一致')
            or tr(' · base changed; review required', ' · 基础版本已变化，需核对', ' · 基礎版本已變更，需核對'))
      end
    end
    if #candidates > 0 then
      vim.ui.select(choices, { prompt = tr('Recover a model draft? Recovery files are not saved project declarations.',
        '恢复模型草稿？恢复文件不等于已保存的项目声明。', '復原模型草稿？復原檔案不等於已儲存的專案宣告。') }, function(_, choice)
        if not choice or choice == 2 or state.closed or state.opts.project ~= project or state.builder_draft then return end
        if choice > 2 then
          local candidate = candidates[choice - 2]
          state.builder_draft, state.builder_recovery_base = candidate.draft, candidate.base
          state.builder_from_recovery = true
        end
        open_model_builder(state)
      end)
      return
    end
  end
  if not state.builder_draft then
    state.builder_draft = saved or { inputs = {}, outputs = {} }
    state.builder_recovery_base, state.builder_from_recovery = nil, nil
  elseif state.builder_draft.base_revision ~= (saved and saved.base_revision)
      and state.stale_builder_ack ~= state.builder_draft then
    local previous, prior_revision = state.builder_draft, saved and saved.base_revision
    vim.ui.select({tr('Keep the existing draft', '保留当前草稿', '保留目前草稿'),
      tr('Review a three-way merge', '审核三方合并', '檢視三方合併'),
      tr('Replace it with the saved declaration', '用已保存声明替换草稿', '以已儲存宣告取代草稿'),
      tr('Cancel', '取消', '取消')}, {
      prompt = tr('The declaration changed while your draft was open. Keeping the draft requires conflict review before saving.',
        '草稿打开期间声明已变化。保留草稿后需解决冲突才能保存。', '草稿開啟期間宣告已變更。保留草稿後需解決衝突才能儲存。'),
    }, function(_, choice)
      if state.closed or state.opts.project ~= project or state.builder_draft ~= previous or not choice or choice == 4 then return end
      local latest = builder.load(project)
      if (latest and latest.base_revision) ~= prior_revision then
        notify(tr('The declaration changed again; reopen the canvas.', '声明再次变化，请重新打开画布。', '宣告再次變更，請重新開啟畫布。'), vim.log.levels.WARN); return
      end
      if choice == 2 then
        if not project_config_current(state) then
          notify(tr('Project configuration changed; refresh it before merging.', '项目配置已变化，请刷新后再合并。', '專案設定已變更，請重新整理後再合併。'), vim.log.levels.WARN); return
        end
        local checkpoint = state.builder_checkpoint
        local base = checkpoint and checkpoint.draft == previous and checkpoint.base or state.builder_recovery_base
        local mine, mine_error = builder_drafts.snapshot(previous)
        local theirs = latest and builder_drafts.snapshot(latest)
        if not mine or not theirs then
          notify(tr('Cannot prepare merge: ', '无法准备合并：', '無法準備合併：') .. tostring(mine_error or 'saved declaration unavailable'), vim.log.levels.WARN); return
        end
        local merged, conflicts, sections = builder_drafts.merge(base, mine, theirs, builder.restore_snapshot)
        if not merged then
          notify(tr('Merge needs manual resolution; drafts remain unchanged: ', '合并需要手动解决，草稿未改动：', '合併需要手動解決，草稿未變更：')
            .. table.concat(conflicts or {}, ', '), vim.log.levels.WARN); return
        end
        local merged_raw = builder_drafts.snapshot(merged)
        if not merged_raw then notify(tr('Cannot encode merge preview.', '无法编码合并预览。', '無法編碼合併預覽。'), vim.log.levels.WARN); return end
        local before = vim.inspect(vim.json.decode(mine)) .. '\n'
        local after = vim.inspect(vim.json.decode(merged_raw)) .. '\n'
        local ok, diff = pcall(vim.diff, before, after, {result_type = 'unified', ctxlen = 3})
        if not ok or not reviewable_text(diff) then notify(tr('Merge preview is too large to review.', '合并预览过大，无法审核。', '合併預覽過大，無法檢視。'), vim.log.levels.WARN); return end
        local buf = vim.api.nvim_create_buf(false, true)
        vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
        local lines = {tr('Proposed merge into the in-memory draft; project files are unchanged.',
          '拟合并到内存草稿；项目文件不会在此步骤修改。', '擬合併至記憶體草稿；專案檔案不會在此步驟修改。'),
          tr('Changed sections: ', '变化的部分：', '變更的部分：') .. table.concat(sections or {}, ', '), ''}
        vim.list_extend(lines, vim.split(diff, '\n', {plain = true}))
        vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines); vim.bo[buf].modifiable = false
        if not open_aux_buffer(buf, false, false) then return end
        local review_win = vim.api.nvim_get_current_win()
        vim.keymap.set('n', 'q', function()
          if vim.api.nvim_win_is_valid(review_win) and vim.api.nvim_win_get_buf(review_win) == buf then pcall(vim.api.nvim_win_close, review_win, false) end
        end, {buffer = buf, silent = true, desc = 'Cancel draft merge'})
        review_gate(buf, {tr('Cancel', '取消', '取消'), tr('Apply to draft', '应用到草稿', '套用至草稿')},
          tr('Apply the reviewed merge to the draft?', '将审核后的合并应用到草稿？', '將檢視後的合併套用至草稿？'), function(_, answer)
          if answer ~= 2 or state.closed or state.opts.project ~= project or not project_config_current(state) or state.builder_draft ~= previous
              or builder_drafts.snapshot(previous) ~= mine then return end
          local now = builder.load(project)
          if not now or now.base_revision ~= prior_revision or builder_drafts.snapshot(now) ~= theirs then
            notify(tr('The saved declaration changed again; review the merge again.', '已保存声明再次变化，请重新审核合并。', '已儲存宣告再次變更，請重新檢視合併。'), vim.log.levels.WARN); return
          end
          state.builder_draft, state.stale_builder_ack = merged, nil
          state.builder_recovery_base, state.builder_from_recovery, state.builder_checkpoint = theirs, true, nil
          if vim.api.nvim_win_is_valid(review_win) and vim.api.nvim_win_get_buf(review_win) == buf then pcall(vim.api.nvim_win_close, review_win, false) end
          open_model_builder(state)
        end, nil, true)
        return
      end
      if choice == 1 then state.stale_builder_ack = previous
      elseif choice == 3 then
        state.builder_draft, state.stale_builder_ack = latest or {inputs = {}, outputs = {}}, nil
        state.builder_recovery_base, state.builder_from_recovery, state.builder_checkpoint = nil, nil, nil
      end
      open_model_builder(state)
    end)
    return
  end
  if state.stale_builder_ack == state.builder_draft then state.stale_builder_ack = nil end
  local function same_context()
    return not state.closed and state.opts.project == project and state.change_epoch == epoch
  end
  local checkpoint = state.builder_checkpoint
  if not checkpoint or checkpoint.draft ~= state.builder_draft or checkpoint.project ~= project then
    local initial, snapshot_error = builder_drafts.snapshot(state.builder_draft)
    local merge_base
    if state.builder_from_recovery then merge_base = state.builder_recovery_base else merge_base = initial end
    if state.builder_from_recovery and not merge_base and saved and state.builder_draft.base_revision == saved.base_revision then
      merge_base = builder_drafts.snapshot(saved)
    end
    checkpoint = {draft = state.builder_draft, project = project,
      baseline = (state.builder_from_recovery and merge_base) or initial, latest = initial, base = merge_base}
    state.builder_checkpoint = checkpoint
    if not initial then notify(tr('Draft recovery is unavailable: ', '草稿恢复不可用：', '草稿復原無法使用：') .. tostring(snapshot_error), vim.log.levels.WARN) end
  end
  local function checkpoint_draft(immediate)
    if state.builder_draft ~= checkpoint.draft or state.opts.project ~= checkpoint.project then return end
    local function flush()
      checkpoint.scheduled = false
      if state.builder_draft ~= checkpoint.draft or state.opts.project ~= checkpoint.project then return end
      local raw, error = builder_drafts.snapshot(checkpoint.draft)
      if not raw then
        if not checkpoint.warned then notify(tr('Draft could not be saved for recovery: ', '无法保存草稿恢复文件：', '無法儲存草稿復原檔案：') .. tostring(error), vim.log.levels.WARN); checkpoint.warned = true end
        return
      end
      checkpoint.latest = raw
      if not checkpoint.handle and checkpoint.latest == checkpoint.baseline then return end
      if not checkpoint.handle then
        local handle, failure = builder_drafts.create(checkpoint.project)
        if not handle then
          if not checkpoint.warned then notify(tr('Draft recovery could not be created: ', '无法创建草稿恢复文件：', '無法建立草稿復原檔案：') .. tostring(failure), vim.log.levels.WARN); checkpoint.warned = true end
          return
        end
        checkpoint.handle = handle
        notify(tr('Model draft recovery is stored in the editor state directory; do not put secrets in parameters.',
          '模型草稿恢复文件保存在编辑器状态目录，请勿在参数中填写密钥。', '模型草稿復原檔案儲存在編輯器狀態目錄，請勿在參數中填寫金鑰。'), vim.log.levels.INFO)
      end
      local packed, pack_error = builder_drafts.pack(checkpoint.latest, checkpoint.base)
      local ok, failure
      if packed then ok, failure = builder_drafts.write(checkpoint.handle, packed) else failure = pack_error end
      if not ok and not checkpoint.warned then
        notify(tr('Draft recovery save failed; keep this session open: ', '草稿恢复保存失败，请保持当前会话：', '草稿復原儲存失敗，請保持目前工作階段：') .. tostring(failure), vim.log.levels.WARN)
        checkpoint.warned = true
      end
    end
    if immediate then flush()
    elseif not checkpoint.scheduled then checkpoint.scheduled = true; vim.defer_fn(flush, 500) end
  end
  local function saved_canvas_current()
    if not same_context() or not saved or not project_config_current(state) then return false end
    local latest = builder.load(project)
    if not latest or latest.base_revision ~= saved.base_revision or state.builder_draft.base_revision ~= saved.base_revision
        or state.builder_draft.reconcile_assembly or (state.model and state.project_info and state.model ~= state.project_info.model)
        or #dirty_buffers(project) > 0 then return false end
    local function input_specs(draft)
      local inputs = {}
      for _, input in ipairs(draft.inputs or {}) do
        inputs[#inputs + 1] = {name = input.name, shape = input.shape, dtype = input.dtype,
          source = input.source and input.source.name or nil, factory = input.factory,
          component_width = input.component_width, native_output = input.native_output, layers = input.layers}
      end
      return inputs
    end
    if not vim.deep_equal(input_specs(state.builder_draft), input_specs(saved)) then return false end
    for _, field in ipairs({'outputs', 'components', 'component_params', 'data', 'training', 'supervision'}) do
      if not vim.deep_equal(state.builder_draft[field], saved[field]) then return false end
    end
    return true
  end
  local graph_file = vim.uv.fs_lstat(project .. '/model-graph.json')
  builder.open(state.builder_draft, {
    checkpoint_draft = checkpoint_draft,
    graph_exists = graph_file ~= nil and graph_file.type == 'file',
    package_project = function()
      if not saved_canvas_current() then
        return notify(tr('Save the canvas and project files before packaging.', '打包前请先保存画布和项目文件。', '打包前請先儲存畫布和專案檔案。'), vim.log.levels.WARN)
      end
      local base, cli = saved.base_revision, state.opts.cli
      local function stable()
        return not state.closed and state.opts.project == project and state.opts.cli == cli
          and same_context() and saved_canvas_current() and state.builder_draft.base_revision == base
      end
      state.busy = tr('Checking package support', '检查打包能力', '檢查打包能力'); render(state)
      request(state, {'--describe-interface'}, function(interface, error)
        state.busy = nil; render(state)
        if not stable() then return end
        local caps = interface and interface.data and interface.data.capabilities
        if error or not interface or interface.status ~= 'success' or interface.operation ~= 'interface'
            or type(caps) ~= 'table' or caps['project.scaffold_recipe_bundle_v1'] ~= true then
          return notify(tr('This CLI cannot package scaffold projects.', '当前 CLI 不支持打包骨架项目。', '目前 CLI 不支援打包骨架專案。'), vim.log.levels.WARN)
        end
        package_project(state, 'scaffold', base, stable)
      end)
    end,
    preview = function(fields)
      if same_context() then create_model(state, fields) end
    end,
    graph_canvas = function()
      if not same_context() then return end
      local path = project .. '/model-graph.json'
      local stat, _, code = vim.uv.fs_lstat(path)
      local info = state.project_info
      local model = info and info.model
      local config_revision = info and info.config_revision
      if not saved or stat or code ~= 'ENOENT' or state.graph_canvas or not saved_canvas_current()
          or type(model) ~= 'string' then return sessions.open_graph_canvas(state) end
      vim.ui.select({tr('Open an empty graph', '打开空图', '開啟空圖'),
        tr('Review a wrapper around the saved model', '审核包装已保存模型', '檢視包裝已儲存模型'),
        tr('Review editable layers from the declaration', '审核从声明生成的可编辑层', '檢視從宣告產生的可編輯層'),
        tr('Cancel', '取消', '取消')}, {
        prompt = tr('Editable migration uses the declaration, not the current source or weights.',
          '可编辑迁移依据声明，不包含当前源码修改或权重。', '可編輯遷移依據宣告，不包含目前原始碼修改或權重。'),
      }, function(_, choice)
        if not choice or choice == 4 or not saved_canvas_current() then return end
        if choice == 1 then return sessions.open_graph_canvas(state) end
        local editable = choice == 3
        local function stable()
          local current_stat, _, current_code = vim.uv.fs_lstat(path)
          return not state.busy and saved_canvas_current() and not current_stat and current_code == 'ENOENT'
            and not state.graph_canvas and state.project_info and state.project_info.model == model
            and state.project_info.config_revision == config_revision
        end
        if not stable() then return end
        state.busy = tr('Checking graph import support', '检查图导入能力', '檢查圖匯入能力'); render(state)
        request(state, {'--describe-interface'}, function(interface, failure)
          state.busy = nil; render(state)
          local caps = interface and interface.data and interface.data.capabilities
          if not stable() then return end
          if failure or not interface or interface.operation ~= 'interface' or interface.status ~= 'success'
              or type(caps) ~= 'table' or caps['project.graph_import_scaffold_preview_v1'] ~= true
              or (editable and caps['project.graph_import_editable_layers_v1'] ~= true) then
            return notify(tr('The selected CLI cannot preview this graph import.', '所选 CLI 无法预览此图导入。', '所選 CLI 無法預覽此圖匯入。'), vim.log.levels.WARN)
          end
          state.busy = tr('Planning graph import', '规划图导入', '規劃圖匯入'); render(state)
          local args = {'graph-import-scaffold', '--recipe', project .. '/model-maven.json',
            '--if-recipe', saved.base_revision, '--model', model}
          local carry_project = caps['project.graph_import_project_data_v1'] == true and sha256(config_revision)
          if carry_project then vim.list_extend(args, {'--if-project', config_revision}) end
          if editable then args[#args + 1] = '--editable' end
          request(state, args, function(report, error, stderr)
            state.busy = nil; render(state)
            if not stable() then return end
            state.last = {report = report, transport_error = error, stderr = stderr}
            local buffer, data = show_report(state), report and report.data
            if error or not report or report.operation ~= 'graph_import_scaffold' or report.status ~= 'success'
                or type(data) ~= 'table' or data.committed ~= false or data.recipe_sha256 ~= saved.base_revision
                or data.representation ~= (editable and 'editable_recipe_layers' or 'opaque_model_wrapper')
                or (carry_project and data.project_revision ~= config_revision)
                or type(data.graph) ~= 'table' then return end
            local shown = state.last
            review_gate(buffer, {tr('Cancel', '取消', '取消'), tr('Open graph draft', '打开图草稿', '開啟圖草稿')},
              tr('Open this graph draft? Original files are retained; runtime behavior is unverified.',
                '打开此图草稿？原文件保留；运行行为尚未验证。', '開啟此圖草稿？原檔案保留；執行行為尚未驗證。'), function(_, selected)
                if selected == 2 and stable() and state.last == shown then sessions.open_graph_canvas(state, data.graph) end
              end, nil, false)
          end)
        end)
      end)
    end,
    selected_supervision = function(kind, name)
      if not saved_canvas_current() then
        return nil, tr('Save the canvas and project files before inspecting this port.',
          '请先保存画布和项目文件，再查看此端口。', '請先儲存畫布與專案檔案，再查看此連接埠。')
      end
      local observed = state.last
      local report = observed and observed.report
      local calls = report and report.status == 'success' and report.operation == 'probe' and report.data and report.data.calls
      if not observed or observed.context_changed or observed.isolated_variant or observed.historical_observation
          or type(calls) ~= 'table' or not is_list(calls) then
        return nil, tr('Run the saved model forward before inspecting this port.',
          '请先运行已保存模型的前向，再查看此端口。', '請先執行已儲存模型的前向，再查看此連接埠。')
      end
      local rows = observed_port_choices(calls)
      local preferred = {path = 'model', port = (kind == 'input' and 'inputs.kwargs.' or 'outputs.') .. name}
      local matches = 0
      for _, row in ipairs(rows) do if row.path == preferred.path and row.port == preferred.port then matches = matches + 1 end end
      if matches ~= 1 then
        return nil, tr('This port was not uniquely observed; run forward or inspect the model report.',
          '当前观察中无法唯一定位此端口，请重新前向或检查模型报告。', '目前觀察中無法唯一定位此連接埠，請重新前向或檢查模型報告。')
      end
      return function() sessions.port_supervision(state, preferred) end
    end,
    forward_saved = function()
      if not saved_canvas_current() then
        return nil, tr('Save the canvas and project files before running the model.',
          '请先保存画布和项目文件，再运行模型。', '請先儲存畫布與專案檔案，再執行模型。')
      end
      if not state.actions or not state.actions.p then return nil, tr('Forward is unavailable.', '前向不可用。', '前向不可用。') end
      return function() state.actions.p() end
    end,
    image_project = function()
      if same_context() then sessions.create_image_project(state) end
    end,
    advanced = function()
      if same_context() then create_model(state) end
    end,
    assembly_status = function(draft)
      if not same_context() or type(canvas_project_config) ~= 'table' then return nil end
      local bindings = canvas_project_config.model_injections
      local params = canvas_project_config.model_params
      if type(bindings) ~= 'table' then return nil end
      if params == vim.NIL then params = nil end
      if params ~= nil and type(params) ~= 'table' then return nil, tr('invalid model parameters', '模型参数无效', '模型參數無效') end
      for name in pairs(params or {}) do
        if name ~= 'input_routes' and name ~= 'encoder_output_modes' then
          return nil, tr('unsupported model parameter ', '不支持的模型参数 ', '不支援的模型參數 ') .. tostring(name)
        end
      end
      local routes = params and params.input_routes or nil
      local modes = params and params.encoder_output_modes or nil
      return builder.assembly_matches(draft, bindings, routes ~= vim.NIL and routes or nil, modes ~= vim.NIL and modes or nil)
    end,
    data_status = function(draft)
      if not same_context() or not project_config_current(state) or type(canvas_project_config) ~= 'table'
          or not vim.deep_equal(canvas_project_config, project_config(project)) then return nil end
      return builder.data_matches(draft, canvas_project_config)
    end,
    training_status = function(draft)
      local previous, info = state.last_training_entry, state.project_info
      if not same_context() or not project_config_current(state) or type(info) ~= 'table'
          or not previous or previous.project ~= project or previous.model ~= (state.model or info.model)
          or previous.config_revision ~= info.config_revision or type(previous.params) ~= 'string' then return nil end
      local ok, params = pcall(vim.json.decode, previous.params)
      if not ok or type(params) ~= 'table' then return nil end
      local entry = previous.value
      local module = type(info.model) == 'string' and info.model:match('^(.+):model$') or nil
      if previous.mode ~= 'external-loop' and module and entry == module .. ':step' then entry = '$model:step' end
      local training = draft.training
      if type(training) ~= 'table' or training.mode ~= previous.mode or training.entry ~= entry
          or not vim.deep_equal(training.params or {}, params) then return false end
      local chosen = state.last_training_optimizer
      if previous.mode ~= 'external-loop' and chosen and chosen.project == project and chosen.model == previous.model
          and chosen.mode == previous.mode and chosen.entry == previous.value and chosen.revision == previous.config_revision
          and chosen.cli == state.opts.cli and chosen.python == state.opts.python then
        local optimizer = optimizer_profile(chosen.args)
        if not optimizer then return nil end
        local function normalized(value)
          if type(value) ~= 'table' or not next(value) then return nil end
          local result = vim.deepcopy(value)
          if type(result.params) == 'table' and not next(result.params) then result.params = nil end
          return next(result) and result or nil
        end
        return vim.deep_equal(normalized(training.optimizer), normalized(optimizer))
      end
      return true
    end,
    assembly = function(slot)
      if same_context() then assemble(state, slot) end
    end,
    edit_input_augmentation = function(input)
      if not same_context() or not project_config_current(state) or state.project_status ~= 'configured' then
        notify(tr('Save the project before editing its transform pipeline.', '请先保存项目，再编辑变换流水线。', '請先儲存專案，再編輯變換流水線。'), vim.log.levels.WARN)
        return
      end
      edit_input_augmentation(state, input)
    end,
    connect_csv = function(input, output)
      if not same_context() then return end
      local original_draft = state.builder_draft
      local previous_data = vim.deepcopy(original_draft and original_draft.data)
      local function ports()
        local snapshot = {inputs = {}, outputs = {}}
        for _, row in ipairs(original_draft and original_draft.inputs or {}) do
          snapshot.inputs[#snapshot.inputs + 1] = {name = row.name, shape = row.shape, dtype = row.dtype}
        end
        for _, row in ipairs(original_draft and original_draft.outputs or {}) do
          snapshot.outputs[#snapshot.outputs + 1] = {name = row.name, width = row.width, loss = row.loss}
        end
        return snapshot
      end
      local original_ports = ports()
      local params = previous_data and previous_data.params
      local can_edit_target = output and previous_data and previous_data.factory == 'model_csv:batch'
        and type(params) == 'table' and type(params.path) == 'string'
        and type(params.inputs) == 'table' and not vim.islist(params.inputs)
        and type(params.targets) == 'table' and not vim.islist(params.targets) and params.targets['$tensor'] == nil
      local can_edit_input = input and previous_data and previous_data.factory == 'model_csv:batch'
        and type(params) == 'table' and type(params.path) == 'string'
        and type(params.inputs) == 'table' and not vim.islist(params.inputs)
      local options = {}
      if can_edit_target then options[#options + 1] = tr('Edit only this output target', '只修改此输出的目标', '只修改此輸出的目標')
      elseif can_edit_input then options[#options + 1] = tr('Edit only this input', '只修改此输入', '只修改此輸入') end
      options[#options + 1] = tr('Create editable CSV adapter', '创建可编辑 CSV 适配器', '建立可編輯 CSV 配接器')
      options[#options + 1] = tr('Configure CSV mapping again', '重新配置 CSV 映射', '重新設定 CSV 對應')
      vim.ui.select(options, {
        prompt = previous_data and tr('Reconfiguring replaces the data declaration; editing one target preserves the other parameters.',
          '重新配置会替换数据声明；单独编辑端口会保留其他参数。', '重新設定會取代資料宣告；單獨編輯連接埠會保留其他參數。')
          or tr('Connect CSV to the model draft', '将 CSV 接入模型草稿', '將 CSV 接入模型草稿'),
      }, function(_, choice)
        if not choice or not same_context() or state.builder_draft ~= original_draft then return end
        local function accept(data)
          if not same_context() or state.builder_draft ~= original_draft or not vim.deep_equal(original_draft.data, previous_data)
              or not vim.deep_equal(ports(), original_ports) then
            notify(tr('Draft data or model ports changed; reopen CSV configuration.', '草稿数据或模型端口已变化，请重新配置 CSV。', '草稿資料或模型連接埠已變更，請重新設定 CSV。'), vim.log.levels.WARN)
            return
          end
          original_draft.data = data
          vim.schedule(function() if same_context() then open_model_builder(state) end end)
        end
        if can_edit_target and choice == 1 then configure_csv_adapter(state, input, accept, output, true); return end
        if can_edit_input and choice == 1 then configure_csv_adapter(state, input, accept, output, false, true); return end
        local index = (can_edit_target or can_edit_input) and choice - 1 or choice
        if index == 1 then create_csv_adapter(state, input, accept, output)
        elseif index == 2 then configure_csv_adapter(state, input, accept, output) end
      end)
    end,
    preview_draft_data = function(data)
      local original_draft = state.builder_draft
      local function current()
        return same_context() and state.builder_draft == original_draft and vim.deep_equal(original_draft.data, data)
          and project_config_current(state)
      end
      if not current() or type(data) ~= 'table' or type(data.factory) ~= 'string' then return end
      local args = {'data', 'preview', '--batch', data.factory, '--whole-batch', '--no-split', '--renderer', 'summary'}
      local names = vim.tbl_keys(data.params or {}); table.sort(names)
      for _, name in ipairs(names) do
        local ok, value = pcall(vim.json.encode, data.params[name])
        if not ok then notify(tr('Data parameters cannot be encoded.', '数据参数无法编码。', '資料參數無法編碼。'), vim.log.levels.WARN); return end
        vim.list_extend(args, {'--param', name .. '=' .. value})
      end
      request(state, {'--describe-interface'}, function(interface, failure)
        if not current() then return end
        local caps = not failure and interface and interface.status == 'success' and interface.data and interface.data.capabilities
        if type(caps) ~= 'table' or caps['data.preview_whole_batch_v1'] ~= true or caps['data.preview_no_split_v1'] ~= true then
          notify(tr('This CLI cannot preview the full batch without a split.', '当前 CLI 不支持无切分的完整批次预览。', '目前 CLI 不支援無切分的完整批次預覽。'), vim.log.levels.WARN); return
        end
        run(state, tr('Preview draft batch', '预览草稿批次', '預覽草稿批次'), args, nil,
          tr('Runs the selected batch factory and writes a local summary. This does not validate model binding or dataset coverage.',
            '将运行所选批次工厂并写入本地摘要；这不验证模型绑定或数据集覆盖范围。',
            '將執行所選批次工廠並寫入本機摘要；這不驗證模型繫結或資料集涵蓋範圍。'), true)
      end)
    end,
    edit_encoder_source = function(input)
      if not same_context() or not project_config_current(state) or not saved_encoder_names[input]
          or (state.model and state.project_info and state.model ~= state.project_info.model) then
        notify(tr('Save the canvas and select its project model before editing this encoder.',
          '请先保存画布并选择其项目模型，再修改此编码器。', '請先儲存畫布並選擇其專案模型，再修改此編碼器。'), vim.log.levels.WARN); return
      end
      state.last_selection = 'model.encoders.enc_' .. input
      if state.actions and state.actions.W then state.actions.W() end
    end,
    edit_data = function()
      if same_context() then
        notify(tr('After saving, reopen the canvas and load the project input to update the declaration.',
          '保存后请重新打开画布并载入项目输入，以更新声明。', '儲存後請重新開啟畫布並載入專案輸入，以更新宣告。'), vim.log.levels.INFO)
        save_project_input(state)
      end
    end,
    sync_training = function(callback)
      local previous = state.last_training_entry
      local info = state.project_info
      if not same_context() or not project_config_current(state) or type(info) ~= 'table'
          or not previous or previous.project ~= project or previous.model ~= (state.model or info.model)
          or previous.config_revision ~= info.config_revision or type(previous.params) ~= 'string' then
        callback(nil, tr('Prepare training settings in this project first.', '请先在当前项目准备训练设置。', '請先在目前專案準備訓練設定。')); return
      end
      local ok, params = pcall(vim.json.decode, previous.params)
      if not ok or type(params) ~= 'table' then callback(nil, tr('Training parameters are unavailable.', '训练参数不可用。', '訓練參數無法使用。')); return end
      vim.ui.select({ tr('Load training settings', '载入训练设置', '載入訓練設定'), tr('Cancel', '取消', '取消') }, {
        prompt = tr('Save the selected training entry, parameters and available optimizer settings in model-maven.json?',
          '将所选训练入口、参数和可用的优化器设置保存到 model-maven.json？', '將所選訓練入口、參數和可用的最佳化器設定儲存到 model-maven.json？')
      }, function(_, choice)
        if choice ~= 1 then return end
        if not same_context() or not project_config_current(state) or state.last_training_entry ~= previous
            or not state.project_info or state.project_info.config_revision ~= previous.config_revision then
          callback(nil, tr('Project changed; reopen the canvas.', '项目已变化，请重新打开画布。', '專案已變更，請重新開啟畫布。')); return
        end
        local module = type(info.model) == 'string' and info.model:match('^(.+):model$') or nil
        local entry = previous.value
        if previous.mode ~= 'external-loop' and module and previous.value == module .. ':step' then entry = '$model:step' end
        local optimizer, chosen = nil, state.last_training_optimizer
        if previous.mode ~= 'external-loop' and chosen and chosen.project == project and chosen.model == previous.model
            and chosen.mode == previous.mode and chosen.entry == previous.value and chosen.revision == previous.config_revision
            and chosen.cli == state.opts.cli and chosen.python == state.opts.python then
          optimizer = optimizer_profile(chosen.args)
          if not optimizer then callback(nil, tr('Optimizer settings cannot be saved.', '无法保存优化器设置。', '無法儲存最佳化器設定。')); return end
        elseif previous.mode ~= 'external-loop' then
          local saved = declared_training(state, info, previous.mode)
          if saved and saved.entry == previous.value then optimizer = vim.deepcopy(saved.optimizer) end
        end
        callback({ mode = previous.mode, entry = entry, params = params, optimizer = optimizer })
      end)
    end,
    link_supervision = function(callback)
      if not same_context() or not project_config_current(state) then return end
      vim.ui.input({ prompt = tr('Project-relative supervision file: ', '项目内监督文件路径：', '專案內監督檔案路徑：'), default = 'supervision.json', completion = 'file' }, function(value)
        if not value or not same_context() or not project_config_current(state) then return end
        if value == '' or #value > 1024 or value:find('[%c\\:]') or value:sub(1, 1) == '/'
            or value:match('^%./') or value:match('/%./') or value:match('/%.$')
            or value:match('^%.%.$') or value:match('^%.%./') or value:match('/%.%./') or value:match('/%.%.$') then
          callback(nil, tr('Choose a project-relative path without parent segments.', '请选择不含上级目录的项目相对路径。', '請選擇不含上層目錄的專案相對路徑。')); return
        end
        local path = project .. '/' .. value
        local stat, resolved = vim.uv.fs_lstat(path), vim.uv.fs_realpath(path)
        if not stat or stat.type ~= 'file' or stat.size > 2 * 1024 * 1024 or not resolved or not in_project(project, resolved) then
          callback(nil, tr('Choose a regular supervision file inside the project (at most 2 MiB).',
            '请选择项目内不超过 2 MiB 的普通监督文件。', '請選擇專案內不超過 2 MiB 的一般監督檔案。')); return
        end
        local file = io.open(path, 'rb')
        if not file then callback(nil, tr('Cannot read supervision file.', '无法读取监督文件。', '無法讀取監督檔案。')); return end
        local raw = file:read(2 * 1024 * 1024 + 1); file:close()
        local ok, bundle = pcall(vim.json.decode, raw or '')
        if not raw or #raw > 2 * 1024 * 1024 or not ok or type(bundle) ~= 'table'
            or bundle.format ~= 'model-maven-supervision-bundle-v1' or type(bundle.state) ~= 'table'
            or type(bundle.state.marks) ~= 'table' or not is_list(bundle.state.marks) then
          callback(nil, tr('The file is not a supported supervision bundle.', '该文件不是受支持的监督声明。', '該檔案不是受支援的監督宣告。')); return
        end
        local reference = { file = value, sha256 = vim.fn.sha256(raw) }
        vim.ui.select({ tr('Link file', '关联文件', '連結檔案'), tr('Cancel', '取消', '取消') }, {
          prompt = tr('Reference marks: ', '引用标记数：', '參照標記數：') .. #bundle.state.marks
            .. tr('; target projects must import and rebind them.', '；目标项目需导入并重新绑定。', '；目標專案需匯入並重新繫結。'),
        }, function(_, choice)
          if choice ~= 1 or not same_context() or not project_config_current(state) then return end
          callback(reference)
        end)
      end)
    end,
    sync_data = function(callback)
      if not same_context() or not project_config_current(state) then
        callback(nil, tr('Project changed; reopen the canvas.', '项目已变化，请重新打开画布。', '專案已變更，請重新開啟畫布。')); return
      end
      local current = project_config(project)
      if type(current) ~= 'table' or type(current.batch) ~= 'string'
          or (current.batch_params ~= nil and current.batch_params ~= vim.NIL and type(current.batch_params) ~= 'table') then
        callback(nil, tr('No saved input factory.', '没有已保存的输入工厂。', '沒有已儲存的輸入工廠。')); return
      end
      if builder.data_matches({ data = nil }, current) == true then
        callback(nil, tr('The project uses the generated synthetic input. Connect real data before loading an input into the declaration.',
          '项目当前使用生成的合成输入。请先接入真实数据，再载入声明。',
          '專案目前使用產生的合成輸入。請先接入真實資料，再載入宣告。')); return
      end
      vim.ui.select({ tr('Load input', '载入输入', '載入輸入'), tr('Cancel', '取消', '取消') }, {
        prompt = tr('Save the input factory and its parameters in model-maven.json?',
          '将输入工厂及其参数保存到 model-maven.json？', '將輸入工廠及其參數儲存到 model-maven.json？')
      }, function(_, choice)
        if choice ~= 1 then return end
        if not same_context() or not project_config_current(state) or not vim.deep_equal(current, project_config(project)) then
          callback(nil, tr('Project changed; reopen the canvas.', '项目已变化，请重新打开画布。', '專案已變更，請重新開啟畫布。')); return
        end
        local binding = current.batch_binding
        if binding == vim.NIL then binding = nil end
        callback({ factory = current.batch, binding = binding,
          params = type(current.batch_params) == 'table' and vim.deepcopy(current.batch_params) or {} })
      end)
    end,
    sync_assembly = function(callback)
      if not same_context() or not project_config_current(state) then
        callback(false, tr('Project changed; reopen the canvas.', '项目已变化，请重新打开画布。', '專案已變更，請重新開啟畫布。'))
        return
      end
      local current = project_config(project)
      local bindings = type(current) == 'table' and current.model_injections or nil
      local params = type(current) == 'table' and current.model_params or nil
      if type(bindings) ~= 'table' then
        callback(false, tr('Saved component bindings are unavailable.', '无法读取已保存的组件绑定。', '無法讀取已儲存的元件繫結。'))
        return
      end
      if params ~= nil and params ~= vim.NIL then
        if type(params) ~= 'table' or (next(params) and is_list(params)) then
          callback(false, tr('Saved model parameters are not an object.', '已保存的模型参数不是对象。', '已儲存的模型參數不是物件。'))
          return
        end
        for name in pairs(params) do
          if name ~= 'input_routes' and name ~= 'encoder_output_modes' then
            callback(false, tr('This canvas cannot yet synchronize model parameter: ', '画布暂时无法同步此模型参数：', '畫布暫時無法同步此模型參數：') .. tostring(name))
            return
          end
        end
      end
      vim.ui.select({
        tr('Load saved assembly', '载入已保存装配', '載入已儲存裝配'),
        tr('Keep current draft', '保留当前草稿', '保留目前草稿'),
      }, { prompt = tr('Load project bindings, routes and output modes? Replaced built-in encoder layers will be removed from this draft.',
        '载入项目组件绑定、输入接线和输出方式？被组件替代的内置编码层将从当前草稿移除。',
        '載入專案元件繫結、輸入接線和輸出方式？被元件取代的內建編碼層將從目前草稿移除。') }, function(_, choice)
        if choice ~= 1 then return end
        if not same_context() or not project_config_current(state) or not vim.deep_equal(current, project_config(project)) then
          callback(false, tr('Project changed; reopen the canvas.', '项目已变化，请重新打开画布。', '專案已變更，請重新開啟畫布。'))
          return
        end
        local routes = type(params) == 'table' and params.input_routes or nil
        if routes == vim.NIL then routes = nil end
        local modes = type(params) == 'table' and params.encoder_output_modes or nil
        if modes == vim.NIL then modes = nil end
        local ok, err = builder.sync_assembly(state.builder_draft, bindings, routes, modes)
        callback(ok, err)
      end)
    end,
    layer_catalog = function(callback)
      request(state, { '--describe-interface' }, function(report)
        local catalog = report and report.status == 'success' and type(report.data) == 'table'
          and report.data.scaffold_encoder_layers
        local layers = {}
        if same_context() and type(catalog) == 'table' and is_list(catalog) then
          for _, item in ipairs(catalog) do
            if type(item) == 'table' and type(item.label) == 'string' and #item.label <= 32
                and not item.label:find('[%c]') and builder.supported_layer(item.defaults) then
              layers[#layers + 1] = item
            end
          end
        end
        local capabilities = report and type(report.data) == 'table' and report.data.capabilities or nil
        callback(layers, type(capabilities) == 'table' and capabilities['project.scaffold_recipe_factory_layers_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.scaffold_residual_layers_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.scaffold_parallel_layers_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.scaffold_custom_loss_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.scaffold_layer_ids_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.recipe_layer_move_plan_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.recipe_layer_edit_plan_v1'] == true,
          type(capabilities) == 'table' and capabilities['project.recipe_layer_cross_copy_plan_v1'] == true)
      end)
    end,
    plan_layer_move = function(document, operation, callback)
      if not same_context() then callback(nil, tr('Project context changed.', '项目上下文已变化。', '專案上下文已變更。')); return end
      local encoded, raw = pcall(vim.json.encode, document)
      if not encoded or #raw > 128 * 1024 then callback(nil, tr('Draft is too large to plan.', '草稿过大，无法规划。', '草稿過大，無法規劃。')); return end
      local path = vim.fn.tempname()
      local fd, failure = vim.uv.fs_open(path, 'wx', 384)
      if not fd then callback(nil, tostring(failure)); return end
      local written, write_error = vim.uv.fs_write(fd, raw, 0)
      vim.uv.fs_close(fd)
      if written ~= #raw then vim.uv.fs_unlink(path); callback(nil, tostring(write_error)); return end
      local revision = vim.fn.sha256(raw)
      local encoded_moves = vim.json.encode({operation})
      request(state, {'recipe-layer-plan', '--recipe', path, '--if-recipe', revision, '--moves', encoded_moves}, function(report, error)
        vim.uv.fs_unlink(path)
        local data = report and report.data
        local plan = type(data) == 'table' and data.plan or nil
        if not same_context() or error or not report or report.status ~= 'success' or report.operation ~= 'recipe_layer_plan'
            or type(plan) ~= 'table' or plan.input_sha256 ~= revision or plan.committed ~= false
            or type(plan.outcomes) ~= 'table' or #plan.outcomes ~= 1 or type(plan.outcomes[1]) ~= 'table'
            or plan.outcomes[1].id ~= operation.id or type(plan.outcomes[1].order) ~= 'table' then
          callback(nil, tr('Could not verify the backend move plan.', '无法核对后端移动计划。', '無法核對後端移動計畫。')); return
        end
        callback(plan)
      end, function() vim.uv.fs_unlink(path) end)
    end,
    plan_layer_edit = function(document, operation, callback)
      if not same_context() then callback(nil, tr('Project context changed.', '项目上下文已变化。', '專案上下文已變更。')); return end
      local operations = type(operation) == 'table' and operation.action and {operation} or operation
      if type(operations) ~= 'table' or not is_list(operations) or #operations == 0 or #operations > 64 then
        callback(nil, tr('Invalid edit operations.', '编辑操作无效。', '編輯操作無效。')); return
      end
      local encoded, raw = pcall(vim.json.encode, document)
      local encoded_ops, ops = pcall(vim.json.encode, operations)
      if not encoded or not encoded_ops or #raw > 128 * 1024 or #ops > 128 * 1024 then
        callback(nil, tr('Draft or operation is too large to plan.', '草稿或操作过大，无法规划。', '草稿或操作過大，無法規劃。')); return
      end
      local function write_temp(bytes)
        local path = vim.fn.tempname()
        local fd, error = vim.uv.fs_open(path, 'wx', 384)
        if not fd then return nil, error end
        local written, write_error = vim.uv.fs_write(fd, bytes, 0)
        vim.uv.fs_close(fd)
        if written ~= #bytes then vim.uv.fs_unlink(path); return nil, write_error or 'short write' end
        return path
      end
      local recipe_path, failure = write_temp(raw)
      if not recipe_path then callback(nil, tostring(failure)); return end
      local ops_path, ops_error = write_temp(ops)
      if not ops_path then vim.uv.fs_unlink(recipe_path); callback(nil, tostring(ops_error)); return end
      local function cleanup() vim.uv.fs_unlink(recipe_path); vim.uv.fs_unlink(ops_path) end
      local revision, ops_revision = vim.fn.sha256(raw), vim.fn.sha256(ops)
      request(state, {'recipe-layer-edit-plan', '--recipe', recipe_path, '--if-recipe', revision,
        '--operations', ops_path, '--if-operations', ops_revision}, function(report, error)
        cleanup()
        local plan = report and report.data and report.data.plan
        if not same_context() or error or not report or report.status ~= 'success' or report.operation ~= 'recipe_layer_edit_plan'
            or type(plan) ~= 'table' or plan.input_sha256 ~= revision or plan.operations_sha256 ~= ops_revision
            or plan.committed ~= false or type(plan.outcomes) ~= 'table' or #plan.outcomes ~= #operations then
          local diagnostic = report and type(report.diagnostics) == 'table' and report.diagnostics[1] or nil
          local reason = type(diagnostic) == 'table' and type(diagnostic.message) == 'string'
            and (' ' .. vim.fn.strcharpart(diagnostic.message:gsub('[%c]', ' '), 0, 300)) or ''
          callback(nil, tr('Could not verify the backend edit plan.', '无法核对后端编辑计划。', '無法核對後端編輯計畫。') .. reason); return
        end
        for index, item in ipairs(operations) do
          if type(plan.outcomes[index]) ~= 'table' or plan.outcomes[index].action ~= item.action then
            callback(nil, tr('Backend operation order differs.', '后端操作顺序不一致。', '後端操作順序不一致。')); return
          end
        end
        callback(plan)
      end, cleanup)
    end,
    factories = function(callback)
      find_component_factories(state, same_context, callback)
    end,
    discover_layers = function(callback)
      discover_layer_classes(state, function(layer)
        if same_context() then callback(layer) end
      end)
    end,
    discover_module_operators = function(callback)
      discover_module_operators(state, function(item)
        if same_context() then callback(item) end
      end)
    end,
  })
end

local function find_action(state, actions)
  if state.closed or not vim.api.nvim_buf_is_valid(state.panel) then return end
  local old_expanded = state.expanded
  local view
  if state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
    local ok, saved = pcall(vim.api.nvim_win_call, state.panel_win, vim.fn.winsaveview)
    if ok then view = saved end
  end
  state.expanded = true
  render(state)
  local panel_lines = vim.api.nvim_buf_get_lines(state.panel, 0, -1, false)
  state.expanded = old_expanded
  render(state)
  if view and state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
    pcall(vim.api.nvim_win_call, state.panel_win, function() vim.fn.winrestview(view) end)
  end
  local entries, seen = {}, {}
  for _, line in ipairs(panel_lines) do
    local key, label = line:match('^%[([^%]]+)%]%s*(.+)$')
    if key and #key == 1 and key ~= 'f' and actions[key] and not seen[key]
        and not label:match('%[[^%]]+%]') then
      entries[#entries + 1] = { key = key, label = label }
      seen[key] = true
    end
  end
  if #entries == 0 then
    notify(tr('No actions are available.', '没有可用操作。', '沒有可用操作。'), vim.log.levels.INFO)
    return
  end
  local buf = vim.api.nvim_create_buf(false, true)
  vim.bo[buf].buftype, vim.bo[buf].bufhidden, vim.bo[buf].swapfile = 'nofile', 'wipe', false
  local lines = { tr('Find an action', '搜索操作', '搜尋操作'),
    tr('[/] Search  [Enter] Choose  [q] Close', '[/] 搜索  [Enter] 选择  [q] 关闭', '[/] 搜尋  [Enter] 選擇  [q] 關閉'), '' }
  for _, entry in ipairs(entries) do lines[#lines + 1] = '[' .. entry.key .. '] ' .. entry.label end
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
  vim.bo[buf].modifiable = false
  local opened = pcall(vim.cmd, 'botright split')
  if not opened then opened = pcall(vim.cmd, 'botright vsplit') end
  if not opened then
    pcall(vim.api.nvim_buf_delete, buf, { force = true })
    notify(tr('Not enough room to open action search. Resize the editor or use x to show actions in the panel.',
      '空间不足，无法打开操作搜索。请调整编辑器大小，或按 x 在面板显示操作。',
      '空間不足，無法開啟操作搜尋。請調整編輯器大小，或按 x 在面板顯示操作。'), vim.log.levels.WARN)
    return
  end
  local win = vim.api.nvim_get_current_win()
  vim.api.nvim_win_set_buf(win, buf)
  vim.wo[win].wrap = false
  vim.api.nvim_win_set_cursor(win, { 4, 0 })
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, silent = true, desc = 'Close action search' })
  vim.keymap.set('n', '<CR>', function()
    if state.closed or not vim.api.nvim_win_is_valid(win) then return end
    local index = vim.api.nvim_win_get_cursor(win)[1] - 3
    local entry = entries[index]
    if not entry or not actions[entry.key] then return end
    vim.api.nvim_win_close(win, true)
    if state.closed or not state.panel_win or not vim.api.nvim_win_is_valid(state.panel_win) then return end
    vim.api.nvim_set_current_win(state.panel_win)
    actions[entry.key]()
  end, { buffer = buf, silent = true, desc = 'Choose action' })
end

M._ui_actions = {browse_modules = browse_modules, open_observed_source = open_observed_source, browse_tensor_links = browse_tensor_links, capture_canvas_forward = capture_canvas_forward, replay_canvas_forward = replay_canvas_forward, discard_canvas_forward = discard_canvas_forward, recheck_after_edit = recheck_after_edit, compare_observations = compare_observations, browse_runs = browse_runs, browse_variants = browse_variants, browse_marks = browse_marks, rebind_mark = rebind_mark, browse_rules = browse_rules, capability_overview = capability_overview, save_project_python = save_project_python, choose_runtime_paths = choose_runtime_paths, environment_menu = environment_menu, show_help = show_help, configure_csv_adapter = configure_csv_adapter, create_csv_adapter = create_csv_adapter, resolve_pending = resolve_pending, prepare_training = prepare_training, create_adapter_draft = create_adapter_draft, open_source = open_source, save_project_model = save_project_model, save_project_input = save_project_input, setup_existing = setup_existing, find_action = find_action}

function M.open(options)
  local key = vim.fs.normalize(options.project)
  local existing = sessions[key]
  if existing and vim.api.nvim_buf_is_valid(existing.panel)
      and (not existing.panel_win or not vim.api.nvim_win_is_valid(existing.panel_win)) then
    local found
    for _, tab in ipairs(vim.api.nvim_list_tabpages()) do
      for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
        if vim.api.nvim_win_get_buf(win) == existing.panel then found = win; break end
      end
      if found then break end
    end
    if found then
      existing.panel_win = found
      existing.tab = vim.api.nvim_win_get_tabpage(found)
      existing.single_panel = false
      vim.bo[existing.panel].bufhidden = 'wipe'
    else
      local code_win = vim.api.nvim_get_current_win()
      local tab = vim.api.nvim_get_current_tabpage()
      local code_buf = vim.api.nvim_get_current_buf()
      local old_windows = {}
      for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do old_windows[win] = true end
      local ok, err = pcall(vim.cmd, 'botright split')
      if not ok then
        notify(tr('Could not reopen the existing workspace panel: ', '无法重新打开已有工作区面板：', '無法重新開啟現有工作區面板：') .. tostring(err), vim.log.levels.WARN)
        return
      end
      local created = {}
      if vim.api.nvim_tabpage_is_valid(tab) then
        for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
          if not old_windows[win] then created[#created + 1] = win end
        end
      end
      if #created ~= 1 or vim.api.nvim_win_get_buf(created[1]) ~= code_buf then
        notify(tr('Could not identify a safe workspace split; existing windows were kept.',
          '无法确定可安全使用的工作区分屏；已保留现有窗口。',
          '無法確定可安全使用的工作區分割視窗；已保留現有視窗。'), vim.log.levels.WARN)
        return
      end
      local win = created[1]
      local placed, place_error = pcall(vim.api.nvim_win_set_buf, win, existing.panel)
      if not placed or not vim.api.nvim_win_is_valid(win)
          or vim.api.nvim_win_get_buf(win) ~= existing.panel then
        if vim.api.nvim_win_is_valid(win) and vim.api.nvim_win_get_buf(win) == code_buf then
          pcall(vim.api.nvim_win_close, win, false)
        end
        notify(tr('Could not display the existing workspace panel: ', '无法显示已有工作区面板：', '無法顯示現有工作區面板：') .. tostring(place_error), vim.log.levels.WARN)
        return
      end
      existing.code_win, existing.panel_win = code_win, win
      existing.tab = tab
      existing.single_panel = false
      vim.bo[existing.panel].bufhidden = 'wipe'
      vim.wo[win].wrap = true
    end
  end
  if existing and vim.api.nvim_buf_is_valid(existing.panel) and existing.panel_win
      and vim.api.nvim_win_is_valid(existing.panel_win) then
    if existing.single_panel and vim.api.nvim_win_get_buf(existing.panel_win) ~= existing.panel then
      for _, tab in ipairs(vim.api.nvim_list_tabpages()) do
        local found
        for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
          if vim.api.nvim_win_get_buf(win) == existing.panel then found = win; break end
        end
        if found then
          existing.panel_win, existing.tab, existing.single_panel = found, tab, false
          vim.bo[existing.panel].bufhidden = 'wipe'
          break
        end
      end
    end
    if not existing.single_panel and vim.api.nvim_win_get_buf(existing.panel_win) ~= existing.panel then
      local found
      for _, tab in ipairs(vim.api.nvim_list_tabpages()) do
        for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
          if vim.api.nvim_win_get_buf(win) == existing.panel then found = win; break end
        end
        if found then break end
      end
      if not found then
        notify(tr('The workspace panel is no longer in its recorded window. Reopen it from a visible panel or close that session first.',
          '工作区面板已不在记录的窗口中。请从可见面板返回，或先关闭该会话。',
          '工作區面板已不在記錄的視窗中。請從可見面板返回，或先關閉該工作階段。'), vim.log.levels.WARN)
        return
      end
      existing.panel_win = found
      existing.tab = vim.api.nvim_win_get_tabpage(found)
    end
    vim.api.nvim_set_current_win(existing.panel_win)
    if existing.single_panel and vim.api.nvim_get_current_buf() ~= existing.panel then
      local current = vim.api.nvim_get_current_buf()
      local hidden = vim.bo[current].bufhidden
      if vim.bo[current].buftype ~= '' or (hidden ~= '' and hidden ~= 'hide') then
        notify(tr('The workspace window now contains a special buffer. Return to a normal source buffer before reopening the panel.',
          '工作区窗口现在显示特殊 buffer；请先返回普通源码 buffer，再重新打开面板。',
          '工作區視窗目前顯示特殊 buffer；請先返回一般原始碼 buffer，再重新開啟面板。'), vim.log.levels.WARN)
        return
      end
      existing.code_buf, existing.code_view, existing.code_wrap = current, vim.fn.winsaveview(), vim.wo[existing.panel_win].wrap
      local ok, err = pcall(vim.cmd, 'hide buffer ' .. tostring(existing.panel))
      if not ok or vim.api.nvim_get_current_buf() ~= existing.panel then
        notify(tr('Could not return to the workspace panel: ', '无法返回工作区面板：', '無法返回工作區面板：') .. tostring(err), vim.log.levels.WARN)
        return
      end
      vim.wo[existing.panel_win].wrap = true
      if existing.panel_view then pcall(vim.fn.winrestview, existing.panel_view) end
    end
    local differences = {}
    if options.cli ~= existing.opts.cli or options.cli_unresolved ~= existing.opts.cli_unresolved then
      differences[#differences + 1] = tr('CLI in use: ', '当前使用的 CLI：', '目前使用的 CLI：') .. tostring(existing.opts.cli)
        .. tr('; requested: ', '；本次请求：', '；本次請求：') .. tostring(options.cli)
    end
    -- An omitted Python does not request resetting the user's session choice.
    if options.python_requested and options.python ~= existing.opts.python then
      differences[#differences + 1] = tr('Python in use: ', '当前使用的 Python：', '目前使用的 Python：')
        .. tostring(existing.opts.python or tr('project environment / default', '项目环境 / 默认', '專案環境 / 預設'))
        .. tr('; requested: ', '；本次请求：', '；本次請求：')
        .. tostring(options.python or tr('project environment / default', '项目环境 / 默认', '專案環境 / 預設'))
    end
    if #differences > 0 then
      notify(tr('Existing workspace kept its runtime. ', '已有工作区保留了原运行环境。', '現有工作區保留了原執行環境。')
        .. table.concat(differences, '  ')
        .. tr(' Change Python with e, or choose the CLI from the environment menu (E).',
          ' 按 e 更改 Python，或在环境菜单（E）中选择 CLI。',
          ' 按 e 更改 Python，或在環境選單（E）中選擇 CLI。'), vim.log.levels.WARN)
    end
    -- Focusing an existing panel must not resize the user's other windows.
    return
  end
  local state = { opts = options, code_win = vim.api.nvim_get_current_win(), initial_buf = vim.api.nvim_get_current_buf(),
    tab = vim.api.nvim_get_current_tabpage(), host = vim.fn.hostname() }
  local panel = vim.api.nvim_create_buf(false, true)
  state.panel = panel
  vim.bo[panel].buftype = 'nofile'
  vim.bo[panel].bufhidden = 'wipe'
  vim.bo[panel].swapfile = false
  vim.bo[panel].filetype = 'modelmaven'
  local available_width = vim.api.nvim_win_get_width(state.code_win)
  local available_height = vim.api.nvim_win_get_height(state.code_win)
  local initial_hidden = vim.bo[state.initial_buf].bufhidden
  state.single_panel = available_width < 60 and vim.bo[state.initial_buf].buftype == ''
    and (initial_hidden == '' or initial_hidden == 'hide')
  local opened, open_error, old_windows
  if state.single_panel then
    state.code_buf, state.code_view, state.code_wrap = state.initial_buf, vim.fn.winsaveview(), vim.wo[state.code_win].wrap
    vim.bo[panel].bufhidden = 'hide'
    opened, open_error = pcall(vim.cmd, 'hide buffer ' .. tostring(panel))
    opened = opened and vim.api.nvim_win_is_valid(state.code_win)
      and vim.api.nvim_win_get_buf(state.code_win) == panel
  else
  old_windows = {}
  for _, win in ipairs(vim.api.nvim_tabpage_list_wins(state.tab)) do old_windows[win] = true end
  local command = available_width >= 100 and 'botright 36vsplit'
    or ('botright ' .. math.max(3, math.min(12, math.floor(available_height * 0.4))) .. 'split')
  opened, open_error = pcall(vim.cmd, command)
  end
  if not opened then
    pcall(vim.api.nvim_buf_delete, panel, { force = true })
    notify(tr('Could not open the workspace panel: ', '无法打开工作区面板：', '無法開啟工作區面板：') .. tostring(open_error), vim.log.levels.ERROR)
    return
  end
  if state.single_panel then
    state.panel_win = state.code_win
  else
    local created = {}
    if vim.api.nvim_tabpage_is_valid(state.tab) then
      for _, win in ipairs(vim.api.nvim_tabpage_list_wins(state.tab)) do
        if not old_windows[win] then created[#created + 1] = win end
      end
    end
    if #created ~= 1 then
      if vim.api.nvim_buf_is_valid(panel) then pcall(vim.api.nvim_buf_delete, panel, { force = true }) end
      notify(tr('Could not identify the workspace split; existing windows were kept.',
        '无法确定工作区分屏；已保留现有窗口。',
        '無法確定工作區分割視窗；已保留現有視窗。'), vim.log.levels.ERROR)
      return
    end
    state.panel_win = created[1]
  end
  if not state.single_panel then
    local split_buf = vim.api.nvim_win_get_buf(state.panel_win)
    if split_buf ~= state.initial_buf then
      if vim.api.nvim_buf_is_valid(panel) then pcall(vim.api.nvim_buf_delete, panel, { force = true }) end
      notify(tr('The new split already contains another buffer; it was kept.',
        '新分屏已显示其他 buffer，已保留该窗口。',
        '新分割視窗已顯示其他 buffer，已保留該視窗。'), vim.log.levels.WARN)
      return
    end
    local placed, place_error = pcall(vim.api.nvim_win_set_buf, state.panel_win, panel)
    if not placed or not vim.api.nvim_win_is_valid(state.panel_win)
        or vim.api.nvim_win_get_buf(state.panel_win) ~= panel then
      -- Autocommands may reject the buffer or replace it while the split is
      -- opening. Only close our split if it still contains the original
      -- duplicate; never discard a buffer installed by user configuration.
      if vim.api.nvim_win_is_valid(state.panel_win)
          and vim.api.nvim_win_get_buf(state.panel_win) == split_buf then
        pcall(vim.api.nvim_win_close, state.panel_win, false)
      end
      if vim.api.nvim_buf_is_valid(panel) then
        pcall(vim.api.nvim_buf_delete, panel, { force = true })
      end
      notify(tr('Could not display the workspace panel; the existing buffers were kept: ',
        '无法显示工作区面板；已保留现有 buffer：',
        '無法顯示工作區面板；已保留現有 buffer：') .. tostring(place_error or ''), vim.log.levels.ERROR)
      return
    end
  end
  vim.wo[state.panel_win].wrap = true
  sessions[key] = state
  local group = vim.api.nvim_create_augroup('ModelMaven_' .. tostring(panel), { clear = true })
  state.read_buffers = {}
  for _, existing_buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(existing_buf) then state.read_buffers[existing_buf] = true end
  end
  local source_events = { 'BufWritePost', 'BufReadPost', 'FileChangedShellPost' }
  if vim.fn.exists('##BufModifiedSet') == 1 then
    source_events[#source_events + 1] = 'BufModifiedSet'
  else
    -- BufModifiedSet is not available in every supported Neovim build.
    -- TextChanged events still invalidate observations for unsaved edits;
    -- the execution gate independently checks buffer and disk contents.
    source_events[#source_events + 1] = 'TextChanged'
    source_events[#source_events + 1] = 'TextChangedI'
  end
  vim.api.nvim_create_autocmd(source_events, {
    group = group,
    callback = function(event)
      if not vim.api.nvim_buf_is_valid(event.buf) then return end
      local name = vim.api.nvim_buf_get_name(event.buf)
      if in_project(state.opts.project, name) then
        if event.event == 'BufModifiedSet' and not state.read_buffers[event.buf]
            and not vim.bo[event.buf].modified then
          render(state)
          return
        end
        local first_read = event.event == 'BufReadPost' and not state.read_buffers[event.buf]
        state.read_buffers[event.buf] = true
        if event.event == 'BufReadPost' or event.event == 'BufWritePost' then
          vim.b[event.buf].model_maven_reload_required = nil
        end
        -- Opening an additional source buffer does not by itself change the
        -- project. A later reload, write, edit or file-change event still
        -- invalidates prior evidence; execution gates compare buffers to disk.
        if first_read then render(state); return end
        state.change_epoch = (state.change_epoch or 0) + 1
        if state.last then
          state.result_label = tr('project changed; recheck', '项目已变化，请重验', '專案已變更，請重驗')
          state.last.context_changed = true; state.last.observed_context_changed = true
        end
        render(state)
      end
    end,
  })
  vim.api.nvim_create_autocmd({ 'WinEnter', 'BufEnter' }, {
    group = group,
    callback = function(event)
      if state.closed or state.loading_source_candidate or vim.api.nvim_get_current_tabpage() ~= state.tab then return end
      local win, buf = vim.api.nvim_get_current_win(), event.buf
      -- bufload() can fire BufEnter in Neovim's temporary autocmd window.
      -- That window cannot serve as the user's source window after the event.
      if vim.fn.win_id2win(win) == 0 or vim.api.nvim_win_get_buf(win) ~= buf then return end
      if (win ~= state.panel_win or state.single_panel) and buf ~= state.panel
          and vim.api.nvim_buf_is_valid(buf) and vim.bo[buf].buftype == '' then
        local name = vim.api.nvim_buf_get_name(buf)
        if in_project(state.opts.project, name) or (buf == state.initial_buf and name == '') then
          state.code_win = win
          if state.single_panel and win == state.panel_win then state.code_buf = buf end
        end
      end
      render(state)
    end,
  })
  vim.api.nvim_create_autocmd({ 'FocusGained', 'BufEnter' }, {
    group = group,
    callback = function(event)
      if state.closed then return end
      if event.event == 'BufEnter' and event.buf ~= state.panel then return end
      if not state.busy and not project_config_current(state) then
        if state.last then state.last.context_changed = true; state.last.observed_context_changed = true end
        state.change_epoch = (state.change_epoch or 0) + 1
        state.journey = nil
        state.result_label = tr('project configuration changed; rechecking',
          '项目配置已变化，正在重新检查', '專案設定已變更，正在重新檢查')
        refresh_project(state)
        return
      end
      if not state.last or state.last.context_changed then return end
      state.buffer_comparisons = state.buffer_comparisons or {}
      if #stale_python_buffers(state.opts.project, state.buffer_comparisons) > 0
          or observed_sources_changed(state.last.observed_source_stats) then
        state.last.context_changed = true; state.last.observed_context_changed = true
        state.result_label = tr('source changed or an open buffer differs from disk; reconcile and recheck',
          '源码已变化或打开的 buffer 与磁盘不一致，请处理并重验', '原始碼已變更或開啟的 buffer 與磁碟不一致，請處理並重新驗證')
        render(state)
      end
    end,
  })
  vim.api.nvim_create_autocmd('BufWipeout', {
    group = group, buffer = panel, once = true,
    callback = function()
      state.closed = true
      confirmation.revoke()
      if has_assembly_changes(state.assembly_draft) and not state.assembly_draft_discard_confirmed then
        vim.schedule(function()
          notify(tr('The workspace closed; its in-memory assembly draft was not saved.',
            '工作区已关闭；内存中的装配草稿未保存。', '工作區已關閉；記憶體中的裝配草稿未儲存。'), vim.log.levels.WARN)
        end)
      end
      if has_layer_draft(state.layer_draft) and not state.layer_draft_discard_confirmed then
        vim.schedule(function()
          notify(tr('The workspace closed; its in-memory Layer draft was not saved.',
            '工作区已关闭；内存中的 Layer 草稿未保存。', '工作區已關閉；記憶體中的 Layer 草稿未儲存。'), vim.log.levels.WARN)
        end)
      end
      if not state.busy and state.snapshot_cleanup then state.snapshot_cleanup() end
      if not state.busy and state.canvas_snapshot_cleanup then state.canvas_snapshot_cleanup() end
      require('model_maven.model_preview').close(state)
      if sessions[key] == state then sessions[key] = nil end
      pcall(vim.api.nvim_del_augroup_by_id, group)
    end,
  })
  if state.single_panel then
    vim.api.nvim_create_autocmd('WinClosed', {
      group = group,
      callback = function(event)
        if not state.single_panel then return end
        if event.match ~= tostring(state.panel_win) then return end
