        -- cleanup until Neovim finishes closing it; never close another window.
        vim.schedule(function()
          if not state.closed and not vim.api.nvim_win_is_valid(state.panel_win)
              and vim.api.nvim_buf_is_valid(panel) then
            pcall(vim.api.nvim_buf_delete, panel, { force = true })
          end
        end)
      end,
    })
  end
  local actions = {}
  local owned_descriptions = {}
  state.actions = actions
  local function map(keybind, callback, description)
    actions[keybind] = callback
    owned_descriptions[keybind] = description
    vim.keymap.set('n', keybind, callback, { buffer = panel, silent = true, nowait = true, desc = description })
  end
  map('8', function()
    if state.model_preview then
      state.model_preview_hidden = true
      require('model_maven.model_preview').close(state)
    else
      state.model_preview_hidden = false
      require('model_maven.model_preview').open(state)
    end
  end, 'Toggle model preview')
  map('n', function()
    if state.closed or state.busy then return end
    local project = state.opts.project
    local graph, _, graph_error = vim.uv.fs_lstat(project .. '/model-graph.json')
    local active = state.graph_canvas and state.graph_canvas.project == project
    if graph or active then return sessions.open_graph_canvas(state) end
    if graph_error ~= 'ENOENT' then
      return notify(tr('Cannot inspect graph file; check the project path.', '无法检查图文件，请检查项目路径。', '無法檢查圖檔，請檢查專案路徑。'), vim.log.levels.WARN)
    end
    local saved, failure = require('model_maven.model_builder').load(project)
    if failure then return notify(failure, vim.log.levels.WARN) end
    if saved or state.builder_draft then return open_model_builder(state) end
    sessions.open_graph_canvas(state)
  end, 'Open model design')
  map('a', function() M._ui_actions.setup_existing(state) end, 'Set up existing model')
  local function panel_action(row, column)
    local button = state.builder_buttons[row]
    if button then return button end
    for _, target in ipairs(state.panel_action_targets or {}) do
      if target.row == row and column >= target.start and column <= target.finish then return target.key end
    end
  end
  vim.keymap.set('n', '<CR>', function()
    local cursor = vim.api.nvim_win_get_cursor(0)
    local key = panel_action(cursor[1], cursor[2] + 1)
    if key and actions[key] then actions[key]() end
  end, { buffer = panel, silent = true })
  for _, mouse_key in ipairs({ '<LeftMouse>', '<2-LeftMouse>', '<3-LeftMouse>', '<4-LeftMouse>' }) do
    vim.keymap.set('n', mouse_key, function()
      local mouse = vim.fn.getmousepos()
      local key = mouse.winid == state.panel_win and panel_action(mouse.line, mouse.column)
      if not key then return mouse_key end
      vim.schedule(function() if not state.closed and actions[key] then actions[key]() end end)
      return '<Ignore>'
    end, { buffer = panel, expr = true, silent = true })
  end
  map('F', function() discover_entries(state) end, 'Find project entrypoints')
  map('N', function()
    local project, epoch = state.opts.project, state.change_epoch or 0
    vim.ui.select({ tr('Model and input adapter', '模型与输入适配器', '模型與輸入配接器'),
      tr('Framework-neutral training loop', '无框架训练循环', '無框架訓練迴圈') }, {
      prompt = tr('Choose a code draft', '选择代码草稿', '選擇程式碼草稿'),
    }, function(_, choice)
      if not choice or state.closed or state.busy or state.opts.project ~= project
          or (state.change_epoch or 0) ~= epoch then return end
      M._ui_actions.create_adapter_draft(state, choice == 2)
    end)
  end, 'Write project adapter or loop')
  map('U', function()
    local old, old_intent, project = state.user_goal, state.goal_intent, state.opts.project
    local choices = {
      { 'understand', tr('Understand my model', '理解模型', '理解模型') },
      { 'edit', tr('Change my model', '修改模型', '修改模型') },
      { 'contract', tr('Check model port contracts', '检查模型端口契约', '檢查模型連接埠契約') },
      { 'supervise', tr('Add supervision', '添加监督', '新增監督') },
      { 'train', tr('Try or train my model', '试跑或训练模型', '試跑或訓練模型') },
      { 'custom', tr('Write a custom goal', '填写其他目标', '填寫其他目標') },
      { 'clear', tr('Clear goal', '清除目标', '清除目標') },
    }
    local labels = {}
    for _, item in ipairs(choices) do labels[#labels + 1] = item[2] end
    local function current()
      return not state.closed and state.opts.project == project and state.user_goal == old and state.goal_intent == old_intent
    end
    vim.ui.select(labels, { prompt = tr('What are you working on? (session only)', '你现在想做什么？（仅本会话）', '你現在想做什麼？（僅本工作階段）') }, function(_, index)
      if not index or not current() then return end
      local choice = choices[index]
      if choice[1] == 'custom' then
        vim.ui.input({ prompt = tr('Current goal (empty clears): ', '当前目标（留空清除）：', '目前目標（留空清除）：'), default = old or '' }, function(value)
          if value == nil or not current() then return end
          if #value > 400 or value:find('[\r\n%z\1-\31\127]') then
            notify(tr('Use at most 400 bytes of single-line text.', '请输入不超过 400 字节的单行文字。', '請輸入不超過 400 位元組的單行文字。'), vim.log.levels.WARN); return
          end
          value = vim.trim(value)
          state.user_goal, state.goal_intent = value ~= '' and value or nil, nil
          state.supervision_progress = nil
          render(state)
        end)
      else
        state.goal_intent = choice[1] ~= 'clear' and choice[1] or nil
        state.user_goal = choice[1] ~= 'clear' and choice[2] or nil
        if choice[1] ~= 'supervise' then state.supervision_progress = nil end
        render(state)
      end
    end)
  end, 'Set current goal')
  map('o', function() M._ui_actions.open_source(state) end, 'Open source')
  map('z', function()
    local win = state.code_win
    if not win or not vim.api.nvim_win_is_valid(win) or vim.api.nvim_win_get_tabpage(win) ~= state.tab then
      notify(tr('Open a source file first.', '请先打开源码文件。', '請先開啟原始碼檔案。'), vim.log.levels.INFO); return
    end
    if state.single_panel and win == state.panel_win and vim.api.nvim_get_current_buf() == state.panel then
      if not state.code_buf or not vim.api.nvim_buf_is_valid(state.code_buf) then
        notify(tr('The source buffer is no longer available.', '源码 buffer 已不可用。', '原始碼 buffer 已無法使用。'), vim.log.levels.WARN); return
      end
      state.panel_view = vim.fn.winsaveview()
      local ok, err = pcall(vim.cmd, 'hide buffer ' .. tostring(state.code_buf))
      if not ok or vim.api.nvim_get_current_buf() ~= state.code_buf then
        notify(tr('Could not return to source: ', '无法返回源码：', '無法返回原始碼：') .. tostring(err), vim.log.levels.WARN); return
      end
      if state.code_wrap ~= nil then vim.wo[win].wrap = state.code_wrap end
      if state.code_view then pcall(vim.fn.winrestview, state.code_view) end
    end
    vim.api.nvim_set_current_win(win)
    notify(tr('Return: :ModelMaven', '返回：:ModelMaven', '返回：:ModelMaven'), vim.log.levels.INFO)
  end, 'Focus source')
  local function choose_context(field, prompt)
    if state.busy then notify(tr('Wait for the current operation before changing context.', '请等当前操作完成后再切换上下文。', '請等目前操作完成後再切換上下文。'), vim.log.levels.WARN); return end
    local current = field == 'python' and state.opts.python or state[field]
    local project, epoch = state.opts.project, state.change_epoch or 0
    vim.ui.input({ prompt = prompt, default = current or '' }, function(value)
      if value == nil or state.closed then return end
      if state.busy then notify(tr('The operation is running; context was not changed.', '操作仍在运行，未更改上下文。', '操作仍在執行，未變更上下文。'), vim.log.levels.WARN); return end
      local latest = field == 'python' and state.opts.python or state[field]
      if state.opts.project ~= project or (state.change_epoch or 0) ~= epoch or latest ~= current then
        notify(tr('Context changed; reopen this selection.', '上下文已变化，请重新选择。', '上下文已變更，請重新選擇。'), vim.log.levels.WARN); return
      end
      if (value ~= '' and value or nil) == current then return end
      if field == 'python' then state.opts.python = value ~= '' and value or nil
      else switch_factory(state, field, value ~= '' and value or nil) end
      state.change_epoch = (state.change_epoch or 0) + 1
      state.journey = nil
      if field == 'model' then state.auto_opened_source = nil end
      if state.last then
        local created_without_forward = field == 'python' and state.result_label
          == tr('model created; forward not run', '模型已创建；尚未运行前向', '模型已建立；尚未執行前向')
        if not created_without_forward then
          state.result_label = tr('context changed; recheck', '上下文已变化，请重验', '上下文已變更，請重驗')
        end
        state.last.context_changed = true; state.last.observed_context_changed = true
      end
      render(state)
    end)
  end
  map('m', function() choose_context('model', tr('Model factory module:callable (empty = project default): ', '模型工厂 module:callable（留空用项目默认值）：', '模型工廠 module:callable（留空用專案預設值）：')) end, 'Choose model')
  map('Q', function() M._ui_actions.save_project_model(state) end, 'Save project model')
  map('b', function() choose_context('batch', tr('Input factory module:callable (empty = project default): ', '输入工厂 module:callable（留空用项目默认值）：', '輸入工廠 module:callable（留空用專案預設值）：')) end, 'Choose input')
  map('S', function(use_current) M._ui_actions.save_project_input(state, use_current) end, 'Save project input')
  map('j', function()
    if state.busy or state.closed or not project_config_current(state) then return end
    local config = project_config(state.opts.project) or {}
    local batch = state.batch or config.batch
    if type(batch) ~= 'string' or batch == '' then
      notify(tr('Choose an input factory first.', '请先选择输入工厂。', '請先選擇輸入工廠。'), vim.log.levels.INFO); return
    end
    local project, epoch = state.opts.project, state.change_epoch or 0
    -- Explicit session factories follow the CLI's input-resolution rules:
    -- project parameters belong only to the saved factory, not an override.
    local params = not state.batch and type(config.batch_params) == 'table' and vim.deepcopy(config.batch_params) or {}
    local whole_batch = (state.batch_binding or (not state.batch and config.batch_binding or nil)) == 'single-raw'
    for key, value in pairs(state.batch_params or {}) do params[key] = value end
    local encoded, default = pcall(vim.json.encode, params)
    if encoded and next(params) == nil then default = '{}' end
    if not encoded or #default > 65536 then
      notify(tr('Input parameters cannot be reviewed; adjust them first.', '输入参数无法审阅，请先调整。', '輸入參數無法檢視，請先調整。'), vim.log.levels.WARN); return
    end
    vim.ui.input({ prompt = tr('Batch factory parameters as JSON (recorded; no secrets): ',
      '批次工厂参数 JSON（会记录，请勿填写密钥）：', '批次工廠參數 JSON（會記錄，請勿填寫密鑰）：'), default = default }, function(raw)
      if raw == nil or state.closed or state.busy or state.opts.project ~= project
          or (state.change_epoch or 0) ~= epoch or not project_config_current(state) then return end
      local ok, values = pcall(vim.json.decode, raw)
      if #raw > 65536 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') then
        notify(tr('Enter a JSON object of at most 64 KiB.', '请输入不超过 64 KiB 的 JSON 对象。', '請輸入不超過 64 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
      end
      local args, names = { 'data', 'preview', '--batch', batch, '--renderer', 'summary' }, vim.tbl_keys(values)
      if #names > 64 then notify(tr('At most 64 parameters are supported.', '最多支持 64 个参数。', '最多支援 64 個參數。'), vim.log.levels.WARN); return end
      table.sort(names)
      for _, name in ipairs(names) do
        if not parameter_name_candidate(name) then
          notify(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。'), vim.log.levels.WARN); return
        end
        local serializable, value = pcall(vim.json.encode, values[name])
        if not serializable then notify(tr('Invalid parameter value.', '参数值无效。', '參數值無效。'), vim.log.levels.WARN); return end
        vim.list_extend(args, { '--param', name .. '=' .. value })
      end
      vim.ui.input({ prompt = tr('Maximum preview samples (1–64): ', '最多预览样本数（1–64）：', '最多預覽樣本數（1–64）：'), default = '12' }, function(samples)
      if not samples or not samples:match('^%d+$') or tonumber(samples) < 1 or tonumber(samples) > 64 then
        if samples then notify(tr('Choose an integer from 1 to 64.', '请输入 1 到 64 的整数。', '請輸入 1 到 64 的整數。'), vim.log.levels.WARN) end
        return
      end
      if state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
          or not project_config_current(state) then return end
      vim.list_extend(args, { '--samples', samples })
      local effect = tr('Executes the selected batch factory and writes a local preview under .model-maven/previews; generated artifacts may contain sensitive data.',
        '将执行所选批次工厂，并在 .model-maven/previews 写入本地预览；生成的产物可能包含敏感数据。',
        '將執行所選批次工廠，並在 .model-maven/previews 寫入本機預覽；產物可能包含敏感資料。')
        .. '\n' .. tr('Batch: ', '批次：', '批次：') .. batch
        .. '\n' .. tr('Maximum preview samples: ', '最多预览样本数：', '最多預覽樣本數：') .. samples
        .. tr(' (factory may load more)', '（工厂内部可能加载更多）', '（工廠內部可能載入更多）')
        .. '\n' .. tr('Parameter names: ', '参数名：', '參數名稱：') .. (#names > 0 and table.concat(names, ', ') or tr('none', '无', '無'))
        .. (whole_batch and tr('\nShows the whole factory result as one item; no dataset sampling or project augmentation. This does not validate forward binding.',
          '\n将整个工厂返回值作为一项展示，不采样数据集或应用项目增强；此预览不验证前向绑定。',
          '\n將整個工廠回傳值作為一項顯示，不取樣資料集或套用專案增強；此預覽不驗證前向繫結。')
        or tr('\nFor a regular batch factory, shows its entire output as one item because the batch axis is unknown. A returned dataset is sampled. This does not validate forward binding.',
          '\n普通批次工厂的返回值作为一项完整展示，因为批次轴未知；若返回数据集则进行采样。此预览不验证前向绑定。',
          '\n一般批次工廠的回傳值作為一項完整顯示，因為批次軸未知；若回傳資料集則進行取樣。此預覽不驗證前向繫結。'))
      local function start()
        if state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch
            or not project_config_current(state) then return end
        run(state, tr('Preview batch summary', '预览批次摘要', '預覽批次摘要'), args, nil, effect, true)
      end
      if not whole_batch then start(); return end
      vim.list_extend(args, { '--whole-batch', '--augment-split', 'none' })
      request(state, { '--describe-interface' }, function(interface, failure)
        if state.closed or state.busy or state.opts.project ~= project or (state.change_epoch or 0) ~= epoch then return end
        local caps = not failure and interface and interface.status == 'success' and type(interface.data) == 'table' and interface.data.capabilities or nil
        if type(caps) ~= 'table' or caps['data.preview_whole_batch_v1'] ~= true then
          notify(tr('This CLI cannot preview the whole factory result.', '当前 CLI 无法预览完整工厂返回值。', '目前 CLI 無法預覽完整工廠回傳值。'), vim.log.levels.WARN); return
        end
        start()
      end)
      end)
    end)
  end, 'Preview batch summary')
  map('J', function()
    if state.busy or state.closed or not project_config_current(state) then return end
    local project, epoch = state.opts.project, state.change_epoch or 0
    local function current()
      return not state.closed and not state.busy and state.opts.project == project
        and (state.change_epoch or 0) == epoch and project_config_current(state)
    end
    vim.ui.input({ prompt = tr('Dataset factory module:callable: ', '数据集工厂 module:callable：', '資料集工廠 module:callable：') }, function(factory)
      if not factory or factory == '' or not current() then return end
      local last = state.last and not state.last.context_changed and state.last.report
      local previous = last and last.operation == 'preview' and last.status == 'success'
        and type(last.data) == 'table' and last.data.published == true and last.data.scope or nil
      local previous_seed = type(previous) == 'table' and previous.source_kind == 'dataset'
        and previous.source_entrypoint == factory and type(previous.seed_decimal) == 'string'
        and #previous.seed_decimal <= 20 and previous.seed_decimal:match('^%d+$') and previous.seed_decimal or nil
      vim.ui.select({
        tr('Quick preview: no parameters or split, up to 12 samples', '快速预览：无参数、无切分，最多 12 个样本', '快速預覽：無參數、無切分，最多 12 個樣本'),
        tr('Configure parameters, split and sampling', '配置参数、切分和采样', '設定參數、切分和取樣'),
      }, { prompt = tr('How would you like to preview?', '如何预览？', '如何預覽？') }, function(_, mode)
      if not mode or not current() then return end
      if mode == 1 then
        request(state, { '--describe-interface' }, function(report, err)
          if not current() then return end
          local capabilities = not err and report and report.status == 'success' and type(report.data) == 'table' and report.data.capabilities or nil
          if type(capabilities) ~= 'table' or capabilities['data.preview_no_split_v1'] ~= true then
            notify(tr('This CLI cannot preview without a split. Update it or use the configured preview.',
              '当前 CLI 不支持无切分预览；请更新或使用配置预览。', '目前 CLI 不支援無切分預覽；請更新或使用設定預覽。'), vim.log.levels.WARN)
            return
          end
          local effect = tr('Calls the dataset factory without explicit parameters or a split, samples up to 12 items with the CLI default seed, and writes local preview artifacts. The seed may be passed to the factory. No project augmentation is selected. The factory may read or change other state.',
            '将不带显式参数或切分调用数据集工厂，使用 CLI 默认种子采样最多 12 项并写入本地预览；种子可能传给工厂。不选择项目增强，工厂可能读取或修改其他状态。',
            '將不帶明確參數或切分呼叫資料集工廠，使用 CLI 預設種子取樣最多 12 項並寫入本機預覽；種子可能傳給工廠。不選擇專案增強，工廠可能讀取或修改其他狀態。')
            .. (capabilities['data.preview_random_seed_v1'] == true and tr('\nA new sampling seed will be generated; the report shows it for reuse.',
              '\n将生成新的采样种子；报告会显示该种子以便复用。', '\n將產生新的取樣種子；報告會顯示該種子以便重用。') or '')
            .. '\n' .. tr('Factory: ', '工厂：', '工廠：') .. factory
          run(state, tr('Preview dataset summary', '预览数据集摘要', '預覽資料集摘要'),
            { 'data', 'preview', '--dataset', factory, '--renderer', 'summary', '--no-split', '--samples', '12' }, nil, effect, true)
        end)
        return
      end
      vim.ui.input({ prompt = tr('Dataset parameters as JSON (recorded; no secrets): ',
        '数据集参数 JSON（会记录，请勿填写密钥）：', '資料集參數 JSON（會記錄，請勿填寫密鑰）：'), default = '{}' }, function(raw)
        if raw == nil or not current() then return end
        local ok, values = pcall(vim.json.decode, raw)
        if #raw > 65536 or not ok or type(values) ~= 'table' or not raw:match('^%s*{') then
          notify(tr('Enter a JSON object of at most 64 KiB.', '请输入不超过 64 KiB 的 JSON 对象。', '請輸入不超過 64 KiB 的 JSON 物件。'), vim.log.levels.WARN); return
        end
        local args, names = { 'data', 'preview', '--dataset', factory, '--renderer', 'summary' }, vim.tbl_keys(values)
        if #names > 64 then notify(tr('At most 64 parameters are supported.', '最多支持 64 个参数。', '最多支援 64 個參數。'), vim.log.levels.WARN); return end
        table.sort(names)
        for _, name in ipairs(names) do
          if not parameter_name_candidate(name) then
            notify(tr('Invalid parameter name.', '参数名无效。', '參數名稱無效。'), vim.log.levels.WARN); return
          end
          local serializable, value = pcall(vim.json.encode, values[name])
          if not serializable then notify(tr('Invalid parameter value.', '参数值无效。', '參數值無效。'), vim.log.levels.WARN); return end
          vim.list_extend(args, { '--param', name .. '=' .. value })
        end
        vim.ui.input({ prompt = tr('Split (empty for none): ', '数据切分（留空表示无切分）：', '資料切分（留空表示無切分）：'), default = '' }, function(split)
          if split == nil or not current() then return end
          vim.ui.input({ prompt = tr('Maximum preview samples (1–64): ', '最多预览样本数（1–64）：', '最多預覽樣本數（1–64）：'), default = '12' }, function(samples)
            if not samples or not current() then return end
            if not samples:match('^%d+$') or tonumber(samples) < 1 or tonumber(samples) > 64 then
              notify(tr('Choose an integer from 1 to 64.', '请输入 1 到 64 的整数。', '請輸入 1 到 64 的整數。'), vim.log.levels.WARN); return
            end
            vim.ui.input({ prompt = tr('Stream scan limit (optional, at least sample count): ',
              '流式数据扫描上限（选填，至少为样本数）：', '串流資料掃描上限（選填，至少為樣本數）：'), default = '' }, function(limit)
              if limit == nil or not current() then return end
              if limit ~= '' and (not limit:match('^%d+$') or tonumber(limit) < tonumber(samples) or tonumber(limit) > 100000) then
                notify(tr('Scan limit must be between the sample count and 100000.', '扫描上限须在样本数到 100000 之间。', '掃描上限須在樣本數到 100000 之間。'), vim.log.levels.WARN); return
              end
              vim.ui.input({ prompt = previous_seed
                and tr('Sampling seed (previous value shown; clear for CLI default): ', '采样种子（已填上次值；清空使用 CLI 默认值）：', '取樣種子（已填上次值；清空使用 CLI 預設值）：')
                or tr('Sampling seed (empty uses CLI default): ', '采样种子（留空使用 CLI 默认值）：', '取樣種子（留空使用 CLI 預設值）：'),
                default = previous_seed or '' }, function(seed)
              if seed == nil or not current() then return end
              if seed ~= '' then
                local normalized = seed:gsub('^0+', '')
                if normalized == '' then normalized = '0' end
                if not seed:match('^%d+$') or #normalized > 20
                    or (#normalized == 20 and normalized > '18446744073709551615') then
                  notify(tr('Enter an unsigned 64-bit integer.', '请输入无符号 64 位整数。', '請輸入無符號 64 位整數。'), vim.log.levels.WARN); return
                end
                vim.list_extend(args, { '--seed', normalized })
              end
              local augment_options = {
                tr('Automatic from split', '按切分自动选择', '依切分自動選擇'),
                tr('No project augmentation', '不使用项目增强', '不使用專案增強'),
                tr('Project training augmentation', '项目训练增强', '專案訓練增強'),
                tr('Project evaluation augmentation', '项目评估增强', '專案評估增強'),
              }
              vim.ui.select(augment_options, { prompt = tr('Choose preview augmentation', '选择预览增强', '選擇預覽增強') }, function(_, augment_choice)
              if not augment_choice or not current() then return end
              local augmentation = ({ [2] = 'none', [3] = 'train', [4] = 'eval' })[augment_choice]
              if augmentation then vim.list_extend(args, { '--augment-split', augmentation }) end
              if split == '' then args[#args + 1] = '--no-split'
              else vim.list_extend(args, { '--split', split }) end
              vim.list_extend(args, { '--samples', samples })
              if limit ~= '' then vim.list_extend(args, { '--scan-limit', limit }) end
              local effect = tr('Executes the dataset factory and writes local preview artifacts that may contain sensitive data. Sampling does not prove dataset coverage.',
                '将执行数据集工厂并写入可能含敏感数据的本地预览；采样不能证明数据集覆盖范围。',
                '將執行資料集工廠並寫入可能含敏感資料的本機預覽；取樣不能證明資料集涵蓋範圍。')
                .. '\n' .. tr('Factory: ', '工厂：', '工廠：') .. factory
                .. '\n' .. tr('Split: ', '切分：', '切分：') .. (split ~= '' and split or tr('none', '无', '無'))
                .. '\n' .. tr('Augmentation: ', '增强：', '增強：') .. augment_options[augment_choice]
                .. (not augmentation and tr(' (train split uses training; other splits use evaluation; no split uses none)',
                  '（train 使用训练增强，其他切分使用评估增强，无切分时不使用）',
                  '（train 使用訓練增強，其他切分使用評估增強，無切分時不使用）') or '')
                .. '\n' .. tr('Maximum preview samples: ', '最多预览样本数：', '最多預覽樣本數：') .. samples
                .. '\n' .. tr('Scan limit: ', '扫描上限：', '掃描上限：') .. (limit ~= '' and limit or tr('not specified', '未指定', '未指定'))
                .. '\n' .. tr('Sampling seed: ', '采样种子：', '取樣種子：') .. (seed ~= '' and seed or tr('CLI default; see report', 'CLI 默认值；见报告', 'CLI 預設值；見報告'))
                .. tr('; factory parameters may specify a different seed.', '；工厂参数可指定不同种子。', '；工廠參數可指定不同種子。')
                .. '\n' .. tr('Parameter names: ', '参数名：', '參數名稱：') .. (#names > 0 and table.concat(names, ', ') or tr('none', '无', '無'))
              local function start()
                if current() then run(state, tr('Preview dataset summary', '预览数据集摘要', '預覽資料集摘要'), args, nil, effect, true) end
              end
              if split ~= '' and not augmentation then start(); return end
              request(state, { '--describe-interface' }, function(report, err)
                if not current() then return end
                local capabilities = not err and report and report.status == 'success' and type(report.data) == 'table' and report.data.capabilities or nil
                if type(capabilities) ~= 'table'
                    or (split == '' and capabilities['data.preview_no_split_v1'] ~= true)
                    or (augmentation and capabilities['data.preview_augment_choice_v1'] ~= true) then
                  notify(tr('This CLI does not support the selected split or augmentation option. Update it or use a supported choice.',
                    '当前 CLI 不支持所选切分或增强选项；请更新或选择受支持的选项。', '目前 CLI 不支援所選切分或增強選項；請更新或選擇支援的選項。'), vim.log.levels.WARN)
                  return
                end
                start()
              end)
              end)
              end)
            end)
          end)
        end)
      end)
      end)
    end)
  end, 'Preview dataset summary')
  map('Y', function(preferred_input)
    vim.ui.select({ tr('Create editable CSV adapter', '创建可编辑 CSV 适配器', '建立可編輯 CSV 配接器'),
      tr('Configure existing CSV adapter', '配置已有 CSV 适配器', '設定既有 CSV 配接器') }, {
      prompt = tr('CSV input', 'CSV 输入', 'CSV 輸入'),
    }, function(_, choice)
      if choice == 1 then M._ui_actions.create_csv_adapter(state, preferred_input) elseif choice == 2 then M._ui_actions.configure_csv_adapter(state, preferred_input) end
    end)
  end, tr('Create or configure CSV input', '创建或配置 CSV 输入', '建立或設定 CSV 輸入'))
  map('P', function() choose_factory_parameters(state) end, 'Set factory parameters')
  map('e', function()
    if state.busy or state.closed then return end
    local project, epoch, current = state.opts.project, state.change_epoch or 0, state.opts.python
    local choices = {
      { label = tr('Use project environment / default', '使用项目环境 / 默认值', '使用專案環境 / 預設值'), value = false },
      { label = tr('Enter Python path or command', '输入解释器路径或命令', '輸入直譯器路徑或指令'), manual = true },
    }
    if vim.fn.executable('conda') == 1 then
      choices[#choices + 1] = {label = tr('Discover local conda environments', '发现本机 conda 环境', '探索本機 conda 環境'), scan_conda = true}
    end
    if current then choices[#choices + 1] = { label = tr('Save session Python to project', '将会话 Python 保存到项目', '將工作階段 Python 儲存到專案'), save_project = true } end
    if state.project_info and state.project_info.runtime_python then choices[#choices + 1] = { label = tr('Remove project Python choice', '移除项目 Python 选择', '移除專案 Python 選擇'), clear_project = true } end
    local seen = {}
    local function add(label, executable)
      if type(executable) ~= 'string' or executable == '' or seen[executable] or vim.fn.executable(executable) ~= 1 then return end
      seen[executable] = true
      choices[#choices + 1] = { label = label .. ': ' .. executable, value = executable }
    end
    local windows = vim.fn.has('win32') == 1
    local function environment_path(prefix, conda)
      if type(prefix) ~= 'string' or prefix == '' then return nil end
      -- Environment variables may be relative to the editor's cwd; turn
      -- those candidates into stable paths before the CLI runs in the project.
      prefix = vim.fn.fnamemodify(prefix, ':p')
      local executable = windows and (conda and '/python.exe' or '/Scripts/python.exe') or '/bin/python'
      return vim.fs.normalize(prefix .. executable)
    end
    local function path_executable(name)
      local found = vim.fn.exepath(name)
      return found ~= '' and vim.fn.fnamemodify(found, ':p') or nil
    end
    add(tr('Current session choice', '当前会话选择', '目前工作階段選擇'), current)
    add('VIRTUAL_ENV', environment_path(vim.env.VIRTUAL_ENV, false))
    add('CONDA_PREFIX', environment_path(vim.env.CONDA_PREFIX, true))
    local uv_project = vim.env.UV_PROJECT_ENVIRONMENT
    if type(uv_project) == 'string' and uv_project ~= '' then
      local absolute = uv_project:sub(1, 1) == '/' or uv_project:match('^%a:[/\\]') or uv_project:match('^[/\\][/\\]')
      add('UV_PROJECT_ENVIRONMENT', environment_path(absolute and uv_project or (project .. '/' .. uv_project), false))
    end
    add(tr('Project .venv candidate', '项目 .venv 候选', '專案 .venv 候選'), environment_path(project .. '/.venv', false))
    add('PATH python3', path_executable('python3'))
    add('PATH python', path_executable('python'))
    local function context_current()
      return not state.closed and not state.busy and state.opts.project == project
        and (state.change_epoch or 0) == epoch and state.opts.python == current
    end
    local function set_python(value)
      if not context_current() or value == state.opts.python then return end
      state.opts.python = value
      state.change_epoch = (state.change_epoch or 0) + 1
      state.journey = nil
      if state.last then
        state.last.context_changed = true; state.last.observed_context_changed = true
        if state.result_label ~= tr('model created; forward not run', '模型已创建；尚未运行前向', '模型已建立；尚未執行前向') then
          state.result_label = tr('context changed; recheck', '上下文已变化，请重验', '上下文已變更，請重驗')
        end
      end
      render(state)
    end
    vim.ui.select(choices, {
      prompt = tr('Python (candidates unverified)', 'Python（候选未验证）', 'Python（候選未驗證）'),
      format_item = function(item) return item.label end,
    }, function(item)
      if not item or state.closed or state.busy then return end
      if state.opts.project ~= project or (state.change_epoch or 0) ~= epoch or state.opts.python ~= current then
        notify(tr('Context changed; reopen Python selection.', '上下文已变化，请重新选择 Python。', '上下文已變更，請重新選擇 Python。'), vim.log.levels.WARN); return
      end
      if item.manual then
        choose_context('python', tr('Python path or command: ', 'Python 路径或命令：', 'Python 路徑或指令：'))
        return
      end
      if item.scan_conda then
        local conda = path_executable('conda')
        if not conda then return notify(tr('Conda is unavailable; choose a Python path manually.',
          '无法使用 conda，请手动选择 Python 路径。', '無法使用 conda，請手動選擇 Python 路徑。'), vim.log.levels.WARN) end
        local started = pcall(vim.system, {conda, 'info', '--envs', '--json'}, {text = true, timeout = 5000}, function(result)
          vim.schedule(function()
            if not context_current() then return end
            local raw = type(result.stdout) == 'string' and result.stdout or ''
            local ok, value = false, nil
            if result.code == 0 and #raw <= 1024 * 1024 then ok, value = pcall(vim.json.decode, raw) end
            local envs = ok and type(value) == 'table' and value.envs or nil
            if type(envs) ~= 'table' or not is_list(envs) then
              return notify(tr('Conda discovery failed; choose a Python path manually.',
                'conda 环境发现失败，请手动选择 Python 路径。', 'conda 環境探索失敗，請手動選擇 Python 路徑。'), vim.log.levels.WARN)
            end
            local candidates, paths, found = {}, {}, {}
            for _, prefix in ipairs(envs) do
              if type(prefix) == 'string' and #prefix <= 4096 and not prefix:find('[%c]')
                  and (prefix:sub(1, 1) == '/' or prefix:match('^%a:[/\\]') or prefix:match('^[/\\][/\\]')) then
                local executable = environment_path(prefix, true)
                if executable and not found[executable] and vim.fn.executable(executable) == 1 then
                  found[executable] = true; paths[#paths + 1] = executable; candidates[#candidates + 1] = executable
                end
              end
              if #paths >= 256 then break end
            end
            if #paths == 0 then return notify(tr('No usable conda Python candidates were found.',
              '未发现可用的 conda Python 候选。', '未發現可用的 conda Python 候選。'), vim.log.levels.INFO) end
            vim.ui.select(candidates, {prompt = tr('Conda Python candidates · not imported or verified',
              'conda Python 候选 · 尚未导入或验证', 'conda Python 候選 · 尚未匯入或驗證')}, function(_, index)
              if index and paths[index] and context_current() then set_python(paths[index]) end
            end)
          end)
        end)
        if not started then notify(tr('Could not start conda discovery; choose Python manually.',
          '无法启动 conda 发现，请手动选择 Python。', '無法啟動 conda 探索，請手動選擇 Python。'), vim.log.levels.WARN) end
        return
      end
      if item.save_project or item.clear_project then M._ui_actions.save_project_python(state, item.clear_project == true); return end
      local value = item.value or nil
      set_python(value)
    end)
  end, 'Choose Python')
  map('E', function() M._ui_actions.environment_menu(state) end, 'Inspect environment')
  map('K', function() M._ui_actions.choose_runtime_paths(state) end, 'Configure runtime paths')
  map('i', function() run(state, tr('Inspect model', '检查模型', '檢查模型'), { 'model', 'inspect' }) end, tr('Inspect model', '检查模型', '檢查模型'))
  map('p', function() run(state, tr('Run forward pass', '执行前向', '執行前向'), { 'model', 'probe' }, nil, nil, false, nil, nil, true) end, tr('Run forward pass', '执行前向', '執行前向'))
  map('1', function() M._ui_actions.capture_canvas_forward(state) end, tr('Capture input and run forward', '捕获输入并运行前向', '擷取輸入並執行前向'))
  map('2', function() M._ui_actions.replay_canvas_forward(state) end, tr('Replay captured input', '重放已捕获输入', '重播已擷取輸入'))
  map('3', function() M._ui_actions.discard_canvas_forward(state) end, tr('Discard captured input', '删除输入快照', '刪除輸入快照'))
  map('X', function()
    if state.closed or state.busy then return end
    local project, epoch = state.opts.project, state.change_epoch or 0
    local function current()
      return not state.closed and not state.busy and state.opts.project == project and (state.change_epoch or 0) == epoch
    end
    vim.ui.select({ tr('Run a contract on the current model', '用契约检查当前模型', '用契約檢查目前模型'),
      tr('Open an existing contract', '打开已有契约', '開啟既有契約'),
      tr('Create an empty contract draft', '创建空白契约草稿', '建立空白契約草稿'),
      tr('Draft from the current forward observation', '从当前前向观察创建草稿', '從目前前向觀察建立草稿'),
      tr('Draft from the selected module', '从所选模块创建草稿', '從所選模組建立草稿') }, {
      prompt = tr('Model port contract', '模型端口契约', '模型連接埠契約'),
    }, function(_, choice)
      if not choice or not current() then return end
      local selected_module = choice == 5 and state.last_selection or nil
      if choice == 5 and (type(selected_module) ~= 'string' or selected_module == '') then
        notify(tr('Choose a module from v first, then reopen this action.', '请先用 v 选择模块，再重新打开此操作。', '請先用 v 選擇模組，再重新開啟此操作。'), vim.log.levels.INFO); return
      end
      vim.ui.input({ prompt = tr('Contract JSON file (relative to project or absolute): ',
        '契约 JSON 文件（项目相对路径或绝对路径）：', '契約 JSON 檔案（專案相對路徑或絕對路徑）：'),
        default = state.last_contract_path or (project .. '/'), completion = 'file' }, function(value)
        if not value or value == '' or not current() then return end
        local absolute = value:sub(1, 1) == '/' or value:match('^%a:[/\\]') or value:match('^[/\\][/\\]')
        local path = vim.fs.normalize(absolute and value or (project .. '/' .. value))
        if choice == 2 then
          local stat = vim.uv.fs_stat(path)
          if not stat or stat.type ~= 'file' then
            notify(tr('Choose an existing contract file, or create a draft.', '请选择已有契约文件，或创建草稿。', '請選擇既有契約檔案，或建立草稿。'), vim.log.levels.WARN); return
          end
          state.last_contract_path = path
          focus_source(state, path)
          return
        end
        if choice == 3 or choice == 4 or choice == 5 then
          if vim.uv.fs_lstat(path) or vim.fn.bufnr(path) ~= -1 then
            notify(tr('That file or buffer already exists; choose another path.', '该文件或 buffer 已存在，请选择其他路径。', '該檔案或 buffer 已存在，請選擇其他路徑。'), vim.log.levels.WARN); return
          end
          local draft_lines = { '{', '  "version": 1,', '  "inputs": {},', '  "outputs": {},',
            '  "modules": {},', '  "symbols": {},', '  "static": false', '}' }
          local observation = state.last
          if choice == 4 or choice == 5 then
            local report = observation and observation.report
            local data = report and report.data
            if not observation or observation.context_changed or observation.historical_observation or not report
                or report.operation ~= 'probe' or report.status ~= 'success' or type(data) ~= 'table'
                or data.forward_execution ~= 'executed' or (type(data.evidence_cache) == 'table' and data.evidence_cache.status == 'reused') then
              notify(tr('Run a fresh forward pass before drafting from an observation.', '请先运行新的前向，再从观察创建草稿。', '請先執行新的前向，再從觀察建立草稿。'), vim.log.levels.WARN); return
            end
            local groups, omitted = { inputs = {}, outputs = {} }, false
            local function visit(node, port, group, depth)
              if depth > 6 or #port > 512 or #groups.inputs + #groups.outputs >= 128 then omitted = true; return end
              if type(node) ~= 'table' then omitted = true; return end
              if node.kind == 'tensor' then
                if type(node.dtype) ~= 'string' or type(node.shape) ~= 'table' or not is_list(node.shape) or #node.shape > 64 then omitted = true; return end
                for _, dim in ipairs(node.shape) do
                  if type(dim) ~= 'number' or dim < 0 or dim ~= math.floor(dim) then omitted = true; return end
                end
                local ok_path, encoded_path = pcall(vim.json.encode, port)
                local ok_spec, encoded_spec = pcall(vim.json.encode, { dtype = node.dtype, shape = node.shape })
                if not ok_path or not ok_spec or #encoded_path > 2048 or #encoded_spec > 4096 then omitted = true; return end
                groups[group][#groups[group] + 1] = '    ' .. encoded_path .. ': ' .. encoded_spec
              elseif node.kind == 'dict' and type(node.items) == 'table' and node.observed_keys_all_strings == true then
                local keys = vim.tbl_keys(node.items)
                table.sort(keys)
                if node.items_truncated == true then omitted = true end
                for _, key in ipairs(keys) do
                  if type(key) ~= 'string' or #key > 128 or (key == '<truncated>' and node.items_truncated == true) then
                    omitted = true
                  else
                    local suffix = key ~= '' and not key:find('[%.%[%]%c]') and ('.' .. key) or ('[' .. vim.json.encode(key) .. ']')
                    visit(node.items[key], port .. suffix, group, depth + 1)
                  end
                end
              elseif (node.kind == 'list' or node.kind == 'tuple') and type(node.items) == 'table' and is_list(node.items) then
                if type(node.truncated) == 'number' and node.truncated > 0 then omitted = true end
                for index, item in ipairs(node.items) do visit(item, port .. '[' .. (index - 1) .. ']', group, depth + 1) end
              else omitted = true end
            end
            local observed_inputs, observed_outputs = data.inputs, data.outputs
            local matching_calls = 0
            if choice == 5 then
              if data.trace_truncated ~= false then omitted = true end
              if state.last_selection ~= selected_module or type(data.calls) ~= 'table' or not is_list(data.calls) then
                notify(tr('The selected module or observation changed; choose it again.', '所选模块或观察已变化，请重新选择。', '所選模組或觀察已變更，請重新選擇。'), vim.log.levels.WARN); return
              end
              for _, call in ipairs(data.calls) do
                if type(call) == 'table' and type(call.paths) == 'table' and vim.tbl_contains(call.paths, selected_module) then
                  matching_calls = matching_calls + 1
                  if matching_calls == 1 then observed_inputs, observed_outputs = call.inputs, call.outputs end
                end
              end
              if matching_calls == 0 then
                notify(tr('No call for this module was recorded; run forward or select another module.', '没有记录此模块的调用；请重新前向或选择其他模块。', '沒有記錄此模組的呼叫；請重新前向或選擇其他模組。'), vim.log.levels.WARN); return
              end
            end
            visit(observed_inputs, 'inputs', 'inputs', 0)
            visit(observed_outputs, 'outputs', 'outputs', 0)
            if #groups.inputs + #groups.outputs == 0 then
              notify(tr('No unambiguous tensor ports were recorded; create an empty draft instead.',
                '没有记录到无歧义的 Tensor 端口，请改用空白草稿。', '沒有記錄到無歧義的 Tensor 連接埠，請改用空白草稿。'), vim.log.levels.WARN); return
            end
            local encoded_module
            if choice == 5 then
              local ok, encoded = pcall(vim.json.encode, selected_module)
              if not ok or #encoded > 4096 then notify(tr('The module path cannot be encoded.', '无法编码模块路径。', '無法編碼模組路徑。'), vim.log.levels.WARN); return end
              encoded_module = encoded
            end
            draft_lines = choice == 5 and { '{', '  "version": 1,', '  "inputs": {},', '  "outputs": {},', '  "modules": {', '    ' .. encoded_module .. ': {', '      "inputs": {' }
              or { '{', '  "version": 1,', '  "inputs": {' }
            for index, line in ipairs(groups.inputs) do draft_lines[#draft_lines + 1] = (choice == 5 and '    ' or '') .. line .. (index < #groups.inputs and ',' or '') end
            vim.list_extend(draft_lines, choice == 5 and { '      },', '      "outputs": {' } or { '  },', '  "outputs": {' })
            for index, line in ipairs(groups.outputs) do draft_lines[#draft_lines + 1] = (choice == 5 and '    ' or '') .. line .. (index < #groups.outputs and ',' or '') end
            vim.list_extend(draft_lines, choice == 5 and { '      }', '    }', '  },', '  "symbols": {},', '  "static": false', '}' }
              or { '  },', '  "modules": {},', '  "symbols": {},', '  "static": false', '}' })
            if omitted then notify(tr('Some values or ports were omitted; inspect the full observation.', '部分值或端口已省略，请检查完整观察。', '部分值或連接埠已省略，請檢查完整觀察。'), vim.log.levels.WARN) end
            if choice == 5 then notify(tr('Draft uses the first recorded call (recorded calls: ', '草稿使用第一次记录的调用（已记录调用数：', '草稿使用第一次記錄的呼叫（已記錄呼叫數：')
              .. matching_calls .. tr('); the contract checks every observed call. Review dynamic shapes.', '）；契约会检查每次观察到的调用，请审核动态形状。', '）；契約會檢查每次觀察到的呼叫，請檢視動態形狀。'), vim.log.levels.WARN) end
          end
          if not focus_source(state, path) then return end
          local buf = vim.api.nvim_get_current_buf()
          if not current() or vim.fs.normalize(vim.api.nvim_buf_get_name(buf)) ~= path
              or ((choice == 4 or choice == 5) and (state.last ~= observation or observation.context_changed))
              or (choice == 5 and state.last_selection ~= selected_module)
              or vim.uv.fs_lstat(path) or vim.bo[buf].modified or vim.api.nvim_buf_line_count(buf) ~= 1
              or vim.api.nvim_buf_get_lines(buf, 0, 1, false)[1] ~= '' then
            notify(tr('The new buffer changed while opening; no draft was inserted.', '新 buffer 在打开时已变化，未插入草稿。', '新 buffer 在開啟時已變更，未插入草稿。'), vim.log.levels.WARN); return
          end
          vim.api.nvim_buf_set_lines(buf, 0, -1, false, draft_lines)
          vim.bo[buf].filetype = 'json'
          state.last_contract_path = path
          notify((choice == 4 or choice == 5) and tr('Draft uses shapes and dtypes from one forward, including fixed batch dimensions. Review and generalize it, then :write; no file has been created yet.',
            '草稿中的形状和 dtype 来自一次前向，包含固定批次维度；请审核并泛化后用 :write 保存，文件尚未创建。',
            '草稿中的形狀和 dtype 來自一次前向，包含固定批次維度；請檢視並泛化後用 :write 儲存，檔案尚未建立。')
            or tr('Fill in port rules and :write to save. This draft checks the real forward; set static to true to request FX/Meta inference.',
            '请填写端口规则并用 :write 保存。草稿默认检查真实前向；可将 static 设为 true 请求 FX/Meta 推演。',
            '請填寫連接埠規則並用 :write 儲存。草稿預設檢查真實前向；可將 static 設為 true 要求 FX/Meta 推演。'), vim.log.levels.INFO)
          return
        end
        local resolved = vim.uv.fs_realpath(path)
        local function read_contract()
          local current_path = vim.uv.fs_realpath(path)
          local info = current_path and vim.uv.fs_stat(current_path)
          if not resolved or current_path ~= resolved or not info or info.type ~= 'file' or info.size > 1024 * 1024 then return nil end
          for _, buf in ipairs(vim.api.nvim_list_bufs()) do
            local name = vim.api.nvim_buf_get_name(buf)
            if vim.api.nvim_buf_is_loaded(buf) and name ~= '' and vim.uv.fs_realpath(name) == resolved and vim.bo[buf].modified then return nil end
          end
          local file = io.open(resolved, 'rb')
          if not file then return nil end
          local raw = file:read(1024 * 1024 + 1) or ''
          file:close()
          if #raw > 1024 * 1024 then return nil end
          local ok, data = pcall(vim.json.decode, raw)
          if not ok or type(data) ~= 'table' or not raw:match('^%s*{') then return nil end
          return vim.fn.sha256(raw)
        end
        local digest = read_contract()
        if not digest then
          notify(tr('Contract must be a saved, readable JSON object of at most 1 MiB; reconcile any modified buffer.',
            '契约须为已保存、可读取且不超过 1 MiB 的 JSON 对象；请先处理未保存的 buffer。',
            '契約須為已儲存、可讀取且不超過 1 MiB 的 JSON 物件；請先處理未儲存的 buffer。'), vim.log.levels.WARN); return
        end
        state.last_contract_path = path
        state.busy = tr('Checking contract support', '检查契约能力', '檢查契約能力'); render(state)
        request(state, { '--describe-interface' }, function(interface, failure)
          state.busy = nil; render(state)
          if not current() then return end
          local caps = interface and interface.operation == 'interface' and interface.status == 'success'
            and type(interface.data) == 'table' and interface.data.capabilities
          if failure or type(caps) ~= 'table' or caps['model.contract_identity_v1'] ~= true
              or caps['model.contract_preload_v1'] ~= true then
            notify(tr('This CLI cannot pin contract contents; select a compatible CLI.', '此 CLI 无法固定契约内容，请选择兼容版本。', '此 CLI 無法固定契約內容，請選擇相容版本。'), vim.log.levels.WARN); return
          end
          run(state, tr('Run model contract', '运行模型契约', '執行模型契約'),
            { 'model', 'probe', '--contract', resolved, '--if-contract-sha256', digest }, nil,
            tr('Contract file: ', '契约文件：', '契約檔案：') .. resolved
              .. tr('\nThe worker verifies and loads these bytes before model and input factories. Python startup hooks may already have run.',
                '\nworker 在模型和输入工厂前核对并加载这些内容；Python 启动钩子可能已执行。', '\nworker 在模型和輸入工廠前核對並載入這些內容；Python 啟動掛鉤可能已執行。'),
            false, function()
              if read_contract() ~= digest then
                notify(tr('Contract changed or is unavailable; review it and retry.', '契约已变化或不可用，请检查后重试。', '契約已變更或無法使用，請檢查後重試。'), vim.log.levels.WARN)
                return false
              end
              return true
            end, nil, true)
        end)
      end)
    end)
  end, tr('Open or run a model port contract', '打开或运行模型端口契约', '開啟或執行模型連接埠契約'))
  map('h', function()
    local saved = state.saved_forward
    if state.closed or state.busy or not saved or saved.project ~= state.opts.project
        or saved.epoch ~= (state.change_epoch or 0) or not project_config_current(state) then
      notify(tr('No earlier forward observation is available for this context.',
        '当前上下文没有可查看的先前前向观察。', '目前上下文沒有可查看的先前前向觀察。'), vim.log.levels.INFO); return
    end
    if #dirty_buffers(state.opts.project) > 0 or #reloads_pending(state) > 0
        or #stale_python_buffers(state.opts.project) > 0 then
      notify(tr('Reconcile project buffers before reopening an observation.',
        '重新查看观察前请先处理项目 buffer。', '重新查看觀察前請先處理專案 buffer。'), vim.log.levels.WARN); return
    end
    state.last = { report = saved.report, stderr = saved.stderr, historical_observation = true,
      scope = tr('Earlier observation; no new forward was run. Source, data and external dependencies may have changed.',
        '先前观察；没有执行新前向。源码、数据和外部依赖可能已变化。',
        '先前觀察；沒有執行新前向。原始碼、資料和外部依賴可能已變更。') }
    state.result_label = tr('earlier forward observation', '先前前向观察', '先前前向觀察')
    render(state)
    show_report(state)
  end, tr('Reopen last forward observation', '重新查看上次前向观察', '重新查看上次前向觀察'))
  map('V', function() M._ui_actions.recheck_after_edit(state) end, 'Recheck after source change')
  map('L', function() probe_local(state) end, 'Replay selected layer')
  map('O', function() M._ui_actions.compare_observations(state) end, 'Compare forward observations')
  map('Z', function() M._ui_actions.browse_variants(state) end, tr('Browse saved variants', '查看已保存变体', '查看已儲存變體'))
  map('l', function() run(state, tr('Browse layers', '浏览层', '瀏覽層'), { 'layer', 'list' }) end, tr('Browse layers', '浏览层', '瀏覽層'))
  map('v', function() M._ui_actions.browse_modules(state) end, 'Browse reported modules')
  map('G', function() M._ui_actions.browse_tensor_links(state) end, 'Browse observed tensor links')
  map('g', function() M._ui_actions.open_observed_source(state) end, 'Open observed implementation')
  map('w', function() preview_layer(state) end, 'Preview layer change')
  map('W', function() compose_layer_transaction(state) end, 'Compose layer transaction')
  map('A', function() assemble(state) end, 'Assemble components and routes')
  map('t', function() mark_observed_port(state) end, 'Mark an observed input or output')
  map('M', function(repair)
    local report = state.last and state.last.report
    local imported = state.last and not state.last.context_changed and report and report.operation == 'semantic_supervise'
      and report.status == 'success' and type(report.data) == 'table' and report.data.committed == true
      and type(report.data.imported) == 'number' and report.data.imported > 0
    M._ui_actions.browse_marks(state, repair or imported)
  end, 'Browse semantic marks')
  map('4', function() sessions.transfer_supervision(state, false) end, 'Export supervision')
  map('5', function() sessions.transfer_supervision(state, true) end, 'Import supervision')
  map('6', function(preferred) sessions.port_supervision(state, preferred) end, 'Inspect port supervision')
  map('9', function() sessions.sync_scaffold_declaration(state, 'data') end, 'Save project input in declaration')
  map('0', function() sessions.sync_scaffold_declaration(state, 'training') end, 'Save training settings in declaration')
  map('B', function(preferred) M._ui_actions.rebind_mark(state, preferred) end, 'Rebind semantic mark')
  map('d', function(use_selected) add_rule(state, use_selected) end, 'Add supervision rule')
  map('D', function() M._ui_actions.browse_rules(state) end, 'Browse supervision rules')
  map('u', function()
    local project, epoch, cli, device = state.opts.project, state.change_epoch or 0, state.opts.cli, state.probe_device
    local function current()
      return not state.closed and not state.busy and state.opts.project == project and (state.change_epoch or 0) == epoch
        and state.opts.cli == cli and state.probe_device == device and project_config_current(state)
    end
    local function start()
    if not current() then return end
    run(state, tr('Preview supervision', '预览监督', '預覽監督'), { 'model', 'supervise', 'preview' }, function(report, failure, _, stale)
      if not failure and not stale and report and report.operation == 'semantic_supervise'
          and report.status == 'success' and type(report.data) == 'table' and type(report.data.results) == 'table' then
        state.supervision_progress = { report = state.last, stage = 'preview' }
        render(state)
      end
    end)
    end
    if not device then start(); return end
    request(state, { '--describe-interface' }, function(report, err)
      if not current() then return end
      local caps = not err and report and report.status == 'success' and type(report.data) == 'table' and report.data.capabilities or nil
      if type(caps) ~= 'table' or caps['supervision.preview_device_v1'] ~= true then
        notify(tr('This CLI cannot use the selected device for supervision preview. Update it or clear the forward device.',
          '当前 CLI 无法在监督预览中使用所选设备；请更新或清除前向设备。', '目前 CLI 無法在監督預覽中使用所選裝置；請更新或清除前向裝置。'), vim.log.levels.WARN); return
      end
      start()
    end)
  end, 'Preview supervision')
  map('y', function() prepare_trial(state) end, 'Prepare a training trial')
  map('T', function() M._ui_actions.prepare_training(state) end, 'Prepare background training')
  map('R', function() M._ui_actions.browse_runs(state) end, 'Browse runs')
  map('H', function() M._ui_actions.resolve_pending(state) end, 'Resolve unconfirmed training start')
  map('r', function() show_report(state) end, 'Show last report')
  map('k', function()
    local error = state.project_error
    if error then
      if type(error) == 'table' and type(error.report) == 'table' then
        state.last = { report = error.report, stderr = error.stderr }
      elseif type(error) == 'table' then
        state.last = { transport_error = error, stderr = error.stderr }
      else
        state.last = { project_error = error }
      end
      show_report(state)
    end
    refresh_project(state)
  end, 'Check project')
  map('I', function() M._ui_actions.capability_overview(state) end, 'Capability and evidence overview')
  map('c', function()
    if state.busy then notify('Wait for the operation to finish before switching projects.', vim.log.levels.WARN); return end
    local project, epoch = state.opts.project, state.change_epoch or 0
    local function current()
      return not state.closed and not state.busy and state.opts.project == project and (state.change_epoch or 0) == epoch
    end
    vim.ui.select({ tr('Choose a project directory', '选择项目目录', '選擇專案目錄'),
      tr('Continue from open or recent files', '从已打开或最近文件继续', '從已開啟或最近檔案繼續') }, {
        prompt = tr('Open a project', '打开项目', '開啟專案'),
      }, function(_, choice)
      if not choice or not current() then return end
      if choice == 1 then
        vim.ui.input({ prompt = tr('Project directory: ', '项目目录：', '專案目錄：'), default = project, completion = 'dir' }, function(value)
          if value and value ~= '' and current() then require('model_maven').open({ project = value }) end
        end)
        return
      end
      local files, seen_files = {}, {}
      local function add_file(path)
        if type(path) ~= 'string' or path == '' or path:match('^[%a][%w+.-]*://') or seen_files[path] then return end
        seen_files[path] = true
        files[#files + 1] = path
      end
      for _, buf in ipairs(vim.api.nvim_list_bufs()) do
        if vim.api.nvim_buf_is_loaded(buf) and vim.bo[buf].buftype == '' then add_file(vim.api.nvim_buf_get_name(buf)) end
      end
      for index, path in ipairs(vim.v.oldfiles or {}) do
        if index > 256 or #files >= 256 then break end
        add_file(path)
      end
      local candidates, seen_roots, checked = {}, {}, {}
      for _, file in ipairs(files) do
        local resolved = vim.uv.fs_realpath(file)
        local directory = resolved and vim.fs.dirname(vim.fs.normalize(resolved)) or nil
        while directory and not checked[directory] do
          checked[directory] = true
          local config = vim.uv.fs_lstat(directory .. '/.model-maven/project.json')
          if config and config.type == 'file' then
            if not seen_roots[directory] then
              candidates[#candidates + 1], seen_roots[directory] = directory, true
            end
            break
          end
          local parent = vim.fs.dirname(directory)
          if not parent or parent == directory then break end
          directory = parent
        end
        if #candidates >= 50 then break end
      end
      if #candidates == 0 then
        notify(tr('No configured projects were found in open or recent files. Choose a directory instead.',
          '已打开或最近文件中没有找到已配置项目；可以选择项目目录。',
          '已開啟或最近檔案中沒有找到已設定專案；可以選擇專案目錄。'), vim.log.levels.INFO); return
      end
      vim.ui.select(candidates, { prompt = tr('Choose a configured project; no project code has run',
        '选择已配置项目；尚未执行项目代码', '選擇已設定專案；尚未執行專案程式碼') }, function(selected)
        if selected and current() then require('model_maven').open({ project = selected }) end
      end)
    end)
  end, 'Open project')
  map('s', function()
    locale.choose(function()
      for _, session in pairs(sessions) do
        -- This table also owns shared helper functions, not just sessions.
        if type(session) == 'table' and not session.closed and type(session.panel) == 'number'
            and vim.api.nvim_buf_is_valid(session.panel) then
          if session.refresh_keymap_descriptions then session.refresh_keymap_descriptions() else render(session) end
          local preview = require('model_maven.model_preview')
          -- Live preview propagates locale through its snapshot, preserving
          -- the renderer, camera and window geometry.
          preview.refresh(session)
        end
      end
    end)
  end, 'Language')
  map('x', function() state.expanded = not state.expanded; render(state) end, 'Toggle all actions')
  map('C', function()
    if not state.busy or not state.cancellable or not state.process or state.cancel_requested then
      notify(tr('This operation cannot be cancelled here.', '此操作不能在此处取消。', '此操作不能在此處取消。'), vim.log.levels.INFO); return
    end
    local ok, result, failure = pcall(state.process.kill, state.process, 2)
    if not ok or result == false or (result == nil and failure ~= nil) then
      notify(tr('Could not request cancellation: ', '无法请求取消：', '無法要求取消：') .. tostring(failure or result), vim.log.levels.WARN)
      return
    end
    state.cancel_requested = true
    render(state)
  end, 'Request cancellation')
  map('?', function() M._ui_actions.show_help() end, 'Help')
  local function close_workspace()
    if state.panel_win and vim.api.nvim_win_is_valid(state.panel_win)
        and vim.api.nvim_get_current_win() ~= state.panel_win then
      notify(tr('This panel is also open in another window. Focus the workspace window before closing it.',
        '面板也显示在其他窗口；请先聚焦工作区窗口再关闭。',
        '面板也顯示在其他視窗；請先聚焦工作區視窗再關閉。'), vim.log.levels.WARN)
      return
    end
    if state.panel_win and vim.api.nvim_win_is_valid(state.panel_win)
        and vim.api.nvim_win_get_buf(state.panel_win) ~= panel then
      notify(tr('The recorded panel window now shows another buffer; it was left open. Return the panel to that window before closing.',
        '记录的面板窗口现在显示其他 buffer，已保留该窗口；请先将面板放回该窗口再关闭。',
        '記錄的面板視窗現在顯示其他 buffer，已保留該視窗；請先將面板放回該視窗再關閉。'), vim.log.levels.WARN)
      return
    end
    if state.single_panel and state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
      local replacement = state.code_buf
      if not replacement or not vim.api.nvim_buf_is_valid(replacement) then replacement = state.initial_buf end
      if not replacement or not vim.api.nvim_buf_is_valid(replacement) then replacement = vim.api.nvim_create_buf(true, false) end
      local restored = pcall(vim.api.nvim_win_set_buf, state.panel_win, replacement)
      if restored then
        if state.code_wrap ~= nil then vim.wo[state.panel_win].wrap = state.code_wrap end
        if state.code_view then pcall(vim.api.nvim_win_call, state.panel_win, function() vim.fn.winrestview(state.code_view) end) end
        pcall(vim.api.nvim_buf_delete, panel, { force = true })
      else notify(tr('Could not restore the source buffer.', '无法恢复源码 buffer。', '無法還原原始碼 buffer。'), vim.log.levels.WARN) end
      return
    end
    if state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
      local closed = pcall(vim.api.nvim_win_close, state.panel_win, true)
      if not closed and vim.api.nvim_win_is_valid(state.panel_win) then
        -- The user may have closed every other window. Keep Neovim open and
        -- restore its original buffer (including unsaved edits) when possible.
        local replacement = state.initial_buf
        if not replacement or replacement == state.panel or not vim.api.nvim_buf_is_valid(replacement) then
          replacement = vim.api.nvim_create_buf(true, false)
        end
        local restored = pcall(vim.api.nvim_win_set_buf, state.panel_win, replacement)
        if not restored then
          notify(tr('Could not close the panel; restore another buffer and try again.',
            '无法关闭面板；请先切换到其他 buffer 后重试。',
            '無法關閉面板；請先切換到其他 buffer 後重試。'), vim.log.levels.WARN)
        end
      end
    end
  end
  map('q', function()
    if state.busy then
      notify(tr('The CLI operation is still running. Its outcome is not yet known; keep the panel open.', 'CLI 操作仍在运行，结果尚未知；请保持面板打开。', 'CLI 操作仍在執行，結果尚未知；請保持面板開啟。'), vim.log.levels.WARN)
      return
    end
    local draft, layer_draft = state.assembly_draft, state.layer_draft
    if not has_assembly_changes(draft) and not has_layer_draft(layer_draft) then close_workspace(); return end
    local reviewed_spec = draft and vim.deepcopy(draft.spec) or nil
    local reviewed_layers = layer_draft and vim.deepcopy({ layer_draft.operations, layer_draft.structures }) or nil
    vim.ui.select({ tr('Keep workspace open', '保持工作区打开', '保持工作區開啟'), tr('Discard drafts and close', '放弃草稿并关闭', '放棄草稿並關閉') }, {
      prompt = tr('Assembly and Layer drafts exist only in this workspace session.', '装配和 Layer 草稿仅保存在本次工作区会话中。', '裝配和 Layer 草稿僅保存在本次工作區工作階段中。'),
    }, function(_, choice)
      if choice ~= 2 or state.closed or state.busy or state.assembly_draft ~= draft or state.layer_draft ~= layer_draft then return end
      if (draft and not vim.deep_equal(draft.spec, reviewed_spec)) or (layer_draft
          and not vim.deep_equal({ layer_draft.operations, layer_draft.structures }, reviewed_layers)) then
        notify(tr('A draft changed; review it before closing.', '草稿已变化，请查看后重新关闭。', '草稿已變更，請檢視後重新關閉。'), vim.log.levels.WARN)
        return
      end
      state.assembly_draft_discard_confirmed, state.layer_draft_discard_confirmed = true, true
      close_workspace()
      if not state.closed then state.assembly_draft_discard_confirmed, state.layer_draft_discard_confirmed = nil, nil end
    end)
  end, 'Close workspace')
  map('f', function() M._ui_actions.find_action(state, actions) end, 'Find action')
  -- Reuse the translated action list for Neovim's keymap descriptions (and
  -- plugins such as which-key). Do not replace mappings the user changed.
  state.refresh_keymap_descriptions = function()
    if state.closed or not vim.api.nvim_buf_is_valid(panel) then return end
    local view
    if state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
      local ok, saved = pcall(vim.api.nvim_win_call, state.panel_win, vim.fn.winsaveview)
      if ok then view = saved end
    end
    local expanded = state.expanded
    state.expanded = true
    render(state)
    local lines = vim.api.nvim_buf_get_lines(panel, 0, -1, false)
    state.expanded = expanded
    render(state)
    if view and state.panel_win and vim.api.nvim_win_is_valid(state.panel_win) then
      pcall(vim.api.nvim_win_call, state.panel_win, function() vim.fn.winrestview(view) end)
    end
    local descriptions = {
      x = tr('Toggle all actions', '展开或收起全部操作', '展開或收合全部操作'),
      C = tr('Request cancellation', '请求取消', '要求取消'),
    }
    for _, line in ipairs(lines) do
      local key, label = line:match('^%[([^%]]+)%]%s*(.+)$')
      if key and #key == 1 and actions[key] and not label:match('%[[^%]]+%]') then
        descriptions[key] = label
      end
    end
    for _, existing in ipairs(vim.api.nvim_buf_get_keymap(panel, 'n')) do
      local key = existing.lhs
      if descriptions[key] and existing.callback == actions[key] and existing.desc == owned_descriptions[key]
          and existing.silent == 1 and existing.nowait == 1 and existing.noremap == 1 and existing.expr == 0 then
        vim.keymap.set('n', key, actions[key], { buffer = panel, silent = true, nowait = true, desc = descriptions[key] })
        owned_descriptions[key] = descriptions[key]
      end
    end
  end
  state.refresh_keymap_descriptions()
  require('model_maven.model_preview').open(state)
  refresh_project(state)
end

return M
